const Fold = union(enum) {
    /// Nothing to compute with. The ordinary case: a call, a name reaching
    /// something that can be assigned again, anything built out of one.
    not_constant,
    /// An expression with no value in its type: one already refused, or one
    /// whose operands left the type they were written in.
    absent,
    /// Numeric arithmetic keeps its integer value separately from truth and text.
    value: i128,
    string: []const u8,
    truth: bool,
    aggregate: constfold.ConstantId,

    /// What the routine that folds a constant expression wherever one is read
    /// answered, preserving the value's domain.
    fn of(v: constfold.Value) Fold {
        return switch (v) {
            .not_constant => .not_constant,
            .absent => .absent,
            .integer => |n| .{ .value = n },
            .truth => |b| .{ .truth = b },
            .string => |literal| .{ .string = literal },
            .aggregate => |id| .{ .aggregate = id },
        };
    }

    fn isConstant(self: Fold) bool {
        return switch (self) {
            .not_constant => false,
            else => true,
        };
    }

    /// The value, for the arithmetic that needs one. A constant expression
    /// with none folds nothing further: there is no number to compute with.
    fn valueOf(self: Fold) ?i128 {
        return switch (self) {
            .value => |v| v,
            else => null,
        };
    }
};

/// Checks a tree against its declared types.
///
/// A type flows *inward* from an annotation or the return type, and *outward*
/// from an expression that determines its own. Constant expressions are folded
/// during checking, which is what lets a range or overflow failure be reported
/// where it is written rather than at run time.
///
/// Every expression ends with exactly one type, and it is `.poison` if and only
/// if the expression or something it contains was reported.
///
/// Checks a tree that is its own module. For a caller holding a tree and no
/// directory structure -- a test, the generator, the fuzzer.
pub fn typecheckTree(
    gpa: std.mem.Allocator,
    resolved: *const resolve_mod.ResolvedTree,
    sink: *Sink,
) !Typing {
    var typing = try typecheck(gpa, &resolved.expanded, &resolved.resolution, sink);
    errdefer typing.deinit(gpa);
    try resolved.expanded.collapseGeneratedDiagnostics(sink);
    return typing;
}

/// Checked library answers and the continuation state not needed by lowering.
/// The expanded program and its resolution must outlive this snapshot.
pub const LibraryPrefix = struct {
    arena: std.heap.ArenaAllocator,
    typing: Typing,
    seed: CheckSeed,

    pub fn deinit(self: *LibraryPrefix) void {
        self.arena.deinit();
        self.* = undefined;
    }
};

const RetainedTyping = struct { typing: Typing, seed: CheckSeed };

const CheckSeed = struct {
    parameters: []const []const TypeId,
    declared_types: []const TypeId,
    expression_owners: []const DeclId,
    binding_owners: []const DeclId,
    declarations: []const bool,
    call_impls: []const types_mod.CallImpl,
};

pub fn typecheckLibraryPrefix(
    backing: std.mem.Allocator,
    program: *const ExpandedProgram,
    resolution: *const Resolution,
    sink: *Sink,
) !LibraryPrefix {
    if (sink.hasErrors() or program.modules.len == 0) return error.InvalidLibraryPrefix;
    for (program.modules) |module| if (!module.library) return error.InvalidLibraryPrefix;
    var arena = std.heap.ArenaAllocator.init(backing);
    errdefer arena.deinit();
    var seed: CheckSeed = undefined;
    const typing = try typecheckInternal(arena.allocator(), program, resolution, sink, &seed, null, false);
    if (sink.hasErrors()) return error.InvalidLibraryPrefix;
    return .{ .arena = arena, .typing = typing, .seed = seed };
}

pub fn typecheck(
    gpa: std.mem.Allocator,
    program: *const ExpandedProgram,
    resolution: *const Resolution,
    sink: *Sink,
) !Typing {
    return typecheckInternal(gpa, program, resolution, sink, null, null, false);
}

/// Prepare all methods an editor can offer at a written selection. Normal
/// checking prepares only the names and trait keys the program requests.
pub fn typecheckForEditor(
    gpa: std.mem.Allocator,
    program: *const ExpandedProgram,
    resolution: *const Resolution,
    sink: *Sink,
) !Typing {
    return typecheckInternal(gpa, program, resolution, sink, null, null, true);
}

pub const ContinuedTyping = struct {
    arena: std.heap.ArenaAllocator,
    typing: Typing,

    pub fn deinit(self: *ContinuedTyping) void {
        self.arena.deinit();
        self.* = undefined;
    }
};

/// Continue from attached library identities. The prefix must outlive the result.
pub fn typecheckWithPrefix(
    backing: std.mem.Allocator,
    program: *const ExpandedProgram,
    resolution: *const Resolution,
    sink: *Sink,
    prefix: *const LibraryPrefix,
    relocation: relocation_mod.Relocation,
    /// Whether to prepare every method an editor can offer at a written
    /// selection, as `typecheckForEditor` does.
    prepare_completions: bool,
) !ContinuedTyping {
    var arena = std.heap.ArenaAllocator.init(backing);
    errdefer arena.deinit();
    const gpa = arena.allocator();
    var retained: RetainedTyping = .{ .typing = prefix.typing, .seed = prefix.seed };
    {
        const mapping = relocation;
        retained.typing = try retained_typing.attach(gpa, &prefix.typing, mapping);
        retained.seed = .{
            .parameters = try attachSeedRows(gpa, []const TypeId, prefix.seed.parameters, .decls, &.{}, mapping),
            .declared_types = try attachSeedRows(gpa, TypeId, prefix.seed.declared_types, .decls, .poison, mapping),
            .declarations = try attachSeedRows(gpa, bool, prefix.seed.declarations, .decls, false, mapping),
            .expression_owners = try attachSeedRows(gpa, DeclId, prefix.seed.expression_owners, .exprs, .none, mapping),
            .binding_owners = try gpa.dupe(DeclId, prefix.seed.binding_owners),
            .call_impls = try retained_typing.mapValue(gpa, mapping, prefix.seed.call_impls),
        };
        for (@constCast(retained.seed.binding_owners)) |*owner| owner.* = mapping.id(DeclId, owner.*);
    }
    const typing = try typecheckInternal(gpa, program, resolution, sink, null, &retained, prepare_completions);
    return .{ .arena = arena, .typing = typing };
}

fn attachSeedRows(
    gpa: std.mem.Allocator,
    comptime T: type,
    saved: []const T,
    comptime domain: relocation_mod.Domain,
    fill: T,
    mapping: relocation_mod.Relocation,
) ![]const T {
    const end = mapping.index(domain, @intCast(saved.len));
    const result = try gpa.alloc(T, end);
    @memset(result, fill);
    for (saved, 0..) |value, i| result[mapping.index(domain, @intCast(i))] = mapping.value(value);
    return result;
}

/// Frees what a recorded demand owns: a trait demand's arguments.
fn freeRefusedDemand(gpa: std.mem.Allocator, demand: types_mod.RefusedDemand) void {
    if (demand.lacks == .trait and demand.lacks.trait.args.len > 0) gpa.free(demand.lacks.trait.args);
}

fn typecheckInternal(
    gpa: std.mem.Allocator,
    program: *const ExpandedProgram,
    resolution: *const Resolution,
    sink: *Sink,
    captured_seed: ?*CheckSeed,
    retained: ?*const RetainedTyping,
    prepare_completions: bool,
) !Typing {
    const ast = &program.ast;
    // Built inside a block so the guards below stop where it ends. Written as
    // one struct literal, a field that failed left every field before it
    // allocated and belonging to a checker that was never built; guarded from
    // out here instead, they would fire again beside the `defer`s that own
    // them once the checker exists, and free the same memory twice.
    var c: Checker = made: {
        const constraint_subjects = try gpa.alloc(TypeId, resolution.constraints.records.len);
        errdefer gpa.free(constraint_subjects);
        @memset(constraint_subjects, .poison);

        var builder = if (retained) |prefix| try Typing.Builder.reopen(gpa, &prefix.typing) else try Typing.Builder.init(gpa);
        builder.implementations_settled = false;
        errdefer builder.deinit();

        var folds = try @import("../support/table.zig").Table(ExprId, Fold).of(gpa, ast.exprCount(), .not_constant);
        errdefer folds.deinit(gpa);

        var binding_types = try resolution.bindingTable(gpa, TypeId, .poison);
        errdefer binding_types.deinit(gpa);

        const expression_owners = try gpa.alloc(DeclId, ast.exprCount());
        errdefer gpa.free(expression_owners);
        @memset(expression_owners, .none);
        const binding_owners = try gpa.alloc(DeclId, resolution.bindingCount());
        errdefer gpa.free(binding_owners);
        @memset(binding_owners, .none);

        var decl_returns = try ast.declTable(gpa, TypeId, .poison);
        errdefer decl_returns.deinit(gpa);

        var decl_signatures = try ast.declTable(gpa, TypeId, .poison);
        errdefer decl_signatures.deinit(gpa);

        const declared_requirements = try gpa.alloc(node.CapabilityRequirement, ast.declCount());
        errdefer gpa.free(declared_requirements);

        const declared_traits = try gpa.alloc([]const types_mod.BoundTrait, ast.declCount());
        errdefer gpa.free(declared_traits);
        @memset(declared_traits, &.{});

        const declared_callables = try gpa.alloc([]const TypeId, ast.declCount());
        errdefer gpa.free(declared_callables);
        @memset(declared_callables, &.{});

        const ring_said = try gpa.alloc(bool, resolution.bindingCount());
        errdefer gpa.free(ring_said);

        const constant_taken = try gpa.alloc(bool, resolution.bindingCount());
        errdefer gpa.free(constant_taken);

        const callable_default_sites = try gpa.alloc(?Checker.CallableDefaultSite, ast.exprCount());
        errdefer gpa.free(callable_default_sites);
        @memset(callable_default_sites, null);

        const callable_defaults_checked = try gpa.alloc(bool, ast.exprCount());
        errdefer gpa.free(callable_defaults_checked);
        @memset(callable_defaults_checked, false);

        const call_of = try gpa.alloc(u32, ast.exprCount());
        errdefer gpa.free(call_of);
        @memset(call_of, Checker.no_call);

        const recovery_of = try gpa.alloc(bool, ast.exprCount());
        errdefer gpa.free(recovery_of);
        @memset(recovery_of, false);

        const defaults_folded = try gpa.alloc(bool, ast.declCount());
        errdefer gpa.free(defaults_folded);
        @memset(defaults_folded, false);

        const signature_built = try gpa.alloc(bool, ast.declCount());
        errdefer gpa.free(signature_built);
        @memset(signature_built, false);

        const declared_results = try gpa.alloc(?TypeId, ast.declCount());
        errdefer gpa.free(declared_results);
        @memset(declared_results, null);

        const closure_descriptors = try gpa.alloc(types_mod.ClosureDescriptor, resolution.closures.count());
        errdefer gpa.free(closure_descriptors);
        @memset(closure_descriptors, .{
            .enclosing = .none,
            .expr = .none,
            .body = .none,
            .signature = .poison,
        });

        errdefer for (closure_descriptors) |descriptor| gpa.free(descriptor.owned_fields);
        for (closure_descriptors, 0..) |*descriptor, index| {
            const captures = resolution.closureCaptures(@enumFromInt(index));
            var count: usize = 0;
            for (captures) |capture| if (capture.convention == .sink) {
                count += 1;
            };
            const owned = try gpa.alloc(types_mod.FieldOrdinal, count);
            var next: usize = 0;
            for (captures, 0..) |capture, field| if (capture.convention == .sink) {
                owned[next] = @enumFromInt(field);
                next += 1;
            };
            descriptor.owned_fields = owned;
        }

        const binder_places = try gpa.alloc(?Checker.BinderPlace, resolution.bindingCount());
        errdefer gpa.free(binder_places);

        const written_types = try gpa.alloc(TypeId, ast.tokens.len);
        errdefer gpa.free(written_types);
        @memset(written_types, .poison);

        // The trait a bracket names, and the two members of it a site reads.
        // Found here for the reason every other prelude declaration is: which
        // declaration `Index` is is a fact about this compilation, and its
        // members are facts about the library -- neither is a search a bracket
        // repeats.
        const index_decl = preludeDecl(ast, resolution, "Index");

        // The two traits a `for` walks through, and the declared type each of
        // them settles. Found here for the reason `Index` is: which
        // declarations they are is a fact about this compilation, and their
        // members are facts about the library.
        const sequence_decl = sequenceDecl(ast, resolution);
        const iterator_decl = iteratorDecl(ast, resolution);
        const formatting = FormattingDecls.init(ast, resolution);
        const from_decl = fromDecl(program);
        const settle_decl = settleDecl(program);

        break :made .{
            .gpa = gpa,
            .retained = retained,
            .program = program,
            .current = program.source.primary,
            .raw_accesses = RawAccesses.init(program, ast),
            .float_math_candidates = FloatMath.candidates(program, ast),
            .ast = ast,
            .constraints = &resolution.constraints,
            .constraint_subjects = constraint_subjects,
            .res = resolution,
            .sink = sink,
            .builder = builder,
            .folds = folds,
            .binding_types = binding_types,
            .expression_owners = expression_owners,
            .binding_owners = binding_owners,
            .decl_returns = decl_returns,
            .decl_signatures = decl_signatures,
            .declared_requirements = declared_requirements,
            .declared_traits = declared_traits,
            .declared_callables = declared_callables,
            .ring_said = ring_said,
            .constant_taken = constant_taken,
            .callable_default_sites = callable_default_sites,
            .callable_defaults_checked = callable_defaults_checked,
            .call_of = call_of,
            .recovery_of = recovery_of,
            .defaults_folded = defaults_folded,
            .signature_built = signature_built,
            .declared_results = declared_results,
            .closure_descriptors = closure_descriptors,
            .binder_places = binder_places,
            .written_types = written_types,
            .binding_value_locs = try gpa.alloc(Loc, resolution.bindingCount()),
            .option_decl = preludeDecl(ast, resolution, "Option"),
            .str_decl = preludeDecl(ast, resolution, "Str"),
            .result_decl = preludeDecl(ast, resolution, "Result"),
            .display_decl = formatting.display.trait,
            .formatting = formatting,
            .equatable_decl = equatableDecl(ast, resolution),
            .comparable_decl = comparableDecl(ast, resolution),
            .range_decl = preludeDecl(ast, resolution, "Range"),
            .index_decl = index_decl,
            .index_at = traitMemberNamed(ast, resolution, index_decl, "at"),
            .index_elem = traitMemberNamed(ast, resolution, index_decl, "Elem"),
            .from_end_decl = preludeDecl(ast, resolution, "FromEnd"),
            .sequence_decl = sequence_decl,
            .sequence_iter = traitMemberNamed(ast, resolution, sequence_decl, "Iter"),
            .iterator_decl = iterator_decl,
            .iterator_item = traitMemberNamed(ast, resolution, iterator_decl, "Item"),
            .allocator_decl = program.libraryDeclIn("mem", "Allocator"),
            .from_decl = from_decl,
            .from_member = traitMemberNamed(ast, resolution, from_decl, "from"),
            .settle_decl = settle_decl,
            .settle_reason = traitMemberNamed(ast, resolution, settle_decl, "Reason"),
        };
    };
    c.builder.constant_pool = &c.folded.pool;
    c.builder.closure_descriptors = c.closure_descriptors;
    c.builder.certified_storage = c.raw_accesses.storage;
    c.builder.certified_buffer = c.raw_accesses.buffer;
    c.builder.certified_slice = c.raw_accesses.slice;
    c.builder.certified_closure_entry = c.raw_accesses.closure_entry_type;
    // The resolver settled which declarations tuple syntax names; the pool
    // spells their instances as tuples.
    c.builder.tuple_decls = resolution.tuple_decls;
    c.builder.open_types = &c.open_types;
    defer gpa.free(c.constraint_subjects);
    defer gpa.free(c.expression_owners);
    defer gpa.free(c.binding_owners);
    defer c.contextual_constraints.deinit(gpa);
    defer c.leaves.deinit(gpa);
    defer c.folds.deinit(gpa);
    defer c.literal_values.deinit(gpa);
    defer c.open_types.deinit(gpa);
    defer c.conversion_targets.deinit(gpa);
    defer c.integer_properties.deinit(gpa);
    defer c.selected_places.deinit(gpa);
    defer c.place_projections.deinit(gpa);
    defer c.implicit_test_successes.deinit(gpa);
    defer c.try_conversions.deinit(gpa);
    defer c.field_names.deinit(gpa);
    defer c.type_selections.deinit(gpa);
    defer c.contract_variants.deinit(gpa);
    defer c.readonly_places.deinit(gpa);
    defer c.carried_places.deinit(gpa);
    defer c.borrowed_temporaries.deinit(gpa);
    defer c.interpolation_positions.deinit(gpa);
    defer c.receivers_checked.deinit(gpa);
    defer c.array_lengths.deinit(gpa);
    defer c.refused.deinit(gpa);
    defer c.folded_indices.deinit(gpa);
    defer c.constant_values.deinit(gpa);
    defer c.constant_groundness.deinit(gpa);
    defer {
        var plans = c.constant_materializations.valueIterator();
        while (plans.next()) |plan| gpa.free(plan.fields);
        c.constant_materializations.deinit(gpa);
    }
    defer c.field_name_spellings.deinit(gpa);
    defer c.decl_of_type.deinit(gpa);
    defer c.named_postfix_functions.deinit(gpa);
    defer c.decided_marks.deinit(gpa);
    defer c.deferred_marks.deinit(gpa);
    for (resolution.deferred_immutable, 0..) |lent, at| try c.deferred_marks.put(gpa, lent.mark, @intCast(at));
    defer c.impl_index.deinit(gpa);
    defer {
        c.loops.deinit(gpa);
    }
    defer c.bounds_reported.deinit(gpa);
    defer c.bounds_reported_order.deinit(gpa);
    defer c.refused_parts.deinit(gpa);
    defer c.bound_sites.deinit(gpa);
    defer c.alias_site_args.deinit(gpa);
    defer c.alias_types.deinit(gpa);
    defer c.alias_shapes.deinit(gpa);
    defer c.aliases_reading.deinit(gpa);
    defer c.defaults_reading.deinit(gpa);
    defer c.carried_omissions.deinit(gpa);
    defer c.impls_publishing.deinit(gpa);
    defer c.defaulted_calls.deinit(gpa);
    defer c.defaulted_bindings.deinit(gpa);
    defer c.deinitCheckedTemplateRequirements();
    defer c.invalid_templates.deinit(gpa);
    defer c.suppressed_generated_implementations.deinit(gpa);
    defer c.discarded_components.deinit(gpa);
    defer c.suppressed_generated_bodies.deinit(gpa);
    defer {
        for (c.call_impls.items) |record| if (record.args.len > 0) gpa.free(record.args);
        c.call_impls.deinit(gpa);
        c.overlapping.deinit(gpa);
    }
    defer {
        for (c.calls.items) |call| call.deinit(gpa);
        c.calls.deinit(gpa);
    }
    defer c.recovered_call_args.deinit(gpa);
    defer c.recovered_calls.deinit(gpa);
    defer {
        for (c.function_values.items) |value| value.deinit(gpa);
        c.function_values.deinit(gpa);
        for (c.pending_values.items) |pending| pending.deinit(gpa);
        c.pending_values.deinit(gpa);
        c.binding_labels.deinit(gpa);
    }
    defer gpa.free(c.call_of);
    defer gpa.free(c.recovery_of);
    defer gpa.free(c.defaults_folded);
    defer gpa.free(c.signature_built);
    defer gpa.free(c.declared_results);
    defer c.template_signatures.deinit(gpa);
    defer c.declined_contracts.deinit(gpa);
    defer c.refused_owned_promises.deinit(gpa);
    defer c.refused_owned_subjects.deinit(gpa);
    defer c.adopted_contracts.deinit(gpa);
    defer c.defaulted_contracts.deinit(gpa);
    defer {
        for (c.closure_descriptors) |descriptor| gpa.free(descriptor.owned_fields);
        gpa.free(c.closure_descriptors);
    }
    defer {
        for (c.projected.items) |row| gpa.free(row.impl_args);
        c.projected.deinit(gpa);
    }
    defer {
        for (c.traversals.items) |row| gpa.free(row.impl_args);
        c.traversals.deinit(gpa);
    }
    defer c.traversal_of_type.deinit(gpa);
    defer c.traversal_positions.deinit(gpa);
    defer {
        for (c.expansions.items) |row| {
            gpa.free(row.impl_args);
            if (row.delegation) |delegate| gpa.free(delegate.backing_args);
        }
        c.expansions.deinit(gpa);
    }
    defer c.delegation_state.deinit(gpa);
    defer c.range_places.deinit(gpa);
    defer c.projected_at.deinit(gpa);
    defer c.written.deinit(gpa);
    defer c.walk_helps.deinit(gpa);
    defer c.refused_demands.deinit(gpa);
    defer {
        for (c.refused_demands_order.items) |demand| freeRefusedDemand(gpa, demand);
        c.refused_demands_order.deinit(gpa);
    }
    defer c.reach_marks.deinit(gpa);
    defer c.expansion_of_impl.deinit(gpa);
    defer c.extern_symbols.deinit(gpa);
    // Deferred rather than guarded: the index built from it is what the caller
    // leaves with, and the list itself is spent once that is built.
    defer c.supplied.deinit(gpa);
    defer {
        for (c.postfix.items) |p| gpa.free(p.args);
        c.postfix.deinit(gpa);
    }
    defer c.named.deinit(gpa);
    defer c.contract_parameters.deinit(gpa);
    // Deferred rather than guarded: the table the caller leaves with is taken
    // off this field, which leaves an empty one behind to free.
    defer c.defaults.deinit(gpa);
    defer c.type_param_slots.deinit(gpa);
    defer c.param_slots.deinit(gpa);
    defer c.param_slots_built.deinit(gpa);
    defer gpa.free(c.ring_said);
    defer gpa.free(c.constant_taken);
    defer gpa.free(c.callable_default_sites);
    defer gpa.free(c.callable_defaults_checked);
    defer c.constant_ring.deinit(gpa);
    defer {
        for (c.constant_dependencies.items) |dependencies| gpa.free(dependencies.bindings);
        c.constant_dependencies.deinit(gpa);
    }
    defer c.folded.deinit(gpa);
    defer gpa.free(c.binder_places);
    defer c.lent_now.deinit(gpa);
    defer c.aliased.deinit(gpa);
    defer c.pattern_places.deinit(gpa);
    defer {
        var names = c.variant_names.valueIterator();
        while (names.next()) |index| index.deinit(gpa);
        c.variant_names.deinit(gpa);
    }
    defer gpa.free(c.binding_value_locs);
    errdefer c.builder.deinit();
    // Guarded rather than deferred: the binding types leave with the caller,
    // so the only run that frees them here is one that never gets that far.
    errdefer c.binding_types.deinit(gpa);
    errdefer c.decl_returns.deinit(gpa);
    errdefer c.decl_signatures.deinit(gpa);
    errdefer gpa.free(c.declared_requirements);
    errdefer gpa.free(c.declared_traits);
    errdefer {
        for (c.declared_callables) |bounds| if (bounds.len > 0) gpa.free(bounds);
        gpa.free(c.declared_callables);
    }
    errdefer gpa.free(c.written_types);
    defer c.variant_uses.deinit(gpa);
    if (retained) |prefix| c.folded.pool = try prefix.typing.constant_pool.clone(gpa);

    // A declaration with no body, or one whose annotation did not read as a
    // type, keeps this -- and lowering generates nothing for either.
    @memset(c.ring_said, false);
    @memset(c.constant_taken, false);
    @memset(c.binder_places, null);
    @memset(c.binding_value_locs, Loc.nowhere);
    if (retained) |prefix| try c.retainAnswers(prefix);
    try c.indexTypeParams();
    // What each declared type's bounds demand of whatever settles it, which is
    // what a projection of it owes. Read from the routine a type parameter's
    // capability is read from, because a declared type carries bounds on the
    // terms a type parameter does and a second reading of the same run of
    // names would be a second answer to one question.
    //
    // Before every written type, since a projection is interned the first time
    // one is read and its capability is settled where it is minted. Linear for
    // every declaration that declares no type, which is the answer a
    // projection of nothing would get anyway.
    @memset(c.declared_requirements, .unrestricted);

    // Before any bound list is read for what it admits. That reading follows a
    // trait's bounds to their own, and a cycle is a promise no implementation
    // could keep -- said here, once, rather than at each bound that reaches
    // one.
    try c.reportTraitBoundCycles();

    // After the cycles and before anything reads what a list demands: a list
    // asking a capability of a name twice is refused for what it says, and every
    // reading of it below here is of a list that said it once.
    try c.reportCapabilityDemands();

    // A bound's argument count is a property of the bound alone, fixed the
    // moment its trait is declared -- so it is checked here, once, rather
    // than wherever a bound is later read for what it admits.
    try c.reportBoundArity();

    // The capability alone here, from a reading that interns nothing. A
    // projection's capability is settled where the projection is minted, which
    // is before the head types are in the pool -- and interning a bound's
    // arguments needs them there. The traits the same bounds name are read
    // below, once they are.
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        if (ast.declTag(d) != .associated_type) continue;
        const reaches = try c.traitsBounding(null, ast.declBounds(d));
        defer types_mod.freeBoundTraits(gpa, reaches);
        c.declared_requirements[i] = capabilityDemandedBy(ast, resolution, ast.declBounds(d), reaches);
    }
    c.builder.declared_requirements = c.declared_requirements;

    const z_decltypes = tracy.beginZone(@src(), "tc.decltypes");
    try c.builder.setExprCount(ast.exprCount());
    if (retained) |prefix| {
        @memcpy(c.builder.expr_types.items[0..prefix.typing.expr_types.len], prefix.typing.expr_types);
        @memcpy(c.builder.construction_types.items[0..prefix.typing.construction_types.len], prefix.typing.construction_types);
    }

    // Every declared type enters the pool before any body is walked, for the
    // reason declarations enter the module scope first: a body may mention a
    // type declared further down.
    var type_of_decl = try ast.declTable(gpa, TypeId, .poison);
    defer type_of_decl.deinit(gpa);
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        if (c.isRetained(d)) {
            type_of_decl.set(d, retained.?.seed.declared_types[i]);
            continue;
        }
        if (ast.declTag(d) == .struct_) {
            // Entered with its fields' types unresolved, for the reason an
            // enum is: a field may name a type declared further down.
            const run = try gpa.alloc(types_mod.Field, ast.declFields(d).len);
            defer gpa.free(run);
            for (ast.declFields(d), 0..) |f, k| {
                run[k] = .{ .name = ast.tokenText(f.name), .ty = .poison };
                if (ast.tokenName(f.name) != .none) try c.field_name_spellings.put(gpa, ast.tokenName(f.name), ast.tokenText(f.name));
            }
            type_of_decl.set(d, try c.builder.addStruct(
                ast.tokenText(ast.declName(d)),
                ast.declOwnershipPolicy(d),
                run,
            ));
            try c.builder.noteTemplate(d, @intCast(program.moduleOf(d).index()), type_of_decl.get(d));
            continue;
        }
        if (ast.declTag(d) == .newtype) {
            // Entered with its base still `.poison`: a newtype's base may
            // name a type declared further down, the same reason a
            // structure's fields are entered unresolved above.
            var refined = false;
            var lo: i128 = 0;
            var hi: i128 = 0;
            // A clause whose bounds the parser could not read holds nobody to
            // anything: the mistake was reported where it was found, and a
            // range folded out of tokens that are not there would refuse
            // every construction of the type for a second reason.
            if (ast.newtypeRefinement(d)) |r| readable: {
                if (r.lo_token == .none or r.hi_token == .none) break :readable;

                refined = true;
                const lo_v = c.foldRefinementBound(r.lo());
                const hi_v = c.foldRefinementBound(r.hi());
                lo = lo_v;
                // Folded to a closed interval regardless of how it was
                // spelled, the way a range pattern already folds `..` and
                // `..=` to the same interval before [T-Cover] reads it.
                hi = if (r.inclusive) hi_v else hi_v - 1;
                if (lo > hi) {
                    try c.sink.addErrorFmt(
                        .t_refine,
                        ast.fileOfDecl(d),
                        ast.declNameSpan(d),
                        "widen the range, or write no clause at all",
                        "{d}{s}{d} admits no value for `{s}`",
                        .{
                            lo_v,
                            if (r.inclusive) "..=" else "..",
                            hi_v,
                            ast.tokenText(ast.declName(d)),
                        },
                    );
                }
            }
            type_of_decl.set(d, try c.builder.addNewtype(
                ast.tokenText(ast.declName(d)),
                ast.declOwnershipPolicy(d),
                .poison,
                refined,
                lo,
                hi,
            ));
            // A name over a base is a declared type like the two above, so it
            // is recorded as one: what a declaration declares is how an `impl`
            // finds the head it names, and a head no declaration answers for
            // reaches no implementation at all.
            try c.builder.noteTemplate(d, @intCast(program.moduleOf(d).index()), type_of_decl.get(d));
            continue;
        }
        if (ast.declTag(d) != .enum_) continue;

        const variants = ast.declVariants(d);

        const entries = try gpa.alloc(types_mod.Variant, variants.len);
        defer gpa.free(entries);
        // Callable bounds need the payload shape before field types resolve.
        // Reserve each slot now and fill its type after every nominal exists.
        for (variants, 0..) |v, k| {
            const count = ast.variantFields(v).len;
            const fields = try gpa.alloc(types_mod.Field, count);
            defer gpa.free(fields);
            @memset(fields, .{ .name = "", .ty = .poison });
            entries[k] = .{
                .name = ast.tokenText(v.name),
                .first_field = try c.builder.addFields(fields),
                .field_count = @intCast(count),
            };
        }

        type_of_decl.set(d, try c.builder.addEnum(
            ast.tokenText(ast.declName(d)),
            ast.declOwnershipPolicy(d),
            entries,
        ));
        try c.builder.noteTemplate(d, @intCast(program.moduleOf(d).index()), type_of_decl.get(d));
    }
    c.type_of_decl = type_of_decl.reading();
    var walking = type_of_decl.pairs();
    while (walking.next()) |each| {
        const t = each.value;
        if (t == .poison) continue;
        const gop = try c.decl_of_type.getOrPut(gpa, t);
        if (!gop.found_existing) gop.value_ptr.* = each.id;
    }

    z_decltypes.end();

    // What a declared type's bounds promise, at the arguments they name:
    // `type Elem: Lookup[UInt64]` promises `Lookup` at `UInt64`, so a settled
    // reference standing for `Elem` discharges a bound written at that
    // argument and none written at another.
    //
    // Here because both ends are fixed. An argument may name a type this
    // module declares, so the head types must already be in the pool; and
    // minting a settled reference reads this table, so it must be filled
    // before the first one -- which is an implementation's own head, interned
    // just below.
    //
    // Settled once for the declaration rather than per implementation,
    // because nothing open can stand in such an argument: neither the trait's
    // own parameters nor `Self` resolves there, so there is nothing for an
    // instantiation to substitute.
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        if (ast.declTag(d) != .associated_type) continue;
        c.declared_traits[i] = try c.traitsBounding(
            .{ .module = program.moduleOf(d), .owner = d },
            ast.declBounds(d),
        );
    }
    c.builder.declared_traits = c.declared_traits;

    // Once the head types are interned and before any bound is discharged: a
    // bound is asked about while a body is walked, and the answer is the same
    // whichever body asks.
    const z_impls = tracy.beginZone(@src(), "tc.impls");

    // What a token owns and what an extent holds, for every declaration at
    // once. Both questions are asked per implementation and per trait, and
    // each of them answered by a filter over the program is that filter run
    // once per implementation the program declares.
    c.decls = try DeclIndex.build(gpa, ast);
    defer c.decls.deinit(gpa);

    const implementations = try collectImplementations(gpa, ast, program, resolution, &c.builder);
    // The arguments each one supplied are handed on with it rather than freed
    // here: lowering asks the same question after instantiation that a call
    // asked before it, and the answer is keyed on them.
    defer gpa.free(implementations);
    c.implementations = implementations;
    c.impl_index = try types_mod.ImplIndex.build(gpa, implementations);

    // What each declaration's implementation recorded, as a row of the list
    // above. Which implementation encloses a declaration is the resolver's
    // relation, so this is that relation followed by the row: a declaration
    // whose implementation the collection recorded nothing for holds no row
    // here, and what `Self` is there is answered off the relation itself.
    //
    // One entry per declaration, and one step to fill each.
    const row_of_impl = try gpa.alloc(u32, ast.declCount());
    defer gpa.free(row_of_impl);
    c.row_of_impl = row_of_impl;
    @memset(row_of_impl, impl_of_none);
    // An implementation the compiler provides encloses no declaration, so
    // there is no row of this table for it to be the answer of.
    for (implementations, 0..) |i, k| {
        if (i.isAmbient()) continue;
        row_of_impl[i.decl.index()] = @intCast(k);
    }

    const impl_of_decl = try gpa.alloc(u32, ast.declCount());
    errdefer gpa.free(impl_of_decl);
    @memset(impl_of_decl, impl_of_none);
    for (0..ast.declCount()) |i| {
        const impl = resolution.implEnclosing(node.DeclId.at(@intCast(i)));
        if (impl == node.DeclId.none) continue;
        impl_of_decl[i] = row_of_impl[impl.index()];
    }
    c.impl_of_decl = impl_of_decl;

    // Which traversal each type declares, from the implementations already
    // collected. A walk then asks an index rather than searching the program's
    // declarations for a `trav` written on the type it walks, which is a walk
    // of everything per loop.
    //
    // **Bound:** the members of the inherent implementations, once.
    for (implementations, 0..) |row, at| {
        if (row.isAmbient()) continue;
        if (row.trait != types_mod.Implementation.no_trait) continue;
        const impl = row.decl;
        const head = ast.declName(impl);
        // The declaration the row's head names, as the collection recorded it.
        // A builtin head names none: nothing declares a primitive, and an
        // array's traversal is the compiler's own.
        const declares = switch (row.head) {
            .applied => |named| named,
            .whole => |ty| c.declaringType(ty) orelse continue,
            .parameter, .default_, .array, .borrow_, .callable_ => continue,
        };
        for (c.decls.ownedBy(head)) |member| {
            if (ast.declTag(member) != .traversal_) continue;
            const seen = try c.traversal_of_type.getOrPut(gpa, declares);
            if (seen.found_existing) {
                // Two traversals are two orders, and a walk over the type
                // would have to pick one. The second is reported where it is
                // written, which is the one a reader has to remove.
                try sink.addErrorFmt(
                    .t_lend,
                    ast.fileOf(ast.declName(member)),
                    ast.tokenSpan(ast.declName(member)),
                    "a type is walked in one order, and this is a second",
                    "`{s}` already declares a traversal",
                    .{ast.tokenText(head)},
                );
                continue;
            }
            seen.value_ptr.* = .{ .member = member, .row = @intCast(at) };
        }
    }

    // The pool settles a settled reference through the tables a call reaches a
    // body through -- `Builder.borrowTables` names the set -- so it is handed
    // each of them as it is built, the pairing below being the last. Borrowed
    // rather than given: what the checker leaves with owns them.
    c.builder.implementations = implementations;
    c.builder.impl_of_decl = impl_of_decl;
    c.builder.impl_index = c.impl_index;
    c.builder.decl_returns = c.decl_returns.reading();

    z_impls.end();

    // A declaration's type parameters, interned before anything reads an
    // annotation. A parameter is Copyable where a bound says so and Linear
    // otherwise: the pessimistic default is what makes one check of a body
    // sound for every instantiation.
    const z_params = tracy.beginZone(@src(), "tc.params");
    const param_types = try gpa.alloc([]const TypeId, ast.declCount());
    for (param_types) |*slot| slot.* = &.{};
    defer {
        for (param_types) |slot| if (slot.len > 0) gpa.free(slot);
        gpa.free(param_types);
    }

    // Aliased into the checker before a single parameter is interned, rather
    // than once every declaration's row is built: a bound may name an earlier
    // parameter of its own declaration -- `[I, C: Lookup[I]]` -- and
    // resolving that name reads this table through `self.param_types`. A row
    // is handed to its slot before it is filled, so the alias sees each
    // position the moment `addParameter` settles it rather than only once the
    // whole declaration is done.
    c.param_types = param_types;

    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        const params = ast.declTypeParams(d);
        if (params.len == 0) continue;
        if (c.isRetained(d)) {
            param_types[i] = try gpa.dupe(TypeId, retained.?.seed.parameters[i]);
            continue;
        }

        // Handed to its slot immediately, so the outer `defer` above is what
        // frees it on every path -- including one a later position in this
        // same declaration fails on, since that position already read the
        // positions before it through this same row.
        const row = try gpa.alloc(TypeId, params.len);
        // A position not yet reached reads poison until it is: a bound naming
        // one out of order -- a later parameter of the same declaration, or
        // one the parser never finished -- finds nothing usable rather than
        // whatever bytes the allocator happened to leave there.
        @memset(row, .poison);
        param_types[i] = row;

        // What a bound demands of a capability is read from the bounds alone,
        // and from a closure walked with nothing interned: a capability does not
        // depend on a bound's arguments, and interning one would read the
        // parameters of a trait this loop may not have reached.
        //
        for (params, 0..) |p, k| {
            const bounds = c.parameterBounds(d, k);
            const reaches = try c.traitsBounding(null, bounds);
            defer types_mod.freeBoundTraits(gpa, reaches);
            row[k] = try c.builder.addParameter(
                ast.tokenText(p.name),
                @intCast(i),
                @intCast(k),
                capabilityDemandedBy(ast, resolution, bounds, reaches),
                &.{},
            );
            c.builder.pool.items[row[k].index()].parameter.integer = integerDemandedBy(ast, resolution, bounds, reaches);
            c.builder.pool.items[row[k].index()].parameter.owned = ownedBound(ast, resolution, bounds) != null;
        }
    }

    // Resolve trait argument shapes before a field selects an associated
    // type through a parameter. Callable effects depend on completed fields,
    // so this first environment carries only callable shapes.
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        for (ast.declTypeParams(d), 0..) |_, k| {
            const traits = try c.traitsBounding(
                .{ .module = program.moduleOf(d), .owner = d },
                c.parameterBounds(d, k),
            );
            try c.builder.setBoundTraits(param_types[i][k], traits);
        }
    }
    try c.reportRefusedParts();
    // A shape read before a part was refused may be one reading it would
    // not terminate, so aliases are read again from here.
    c.alias_shapes.clearRetainingCapacity();
    try c.fillDeclaredParts(false);
    try c.builder.refillInstances();
    c.callable_effects_ready = true;

    // Associated promises can themselves apply callable type arguments.
    // Keep their old rows owned until the checker finishes; stand-ins may
    // still name those rows until the canonical promises below are installed.
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        if (ast.declTag(d) != .associated_type) continue;
        const previous = c.declared_traits[i];
        const current = try c.traitsBounding(
            .{ .module = program.moduleOf(d), .owner = d },
            ast.declBounds(d),
        );
        errdefer types_mod.freeBoundTraits(gpa, current);
        try c.builder.owned_bounds.append(gpa, previous);
        c.declared_traits[i] = current;
    }

    // A settled reference may be interned while the callable bounds below are
    // read, so its declaration's callable promises must already be available.
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        if (ast.declTag(d) != .associated_type) continue;
        c.declared_callables[i] = try c.callablesBounding(
            .{ .module = program.moduleOf(d), .owner = d },
            ast.declBounds(d),
            c.declared_traits[i],
        );
    }
    c.builder.declared_callables = c.declared_callables;
    for (c.builder.standins.items) |standin| {
        const parameter = &c.builder.pool.items[standin.ty.index()].parameter;
        parameter.traits = c.declared_traits[standin.member.index()];
        parameter.callables = c.declared_callables[standin.member.index()];
    }

    // What each parameter's bounds admit, at the arguments they name.
    //
    // A second sweep because a bound's arguments are read in the scope of the
    // trait that wrote them: `trait Fancy[X]: Lookup[X]` requires `Lookup` at
    // whatever `X` stands for, so a parameter bounded `Fancy[UInt64]` cannot
    // be settled until `Fancy`'s own parameters are in the pool. One loop
    // would settle that in whatever order the declarations happen to sit in,
    // which is a program meaning one thing and its declarations reversed
    // meaning another.
    //
    // Within a declaration this still runs in order, which is what a bound
    // naming an earlier parameter of its own declaration reads -- and a
    // settled reference in a bound's argument reads the bounds of the
    // parameter it is rooted at, which is an earlier position of the same
    // declaration or nothing.
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        // A trait signature's bounds may name `Self` and what its
        // implementation settles, `F: fn(sink reading: Self.Reading) -> U`.
        // They are read over the signature's symbolic `Self`, the reading
        // its parameter annotations take, and a call reads them with its own
        // `Self` in that place.
        c.self_at_call = if (ast.declTypeParams(d).len > 0 and ast.declIsSignature(d)) try c.signatureSelfType(d) else null;
        defer c.self_at_call = null;
        for (ast.declTypeParams(d), 0..) |_, k| {
            const bounds = c.parameterBounds(d, k);
            const admits = try c.traitsBounding(
                .{ .module = program.moduleOf(d), .owner = d },
                bounds,
            );
            try c.builder.setBoundTraits(param_types[i][k], admits);
            var owned = try c.callablesBounding(
                .{ .module = program.moduleOf(d), .owner = d },
                bounds,
                admits,
            );
            if (c.raw_accesses.opensClosure(d) and k == 0) owned = try c.withClosureSignature(d, owned);
            try c.builder.setCallableBounds(param_types[i][k], owned);
        }
    }

    // Direct and projected constraints are resolved only after every direct
    // parameter predicate has joined the parameter's bound environment. A
    // projected subject can therefore read through a bound written after it.
    try c.resolveConstraints();

    z_params.end();

    // What each implementation supplied for its trait's parameters, and what
    // its head names. Read here because everything below asks which
    // implementations answer for which types, and an applied head that has not
    // been settled still stands for the constructor it names and applies
    // nothing to it -- so no member of any family answers for anything, and a
    // question about the implementations gets an answer about the concrete
    // ones alone.
    const z_heads = tracy.beginZone(@src(), "tc.heads");
    for (implementations) |*i| {
        // An implementation the compiler provides has no declaration to read a
        // head or trait arguments off: it supplies none, and its head is the
        // primitive it was seeded for.
        if (i.isAmbient()) continue;
        i.args = try c.traitArgumentsOf(i.decl);
        try c.settleHead(i);
        try c.settleImplementationPredicates(i);
    }

    z_heads.end();

    // Every implementation's head and trait arguments are settled now, so two
    // that could answer for one instantiation can be told from two that
    // cannot. Asked at declaration time and not at a call: coherence is a
    // property of the declarations, so a program's compiling could not depend
    // on whether anything ever calls through either one.
    const z_overlap = tracy.beginZone(@src(), "tc.overlap");
    try c.refuseOverlappingImplementations(implementations);
    z_overlap.end();

    // Before a part is resolved, because resolving one is what does not
    // terminate: a part that grows its own declaration's argument mints a type
    // per level until the stack ends, and one that holds its own declaration
    // mints a type that contains itself.
    const z_parts = tracy.beginZone(@src(), "tc.parts");
    try c.fillDeclaredParts(true);

    // Every alias is read once with callable effects settled, whether or not
    // anything names it: a published alias nothing in this program writes
    // still answers for the bounds its own written type must meet. A retained
    // library's alias is answered from that library's typing, and kept here
    // too so tooling reads every alias from one table.
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        if (ast.declTag(d) != .alias) continue;
        try c.alias_types.put(gpa, d, try c.aliasedType(d));
    }

    // Asked once, after every type is entered and before any layout is: a
    // type on a cycle has no size to compute, and every pass below here asks
    // for one.
    // Every template is complete now, so every instantiation made while one
    // was still being read is filled again from the finished thing.
    try c.builder.refillInstances();
    try c.checkStorageCertificates(type_of_decl);

    try c.reportLayoutCycles(type_of_decl);
    try c.reportCopyabilityDeclarations(type_of_decl);

    z_parts.end();

    const observation_traits = try @import("observations.zig").compute(gpa, ast, resolution);
    errdefer gpa.free(observation_traits);
    c.builder.observation_traits = observation_traits;
    const z_signatures = tracy.beginZone(@src(), "tc.signatures");

    // Which member of each implementation supplies which member of its trait,
    // and what each declared type was settled to. Before any signature is read
    // and any body is walked, because `Self.Item` written in either is that
    // pairing followed by that type -- and a written type read before the
    // answer exists is a type nobody named.
    try c.pairImplementationMembers();
    c.supply = try types_mod.SupplyIndex.build(gpa, ast.declCount(), c.supplied.items);
    errdefer c.supply.deinit(gpa);
    c.builder.supply = c.supply;
    try c.settleDeclaredTypes();
    for (implementations) |implementation| {
        if (!implementation.isAmbient() and ast.declDelegation(implementation.decl) != .none)
            _ = try c.settleDelegation(implementation.decl);
    }

    // And again, now that every implementation has settled what its trait
    // declared. A part written as a settled reference stands for whatever an
    // implementation settles the name to, and an instantiation minted before
    // that answer existed took poison for it: what a value of the type holds
    // was decided here rather than where the type was minted, so this is the
    // first point the pool says what it is.
    //
    // Which is what makes the cycle askable at all. An implementation may
    // close a layout the declaration alone does not -- settling `Iter` to
    // `S[Box]` is what makes an `S[Box]` hold an `S[Box]` -- and the argument
    // that closes it is the implementation's choice, so the answer belongs to
    // the type the argument makes and not to the declaration. Asked of the
    // written parts before instantiation and of the minted types after
    // settlement, through the one routine that answers it either time.
    //
    // **Bound:** one pass over the instantiations, as the refill above is,
    // and one walk of the pool.
    try c.builder.refillInstances();
    try c.reportLayoutCycles(type_of_decl);

    // Install written constant types before defaults can force initializers.
    // Unannotated constants acquire their type when their initializer is checked.
    for (0..resolution.bindingCount()) |i| {
        const b = BindingId.at(@intCast(i));
        if (resolution.kindOf(b) != .constant) continue;
        const d = resolution.declaredBy(b);
        c.current = program.moduleOf(d);
        c.generic = d;
        const annotation = ast.declReturnRef(d);
        if (annotation.wasWritten()) c.setBindingType(b, try c.bindingTypeCountingLiteral(annotation, ast.declInit(d)));
        c.generic = node.DeclId.none;
    }

    // Read parameter annotations with the same symbolic Self evidence used
    // by the callable signature, before defaults or bodies inspect them.
    // A source template's member reads `Self` as the template's open
    // parameter, the reading its signature is held to, so its annotations are
    // read in that scope below rather than here.
    for (program.template_members) |plan| try c.template_signatures.put(gpa, plan.member, .{ .template = plan.template, .signature = plan.signature });
    for (0..ast.declCount()) |i| {
        const owner = node.DeclId.at(@intCast(i));
        if (resolution.parametersOf(owner).len == 0) continue;
        if (c.template_signatures.contains(owner)) continue;
        c.current = program.moduleOf(owner);
        c.generic = owner;
        c.self_at_call = if (ast.declIsSignature(owner)) try c.signatureSelfType(owner) else null;
        for (resolution.parametersOf(owner)) |b| {
            const p = ast.declParams(owner)[resolution.paramIndexOf(b)];
            c.setBindingType(b, try c.typeOfRef(p.written));
        }
        c.self_at_call = null;
        c.generic = node.DeclId.none;
    }
    for (program.template_members) |plan| {
        c.current = program.moduleOf(plan.member);
        c.generic = plan.member;
        c.symbolic_self_owner = plan.member;
        c.self_at_call = try c.templateSelf(plan.template);
        for (resolution.parametersOf(plan.member)) |b| {
            const p = ast.declParams(plan.member)[resolution.paramIndexOf(b)];
            c.setBindingType(b, try c.typeOfRef(p.written));
        }
        c.self_at_call = null;
        c.symbolic_self_owner = node.DeclId.none;
        c.generic = node.DeclId.none;
    }

    // Then what each is bound to. Before every body, because what a constant
    // folded to is what a name reaching it stands for wherever it is written.
    // This settles the ones nothing else reached; a constant whose initialiser
    // names another has already taken that one first.
    for (0..resolution.bindingCount()) |i| {
        const b = BindingId.at(@intCast(i));
        if (resolution.kindOf(b) != .constant) continue;
        try c.ensureConstant(b);
    }

    c.callable_defaults_ready = true;
    for (c.callable_default_sites) |site| {
        if (site) |default| try c.checkCallableDefault(default);
    }

    // A template is source and its signature can be checked before any
    // generated signature is read. Do that first so an invalid template
    // suppresses its already-expanded members before a malformed copy can
    // produce a second, causally downstream implementation diagnostic.
    const source_decl_count = program.source.ast.declCount();
    for (program.modules, 0..) |_, mi| {
        c.current = ModuleId.from(mi);
        for (program.declsOf(c.current)) |d| {
            if (d.index() >= source_decl_count or ast.declTag(d) != .function) continue;
            try c.ensureSignature(d);
        }
    }
    try c.checkTemplateMembers();

    // A body may select a generated declaration from any module. Build every
    // admitted generated signature before walking any body so selection is
    // independent of source and load order. Suppressed copies stay poison;
    // their source template already owns the diagnostic.
    for (program.modules, 0..) |_, mi| {
        c.current = ModuleId.from(mi);
        for (program.declsOf(c.current)) |d| {
            if (d.index() < source_decl_count or ast.declTag(d) != .function) continue;
            if (c.generatedBodyIsSuppressed(d)) continue;
            try c.ensureSignature(d);
        }
    }

    c.release_discard = program.libraryDeclIn("release", "discard") orelse .none;

    // The structural supplier belongs to the library's actual Release contract.
    // Source traits with the same spelling do not acquire closure implementations.
    if (program.libraryDeclIn("release", "Release")) |trait| {
        if (traitMemberNamed(ast, resolution, trait, "release")) |member| {
            const signature = c.builder.get(c.decl_signatures.get(member));
            if (signature == .callable and signature.callable.result == .unit) {
                const params = c.builder.callableParams(signature.callable);
                if (params.len == 1 and params[0].convention == .sink)
                    c.builder.closure_release = .{ .trait = trait, .member = member };
            }
        }
    }

    var signature_view = c.builder.view();
    signature_view.decl_signatures = c.decl_signatures;
    c.float_math = c.float_math_candidates.checked(ast, &signature_view);

    z_signatures.end();

    const z_headers = tracy.beginZone(@src(), "tc.headers");
    try c.validateTemplateRequirements();
    try c.checkComponentRequirements();
    try c.checkImplementations();
    try c.checkStructuralSupertraits();
    try c.resettleConstraintSubjects();
    z_headers.end();

    c.builder.implementations_settled = true;
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        if (ast.declTag(d) == .traversal_ and ast.declDelegation(d) != .none and !c.isRetained(d))
            try c.checkDelegatedTraversal(d);
    }
    const z_bodies = tracy.beginZone(@src(), "tc.bodies");
    for (program.modules, 0..) |*m, mi| {
        c.current = ModuleId.from(mi);
        for (program.declsOf(c.current)) |d| {
            if (c.isRetained(d)) continue;
            if (ast.declIsExtern(d)) try c.checkExtern(d, m.externs, m.library);
            if (c.program.publishesExport(d)) try c.checkExport(d);
            if (ast.declTag(d) == .function) try c.checkLibraryFunctionDefaults(d);

            // Its own parameters answer for the whole declaration: the return
            // type, every annotation in the body, and every signature the body
            // writes down.
            c.generic = d;
            defer c.generic = node.DeclId.none;

            // A parameter's default is typed and folded here, which is the one
            // place either can happen: a call that omits the parameter is
            // handed the value rather than the expression. Above the bodyless
            // `continue` below, because a trait signature and an `extern`
            // declaration have no body to reach it through and a default
            // written on either is still an expression this pass owes a type
            // -- and still the one a call omitting the parameter receives.
            try c.ensureDefaults(d);

            const body = ast.declBody(d);
            if (body == ExprId.none) continue;
            if (c.generatedBodyIsSuppressed(d)) {
                std.debug.assert(ast.declTag(d) == .function);
                std.debug.assert(program.originOf(d) != null);
                try c.suppressed_generated_bodies.append(gpa, d);
                continue;
            }

            // What a projection's braces hold is a path and not code, and that
            // is a fact about the tree rather than about types. Asked here, on
            // the walk that already has the declaration in hand, so there is
            // no second walk over every declaration to find the few that are
            // projections.
            if (ast.declTag(d) == .projection) try c.checkProjectionBody(d);

            // The return type is the outermost expectation, and the one a mismatch
            // in the body most often needs pointed at.
            // Whether one was written, not whether it has a name: an array has
            // none, and reading that absence as "nothing was written" leaves a
            // body checked against no expectation and a function whose return
            // type lowering never learns.
            const written_return = ast.declReturnRef(d);
            const want: ?Expected = if (written_return.wasWritten()) blk: {
                const ty = try c.declaredResultType(d);
                if (ty == .poison) break :blk null;
                break :blk .{
                    .ty = ty,
                    .at = c.locOfWritten(written_return),
                    .reason = .return_type,
                    .alias = c.aliasHeading(d, written_return),
                };
            } else if (ast.declIsTest(d)) .{
                .ty = try returnType(&c, d),
                .at = .{ .file = ast.fileOfDecl(d), .span = ast.tokenSpan(ast.declName(d)) },
                .reason = .return_type,
                .unit_test_success = true,
            } else if (ast.declTag(d) == .function and written_return.isOmitted()) .{
                .ty = try c.declaredResultType(d),
                .at = .{ .file = ast.fileOfDecl(d), .span = ast.tokenSpan(ast.declName(d)) },
                .reason = .omitted_result,
            } else null;

            // Recorded from the same call the body is checked against, so
            // there is one answer to what a function returns rather than two
            // that agree until a body's value leaves only through `return`.
            c.decl_returns.set(d, if (want) |x| x.ty else .poison);

            c.current_return = want;
            // A trait's provided operation is checked once over its symbolic
            // `Self`, the reading its header takes, so every type implementing
            // the trait runs the one body.
            c.self_at_call = if (ast.declIsProvided(d)) try c.signatureSelfType(d) else null;
            defer c.self_at_call = null;
            // A body's open literals take the default where nothing in the
            // body settled them, before any other body can read their types.
            const scope = c.openScope();
            const actual = try c.checkBody(body, want);
            try c.closeScope(scope);
            if (want) |context| if (context.unit_test_success and actual == .unit) {
                try c.implicit_test_successes.put(gpa, body, context.ty);
            };
        }
    }
    z_bodies.end();

    try c.settleExternSymbols();

    try c.resolveAllOpen();

    const z_obligations = tracy.beginZone(@src(), "tc.obligations");
    // Before the implementations, so a bracket refused for its index is
    // reported beside the other things said about the body it sits in.
    if (c.index_decl) |index_trait| for (implementations) |implementation| {
        if (!implementation.isAmbient() and implementation.trait == index_trait.index())
            _ = try c.expansionOf(implementation.decl);
    };
    try c.checkProjectionCycles();
    try c.checkWriteCeilings();
    try c.checkProjectedIndexRanges();
    try c.checkEntryAnswer();
    try c.checkTestAnswers();

    // Last, because a body and an implementation both write types too, and a
    // bound reads an argument's capability: every instantiation the program
    // reaches exists by now, and every one of them has settled.
    try c.reportBrokenBounds();
    try c.checkPolyRec();
    try reportOversizedTypes(sink, program, &c.builder, 0);

    // The binding types pass to the caller rather than being freed: lowering
    // needs a parameter's type, and reading a declared one back out of its
    // annotation would ask a question about names that this pass answered.
    //
    // Handing the builder over last leaves nothing that can fail after the
    // guards above stop applying: every one of them frees something the
    // returned typing has taken.
    z_obligations.end();
    const calls = try c.calls.toOwnedSlice(gpa);
    errdefer {
        for (calls) |call| call.deinit(gpa);
        gpa.free(calls);
    }
    const recovered_call_args = try c.recovered_call_args.toOwnedSlice(gpa);
    errdefer gpa.free(recovered_call_args);
    const recovered_calls = try c.recovered_calls.toOwnedSlice(gpa);
    errdefer gpa.free(recovered_calls);
    const function_values = try c.function_values.toOwnedSlice(gpa);
    errdefer {
        for (function_values) |value| value.deinit(gpa);
        gpa.free(function_values);
    }

    // Handed on rather than freed: lowering asks the same question after
    // instantiation that a bound asked before it.
    const impls = try gpa.dupe(types_mod.Implementation, c.implementations);
    errdefer gpa.free(impls);

    // What a symbol calls each module. Built here because this is the pass
    // holding both the program and the pool a symbol is spelled from; a type
    // pool has no program to ask, and a second walk deriving it at each symbol
    // would be the same question answered twice.
    //
    // The module's import route, which the loader recorded: `std.text` is what
    // a reader imports, wherever the library's directory sits. Never a
    // directory: a directory is wherever the source happens to sit, so
    // spelling it would put a build path in every symbol -- two machines, or
    // two checkouts, compiling one program would emit different names, and the
    // cache keyed on emitted IR would answer for neither. So the root's route
    // is empty and a module below it contributes its own. A function's symbol
    // ends whichever route it has with `;`, so the root's `main` is `;main`.
    //
    // Before the pool is finished, so that nothing here can fail after there is
    // a pool to release: a `finish` that succeeded and an allocation that did
    // not is a whole type pool nobody owns.
    const module_paths = try gpa.alloc([]const u8, c.program.modules.len);
    var filled: usize = 0;
    errdefer {
        for (module_paths[0..filled]) |m| gpa.free(m);
        gpa.free(module_paths);
    }
    for (0..c.program.modules.len) |i| {
        const dotted = try gpa.dupe(u8, c.program.modulePath(ModuleId.from(i)));
        module_paths[i] = dotted;
        filled = i + 1;
    }

    const suppressed_generated_bodies = try c.suppressed_generated_bodies.toOwnedSlice(gpa);
    errdefer gpa.free(suppressed_generated_bodies);

    const postfix = try c.postfix.toOwnedSlice(gpa);
    errdefer {
        for (postfix) |p| gpa.free(p.args);
        gpa.free(postfix);
    }
    const named = try c.named.toOwnedSlice(gpa);
    errdefer gpa.free(named);
    const projected = try c.projected.toOwnedSlice(gpa);
    errdefer gpa.free(projected);
    const traversals = try c.traversals.toOwnedSlice(gpa);
    errdefer gpa.free(traversals);
    const expansions = try c.expansions.toOwnedSlice(gpa);
    errdefer {
        for (expansions) |row| {
            gpa.free(row.impl_args);
            if (row.delegation) |delegate| gpa.free(delegate.backing_args);
        }
        gpa.free(expansions);
    }
    const range_places = try c.range_places.toOwnedSlice(gpa);
    errdefer gpa.free(range_places);

    // The lists have settled and their row order cannot change. The index
    // stores positions, so finishing the type pool cannot invalidate it.
    var indexed = c.builder.view();
    indexed.calls = calls;
    indexed.recovered_call_args = recovered_call_args;
    indexed.recovered_calls = recovered_calls;
    indexed.function_values = function_values;
    indexed.postfix = postfix;
    indexed.projected = projected;
    indexed.traversals = traversals;
    indexed.range_places = range_places;
    var call_index = try types_mod.CallIndex.build(gpa, ast.exprCount(), &indexed);
    errdefer call_index.deinit(gpa);

    try c.reportDeferredUnused();
    try c.reportDeferredImmutable();
    try c.prepareValueQueries(prepare_completions);
    const constant_texts = try c.folded.takeTexts(gpa);
    errdefer {
        for (constant_texts) |bytes| gpa.free(bytes);
        gpa.free(constant_texts);
    }
    if (captured_seed) |seed| {
        const parameters = try gpa.alloc([]const TypeId, param_types.len);
        for (param_types, parameters) |row, *saved| saved.* = try gpa.dupe(TypeId, row);
        seed.* = .{
            .parameters = parameters,
            .declared_types = try gpa.dupe(TypeId, type_of_decl.entries),
            .expression_owners = try gpa.dupe(DeclId, c.expression_owners),
            .binding_owners = try gpa.dupe(DeclId, c.binding_owners),
            .declarations = try gpa.alloc(bool, ast.declCount()),
            .call_impls = try copyRetained(gpa, @as([]const types_mod.CallImpl, c.call_impls.items)),
        };
        @memset(@constCast(seed.declarations), true);
    }
    // The checker transfers its graph below; reopened builders clone borrowed graphs.
    c.builder.constant_pool = &.{};
    var typing = try c.builder.finish(c.binding_types);
    typing.observation_traits = observation_traits;
    typing.literal_values = c.literal_values;
    c.literal_values = .empty;
    typing.integer_properties = c.integer_properties;
    c.integer_properties = .empty;
    typing.conversion_targets = c.conversion_targets;
    c.conversion_targets = .empty;
    typing.implicit_test_successes = c.implicit_test_successes;
    c.implicit_test_successes = .empty;
    typing.try_conversions = c.try_conversions;
    c.try_conversions = .empty;
    typing.place_projections = c.place_projections;
    c.place_projections = .empty;
    typing.field_names = c.field_names;
    c.field_names = .empty;
    typing.type_selections = c.type_selections;
    c.type_selections = .empty;
    typing.contract_variants = c.contract_variants;
    c.contract_variants = .empty;
    typing.readonly_places = c.readonly_places;
    c.readonly_places = .empty;
    typing.carried_places = c.carried_places;
    c.carried_places = .empty;
    typing.borrowed_temporaries = c.borrowed_temporaries;
    c.borrowed_temporaries = .empty;
    typing.interpolation_positions = c.interpolation_positions;
    c.interpolation_positions = .empty;
    typing.refused = c.refused;
    c.refused = .empty;
    typing.folded_indices = c.folded_indices;
    c.folded_indices = .empty;
    typing.selected_places = c.selected_places;
    c.selected_places = .empty;
    typing.module_paths = module_paths;
    typing.closures = c.closure_descriptors;
    c.closure_descriptors = &.{};
    typing.call_index = call_index;
    typing.calls = calls;
    typing.recovered_call_args = recovered_call_args;
    typing.recovered_calls = recovered_calls;
    typing.function_values = function_values;
    typing.decl_signatures = c.decl_signatures;
    typing.raw_accesses = c.raw_accesses.withCheckedScalars(program, ast, &typing);
    typing.float_math = c.float_math;
    c.decl_signatures = .empty;
    typing.implementations = impls;
    // Handed over with the list it indexes, because it is a way to reach an
    // entry of that list and means nothing beside another.
    typing.impl_index = c.impl_index;
    c.impl_index = .{};
    // Built from the pairs the walk settled, which is the one place the
    // relation is computed. Lowering and a rename each read it rather than
    // matching a member to a signature by the name they share -- as this pass
    // itself does, for a settled reference and for the checks below the
    // pairing.
    typing.supply_index = c.supply;
    c.supply = .{};
    // Handed on rather than freed, beside the list it indexes: lowering names
    // a member's symbol by the implementation it sits in, and asking that
    // again there is the same walk over every region a second time.
    typing.impl_of_decl = impl_of_decl;
    typing.suppressed_generated_bodies = suppressed_generated_bodies;
    typing.postfix = postfix;
    typing.named = named;
    typing.contract_parameters = c.contract_parameters;
    c.contract_parameters = .empty;
    typing.binding_labels = c.binding_labels;
    c.binding_labels = .empty;
    typing.declined_contracts = c.declined_contracts;
    c.declined_contracts = .empty;
    typing.adopted_contracts = c.adopted_contracts;
    c.adopted_contracts = .empty;
    typing.defaulted_contracts = c.defaulted_contracts;
    c.defaulted_contracts = .empty;
    typing.aliased = c.alias_types;
    c.alias_types = .empty;
    // Handed on rather than freed: a bracket that routes is the path its
    // implementation names, and lowering emits that path rather than deciding a
    // second time which implementation the bracket reached.
    typing.projected = projected;
    // And for the same reason: a lending walk runs through the traversal the
    // checker found, whose positions it held to the projection's index.
    typing.traversals = traversals;
    typing.expansions = expansions;
    typing.expansion_of_impl = c.expansion_of_impl;
    c.expansion_of_impl = .empty;
    typing.extern_symbols = c.extern_symbols;
    c.extern_symbols = .empty;
    typing.traversal_positions = c.traversal_positions;
    c.traversal_positions = .empty;
    // Handed on for the reason the expansions are: where a range place begins
    // was settled here, and lowering emits that rather than settling it again.
    typing.range_places = range_places;
    // Handed over rather than freed: what a default is worth is what lowering
    // splices into every call that omits the parameter.
    typing.defaults = c.defaults;
    c.defaults = .{};
    // Handed on rather than freed: what a written type settled to is the
    // checker's answer, and every renderer below here was working it out again.
    typing.written_types = c.written_types;
    typing.variant_uses = c.variant_uses;
    c.variant_uses = .empty;

    // What the caret settles to, for the reader that has to interpret one: the
    // checker decided which declaration it is, so lowering reads the decision
    // rather than making it again.
    typing.from_end = c.fromEndType() orelse .poison;

    typing.decl_returns = c.decl_returns;
    typing.declared_requirements = c.declared_requirements;
    typing.declared_traits = c.declared_traits;
    typing.declared_callables = c.declared_callables;
    typing.contextual_constraints = c.contextual_constraints;
    c.contextual_constraints = .{};
    typing.field_name_spellings = c.field_name_spellings;
    c.field_name_spellings = .empty;
    typing.constant_texts = constant_texts;
    typing.constant_pool = c.folded.pool;
    c.folded.pool = .{};
    typing.constant_materializations = c.constant_materializations;
    c.constant_materializations = .empty;
    typing.constant_values = c.constant_values;
    c.constant_values = .empty;
    try c.writeWalkHelps(&typing);
    return typing;
}

/// The trait declaration a written trait name means, read where it was written.
///
/// A name is unique only within a module -- two modules each declaring a
/// `Measure` is most of what a module is for -- so a trait is a declaration and
/// never its spelling. Matched by text, one module's implementations answered
/// for another's trait, and a call reached a body written against a trait it
/// never named.
///
/// Which declaration a name reaches is the resolver's question, and it answered
/// it for every name a module can write: its own, what it imported, what was
/// re-exported to it, and what the prelude gave it. Asking again here missed
/// every route but the first two.
fn traitAt(
    ast: *const Ast,
    res: *const Resolution,
    tok: TokenId,
) ?node.DeclId {
    if (tok == TokenId.none) return null;
    if (ast.tokenTag(tok) != .identifier) return null;
    const binding = res.writtenAt(tok);
    if (binding != .none and res.kindOf(binding) == .trait) return res.declaredBy(binding);
    return res.traitNamed(res.moduleOfFile(ast.fileOf(tok)), ast.tokenName(tok));
}
/// The strongest capability required by the written bounds and their shared
/// transitive trait closure. An unrestricted parameter promises neither
/// duplication nor omission of settlement.
///
/// Reads the supplied closure once; trait traversal belongs to traitsBounding.
fn capabilityDemandedBy(
    ast: *const Ast,
    res: *const Resolution,
    bounds: []const node.TraitBound,
    through: []const types_mod.BoundTrait,
) node.CapabilityRequirement {
    return capabilityDemand(ast, res, bounds, through).requirement;
}

/// Every place one run of bounds demanded a single capability from.
const Demanded = struct {
    /// The first bound on the list naming it, `.none` where none does.
    written: TokenId = .none,
    /// The second such bound, for a list naming it more than once.
    again: TokenId = .none,
    /// The first trait the list reaches whose own bounds name it, `.none`
    /// where none does.
    through: node.DeclId = node.DeclId.none,

    fn demanded(self: Demanded) bool {
        return self.written != .none or self.through != node.DeclId.none;
    }

    /// Whether a bound the list wrote asks for what the list already asks for.
    /// A capability reached through two traits is not this: neither of those
    /// bounds is a capability, so dropping either drops the operations it names.
    fn restated(self: Demanded) bool {
        return self.written != .none and
            (self.again != .none or self.through != node.DeclId.none);
    }
};

/// What a run of bounds demands of whatever stands against it, and where each
/// demand came from.
const Demand = struct {
    requirement: node.CapabilityRequirement,
    copyable: Demanded,
    discardable: Demanded,
    unrestricted: Demanded,
};
/// The strongest capability requirement and the written or inherited sources
/// of each requirement. Redundant combinations are diagnosed by the caller.
fn capabilityDemand(
    ast: *const Ast,
    res: *const Resolution,
    bounds: []const node.TraitBound,
    through: []const types_mod.BoundTrait,
) Demand {
    var copyable: Demanded = .{};
    var unrestricted: Demanded = .{};
    var discardable: Demanded = .{};

    for (bounds) |b| {
        if (b.kind == .callable) continue;
        const source: *Demanded = switch (resolve_mod.boundNames(ast, b.named.name, traitAt(ast, res, b.named.name))) {
            .capability => |u| switch (u) {
                .copyable => &copyable,
                .discardable => &discardable,
                .unrestricted => &unrestricted,
            },
            .trait, .integer, .owned, .unknown => continue,
        };
        if (source.written == .none) {
            source.written = b.named.name;
        } else if (source.again == .none) {
            source.again = b.named.name;
        }
    }

    // Each trait's own bounds and no deeper: what those reach is in `through`
    // already, so one step over every entry is the whole closure.
    for (through) |t| {
        const trait = node.DeclId.at(t.trait);
        for (ast.declBounds(trait)) |b| {
            if (b.kind == .callable) continue;
            const source: *Demanded = switch (resolve_mod.boundNames(ast, b.named.name, traitAt(ast, res, b.named.name))) {
                .capability => |u| switch (u) {
                    .copyable => &copyable,
                    .discardable => &discardable,
                    .unrestricted => &unrestricted,
                },
                .trait, .integer, .owned, .unknown => continue,
            };
            if (source.through == node.DeclId.none) source.through = trait;
        }
    }

    return .{
        .requirement = if (copyable.demanded() or integerDemandedBy(ast, res, bounds, through)) .copyable else if (discardable.demanded()) .discardable else .unrestricted,
        .copyable = copyable,
        .discardable = discardable,
        .unrestricted = unrestricted,
    };
}

/// Integer membership is independent of the ownership capability lattice.
/// The trait closure is supplied by traitsBounding, so this reads each bound once.
fn integerDemandedBy(ast: *const Ast, res: *const Resolution, bounds: []const node.TraitBound, through: []const types_mod.BoundTrait) bool {
    for (bounds) |bound| {
        if (bound.kind == .named and resolve_mod.boundNames(ast, bound.named.name, traitAt(ast, res, bound.named.name)) == .integer) return true;
    }
    for (through) |required| {
        for (ast.declBounds(node.DeclId.at(required.trait))) |bound| {
            if (bound.kind == .named and resolve_mod.boundNames(ast, bound.named.name, traitAt(ast, res, bound.named.name)) == .integer) return true;
        }
    }
    return false;
}

/// The bound in a run that demands a capability: the first that names
/// `Copyable`, `Discardable` or `Linear`, or else the first named bound, a
/// trait that requires the capability. Null where the run names nothing.
fn capabilityToken(ast: *const Ast, res: *const Resolution, bounds: []const node.TraitBound) ?TokenId {
    var first: ?TokenId = null;
    for (bounds) |bound| {
        if (bound.kind != .named) continue;
        if (first == null) first = bound.named.name;
        switch (resolve_mod.boundNames(ast, bound.named.name, traitAt(ast, res, bound.named.name))) {
            .capability => return bound.named.name,
            else => {},
        }
    }
    return first;
}

/// The first bound in a run that names `Owned`. Only the run itself is read:
/// a trait cannot require `Owned`, so no trait it reaches adds the demand.
fn ownedBound(ast: *const Ast, res: *const Resolution, bounds: []const node.TraitBound) ?TokenId {
    for (bounds) |bound| {
        if (bound.kind == .named and resolve_mod.boundNames(ast, bound.named.name, traitAt(ast, res, bound.named.name)) == .owned) return bound.named.name;
    }
    return null;
}

/// A written type spelled as the program wrote it, appended to `out`.
///
/// For a message about a bound, whose arguments are written types and not
/// interned ones: nothing has settled them where a signature and a member are
/// compared, so the spelling comes from the tree rather than from the pool.
/// One walk for every form, so a message never names a construction the
/// grammar has no place for.
fn spellWritten(
    gpa: std.mem.Allocator,
    ast: *const Ast,
    out: *std.ArrayList(u8),
    ref: node.TypeRef,
) std.mem.Allocator.Error!void {
    switch (ref.kind) {
        .grouped => {
            try out.append(gpa, '(');
            for (ast.typeArgs(ref.args)) |argument| try spellWritten(gpa, ast, out, argument);
            try out.append(gpa, ')');
            return;
        },
        .borrow => {
            try out.appendSlice(gpa, "borrow ");
            for (ast.typeArgs(ref.args)) |argument| try spellWritten(gpa, ast, out, argument);
            return;
        },
        .tuple => {
            try out.append(gpa, '(');
            for (ast.typeArgs(ref.args), 0..) |component, i| {
                if (i > 0) try out.appendSlice(gpa, ", ");
                try spellWritten(gpa, ast, out, component);
            }
            try out.append(gpa, ')');
            return;
        },
        .named => try out.appendSlice(gpa, ast.tokenText(ref.name)),
        .selection => {
            try spellWritten(gpa, ast, out, ast.selectionBase(ref));
            try out.append(gpa, '.');
            try out.appendSlice(gpa, ast.tokenText(ref.name));
        },
        .array => {
            try out.append(gpa, '[');
            for (ast.typeArgs(ref.args)) |a| try spellWritten(gpa, ast, out, a);
            try out.appendSlice(gpa, "; ");
            try out.appendSlice(gpa, ast.arrayLengthText(ref));
            try out.append(gpa, ']');
            return;
        },
        .callable => {
            const callable = ast.callableType(ref);
            if (callable.invocation != .read) {
                try out.appendSlice(gpa, @tagName(callable.invocation));
                try out.append(gpa, ' ');
            }
            try out.appendSlice(gpa, "fn(");
            for (ast.params[callable.params.start..callable.params.end], 0..) |param, i| {
                if (i > 0) try out.appendSlice(gpa, ", ");
                try out.appendSlice(gpa, @tagName(param.convention));
                try out.append(gpa, ' ');
                try out.appendSlice(gpa, ast.tokenText(param.name));
                try out.appendSlice(gpa, ": ");
                try spellWritten(gpa, ast, out, param.written);
                if (param.default != ExprId.none) {
                    try out.appendSlice(gpa, " = ");
                    try out.appendSlice(gpa, ast.exprText(param.default));
                }
            }
            try out.append(gpa, ')');
            if (callable.result.wasWritten()) {
                try out.appendSlice(gpa, " -> ");
                try spellWritten(gpa, ast, out, callable.result);
            }
            return;
        },
    }
    if (ref.args.len() == 0) return;
    try out.append(gpa, '[');
    for (ast.typeArgs(ref.args), 0..) |a, i| {
        if (i > 0) try out.appendSlice(gpa, ", ");
        try spellWritten(gpa, ast, out, a);
    }
    try out.append(gpa, ']');
}

/// A bound spelled as the program wrote it: the name, applied to its arguments
/// where it has any. The caller owns the slice.
fn spellBound(
    gpa: std.mem.Allocator,
    ast: *const Ast,
    bound: node.TraitBound,
) std.mem.Allocator.Error![]const u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(gpa);
    switch (bound.kind) {
        .named => {
            if (bound.named.path.len() == 0) {
                try out.appendSlice(gpa, ast.tokenText(bound.named.name));
            } else {
                var names = ast.namesOf(bound.named.path);
                var first = true;
                while (names.next()) |name| {
                    if (!first) try out.append(gpa, '.');
                    first = false;
                    try out.appendSlice(gpa, ast.tokenText(name));
                }
            }
            if (bound.named.args.len() != 0) {
                try out.append(gpa, '[');
                for (ast.typeArgs(bound.named.args), 0..) |argument, index| {
                    if (index != 0) try out.appendSlice(gpa, ", ");
                    try spellWritten(gpa, ast, &out, argument);
                }
                try out.append(gpa, ']');
            }
        },
        .callable => try spellWritten(gpa, ast, &out, ast.callableRef(bound.callable)),
    }
    return out.toOwnedSlice(gpa);
}

fn spellWrittenOwned(
    gpa: std.mem.Allocator,
    ast: *const Ast,
    ref: node.TypeRef,
) std.mem.Allocator.Error![]const u8 {
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(gpa);
    try spellWritten(gpa, ast, &out, ref);
    return out.toOwnedSlice(gpa);
}

/// Reports a trait operation named as a value at a type that answers it only
/// through an observation of itself, so no body takes the value as it is.
///
/// Two askers and one sentence: the checker asks where `Self` is concrete, and
/// instantiation asks where the value's `Self` was a parameter until then.
pub fn reportBodilessOperation(sink: *Sink, file: FileId, span: Span, operation: []const u8, held: []const u8) std.mem.Allocator.Error!void {
    try sink.addErrorFmt(
        .n_not_a_value,
        file,
        span,
        "call it, or wrap the call in a function or a lambda",
        "`{s}` for `{s}` has no body of its own to be a value",
        .{ operation, held },
    );
}

test "a body-less operation is reported with the type it was reached at" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    var sink = Sink.init(arena.allocator());
    try reportBodilessOperation(&sink, .from(0), .{ .start = 0, .end = 1 }, "equals", "[UInt8; 3]");
    try testing.expectEqual(Code.n_not_a_value, sink.items()[0].code.?);
    try testing.expectEqualStrings("`equals` for `[UInt8; 3]` has no body of its own to be a value", sink.items()[0].message);
}

/// What an instance of a body written in `decl` binds besides `decl`'s own
/// type parameters: the implementation enclosing it, or for a trait's
/// provided operation the trait and the operation's symbolic `Self`. One
/// routine for the checker minting a closure's type, discovery and lowering,
/// so a closure's environment, its signature and its body are read under one
/// substitution, and the one its enclosing body is.
pub fn bodyParametersOf(ast: *const Ast, res: *const Resolution, typing: *const Typing, decl: node.DeclId) types_mod.BodyParameters {
    if (decl == node.DeclId.none) return .{};
    if (ast.declIsProvided(decl)) return .{ .owner = res.signatures.traitOf(ast, decl) orelse node.DeclId.none, .provided = true };
    return .{ .owner = if (typing.implementationOf(decl)) |enclosing| enclosing.decl else node.DeclId.none };
}

test "bodyParametersOf names what an instance binds besides the body's own parameters" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "t.lin", .text =
        \\trait Scaled {
        \\    fn factor(self: Self) -> UInt8
        \\    fn doubled(self: Self) -> UInt8 { self.factor() * 2 }
        \\}
        \\struct Crate { weight: UInt8 }
        \\impl Scaled for Crate {
        \\    fn factor(self: Self) -> UInt8 { self.weight }
        \\}
        \\fn main() -> UInt8 { Crate { weight = 2 }.doubled() }
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const res = try resolveTree(gpa, &ast, &sink);
    const typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    const tree = &res.expanded.ast;

    var trait: node.DeclId = .none;
    var implementation: node.DeclId = .none;
    var provided: node.DeclId = .none;
    var member: node.DeclId = .none;
    var main: node.DeclId = .none;
    for (0..tree.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        const name = tree.tokenText(tree.declName(d));
        if (std.mem.eql(u8, name, "Scaled")) trait = d;
        if (std.mem.eql(u8, name, "doubled")) provided = d;
        if (std.mem.eql(u8, name, "main")) main = d;
        if (std.mem.eql(u8, name, "factor") and !tree.declIsSignature(d)) member = d;
        if (typing.implementationOf(d)) |enclosing| implementation = enclosing.decl;
    }

    const at_provided = bodyParametersOf(tree, &res.resolution, &typing, provided);
    try testing.expectEqual(trait, at_provided.owner);
    try testing.expect(at_provided.provided);
    const at_member = bodyParametersOf(tree, &res.resolution, &typing, member);
    try testing.expectEqual(implementation, at_member.owner);
    try testing.expect(!at_member.provided);
    const at_main = bodyParametersOf(tree, &res.resolution, &typing, main);
    try testing.expectEqual(node.DeclId.none, at_main.owner);
    try testing.expect(!at_main.provided);
    try testing.expectEqual(node.DeclId.none, bodyParametersOf(tree, &res.resolution, &typing, node.DeclId.none).owner);
}

/// Reports a key that names no implementation: the trait with the arguments
/// settled for its parameters, and the type asked about.
///
/// Two askers and one sentence. A call settles the trait's arguments, and where
/// every part of the key is a type this pass asks; where a part of it is a
/// parameter there is nothing to ask until the instantiation supplies one, and
/// instantiation asks then -- a bound promises the type answers the trait, which is
/// not a promise about which of its implementations a call reaches. The same
/// mistake at two times, so one message rather than two that drift.
pub fn reportMissingImplementation(
    gpa: std.mem.Allocator,
    sink: *Sink,
    ast: *const Ast,
    pool: *const Typing.Builder,
    trait: node.DeclId,
    args: []const TypeId,
    held: TypeId,
    file: FileId,
    span: Span,
    /// The edit the label offers, which only the checker can name; an
    /// instantiation passes `missing_at_instantiation`.
    help: []const u8,
) std.mem.Allocator.Error!void {
    // Spelled as the program spells it, through the one routine that applies a
    // name to arguments -- which for a trait taking none is the name alone.
    const written = try pool.spellInstance(ast.tokenText(ast.declName(trait)), args);
    defer gpa.free(written);

    try sink.addErrorFmt(
        .t_bound,
        file,
        span,
        help,
        "`{s}` does not implement `{s}`",
        .{ pool.nameOf(held), written },
    );
}

/// The label of a missing implementation found while instantiating, where
/// the program's modules are not at hand to say which edit it may make.
pub const missing_at_instantiation = "no implementation answers for these arguments";

/// Whether a type implements a trait at all, whatever the arguments.
///
/// What a bound asks, and it is a different question from which body a call
/// runs: `T: Holds` promises the type answers the trait, and which of its
/// implementations a call reaches is settled by the call. A bound is also
/// asked before a call has settled anything, so an answer keyed on the
/// arguments would have none to be keyed on.
pub fn implementsAnyOf(
    gpa: std.mem.Allocator,
    index: *const types_mod.ImplIndex,
    impls: []const types_mod.Implementation,
    pool: anytype,
    trait: node.DeclId,
    held: TypeId,
) std.mem.Allocator.Error!bool {
    if (trait == node.DeclId.none) return false;
    return index.any(gpa, impls, pool, trait.index(), held, .none, .forward);
}

/// Whether a written type name names the type a value holds.
///
/// Two readings, and the first wins where it applies: the declaration the name
/// reaches against the declaration the type came from, which is what makes
/// `Cell` name `Cell[UInt8]`. Where either is missing there is no declaration
/// to compare, so the spelling decides -- against the pool's name and then
/// against the name of the declaration an instantiation was made from.
///
/// The two declarations are the caller's to supply, because a caller asking
/// about many written names for one type works the second out once, and a
/// caller asking about one written name has a cheaper route to the first.
pub fn namesTheType(
    ast: *const Ast,
    typing: *const Typing,
    written: TokenId,
    held: TypeId,
    /// The declaration the written name reaches, or null where it names none.
    named: ?node.DeclId,
    /// The declaration `held` came from, or null where it came from none.
    came_from: ?node.DeclId,
) bool {
    if (named) |reaches| {
        if (came_from) |origin| return origin == reaches;
    }

    const text = ast.tokenText(written);
    if (std.mem.eql(u8, text, typing.nameOf(held))) return true;
    const origin = typing.instanceOf(held) orelse return false;
    const d = origin.decl;
    return std.mem.eql(u8, text, ast.tokenText(ast.declName(d)));
}

/// Whether a trait's member is one `kind` of enumeration is after: a
/// signature a postfix call passes the receiver to, an associated type, or
/// any operation, which a call written after a type's name reaches.
fn memberSought(ast: *const Ast, member: node.DeclId, kind: Reach.MemberSought) bool {
    return switch (kind) {
        .operation => ast.declIsSignature(member) and postfixReaches(ast, member),
        .associated => settlesAType(ast, member),
        .namespaced => ast.declIsSignature(member) and ast.declTag(member) == .function,
    };
}

/// Whether the postfix form reaches a signature a trait declares.
///
/// The first parameter is what the receiver becomes, so an operation that does
/// not take `Self` there is not one this form reaches -- `Account.label(6)`
/// stays what it is.
///
/// Costs the declaration's own parameters. Which signatures a trait declares is
/// the resolver's recording, so this decides one signature and never searches
/// for them.
fn postfixReaches(ast: *const Ast, sig: node.DeclId) bool {
    const params = ast.declParams(sig);
    if (params.len == 0) return false;
    return refNamesSelf(ast, params[0].written);
}

/// Whether a parameter reads `Self`: written `Self` under the `read`
/// convention. Such a parameter takes the value an observation reads as well
/// as the value itself; every other parameter takes exactly what is passed.
fn readsSelf(ast: *const Ast, parameter: node.Param) bool {
    const written = ast.withoutTypeGroups(parameter.written);
    return parameter.convention == .read and written.kind == .named and resolve_mod.namesSelf(ast, written.name);
}

/// The observations a call looks through to pass `got` to `parameter`: none
/// where `got` fits as it is, otherwise one per `borrow` a parameter reading
/// `Self` reads through until what is left fits, and null where nothing
/// fits. `fits` holds a candidate to the parameter's type, because a checked
/// call compares two settled types while an enumeration holds a block's
/// open parameters to the receiver.
///
/// One routine for the call that accepts a receiver and the lookup that says
/// which operations a receiver reaches, so the dot reaches exactly what the
/// call then takes.
fn observationsPassing(pool: anytype, ast: *const Ast, parameter: node.Param, got: TypeId, fits: anytype) ?u32 {
    var layers: u32 = 0;
    var left = got;
    while (true) {
        if (fits.fits(left)) return layers;
        if (!readsSelf(ast, parameter)) return null;
        left = switch (pool.get(left)) {
            .borrow => |observation| observation.referent,
            else => return null,
        };
        layers += 1;
    }
}

/// Whether this type is an interpolation and this trait is the one that
/// renders. An interpolation answers `Display` without an implementation
/// written anywhere: the pieces are in the type, and lowering walks them.
///
/// Asked instead of a table entry, because the table is built before any body
/// is walked and these types are minted while one is. An entry added
/// afterwards would be invisible to the very call that needed it.
///
/// One predicate and two askers: the checker admits such a call, and lowering
/// intercepts the ones it admitted. A lowering that asked only about the type
/// would intercept a call through a second trait the checker never blessed.
pub fn rendersDisplayItself(
    typing: *const Typing,
    display: ?node.DeclId,
    held: TypeId,
    trait: node.DeclId,
) bool {
    if (trait != (display orelse return false)) return false;
    return typing.isInterpolation(held);
}

/// Which declaration `Display` is, for whoever needs to recognise it.
///
/// The prelude is what a program's names resolve against, so this is the one
/// thing that decides it -- and the checker, which admits an interpolation,
/// and lowering, which renders one, have to mean the same declaration.
pub fn displayDecl(ast: *const Ast, res: *const Resolution) ?node.DeclId {
    return preludeDecl(ast, res, "Display");
}

pub fn debugDecl(ast: *const Ast, res: *const Resolution) ?node.DeclId {
    return preludeDecl(ast, res, "Debug");
}

pub const FormattingTarget = struct {
    trait: ?node.DeclId,
    member: ?node.DeclId,
};

/// The declarations interpolation syntax selects, settled once from the
/// prelude and shared by checking, instantiation discovery and lowering.
pub const FormattingDecls = struct {
    display: FormattingTarget,
    debug: FormattingTarget,

    pub fn init(ast: *const Ast, res: *const Resolution) FormattingDecls {
        const display = displayDecl(ast, res);
        const debug = debugDecl(ast, res);
        return .{
            .display = .{ .trait = display, .member = traitMemberNamed(ast, res, display, "fmt") },
            .debug = .{ .trait = debug, .member = traitMemberNamed(ast, res, debug, "debug") },
        };
    }

    pub fn target(self: FormattingDecls, format: node.InterpolationFormat) FormattingTarget {
        return if (format.debug) self.debug else self.display;
    }
};

/// Which declaration `Equatable` is, for whoever needs to recognise it.
///
/// The prelude is what a program's names resolve against, so this is the one
/// thing that decides it -- and the checker, which demands the trait an
/// operator needs, and lowering, which reaches its implementation, have to
/// mean the same declaration.
pub fn equatableDecl(ast: *const Ast, res: *const Resolution) ?node.DeclId {
    return preludeDecl(ast, res, "Equatable");
}

/// Which declaration `Comparable` is, on the same terms as `equatableDecl`.
pub fn comparableDecl(ast: *const Ast, res: *const Resolution) ?node.DeclId {
    return preludeDecl(ast, res, "Comparable");
}

/// Which declaration `Steppable` is, on the same terms as `equatableDecl`.
pub fn steppableDecl(ast: *const Ast, res: *const Resolution) ?node.DeclId {
    return preludeDecl(ast, res, "Steppable");
}

/// Which declaration `Sequence` is, on the same terms as `equatableDecl`: the
/// checker demands it of what a `for` walks, and lowering calls the
/// implementation it found, so the two name one declaration.
pub fn sequenceDecl(ast: *const Ast, res: *const Resolution) ?node.DeclId {
    return preludeDecl(ast, res, "Sequence");
}

/// Which declaration `Iterator` is, on the same terms as `sequenceDecl`.
pub fn iteratorDecl(ast: *const Ast, res: *const Resolution) ?node.DeclId {
    return preludeDecl(ast, res, "Iterator");
}

/// Which declaration is the library's `std.convert.From`, the trait `?`
/// converts a different error through. A program's own trait of that name is
/// a different declaration. Null where no library is loaded.
pub fn fromDecl(program: *const ExpandedProgram) ?node.DeclId {
    return program.libraryDeclIn("convert", "From");
}

/// The library's `Settle`, which `Result.settled()` reduces a failure through.
pub fn settleDecl(program: *const ExpandedProgram) ?node.DeclId {
    return program.libraryDeclIn("release", "Settle");
}

/// The signature or associated type a trait declares under this name, or null
/// where it declares none and where no trait was named at all.
///
/// Read from the resolver's index of what each trait declares, which is what
/// every other reader of a trait's members asks. Written here rather than at
/// the caller so that the operator's `less` and the one an implementation
/// supplies are the same declaration.
///
/// **Bound:** the members of the one trait, however many declarations the
/// program holds, so asking it once per comparison or loop costs nothing that
/// grows with the program.
pub fn traitMemberNamed(ast: *const Ast, res: *const Resolution, trait: ?node.DeclId, name: []const u8) ?node.DeclId {
    const declared = trait orelse return null;
    var signatures = res.signatures.of(ast, declared);
    while (signatures.next()) |d| {
        if (std.mem.eql(u8, ast.tokenText(ast.declName(d)), name)) return d;
    }
    var types = res.signatures.typesOf(ast, declared);
    while (types.next()) |d| {
        if (std.mem.eql(u8, ast.tokenText(ast.declName(d)), name)) return d;
    }
    return null;
}

/// Which of two operations was written first. Declaration order is what a
/// walk of the declarations produced, and it is the order `[N-Ambiguous]`
/// reads the first two entries under one name in.
fn writtenBefore(_: void, a: Applicable, b: Applicable) bool {
    return a.sig.index() < b.sig.index();
}

/// The position of the row `collectImplementations` recorded for an
/// implementation, or null where it recorded none -- a head naming nothing,
/// which is reported where it is written.
///
/// Searched rather than walked: the rows are in declaration order because
/// the declarations are read in order, and the rows the compiler provides
/// carry no declaration and sort after every written one. One routine for the
/// checker holding an `impl` and for a lookup holding a member of one, so
/// both find the same row.
///
/// **Bound:** the log of the implementations.
pub fn implementationRowIndex(impls: []const types_mod.Implementation, impl: node.DeclId) ?usize {
    if (impl == node.DeclId.none) return null;
    var lo: usize = 0;
    var hi: usize = impls.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (impls[mid].decl.index() < impl.index()) lo = mid + 1 else hi = mid;
    }
    if (lo < impls.len and impls[lo].decl.index() == impl.index()) return lo;
    return null;
}

test "an implementation's row is found by its declaration" {
    const row = struct {
        fn of(decl: node.DeclId) types_mod.Implementation {
            return .{ .trait = types_mod.Implementation.no_trait, .head = .array, .ty = .poison, .decl = decl };
        }
    };
    const impls = [_]types_mod.Implementation{ row.of(node.DeclId.at(2)), row.of(node.DeclId.at(5)), row.of(node.DeclId.at(9)), row.of(node.DeclId.none) };
    try std.testing.expectEqual(@as(?usize, 0), implementationRowIndex(&impls, node.DeclId.at(2)));
    try std.testing.expectEqual(@as(?usize, 1), implementationRowIndex(&impls, node.DeclId.at(5)));
    try std.testing.expectEqual(@as(?usize, 2), implementationRowIndex(&impls, node.DeclId.at(9)));
    try std.testing.expectEqual(@as(?usize, null), implementationRowIndex(&impls, node.DeclId.at(4)));
    try std.testing.expectEqual(@as(?usize, null), implementationRowIndex(&impls, node.DeclId.at(12)));
    try std.testing.expectEqual(@as(?usize, null), implementationRowIndex(&impls, node.DeclId.none));
    try std.testing.expectEqual(@as(?usize, null), implementationRowIndex(&.{}, node.DeclId.at(2)));
}

/// One operation the postfix form could reach on a receiver.
pub const Applicable = struct {
    /// What the call would run: an inherent member, or the signature a trait
    /// declares.
    sig: node.DeclId,
    /// The trait that declares it, and `.none` where the type declares it
    /// itself.
    trait: node.DeclId,
};

/// An [O-LinearWalk] report whose help is written once checking has ended:
/// where it sits in the sink, the loop, what it walked, the iterator that
/// walk abandons, and the declaration the loop is in.
const WalkHelp = struct { report: usize, loop: ExprId, walked: TypeId, iter: TypeId, owner: node.DeclId };

/// Whether a declaration states bounds of its own, beyond those of the block
/// that encloses it. Nothing decides such bounds for a receiver a report asks
/// about, so an operation stating them is never named as settling one.
fn declaresOwnBounds(constraints: *const Constraints, d: node.DeclId) bool {
    for (constraints.ofDeclaration(d)) |constraint| {
        if (constraints.requirementsOf(constraint).len != 0) return true;
    }
    return false;
}

/// Which operations settle a value of a type: the ones a postfix call written
/// in `owner`'s module reaches that take the value by `sink`, leave a result
/// owing nothing, and are not `owner` itself.
///
/// One routine, because two reports name them: a leak ([O-Leak]) and a walk
/// that would abandon a linear iterator ([O-LinearWalk]). Two readings of it
/// told a reader to settle a value with an operation that did not.
///
/// For a member of an implementation, whether the result owes is the
/// checker's answer for the type in `owner`, with its block arguments
/// substituted: `Builder.prepareSettlingResult` records it, only where the
/// block applies and the operation states no bounds of its own, so an
/// operation it decided nothing for is not named. For a trait's own
/// signature it is the result the member supplying it writes, in the
/// implementation a call selects for the type, which
/// `Builder.prepareTraitSettlingResult` records: the blanket
/// `impl[I: Iterator] Sequence for I` answers `iterate` with the iterator
/// itself, so calling it leaves the caller holding what it held. Where no
/// implementation's member was decided, the signature's result is asked about
/// under the trait's bounds. An operation stating bounds of its own is left
/// undecided either way, which reads as owing: nothing here checks those bounds
/// for the type, and `for_each`'s `Self.Iter: Discardable` is one a linear
/// iterator fails.
pub const Settlers = struct {
    ast: *const Ast,
    res: *const Resolution,
    typing: *const Typing,
    reach: Reach,
    owner: node.DeclId,

    /// Fills `out` with up to its length of the operations that settle a
    /// value of `t`, in the order `Reach.each` yields them: the type's own
    /// first, then the traits'. How many were found, up to `out.len`.
    ///
    /// Costs `Reach.each` over one type -- its own operations and the traits
    /// the module can see -- and a comparison of names among those.
    pub fn operations(self: Settlers, gpa: std.mem.Allocator, t: TypeId, out: []node.DeclId) std.mem.Allocator.Error!usize {
        var applicable: std.ArrayList(Applicable) = .empty;
        defer applicable.deinit(gpa);
        try self.reach.each(gpa, t, &applicable);
        var found: usize = 0;
        for (applicable.items) |a| {
            if (found == out.len) break;
            const name = self.ast.tokenName(self.ast.declName(a.sig));
            var runs: NameReach = .{};
            for (applicable.items) |other| {
                if (self.ast.tokenName(self.ast.declName(other.sig)) == name) runs.note(other);
            }
            if (!runs.reaches(a)) continue;
            if (!self.settles(t, a.sig)) continue;
            out[found] = a.sig;
            found += 1;
        }
        return found;
    }

    /// Whether the operation `sig`, declared by a trait or by the type
    /// itself, settles a value of `t`.
    pub fn settles(self: Settlers, t: TypeId, sig: node.DeclId) bool {
        const params = self.ast.declParams(sig);
        if (params.len == 0 or params[0].convention != .sink) return false;
        const recorded = self.typing.settlingResultOwes(self.owner, t, sig);
        const result_owes = recorded orelse if (self.typing.implementationIdOf(sig) != null or declaresOwnBounds(&self.res.constraints, sig))
            true
        else
            self.typing.mustConsumeWithin(self.typing.contextual_constraints.parentOf(sig), self.typing.declReturn(sig));
        if (result_owes) return false;
        if (self.res.implEnclosing(self.owner) != .none and
            self.ast.tokenName(self.ast.declName(sig)) == self.ast.tokenName(self.ast.declName(self.owner))) return false;
        return true;
    }

    /// An operation of `t`'s own that consumes it and answers
    /// `Result[R, Self]` with a discardable `R`, such as `Vec.finish`: it
    /// settles the value or hands the same value back as `Err`. The first of
    /// them a postfix call reaches, or null. Costs `Reach.each` over one type.
    pub fn handingBack(self: Settlers, gpa: std.mem.Allocator, t: TypeId) std.mem.Allocator.Error!?node.DeclId {
        const result_decl = preludeDecl(self.ast, self.res, "Result") orelse return null;
        var applicable: std.ArrayList(Applicable) = .empty;
        defer applicable.deinit(gpa);
        try self.reach.each(gpa, t, &applicable);
        for (applicable.items) |a| {
            if (a.trait != .none) continue;
            const params = self.ast.declParams(a.sig);
            if (params.len == 0 or params[0].convention != .sink) continue;
            const id = self.typing.implementationIdOf(a.sig) orelse continue;
            const row = self.typing.implementations[@intFromEnum(id)];
            const answers = self.typing.instanceOf(self.typing.declReturn(a.sig)) orelse continue;
            if (answers.decl != result_decl) continue;
            const args = self.typing.argsOf(answers);
            if (args.len != 2 or args[1] != row.ty) continue;
            if (self.typing.mustConsumeWithin(self.typing.contextual_constraints.parentOf(a.sig), args[0])) continue;
            return a.sig;
        }
        return null;
    }
};

/// What the operations one written name reaches say about a postfix call of
/// that name: how many there are, and whether the type declares one itself.
pub const NameReach = struct {
    operations: u32 = 0,
    inherent: bool = false,

    pub fn note(self: *NameReach, a: Applicable) void {
        self.operations += 1;
        if (a.trait == node.DeclId.none) self.inherent = true;
    }

    /// Whether `x.name()` runs `a`, one of the operations counted here.
    ///
    /// The type's own operation is the one the postfix form reaches, and a
    /// trait's is then reached written out. The type's operation is declared
    /// with the type and reached without an import, so importing a trait or
    /// adding a bound can never change what an existing call runs -- the
    /// hazard [N-Ambiguous] exists to prevent does not arise. Without one, a
    /// single trait's operation is reached, and two traits' leave the call
    /// ambiguous.
    ///
    /// An inherent operation is counted only where the call could take it --
    /// accessible from the call's module, declared for the receiver's
    /// instantiation, and taking the receiver first -- which `Reach` decides
    /// before anything is noted here.
    pub fn reaches(self: NameReach, a: Applicable) bool {
        if (self.inherent) return a.trait == node.DeclId.none;
        return self.operations == 1;
    }
};

test "a postfix call reaches the type's own operation before a trait's" {
    const own: Applicable = .{ .sig = node.DeclId.at(1), .trait = node.DeclId.none };
    const first: Applicable = .{ .sig = node.DeclId.at(2), .trait = node.DeclId.at(10) };
    const second: Applicable = .{ .sig = node.DeclId.at(3), .trait = node.DeclId.at(11) };

    var beside: NameReach = .{};
    for ([_]Applicable{ first, own, second }) |a| beside.note(a);
    try std.testing.expect(beside.reaches(own));
    try std.testing.expect(!beside.reaches(first));
    try std.testing.expect(!beside.reaches(second));

    var alone: NameReach = .{};
    alone.note(first);
    try std.testing.expect(alone.reaches(first));

    var two: NameReach = .{};
    two.note(first);
    two.note(second);
    try std.testing.expect(!two.reaches(first));
    try std.testing.expect(!two.reaches(second));
}

/// Keeps, of `applicable`, the entries a call of their name runs: per name,
/// the one `NameReach.reaches` picks, and none of a name two traits answer.
/// Order is kept. The one reading of a whole enumeration, so a listing and the
/// call it offers agree on which entry a name reaches.
///
/// **Bound:** one table sized by the names in `applicable`.
pub fn keepReached(gpa: std.mem.Allocator, ast: *const Ast, applicable: *std.ArrayList(Applicable)) !void {
    var reaches: std.AutoHashMapUnmanaged(StringId, NameReach) = .empty;
    defer reaches.deinit(gpa);
    for (applicable.items) |a| {
        const entry = try reaches.getOrPut(gpa, ast.tokenName(ast.declName(a.sig)));
        if (!entry.found_existing) entry.value_ptr.* = .{};
        entry.value_ptr.note(a);
    }
    var kept: usize = 0;
    for (applicable.items) |a| {
        if (!reaches.get(ast.tokenName(ast.declName(a.sig))).?.reaches(a)) continue;
        applicable.items[kept] = a;
        kept += 1;
    }
    applicable.shrinkRetainingCapacity(kept);
}

test "keepReached keeps the entry each name reaches" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "t.lin", .text =
        \\trait A {
        \\    fn blank() -> Self
        \\    fn only() -> Self
        \\}
        \\trait B {
        \\    fn blank() -> Self
        \\    fn shared() -> Self
        \\}
        \\struct S { n: UInt8 }
        \\impl S { fn shared() -> S { .{ n = 0 } } }
        \\
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    const ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const at = struct {
        fn decl(tree: *const Ast, name: []const u8, nth: usize) node.DeclId {
            var seen: usize = 0;
            for (0..tree.declCount()) |i| {
                const d = node.DeclId.at(@intCast(i));
                if (!std.mem.eql(u8, tree.tokenText(tree.declName(d)), name)) continue;
                if (seen == nth) return d;
                seen += 1;
            }
            unreachable;
        }
    };
    const a = at.decl(&ast, "A", 0);
    const b = at.decl(&ast, "B", 0);
    var list: std.ArrayList(Applicable) = .empty;
    // The type's own `shared` beats B's; `blank` is answered by two traits;
    // `only` by one.
    try list.appendSlice(gpa, &.{
        .{ .sig = at.decl(&ast, "shared", 1), .trait = node.DeclId.none },
        .{ .sig = at.decl(&ast, "blank", 0), .trait = a },
        .{ .sig = at.decl(&ast, "only", 0), .trait = a },
        .{ .sig = at.decl(&ast, "blank", 1), .trait = b },
        .{ .sig = at.decl(&ast, "shared", 0), .trait = b },
    });
    try keepReached(gpa, &ast, &list);
    try std.testing.expectEqual(@as(usize, 2), list.items.len);
    try std.testing.expectEqual(at.decl(&ast, "shared", 1), list.items[0].sig);
    try std.testing.expectEqual(at.decl(&ast, "only", 0), list.items[1].sig);
}

/// One eligible associated declaration and its complete trait key.
/// Argument storage belongs to the immutable typing used for lookup.
pub const Associated = struct { sig: DeclId, trait: DeclId, args: []const TypeId };

/// What `x.f()` and `Type.f()` may mean, and the one place that decides it.
///
/// **One enumeration, and every asker filters it.** The checker asks which
/// operation one written name reaches and whether two answer; completion asks
/// which names could be written at all. Those are the same question read two
/// ways, and answering the second by matching names would be a second reading
/// of the rule -- which is how a trait an editor offered and a compiler refused
/// would come about.
///
/// The pool rather than the checker's own state, so the answer is reachable
/// after the pass as well as during it: a `Typing` is what a checked module
/// leaves behind, and `Builder.view` is what the pass holds mid-flight.
pub const Reach = struct {
    ast: *const Ast,
    source_program: *const Program,
    expanded_program: ?*const ExpandedProgram = null,
    res: *const Resolution,
    typing: *const Typing,
    index: *const types_mod.ImplIndex,
    impls: []const types_mod.Implementation,
    /// The callable type of every declaration, settled before any body is
    /// walked. Read to hold an inherent operation's first parameter to the
    /// receiver.
    signatures: types_mod.Signatures,
    /// The module the call is written in. Which traits are in play is what that
    /// module can see, which is what stops importing a library changing what an
    /// existing call means, and which of a type's own operations are in play is
    /// what that module may name.
    from: ModuleId,
    /// Declaration-local evidence for open receiver types.
    scope: node.DeclId = .none,
    /// The prelude's `Display`, so an interpolation answers it with no
    /// implementation written anywhere.
    display: ?node.DeclId,

    fn moduleOf(self: *const Reach, d: node.DeclId) ModuleId {
        if (self.expanded_program) |expanded| return expanded.moduleOf(d);
        return self.source_program.moduleOf(d);
    }

    /// Every operation applicable to a value of `held`, inherent first.
    ///
    /// The type's own operations come first and the traits' follow in
    /// declaration order. Which entry a postfix call runs is
    /// `NameReach.reaches`: the type's own where there is one, since the
    /// postfix form reaches it before any trait's; otherwise the only trait's,
    /// and where two traits answer, the first two entries under one name are
    /// the pair `[N-Ambiguous]` is about.
    ///
    /// A field is not an operation and is never listed, so a field of the
    /// same name leaves every operation in place.
    ///
    /// Costs the members the type's own inherent blocks declare, then one
    /// lookup and one run per trait the module can see. Neither dimension is
    /// the program's declarations: the resolver chained each type's inherent
    /// members under its declaration and recorded which signatures each trait
    /// declares, and both are read here rather than searched for. A primitive
    /// came from no declaration and reads the namespaces the library opened on
    /// it; anything else that came from none -- an array, a type parameter --
    /// has no inherent block and declares nothing. The declaration `held`
    /// came from is worked out once per lookup rather than per candidate.
    pub fn each(self: Reach, gpa: std.mem.Allocator, held: TypeId, out: *std.ArrayList(Applicable)) !void {
        try self.eachObserved(gpa, held, out, false, null);
    }

    pub fn eachElsewhere(self: Reach, gpa: std.mem.Allocator, held: TypeId, out: *std.ArrayList(Applicable)) !void {
        try self.eachObserved(gpa, held, out, true, null);
    }

    fn eachObserved(self: Reach, gpa: std.mem.Allocator, held: TypeId, out: *std.ArrayList(Applicable), elsewhere_: bool, wanted: ?StringId) !void {
        if (held == .poison) return;
        // Name shadowing needs a separate candidate list only when forwarding
        // through an observation introduces another receiver's operations.
        if (self.typing.get(held) != .borrow) {
            if (elsewhere_) try self.eachElsewhereDirect(gpa, held, out, wanted, .operation) else try self.eachDirect(gpa, held, out, wanted, true);
            return;
        }
        var earlier: std.AutoHashMapUnmanaged(StringId, void) = .empty;
        defer earlier.deinit(gpa);
        var candidates: std.ArrayList(Applicable) = .empty;
        defer candidates.deinit(gpa);
        var receiver = held;
        var forwarded = false;
        while (receiver != .poison) {
            candidates.clearRetainingCapacity();
            // The type's own operations are held to the receiver as the call
            // passes it, observations and all, so they are read once at the
            // outer layer; a forwarded layer contributes the traits its
            // referent satisfies.
            if (elsewhere_) try self.eachElsewhereDirect(gpa, receiver, &candidates, wanted, .operation) else try self.eachDirect(gpa, receiver, &candidates, wanted, !forwarded);
            const first = out.items.len;
            for (candidates.items) |candidate| {
                const name = self.ast.tokenName(self.ast.declName(candidate.sig));
                if (earlier.contains(name)) continue;
                if (forwarded) {
                    const params = self.ast.declParams(candidate.sig);
                    if (params.len == 0 or params[0].convention != .read) continue;
                }
                try out.append(gpa, candidate);
            }
            for (out.items[first..]) |candidate| try earlier.put(gpa, self.ast.tokenName(self.ast.declName(candidate.sig)), {});
            receiver = switch (self.typing.get(receiver)) {
                .borrow => |observation| observation.referent,
                else => break,
            };
            forwarded = true;
        }
    }

    fn eachDirect(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        out: *std.ArrayList(Applicable),
        wanted: ?StringId,
        own: bool,
    ) !void {
        return self.eachDirectKind(gpa, held, out, wanted, .operation, own);
    }

    /// Which of a trait's members an enumeration is after: an operation a
    /// postfix call passes its receiver to, an associated type, or any
    /// operation a call written after the type's name, `Type.op()`, reaches.
    pub const MemberSought = enum { operation, associated, namespaced };

    /// `own` says whether the type's own operations are read as well as the
    /// traits': they are, except at a layer an observation was forwarded to,
    /// where the receiver they were held to is the outer one.
    fn eachDirectKind(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        out: *std.ArrayList(Applicable),
        wanted: ?StringId,
        kind: MemberSought,
        own: bool,
    ) !void {
        if (held == .poison) return;

        if (own and kind != .associated) try self.inherentOn(gpa, held, out, wanted, kind, null);

        // Under a name, the rows are the members of that name the module's
        // traits declare, in trait order: what a call costs is those rows.
        // Without one, every trait the module sees is read in full, which is
        // what listing every operation a value answers to costs.
        if (wanted) |name| {
            var rows = self.res.traitMembersNamed(self.from, name);
            var trait: node.DeclId = .none;
            // Whether `held` answers `trait`, asked once per trait at its first
            // member that could be taken; the rows of one trait are adjacent.
            var applicable: ?bool = null;
            while (rows.next()) |row| {
                if (row.trait != trait) {
                    trait = row.trait;
                    applicable = null;
                }
                if (!self.memberTakes(row.member, kind)) continue;
                if (applicable == null) applicable = try self.answersDirectly(gpa, held, trait);
                if (!applicable.?) continue;
                try out.append(gpa, .{ .sig = row.member, .trait = trait });
            }
        } else {
            var traits = self.res.traitsSeenBy(self.from);
            while (traits.next()) |trait| {
                var applicable = false;
                var declared = self.traitMembers(trait, kind);
                while (declared.next()) |sig| {
                    if (!self.memberTakes(sig, kind)) continue;
                    if (!applicable) {
                        if (!try self.answersDirectly(gpa, held, trait)) break;
                        applicable = true;
                    }
                    try out.append(gpa, .{ .sig = sig, .trait = trait });
                }
            }
        }

        // A bound on `held` is evidence that it answers the trait the bound
        // names, so that trait's members are read whether or not the module
        // sees it.
        var bounded: std.ArrayList(node.DeclId) = .empty;
        defer bounded.deinit(gpa);
        try self.boundTraitsUnseen(gpa, held, &bounded);
        for (bounded.items) |trait| {
            var declared = self.traitMembers(trait, kind);
            while (declared.next()) |sig| {
                if (!self.memberTakes(sig, kind)) continue;
                if (wanted) |name| if (self.ast.tokenName(self.ast.declName(sig)) != name) continue;
                try out.append(gpa, .{ .sig = sig, .trait = trait });
            }
        }
    }

    fn traitMembers(self: Reach, trait: node.DeclId, kind: MemberSought) resolve_mod.Signatures.Iter {
        return if (kind == .associated) self.res.signatures.typesOf(self.ast, trait) else self.res.signatures.of(self.ast, trait);
    }

    /// Appends, once each, the traits a bound on `held` names that this module
    /// does not see: the bounds written on a type parameter, including the
    /// traits they require, and the `where` clauses in force at this
    /// declaration. A bound names its trait, so its operations are in reach
    /// for the bounded type without a `use`. A concrete type carries no bound
    /// and appends nothing.
    ///
    /// **Bound:** the bounds on `held` within this declaration, each checked
    /// against the ones already appended; nothing is sized by the program.
    fn boundTraitsUnseen(self: Reach, gpa: std.mem.Allocator, held: TypeId, out: *std.ArrayList(node.DeclId)) !void {
        if (held == .poison) return;
        var bounds: std.ArrayList(types_mod.BoundTrait) = .empty;
        defer bounds.deinit(gpa);
        try self.typing.appendBoundsWithin(gpa, self.scope, held, &bounds);
        for (bounds.items) |bound| {
            const trait = node.DeclId.at(bound.trait);
            if (self.res.seesTrait(self.from, trait)) continue;
            if (std.mem.indexOfScalar(node.DeclId, out.items, trait) != null) continue;
            try out.append(gpa, trait);
        }
    }

    /// Whether a `use` could bring `trait` into scope: this module has an
    /// import route to the trait's, the question `Program.importRoute`
    /// answers. The root module and a module beneath a directory such as
    /// `my-lib` are reached by no import, so a trait either declares is not
    /// offered as missing a `use`.
    fn usable(self: Reach, trait: node.DeclId) bool {
        const m = self.moduleOf(trait);
        if (m == .none or m.index() >= self.source_program.modules.len) return true;
        return self.source_program.importRoute(self.from, m) != null;
    }

    fn memberTakes(self: Reach, member: node.DeclId, kind: MemberSought) bool {
        return memberSought(self.ast, member, kind);
    }

    /// Whether `held` answers `trait` for a postfix call from here: by
    /// rendering itself as the prelude's `Display` does, by a direct
    /// implementation, or by an open receiver an implementation covers.
    fn answersDirectly(self: Reach, gpa: std.mem.Allocator, held: TypeId, trait: node.DeclId) !bool {
        return rendersDisplayItself(self.typing, self.display, held, trait) or
            try self.index.any(gpa, self.impls, self.typing, trait.index(), held, self.scope, .direct) or
            try self.index.hasOpenReceiver(self.typing, self.impls, trait.index(), held, self.scope);
    }

    /// Associated names use exact-subject promises first, then the same
    /// visible trait enumeration and prepared applicability as operations.
    pub fn associated(self: Reach, gpa: std.mem.Allocator, held: TypeId, wanted: ?StringId, out: *std.ArrayList(Associated)) !void {
        if (held == .poison) return;
        var bounds: std.ArrayList(types_mod.BoundTrait) = .empty;
        defer bounds.deinit(gpa);
        try self.typing.appendBoundsWithin(gpa, self.scope, held, &bounds);
        const first = out.items.len;
        for (bounds.items) |bound| {
            const trait = DeclId.at(bound.trait);
            var members = self.res.signatures.typesOf(self.ast, trait);
            while (members.next()) |sig| {
                if (!settlesAType(self.ast, sig)) continue;
                if (wanted) |name| if (self.ast.tokenName(self.ast.declName(sig)) != name) continue;
                try appendAssociated(gpa, out, .{ .sig = sig, .trait = trait, .args = bound.args });
            }
        }
        if (wanted != null and out.items.len != first) return;
        const bound_end = out.items.len;
        // Bare parameters and projections expose only promised members.
        if (self.typing.get(held) == .parameter) return;
        var candidates: std.ArrayList(Applicable) = .empty;
        defer candidates.deinit(gpa);
        try self.eachDirectKind(gpa, held, &candidates, wanted, .associated, false);
        var keys: std.ArrayList([]const TypeId) = .empty;
        defer keys.deinit(gpa);
        for (candidates.items) |candidate| {
            const name = self.ast.tokenName(self.ast.declName(candidate.sig));
            var promised = false;
            for (out.items[first..bound_end]) |bound| {
                if (self.ast.tokenName(self.ast.declName(bound.sig)) == name) {
                    promised = true;
                    break;
                }
            }
            if (promised) continue;
            keys.clearRetainingCapacity();
            _ = try self.index.keys(gpa, self.impls, self.typing, candidate.trait, held, self.scope, &keys);
            for (keys.items) |args| try appendAssociated(gpa, out, .{ .sig = candidate.sig, .trait = candidate.trait, .args = args });
        }
    }

    fn appendAssociated(gpa: std.mem.Allocator, out: *std.ArrayList(Associated), candidate: Associated) !void {
        for (out.items) |present| {
            if (present.sig == candidate.sig and present.trait == candidate.trait and std.mem.eql(TypeId, present.args, candidate.args)) return;
        }
        try out.append(gpa, candidate);
    }

    /// The trait that would declare `wanted` for `held` if this module could
    /// see it, or `.none` where none would.
    ///
    /// The same enumeration `each` walks, with the scope test turned round:
    /// there, a trait the module cannot see is not in play and the name does
    /// not resolve; here, that is exactly what is being looked for. Asking it
    /// this way rather than matching names is what keeps one rule with one
    /// implementation -- a second walk deciding what a trait declares would be
    /// free to disagree with the walk that decides what a call means.
    ///
    /// Only for a report. Nothing about what a call resolves to changes: a
    /// trait out of scope stays out of scope, and the answer is what to say
    /// about it rather than what to do.
    pub fn elsewhere(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        wanted: StringId,
    ) !node.DeclId {
        var found: std.ArrayList(Applicable) = .empty;
        defer found.deinit(gpa);
        try self.eachObserved(gpa, held, &found, true, wanted);
        return if (found.items.len == 0) node.DeclId.none else found.items[0].trait;
    }

    /// The trait in scope that declares `wanted` and has an implementation
    /// for `held`'s shape whose bounds `held` does not meet, or `.none`.
    ///
    /// Only for a report: such an operation does not resolve, and saying the
    /// type has no field of that name, or that its parts are sealed, would
    /// send a reader after the wrong mistake. It runs only on that failure and
    /// reads `traits`, the ones in scope declaring `wanted` that preparing the
    /// lookup collected, so it walks no trait names of its own; of those it
    /// reads implementations only for `held`'s head.
    pub fn unmetImplementation(self: Reach, gpa: std.mem.Allocator, held: TypeId, wanted: StringId, traits: []const node.DeclId) !node.DeclId {
        if (held == .poison) return node.DeclId.none;
        const head = self.typing.headOf(held);
        if (head == .parameter or head == .default_) return node.DeclId.none;
        for (traits) |trait| {
            var declares = false;
            var declared = self.res.signatures.of(self.ast, trait);
            while (declared.next()) |sig| {
                if (self.ast.tokenName(self.ast.declName(sig)) != wanted) continue;
                if (!postfixReaches(self.ast, sig)) continue;
                declares = true;
                break;
            }
            if (!declares) continue;
            // A type the trait does apply to reaches the operation some other
            // way, or is refused for a reason of its own.
            if (try self.index.any(gpa, self.impls, self.typing, trait.index(), held, self.scope, .direct)) continue;
            var rows = self.index.candidates(self.impls, trait.index(), head, false);
            while (rows.next()) |at| {
                if (!self.impls[at].head.same(head)) continue;
                if (try self.typing.receiverTraitArguments(@enumFromInt(at), held) != null) return trait;
            }
        }
        return node.DeclId.none;
    }

    /// Every operation `held` would answer to through a trait this module
    /// cannot see, with the trait that declares each.
    ///
    /// One walk with two readers: the report above takes the trait declaring
    /// one name, and an editor takes the whole list to offer what a `use`
    /// would make writable. Neither matches names against traits itself.
    ///
    /// **A trait in scope is not among them, and it takes a check to say so.**
    /// A trait a `use` brought into this module is named by its own module
    /// too, so "not named by this module" is asked of the resolver's record of
    /// what each module sees, not of where the trait was written.
    ///
    /// Under a name, the rows are the members of that name every trait in
    /// the program declares, each once: what a report costs is those rows,
    /// not the program's traits. Without one, every trait some module names
    /// is read in full, which is what an editor listing every operation a
    /// `use` would make writable costs.
    fn eachElsewhereDirect(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        out: *std.ArrayList(Applicable),
        wanted: ?StringId,
        kind: MemberSought,
    ) !void {
        if (held == .poison) return;

        // A trait a bound on `held` names is in reach already, through
        // `eachDirectKind`, so no `use` would add it.
        var bounded: std.ArrayList(node.DeclId) = .empty;
        defer bounded.deinit(gpa);
        try self.boundTraitsUnseen(gpa, held, &bounded);

        if (wanted) |name| {
            var rows = self.res.traitMembersNamedAnywhere(name);
            var trait: node.DeclId = .none;
            // Whether `held` answers `trait` from out of scope, asked once per
            // trait at its first member that could be taken; a trait's rows
            // under one name are adjacent because each was noted once.
            var applicable: ?bool = null;
            while (rows.next()) |row| {
                if (row.trait != trait) {
                    trait = row.trait;
                    applicable = null;
                }
                if (self.res.seesTrait(self.from, trait) or !self.memberTakes(row.member, kind)) continue;
                if (std.mem.indexOfScalar(node.DeclId, bounded.items, trait) != null) continue;
                if (!self.usable(trait)) continue;
                if (applicable == null) applicable = try self.answersDirectly(gpa, held, trait);
                if (!applicable.?) continue;
                try out.append(gpa, .{ .sig = row.member, .trait = trait });
            }
            return;
        }

        // `res.traits` names each trait once however many modules pass it
        // along, so what is offered is the trait rather than its rows.
        for (self.res.traits) |trait| {
            if (self.res.seesTrait(self.from, trait)) continue;
            if (std.mem.indexOfScalar(node.DeclId, bounded.items, trait) != null) continue;
            if (!self.usable(trait)) continue;
            if (!try self.answersDirectly(gpa, held, trait)) continue;

            var declared = self.res.signatures.of(self.ast, trait);
            while (declared.next()) |sig| {
                if (!self.memberTakes(sig, kind)) continue;
                try out.append(gpa, .{ .sig = sig, .trait = trait });
            }
        }
    }

    /// Every operation the type itself declares that a postfix call written
    /// in this module could take, appended in the order they were written.
    ///
    /// A trait's is not one of these: it is reached through the trait, which is
    /// what keeps importing a library from changing a call. What every inherent
    /// `impl` writes are the rows the resolver chained under the declaration
    /// the block's head names, so a declared type reads its own chain, and a
    /// primitive -- which no declaration produced -- reads the namespaces the
    /// library opened on it. Anything else, an array or a type parameter, has
    /// no inherent block and declares nothing. An observation declares nothing
    /// of its own either: `borrow Door` reads `Door`'s chain, and each member
    /// is then held to the observation as the call passes it.
    ///
    /// Sorted at the end because a primitive's blocks may sit in more than one
    /// module and the postfix form reads the first one written. The sort is
    /// over what the type declares, never over the program.
    ///
    /// **Bound:** the members the type's own inherent blocks declare, each
    /// costing one hash lookup for its chain, one binary search for its
    /// block's row, and one structural match against `held`. Nothing is sized
    /// by the program: the chain is per declaration, and the primitives'
    /// namespaces are the library's blocks, which no program lengthens.
    fn inherentOn(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        out: *std.ArrayList(Applicable),
        wanted: ?StringId,
        kind: MemberSought,
        dropped: ?*?Dropped,
    ) !void {
        const first = out.items.len;
        const observed = self.typing.observedReceiver(held).receiver;

        if (self.typing.declOfType(observed)) |origin| {
            var rows = self.res.membersOfType(origin);
            while (rows.next()) |b| try self.appendOwn(gpa, held, b, out, wanted, kind, dropped);
        } else {
            for (self.res.builtin_namespaces) |n| {
                if (n.of != observed) continue;
                var rows = self.res.membersUnder(n.module, n.owner);
                while (rows.next()) |b| try self.appendOwn(gpa, held, b, out, wanted, kind, dropped);
            }
        }

        std.mem.sort(Applicable, out.items[first..], {}, writtenBefore);
    }

    /// An operation the type declares that a postfix call could not take,
    /// and why: it is out of the call's module's reach, or the receiver
    /// cannot be passed to it -- its block is for another instantiation, its
    /// first parameter takes something else, or it takes nothing at all.
    pub const Dropped = struct {
        sig: node.DeclId,
        why: union(enum) {
            inaccessible: resolve_mod.Reach,
            receiver,
        },
    };

    /// Appends one member of a type's namespace, where a postfix call on
    /// `held` written in this module could take it: it is accessible from
    /// here, its block applies to `held`'s instantiation, and its first
    /// parameter takes the receiver. A member the call could not take does
    /// not stand in a trait's way, so it is left out here rather than refused
    /// after it has displaced the trait's; the first one left out under the
    /// wanted name is noted in `dropped`, with its reason, for the report a
    /// call that then reaches nothing makes.
    fn appendOwn(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        b: BindingId,
        out: *std.ArrayList(Applicable),
        wanted: ?StringId,
        kind: MemberSought,
        dropped: ?*?Dropped,
    ) !void {
        const d = self.res.declaredBy(b);

        // A constant declares no code, so there is nothing for a call to run.
        if (self.ast.declBody(d) == ExprId.none) return;
        if (wanted) |name| if (self.ast.tokenName(self.ast.declName(d)) != name) return;

        const why: @FieldType(Dropped, "why") = if (!self.accessible(b, d))
            .{ .inaccessible = self.res.namingReachOf(b) }
        else if (kind == .namespaced)
            // A call written after the type's name passes no receiver, so
            // what the operation's first parameter takes does not matter.
            return out.append(gpa, .{ .sig = d, .trait = node.DeclId.none })
        else if (self.ast.declParams(d).len == 0 or !try self.takesTheReceiver(gpa, held, d))
            // It has to take one, or there is nothing for the receiver to be.
            .receiver
        else
            return out.append(gpa, .{ .sig = d, .trait = node.DeclId.none });

        if (dropped) |slot| {
            if (slot.* == null) slot.* = .{ .sig = d, .why = why };
        }
    }

    /// Whether this module may name the member `b` declares, read from the
    /// reach the resolver settled for the binding: a private member is named
    /// only in its own module and an internal one only within its root, the
    /// same rule the written form `Door.close(door)` is held to.
    fn accessible(self: Reach, b: BindingId, d: node.DeclId) bool {
        const reach = self.res.namingReachOf(b);
        if (reach == .public) return true;
        const holding = self.moduleOf(d);
        if (holding == .none or self.from == .none) return false;
        return resolve_mod.reachableFrom(self.source_program, reach, holding, self.from);
    }

    /// Whether a postfix call on `held` could take the operation `d`: the
    /// block declaring it applies to the instantiation the receiver's
    /// observations reach, and its first parameter takes the receiver as the
    /// call passes it. `impl Box[UInt8]` declares nothing for a `Box[Bool]`,
    /// `fn close(code: UInt8)` inside `impl Door` takes no door, and
    /// `fn open(self: Door)` takes no `borrow Door` -- while
    /// `fn peek(self: borrow Door)` takes exactly that, and `fn lock(self:
    /// Self)` reads the door through the observation.
    ///
    /// Both are the one structural match an implementation's head is held
    /// against a receiver by, run with the block's own parameters open: the
    /// head binds them, and the first parameter is then held to what the head
    /// bound, through the observations the call itself would look through. A
    /// signature that did not check was reported where it was declared and
    /// is taken as reachable, so nothing here says a second thing about it.
    fn takesTheReceiver(self: Reach, gpa: std.mem.Allocator, held: TypeId, d: node.DeclId) !bool {
        const at = implementationRowIndex(self.impls, self.res.implEnclosing(d)) orelse return false;
        const row = self.impls[at];
        const bindings = try gpa.alloc(TypeId, row.parameters);
        defer gpa.free(bindings);
        @memset(bindings, .poison);
        // A block is written for a declared type, never for an observation
        // of one, so its head is held to what the observations reach.
        const observed = self.typing.observedReceiver(held).receiver;
        if (!types_mod.ImplIndex.bindKey(self.typing, observed, row.ty, row.decl.index(), bindings)) return false;
        return self.firstParameterTakes(d, row.decl.index(), bindings, held);
    }

    /// Whether the first parameter of `d` takes `held` as a call would pass
    /// it: the one structural match, run with the parameters `owner` declares
    /// open in `bindings`, through the observations the call looks through.
    /// A signature that did not check was reported where it was declared and
    /// is taken as taking it.
    fn firstParameterTakes(self: Reach, d: node.DeclId, owner: u32, bindings: []TypeId, held: TypeId) bool {
        if (self.ast.declParams(d).len == 0) return false;
        const signature = self.signatures.get(d);
        if (signature == .poison) return true;
        const callable = switch (self.typing.get(signature)) {
            .callable => |callable| callable,
            else => return true,
        };
        const params = self.typing.callableParams(callable);
        if (params.len == 0) return false;
        const Bound = struct {
            pool: *const Typing,
            want: TypeId,
            owner: u32,
            bindings: []TypeId,
            fn fits(bound: @This(), left: TypeId) bool {
                return types_mod.ImplIndex.bindKey(bound.pool, left, bound.want, bound.owner, bound.bindings);
            }
        };
        const bound: Bound = .{ .pool = self.typing, .want = params[0].ty, .owner = owner, .bindings = bindings };
        return observationsPassing(self.typing, self.ast, self.ast.declParams(d)[0], held, bound) != null;
    }

    /// Whether the first parameter of the free function `d` takes `held`, as
    /// in `d(held, …)`, with the function's own type parameters open.
    /// `bindings`, one per type parameter, receives what the match settled
    /// each to, `.poison` where it settled none; whether those meet the
    /// function's bounds is the checker's own bound check to answer.
    pub fn freeFunctionTakes(self: Reach, d: node.DeclId, held: TypeId, bindings: []TypeId) bool {
        std.debug.assert(bindings.len == self.ast.declTypeParams(d).len);
        @memset(bindings, .poison);
        return self.firstParameterTakes(d, d.index(), bindings, held);
    }

    test "a free function takes a value where its first parameter does" {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        const source: Source = .{ .path = "t.lin", .text =
            \\fn double(value: UInt8) -> UInt8 { value * 2 }
            \\fn start() -> UInt8 { 1 }
            \\fn same[T](value: T) -> T { value }
            \\fn flag(value: Bool) -> Bool { value }
            \\fn main() -> UInt8 {
            \\    let n: UInt8 = 4
            \\    let _f = flag(true)
            \\    double(n) + start() + same(n)
            \\}
            \\
        };
        var interner: Interner = .empty;
        const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
        var ast = try parse(gpa, &source, .from(0), tokens, &sink);
        const resolved = try resolve_mod.resolveTree(gpa, &ast, &sink);
        var typing = try typecheckTree(gpa, &resolved, &sink);
        try std.testing.expectEqual(@as(u32, 0), sink.error_count);

        const reach = reachIn(&ast, resolved.expanded.source, &resolved.resolution, &typing, ModuleId.from(0), .none);
        const decl = struct {
            fn named(tree: *const Ast, name: []const u8) node.DeclId {
                for (0..tree.declCount()) |i| {
                    const d = node.DeclId.at(@intCast(i));
                    if (std.mem.eql(u8, tree.tokenText(tree.declName(d)), name)) return d;
                }
                unreachable;
            }
        };
        try std.testing.expect(reach.freeFunctionTakes(decl.named(&ast, "double"), .u8, &.{}));
        var same: [1]TypeId = undefined;
        try std.testing.expect(reach.freeFunctionTakes(decl.named(&ast, "same"), .u8, &same));
        try std.testing.expectEqual(TypeId.u8, same[0]);
        try std.testing.expect(!reach.freeFunctionTakes(decl.named(&ast, "start"), .u8, &.{}));
        try std.testing.expect(!reach.freeFunctionTakes(decl.named(&ast, "flag"), .u8, &.{}));
    }

    /// The operations one written name reaches, in the order `each` yields
    /// them.
    ///
    /// The caller owns the list. Which entry a postfix call runs, if any, is
    /// `NameReach.reaches`: the type's own operation where there is
    /// one, the only trait's otherwise, and none -- `[N-Ambiguous]` -- where
    /// two traits answer.
    ///
    /// Costs the type's own members under the name and the rows the module's
    /// traits declare under it, which the resolver indexed by module and
    /// name; nothing here is the program's types or its traits.
    pub fn named(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        name: StringId,
        out: *std.ArrayList(Applicable),
    ) !void {
        var kept: usize = 0;
        for (out.items) |a| {
            if (self.ast.tokenName(self.ast.declName(a.sig)) != name) continue;
            out.items[kept] = a;
            kept += 1;
        }
        out.shrinkRetainingCapacity(kept);
        try self.eachObserved(gpa, held, out, false, name);
    }

    /// The operations the type itself declares under one name, without the
    /// traits': what a postfix call of that name reaches before any trait's.
    pub fn ownNamed(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        name: StringId,
        out: *std.ArrayList(Applicable),
    ) !void {
        if (held == .poison) return;
        try self.inherentOn(gpa, held, out, name, .operation, null);
    }

    test "a type's own operation is found only where a postfix call could take it" {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        const source: Source = .{ .path = "t.lin", .text =
            \\struct Box[T] { item: T }
            \\struct Door { width: UInt8 }
            \\impl Box[UInt8] { fn get(self: Box[UInt8]) -> UInt8 { self.item } }
            \\impl Door { fn close(code: UInt8) -> UInt8 { code } }
            \\impl Door { fn open(self: Door) -> UInt8 { self.width } }
            \\impl Door { fn peek(self: borrow Door) -> UInt8 where carries() { self.width } }
            \\impl Door { fn lock(self: Self) -> UInt8 { self.width } }
            \\fn main() -> UInt8 {
            \\    let byte: Box[UInt8] = .{ item = 1 }
            \\    let flag: Box[Bool] = .{ item = true }
            \\    let door: Door = .{ width = 2 }
            \\    let _b: Box[Bool] = flag
            \\    let view = borrow door
            \\    byte.get() + Door.close(3) + view.peek() + view.lock() + door.open()
            \\}
            \\
        };
        var interner: Interner = .empty;
        const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
        var ast = try parse(gpa, &source, .from(0), tokens, &sink);
        const resolved = try resolve_mod.resolveTree(gpa, &ast, &sink);
        var typing = try typecheckTree(gpa, &resolved, &sink);
        _ = &typing;
        try std.testing.expectEqual(@as(u32, 0), sink.error_count);

        const spelled = struct {
            fn decl(tree: *const Ast, name: []const u8) node.DeclId {
                for (0..tree.declCount()) |i| {
                    const d = node.DeclId.at(@intCast(i));
                    if (std.mem.eql(u8, tree.tokenText(tree.declName(d)), name)) return d;
                }
                unreachable;
            }
            fn local(tree: *const Ast, typed: *const Typing, name: []const u8) TypeId {
                const body = tree.blockOf(tree.declBody(decl(tree, "main")));
                for (tree.blockStmts(body)) |s| {
                    const data = tree.stmtData(s);
                    if (std.mem.eql(u8, tree.tokenText(data.name), name)) return typed.exprType(data.init);
                }
                unreachable;
            }
        };
        const reach = reachIn(&ast, resolved.expanded.source, &resolved.resolution, &typing, ModuleId.from(0), .none);
        const get = ast.tokenName(ast.declName(spelled.decl(&ast, "get")));
        const close = ast.tokenName(ast.declName(spelled.decl(&ast, "close")));
        const open = ast.tokenName(ast.declName(spelled.decl(&ast, "open")));
        const peek = ast.tokenName(ast.declName(spelled.decl(&ast, "peek")));
        const lock = ast.tokenName(ast.declName(spelled.decl(&ast, "lock")));

        var found: std.ArrayList(Applicable) = .empty;
        // `impl Box[UInt8]` answers for a `Box[UInt8]` and not for a
        // `Box[Bool]`.
        try reach.ownNamed(gpa, spelled.local(&ast, &typing, "byte"), get, &found);
        try std.testing.expectEqual(@as(usize, 1), found.items.len);
        try std.testing.expectEqual(spelled.decl(&ast, "get"), found.items[0].sig);
        found.clearRetainingCapacity();
        try reach.ownNamed(gpa, spelled.local(&ast, &typing, "flag"), get, &found);
        try std.testing.expectEqual(@as(usize, 0), found.items.len);

        // `close` takes a code first, so no door reaches it; `open` takes the
        // door.
        try reach.ownNamed(gpa, spelled.local(&ast, &typing, "door"), close, &found);
        try std.testing.expectEqual(@as(usize, 0), found.items.len);
        try reach.ownNamed(gpa, spelled.local(&ast, &typing, "door"), open, &found);
        try std.testing.expectEqual(@as(usize, 1), found.items.len);
        try std.testing.expectEqual(spelled.decl(&ast, "open"), found.items[0].sig);

        // A borrowed door is held to each first parameter as it is passed:
        // `peek` takes the observation, `lock` reads the door through it,
        // and `open` takes a door by value and so takes no observation.
        const view = spelled.local(&ast, &typing, "view");
        found.clearRetainingCapacity();
        try reach.ownNamed(gpa, view, peek, &found);
        try std.testing.expectEqual(@as(usize, 1), found.items.len);
        try std.testing.expectEqual(spelled.decl(&ast, "peek"), found.items[0].sig);
        found.clearRetainingCapacity();
        try reach.ownNamed(gpa, view, lock, &found);
        try std.testing.expectEqual(@as(usize, 1), found.items.len);
        try std.testing.expectEqual(spelled.decl(&ast, "lock"), found.items[0].sig);
        found.clearRetainingCapacity();
        try reach.ownNamed(gpa, view, open, &found);
        try std.testing.expectEqual(@as(usize, 0), found.items.len);
    }
    /// What a call written after a type's name reaches, `Limits.default()` or
    /// `T.default()`: the type's own operations under `wanted`, or under any
    /// name where it is null, then the operations of the traits in scope that
    /// `held` implements or a bound on it promises, whatever their first
    /// parameter takes.
    ///
    /// The type's own come first, held to what the postfix form holds them
    /// to except the receiver: an operation this module may not name is left
    /// out, noted in `dropped`, and does not stand in a trait's way. Which
    /// entry the call runs is `NameReach.reaches`, the rule the postfix form
    /// reads: the type's own where there is one, otherwise the only trait's,
    /// and none where two traits answer. `traits` false asks for the type's
    /// own alone, for a generic type named where no instantiation says which
    /// implementations are in play.
    ///
    /// Costs the members the type's own blocks declare plus what `each`
    /// costs for the traits' half: under a name, the rows of that name the
    /// module's traits declare, and one applicability question per trait
    /// among them.
    pub fn namespaced(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        wanted: ?StringId,
        traits: bool,
        out: *std.ArrayList(Applicable),
        dropped: ?*?Dropped,
    ) !void {
        if (held == .poison) return;
        try self.inherentOn(gpa, held, out, wanted, .namespaced, dropped);
        if (traits) try self.eachDirectKind(gpa, held, out, wanted, .namespaced, false);
    }

    /// The trait this module cannot see that would answer `Type.wanted()` for
    /// `held`, or `.none` where none would. Only for a report, as `elsewhere`
    /// is for the postfix form.
    fn namespacedElsewhere(self: Reach, gpa: std.mem.Allocator, held: TypeId, wanted: StringId) !node.DeclId {
        if (held == .poison) return node.DeclId.none;
        var found: std.ArrayList(Applicable) = .empty;
        defer found.deinit(gpa);
        try self.eachElsewhereDirect(gpa, held, &found, wanted, .namespaced);
        return if (found.items.len == 0) node.DeclId.none else found.items[0].trait;
    }

    test "a call written after a type's name reaches the operations of the traits it implements" {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        const source: Source = .{ .path = "t.lin", .text =
            \\trait Blank { fn blank() -> Self }
            \\trait Empty { fn blank() -> Self }
            \\trait Measure { fn of(x: Self) -> UInt8 }
            \\struct Meal { courses: UInt8 }
            \\struct Plate { size: UInt8 }
            \\impl Blank for Meal { fn blank() -> Meal { .{ courses = 0 } } }
            \\impl Measure for Meal { fn of(x: Self) -> UInt8 { x.courses } }
            \\impl Blank for Plate { fn blank() -> Plate { .{ size = 0 } } }
            \\impl Empty for Plate { fn blank() -> Plate { .{ size = 1 } } }
            \\fn main() -> UInt8 {
            \\    let meal = Meal.blank()
            \\    let plate: Plate = Empty.blank()
            \\    let _either = Plate.blank()
            \\    Meal.of(meal) + plate.size
            \\}
            \\
        };
        var interner: Interner = .empty;
        const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
        var ast = try parse(gpa, &source, .from(0), tokens, &sink);
        const resolved = try resolve_mod.resolveTree(gpa, &ast, &sink);
        var typing = try typecheckTree(gpa, &resolved, &sink);
        _ = &typing;
        // `Plate.blank()` is the one refusal: both traits answer for a plate.
        try std.testing.expectEqual(@as(u32, 1), sink.error_count);
        try std.testing.expectEqual(Code.n_ambiguous, sink.items()[0].code.?);

        const spelled = struct {
            fn decl(tree: *const Ast, name: []const u8, nth: usize) node.DeclId {
                var seen: usize = 0;
                for (0..tree.declCount()) |i| {
                    const d = node.DeclId.at(@intCast(i));
                    if (!std.mem.eql(u8, tree.tokenText(tree.declName(d)), name)) continue;
                    if (seen == nth) return d;
                    seen += 1;
                }
                unreachable;
            }
            fn local(tree: *const Ast, typed: *const Typing, name: []const u8) TypeId {
                const body = tree.blockOf(tree.declBody(decl(tree, "main", 0)));
                for (tree.blockStmts(body)) |s| {
                    const data = tree.stmtData(s);
                    if (std.mem.eql(u8, tree.tokenText(data.name), name)) return typed.exprType(data.init);
                }
                unreachable;
            }
        };
        const reach = reachIn(&ast, resolved.expanded.source, &resolved.resolution, &typing, ModuleId.from(0), .none);
        const blank = ast.tokenName(ast.declName(spelled.decl(&ast, "blank", 0)));
        const meal = spelled.local(&ast, &typing, "meal");
        const plate = spelled.local(&ast, &typing, "plate");

        // `Meal` implements `Blank` and `Measure`, so both operations are
        // reached, `of` although its first parameter takes the receiver and
        // `blank` although it takes nothing.
        var found: std.ArrayList(Applicable) = .empty;
        try reach.namespaced(gpa, meal, null, true, &found, null);
        try std.testing.expectEqual(@as(usize, 2), found.items.len);
        try std.testing.expectEqual(spelled.decl(&ast, "blank", 0), found.items[0].sig);
        try std.testing.expectEqual(spelled.decl(&ast, "of", 0), found.items[1].sig);

        // Under a name, only `Blank`'s answers for a meal: `Empty` declares
        // `blank` too, and `Meal` does not implement it.
        found.clearRetainingCapacity();
        try reach.namespaced(gpa, meal, blank, true, &found, null);
        try std.testing.expectEqual(@as(usize, 1), found.items.len);
        try std.testing.expectEqual(spelled.decl(&ast, "Blank", 0), found.items[0].trait);

        // A plate implements both traits declaring `blank`, which leaves the
        // name ambiguous.
        found.clearRetainingCapacity();
        try reach.namespaced(gpa, plate, blank, true, &found, null);
        try std.testing.expectEqual(@as(usize, 2), found.items.len);
        var name_reach: NameReach = .{};
        for (found.items) |a| name_reach.note(a);
        try std.testing.expect(!name_reach.reaches(found.items[0]));
    }

    /// The first operation the type declares under `name` that a postfix
    /// call on `held` written in this module could not take, with the reason,
    /// or null where it declares none or the call takes every one. What a
    /// call that reached nothing reports instead of "no field": the name is
    /// declared, and the declaration shows why the call is refused.
    pub fn ownDropped(self: Reach, gpa: std.mem.Allocator, held: TypeId, name: StringId) !?Dropped {
        if (held == .poison) return null;
        var taken: std.ArrayList(Applicable) = .empty;
        defer taken.deinit(gpa);
        var dropped: ?Dropped = null;
        try self.inherentOn(gpa, held, &taken, name, .operation, &dropped);
        return dropped;
    }

    /// An operation the type itself declares, and whether its first
    /// parameter takes the receiver as a postfix call passes it.
    pub const Own = struct { sig: node.DeclId, takes_receiver: bool };

    /// The operation the type itself declares under `name` that this module
    /// may name, whether or not a postfix call could take it: the first one a
    /// call could take, else the first it could not for its receiver. One
    /// out of the module's reach is left out, because the path a report
    /// would offer for it is out of reach too.
    pub fn ownDeclared(self: Reach, gpa: std.mem.Allocator, held: TypeId, name: StringId) !?Own {
        if (held == .poison) return null;
        var taken: std.ArrayList(Applicable) = .empty;
        defer taken.deinit(gpa);
        var dropped: ?Dropped = null;
        try self.inherentOn(gpa, held, &taken, name, .operation, &dropped);
        if (taken.items.len != 0) return .{ .sig = taken.items[0].sig, .takes_receiver = true };
        const left = dropped orelse return null;
        return switch (left.why) {
            .receiver => .{ .sig = left.sig, .takes_receiver = false },
            .inaccessible => null,
        };
    }

    test "an own operation a postfix call could not take is reported with its reason" {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        const source: Source = .{ .path = "t.lin", .text =
            \\struct Box[T] { item: T }
            \\struct Door { width: UInt8 }
            \\impl Box[UInt8] { fn get(self: Box[UInt8]) -> UInt8 { self.item } }
            \\impl Door { fn close(code: UInt8) -> UInt8 { code } }
            \\impl Door { fn make() -> Door { .{ width = 1 } } }
            \\impl Door { fn open(self: Door) -> UInt8 { self.width } }
            \\fn main() -> UInt8 {
            \\    let byte: Box[UInt8] = .{ item = 1 }
            \\    let flag: Box[Bool] = .{ item = true }
            \\    let door = Door.make()
            \\    let _b: Box[Bool] = flag
            \\    byte.get() + Door.close(3) + door.open()
            \\}
            \\
        };
        var interner: Interner = .empty;
        const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
        var ast = try parse(gpa, &source, .from(0), tokens, &sink);
        const resolved = try resolve_mod.resolveTree(gpa, &ast, &sink);
        var typing = try typecheckTree(gpa, &resolved, &sink);
        _ = &typing;
        try std.testing.expectEqual(@as(u32, 0), sink.error_count);

        const spelled = struct {
            fn decl(tree: *const Ast, name: []const u8) node.DeclId {
                for (0..tree.declCount()) |i| {
                    const d = node.DeclId.at(@intCast(i));
                    if (std.mem.eql(u8, tree.tokenText(tree.declName(d)), name)) return d;
                }
                unreachable;
            }
            fn local(tree: *const Ast, typed: *const Typing, name: []const u8) TypeId {
                const body = tree.blockOf(tree.declBody(decl(tree, "main")));
                for (tree.blockStmts(body)) |s| {
                    const data = tree.stmtData(s);
                    if (std.mem.eql(u8, tree.tokenText(data.name), name)) return typed.exprType(data.init);
                }
                unreachable;
            }
            fn named(tree: *const Ast, text: []const u8) StringId {
                return tree.tokenName(tree.declName(decl(tree, text)));
            }
        };
        const reach = reachIn(&ast, resolved.expanded.source, &resolved.resolution, &typing, ModuleId.from(0), .none);
        const door = spelled.local(&ast, &typing, "door");

        // `get` is declared for another instantiation, `close` takes a code
        // first, and `make` takes nothing: each is dropped for its receiver.
        for ([_]struct { held: TypeId, name: []const u8 }{
            .{ .held = spelled.local(&ast, &typing, "flag"), .name = "get" },
            .{ .held = door, .name = "close" },
            .{ .held = door, .name = "make" },
        }) |refused| {
            const dropped = (try reach.ownDropped(gpa, refused.held, spelled.named(&ast, refused.name))).?;
            try std.testing.expectEqual(spelled.decl(&ast, refused.name), dropped.sig);
            try std.testing.expectEqual(.receiver, std.meta.activeTag(dropped.why));
        }

        // `open` takes the door, and nothing declares `lock`: neither is
        // dropped.
        try std.testing.expectEqual(@as(?Dropped, null), try reach.ownDropped(gpa, door, spelled.named(&ast, "open")));
        try std.testing.expectEqual(@as(?Dropped, null), try reach.ownDropped(gpa, spelled.local(&ast, &typing, "byte"), spelled.named(&ast, "open")));
    }

    /// Whether `held` discharges the bound `trait` names, arg-blind: whatever
    /// the arguments, not at the specific ones a written bound names.
    ///
    /// One question with three askers: the type a call through a trait
    /// settled `Self` to, what an editor may offer after a dot, and an
    /// operator's demand for a trait the language rather than a bound names.
    /// Either an implementation exists, or a promise was already made about
    /// the parameter it is -- and a copy of this that knew only about
    /// implementations refused a bounded generic passing its parameter to
    /// another bounded generic, which is the whole of what a bound is for.
    ///
    /// A type argument checked against a written bound's own arguments is a
    /// fourth asker with a mutable pool in hand, since finding an
    /// implementation generic over its own head substitutes through it --
    /// `Checker.discharges` answers that one directly, through the same
    /// `Builder.implementationRow` used to settle a call's body, and falls
    /// back to this reader only where there is no argument to discharge at.
    pub fn discharges(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        trait: TokenId,
    ) std.mem.Allocator.Error!bool {
        return self.answers(gpa, held, traitAt(self.ast, self.res, trait) orelse return false);
    }

    /// `discharges`, from the trait's declaration rather than from a bound
    /// that names one.
    ///
    /// What a comparison asks: the operator names a trait the prelude
    /// declares, and no bound is written anywhere for it to read. One routine,
    /// so `a < b` admits exactly the types a bound naming `Comparable` admits.
    pub fn answers(
        self: Reach,
        gpa: std.mem.Allocator,
        held: TypeId,
        declared: node.DeclId,
    ) std.mem.Allocator.Error!bool {
        if (rendersDisplayItself(self.typing, self.display, held, declared)) return true;
        return self.index.any(gpa, self.impls, self.typing, declared.index(), held, self.scope, .forward);
    }
};

// Makes every test build compile the tests `Reach` holds, including a build
// filtered to one of them, which would otherwise never look inside it.
comptime {
    _ = Reach;
}

/// What a postfix call written in `from` may reach, over a finished check.
///
/// The other end of what the checker builds mid-pass, so a reader asking an
/// editor what a value can do is asking the routine that decided what the
/// compiler accepted. Everything it needs a check leaves behind: the pool
/// carries the implementations and the index that finds one.
pub fn reachIn(
    ast: *const Ast,
    program: *const Program,
    res: *const Resolution,
    typing: *const Typing,
    from: ModuleId,
    scope: node.DeclId,
) Reach {
    return .{
        .ast = ast,
        .source_program = program,
        .res = res,
        .typing = typing,
        .index = &typing.impl_index,
        .impls = typing.implementations,
        .signatures = typing.decl_signatures,
        .from = from,
        .scope = scope,
        .display = displayDecl(ast, res),
    };
}

/// How a diagnostic writes a type for a reader in module `from`: every
/// declared type in it, arguments included, by the name that module writes,
/// its bare name where the module names it that way and its declaring module's
/// name in front where it does not.
///
/// One routine for every report that names a type to a reader, so two rules
/// cannot write one type two ways. Costs one name lookup per declared type the
/// written name contains.
pub fn writtenTypeName(
    arena: std.mem.Allocator,
    ast: *const Ast,
    program: *const ExpandedProgram,
    res: *const Resolution,
    pool: *const Typing,
    from: ModuleId,
    t: TypeId,
) std.mem.Allocator.Error![]const u8 {
    var out: std.Io.Writer.Allocating = .init(arena);
    writeTypeName(&out.writer, ast, program, res, pool, from, t) catch return error.OutOfMemory;
    return out.toOwnedSlice() catch return error.OutOfMemory;
}

fn writeTypeName(
    w: *std.Io.Writer,
    ast: *const Ast,
    program: *const ExpandedProgram,
    res: *const Resolution,
    pool: *const Typing,
    from: ModuleId,
    t: TypeId,
) std.Io.Writer.Error!void {
    if (pool.instanceOf(t)) |instance| {
        // A tuple is written as its components in parentheses, which is the
        // spelling the pool minted for it; the declaration's name is not what
        // a program writes.
        const tuple = pool.isTupleDecl(instance.decl);
        if (tuple) try w.writeAll("(") else {
            try writeDeclaredName(w, ast, program, res, from, instance.decl);
            try w.writeAll("[");
        }
        for (pool.argsOf(instance), 0..) |arg, i| {
            if (i > 0) try w.writeAll(", ");
            try writeTypeName(w, ast, program, res, pool, from, arg);
        }
        return w.writeAll(if (tuple) ")" else "]");
    }
    switch (pool.get(t)) {
        .array => |a| {
            try w.writeAll("[");
            try writeTypeName(w, ast, program, res, pool, from, a.element);
            return w.print("; {d}]", .{a.count});
        },
        .borrow => |b| {
            try w.writeAll("borrow ");
            return writeTypeName(w, ast, program, res, pool, from, b.referent);
        },
        .struct_, .enum_, .newtype => if (pool.declOfType(t)) |d| return writeDeclaredName(w, ast, program, res, from, d),
        else => {},
    }
    return w.writeAll(pool.nameOf(t));
}

fn writeDeclaredName(
    w: *std.Io.Writer,
    ast: *const Ast,
    program: *const ExpandedProgram,
    res: *const Resolution,
    from: ModuleId,
    d: node.DeclId,
) std.Io.Writer.Error!void {
    const name = ast.declName(d);
    if (from != .none) {
        if (res.typeNamed(from, ast.tokenName(name))) |named| if (named == d) return w.writeAll(ast.tokenText(name));
        const module = program.moduleOf(d);
        if (module != .none and module != from) try w.print("{s}.", .{writableQualifier(ast, program, res, from, module, d)});
    }
    return w.writeAll(ast.tokenText(name));
}

/// The module name a reader in `from` writes before a declaration of `module`:
/// the name of `from`'s import of that module, or of an import that re-exports
/// the declaration publicly, and the declaring module's own name where `from`
/// imports neither.
///
/// **Bound:** the imports `from` writes, once each, and only while a report is
/// being written.
fn writableQualifier(
    ast: *const Ast,
    program: *const ExpandedProgram,
    res: *const Resolution,
    from: ModuleId,
    module: ModuleId,
    d: node.DeclId,
) []const u8 {
    const imports = program.get(from).imports;
    for (imports) |import| {
        if (import.module == module) return ast.tokenText(ast.declName(import.decl));
    }
    const name = ast.tokenName(ast.declName(d));
    for (imports) |import| {
        if (import.module == .none) continue;
        const b = res.namedIn(import.module, name) orelse continue;
        if (res.declaredBy(b) != d or res.isAmbient(b) or res.namingReachOf(b) != .public) continue;
        return ast.tokenText(ast.declName(import.decl));
    }
    return program.get(module).name;
}

test "a type is written with its arguments as the module writes them" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "t.lin", .text =
        \\struct Crate { kilograms: UInt8 }
        \\struct Pair[T] { first: T, second: T }
        \\fn main() -> UInt8 {
        \\    let crates: Pair[[Crate; 2]] = .{ first = [.{ kilograms = 1 }, .{ kilograms = 2 }], second = [.{ kilograms = 3 }, .{ kilograms = 4 }] }
        \\    crates.first[0].kilograms
        \\}
    };
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);

    var crates = BindingId.none;
    for (0..res.resolution.bindingCount()) |i| {
        const b = BindingId.at(@intCast(i));
        const token = res.resolution.declaringToken(b);
        if (token != .none and std.mem.eql(u8, res.expanded.ast.tokenText(token), "crates")) crates = b;
    }
    try testing.expect(crates != BindingId.none);
    const written = try writtenTypeName(gpa, &res.expanded.ast, &res.expanded, &res.resolution, &typing, .from(0), typing.bindingType(crates));
    try testing.expectEqualStrings("Pair[[Crate; 2]]", written);
}

/// Every implementation the program declares, by the trait and the type it
/// relates.
///
/// Built once, from the declarations, and read by everything that wants an
/// implementation. It is not a cache of a lookup done elsewhere -- there is no
/// elsewhere: this is where the question is answered, and a bound and a call
/// both read the answer rather than each working it out.
fn collectImplementations(
    gpa: std.mem.Allocator,
    ast: *const Ast,
    program: *const ExpandedProgram,
    res: *const Resolution,
    pool: anytype,
) ![]types_mod.Implementation {
    var out: std.ArrayList(types_mod.Implementation) = .empty;
    errdefer out.deinit(gpa);

    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        if (ast.declTag(d) != .impl_ or !program.isActive(d)) continue;
        // An inherent `impl` names a head and no trait, and a head is what
        // `Self` and the head's own parameters are read off -- so it gets a row
        // the same way, under the trait no declaration has. Left out, an
        // inherent head had no answer here and the resolver's had nothing to
        // agree with.
        const t = ast.declTrait(d);
        const trait: u32 = if (t == TokenId.none)
            types_mod.Implementation.no_trait
        else
            @intCast((traitAt(ast, res, t) orelse continue).index());
        const m = program.moduleOf(d);
        if (m == .none) continue;

        // A builtin head is its own type. Nothing declares one, so there is no
        // declaration for the table of declared names to answer with -- which
        // is a branch in the routine that says which implementation this is,
        // and not a second routine saying it differently.
        const written_head = ast.declHead(d);
        const head = written_head.at;
        var names: ?node.DeclId = null;
        const parameter_head = ast.declHasParameterHead(d);
        // A callable head of too many parameters was refused where it was
        // written, and has no shape to key a row by.
        if (written_head.kind == .callable and ast.callableShape(written_head) == null) continue;
        // A tuple head applies the prelude's declaration of its arity to its
        // components, which is the declaration the resolver keyed the head
        // under. An arity the prelude does not publish was reported there,
        // and names nothing here either.
        const ty: TypeId = if (written_head.kind == .borrow or written_head.kind == .callable or parameter_head)
            .poison
        else if (written_head.kind == .tuple) blk: {
            names = res.tupleDecl(written_head.args.len()) orelse continue;
            break :blk pool.typeOfDecl(names.?) orelse continue;
        } else if (ast.tokenTag(head) == .l_paren)
            .unit
        else
            res.builtinNamed(m, ast.tokenName(head)) orelse blk: {
                const named = res.typeNamed(m, ast.tokenName(head)) orelse continue;
                names = named;
                break :blk pool.typeOfDecl(names.?) orelse continue;
            };

        // A head applying arguments answers for instantiations of what it
        // names, and one applying none answers for the type it names. That is
        // the same sentence a type answers with when it is looked up, read from
        // the side that has a written head rather than an interned type.
        const applies = ast.declHead(d).args.len() > 0;
        try out.append(gpa, .{
            .trait = trait,
            .head = if (ast.declIsDefault(d)) .default_ else if (parameter_head) .parameter else if (written_head.kind == .borrow) .borrow_ else if (written_head.kind == .callable) .{ .callable_ = ast.callableShape(written_head).? } else if (applies and names != null)
                .{ .applied = names.? }
            else
                .{ .whole = ty },
            .ty = ty,
            .decl = d,
            .derived = program.originOf(d) != null,
            .parameters = @intCast(ast.declTypeParams(d).len),
        });
    }
    // The declarations are read in order, so the rows come out in it. Asserted
    // because `suppliedBy` searches on it, and a row appended out of order
    // would make that a wrong answer rather than a slow one.
    for (out.items, 0..) |row, i| {
        if (i > 0) std.debug.assert(out.items[i - 1].decl.index() < row.decl.index());
    }

    // After every written row, so the search above still runs over a list in
    // declaration order: an ambient row's `decl` is above every declaration
    // there is, so it sits past the end of what that search can reach.
    try appendAmbient(gpa, ast, res, pool, &out);
    return out.toOwnedSlice(gpa);
}

/// The implementations the compiler provides, appended to the ones the program
/// writes.
///
/// A primitive cannot implement these in Linea: a body written with `<` is
/// `Comparable.less` and calls itself. They are rows in the one list every
/// other implementation is a row of, found through the one index, so a bound
/// and a call reach them the way they reach a written implementation and
/// nothing has a second table to consult.
///
/// Which pairs they are is the resolver's answer, taken as it stands: it
/// settles which declaration each prelude name is, and it holds every written
/// header against these rows, so a row seeded here from the spellings again
/// could be one nothing was ever held against.
///
/// **Bound:** what the resolver recorded, which is the traits it names times
/// the primitives each runs over -- a constant of the language and not of the
/// program -- and one interned type where any of them is for arrays.
fn appendAmbient(
    gpa: std.mem.Allocator,
    ast: *const Ast,
    res: *const Resolution,
    pool: anytype,
    out: *std.ArrayList(types_mod.Implementation),
) std.mem.Allocator.Error!void {
    // The type standing for the array constructor's family.
    //
    // Every row carries one: a reader asking what a row's family is like --
    // whether some member of it owes nothing, and what that member implements
    // -- asks it of this type, and a head naming a declaration or a type has
    // one already. A constructor's family has no member in the pool until a
    // program writes one, so the row names a member that answers both
    // questions the way the family does: an array owes nothing where its
    // element owes nothing, and every array reaches the same implementations
    // whatever it holds and however long it is.
    //
    // Interned here, beside the rows, so what a row stands for is decided
    // where the row is made and no reader works it out again -- and only
    // where an array row exists at all, so a program compiled without the
    // library gains no type it never wrote.
    const array_witness: TypeId = blk: {
        for (res.ambient_impls) |provided| switch (provided.over) {
            .array => break :blk try pool.arrayOf(.u8, 1),
            .primitive => {},
        };
        break :blk .poison;
    };

    const index_trait = preludeDecl(ast, res, "Index");
    const array_element_member = traitMemberNamed(ast, res, index_trait, "Elem") orelse .none;
    for (res.ambient_impls) |provided| {
        // What the row supplies, as types. A primitive is one already; a type
        // the library declares is named by the resolver and interned here,
        // through the routine every prelude name goes through -- so a row and
        // an expression that mention `FromEnd` mean the declaration the
        // prelude published and not two types that happen to share a spelling.
        const supplied = try gpa.alloc(TypeId, provided.args.len);
        errdefer gpa.free(supplied);
        var named = true;
        for (provided.args, supplied) |arg, *into| {
            into.* = try providedType(gpa, ast, res, pool, arg) orelse {
                named = false;
                break;
            };
        }
        // A row whose argument no library declares is a row nothing could ask
        // for. Left out rather than seeded with poison, so a program compiled
        // without the library reaches the answer a head with no implementation
        // gets rather than one keyed on a type that stands for nothing.
        if (!named) {
            gpa.free(supplied);
            continue;
        }

        try out.append(gpa, .{
            .trait = @intCast(provided.trait.index()),
            // Owned by the row, as every other row's arguments are: the list
            // is freed per row, and a row pointing at what the resolver named
            // would be freed twice.
            .args = supplied,
            .head = switch (provided.over) {
                .primitive => |t| .{ .whole = t },
                .array => .array,
            },
            .ty = switch (provided.over) {
                .primitive => |t| t,
                .array => array_witness,
            },
            .decl = .none,
            .ambient = true,
            .viewed = provided.viewed,
            .array_element_member = if (provided.over == .array and index_trait != null and provided.trait == index_trait.?) array_element_member else .none,
        });
    }
}

/// One argument of a row the compiler provides, as a type -- `null` where no
/// library declares the name it is written with.
///
/// A primitive is a type already; a name is the declaration the prelude
/// published, interned through the routine every prelude name goes through; and
/// an application is that declaration instantiated at its own arguments, read
/// the same way. So a row and an expression that mention `Range[UInt64]` mean
/// one type and not two that happen to share a spelling.
///
/// An instantiation minted here is minted before any part is resolved, and its
/// parts are filled from the finished template by the refill every early
/// instantiation goes through -- what it is depends only on the declaration and
/// the arguments, both of which are settled by now.
fn providedType(
    gpa: std.mem.Allocator,
    ast: *const Ast,
    res: *const Resolution,
    pool: anytype,
    arg: resolve_mod.ProvidedArg,
) std.mem.Allocator.Error!?TypeId {
    switch (arg) {
        .primitive => |t| return t,
        .prelude => |name| {
            const decl = preludeDecl(ast, res, name) orelse return null;
            return pool.typeOfDecl(decl);
        },
        .applied => |a| {
            const decl = preludeDecl(ast, res, a.name) orelse return null;
            const template = pool.typeOfDecl(decl) orelse return null;

            const args = try gpa.alloc(TypeId, a.args.len);
            defer gpa.free(args);
            for (a.args, args) |written, *into| {
                into.* = try providedType(gpa, ast, res, pool, written) orelse return null;
            }
            return try pool.instantiate(template, decl, args);
        },
    }
}

/// What a trait asks for at one member, and what an implementation supplies
/// there.
///
/// One question, asked of either side by the walk that pairs them: what a
/// trait declares and what an implementation supplies are members of the same
/// three kinds, and a reader deciding it twice could decide it differently.
const MemberKind = enum {
    /// A signature and the body that answers it: something a call runs.
    operation,
    /// A projection and the path that answers it: a place a bracket names.
    projection,
    /// A declared type and the type that settles it.
    declared_type,

    /// What it is called in a message about the pair.
    fn noun(self: MemberKind) []const u8 {
        return switch (self) {
            .operation => "an operation",
            .projection => "a projection",
            .declared_type => "a type",
        };
    }
};

/// Which of the three a declaration is.
///
/// Exhaustive, with no `else`, so a member form added to the language says
/// which kind it is before the build succeeds. Everything that is not written
/// inside a trait or an implementation reads as an operation and is never
/// asked: a constant in an `impl` is the one such form, and no trait declares
/// one for it to be paired against.
fn memberKind(ast: *const Ast, d: node.DeclId) MemberKind {
    return switch (ast.declTag(d)) {
        .associated_type => .declared_type,
        .projection => .projection,
        .function,
        .constant,
        // A traversal answers no trait, so nothing pairs one against a
        // signature and this is never read for it.
        .traversal_,
        .enum_,
        .struct_,
        .newtype,
        .alias,
        .import_,
        .use_,
        .impl_,
        .template_impl,
        .derive_impl,
        .trait_,
        .err,
        => .operation,
    };
}

/// Whether a member of a trait or of an implementation is a type rather than
/// something with parameters and a result.
fn settlesAType(ast: *const Ast, d: node.DeclId) bool {
    return memberKind(ast, d) == .declared_type;
}

/// How much access a mode grants, as an order.
///
/// `read` observes, `inout` may write what it observes, and `sink` takes the
/// value away -- each strictly more than the one before it. What this is for
/// is the one place a mode is a ceiling rather than a requirement: a
/// projection's receiver, where the trait states a maximum and an
/// implementation may state less. `sink` sits above the maximum any trait
/// declares, which is why moving an element out through a projection is
/// refused by this comparison rather than by a rule of its own.
pub fn accessGranted(c: node.Convention) u8 {
    return switch (c) {
        .read => 0,
        .inout => 1,
        .sink => 2,
    };
}

/// Whether a declaration answers a trait's question rather than asking one.
///
/// A body for a signature, and a type for a declared one. A declaration
/// carrying neither supplies nothing whatever it is named: `type Item` with
/// nothing after it asks the trait's question a second time, and a function
/// with no body is a signature wherever it is written.
///
/// One question, because both ends of the pairing ask it -- the walk looking
/// for the member that answers a signature, and the walk looking for the
/// signature nothing answers. Two readings of it would disagree about the
/// declaration neither side was written for.
///
/// Exhaustive, with no `else`, so a member form added to the language says
/// which of the two it is before the build succeeds.
fn suppliesSomething(ast: *const Ast, d: node.DeclId) bool {
    return switch (ast.declTag(d)) {
        // A projection answers with a body for the reason a function does: the
        // trait writes the header and the implementation writes what is behind
        // it, whether that is code to run or a path to take.
        .function, .projection => ast.declBody(d) != ExprId.none,
        .associated_type => ast.declReturnRef(d).wasWritten(),
        // A trait declares operations and types, so nothing else answers one.
        // A constant is the form this is worth saying about: an implementation
        // may hold one, and a newtype is the same shape one level up -- neither
        // is reachable inside a trait's or an implementation's braces, so
        // nothing here ever asks this question of one, but the switch is
        // exhaustive regardless of what is reachable.
        .constant, .traversal_, .enum_, .struct_, .newtype, .alias, .import_, .use_, .impl_, .template_impl, .derive_impl, .trait_, .err => false,
    };
}

/// Whether a declaration written inside a trait asks for something rather than
/// answering it.
///
/// A member carrying a body is an operation the trait provides, which no
/// implementation supplies, or a projection body the parser already refused;
/// neither asks an implementation for anything.
fn asksForSomething(ast: *const Ast, d: node.DeclId) bool {
    return ast.declBody(d) == ExprId.none;
}

/// Whether a value of this type is reached by address rather than held in a
/// register.
///
/// A free function over whichever pool minted the type, for the reason
/// `reportOversizedTypes` is one: the checker's is not the only pool, and
/// lowering interns the instantiations a generic body reaches.
pub fn livesInMemoryIn(builder: *const Typing.Builder, t: TypeId) bool {
    if (t == .poison) return false;
    return builder.layoutOf(t).isAggregate();
}

/// Remainder excludes floating-point operands; other arithmetic checks use
/// the same declaration-level integer evidence as conversions and literals.
fn remainderHoldsIn(t: TypeId) bool {
    return t != .f64;
}

/// The fix a reader needs where an operator's operand type refuses it.
///
/// A newtype's refusal is the one with somewhere to go: the base is behind a
/// pattern, and the operator is defined there.
fn operandHint(builder: *const Typing.Builder, t: TypeId) ?[]const u8 {
    if (builder.get(t) == .newtype) return "a name over a base does not inherit its operators: take the value apart to reach them";
    if (builder.get(t) == .array) return "an array compares through its elements, so their type must implement the trait";
    return null;
}

/// Reports every type in `builder` at or after `from` whose width crosses what
/// [L-Size] allows.
///
/// A free function rather than a step of this pass, because a width is decided
/// by whichever pool minted the type and the checker's is not the only one:
/// lowering interns the instantiations a generic body reaches, and asks this of
/// the range it added. Asking where the checker happened to finish left those
/// unasked, and a width that stopped at the limit then reached the backend as a
/// slot smaller than the value it holds.
///
/// Which declaration a type came from is asked of the pool, which answers for
/// a declared type and for an instantiation alike -- so a caller minting only
/// instantiations needs to hand over nothing extra to be reported properly.
pub fn reportOversizedTypes(
    sink: *Sink,
    program: *const ExpandedProgram,
    builder: *const Typing.Builder,
    from: u32,
) !void {
    const ast = &program.ast;
    var next = from;
    while (builder.nextOversized(next)) |t| {
        next = @intFromEnum(t) + 1;

        // A declared type is reported where it is declared, and an
        // instantiation at the declaration it was made from: an instantiation
        // is written wherever it is named, and every one of those places is
        // the same type.
        const at: Loc = if (builder.view().declOfType(t)) |i|
            .{ .file = ast.fileOfDecl(i), .span = ast.declNameSpan(i) }
        else
            .{ .file = program.source.primaryFile(), .span = Span.empty };

        try sink.addErrorFmt(
            .l_size,
            at.file,
            at.span,
            "hold fewer parts, or nest them less deeply",
            "a type is at most {d} bytes wide, and `{s}` is wider",
            .{ types_mod.Layout.max_size, builder.nameOf(t) },
        );
    }
}

/// Whether a pattern is the catch-all.
///
/// The bare `_` and nothing else. `_()` is a call whose callee is `_`, a shape
/// the grammar does not spell -- a pattern's binder list holds at least one
/// name -- and reading the text without the tag made it the catch-all in three
/// passes and not in the fourth. The checker closed the variant cover, lowering
/// jumped into the arm unconditionally, and ownership did not ask what the arm
/// discarded, so a `Key` inside the value was gone with no diagnostic, on one
/// character of spelling.
///
/// Asking is a function rather than a tag test at each site that cares, which
/// is what the routine below is for as well.
pub fn isCatchAll(ast: *const Ast, pattern: ExprId) bool {
    if (pattern == ExprId.none) return false;
    if (ast.exprTag(pattern) != .name_ref) return false;
    return std.mem.eql(u8, ast.tokenText(ast.exprMain(pattern)), "_");
}

/// The prelude declaration with this name, or null where it publishes none.
pub fn preludeDecl(ast: *const Ast, res: *const Resolution, name: []const u8) ?node.DeclId {
    return resolve_mod.preludeDeclIn(ast, res.prelude, name);
}

/// Whether an expression names a variant.
///
/// `Colour.Red` is a selection whose left side is a type, and `.Red` takes its
/// enum from context. The two are different shapes and one thing, so asking is
/// a function rather than a tag test at each site that cares.
pub fn namesAVariant(ast: *const Ast, res: *const Resolution, id: ExprId) bool {
    return resolve_mod.namesAVariant(res, ast, id);
}

/// The base a field expression selects from, groups stripped on both sides.
/// One derivation, exported: what a selection's base *is* must have one
/// answer, and the caller that re-derived it privately is how such answers
/// drift.
pub fn fieldBase(ast: *const Ast, id: ExprId) ExprId {
    return ast.withoutGroups(ast.unaryOperand(ast.withoutGroups(id)));
}

/// Whether an expression selects a name from a value rather than from a
/// namespace.
///
/// The two are told apart by what is on the left, because that is what decides
/// who could have diagnosed a name that is not there. A namespace's names are
/// known to the resolver, which reports its own; a value's are its type's, and
/// nothing before the checker can say.
///
/// A left side that reaches nothing is not a value. Only a bare name can be
/// unresolved -- anything else is an expression, and an expression has a value
/// -- and a bare name reaching nothing is a namespace the tree cannot see: a
/// caller holding one file without the library beside it finds no binding for
/// a name the prelude publishes, and reading that as a value would claim the
/// left side is something this tree never looked at.
pub fn selectsFromAValue(ast: *const Ast, res: *const Resolution, id: ExprId) bool {
    const at = ast.withoutGroups(id);
    if (ast.exprTag(at) != .field) return false;

    return resolve_mod.baseNamesAValue(res, ast, fieldBase(ast, id));
}

/// Whether a call's callee is written `x.name`, the postfix form, which reaches
/// an operation of `x`'s type and never a field.
///
/// Parentheses around the selection make it a value before it is called:
/// `(x.name)()` reads the field `name` and calls what it holds. Parentheses
/// around the receiver alone, `(x).name()`, leave the postfix form intact.
pub fn isPostfixCallee(ast: *const Ast, res: *const Resolution, callee: ExprId) bool {
    return callee != ExprId.none and ast.exprTag(callee) == .field and selectsFromAValue(ast, res, callee);
}

test "isPostfixCallee reads the callee as written" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "t.lin", .text =
        \\struct Door {
        \\    width: fn() -> UInt8,
        \\}
        \\
        \\fn three() -> UInt8 {
        \\    3
        \\}
        \\
        \\fn main() -> UInt8 {
        \\    let door: Door = .{ width = three }
        \\    let _one = (door.width)()
        \\    let _two = (door).width()
        \\    three()
        \\}
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const resolved = try resolveTree(gpa, &ast, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);

    var postfix: usize = 0;
    var value: usize = 0;
    for (0..ast.exprCount()) |i| {
        const id = ExprId.at(@intCast(i));
        if (ast.exprTag(id) != .call) continue;
        if (isPostfixCallee(&ast, &resolved.resolution, ast.call(id).callee)) postfix += 1 else value += 1;
    }
    try testing.expectEqual(@as(usize, 1), postfix);
    try testing.expectEqual(@as(usize, 2), value);
}

/// The receiver a call written `&x.op(args)` lends to its operation, or none
/// where the call lends no receiver.
///
/// `&` on a postfix call marks the receiver, the place the operation's first
/// parameter writes through, exactly as `&x` marks an argument. On any other
/// call it marks the callable place invoked, `&callback(args)` and
/// `&(x.field)(args)`, which is no receiver. Every pass asking which place a
/// marked call lends reads this.
///
/// `&x.name[T](args)` is spelled the same whether `name` is a method, whose
/// receiver the call lends, or a field whose element it invokes. Only the
/// checker's answer tells them apart, so the caller says whether the call
/// reached an operation with its type arguments written:
/// `NormalizedCall.written_type_arguments`.
pub fn lentReceiver(ast: *const Ast, res: *const Resolution, call: ExprId, names_type_arguments: bool) ExprId {
    if (!ast.callMarked(call)) return ExprId.none;
    var callee = ast.call(call).callee;
    if (res.bracketReading(callee) != null) {
        if (!names_type_arguments) return ExprId.none;
        callee = postfixSelection(ast, callee);
    }
    if (!isPostfixCallee(ast, res, callee)) return ExprId.none;
    return fieldBase(ast, callee);
}

/// The selection `x.name` of a call that reached an operation through the
/// postfix form. Where the operation's type arguments are written,
/// `x.name[T](...)`, the callee is the bracket and the selection is in front
/// of it. Parentheses around the whole callee are left out.
pub fn postfixSelection(ast: *const Ast, callee: ExprId) ExprId {
    const written = ast.withoutGroups(callee);
    if (written != ExprId.none and ast.exprTag(written) == .index and ast.bracketTypes(written) != null) return ast.binary(written).lhs;
    return written;
}

test "postfixSelection is the selection in front of an operation's type arguments" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "t.lin", .text =
        \\fn main() -> UInt8 {
        \\    let a = "1".parse[UInt8]()
        \\    let b = "2".length()
        \\    0
        \\}
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    const ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var selections: usize = 0;
    for (0..ast.exprCount()) |i| {
        const id = ExprId.at(@intCast(i));
        if (ast.exprTag(id) != .call) continue;
        const selected = postfixSelection(&ast, ast.call(id).callee);
        try testing.expectEqual(node.Expr.Tag.field, ast.exprTag(selected));
        selections += 1;
    }
    try testing.expectEqual(@as(usize, 2), selections);
}

/// The expression naming what a call reached: its callee, or the name in
/// front of the brackets where the callee was written with type arguments.
pub fn calleeName(ast: *const Ast, call: types_mod.NormalizedCall) ExprId {
    const callee = ast.call(call.at).callee;
    return if (call.written_type_arguments) ast.binary(callee).lhs else callee;
}

test "calleeName is the name in front of a call's type arguments" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "t.lin", .text =
        \\fn same[T](sink value: T) -> T {
        \\    value
        \\}
        \\
        \\fn main() -> UInt8 {
        \\    same[UInt8](3) + same(4)
        \\}
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const resolved = try resolveTree(gpa, &ast, &sink);
    const typing = try typecheckTree(gpa, &resolved, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);

    var named: usize = 0;
    for (typing.calls) |call| {
        const name = calleeName(&ast, call);
        try testing.expectEqual(node.Expr.Tag.name_ref, ast.exprTag(name));
        try testing.expectEqualStrings("same", ast.tokenText(ast.exprMain(name)));
        named += 1;
    }
    try testing.expectEqual(@as(usize, 2), named);
}

test "lentReceiver is the receiver of a marked postfix call" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "t.lin", .text =
        \\struct Door {
        \\    width: UInt8,
        \\    open: fn() -> UInt8,
        \\}
        \\
        \\impl Door {
        \\    fn widen(inout self: Self) {
        \\        self.width += 1
        \\    }
        \\
        \\    fn stretch[T](inout self: Self, _by: T) {
        \\        self.width += 1
        \\    }
        \\}
        \\
        \\fn three() -> UInt8 {
        \\    3
        \\}
        \\
        \\fn main() -> UInt8 {
        \\    var door: Door = .{ width = 1, open = three }
        \\    &door.widen()
        \\    &(door).widen()
        \\    &door.stretch[UInt8](1)
        \\    door.widen()
        \\    &(door.open)()
        \\}
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const resolved = try resolveTree(gpa, &ast, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);

    var lent: usize = 0;
    var unlent: usize = 0;
    for (0..ast.exprCount()) |i| {
        const id = ExprId.at(@intCast(i));
        if (ast.exprTag(id) != .call) continue;
        const receiver = lentReceiver(&ast, &resolved.resolution, id, ast.exprTag(ast.call(id).callee) == .index);
        if (receiver == ExprId.none) {
            unlent += 1;
            continue;
        }
        lent += 1;
        try testing.expectEqual(node.Expr.Tag.name_ref, ast.exprTag(receiver));
        try testing.expectEqualStrings("door", ast.tokenText(ast.exprMain(receiver)));
    }
    try testing.expectEqual(@as(usize, 3), lent);
    try testing.expectEqual(@as(usize, 2), unlent);
}

/// What `impl_of_decl` holds for a declaration no implementation encloses.
const impl_of_none = types_mod.Typing.no_implementation;

const namesSelf = resolve_mod.namesSelf;

/// Whether a written type is `Self` itself, rather than something written off
/// it.
///
/// `Self.Item` begins with the same token and is not that type: it is whatever
/// an implementation settled `Item` to, which is a type of its own. Asked
/// wherever a reader means "this position holds the trait's own type" -- an
/// argument standing there settles `Self`, and an argument standing at a
/// settled reference settles nothing, because what it is, is decided by the
/// implementation the call has yet to reach.
fn refNamesSelf(ast: *const Ast, written: node.TypeRef) bool {
    const ref = ast.withoutTypeGroups(written);
    return ref.kind == .named and namesSelf(ast, ref.name);
}

/// The first settled reference headed by `Self` anywhere inside a written
/// type, or null where it holds none.
///
/// Asked of the whole thing rather than of its head: `Option[Self.Item]` is a
/// settled reference one level in, and a reader that looked only at the head
/// would find the constructor and stop.
///
/// **Bound:** the written type's own arguments, which are the tokens it
/// occupies.
fn selectionStartsWithSelf(ast: *const Ast, written: node.TypeRef) bool {
    var ref = ast.withoutTypeGroups(written);
    while (ref.kind == .selection) ref = ast.withoutTypeGroups(ast.selectionBase(ref));
    return refNamesSelf(ast, ref);
}

fn firstSelfSettledRef(ast: *const Ast, ref: node.TypeRef) ?node.TypeRef {
    if (ref.kind == .selection) {
        if (selectionStartsWithSelf(ast, ref)) return ref;
        if (firstSelfSettledRef(ast, ast.selectionBase(ref))) |found| return found;
    }
    if (ref.kind == .callable) {
        const callable = ast.callableType(ref);
        for (ast.params[callable.params.start..callable.params.end]) |param| {
            if (firstSelfSettledRef(ast, param.written)) |found| return found;
        }
        if (firstSelfSettledRef(ast, callable.result)) |found| return found;
    }
    for (ast.typeArgs(ref.args)) |a| {
        if (firstSelfSettledRef(ast, a)) |found| return found;
    }
    return null;
}

/// Whether a parameter declares a value for the calls that leave it out.
///
/// The one spelling of the question. Both pairings ask it to decide whether an
/// unfilled parameter is a mistake, and the fold asks it to decide whether
/// there is an expression to work out -- three readings of one fact, which is
/// exactly the shape that drifts when the fact grows a second condition.
fn hasDefault(p: node.Param) bool {
    return p.default != ExprId.none;
}

/// Whether a member's parameter is named what the signature's is.
///
/// Interned, so the answer is one comparison of two numbers wherever the two
/// spellings agree, which is every parameter of every implementation that is
/// well formed.
///
/// A leading `_` on the member's side is read as the marker it is rather than
/// as part of the name: a member that does not use a value it takes is obliged
/// to mark it -- [N-Unused] admits no other spelling, and a `read` parameter
/// has nothing a body could do with the value instead -- so held to the
/// spelling exactly, an implementation ignoring one of its arguments would have
/// no legal way to be written at all.
///
/// The signature's side is read letter for letter, and the two are not the same
/// question. A signature has no body to leave a value unused in, and its
/// spelling is what every call that names the parameter writes -- so a marker
/// there is part of the name rather than a note about a body, and a member
/// dropping it names something no call does.
fn namedAlike(ast: *const Ast, want: TokenId, got: TokenId) bool {
    if (ast.tokenName(want) == ast.tokenName(got)) return true;
    return std.mem.eql(u8, ast.tokenText(want), unmarked(ast.tokenText(got)));
}

/// A name without the `_` that marks it deliberately unused.
fn unmarked(text: []const u8) []const u8 {
    return if (std.mem.startsWith(u8, text, "_")) text[1..] else text;
}

/// A source template member's template and the trait signature it supplies.
const TemplatePairing = struct { template: DeclId, signature: DeclId };

/// A parameter's declared type, or poison where none was parsed. Read in the
/// module that declared the function, which is not always the one calling it.
fn paramType(c: *Checker, owner: node.DeclId, index: usize) !TypeId {
    // Trait signatures resolve Self and associated types in the call's
    // context, which is a different reading of the written type at each call.
    // Every other declaration keeps the one type its parameter was declared
    // with, a template member's read with the template's open `Self`.
    if (c.ast.declIsSignature(owner))
        return c.typeOfRefOf(c.program.moduleOf(owner), owner, c.ast.declParams(owner)[index].written);
    return c.declaredParamType(owner, index);
}

/// What a direct call yields, read from the declaration rather than from a
/// contextual function value's structural type.
fn returnType(c: *Checker, d: node.DeclId) !TypeId {
    // A trait signature's result is read in the call's context, where `Self`
    // and its projections stand for the call's receiver. Every other
    // declaration keeps the one result type it was declared with.
    if (c.ast.declIsSignature(d))
        return c.declResultOf(c.program.moduleOf(d), d);
    if (c.ast.declIsTest(d) and !c.ast.declReturnRef(d).wasWritten()) {
        if (c.default_test_result) |settled| return settled;
        const failure = c.program.libraryDeclIn("testing", "Failure") orelse return .poison;
        const result = c.result_decl orelse return .poison;
        const made = try c.builder.instantiate(c.type_of_decl.get(result), result, &.{ .unit, c.type_of_decl.get(failure) });
        c.default_test_result = made;
        return made;
    }
    return c.declaredResultType(d);
}

/// A type the surrounding context requires, and where that requirement is
/// written.
///
/// A mismatch reports both. "expected `UInt8`" is only actionable next to the
/// place that asked for a `UInt8`, and that place is almost never the expression
/// the error is reported at.
const SuccessExpectation = struct {
    target: ExprId,
    depth: u32,
    expected: Expected,
};

const FailureExpectation = struct {
    target: ExprId,
    depth: u32,
    expected: TypeId,
};

/// What a postfix call expects of its result, handed to its receiver.
///
/// `recv.name(…)` whose result is expected to be `E` constrains `recv` through
/// `name`'s signature: the receiver's call settles what it left open by
/// reading `name`'s result on the receiver's type against `E`. `success` is
/// the method call's own success context, as `?` or `else` hand it one.
const MethodExpectation = struct {
    target: ExprId,
    name: StringId,
    expected: ?Expected,
    success: ?SuccessExpectation,
};

const Expected = struct {
    ty: TypeId,
    /// Where the annotation, return type or conversion that imposed it was
    /// written. A `Loc` rather than a `Span`: an expectation travels from the
    /// declaration that set it into bodies that may be in another file.
    at: Loc,
    reason: Reason,
    unit_test_success: bool = false,
    /// A generic callable bound supplies context while preserving the value's
    /// intrinsic signature or unique closure type.
    callable_context: bool = false,
    /// The function whose generic callable bound supplied this context, which
    /// a report about how the callback is called names.
    callee: node.DeclId = .none,
    /// Parameter context is complete; the lambda body determines its result.
    infer_lambda_result: bool = false,
    inference: ?[]const Checker.Settling = null,
    /// The alias the expectation was written as, where one was: the report
    /// then says what the alias names beside the annotation that wrote it.
    alias: node.DeclId = .none,
    /// For a call's argument, the receiver the call was made on, so a
    /// mismatch can say where the receiver's type came from.
    receiver: ExprId = .none,
    /// For a call's argument, the declaration the call reaches, so a
    /// mismatch can name the partner that takes an allocator.
    passed_to: node.DeclId = .none,

    const Reason = enum {
        return_type,
        /// A function that writes no result, which therefore returns `()`.
        omitted_result,
        annotation,
        conversion,
        /// The other arm of a conditional, which settled the type first.
        arm,
        /// The other side of a binary operation. Operands must agree, and the
        /// left one settles the type, so it is what a mismatch points at.
        operand,
        /// The binding being assigned, whose type the value must have.
        assignment,
        /// A `break` that settled the loop's type before this one.
        break_site,
        /// The `while` this `break` leaves, which is always Unit.
        while_loop,
        /// The parameter an argument is passed to.
        parameter,
        /// The variant being built, whose payload type the value must have.
        payload,
        /// The field being given, whose type the value must have.
        field,
        /// The element of an unannotated array literal that settled what
        /// the array holds.
        element,
        /// The structure literal a `..base` ends, whose type the base must
        /// have.
        update_base,
        /// The other end of a range, which settled the type first.
        range_end,
        /// The construct this condition belongs to. The type is fixed by the
        /// language rather than written anywhere, so what a mismatch points at
        /// is the `if`, `while` or operator requiring one.
        condition,
        /// The bracket a bare number was written in. An index counts elements,
        /// so a literal with no type of its own takes the one the position
        /// gives it -- which is what decides the trait argument the bracket
        /// looks an implementation up by.
        index_position,
        /// The bracket over a container indexed by exactly one integer type,
        /// which a literal with no type of its own takes as its key.
        index_key,
        /// The caret a count back from the end was written after. It counts
        /// places from the end the way an index counts them from the start,
        /// so what it counts by is a `UInt64` wherever it has no type of its
        /// own.
        from_end_count,
        /// The message operand of `panic`, which the language fixes to `Str`.
        panic_message,
        /// The `else` of a `let … else`, whose block leaves or supplies the
        /// value a success would have.
        unwrapped,

        fn describe(self: Reason) []const u8 {
            return switch (self) {
                .return_type => "expected because of this return type",
                .omitted_result => "this function writes no result type, so it returns `()`",
                .annotation => "expected because of this annotation",
                .conversion => "expected because of this conversion",
                .arm => "expected because of this arm",
                .operand => "expected because of this operand",
                .assignment => "expected because of this binding",
                .break_site => "expected because of this `break`",
                .while_loop => "a `while` yields `()`, whatever its body",
                .parameter => "expected because of this parameter",
                .payload => "expected because of what this variant carries",
                .field => "expected because of this field",
                .element => "this element settles what the array holds",
                .update_base => "a base has the type of the literal it ends",
                .range_end => "expected because of this end",
                .condition => "a condition must be a `Bool`",
                .index_position => "an index counts elements, so a bare number is a `UInt64`",
                .index_key => "this container is indexed by one integer type, which a bare number takes",
                .from_end_count => "a count back from the end counts elements, so it is a `UInt64`",
                .panic_message => "a panic message has type `Str`",
                .unwrapped => "an `else` block leaves, or yields what a success carries",
            };
        }
    };

    /// The type alone, for the checks that compare without reporting.
    fn typeOf(self: ?Expected) ?TypeId {
        return if (self) |e| e.ty else null;
    }
};

/// How a name that reaches something other than a value is described.
const NotAValue = struct {
    /// What the name reaches, read into "`x` is _, and _ is not a value".
    noun: []const u8,
    /// What to write instead, on the label under the name.
    hint: []const u8,
};

/// The words for a name in value position that names something else, or null
/// where it does name a value.
///
/// Decided by what the name reaches rather than by how it is spelled, so a
/// primitive and a declared type answer alike and neither needs a case of its
/// own. Four kinds carry a value; every other one names a thing -- a
/// function, a type, a trait, a module -- and a thing is not something an
/// expression can evaluate to.
///
/// A constant is on the value side. It is a name bound to a value, and where
/// it is written changes who can reach it and nothing about what it is.
fn notAValue(kind: resolve_mod.Kind) ?NotAValue {
    if (resolve_mod.kindIsAValue(kind)) return null;
    return switch (kind) {
        .local, .parameter, .capture, .binder, .constant => unreachable,
        .function => .{
            .noun = "a function",
            .hint = "call it, or name what it returns",
        },
        .declared_type, .builtin_type => .{
            .noun = "a type",
            .hint = "name a value of that type",
        },
        .associated_type => .{
            .noun = "a type a trait declares",
            .hint = "name a value of the type an implementation settles it to",
        },
        .type_parameter => .{
            .noun = "a type parameter",
            .hint = "name a value of the type supplied for it",
        },
        .type_alias => .{
            .noun = "an alias of a type",
            .hint = "name a value of the type it names",
        },
        .trait => .{
            .noun = "a trait",
            .hint = "reach an operation through it, or name a value",
        },
        .module => .{
            .noun = "a module",
            .hint = "name something the module declares",
        },
    };
}

/// What a name reached by selecting out of a type or a trait is, where a
/// value belongs and the name is not one.
///
/// A narrower question than `notAValue`, and narrower on purpose. A type or a
/// trait standing to the left of the dot is the namespace being selected
/// from, and the selection is what it holds -- so a selection whose target is
/// one of those is `Colour.Red` naming a variant, not a type named where a
/// value belongs. What a namespace holds and no value can be is an operation
/// and a type a trait declares.
///
/// Answers for a module reached this way too, but the caller does not ask it
/// there: the caller's own question is not what kind of namespace stands to
/// the left of the dot, but whether the selection settled on that base's own
/// binding -- which is what a variant reference does and a module member
/// never does, so a module reaching this function never happens.
///
/// Exhaustive, with no `else`, so a kind of name added to the language says
/// which side of this it falls on before the build succeeds.
fn memberNotAValue(kind: resolve_mod.Kind) ?NotAValue {
    return switch (kind) {
        .function, .associated_type, .type_parameter, .type_alias => notAValue(kind),
        .local, .parameter, .capture, .binder, .constant => null,
        .declared_type, .builtin_type, .trait, .module => null,
    };
}

/// An expression that leaves, and where it is written.
const Leave = struct {
    /// The index of its first token, which is what orders these and what a
    /// containing extent is compared against.
    at: u32,
    id: ExprId,
    /// How it is named in the message, so the search answers with the word as
    /// well as the place.
    what: []const u8,
};

/// A traversal and the implementation that declares it.
///
/// The row travels with the member because finding a traversal by the type it
/// is written on says nothing about whether that implementation covers the
/// instantiation a walk names -- `impl Pair[UInt8]` declares one, and a
/// `Pair[Int64]` reaches it by the same head.
const Traversal = struct {
    member: node.DeclId,
    row: u32,
};

const Constraints = @import("constraints.zig").Constraints;

const CheckedTemplateRequirement = struct {
    trait: DeclId = .none,
    args: []const TypeId = &.{},
    valid: bool = false,
};

/// A written type with every alias heading it replaced by what the alias
/// wrote, whether the alias is named bare or after the module declaring it.
/// Bounded by the aliases there are, since a cycle among them was refused.
///
/// The one walk down an alias chain: the labels a call through a value names
/// its arguments by and the function type a callable bound names both read it.
fn writtenThroughAliases(ast: *const Ast, res: *const Resolution, written: node.TypeRef) node.TypeRef {
    var at = ast.withoutTypeGroups(written);
    var steps: usize = 0;
    while ((at.kind == .named or at.kind == .selection) and steps <= ast.declCount()) : (steps += 1) {
        const alias = res.aliasReachedBy(at.name) orelse break;
        at = ast.withoutTypeGroups(ast.declReturnRef(alias));
    }
    return at;
}

/// Where the labels a call through a value names its arguments by were
/// written: the type written where the value was declared, a callable bound,
/// a kept closure's signature argument, or the function or lambda a local was
/// bound to. One reading, asked by the argument matcher while checking and by
/// an editor describing a value afterwards.
pub const LabelSources = struct {
    ast: *const Ast,
    res: *const Resolution,
    typing: Typing,
    binding_types: *const types_mod.BindingTypes,
    field_names: *const std.AutoHashMapUnmanaged(TokenId, types_mod.FieldIdentity),
    binding_labels: *const std.AutoHashMapUnmanaged(BindingId, node.ParamRange),

    /// A written type with every alias heading it replaced by what the alias
    /// wrote, so a function type named through an alias keeps its labels.
    fn throughAliases(self: LabelSources, written: node.TypeRef) node.TypeRef {
        return writtenThroughAliases(self.ast, self.res, written);
    }

    /// The labels a call through a value of type `ty`, declared with the
    /// written type `written`, uses. Null where the written type names none.
    pub fn ofWritten(self: LabelSources, given: node.TypeRef, ty: TypeId) ?[]const node.Param {
        const written = self.throughAliases(given);
        if (written.kind == .callable) {
            const range = self.ast.callableTypeById(written.callable).params;
            return self.ast.params[range.start..range.end];
        }
        if (ty == .poison) return null;
        switch (self.typing.get(ty)) {
            .parameter => |parameter| {
                const owner = node.DeclId.at(parameter.owner);
                const parameters = self.ast.declTypeParams(owner);
                if (parameter.index >= parameters.len) return null;
                for (self.ast.boundsOf(parameters[parameter.index])) |bound| {
                    if (bound.kind == .callable) return self.ofWritten(self.ast.callableRef(bound.callable), .poison);
                    if (self.res.aliasReachedBy(bound.named.name)) |alias| {
                        const aliased = self.throughAliases(self.ast.declReturnRef(alias));
                        if (aliased.kind == .callable) return self.ofWritten(aliased, .poison);
                    }
                }
                return null;
            },
            else => {},
        }
        const origin = self.typing.instanceOf(ty) orelse return null;
        if (self.typing.raw_accesses.closure == .none or origin.decl != self.typing.raw_accesses.closure) return null;
        const args = self.ast.typeArgs(written.args);
        if (args.len == 0) return null;
        return self.ofWritten(args[0], .poison);
    }

    /// The labels a call through `callee` names its arguments by. Null
    /// where nothing declared any, and the call passes them by position.
    pub fn ofCallee(self: LabelSources, callee: ExprId) ?[]const node.Param {
        const at = self.ast.withoutGroups(callee);
        switch (self.ast.exprTag(at)) {
            .lambda => return self.ast.lambda(at).params,
            // A copy is the value it copies, labels included.
            .copy_ => return self.ofCallee(self.ast.unaryOperand(at)),
            .name_ref, .field => {},
            else => return null,
        }
        const target = self.res.targetOf(at);
        if (target == BindingId.none) {
            // A field read from a value: the names its declaration wrote.
            if (self.ast.exprTag(at) != .field) return null;
            const selected = self.field_names.get(self.ast.exprMain(at)) orelse return null;
            const declaration = self.typing.declOfType(selected.receiver) orelse return null;
            const fields = self.ast.declFields(declaration);
            if (selected.field.index() >= fields.len) return null;
            return self.ofWritten(fields[selected.field.index()].written, self.typing.fieldType(selected.receiver, selected.field.index()));
        }
        return switch (self.res.kindOf(target)) {
            .function => self.ast.declParams(self.res.declaredBy(target)),
            .parameter => blk: {
                const params = switch (self.res.parameterOwner(target)) {
                    .declaration => |owner| self.ast.declParams(owner),
                    .closure => |owner| self.ast.lambda(self.res.closures.exprOf(owner)).params,
                };
                const index = self.res.paramIndexOf(target);
                if (index >= params.len) break :blk null;
                break :blk self.ofWritten(params[index].written, self.binding_types.get(target));
            },
            .local, .capture, .binder => if (self.binding_labels.get(target)) |range| self.ast.params[range.start..range.end] else null,
            else => null,
        };
    }
};

const Checker = struct {
    const CallableDefaultSite = struct {
        module: ModuleId,
        owner: node.DeclId,
        expr: ExprId,
        parameter: TokenId,
        convention: node.Convention,
        ty: TypeId,
    };

    gpa: std.mem.Allocator,
    retained: ?*const RetainedTyping = null,
    program: *const ExpandedProgram,
    raw_accesses: RawAccesses,
    float_math_candidates: FloatMath,
    float_math: FloatMath = .{},
    ast: *const Ast,
    constraints: *const Constraints,
    /// Resolved subjects, position for position with `constraints.records`.
    constraint_subjects: []TypeId,
    // Producing scopes for final value roots. These scratch tables let the
    // checker freeze scoped capabilities before ownership or tooling reads them.
    expression_owners: []DeclId,
    binding_owners: []DeclId,
    contextual_constraints: types_mod.ContextualConstraints = .{},
    /// Which module the walk is inside, so a bare type name is looked up in
    /// the declarations that can actually see it.
    current: ModuleId = .none,
    /// The declaration whose type parameters are in scope. `.none` outside a
    /// generic one, which is every declaration written before this stage.
    generic: node.DeclId = node.DeclId.none,
    /// What `Self` stands for while a call through a trait is being checked.
    /// Null everywhere else, including inside an implementation, where `Self`
    /// is the type the `impl` names and needs nothing settled.
    ///
    /// A call reaches a signature, which is written in terms of a type it does
    /// not name; the argument names it. Held on the checker rather than passed
    /// down because every read of a written type goes through one routine, and
    /// threading it through each caller would put a parameter meaning "not
    /// applicable" on all of them.
    self_at_call: ?TypeId = null,
    /// Whether `self_at_call` is a `Self` a call or an implementation settled,
    /// rather than the signature's own symbolic one. A signature's written
    /// types are then read at that type, and what they read there is not what
    /// their tokens stand for in the declaration, so nothing is recorded
    /// against them (`recordWritten`).
    self_settled: bool = false,
    /// The inactive template member whose `Self` is being compared with its
    /// trait signature. The type itself is held in `self_at_call`, so both
    /// sides pass through the ordinary written-type reader.
    symbolic_self_owner: node.DeclId = .none,
    /// Each declaration's type parameters as pool entries, by declaration
    /// index. Interned before any body is walked, for the reason declared
    /// types are: an annotation may name one anywhere in the declaration.
    /// Every expression in the program that leaves, ordered by where it is
    /// written. Built the first time a `defer` asks; see `findTheLeaves`.
    leaves: std.ArrayList(Leave) = .empty,
    leaves_built: bool = false,
    param_types: []const []const TypeId = &.{},
    /// The first type parameter of each name in each declaration. Built once
    /// over the AST, so resolving the O(n) annotations of one n-parameter
    /// declaration does not rescan that same parameter row O(n) times.
    type_param_slots: std.AutoHashMapUnmanaged(u64, u32) = .empty,
    /// Which body each call through a trait runs, by call site.
    call_impls: std.ArrayList(types_mod.CallImpl) = .empty,
    /// The implementations refused as overlapping another. What such an
    /// implementation fails to supply is not reported: the overlap is the
    /// mistake, and every member the refused implementation lacks would say
    /// it again.
    overlapping: std.AutoHashMapUnmanaged(node.DeclId, void) = .empty,
    /// The one complete semantic row for each accepted direct call.
    calls: std.ArrayList(types_mod.NormalizedCall) = .empty,
    recovered_call_args: std.ArrayList(types_mod.RecoveredCallArg) = .empty,
    recovered_calls: std.ArrayList(types_mod.RecoveredCall) = .empty,
    function_values: std.ArrayList(types_mod.FunctionValue) = .empty,
    /// The function values named without a written type in the bodies being
    /// checked, innermost last. Each leaves when its body closes, so the list
    /// holds what the open bodies named rather than what the program does.
    pending_values: std.ArrayList(PendingValue) = .empty,
    /// The parameters whose names a call through a local or a capture uses:
    /// those of the type written where it was declared, or of what its
    /// initializer names. One entry per such binding that holds a callable.
    binding_labels: std.AutoHashMapUnmanaged(BindingId, node.ParamRange) = .empty,
    constructor_count: u32 = 0,
    /// Position in `calls` per expression, or `no_call`.
    call_of: []u32 = &.{},
    /// Whether this expression already retained its rejected-call rows.
    recovery_of: []bool = &.{},
    /// Every implementation the program declares, by trait and type.
    implementations: []const types_mod.Implementation = &.{},
    /// The index over them, handed to the typing with the list it indexes.
    impl_index: types_mod.ImplIndex = .{},
    /// Every member an implementation supplies, paired with what its trait
    /// declared, in the order the implementations were read.
    supplied: std.ArrayList(types_mod.Supplied) = .empty,
    /// The pairs above, reachable from either side. Built once the pairing walk
    /// has finished and before any body is checked, because a settled reference
    /// written in a signature or a body is read through it.
    supply: types_mod.SupplyIndex = .{},
    /// Which implementation each declaration sits inside, as a row of
    /// `implementations`. `Absent` for everything outside one.
    ///
    /// One entry per declaration, filled by walking each implementation's own
    /// extent -- so `Self` inside a member is answered by a step rather than
    /// by a search for the `impl` that encloses it.
    impl_of_decl: []const u32 = &.{},
    /// The implementation row named by each implementation declaration.
    /// Dense in declarations because provenance admission starts from a
    /// generated `DeclId` and must not search the implementation list.
    row_of_impl: []const u32 = &.{},
    /// Validated bounds grouped by source template requirement. The checker
    /// owns these rows and their argument slices; no requirement cache crosses
    /// into `Typing`.
    checked_template_requirements: [][]CheckedTemplateRequirement = &.{},
    /// Templates with an invalid member or malformed requirement. Descriptors
    /// naming one are suppressed even when no component row exposes the error.
    invalid_templates: std.AutoHashMapUnmanaged(DeclId, void) = .empty,
    /// Generated implementation headers retained as poisoned lookup evidence
    /// while their member bodies are skipped for semantic recovery.
    suppressed_generated_implementations: std.AutoHashMapUnmanaged(DeclId, void) = .empty,
    /// Records the components a derived `Release` discards rather than
    /// releases. Each is discardable and not proven to implement `Release`
