    refused_parts: std.ArrayList(TokenId) = .empty,
    res: *const Resolution,
    sink: *Sink,
    builder: Typing.Builder,
    folds: @import("../support/table.zig").Table(ExprId, Fold),
    literal_values: std.AutoHashMapUnmanaged(ExprId, types_mod.LiteralValue) = .empty,
    /// Integer literal types no use has settled yet, one entry per literal
