    const Written = struct { at: ExprId, refused: []const u8 };

    /// A loop being checked, and what its exits have settled so far.
    ///
    /// Break sites agree by the rule that governs every other pair of types
    /// that must meet: the first settles it and the rest are checked against
    /// it, reporting at the one that differs and pointing at the one that
    /// decided. A `while` starts already settled to Unit, so `break 1` inside
    /// one is rejected by that same path rather than by a rule of its own.
    const Loop = struct {
        settled: ?Expected,
        /// Whether any `break` was seen. A `loop` with none does not complete,
        /// so it produces no value rather than producing Unit.
        broke: bool,
        /// Whether any `break` carried a value. What a `for` yields turns on
        /// it: one that only ever leaves early carries nothing out, and
        /// `Option[()]` would be a value naming two states a walk does not
        /// have.
        carried: bool = false,
        /// Whether a `return` or a `?` written in the body can leave this loop.
        /// One leaves the function, so it leaves every loop between itself and
        /// the function, which is why every frame records it where a `break`
        /// records only the frame it targets.
        ///
        /// Read together with `broke` by a walk that moves values out of places
        /// one at a time: either is control leaving before the last place, and
        /// what is left behind is the same either way.
        unwound: bool = false,
        /// Whether a `break` carried a value already refused. The loop's type
        /// is then unknown rather than Unit, so nothing downstream reports
        /// it again as a second mistake.
        poisoned: bool = false,
    };

    /// The type an annotation token names: a builtin, or one the program
    /// declared.
    ///
    /// The parser cannot tell the two apart — a declared type is an identifier
    /// — so it records the token and this answers it, which is the same
    /// division that makes a name's meaning the resolver's business rather
    /// than the grammar's.
    fn isRetained(self: *const Checker, decl: DeclId) bool {
        const prefix = self.retained orelse return false;
        return decl != .none and decl.index() < prefix.seed.declarations.len and prefix.seed.declarations[decl.index()];
    }

    fn retainAnswers(self: *Checker, prefix: *const RetainedTyping) !void {
        const saved = &prefix.typing;
        const gpa = self.gpa;
        @memcpy(self.binding_types.entries[0..saved.binding_types.len()], saved.binding_types.entries);
        @memcpy(self.decl_returns.entries[0..saved.decl_returns.len()], saved.decl_returns.entries);
        @memcpy(self.decl_signatures.entries[0..saved.decl_signatures.len()], saved.decl_signatures.entries);
        @memcpy(self.written_types[0..saved.written_types.len], saved.written_types);
        @memcpy(self.expression_owners[0..prefix.seed.expression_owners.len], prefix.seed.expression_owners);
        @memcpy(self.binding_owners[0..prefix.seed.binding_owners.len], prefix.seed.binding_owners);
        for (prefix.seed.declarations, 0..) |checked, i| self.defaults_folded[i] = checked;
        for (0..saved.binding_types.len()) |i| self.constant_taken[i] = self.res.kindOf(BindingId.at(@intCast(i))) == .constant;
        inline for (.{ "literal_values", "conversion_targets", "integer_properties", "selected_places", "place_projections", "implicit_test_successes", "try_conversions", "field_names", "type_selections", "contract_variants", "readonly_places", "carried_places", "borrowed_temporaries", "interpolation_positions", "refused", "folded_indices", "constant_values", "field_name_spellings", "variant_uses", "contract_parameters", "traversal_positions", "binding_labels" }) |field| {
            @field(self, field) = try @field(saved, field).clone(gpa);
        }
        var plans = saved.constant_materializations.iterator();
        while (plans.next()) |entry| {
            const fields = try gpa.dupe(types_mod.FieldOrdinal, entry.value_ptr.fields);
            errdefer gpa.free(fields);
            try self.constant_materializations.put(gpa, entry.key_ptr.*, .{ .fields = fields, .variant = entry.value_ptr.variant });
        }
        self.defaults.values = try saved.defaults.values.clone(gpa);
        inline for (.{ "calls", "recovered_call_args", "recovered_calls", "function_values", "postfix", "named", "projected", "traversals", "expansions", "range_places" }) |field| {
            for (@field(saved, field)) |row| try @field(self, field).append(gpa, try copyRetained(gpa, row));
        }
        for (prefix.seed.call_impls) |call| try self.call_impls.append(gpa, try copyRetained(gpa, call));
        for (self.projected.items) |projection| try self.projected_at.put(gpa, ExprId.at(projection.at), projection.expansion);
        for (self.expansions.items, 0..) |expansion, i| {
            if (expansion.delegation) |forward| if (forward.field == null) continue;
            const implementation = if (expansion.delegation != null) expansion.member else self.res.implEnclosing(expansion.member);
            if (implementation != .none) try self.expansion_of_impl.put(gpa, implementation, @intCast(i));
        }
        for (self.calls.items, 0..) |call, i| self.call_of[call.at.index()] = @intCast(i);
        for (self.function_values.items) |value| if (value.target == .constructor) {
            self.constructor_count = @max(self.constructor_count, @intFromEnum(value.target.constructor.id) + 1);
        };
        for (saved.closures, self.closure_descriptors[0..saved.closures.len]) |descriptor, *target| {
            gpa.free(target.owned_fields);
            target.* = try copyRetained(gpa, descriptor);
        }
    }

    fn typeOfToken(self: *const Checker, tok: TokenId) TypeId {
        return self.typeOfTokenIn(self.current, tok);
    }

    fn parameterBounds(self: *const Checker, d: node.DeclId, index: usize) []const node.TraitBound {
        return self.constraints.parameterBounds(self.ast, d, index);
    }

    fn boundsOnParameter(self: *const Checker, held: TypeId) []const node.TraitBound {
        return switch (self.builder.get(held)) {
            .parameter => |p| self.parameterBounds(node.DeclId.at(p.owner), p.index),
            else => &.{},
        };
    }

    /// Resolves every normalized constraint subject and records each complete
    /// promise once, with one link to the declaration's enclosing generic scope.
    fn resolveConstraints(self: *Checker) std.mem.Allocator.Error!void {
        const starts = try self.gpa.alloc(u32, self.ast.declCount() + 1);
        errdefer self.gpa.free(starts);
        const parents = try self.gpa.alloc(node.DeclId, self.ast.declCount());
        errdefer self.gpa.free(parents);
        const capability_scopes = try self.gpa.alloc(node.DeclId, self.ast.declCount());
        errdefer self.gpa.free(capability_scopes);
        @memset(capability_scopes, .none);
        var contextual: std.ArrayList(types_mod.ContextualConstraint) = .empty;
        errdefer {
            for (contextual.items) |constraint| {
                types_mod.freeBoundTraits(self.gpa, constraint.demand.traits);
                if (constraint.demand.callables.len > 0) self.gpa.free(constraint.demand.callables);
            }
            contextual.deinit(self.gpa);
        }

        // Resolve first because members are allocated before the impl that
        // encloses them, while their bodies inherit that impl's predicates.
        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            for (self.ast.declWherePredicates(d)) |predicate| {
                if (!predicate.subject.wasWritten()) continue;
                if (self.unreadTemplateSubject(d, predicate.subject)) continue;
                if (self.whereSubjectDependsOnOpen(d, predicate.subject)) continue;
                try self.sink.addError(
                    .t_where,
                    self.ast.fileOf(predicate.subject.at),
                    self.ast.writtenSpan(predicate.subject),
                    "a `where` predicate constrains an open type",
                    "this subject depends on no type parameter in scope",
                );
            }
            const range = self.constraints.rangeOfDeclaration(d);
            // A trait signature's `where` subject may name `Self` and what its
            // implementation settles; it is read over the signature's symbolic
            // `Self`, as its bounds are, and a call reads it at its own.
            self.self_at_call = if (range.len() > 0 and self.ast.declIsSignature(d)) try self.signatureSelfType(d) else null;
            defer self.self_at_call = null;
            for (range.start..range.end) |at| {
                const constraint = self.constraints.records[at];
                const resolved = switch (constraint.subject) {
                    .parameter => |index| if (i < self.param_types.len and index < self.param_types[i].len)
                        self.param_types[i][index]
                    else
                        .poison,
                    .written => |subject| try self.typeOfRefOf(self.program.moduleOf(d), d, subject),
                };
                self.constraint_subjects[at] = resolved;
            }
        }

        var promised: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
        defer promised.deinit(self.gpa);
        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            starts[i] = @intCast(contextual.items.len);
            promised.clearRetainingCapacity();
            const enclosing = self.res.implEnclosing(d);
            parents[i] = if (enclosing != .none and enclosing != d)
                enclosing
            else
                self.traitDeclaring(d) orelse node.DeclId.none;

            const range = self.constraints.rangeOfDeclaration(d);
            for (range.start..range.end) |at| {
                const resolved = self.constraint_subjects[at];
                if (resolved == .poison) continue;

                const constraint = self.constraints.records[at];
                const requirements = self.constraints.requirementsOf(constraint);
                if (requirements.len == 0) continue;
                switch (constraint.subject) {
                    // Each `Owned` the clause writes is a promise, so one
                    // written twice in a list is refused as one written in
                    // two clauses is.
                    .written => |written| for (requirements) |requirement| {
                        if (requirement.kind != .named) continue;
                        if (resolve_mod.boundNames(self.ast, requirement.named.name, traitAt(self.ast, self.res, requirement.named.name)) != .owned) continue;
                        try self.promiseWrittenOwned(d, written, resolved, requirement.named.name, &promised);
                    },
                    .parameter => {},
                }
                const context: BoundInterning = .{ .module = self.program.moduleOf(d), .owner = d };
                const traits = try self.traitsBounding(context, requirements);
                errdefer types_mod.freeBoundTraits(self.gpa, traits);
                const callables = try self.callablesBounding(context, requirements, traits);
                errdefer if (callables.len > 0) self.gpa.free(callables);
                try contextual.append(self.gpa, .{
                    .subject = resolved,
                    .demand = .{
                        .traits = traits,
                        .callables = callables,
                        .requirement = capabilityDemandedBy(self.ast, self.res, requirements, traits),
                        .integer = integerDemandedBy(self.ast, self.res, requirements, traits),
                        .owned = ownedBound(self.ast, self.res, requirements) != null,
                    },
                });
            }
        }
        starts[self.ast.declCount()] = @intCast(contextual.items.len);
        for (capability_scopes, 0..) |*scope, index| {
            for (contextual.items[starts[index]..starts[index + 1]]) |constraint| {
                if (constraint.demand.requirement == .unrestricted) continue;
                scope.* = node.DeclId.at(@intCast(index));
                break;
            }
        }
        for (capability_scopes, parents) |*scope, parent| {
            if (scope.* != .none or parent == .none) continue;
            if (capability_scopes[parent.index()] == parent) scope.* = parent;
        }
        const items = try contextual.toOwnedSlice(self.gpa);
        self.contextual_constraints = .{
            .starts = starts,
            .parents = parents,
            .capability_scopes = capability_scopes,
            .items = items,
        };
        self.builder.setContextualConstraints(self.contextual_constraints);
    }

    /// Reads again each `where` subject that was left a stand-in because the
    /// implementation defining it had not been settled when constraints were
    /// resolved: `I.Iter` under `I: Iterator` is `I` once the parameter-headed
    /// `Sequence` implementation answers, and a fact written about `I.Iter`
    /// is then a fact about `I`, which is what the body reads `I.Iter` as.
    /// Keyed facts are replaced where their subject changed, and the lookups
    /// that read them are cleared.
    ///
    /// **Bound:** one reading per `where` subject whose first reading was a
    /// stand-in.
    fn resettleConstraintSubjects(self: *Checker) std.mem.Allocator.Error!void {
        const items = @constCast(self.contextual_constraints.items);
        var changed = false;
        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            const range = self.constraints.rangeOfDeclaration(d);
            if (range.len() == 0) continue;
            var item: usize = if (i < self.contextual_constraints.starts.len) self.contextual_constraints.starts[i] else continue;
            self.self_at_call = if (self.ast.declIsSignature(d)) try self.signatureSelfType(d) else null;
            defer self.self_at_call = null;
            for (range.start..range.end) |at| {
                const resolved = self.constraint_subjects[at];
                const constraint = self.constraints.records[at];
                // The same records `resolveConstraints` kept, in its order.
                if (resolved == .poison or self.constraints.requirementsOf(constraint).len == 0) continue;
                defer item += 1;
                const written = switch (constraint.subject) {
                    .written => |subject| subject,
                    .parameter => continue,
                };
                if (self.builder.standinOf(resolved) == null) continue;
                const settled = try self.typeOfRefOf(self.program.moduleOf(d), d, written);
                if (settled == resolved or settled == .poison) continue;
                self.constraint_subjects[at] = settled;
                items[item].subject = settled;
                changed = true;
                // A promise holds for what the subject now reads as.
                if (ownedBound(self.ast, self.res, self.constraints.requirementsOf(constraint)) != null and self.ownsSubject(d, settled))
                    self.builder.promiseOwned(settled);
            }
        }
        if (changed) self.builder.setContextualConstraints(self.contextual_constraints);
    }

    /// Resolution reads a template member only when it plans the template, so
    /// a subject it never reached belongs to a template it refused and
    /// reported; the name is no evidence of an open type.
    fn unreadTemplateSubject(self: *const Checker, d: node.DeclId, ref: node.TypeRef) bool {
        const enclosing = self.res.implEnclosing(d);
        if (enclosing == .none or self.ast.declTag(enclosing) != .template_impl) return false;
        return ref.kind == .named and self.res.writtenAt(ref.name) == .none;
    }

    fn whereSubjectDependsOnOpen(self: *const Checker, d: node.DeclId, ref: node.TypeRef) bool {
        if (self.mentionsTypeParameter(d, ref)) return true;

        const enclosing = self.res.implEnclosing(d);
        if (enclosing != .none and enclosing != d and self.mentionsTypeParameter(enclosing, ref)) return true;

        const trait = if (self.ast.declTag(d) == .trait_)
            d
        else
            self.traitDeclaring(d) orelse node.DeclId.none;
        if (self.writtenTypeMentionsSelf(ref)) {
            if (trait != .none) return true;
            const implementation = if (self.ast.declTag(d) == .impl_) d else enclosing;
            return implementation != .none and self.ast.declTypeParams(implementation).len != 0;
        }
        return trait != .none and trait != d and self.mentionsTypeParameter(trait, ref);
    }

    fn writtenTypeMentionsSelf(self: *const Checker, ref: node.TypeRef) bool {
        if (ref.kind == .callable) {
            const callable = self.ast.callableType(ref);
            for (self.ast.params[callable.params.start..callable.params.end]) |param| {
                if (self.writtenTypeMentionsSelf(param.written)) return true;
            }
            return self.writtenTypeMentionsSelf(callable.result);
        }
        if (ref.kind == .selection and self.writtenTypeMentionsSelf(self.ast.selectionBase(ref))) return true;
        if (resolve_mod.namesSelf(self.ast, ref.name)) return true;
        for (self.ast.typeArgs(ref.args)) |arg| {
            if (self.writtenTypeMentionsSelf(arg)) return true;
        }
        return false;
    }

    fn selfConstraintAtImplementation(
        self: *Checker,
        implementation: node.DeclId,
        receiver: TypeId,
        ref: node.TypeRef,
    ) std.mem.Allocator.Error!TypeId {
        if (refNamesSelf(self.ast, ref)) return receiver;
        if (ref.kind != .selection or !selectionStartsWithSelf(self.ast, ref)) return .poison;

        const named = ref.name;
        const member = self.memberNamed(named) orelse return .poison;
        const row = self.rowFor(implementation) orelse return .poison;
        return try self.builder.settledBy(row.*, member, self.param_types[implementation.index()]) orelse .poison;
    }

    /// A written type: a head, and the arguments it was given.
    ///
    /// The head resolves as it always did; the arguments turn a template into
    /// an instantiation. Naming a generic type with the wrong number of them,
    /// or giving arguments to one that takes none, is [T-Bound] -- one rule,
    /// because both ask whether what was supplied is what the parameter list
    /// admits.
    fn typeOfRef(self: *Checker, ref: node.TypeRef) !TypeId {
        return self.typeOfRefOf(self.current, self.generic, ref);
    }

    /// The type a callable's written result names. One that writes none
    /// returns `()`; one the parser began and refused names nothing.
    fn resultOfRef(self: *Checker, m: ModuleId, owner: node.DeclId, ref: node.TypeRef) !TypeId {
        if (ref.wasWritten()) return self.typeOfRefOf(m, owner, ref);
        return if (ref.isOmitted()) .unit else .poison;
    }

    /// What a declaration's written result names. Only a function, a trait's
    /// signature and an `extern` return `()` by writing nothing; a
    /// projection, and a declaration that is not a callable, name nothing.
    fn declResultOf(self: *Checker, m: ModuleId, d: node.DeclId) !TypeId {
        const ref = self.ast.declReturnRef(d);
        if (self.ast.declTag(d) != .function) return self.typeOfRefOf(m, d, ref);
        return self.resultOfRef(m, d, ref);
    }

    /// Resolves representation through the ordinary type reader. The first
    /// visit provides callable shapes; the second records their source effects
    /// after every aggregate's owned parts are available.
    fn fillDeclaredParts(self: *Checker, check_refinements: bool) !void {
        const saved_module = self.current;
        const saved_generic = self.generic;
        defer {
            self.current = saved_module;
            self.generic = saved_generic;
        }
        for (self.program.modules, 0..) |_, mi| {
            self.current = ModuleId.from(mi);
            for (self.program.declsOf(self.current)) |d| {

                // Its own parameters answer while its parts are read: `x: A` in a
                // generic structure names the parameter, not a module-level type
                // that happens to share the letter.
                self.generic = d;
                defer self.generic = node.DeclId.none;

                if (self.ast.declTag(d) == .struct_) {
                    for (self.ast.declFields(d), 0..) |f, k| {
                        self.builder.setFieldType(
                            self.type_of_decl.get(d),
                            @intCast(k),
                            try self.typeOfPart(f.written),
                        );
                    }
                    continue;
                }
                if (self.ast.declTag(d) == .newtype) {
                    const base = try self.typeOfPart(self.ast.declReturnRef(d));
                    self.builder.setNewtypeBase(self.type_of_decl.get(d), base);

                    // Only where a clause was written: an unrefined newtype
                    // admits every value its base does, whatever the base is,
                    // and there is nothing here for [T-Refine] to say.
                    if (check_refinements and self.ast.newtypeRefinement(d) != null and base != .poison) {
                        switch (self.builder.get(base)) {
                            // A clause narrows what the base admits and cannot
                            // reach past it: a bound the base cannot hold names
                            // values no construction could ever supply, so the
                            // contract is a lie whichever door reads it. Asked of
                            // the folded interval rather than of the tokens, so
                            // one test covers both spellings of the range, and
                            // only where that interval exists -- an empty one is
                            // reported where it was folded and has no ends for
                            // this to be about.
                            .integer => {
                                const r = self.builder.refinementOf(self.type_of_decl.get(d));
                                if (r.lo <= r.hi and !(self.builder.holds(base, r.lo) and self.builder.holds(base, r.hi))) {
                                    try self.sink.addErrorFmt(
                                        .t_refine,
                                        self.ast.fileOfDecl(d),
                                        self.ast.declNameSpan(d),
                                        "narrow the range to what the base can hold",
                                        "{d}..={d} reaches outside `{s}`, which `{s}` refines",
                                        .{ r.lo, r.hi, (try self.typeName(base)), self.ast.tokenText(self.ast.declName(d)) },
                                    );
                                }
                            },
                            else => try self.sink.addErrorFmt(
                                .t_refine,
                                self.ast.fileOfDecl(d),
                                self.ast.declNameSpan(d),
                                "only an integer type may be refined",
                                "`{s}` refines `{s}`, which is not an integer type",
                                .{ self.ast.tokenText(self.ast.declName(d)), (try self.typeName(base)) },
                            ),
                        }
                    }
                    continue;
                }
                if (self.ast.declTag(d) != .enum_) continue;

                for (self.ast.declVariants(d), 0..) |v, k| {
                    const carried = self.ast.variantFields(v);
                    if (carried.len == 0) continue;

                    for (carried, 0..) |field, j| {
                        self.builder.setVariantFieldType(
                            self.type_of_decl.get(d),
                            @intCast(k),
                            @intCast(j),
                            try self.typeOfPart(field.written),
                        );
                    }
                }
            }
        }
    }

    /// A written part of a declared type.
    ///
    /// A part refused by [T-PolyRec] or by [T-InfiniteLayout] is answered with
    /// poison rather than resolved, because resolving it is a substitution
    /// that does not terminate or one that mints a type nothing can lay out.
    /// Breaking is not tidying: the declaration keeps the part, and every pass
    /// below here still asks for its layout.
    fn typeOfPart(self: *Checker, ref: node.TypeRef) !TypeId {
        for (self.refused_parts.items) |seen| {
            if (seen == ref.at) return .poison;
        }
        // Whole, not rebuilt from its head and its arguments. An array has no
        // head, so a `TypeRef` reassembled from those two is a named type with
        // no name -- which resolves to poison and says nothing, and a part
        // whose type is poison obliges nothing and is laid out as nothing.
        return self.typeOfRef(ref);
    }

    /// One step of a place, taken from the place inside it.
    const Step = union(enum) {
        /// A field, by its interned name.
        field: StringId,
        observed,
        /// One of what a variant carries, by which variant and which
        /// position: two names bound by one arm are two places, and the same
        /// position of the same variant is one place however often it is
        /// matched.
        carried: struct { variant: u32, index: u32 },
        /// Which element a bracket reached, where the checker settled it, and
        /// null where the number it wrote settles to nothing this pass knows.
        /// A bracket over a container settles to nothing here for a reason of
        /// its own: what it reaches is the implementation's path to decide and
        /// the site's number is not it.
        element: ?i128,

        /// Whether two steps may be the same step.
        ///
        /// Every step but an element is itself or another, and the names are
        /// the whole of the question. Two elements are one unless both settled
        /// and settled apart: a number that reaches this pass unsettled is a
        /// run-time question, and an element nobody can name is held to be
        /// every element -- which is the answer that is wrong in the safe
        /// direction.
        fn conflicts(self: Step, other: Step) bool {
            switch (self) {
                .element => |mine| switch (other) {
                    .element => |theirs| {
                        const a = mine orelse return true;
                        const b = theirs orelse return true;
                        return a == b;
                    },
                    else => return false,
                },
                else => return std.meta.eql(self, other),
            }
        }
    };

    /// What a pattern's name stands for: the place the pattern took apart, and
    /// which part of it. The place is the value the construct lends or takes,
    /// or a pattern nested in its pattern, whose own place `pattern_places`
    /// records; so a binder at any depth is a path of steps to a root.
    const BinderPlace = struct {
        of: ExprId,
        step: Step,
    };

    /// A place a construct is lending, and whether it may be written through.
    ///
    /// Readers share and writers do not: two `read` lends of one place are two
    /// views of what neither changes, while an `inout` lend is the only path
    /// to what it names for as long as it lasts. `at` is the construct, which
    /// is what a reader has to be pointed at.
    const Lend = struct { place: ExprId, writable: bool, at: ExprId };

    /// A written type that named a generic declaration. The instantiation
    /// carries the declaration and the arguments, so nothing beyond where it
    /// was written has to be kept beside it.
    /// A written type whose bounds are asked about later, and the declaration
    /// whose braces it was written in.
    ///
    /// The declaration is carried because the question is not answerable
    /// without it: a bound is discharged by an implementation *or* by the
    /// enclosing declaration's own parameter carrying that bound, and which
    /// declaration is enclosing is exactly what a deferred check has lost.
    ///
    /// Taken from the owner the type was read for rather than from whatever
    /// the checker was walking at the time. They are the same thing where both
    /// exist, and a signature is read before any body is walked -- so reading
    /// the walk would answer "nothing" for exactly the annotations a parameter
    /// appears in.
    /// A written type whose arguments a declaration's bounds must admit.
    /// An instantiation names its declaration through `ty`; an applied alias
    /// has no instantiation of its own, so it names the alias and the run of
    /// `alias_site_args` it was given.
    const BoundSite = struct {
        ty: TypeId,
        at: TokenId,
        within: node.DeclId,
        alias: node.DeclId = .none,
        args_start: u32 = 0,
        args_len: u32 = 0,
    };

    /// One declaration holding another among its parts, and which part holds
    /// it.
    ///
    /// The part travels with the edge because a part this pass refuses holds
    /// nothing: it is answered with poison from here on, so a declaration
    /// reached only through it is not reached at all.
    const Holds = struct { from: node.DeclId, to: node.DeclId, part: u32 };

    /// A type written inside a declaration's braces, and whose braces they
    /// are. A structure's field and an enum's payload are one thing here for
    /// the reason they are one run in the field table.
    const Part = struct {
        m: ModuleId,
        d: node.DeclId,
        ref: node.TypeRef,
    };

    /// Refuses a written part that no substitution and no layout can answer.
    ///
    /// Two questions, one graph. [T-PolyRec] asks whether a part reaches its
    /// own declaration again at a *larger* type argument: such a declaration
    /// stands for infinitely many types, and the substitution that builds them
    /// mints one per level until the stack ends. [T-InfiniteLayout] asks
    /// whether it reaches it again through what it *holds inline*: such a
    /// declaration stands for one type per argument, and every one of them
    /// would have to contain itself.
    ///
    /// Both are asked of the written syntax rather than of resolved types,
    /// because resolving such a part is the walk that diverges -- a check that
    /// reads resolved types runs after the crash it exists to prevent.
    ///
    /// The layout question is asked here, of a declaration with parameters,
    /// rather than left to the cycle among the types the pool minted. An
    /// instantiation rebuilds whatever its template's parts hold, so a cycle
    /// broken where it was minted is built again by the next argument -- and
    /// the program was reported and then laid out anyway, which is a stack
    /// that ends. A declaration with no parameters is one type, and the cycle
    /// among minted types is where that is answered.
    ///
    /// What an implementation settles a declared type to is answered there
    /// too. This reads the written syntax, and a part written as a settled
    /// reference stands for a type the syntax does not name: which argument
    /// closes such a cycle is the implementation's choice, so it is asked of
    /// the minted types once every implementation has settled.
    fn reportRefusedParts(self: *Checker) std.mem.Allocator.Error!void {
        var parts: std.ArrayList(Part) = .empty;
        defer parts.deinit(self.gpa);
        try self.collectParts(&parts);

        // Which parts still hold anything. A part refused below is answered
        // with poison wherever it is read, and the graph loses its edges with
        // it: a cycle that runs through one is a cycle the program no longer
        // has.
        const alive = try self.gpa.alloc(bool, parts.items.len);
        defer self.gpa.free(alive);
        @memset(alive, true);

        // Every declaration a part names, head and arguments alike, which is
        // what resolving it would instantiate.
        var named: std.ArrayList(Holds) = .empty;
        defer named.deinit(self.gpa);
        for (parts.items, 0..) |p, i| try self.noteHeld(&named, p, @intCast(i));

        var mints = try self.holdingOf(named.items, .from, null);
        defer mints.deinit(self.gpa);
        try self.connect(&mints);

        for (parts.items, 0..) |p, i| {
            if (!try self.reportGrowth(&mints, p, p.ref)) continue;
            try self.refused_parts.append(self.gpa, p.ref.at);
            alive[i] = false;
        }

        // A refusal is what the next question is asked after, because a
        // refused part holds nothing: its declaration stops laying out
        // whatever only that part laid out, and a declaration handing itself
        // to a parameter that is no longer held reaches itself no more. Asked
        // once, the walk reports a second declaration whose size the first
        // refusal restored.
        while (try self.reportHeldDeclaration(parts.items, alive, named.items)) {}
    }

    /// Reports the first part that lays out the declaration it sits in, and
    /// says whether it found one.
    ///
    /// What a declaration holds is read here rather than handed in, because
    /// that is what a refusal changes.
    ///
    /// **Bound:** what each declaration holds, the edges its parts write, and
    /// one grouping of the graph -- once per refusal, and a refusal is a
    /// diagnostic, so a program this reports nothing about pays for one.
    fn reportHeldDeclaration(
        self: *Checker,
        parts: []const Part,
        alive: []bool,
        named: []const Holds,
    ) std.mem.Allocator.Error!bool {
        var held = try self.heldParameters(parts, alive, named);
        defer held.deinit(self.gpa);

        // What each part holds inline, in part order -- so the run one part
        // contributes is where it began to where the next did, and the
        // question asked about one part reads its own edges rather than every
        // edge its declaration wrote.
        var inline_holds: std.ArrayList(Holds) = .empty;
        defer inline_holds.deinit(self.gpa);

        const first = try self.gpa.alloc(u32, parts.len + 1);
        defer self.gpa.free(first);

        for (parts, 0..) |p, i| {
            first[i] = @intCast(inline_holds.items.len);
            if (alive[i]) try self.noteHeldInline(&inline_holds, p, @intCast(i), p.ref, held);
        }
        first[parts.len] = @intCast(inline_holds.items.len);

        var holds = try self.holdingOf(inline_holds.items, .from, alive);
        defer holds.deinit(self.gpa);
        try self.connect(&holds);

        var path: std.ArrayList(node.DeclId) = .empty;
        defer path.deinit(self.gpa);

        for (parts, 0..) |p, i| {
            if (!alive[i]) continue;
            if (self.ast.declTypeParams(p.d).len == 0) continue;
            // An alias lays nothing out of its own: a cycle through one is
            // reported at the part of the declaration that names it.
            if (self.ast.declTag(p.d) == .alias) continue;
            if (!holdsAgain(&holds, inline_holds.items[first[i]..first[i + 1]], p.d)) continue;

            path.clearRetainingCapacity();
            try self.cycleThrough(&holds, inline_holds.items[first[i]..first[i + 1]], p.d, &path);

            try self.sink.addErrorFmt(
                .t_infinite_layout,
                self.ast.fileOfDecl(p.d),
                self.ast.tokenSpan(if (p.ref.name != TokenId.none) p.ref.name else p.ref.at),
                "a value would have to hold one, so it has no size",
                "{s}",
                .{try self.spellCycle(p.d, path.items)},
            );
            try self.refused_parts.append(self.gpa, p.ref.at);
            alive[i] = false;
            return true;
        }
        return false;
    }

    /// The declarations a cycle runs through, from the one this part holds
    /// round to the declaration the part sits in.
    ///
    /// Walked only where the grouping has already said there is a cycle, and
    /// only within the group: every declaration in one leads back to every
    /// other, so this finds the way round rather than searching for whether
    /// there is one.
    ///
    /// **Bound:** one visit per declaration of the group and one per edge
    /// leaving it, once per refusal.
    fn cycleThrough(
        self: *Checker,
        holding: *const Holding,
        from: []const Holds,
        to: node.DeclId,
        out: *std.ArrayList(node.DeclId),
    ) std.mem.Allocator.Error!void {
        const group = holding.component[to.index()];

        const start = for (from) |e| {
            if (holding.component[e.to.index()] == group) break e.to;
        } else return;

        if (start == to) {
            try out.append(self.gpa, to);
            return;
        }

        // Which declaration each was reached from, which is also what says it
        // was reached at all.
        const reached_from = try self.gpa.alloc(node.DeclId, holding.component.len);
        defer self.gpa.free(reached_from);
        @memset(reached_from, node.DeclId.none);
        reached_from[start.index()] = start;

        var queue: std.ArrayList(node.DeclId) = .empty;
        defer queue.deinit(self.gpa);
        try queue.append(self.gpa, start);

        // Nearest first, so what a reader is shown is the shortest way round
        // rather than the first the walk wandered into.
        var head: usize = 0;
        outer: while (head < queue.items.len) : (head += 1) {
            const d = queue.items[head];
            for (holding.runs[holding.starts[d.index()]..holding.starts[d.index() + 1]]) |e| {
                const edge = holding.edges[e];
                if (!holding.follows(edge)) continue;
                if (holding.component[edge.to.index()] != group) continue;
                if (reached_from[edge.to.index()] != node.DeclId.none) continue;

                reached_from[edge.to.index()] = d;
                if (edge.to == to) break :outer;
                try queue.append(self.gpa, edge.to);
            }
        }
        if (reached_from[to.index()] == node.DeclId.none) return;

        var at = to;
        while (true) {
            try out.append(self.gpa, at);
            if (at == start) break;
            at = reached_from[at.index()];
        }
        std.mem.reverse(node.DeclId, out.items);
    }

    /// `A contains B contains A`: the cycle a refused part closes, spelled as
    /// the walk over minted types spells one.
    ///
    /// The cycle rather than its near end, and one spelling for both rules: a
    /// reader has to know which edge to break, and the declaration a part sits
    /// in does not say which other declaration leads back to it.
    fn spellCycle(
        self: *Checker,
        d: node.DeclId,
        path: []const node.DeclId,
    ) std.mem.Allocator.Error![]const u8 {
        var how: std.ArrayList(u8) = .empty;
        defer how.deinit(self.gpa);

        try how.appendSlice(self.gpa, self.ast.tokenText(self.ast.declName(d)));
        if (path.len <= 1) {
            try how.appendSlice(self.gpa, " contains itself");
        } else for (path) |step| {
            try how.appendSlice(self.gpa, " contains ");
            try how.appendSlice(self.gpa, self.ast.tokenText(self.ast.declName(step)));
        }
        return self.sink.arena.dupe(u8, how.items);
    }

    /// Which of each declaration's type parameters sit in something it lays
    /// out inline.
    ///
    /// A parameter a declaration merely names is not one it holds: `Mid[T]`
    /// writing `m: Marker[T]` hands `T` to a position `Marker` lays nothing
    /// out at, so a `Mid[S[T]]` holds no `S[T]` and the layout closes. Read as
    /// "named, therefore held", the question above would answer with cycles
    /// the program does not have.
    ///
    /// **Bound:** a part is read again only when a declaration it names gains
    /// a held parameter, and a declaration gains each of its parameters once,
    /// so the whole is the parts plus the names they write times the
    /// parameters those names can gain.
    fn heldParameters(
        self: *Checker,
        parts: []const Part,
        alive: []const bool,
        named: []const Holds,
    ) std.mem.Allocator.Error!Held {
        var held = try self.emptyHeld();
        errdefer held.deinit(self.gpa);

        // Which parts name each declaration, so a declaration that gains a
        // held parameter reaches the parts that could hold one through it
        // without the program being read again.
        var naming = try self.holdingOf(named, .to, null);
        defer naming.deinit(self.gpa);

        // Queue each part once until it is visited. FIFO order lets sibling
        // fields contribute their parameters before a dependent part is read.
        const work = try self.gpa.alloc(u32, parts.len);
        defer self.gpa.free(work);
        const queued = try self.gpa.alloc(bool, parts.len);
        defer self.gpa.free(queued);
        @memset(queued, true);
        for (work, 0..) |*part, i| part.* = @intCast(i);
        var head: usize = 0;
        var tail: usize = 0;
        var pending = parts.len;

        while (pending != 0) {
            const i = work[head];
            head = if (head + 1 == work.len) 0 else head + 1;
            pending -= 1;
            queued[i] = false;
            if (!alive[i]) continue;
            const p = parts[i];
            if (!self.markHeldByPart(p, p.ref, held)) continue;

            const at = p.d.index();
            for (naming.runs[naming.starts[at]..naming.starts[at + 1]]) |e| {
                const dependent = named[e].part;
                if (!alive[dependent] or queued[dependent]) continue;
                work[tail] = dependent;
                tail = if (tail + 1 == work.len) 0 else tail + 1;
                pending += 1;
                queued[dependent] = true;
            }
        }
        return held;
    }

    /// A bit per type parameter of every declaration, saying whether the
    /// declaration lays anything out at it.
    ///
    /// The run is sized by the parameters the declaration itself declares
    /// rather than by a machine word. A word answers for the first
    /// thirty-two positions and has to guess past them, and either guess is
    /// wrong about a program the language admits: guessing "held" refuses a
    /// declaration that has a size, and guessing "not held" lays out one that
    /// does not.
    const Held = struct {
        /// Where each declaration's run of bits begins, with one past the end
        /// of the last.
        starts: []const u32,
        /// One bit per parameter, in those runs.
        bits: []bool,

        /// Whether a declaration lays anything out at one of its parameters.
        /// A position it does not have holds nothing -- an argument written
        /// past the last parameter is an arity mistake, reported where the
        /// type is read.
        fn holds(self: Held, d: node.DeclId, k: usize) bool {
            const run = self.runOf(d);
            if (k >= run.len) return false;
            return run[k];
        }

        /// Records that a declaration lays something out at one of its
        /// parameters, and says whether that was news.
        fn mark(self: Held, d: node.DeclId, k: usize) bool {
            const run = self.runOf(d);
            if (k >= run.len) return false;
            if (run[k]) return false;
            run[k] = true;
            return true;
        }

        fn runOf(self: Held, d: node.DeclId) []bool {
            return self.bits[self.starts[d.index()]..self.starts[d.index() + 1]];
        }

        fn deinit(self: *Held, gpa: std.mem.Allocator) void {
            gpa.free(self.starts);
            gpa.free(self.bits);
        }
    };

    /// A run per declaration, sized by that declaration's parameters, with
    /// nothing held yet.
    fn emptyHeld(self: *Checker) std.mem.Allocator.Error!Held {
        const decls = self.ast.declCount();

        const starts = try self.gpa.alloc(u32, decls + 1);
        errdefer self.gpa.free(starts);

        var total: u32 = 0;
        for (0..decls) |i| {
            starts[i] = total;
            total += @intCast(self.ast.declTypeParams(node.DeclId.at(@intCast(i))).len);
        }
        starts[decls] = total;

        const bits = try self.gpa.alloc(bool, total);
        @memset(bits, false);
        return .{ .starts = starts, .bits = bits };
    }

    /// Which declarations each one holds, and which of them lead back to each
    /// other.
    ///
    /// Built once per question rather than per part: both halves are sized by
    /// the program, and a table sized that way built once per written part is
    /// where a pass becomes the program squared.
    const Holding = struct {
        /// The edges, as the walk reads them.
        edges: []const Holds,
        /// Where each declaration's run of edges begins, with one past the end
        /// of the last.
        starts: []u32,
        /// Which edge each entry of a run is.
        runs: []u32,
        /// Which parts still hold what they name. Null follows every edge,
        /// which is what the graph of what a part *mints* wants: an argument
        /// is minted whether or not anything is laid out at it.
        alive: ?[]const bool,
        /// Which group of mutually reaching declarations each one is in.
        component: []u32,

        /// Whether an edge is one the graph still has.
        fn follows(self: Holding, e: Holds) bool {
            const alive = self.alive orelse return true;
            return alive[e.part];
        }

        fn deinit(self: *Holding, gpa: std.mem.Allocator) void {
            gpa.free(self.starts);
            gpa.free(self.runs);
            gpa.free(self.component);
        }
    };

    /// Which end of an edge a walk reads it from.
    const End = enum { from, to };

    /// The edges as a run per declaration.
    ///
    /// A walk reading the whole list per step costs the program's edges once
    /// per declaration it reaches, and there is a walk per part.
    fn holdingOf(
        self: *Checker,
        edges: []const Holds,
        end: End,
        alive: ?[]const bool,
    ) std.mem.Allocator.Error!Holding {
        const decls = self.ast.declCount();

        const starts = try self.gpa.alloc(u32, decls + 1);
        errdefer self.gpa.free(starts);
        @memset(starts, 0);
        for (edges) |e| starts[endOf(e, end).index() + 1] += 1;
        for (1..decls + 1) |i| starts[i] += starts[i - 1];

        const runs = try self.gpa.alloc(u32, edges.len);
        errdefer self.gpa.free(runs);

        const cursor = try self.gpa.alloc(u32, decls);
        defer self.gpa.free(cursor);
        @memcpy(cursor, starts[0..decls]);

        for (edges, 0..) |e, i| {
            const at = endOf(e, end).index();
            runs[cursor[at]] = @intCast(i);
            cursor[at] += 1;
        }

        // Filled by `connect`, which is what makes the graph answerable.
        const component = try self.gpa.alloc(u32, decls);
        errdefer self.gpa.free(component);
        @memset(component, 0);

        return .{ .edges = edges, .starts = starts, .runs = runs, .alive = alive, .component = component };
    }

    fn endOf(e: Holds, end: End) node.DeclId {
        return switch (end) {
            .from => e.from,
            .to => e.to,
        };
    }

    /// Every type the program writes inside a declaration's braces, gathered
    /// once so the two walks below read one list rather than two copies of
    /// what a declaration's parts are.
    ///
    /// An alias's written type is its one part. A part naming an alias holds
    /// the alias, and the alias holds what it names, so a declaration that
    /// reaches or contains itself through an alias does so through a path in
    /// the same graph a part written out would draw, and each measure below
    /// reads the alias's own parameters where the alias wrote them.
    fn collectParts(self: *Checker, out: *std.ArrayList(Part)) std.mem.Allocator.Error!void {
        for (self.program.modules, 0..) |_, mi| {
            for (self.program.declsOf(ModuleId.from(mi))) |d| {
                switch (self.ast.declTag(d)) {
                    .struct_ => for (self.ast.declFields(d)) |f| {
                        try out.append(self.gpa, .{ .m = ModuleId.from(mi), .d = d, .ref = f.written });
                    },
                    .enum_ => for (self.ast.declVariants(d)) |v| {
                        for (self.ast.variantFields(v)) |f| {
                            try out.append(self.gpa, .{ .m = ModuleId.from(mi), .d = d, .ref = f.written });
                        }
                    },
                    .alias => try out.append(self.gpa, .{ .m = ModuleId.from(mi), .d = d, .ref = self.ast.declReturnRef(d) }),
                    else => {},
                }
            }
        }
    }

    /// Records that `d` holds whatever declarations a written type names,
    /// head and arguments alike.
    ///
    /// Every name, because resolving the part instantiates every one of them:
    /// an argument is minted whether or not the head lays anything out at it.
    fn noteHeld(
        self: *Checker,
        holds: *std.ArrayList(Holds),
        p: Part,
        at: u32,
    ) std.mem.Allocator.Error!void {
        if (p.ref.kind == .callable) {
            const callable = self.ast.callableType(p.ref);
            for (self.ast.params[callable.params.start..callable.params.end]) |param| {
                try self.noteHeld(holds, .{ .m = p.m, .d = p.d, .ref = param.written }, at);
            }
            try self.noteHeld(holds, .{ .m = p.m, .d = p.d, .ref = callable.result }, at);
            return;
        }
        if (self.namesTypeParameter(p.d, p.ref.name)) return;
        if (self.declOfWritten(p.m, p.d, p.ref)) |e| {
            try holds.append(self.gpa, .{ .from = p.d, .to = e, .part = at });
        }
        for (self.ast.typeArgs(p.ref.args)) |a| {
            try self.noteHeld(holds, .{ .m = p.m, .d = p.d, .ref = a }, at);
        }
    }

    /// Records the declarations a written part holds inline: its head, and
    /// whatever stands where that head holds a parameter of its own.
    ///
    /// An argument is followed only into a position something is laid out at.
    /// A head that discards its argument holds nothing at it, so `Marker[S[T]]`
    /// holds a `Marker` and no `S` -- which is the difference between a
    /// declaration that reaches itself and one that contains itself.
    ///
    /// A settled reference is not followed. It stands for whatever an
    /// implementation settled, which this measure does not read: a walk that
    /// looked through one would be an evaluator of declared types rather than
    /// a question about what the program wrote. What it holds is answered of
    /// the minted types instead, once every implementation has settled --
    /// which is where the answer differs per argument, and so where it
    /// belongs.
    fn noteHeldInline(
        self: *Checker,
        holds: *std.ArrayList(Holds),
        p: Part,
        at: u32,
        ref: node.TypeRef,
        held: Held,
    ) std.mem.Allocator.Error!void {
        switch (ref.kind) {
            // An array holds its element wherever it sits, so a type holding
            // an array of itself contains itself as one holding itself does.
            // A tuple holds every component the same way.
            .array, .grouped, .tuple => {
                for (self.ast.typeArgs(ref.args)) |a| {
                    try self.noteHeldInline(holds, p, at, a, held);
                }
                return;
            },
            .selection => return,
            .callable, .borrow => return,
            .named => {},
        }
        if (self.namesTypeParameter(p.d, ref.name)) return;
        const e = self.declOfType(p.m, p.d, ref.name) orelse return;
        try holds.append(self.gpa, .{ .from = p.d, .to = e, .part = at });

        for (self.ast.typeArgs(ref.args), 0..) |a, k| {
            if (!held.holds(e, k)) continue;
            try self.noteHeldInline(holds, p, at, a, held);
        }
    }

    /// Marks which type parameters of the declaration a part sits in that part
    /// holds inline, and says whether that added one.
    fn markHeldByPart(self: *const Checker, p: Part, ref: node.TypeRef, held: Held) bool {
        switch (ref.kind) {
            .array, .grouped, .tuple => {
                var added = false;
                for (self.ast.typeArgs(ref.args)) |a| {
                    if (self.markHeldByPart(p, a, held)) added = true;
                }
                return added;
            },
            .selection => return false,
            .callable, .borrow => return false,
            .named => {},
        }
        if (self.parameterIndex(p.d, ref.name)) |k| return held.mark(p.d, k);
        const e = self.declOfType(p.m, p.d, ref.name) orelse return false;

        var added = false;
        for (self.ast.typeArgs(ref.args), 0..) |a, k| {
            if (!held.holds(e, k)) continue;
            if (self.markHeldByPart(p, a, held)) added = true;
        }
        return added;
    }

    test "a type holding itself through a tuple component is refused as through an array" {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        _ = try typingAsPrelude(gpa, own_tuple2 ++
            \\struct S { pair: (UInt8, S) }
            \\fn main() -> UInt8 { 0 }
            \\
        , &sink);
        try testing.expect(diagnosticSays(&sink, .t_infinite_layout, "S"));
    }

    /// Reports the innermost instantiation inside a written type that grows
    /// one of `d`'s parameters and reaches `d` again, and says whether it
    /// found one.
    ///
    /// Innermost first, because the argument that grows is the one a reader
    /// has to change, and an outer instantiation carrying it says nothing
    /// about which.
    fn reportGrowth(
        self: *Checker,
        holding: *Holding,
        p: Part,
        ref: node.TypeRef,
    ) std.mem.Allocator.Error!bool {
        if (ref.kind == .callable) {
            const callable = self.ast.callableType(ref);
            for (self.ast.params[callable.params.start..callable.params.end]) |param| {
                if (try self.reportGrowth(holding, p, param.written)) return true;
            }
            return self.reportGrowth(holding, p, callable.result);
        }
        if (self.isTypeParameter(p.d, ref)) return false;
        for (self.ast.typeArgs(ref.args)) |a| {
            if (try self.reportGrowth(holding, p, a)) return true;
        }

        // A projection instantiates nothing. Its head names the type a
        // declared type is selected from rather than a generic being applied,
        // so nothing here reaches a declaration again -- what it contributes
        // is a structural step wherever it stands as an argument, which is
        // asked of it by the instantiation holding it. A dotted name whose
        // head is a module is not one of those: it names a declaration, and it
        // instantiates whatever it was given.
        const named = self.qualifiedTypeName(ref);
        if (ref.kind == .selection and named == null) return false;

        const at = named orelse ref.name;
        const e = self.declOfWritten(p.m, p.d, ref) orelse return false;

        // An argument written without `d`'s parameters, or written as one of
        // them exactly, is no larger than what `d` was given. Anything else
        // puts one of them under a constructor.
        var grows = false;
        for (self.ast.typeArgs(ref.args)) |a| {
            if (self.isTypeParameter(p.d, a)) continue;
            if (self.mentionsTypeParameter(p.d, a)) grows = true;
        }
        if (!grows) return false;
        if (!reachesBack(holding, e, p.d)) return false;

        try self.sink.addErrorFmt(
            .t_poly_rec,
            self.ast.fileOf(at),
            self.ast.tokenSpan(at),
            "a part that reaches its own declaration again keeps or reduces the structure of its type arguments",
            "this part instantiates `{s}` with more than `{s}` was given",
            .{ self.ast.tokenText(at), self.ast.tokenText(self.ast.declName(p.d)) },
        );
        return true;
    }

    /// Whether a written type is one of `d`'s type parameters and nothing
    /// more, which is what the measure holds to be no larger than what `d` was
    /// given.
    ///
    /// A projection is not, however its head is written: `S.Next` puts `S`
    /// beneath a type-level operation, and one such step is what the measure
    /// counts. What an implementation settles the declared type to is not
    /// read -- the measure is a structural approximation of termination, and
    /// looking through a projection would make it an evaluator of declared
    /// types instead.
    fn isTypeParameter(self: *const Checker, d: node.DeclId, ref: node.TypeRef) bool {
        if (ref.kind != .named) return false;
        return self.namesTypeParameter(d, ref.name);
    }

    /// Whether a written name is one of `d`'s type parameters, which answers
    /// before a module-level type of the same name for the reason it does
    /// wherever a part is read.
    fn namesTypeParameter(self: *const Checker, d: node.DeclId, tok: TokenId) bool {
        return self.parameterIndex(d, tok) != null;
    }

    /// Which of `d`'s type parameters a written name is, or null where it is
    /// none of them.
    fn parameterIndex(self: *const Checker, d: node.DeclId, tok: TokenId) ?usize {
        const binding = self.res.writtenAt(tok);
        if (binding == .none or self.res.kindOf(binding) != .type_parameter) return null;
        if (self.res.typeParameterOwner(binding) != d) return null;
        return self.res.paramIndexOf(binding);
    }

    /// Whether a written type says anything about `d`'s type parameters,
    /// however deep inside its arguments it says it.
    ///
    /// A projection says what its head says: `W.Item` puts `W` beneath a
    /// type-level operation, so the parameter is mentioned and what an
    /// implementation settles the name to is not read. That is one structural
    /// step wherever the projection stands, which is what the instantiation
    /// holding it asks about.
    ///
    /// The written type whole rather than a head and a range: an array has no
    /// head, and a reader handed those two separately decides what a written
    /// type is a second time.
    fn mentionsTypeParameter(self: *const Checker, d: node.DeclId, ref: node.TypeRef) bool {
        if (ref.kind == .callable) {
            const callable = self.ast.callableType(ref);
            for (self.ast.params[callable.params.start..callable.params.end]) |param| {
                if (self.mentionsTypeParameter(d, param.written)) return true;
            }
            return self.mentionsTypeParameter(d, callable.result);
        }
        if (ref.kind == .selection and self.mentionsTypeParameter(d, self.ast.selectionBase(ref))) return true;
        if (ref.kind == .named and self.namesTypeParameter(d, ref.name)) return true;
        for (self.ast.typeArgs(ref.args)) |a| {
            if (self.mentionsTypeParameter(d, a)) return true;
        }
        return false;
    }

    /// Whether holding leads from any of these edges back to the declaration
    /// they leave.
    ///
    /// Reaching the declaration again is what [T-PolyRec] asks about rather
    /// than naming it, so a cycle through several declarations is held to the
    /// rule as one through a single declaration is -- and [T-InfiniteLayout]
    /// asks the same of the graph of what is held inline, which is why one
    /// grouping answers both over two edge sets.
    ///
    /// The edges of one part, because a part is what either question is asked
    /// about: what one part holds is what it reaches from, and the rest of its
    /// own declaration's parts say nothing about it. Each of those edges
    /// leaves `to`, so holding leads back to `to` exactly when the two ends
    /// reach each other -- which is what `connect` grouped them by.
    ///
    /// **Bound:** one lookup per edge of the one part.
    fn holdsAgain(holding: *const Holding, from: []const Holds, to: node.DeclId) bool {
        for (from) |e| {
            if (reachesBack(holding, e.to, to)) return true;
        }
        return false;
    }

    /// Whether holding leads from one declaration back to another that holds
    /// it. The edge the other way is what the question is asked about -- a
    /// part naming this declaration -- so the two reach each other exactly
    /// when `connect` put them in one group.
    fn reachesBack(holding: *const Holding, from: node.DeclId, to: node.DeclId) bool {
        return holding.component[from.index()] == holding.component[to.index()];
    }

    /// Groups the declarations so that two are in one group exactly when
    /// holding leads from each of them back to the other.
    ///
    /// One pass for the whole graph rather than a walk from every part. The
    /// question a part asks is answered by two lookups once this has run, and
    /// asked per part over a walk it was the parts times the declarations they
    /// reach -- which a module of many generic declarations pays in full,
    /// because every one of them walks whatever the others hold.
    ///
    /// **Bound:** one visit per declaration and one per edge.
    fn connect(self: *const Checker, holding: *Holding) std.mem.Allocator.Error!void {
        const decls = holding.component.len;
        const unvisited = std.math.maxInt(u32);

        // When each declaration was first reached, and the earliest anything
        // it reaches was: a declaration whose two agree is the root of a
        // group, and everything above it on the stack is in that group.
        const entered = try self.gpa.alloc(u32, decls);
        defer self.gpa.free(entered);
        @memset(entered, unvisited);

        const earliest = try self.gpa.alloc(u32, decls);
        defer self.gpa.free(earliest);

        const grouping = try self.gpa.alloc(bool, decls);
        defer self.gpa.free(grouping);
        @memset(grouping, false);

        var pending: std.ArrayList(u32) = .empty;
        defer pending.deinit(self.gpa);

        // The walk's own stack, as a declaration and how far through its run
        // it has read. Held here rather than in the call stack, because the
        // depth is the program's and a program is not bounded by a stack.
        var walk: std.ArrayList(Reached) = .empty;
        defer walk.deinit(self.gpa);

        var order: u32 = 0;
        var groups: u32 = 0;

        for (0..decls) |root| {
            if (entered[root] != unvisited) continue;

            entered[root] = order;
            earliest[root] = order;
            order += 1;
            try pending.append(self.gpa, @intCast(root));
            grouping[root] = true;
            try walk.append(self.gpa, .{ .at = @intCast(root), .edge = holding.starts[root] });

            while (walk.items.len > 0) {
                const top = walk.items.len - 1;
                const d = walk.items[top].at;
                const cursor = walk.items[top].edge;

                if (cursor < holding.starts[d + 1]) {
                    walk.items[top].edge = cursor + 1;
                    const edge = holding.edges[holding.runs[cursor]];
                    if (!holding.follows(edge)) continue;

                    const held: u32 = @intCast(edge.to.index());
                    if (entered[held] == unvisited) {
                        entered[held] = order;
                        earliest[held] = order;
                        order += 1;
                        try pending.append(self.gpa, held);
                        grouping[held] = true;
                        try walk.append(self.gpa, .{ .at = held, .edge = holding.starts[held] });
                    } else if (grouping[held]) {
                        earliest[d] = @min(earliest[d], entered[held]);
                    }
                    continue;
                }

                if (earliest[d] == entered[d]) {
                    while (pending.pop()) |w| {
                        grouping[w] = false;
                        holding.component[w] = groups;
                        if (w == d) break;
                    }
                    groups += 1;
                }

                _ = walk.pop();
                if (walk.items.len > 0) {
                    const above = walk.items[walk.items.len - 1].at;
                    earliest[above] = @min(earliest[above], earliest[d]);
                }
            }
        }
    }

    /// One declaration on the grouping walk, and how far through what it holds
    /// the walk has read.
    const Reached = struct { at: u32, edge: u32 };

    /// A written type, and what it settled to recorded against the token that
    /// wrote it.
    ///
    /// Recorded here because this is the one place a head and its arguments
    /// become a handle. A renderer that read the source instead was answering
    /// a question already answered, and answered it differently: the mono dump
    /// declared one name and referred to the same type by another.
    fn typeOfRefOf(
        self: *Checker,
        m: ModuleId,
        owner: node.DeclId,
        ref: node.TypeRef,
    ) std.mem.Allocator.Error!TypeId {
        switch (ref.kind) {
            .grouped => {
                const arguments = self.ast.typeArgs(ref.args);
                if (arguments.len != 1) return .poison;
                return self.typeOfRefOf(m, owner, arguments[0]);
            },
            .borrow => {
                const arguments = self.ast.typeArgs(ref.args);
                if (arguments.len != 1) return .poison;
                return self.builder.borrowOf(try self.typeOfRefOf(m, owner, arguments[0]));
            },
            // A name the trait that declares it wrote bare. The same
            // declaration `Self.Item` reaches, so it takes the same reading --
            // what says the bare name is that declaration is the resolver, and
            // it says so only inside the braces that declare it.
            .named => if (self.namesADeclaredType(ref.name)) {
                return self.declaredTypeOf(owner, ref);
            },
            .array => return self.arrayTypeOf(m, owner, ref),
            .callable => return self.callableTypeOf(m, owner, ref),
            .tuple => return self.tupleTypeOf(m, owner, ref),
            // A dotted name whose head is a module names the type that module
            // declares, which is a name with a dot in it and nothing more: it
            // takes its own arguments and settles exactly as a name in scope
            // does.
            //
            // What a settled reference names is settled by an implementation
            // rather than by a name any module holds, so it is read through
            // the implementation rather than through the scope.
            .selection => {
                if (self.qualifiedTypeName(ref)) |at| return self.qualifiedTypeOf(m, owner, ref, at);
                return self.settledRefTypeOf(owner, ref);
            },
        }
        const settled = try self.settleRef(m, owner, ref.name, ref.args);
        self.recordWritten(owner, ref.name, settled);
        return settled;
    }

    /// `(A, B)`: the prelude's tuple declaration of that arity, instantiated
    /// at the components.
    ///
    /// Every component is read whatever the arity, so a mistake inside one is
    /// reported where it is written. A tuple of an arity the parser refused
    /// names no type and was reported there; one of an arity the prelude does
    /// not publish is reported here, as text is where the prelude declares no
    /// `Str`.
    fn tupleTypeOf(
        self: *Checker,
        m: ModuleId,
        owner: node.DeclId,
        ref: node.TypeRef,
    ) std.mem.Allocator.Error!TypeId {
        const written = self.ast.typeArgs(ref.args);
        var components: std.ArrayList(TypeId) = .empty;
        defer components.deinit(self.gpa);
        var invalid = false;
        for (written) |component| {
            const ty = try self.typeOfRefOf(m, owner, component);
            if (ty == .poison) invalid = true;
            try components.append(self.gpa, ty);
        }
        const decl = self.tupleDecl(written.len) orelse {
            try self.reportUnpublishedTuple(written.len, self.ast.fileOf(ref.at), self.ast.writtenSpan(ref));
            return .poison;
        };
        if (invalid) return .poison;
        const settled = try self.tupleType(decl, components.items);
        self.recordWritten(owner, ref.at, settled);
        return settled;
    }

    /// The prelude's declaration of a tuple with `arity` components, or null
    /// where there is none to instantiate: the resolver's answer, which is
    /// also what keyed every tuple head.
    fn tupleDecl(self: *const Checker, arity: usize) ?node.DeclId {
        return self.res.tupleDecl(arity);
    }

    /// The instance of the tuple declaration `decl` at `components`, which is
    /// the one type every spelling of that tuple reaches.
    fn tupleType(self: *Checker, decl: node.DeclId, components: []const TypeId) std.mem.Allocator.Error!TypeId {
        return self.builder.instantiate(self.type_of_decl.get(decl), decl, components);
    }

    /// Reports a tuple of an arity the parser admits and the prelude declares
    /// no type for. Silent for an arity the parser refused, which it reported
    /// at the `(`.
    fn reportUnpublishedTuple(self: *Checker, arity: usize, file: FileId, span: Span) std.mem.Allocator.Error!void {
        if (!node.isTupleArity(arity)) return;
        try self.sink.addErrorFmt(
            .t_literal,
            file,
            span,
            "build against a library that declares it",
            "a tuple of {d} has no type here: the prelude declares no `Tuple{d}`",
            .{ arity, arity },
        );
    }

    test "a tuple type is spelled as the program writes it, in a report and in the pool alike" {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        const checked = try typingAsPrelude(gpa, own_tuple2 ++
            \\fn main() -> UInt8 {
            \\    let pair: (UInt8, Bool) = (1, true)
            \\    let _long: Tuple2[UInt8, Bool] = pair
            \\    0
            \\}
            \\
        , &sink);
        try testing.expectEqual(@as(u32, 0), sink.error_count);
        const ast = &checked.res.expanded.ast;
        var pair = BindingId.none;
        var long = BindingId.none;
        for (0..checked.res.resolution.bindingCount()) |i| {
            const b = BindingId.at(@intCast(i));
            const tok = checked.res.resolution.declaringToken(b);
            if (tok == TokenId.none) continue;
            if (std.mem.eql(u8, ast.tokenText(tok), "pair")) pair = b;
            if (std.mem.eql(u8, ast.tokenText(tok), "_long")) long = b;
        }
        try testing.expect(pair != BindingId.none and long != BindingId.none);
        // The two spellings reach one type, and every reader of the type spells
        // it as the tuple: the pool's own name, and the name a report writes.
        const ty = checked.typing.bindingType(pair);
        try testing.expectEqual(ty, checked.typing.bindingType(long));
        try testing.expectEqualStrings("(UInt8, Bool)", checked.typing.nameOf(ty));
        const written = try writtenTypeName(gpa, ast, &checked.res.expanded, &checked.res.resolution, &checked.typing, .from(0), ty);
        try testing.expectEqualStrings("(UInt8, Bool)", written);
        // The spelling a bound's message takes from the tree agrees with it.
        var spelled = false;
        for (0..ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            if (ast.declTag(d) != .function) continue;
            for (ast.blockStmts(ast.blockOf(ast.declBody(d)))) |s| {
                const annotation = ast.stmtData(s).annotation;
                if (annotation.kind != .tuple) continue;
                try testing.expectEqualStrings(written, try spellWrittenOwned(gpa, ast, annotation));
                spelled = true;
            }
        }
        try testing.expect(spelled);
    }

    test "a tuple of an arity the parser refused is typed poison silently, and an unpublished one is reported" {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        {
            // `(7,)`, a nine-tuple and a one-binder pattern were reported by
            // the parser, so the literal, the type and the pattern say nothing.
            var sink = Sink.init(gpa);
            _ = try typingAsPrelude(gpa, own_tuple2 ++
                \\fn main() -> UInt8 {
                \\    let _one = (7,)
                \\    let _nine: (UInt8, UInt8, UInt8, UInt8, UInt8, UInt8, UInt8, UInt8, UInt8) = (1, 2, 3, 4, 5, 6, 7, 8, 9)
                \\    let pair: (UInt8, Bool) = (1, true)
                \\    let (_a,) = pair
                \\    let (_b,) = 5
                \\    0
                \\}
                \\
            , &sink);
            var codes: usize = 0;
            for (sink.items()) |d| {
                try testing.expectEqual(Code.s_tuple, d.code.?);
                codes += 1;
            }
            try testing.expectEqual(@as(usize, 5), codes);
        }
        {
            // A three-tuple is admitted by the parser and declared by no prelude
            // here, which is reported once for the literal and once for the type.
            var sink = Sink.init(gpa);
            _ = try typingAsPrelude(gpa, own_tuple2 ++
                \\fn main() -> UInt8 {
                \\    let _three: (UInt8, UInt8, UInt8) = (1, 2, 3)
                \\    0
                \\}
                \\
            , &sink);
            var tuples: usize = 0;
            for (sink.items()) |d| {
                if (d.code.? == .t_literal) tuples += 1;
            }
            try testing.expectEqual(@as(usize, 2), tuples);
        }
    }

    fn callableTypeOf(
        self: *Checker,
        m: ModuleId,
        owner: node.DeclId,
        ref: node.TypeRef,
    ) std.mem.Allocator.Error!TypeId {
        const written = self.ast.callableType(ref);
        var params: std.ArrayList(types_mod.CallableParam) = .empty;
        defer params.deinit(self.gpa);
        var invalid = false;

        for (self.ast.params[written.params.start..written.params.end]) |param| {
            const ty = try self.typeOfRefOf(m, owner, param.written);
            var default: types_mod.CallableDefault = .absent;
            if (param.default != ExprId.none) {
                try self.noteCallableDefault(.{
                    .module = m,
                    .owner = owner,
                    .expr = param.default,
                    .parameter = param.name,
                    .convention = param.convention,
                    .ty = ty,
                });
                if ((try self.worth(param.default)).checked()) |value| {
                    default = .{ .value = value };
                } else {
                    invalid = true;
                }
            }
            if (ty == .poison) invalid = true;
            try params.append(self.gpa, .{
                .spelling = self.ast.tokenText(param.name),
                .convention = param.convention,
                .ty = ty,
                .default = default,
            });
        }

        const result = try self.resultOfRef(m, owner, written.result);
        if (invalid or result == .poison) {
            try self.noteContractRoots(self.ast.params[written.params.start..written.params.end], self.ast.contracts[written.contracts.start..written.contracts.end]);
            return .poison;
        }
        const contracts = if (self.callable_effects_ready)
            try self.normalizeContracts(params.items, self.ast.params[written.params.start..written.params.end], result, self.ast.contracts[written.contracts.start..written.contracts.end], ref.at, null, null)
        else
            &.{};
        defer types_mod.freeContracts(self.gpa, contracts);
        const settled = try self.builder.internCallable(params.items, result, contracts, written.invocation);
        self.recordWritten(owner, ref.at, settled);
        return settled;
    }

    /// Records what a written type's token reads as, for every later reader of
    /// the token. A trait signature read at a `Self` a call settled is one
    /// call's reading, and the token keeps the declaration's own.
    fn recordWritten(self: *Checker, owner: node.DeclId, at: TokenId, settled: TypeId) void {
        if (at == TokenId.none or at.index() >= self.written_types.len) return;
        if (self.self_settled and self.ast.declIsSignature(owner)) return;
        self.written_types[at.index()] = settled;
    }

    fn callableBoundTypeOf(self: *Checker, module: ModuleId, owner: node.DeclId, ref: node.TypeRef) !TypeId {
        return self.carriedUnlessDeclined(try self.typeOfRefOf(module, owner, ref), ref);
    }

    /// A callable bound's signature, which carries its callee unless the
    /// written function type declines with an empty `carries()`.
    fn carriedUnlessDeclined(self: *Checker, raw: TypeId, ref: node.TypeRef) !TypeId {
        if (raw == .poison or !self.callable_effects_ready) return raw;
        const written = self.ast.callableType(ref);
        for (self.ast.contracts[written.contracts.start..written.contracts.end]) |contract| {
            if (contract.kind == .carries and contract.source.root == .none and contract.target.root == .none) return raw;
        }
        return self.builder.carriedByCallee(raw);
    }

    const ContractNames = std.AutoHashMapUnmanaged(StringId, types_mod.ContractRoot);

    fn contractNames(self: *Checker, params: []const node.Param, closure: ?resolve_mod.ClosureId) !ContractNames {
        var names: ContractNames = .empty;
        errdefer names.deinit(self.gpa);
        if (closure) |owner| for (self.res.closureCaptures(owner), 0..) |capture, index| {
            const name = self.res.captureNameToken(capture.binding);
            try names.put(self.gpa, self.ast.tokenName(name), .{ .capture = .{ .closure = owner, .field = @enumFromInt(index) } });
        };
        for (params, 0..) |param, index| {
            if (param.name != .none) try names.put(self.gpa, self.ast.tokenName(param.name), .{ .parameter = @intCast(index) });
        }
        return names;
    }

    fn contractRoot(self: *Checker, declared_params: []const node.Param, names: *const ContractNames, head: TokenId) !?types_mod.ContractRoot {
        const root = names.get(self.ast.tokenName(head)) orelse {
            self.reportAtToken(.t_borrow_contract, head, "a contract path must name a declared source", "this source is not declared", null);
            return null;
        };
        const declaration = switch (root) {
            .parameter => |parameter| declared_params[parameter].name,
            .capture => |capture| self.res.declaringToken(self.res.closureCaptures(capture.closure)[capture.field.index()].binding),
            .callee => unreachable,
        };
        if (declaration != .none) try self.contract_parameters.put(self.gpa, head, declaration);
        // A place lent `inout` changes on the next call, so no result may
        // depend on it and nothing may be retained in it.
        if (root == .capture and self.res.closureCaptures(root.capture.closure)[root.capture.field.index()].convention == .inout) {
            self.reportAtToken(.t_borrow_contract, head, "a contract cannot name an `inout` capture", "this capture is lent `inout`", null);
            return null;
        }
        return root;
    }

    // Preserve source identities even when an unavailable imported type prevents
    // typing the contract's field paths or result targets.
    fn noteContractRoots(self: *Checker, params: []const node.Param, contracts: []const node.Contract) !void {
        if (contracts.len == 0) return;
        var names = try self.contractNames(params, null);
        defer names.deinit(self.gpa);
        for (contracts) |contract| {
            if (contract.source.root != .none) _ = try self.contractRoot(params, &names, contract.source.root);
            if (contract.kind == .retains and contract.destination.root != .none)
                _ = try self.contractRoot(params, &names, contract.destination.root);
        }
    }

    fn contractPath(self: *Checker, params: []const types_mod.CallableParam, declared_params: []const node.Param, names: *const ContractNames, path: node.ContractPath) !?types_mod.ContractPath {
        if (path.root == .none) return null;
        const root = (try self.contractRoot(declared_params, names, path.root)) orelse return null;
        var fields: std.ArrayList(types_mod.PathSelector) = .empty;
        errdefer fields.deinit(self.gpa);
        var spelling: std.ArrayList(u8) = .empty;
        defer spelling.deinit(self.gpa);
        try spelling.appendSlice(self.gpa, self.ast.tokenText(path.root));
        var ty = switch (root) {
            .parameter => |parameter| params[parameter].ty,
            .capture => |capture| self.binding_types.get(self.res.closureCaptures(capture.closure)[capture.field.index()].binding),
            .callee => unreachable,
        };
        for (self.ast.contractSteps(path)) |step| {
            switch (step) {
                .dereference => |token| {
                    if (self.builder.get(ty) != .borrow) {
                        self.reportAtToken(.t_borrow_contract, token, "only an observation has a referent", "this contract path cannot be dereferenced", null);
                        fields.deinit(self.gpa);
                        return null;
                    }
                    ty = self.builder.get(ty).borrow.referent;
                    try fields.append(self.gpa, .observed);
                    try spelling.insertSlice(self.gpa, 0, "*(");
                    try spelling.append(self.gpa, ')');
                },
                .field => |token| {
                    const adjustment = self.builder.view().observedReceiver(ty);
                    for (0..adjustment.observations) |_| try fields.append(self.gpa, .observed);
                    ty = adjustment.receiver;
                    // Refused, and still read, so the body is checked against
                    // the contract as written rather than against none.
                    if (self.sealedHere(ty)) self.reportSealedAtToken(token, ty);
                    const found = self.builder.lookupField(ty, self.ast.tokenText(token)) orelse {
                        self.reportAtToken(.t_borrow_contract, token, "a contract path must name an existing field", "this field is not part of the contract source", null);
                        fields.deinit(self.gpa);
                        return null;
                    };
                    try self.field_names.put(self.gpa, token, .{ .receiver = ty, .field = @enumFromInt(found.index) });
                    try fields.append(self.gpa, .{ .field = self.ast.tokenName(token) });
                    ty = found.ty;
                    try spelling.append(self.gpa, '.');
                    try spelling.appendSlice(self.gpa, self.ast.tokenText(token));
                },
            }
        }
        const path_spelling = try spelling.toOwnedSlice(self.gpa);
        errdefer self.gpa.free(path_spelling);
        return .{ .root = root, .fields = try fields.toOwnedSlice(self.gpa), .spelling = path_spelling };
    }

    fn contractTarget(self: *Checker, result: TypeId, path: node.ContractPath) !?struct { selectors: []const types_mod.ResultSelector, spelling: []const u8 } {
        var selectors: std.ArrayList(types_mod.ResultSelector) = .empty;
        defer selectors.deinit(self.gpa);
        var spelling: std.ArrayList(u8) = .empty;
        defer spelling.deinit(self.gpa);
        var ty = result;
        const steps = self.ast.contractSteps(path);
        const root_count: usize = if (path.root == .none) 0 else 1;
        for (0..root_count + steps.len) |index| {
            const step: node.ContractStep = if (index < root_count) .{ .field = path.root } else steps[index - root_count];
            const name = switch (step) {
                .field => |token| token,
                .dereference => |token| {
                    self.reportAtToken(.t_borrow_contract, token, "a result target cannot enter observation storage", "result targets name owned result components", null);
                    return null;
                },
            };
            if (self.builder.get(ty) == .borrow) {
                self.reportAtToken(.t_borrow_contract, name, "a result target cannot enter observation storage", "result targets name owned result components", null);
                return null;
            }
            const text = self.ast.tokenText(name);
            if (self.sealedHere(ty)) self.reportSealedAtToken(name, ty);
            if (self.builder.get(ty) == .enum_) {
                const variant = (try self.variantNamed(ty, text)) orelse {
                    self.reportAtToken(.t_borrow_contract, name, "a result target must name an existing variant", "this variant is not part of the result", null);
                    return null;
                };
                if (self.builder.variantFieldCount(ty, variant) != 1) {
                    self.reportAtToken(.t_borrow_contract, name, "a variant target requires exactly one payload", "use a whole-result contract for this shape", null);
                    return null;
                }
                try self.contract_variants.put(self.gpa, name, .{ .receiver = ty, .ordinal = @enumFromInt(variant) });
                try selectors.append(self.gpa, .{ .payload = .{ .variant = @enumFromInt(variant), .index = 0 } });
                ty = self.builder.variantFieldType(ty, variant, 0);
            } else {
                const field = self.builder.lookupField(ty, text) orelse {
                    self.reportAtToken(.t_borrow_contract, name, "a result target must name an existing contained field", "this field is not part of the result", null);
                    return null;
                };
                try self.field_names.put(self.gpa, name, .{ .receiver = ty, .field = @enumFromInt(field.index) });
                try selectors.append(self.gpa, .{ .field = .{ .name = self.ast.tokenName(name), .index = field.index } });
                ty = field.ty;
            }
            try spelling.append(self.gpa, '.');
            try spelling.appendSlice(self.gpa, text);
        }
        const owned = try selectors.toOwnedSlice(self.gpa);
        errdefer self.gpa.free(owned);
        return .{ .selectors = owned, .spelling = try spelling.toOwnedSlice(self.gpa) };
    }

    /// The trait signature a member supplies, or null for a declaration that
    /// supplies none.
    fn suppliedSignature(self: *const Checker, member: node.DeclId) ?node.DeclId {
        if (self.supply.signatureOf(member)) |sig| return sig;
        const pairing = self.template_signatures.get(member) orelse return null;
        return pairing.signature;
    }

    /// What reading a signature's contracts decided besides the contracts.
    const ContractOutcome = struct {
        /// A clause was refused or the source was ambiguous, so the body is
        /// not checked against what remains.
        declined: bool = false,
        /// The parameter whose carrier type supplied the contract of a
        /// signature that wrote no clause.
        carrier: ?u32 = null,
    };

    const CarrierParameters = struct {
        count: u32 = 0,
        first: u32 = 0,

        /// The parameter that is the default source: the only carrier.
        fn sole(self: CarrierParameters) ?u32 {
            return if (self.count == 1) self.first else null;
        }
    };

    /// Whether values of `ty` are carriers: the type, after alias expansion,
    /// is an instantiation or a declaration marked `@carrier`.
    fn isCarrierType(self: *const Checker, ty: TypeId) !bool {
        const declaration = self.declaringType(ty) orelse return false;
        return self.ast.declIsCarrier(declaration);
    }

    /// The parameters whose types are carriers and could be the source of
    /// `result`, whatever their convention.
    ///
    /// **Bound:** one pass over the signature's parameters.
    fn carrierParameters(self: *Checker, params: []const types_mod.CallableParam, result: TypeId) !CarrierParameters {
        var found: CarrierParameters = .{};
        for (params, 0..) |parameter, index| {
            if (!try self.isCarrierType(parameter.ty)) continue;
            if (!try types_mod.isEligibleSource(&self.builder, parameter, result)) continue;
            if (found.count == 0) found.first = @intCast(index);
            found.count += 1;
        }
        return found;
    }

    fn normalizeContracts(self: *Checker, params: []types_mod.CallableParam, declared_params: []const node.Param, result: TypeId, written: []const node.Contract, at: TokenId, closure: ?resolve_mod.ClosureId, outcome: ?*ContractOutcome) ![]const types_mod.CallableContract {
        var contracts: std.ArrayList(types_mod.CallableContract) = .empty;
        errdefer {
            for (contracts.items) |contract| {
                types_mod.freeContractPath(self.gpa, contract.source);
                self.gpa.free(contract.target);
                self.gpa.free(contract.target_spelling);
                if (contract.destination) |destination| types_mod.freeContractPath(self.gpa, destination);
            }
            contracts.deinit(self.gpa);
        }
        var names = try self.contractNames(declared_params, closure);
        defer names.deinit(self.gpa);
        // A clause whose source, destination or target is refused is dropped,
        // and what remains is not what anyone declared.
        var dropped = false;
        for (written) |clause| {
            // `carries()` writes no source, which is a promise of independence
            // rather than a refusal.
            const source = (try self.contractPath(params, declared_params, &names, clause.source)) orelse {
                if (clause.source.root != .none) dropped = true;
                continue;
            };
            errdefer types_mod.freeContractPath(self.gpa, source);
            const destination = if (clause.kind == .retains)
                (try self.contractPath(params, declared_params, &names, clause.destination)) orelse {
                    types_mod.freeContractPath(self.gpa, source);
                    dropped = true;
                    continue;
                }
            else
                null;
            errdefer if (destination) |dest| types_mod.freeContractPath(self.gpa, dest);
            if (destination) |dest| {
                for (dest.fields) |step| if (step == .observed) {
                    self.reportAtToken(.t_borrow_contract, clause.at, "retention cannot write through an observation", "the destination crosses readonly referent storage", null);
                    break;
                };
                const mutable = switch (dest.root) {
                    .parameter => |parameter| params[parameter].convention == .inout,
                    .capture => |capture| resolve_mod.captureIsMutable(
                        self.res.closureCaptures(capture.closure)[capture.field.index()].convention,
                        self.closure_descriptors[capture.closure.index()].invocation,
                    ),
                    .callee => unreachable,
                };
                if (!mutable) self.reportAtToken(.t_borrow_contract, clause.at, "retention requires an inout destination", "this destination is not mutable", null);
            }
            if (clause.kind == .borrows or clause.borrows_source) {
                var observes_existing = false;
                for (source.fields) |selector| if (selector == .observed) {
                    observes_existing = true;
                    break;
                };
                if (!observes_existing) {
                    switch (source.root) {
                        .callee => unreachable,
                        .parameter => |parameter| {
                            if (params[parameter].convention == .sink) self.reportAtToken(.t_borrow_contract, clause.at, "a consumed parameter cannot supply escaping place storage", "borrow a read or inout parameter", null);
                            params[parameter].stable_address = true;
                        },
                        .capture => |capture| {
                            if (self.res.closureCaptures(capture.closure)[capture.field.index()].convention == .sink)
                                self.reportAtToken(.t_borrow_contract, clause.at, "a result cannot borrow closure-owned storage", "carry existing captured dependencies instead", null);
                        },
                    }
                }
            }
            const target = (try self.contractTarget(result, clause.target)) orelse {
                types_mod.freeContractPath(self.gpa, source);
                if (destination) |dest| types_mod.freeContractPath(self.gpa, dest);
                dropped = true;
                continue;
            };
            errdefer self.gpa.free(target.selectors);
            errdefer self.gpa.free(target.spelling);
            try contracts.append(self.gpa, .{ .target = target.selectors, .target_spelling = target.spelling, .kind = switch (clause.kind) {
                .borrows => .borrows,
                .carries => .carries,
                .retains => .retains,
            }, .source = source, .destination = destination, .borrows_source = clause.borrows_source });
        }
        // The body is not checked against the remainder of a dropped clause:
        // the refusal is its error.
        if (dropped) if (outcome) |out| {
            out.declined = true;
        };
        const carriers: CarrierParameters = if (written.len == 0) try self.carrierParameters(params, result) else .{};
        if (written.len == 0) switch (try types_mod.inferredSource(&self.builder, params, result, carriers.sole())) {
            .none => {},
            .ambiguous => {
                var eligible: usize = 0;
                for (params) |parameter| eligible += @intFromBool(try types_mod.isEligibleSource(&self.builder, parameter, result));
                var sources: std.ArrayList(u8) = .empty;
                defer sources.deinit(self.gpa);
                var clauses: std.ArrayList(u8) = .empty;
                defer clauses.deinit(self.gpa);
                var listed: usize = 0;
                for (params) |parameter| {
                    if (!try types_mod.isEligibleSource(&self.builder, parameter, result)) continue;
                    const separator = if (listed == 0) "" else if (listed + 1 == eligible) " or " else ", ";
                    try sources.print(self.gpa, "{s}`{s}`", .{ separator, parameter.spelling });
                    try clauses.print(self.gpa, "{s}`where borrows({s})`", .{ separator, parameter.spelling });
                    listed += 1;
                }
                if (carriers.count > 1) {
                    var named: std.ArrayList(u8) = .empty;
                    defer named.deinit(self.gpa);
                    var carried: std.ArrayList(u8) = .empty;
                    defer carried.deinit(self.gpa);
                    var listed_carriers: usize = 0;
                    for (params) |parameter| {
                        if (!try self.isCarrierType(parameter.ty)) continue;
                        if (!try types_mod.isEligibleSource(&self.builder, parameter, result)) continue;
                        const joiner = if (listed_carriers == 0) "" else if (listed_carriers + 1 == carriers.count) " and " else ", ";
                        const alternative = if (listed_carriers == 0) "" else if (listed_carriers + 1 == carriers.count) " or " else ", ";
                        try named.print(self.gpa, "{s}`{s}`", .{ joiner, parameter.spelling });
                        try carried.print(self.gpa, "{s}`where carries({s})`", .{ alternative, parameter.spelling });
                        listed_carriers += 1;
                    }
                    const help = try std.fmt.allocPrint(self.sink.arena, "{s} are carriers, so none is the default source; add {s}, or list several sources in one clause", .{ named.items, carried.items });
                    self.reportAtToken(.t_borrow_contract, at, "the result has more than one eligible observation source, and several parameters are carriers", help, null);
                } else {
                    const help = try std.fmt.allocPrint(self.sink.arena, "the result may borrow from {s}; add {s}, or list several sources in one clause", .{ sources.items, clauses.items });
                    self.reportAtToken(.t_borrow_contract, at, "the result has more than one eligible observation source", help, null);
                }
                // The body has no contract to be checked against, so the
                // ambiguity is the only error it reports.
                if (outcome) |out| out.declined = true;
            },
            .one => |source| {
                if (source.place) params[source.parameter].stable_address = true;
                if (source.by_carrier) if (outcome) |out| {
                    out.carrier = source.parameter;
                };
                const spelling = try self.gpa.dupe(u8, params[source.parameter].spelling);
                errdefer self.gpa.free(spelling);
                try contracts.append(self.gpa, .{ .kind = if (source.place) .borrows else .carries, .source = .{ .root = .{ .parameter = source.parameter }, .spelling = spelling } });
            },
        };
        return contracts.toOwnedSlice(self.gpa);
    }

    /// The contracts a member of `impl Trait for T` without a clause of its
    /// own promises: its trait signature's, with each source rooted at the
    /// member's parameter in the same position and spelled by the member's
    /// name for it. Null when the signature is unusable or its parameters do
    /// not line up with the member's, which the member/signature comparison
    /// reports, or when the signature's own contract was left undecided.
    ///
    /// **Bound:** one lookup of the signature, and one copy per contract it
    /// declares.
    fn adoptedContracts(self: *Checker, params: []types_mod.CallableParam, sig: node.DeclId) !?[]const types_mod.CallableContract {
        try self.ensureSignature(sig);
        if (self.declined_contracts.contains(sig)) return null;
        const promised = switch (self.builder.get(self.decl_signatures.get(sig))) {
            .callable => |callable| callable,
            else => return null,
        };
        const promised_params = self.builder.callableParams(promised);
        if (promised_params.len != params.len) return null;
        const contracts = try self.gpa.alloc(types_mod.CallableContract, promised.contracts.len);
        var filled: usize = 0;
        errdefer {
            for (contracts[0..filled]) |contract| {
                types_mod.freeContractPath(self.gpa, contract.source);
                self.gpa.free(contract.target);
                self.gpa.free(contract.target_spelling);
                if (contract.destination) |dest| types_mod.freeContractPath(self.gpa, dest);
            }
            self.gpa.free(contracts);
        }
        for (promised.contracts, contracts) |contract, *adopted| {
            const source = try self.respelledPath(contract.source, promised_params, params);
            errdefer types_mod.freeContractPath(self.gpa, source);
            const destination = if (contract.destination) |dest| try self.respelledPath(dest, promised_params, params) else null;
            errdefer if (destination) |dest| types_mod.freeContractPath(self.gpa, dest);
            const target = try self.gpa.dupe(types_mod.ResultSelector, contract.target);
            errdefer self.gpa.free(target);
            adopted.* = .{
                .kind = contract.kind,
                .source = source,
                .target = target,
                .target_spelling = try self.gpa.dupe(u8, contract.target_spelling),
                .destination = destination,
                .borrows_source = contract.borrows_source,
            };
            filled += 1;
        }
        for (promised_params, params) |want, *got| got.stable_address = got.stable_address or want.stable_address;
        return contracts;
    }

    /// A contract path rooted at the signature's parameter, spelled by the
    /// member's name for the parameter in the same position. The path's
    /// selectors are the signature's.
    fn respelledPath(self: *Checker, path: types_mod.ContractPath, from: []const types_mod.CallableParam, to: []const types_mod.CallableParam) !types_mod.ContractPath {
        const index = switch (path.root) {
            .parameter => |index| index,
            .capture, .callee => unreachable,
        };
        // A dereference wraps the path as `*(...)`, so the root name follows
        // every opening `*(`.
        var opened: usize = 0;
        while (std.mem.startsWith(u8, path.spelling[opened..], "*(")) opened += 2;
        const rest = path.spelling[opened + from[index].spelling.len ..];
        const spelling = try std.mem.concat(self.gpa, u8, &.{ path.spelling[0..opened], to[index].spelling, rest });
        errdefer self.gpa.free(spelling);
        return .{ .root = path.root, .fields = try self.gpa.dupe(types_mod.PathSelector, path.fields), .spelling = spelling };
    }

    fn signatureSelfType(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!TypeId {
        const trait = self.traitDeclaring(d) orelse return .poison;
        const inherited = try self.traitsBounding(.{ .module = self.program.moduleOf(trait), .owner = trait }, self.ast.declBounds(trait));
        var admitted: std.ArrayList(types_mod.BoundTrait) = .fromOwnedSlice(@constCast(inherited));
        errdefer {
            for (admitted.items) |bound| if (bound.args.len > 0) self.gpa.free(bound.args);
            admitted.deinit(self.gpa);
        }
        const arguments = try self.gpa.dupe(TypeId, self.param_types[trait.index()]);
        admitted.append(self.gpa, .{ .trait = trait.index(), .args = arguments }) catch |err| {
            self.gpa.free(arguments);
            return err;
        };
        const requirement = capabilityDemandedBy(self.ast, self.res, self.ast.declBounds(trait), admitted.items);
        return self.builder.addParameter("Self", d.index(), @intCast(self.ast.declTypeParams(d).len), requirement, try admitted.toOwnedSlice(self.gpa));
    }

    /// Returns a parameter's type as its own declaration's scope reads it. A
    /// named parameter's type was resolved once, as its binding's type, before
    /// any signature is built; only a parameter whose name did not parse, and
    /// so has no binding, is resolved here, by its one reader.
    fn declaredParamType(self: *Checker, d: node.DeclId, index: usize) std.mem.Allocator.Error!TypeId {
        if (self.parameterBinding(d, index)) |binding| return self.binding_types.get(binding);
        return self.typeOfRefOf(self.program.moduleOf(d), d, self.ast.declParams(d)[index].written);
    }

    /// Returns the binding a declaration's parameter declares, or null when its
    /// name did not parse. Bindings are recorded in parameter order, one per
    /// named parameter, so a declaration whose every name parsed is indexed
    /// directly.
    fn parameterBinding(self: *const Checker, d: node.DeclId, index: usize) ?BindingId {
        const bindings = self.res.parametersOf(d);
        if (bindings.len == self.ast.declParams(d).len) return bindings[index];
        for (bindings) |binding| if (self.res.paramIndexOf(binding) == index) return binding;
        return null;
    }

    /// Returns a function declaration's written result type, resolved once in
    /// the scope its parameters are read in: the declaration's module and
    /// parameters, a trait signature's symbolic `Self`, or a template member's
    /// open `Self`. Every reader of the declared result reads this answer.
    fn declaredResultType(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!TypeId {
        if (self.declared_results[d.index()]) |resolved| return resolved;
        const outer_module = self.current;
        const outer_generic = self.generic;
        const outer_self = self.self_at_call;
        const outer_symbolic_owner = self.symbolic_self_owner;
        defer {
            self.current = outer_module;
            self.generic = outer_generic;
            self.self_at_call = outer_self;
            self.symbolic_self_owner = outer_symbolic_owner;
        }
        self.current = self.program.moduleOf(d);
        self.generic = d;
        if (self.template_signatures.get(d)) |pairing| {
            self.symbolic_self_owner = d;
            self.self_at_call = try self.templateSelf(pairing.template);
        } else {
            self.symbolic_self_owner = .none;
            self.self_at_call = if (self.ast.declIsSignature(d)) try self.signatureSelfType(d) else null;
        }
        // A test that writes no result answers its default `Result`, which
        // `returnType` settles before asking here.
        const resolved = try self.declResultOf(self.current, d);
        self.declared_results[d.index()] = resolved;
        return resolved;
    }

    fn callableSignatureOf(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!TypeId {
        const saved_self = self.self_at_call;
        defer self.self_at_call = saved_self;
        if (self.ast.declIsSignature(d)) self.self_at_call = try self.signatureSelfType(d);
        const params = self.ast.declParams(d);
        const callable_params = try self.gpa.alloc(types_mod.CallableParam, params.len);
        defer self.gpa.free(callable_params);
        var valid = true;
        for (params, 0..) |param, i| {
            const ty = try self.declaredParamType(d, i);
            var default: types_mod.CallableDefault = .absent;
            if (hasDefault(param)) {
                if (self.defaults.get(@intCast(d.index()), @intCast(i))) |value| {
                    default = .{ .value = value };
                } else {
                    valid = false;
                }
            }
            if (ty == .poison) valid = false;
            callable_params[i] = .{
                .spelling = self.ast.tokenText(param.name),
                .convention = param.convention,
                .ty = ty,
                .default = default,
            };
        }
        // The signature's own reading of its result, in the scope its
        // parameters were read in; calls read a trait signature's again.
        const result = if (self.ast.declIsSignature(d)) try self.declaredResultType(d) else try returnType(self, d);
        if (!valid or result == .poison) {
            try self.noteContractRoots(params, self.ast.declContracts(d));
            return .poison;
        }
        const written = self.ast.declContracts(d);
        // A member supplying a trait signature and writing no clause promises
        // what the signature promises; every other function infers.
        if (written.len == 0) if (self.suppliedSignature(d)) |sig| {
            try self.adopted_contracts.put(self.gpa, d, sig);
            const adopted = (try self.adoptedContracts(callable_params, sig)) orelse {
                try self.declined_contracts.put(self.gpa, d, {});
                return self.builder.internCallable(callable_params, result, &.{}, .read);
            };
            defer types_mod.freeContracts(self.gpa, adopted);
            return self.builder.internCallable(callable_params, result, adopted, .read);
        };
        if (written.len == 0 and self.refused_owned_promises.contains(d)) {
            try self.declined_contracts.put(self.gpa, d, {});
            return self.builder.internCallable(callable_params, result, &.{}, .read);
        }
        var outcome: ContractOutcome = .{};
        const contracts = try self.normalizeContracts(callable_params, params, result, written, self.ast.declName(d), null, &outcome);
        defer types_mod.freeContracts(self.gpa, contracts);
        if (outcome.declined) try self.declined_contracts.put(self.gpa, d, {});
        if (outcome.carrier) |parameter| try self.defaulted_contracts.put(self.gpa, d, parameter);
        return self.builder.internCallable(callable_params, result, contracts, .read);
    }

    fn noteCallableDefault(self: *Checker, site: CallableDefaultSite) std.mem.Allocator.Error!void {
        const at = site.expr.index();
        if (self.callable_defaults_checked[at]) return;
        if (self.callable_defaults_ready) return self.checkCallableDefault(site);
        if (self.callable_default_sites[at] == null) self.callable_default_sites[at] = site;
        _ = try self.worth(site.expr);
    }

    /// The type a parameter of `d` holds a default of when its declared type
    /// `ty` is one of `d`'s own type parameters that writes a default, or null
    /// for every other type.
    fn defaultedTypeParameter(self: *Checker, d: node.DeclId, ty: TypeId) std.mem.Allocator.Error!?TypeId {
        if (ty == .poison) return null;
        const parameter = switch (self.builder.get(ty)) {
            .parameter => |p| p,
            else => return null,
        };
        if (parameter.owner != d.index()) return null;
        const generics = self.ast.declTypeParams(d);
        if (parameter.index >= generics.len or !generics[parameter.index].default.wasWritten()) return null;
        return try self.defaultAt(d, parameter.index);
    }

    fn rejectParameterDefault(self: *Checker, expression: ExprId, ty: TypeId) std.mem.Allocator.Error!bool {
        if (self.builder.get(ty) == .parameter) {
            _ = self.report(
                .t_default,
                expression,
                "a default cannot have the parameter type `{s}`",
                .{self.typeName(ty) catch return true},
                "the parameter type is settled by the call",
            );
            return true;
        }
        // A type mentioning a parameter or a projection is settled by the call.
        if (ty == .poison or try self.builder.allGround(&.{ty})) return false;
        _ = self.report(
            .t_default,
            expression,
            "a default cannot have the type `{s}`, which depends on a type parameter",
            .{self.typeName(ty) catch return true},
            "a default is one value, and this type is settled by the call",
        );
        return true;
    }

    /// Refuses a constant or default whose type owes settlement. The value is
    /// built afresh wherever a constant is read or a default omitted, and
    /// nothing at that point takes ownership of it, so a type with an
    /// obligation could never discharge it. Reported against the rule the
    /// caller names.
    fn refuseObligedConstant(self: *Checker, rule: Code, expression: ExprId, ty: TypeId) std.mem.Allocator.Error!bool {
        if (ty == .poison) return false;
        if (try self.builder.mayDiscardWithin(self.generic, ty)) return false;
        _ = self.report(
            rule,
            expression,
            "a constant of `{s}` would be built where nothing settles it",
            .{(try self.typeName(ty))},
            "a value of this type must be settled, so it cannot be a constant",
        );
        return true;
    }

    fn checkCallableDefault(self: *Checker, site: CallableDefaultSite) std.mem.Allocator.Error!void {
        const at = site.expr.index();
        if (self.callable_defaults_checked[at]) return;
        self.callable_defaults_checked[at] = true;

        const outer_module = self.current;
        const outer_generic = self.generic;
        self.current = site.module;
        self.generic = site.owner;
        defer {
            self.current = outer_module;
            self.generic = outer_generic;
        }

        const expected: ?Expected = if (site.ty == .poison) null else .{
            .ty = site.ty,
            .at = .{ .file = self.ast.fileOf(site.parameter), .span = self.ast.tokenSpan(site.parameter) },
            .reason = .parameter,
        };
        if (try self.rejectParameterDefault(site.expr, site.ty)) return;
        _ = try self.check(site.expr, expected);
        if (self.builder.exprType(site.expr) == .poison) return;
        const folded = try self.worth(site.expr);
        // An `inout` default is refused for that alone, which says all there
        // is to say about it.
        if (folded.checked() != null and site.convention != .inout and try self.refuseObligedConstant(.t_default, site.expr, site.ty)) return;
        const planned: Planned = if (folded.checked()) |value|
            try self.validateConstant(value, site.ty)
        else if (folded.isConstant()) .planned else .refused;
        if (planned != .planned) try self.reportDefaultNotConstant(site.expr, planned);
    }

    /// The label for an empty block where a constant is required, whole or as
    /// a part. Writing `{}` for the unit value is the mistake it answers.
    const empty_block_is_not_a_constant = "an empty block is not a constant; write `()` for the unit value";

    /// Whether a constant's initialiser holds `{}` where a value is built:
    /// the whole expression, or a part of a variant construction, structure
    /// literal or array literal, through any parentheses.
    ///
    /// **Bound:** the nodes of this one initialiser, each visited once.
    fn holdsEmptyBlock(self: *const Checker, id: ExprId) bool {
        if (id == ExprId.none) return false;
        const at = self.ast.withoutGroups(id);
        switch (self.ast.exprTag(at)) {
            .block => {
                const b = self.ast.blockOf(at);
                return self.ast.blockStmts(b).len == 0 and b.tail == ExprId.none;
            },
            .call => {
                // A variant is constructed through `.Name(…)` or
                // `Type.Name(…)`; any other call is not a constant anyway.
                const call = self.ast.call(at);
                switch (self.ast.exprTag(self.ast.withoutGroups(call.callee))) {
                    .variant_ref, .field => {},
                    else => return false,
                }
                for (call.args) |part| if (self.holdsEmptyBlock(part)) return true;
                return false;
            },
            .struct_literal, .array_literal, .tuple_literal => {
                for (self.ast.call(at).args) |part| if (self.holdsEmptyBlock(part)) return true;
                return false;
            },
            else => return false,
        }
    }

    /// Whether an expression, through any parentheses, names a module
    /// constant.
    fn namesConstant(self: *const Checker, id: ExprId) bool {
        const at = self.ast.withoutGroups(id);
        if (self.ast.exprTag(at) != .name_ref) return false;
        const target = self.res.targetOf(at);
        return target != BindingId.none and self.res.kindOf(target) == .constant;
    }

    /// Reports a default that is not a constant of its parameter's type.
    fn reportDefaultNotConstant(self: *Checker, at: ExprId, planned: Planned) std.mem.Allocator.Error!void {
        // A default naming a constant whose initialiser is not constant was
        // already reported at that constant's declaration.
        if (planned == .refused and self.namesConstant(at) and !(try self.worth(at)).isConstant()) return;
        switch (planned) {
            .uncopyable => |ty| try self.reportUncopyableConstant(.t_default, at, ty, "a default is built again at every call that omits it"),
            .planned, .refused => _ = self.report(
                .t_default,
                at,
                "a default is worked out where the parameter is declared, so it is a constant expression",
                .{},
                if (self.holdsEmptyBlock(at)) empty_block_is_not_a_constant else "this is not a constant",
            ),
        }
    }

    /// How a report writes `t` to a reader of the module being checked, by
    /// `writtenTypeName`: bare where the module names the type that way, and
    /// through its declaring module where it does not, so a report never
    /// writes two different types the same way.
    fn typeName(self: *const Checker, t: TypeId) std.mem.Allocator.Error![]const u8 {
        const pool = self.builder.view();
        return writtenTypeName(self.sink.arena, self.ast, self.program, self.res, &pool, self.current, t);
    }

    /// Reports a constant or default built from the parts of a type that is
    /// not copyable. The expression is a constant expression, and what stops
    /// it is the type: the value is built afresh wherever it is used, which is
    /// a copy. So the report names the type, and says to mark it `@copyable`
    /// where the program declares it; a library's type cannot be changed, so
    /// there the value is written where it is used instead.
    fn reportUncopyableConstant(self: *Checker, rule: Code, at: ExprId, ty: TypeId, built_again: []const u8) std.mem.Allocator.Error!void {
        const name = try self.typeName(ty);
        const declared = self.declaringType(ty);
        const help = if (declared != null and !self.declaredInLibrary(declared.?))
            try std.fmt.allocPrint(self.sink.arena, "mark `{s}` `@copyable`", .{name})
        else
            try std.fmt.allocPrint(self.sink.arena, "`{s}` is not copyable, so write the value where it is used instead", .{name});
        const labels = try self.sink.arena.alloc(Label, 1);
        labels[0] = .{
            .file = self.ast.fileOfExpr(at),
            .span = self.ast.exprSpan(at),
            .message = try std.fmt.allocPrint(self.sink.arena, "built from the parts of `{s}`, which is not copyable", .{name}),
        };
        const notes = try self.sink.arena.alloc([]const u8, 1);
        notes[0] = help;
        try self.sink.add(.{
            .severity = .err,
            .code = rule,
            .message = try std.fmt.allocPrint(self.sink.arena, "{s}, so `{s}` must be copyable", .{ built_again, name }),
            .labels = labels,
            .notes = notes,
        });
        _ = self.record(at, .poison);
    }

    /// Whether a head names a module.
    ///
    /// Read off what the resolver recorded. Which names are modules is that
    /// pass's answer, and asking the imports again here is a second answer
    /// that could disagree with it.
    fn namesAModule(self: *const Checker, tok: TokenId) bool {
        const head = self.res.writtenAt(tok);
        if (head == BindingId.none) return false;
        return self.res.kindOf(head) == .module;
    }

    /// Whether a bare name in type position is a type its trait declares.
    ///
    /// Read off what the resolver recorded, as every other question about what
    /// a name reached is: where a name written bare stands for a member is
    /// that pass's answer, and asking which declarations the trait holds again
    /// here is a second answer free to disagree with it.
    fn namesADeclaredType(self: *const Checker, tok: TokenId) bool {
        const b = self.res.writtenAt(tok);
        if (b == BindingId.none) return false;
        return self.res.kindOf(b) == .associated_type;
    }

    /// The name a dotted type ends at, where its head names a module and the
    /// run stops there. Null for every other head, and for a run that goes on
    /// past the module's type -- what is selected from a type is read through
    /// its bounds, which is the settled reference's own rule.
    fn qualifiedTypeName(self: *const Checker, ref: node.TypeRef) ?TokenId {
        if (ref.kind != .selection) return null;
        const base = self.ast.withoutTypeGroups(self.ast.selectionBase(ref));
        return if (base.kind == .named and self.namesAModule(base.name)) ref.name else null;
    }

    /// `pct.Thing`: the type a module declares, named through the module.
    ///
    /// The declaration is the one the resolver settled the name on, so the
    /// crossing is checked once and this reads its answer. Poison where it
    /// reached nothing or reached something that is not a type: both are
    /// mistakes about names, and that pass reports them.
    fn qualifiedTypeOf(
        self: *Checker,
        m: ModuleId,
        owner: node.DeclId,
        ref: node.TypeRef,
        at: TokenId,
    ) std.mem.Allocator.Error!TypeId {
        if (self.res.aliasReachedBy(at)) |alias| {
            const applied = try self.appliedAlias(m, owner, at, alias, ref.args);
            if (at.index() < self.written_types.len) self.written_types[at.index()] = applied;
            return applied;
        }
        const d = self.declOfWritten(m, owner, ref) orelse return .poison;
        const settled = try self.settledWith(
            m,
            owner,
            at,
            self.type_of_decl.get(d),
            d,
            ref.args,
        );
        self.recordWritten(owner, at, settled);
        return settled;
    }

    /// `Self.Item`: the type the implementation settled that name to.
    ///
    /// One reading for both sides of the relation, because both hold the same
    /// two things -- an implementation and the trait member it answers. Inside
    /// an implementation, `Self` is the type it names and the implementation
    /// is the one enclosing what is being read. At a call, `Self` is what the
    /// call settled and the implementation is the one that answers it, which
    /// is the same lookup the call itself makes to find the body it runs.
    ///
    /// A head that is a type parameter has no implementation to be read
    /// through and is read through its bound instead, which is the other
    /// routine below.
    ///
    /// Poison where the implementation is not yet known -- a trait's own
    /// signature, read where no call has settled anything. Nothing is assumed
    /// of it there: a signature has no body, so there is nothing to check the
    /// settled reference against until a call reaches it.
    fn settledRefTypeOf(
        self: *Checker,
        owner: node.DeclId,
        ref: node.TypeRef,
    ) std.mem.Allocator.Error!TypeId {
        return (try self.selectedReference(owner, ref)).ty;
    }

    fn selectedReference(self: *Checker, owner: node.DeclId, ref: node.TypeRef) std.mem.Allocator.Error!Selected {
        const base = self.ast.withoutTypeGroups(self.ast.selectionBase(ref));
        const from: Selected = if (base.kind == .selection and self.qualifiedTypeName(base) == null)
            try self.selectedReference(owner, base)
        else
            .{
                .ty = try self.typeOfRefOf(self.program.moduleOf(owner), owner, base),
                .named = base.name,
                .settled_once = true,
            };
        if (ref.dot != .none and !self.type_selections.contains(ref.dot)) {
            try self.type_selections.put(self.gpa, ref.dot, .{ .base = from.ty, .member = ref.name, .owner = owner });
        }
        if (ref.name == .none or self.refusedBefore(ref.name)) return .{};
        const run: Run = .{ .last = ref.name, .span = self.ast.writtenSpan(ref) };
        if (ref.args.len() > 0) {
            try self.noteRefused(run.last);
            try self.refuseTypeArity(run.span, run.last, 0, 0, ref.args.len(), null);
            return .{};
        }
        const step: Selected = if (refNamesSelf(self.ast, base))
            try self.selfSelected(owner, ref, run, ref.name)
        else if (base.kind == .named and self.headParameter(owner, base.name) != null) blk: {
            const head = self.headParameter(owner, base.name).?;
            break :blk try self.throughBounds(ref, run, .{
                .bounds = self.boundsOnParameter(head.ty),
                .named = base.name,
                .ty = head.ty,
                .settled_once = true,
            }, ref.name);
        } else blk: {
            if (from.ty == .poison) return .{};
            if (from.declared != .none and self.ast.declBounds(from.declared).len != 0) {
                break :blk try self.throughBounds(ref, run, .{
                    .bounds = self.ast.declBounds(from.declared),
                    .named = from.named,
                    .ty = from.ty,
                    .settled_once = from.settled_once,
                }, ref.name);
            }
            break :blk try self.structuralSelected(owner, ref, run, from.ty);
        };
        if (ref.dot != .none) {
            if (self.type_selections.getPtr(ref.dot)) |selection| {
                selection.declaration = step.declared;
                selection.head_definition = step.head_definition;
            }
        }
        if (step.settled_once) self.recordWritten(owner, ref.name, step.ty);
        return step;
    }

    fn structuralSelected(self: *Checker, owner: DeclId, ref: node.TypeRef, run: Run, held: TypeId) std.mem.Allocator.Error!Selected {
        // A signature read where a call reaches it is read in the caller's
        // scope: the type its `Self` stands for is the caller's, and so is
        // what proves the implementation that type answers through.
        const scope = if (self.ast.declIsSignature(owner) and self.self_at_call != null) self.generic else owner;
        try self.builder.prepareLookupWithin(scope, held);
        const pool = try self.builder.capabilityView();
        var reach = self.reaching(&pool);
        reach.from = self.program.moduleOf(owner);
        reach.scope = scope;
        var candidates: std.ArrayList(Associated) = .empty;
        defer candidates.deinit(self.gpa);
        try reach.associated(self.gpa, held, self.ast.tokenName(ref.name), &candidates);
        if (candidates.items.len != 1) {
            try self.noteRefused(run.last);
            if (candidates.items.len == 0) {
                try self.sink.addErrorFmt(.t_impl, self.ast.fileOf(ref.at), run.span, "bring the trait into scope or add a bound declaring this associated type", "`{s}` has no available associated type `{s}`", .{ (try self.typeName(held)), self.ast.tokenText(ref.name) });
            } else {
                try self.sink.addErrorFmt(.n_ambiguous, self.ast.fileOf(ref.at), run.span, "select the associated type through one explicit bound", "`{s}` has more than one applicable trait key declaring `{s}`", .{ (try self.typeName(held)), self.ast.tokenText(ref.name) });
            }
            return .{};
        }
        const selected = candidates.items[0];
        // Interning can move pool arrays backing the selected key.
        const args = try self.gpa.dupe(TypeId, selected.args);
        defer self.gpa.free(args);
        const settled = try self.builder.settledAtWithin(scope, selected.trait.index(), args, held, selected.sig, self.ast.tokenText(ref.name));
        return .{ .ty = settled.ty, .declared = selected.sig, .named = ref.name, .settled_once = true, .head_definition = settled.head_definition };
    }

    test "component requirement resolution rejects open arguments" {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const sink = try diagnose(arena.allocator(),
            \\trait Required[phantom T] {}
            \\trait Structural {}
            \\struct Open {}
            \\template impl Structural where reflect.components: Required[Open.Item] {}
            \\struct Target {}
            \\derive Structural for Target
            \\fn main() -> UInt8 { let _target: Target = .{}; 0 }
        );
        try testing.expectEqual(@as(usize, 1), sink.items().len);
        try testing.expect(diagnosticSays(&sink, .t_template, "has no available associated type"));
    }

    /// A name a run reached, and what may be selected from it next.
    const Selected = struct {
        /// The type the run has reached.
        ty: TypeId = .poison,
        /// The declared type the name reached, whose bounds are what a name
        /// after it is read through. `.none` where the name reached none.
        declared: node.DeclId = node.DeclId.none,
        /// The token that name is, which is what a message about the next
        /// step names as what it was selected from.
        named: TokenId = .none,
        /// Whether what the run reached is one answer wherever it is read. A
        /// key written out is; what a call settled `Self` to is not.
        settled_once: bool = false,
        /// Whether the name was read through a bound on a key still holding a
        /// parameter and settled to the definition an implementation headed
        /// by a bare parameter gives it, rather than to a stand-in.
        head_definition: bool = false,
    };

    /// What a name is selected from: the bounds it is read through, the name
    /// carrying them, and the type they are attached to.
    const ReadThrough = struct {
        bounds: []const node.TraitBound,
        named: TokenId,
        ty: TypeId,
        settled_once: bool,
    };

    /// A settled reference being read: what a message about it underlines, and
    /// the token a refusal of it is recorded against.
    ///
    /// The run rather than the name a step failed at, because a written type is
    /// read once per position that holds it and a refusal of it is one mistake:
    /// recorded against a name inside the run, a second reading would find
    /// nothing recorded for the run and report it again.
    const Run = struct { last: TokenId, span: Span };

    /// `Item` written inside the trait that declares it: the type an
    /// implementation settled that name to.
    ///
    /// `Self.Item` without the head, which is the same declaration reached the
    /// same way, so this is the reading and not a second one. Recorded against
    /// no token: the bare name stands only in a trait's own signature, where
    /// what it settles to is whatever the call settled and one table would
    /// hold the last call's answer for every reader of a signature every
    /// implementation shares.
    fn declaredTypeOf(
        self: *Checker,
        owner: node.DeclId,
        ref: node.TypeRef,
    ) std.mem.Allocator.Error!TypeId {
        if (self.refusedBefore(ref.name)) return .poison;

        const run: Run = .{ .last = ref.name, .span = self.ast.tokenSpan(ref.name) };

        // A trait declares a type and no parameter list beside it, however the
        // name is written.
        if (ref.args.len() > 0) {
            try self.noteRefused(run.last);
            try self.refuseTypeArity(run.span, run.last, 0, 0, ref.args.len(), null);
            return .poison;
        }

        const step = try self.selfSelected(owner, ref, run, ref.name);
        return step.ty;
    }

    /// A name read through the implementation `Self` names, whether the head
    /// was written or the trait's own braces left it out.
    fn selfSelected(
        self: *Checker,
        owner: node.DeclId,
        ref: node.TypeRef,
        run: Run,
        at: TokenId,
    ) std.mem.Allocator.Error!Selected {
        // An inherent implementation implements no trait, so nothing declared
        // the name and nothing settled it. Said here rather than left as a
        // type nobody named: `Self` does reach the type this `impl` is for, so
        // the resolver had nothing to report about the head.
        if (!self.ast.declIsSignature(owner) and
            self.ast.declOwner(owner) != TokenId.none and
            self.ast.declTrait(owner) == TokenId.none)
        {
            try self.noteRefused(run.last);
            try self.sink.addErrorFmt(
                .t_impl,
                self.ast.fileOf(ref.at),
                run.span,
                "name the type itself, or move this to an implementation of a trait",
                "a settled reference is read through a trait's implementation, and this `impl` names no trait",
                .{},
            );
            return .{};
        }

        const reading = try self.implementationReading(owner) orelse {
            return self.standinAwaitingInstantiation(owner, run, at);
        };

        const sig = try self.declaredTypeNamed(reading.trait, run, at) orelse return .{};

        // Poison where the implementation settles nothing for it, which is the
        // hole [T-Impl] reports against the implementation itself: said once,
        // where the member is missing rather than at every type written in
        // terms of it.
        const settled = try self.builder.settledBy(reading.impl, sig, reading.impl_args) orelse return .{};

        return .{
            .ty = settled,
            .declared = sig,
            .named = at,
            .settled_once = !self.ast.declIsSignature(owner),
        };
    }

    /// `W.Item`, and `O.Mid.Item`: a name read through the bounds on whatever
    /// carries them.
    ///
    /// One question, whatever holds the bounds. A type parameter holds the
    /// ones written on it, and a declared type holds the ones its trait wrote
    /// -- `type Mid: Inner` is what makes `Item` selectable from `O.Mid` -- and
    /// past that the reading is the same: the bound names the trait, so nothing
    /// is searched for, and the trait's declared type is what the name reaches.
    ///
    /// What the name settles to is the key where what it was selected from is
    /// unknown. A body checked once stands for every type the bound admits, so
    /// which type the name settles to is decided at each instantiation, exactly
    /// as which type the head stands for is -- and what it stands for here is
    /// the key that will name it: the bound's trait, what it was selected from,
    /// and the member. Where that is a type, the implementation it names is
    /// what settled the member, which is the lookup a call already makes.
    ///
    /// A part of a declared type holds one on the same terms. Each
    /// instantiation substitutes its own argument for the head, and settling
    /// the key that leaves is what makes `Holder[Counter]`'s part and
    /// `Holder[Flag]`'s two types rather than the one the template wrote.
    ///
    /// **Bound:** the bounds written on the one name, and one keyed lookup for
    /// the type.
    fn throughBounds(
        self: *Checker,
        ref: node.TypeRef,
        run: Run,
        through: ReadThrough,
        at: TokenId,
    ) std.mem.Allocator.Error!Selected {
        const found = try resolve_mod.boundDeclaring(
            through.bounds,
            self.ast.tokenName(at),
            BoundsRead{ .checker = self },
        );

        // A capability bound declares nothing, so a name holding only one of
        // those carries no trait here.
        if (found.traits == 0) {
            try self.noteRefused(run.last);
            try self.sink.addErrorFmt(
                .t_impl,
                self.ast.fileOf(ref.at),
                run.span,
                "bound it by the trait that declares the name",
                "a settled reference selects `{s}` through a bound, and `{s}` carries none",
                .{ self.ast.tokenText(at), self.ast.tokenText(through.named) },
            );
            return .{};
        }

        // Two bounds declaring the name is two declarations the reference
        // reaches, and nothing written here says which -- a settled reference
        // names one type, and a qualification that picks between them is
        // syntax no caller has needed. So it names neither, and what a caller
        // has instead is a name bounded by one of them.
        if (found.declaring > 1) {
            try self.noteRefused(run.last);
            try self.sink.addErrorFmt(
                .n_ambiguous,
                self.ast.fileOf(ref.at),
                run.span,
                "bound it by one of them",
                "`{s}` and `{s}` both declare `{s}`, and a type carrying both bounds reads it through neither",
                .{
                    self.ast.tokenText(found.bound),
                    self.ast.tokenText(found.also),
                    self.ast.tokenText(at),
                },
            );
            return .{};
        }

        // A name none of them declares, said of the bounds together where
        // there are several: naming one of them would report a hole in that
        // trait and leave a reader to find that the others have it too.
        if (found.declaring == 0 and found.traits > 1) {
            try self.noteRefused(run.last);
            try self.sink.addErrorFmt(
                .t_impl,
                self.ast.fileOf(ref.at),
                run.span,
                "name a type one of them declares",
                "a settled reference is read through a trait's bound, and none of `{s}`'s {d} bounds declares `{s}`",
                .{ self.ast.tokenText(through.named), found.traits, self.ast.tokenText(at) },
            );
            return .{};
        }

        // Every bound counted above named a trait, and a run carrying one
        // trait answers with it whether or not that trait declares the name --
        // so a count above zero leaves a declaration to read here, and with
        // one trait bounded and nothing declaring the name that trait is what
        // the hole is reported against below. Guarded rather than indexed on:
        // what must not happen is reading a declaration that is not one, and
        // saying so costs a comparison.
        const trait = if (found.trait == node.DeclId.none) return .{} else found.trait;

        // The trait a bound names is discharged at the arguments it named, so
        // a declared type read through it is settled by the same pair
        // `boundsCarry` discharges at -- read here rather than re-derived from
        // the bound's written arguments a second time, since the parameter's
        // own bounds already interned them when it was declared. The bound
        // the name is read through is what picks the entry, because one trait
        // may bound the parameter at several arguments.
        const args = self.boundArgsWritten(through.ty, trait, .{ .named = .{ .name = found.bound, .args = found.args } });

        const sig = try self.declaredTypeNamed(trait, run, at) orelse return .{};

        // In the scope of the declaration being read, so its `where` clauses
        // prove what the implementation answering needs.
        const settled = try self.builder.settledAtWithin(
            self.generic,
            @intCast(trait.index()),
            args,
            through.ty,
            sig,
            self.ast.tokenText(at),
        );
        return .{
            .ty = settled.ty,
            .declared = sig,
            .named = at,
            .settled_once = through.settled_once,
            .head_definition = settled.head_definition,
        };
    }

    /// The declared type a settled reference names, or null where the trait
    /// declares no such thing and the refusal has been reported.
    ///
    /// One reader for every step. Which trait the name is read through is what
    /// differs -- the implementation's for `Self`, the bound's for everything
    /// selected through one -- and what that trait must declare is one question
    /// however the reader got there.
    ///
    /// Which member the name reaches is the resolver's answer, read here
    /// rather than matched again: a name reaches one declaration, and the pass
    /// that decides which is the one that decides it for every other name in
    /// the program.
    fn declaredTypeNamed(
        self: *Checker,
        trait: node.DeclId,
        run: Run,
        at: TokenId,
    ) std.mem.Allocator.Error!?node.DeclId {
        const sig = self.memberNamed(at) orelse blk: {
            var members = self.res.signatures.typesOf(self.ast, trait);
            while (members.next()) |member| {
                if (self.ast.tokenName(self.ast.declName(member)) == self.ast.tokenName(at)) break :blk member;
            }
            break :blk @as(?DeclId, null);
        } orelse {
            try self.noteRefused(run.last);
            try self.sink.addErrorFmt(
                .t_impl,
                self.ast.fileOf(at),
                self.ast.tokenSpan(at),
                "declare it on the trait, or name one it declares",
                "`{s}` declares no `{s}`",
                .{ self.ast.tokenText(self.ast.declName(trait)), self.ast.tokenText(at) },
            );
            return null;
        };
        if (!settlesAType(self.ast, sig)) {
            try self.noteRefused(run.last);
            try self.sink.addErrorFmt(
                .t_impl,
                self.ast.fileOf(at),
                self.ast.tokenSpan(at),
                "name a type the trait declares",
                "`{s}` declares `{s}` as {s}, and a settled reference names a type",
                .{
                    self.ast.tokenText(self.ast.declName(trait)),
                    self.ast.tokenText(at),
                    memberKind(self.ast, sig).noun(),
                },
            );
            return null;
        }
        return sig;
    }

    /// The trait's arguments a signature of `trait` is read at: what a call or
    /// an implementation settled them to, or, where the signature is read at
    /// its own symbolic `Self`, the trait's own parameters -- the arguments a
    /// call from a provided body passes on, so `Self.Out` in the body's
    /// declared result and in what the call returns is one key.
    fn traitArgumentsHere(self: *const Checker, trait: node.DeclId) []const TypeId {
        if (self.self_settled or trait.index() >= self.param_types.len) return self.trait_args_at_call;
        return self.param_types[trait.index()];
    }

    /// What a settled reference stands for where the call reading it names no
    /// implementation because part of the key is still a parameter.
    ///
    /// Every part of the key is asked about at once -- `Self` and the arguments
    /// the call supplies for the trait's parameters -- because any one of them
    /// being a parameter leaves the same question open: the bound promises an
    /// implementation exists for whatever settles it, and which one that is is
    /// settled where every other part of the key is, at the instantiation. So
    /// the reference stands for the key itself, and substitution settles it
    /// when the key becomes one.
    ///
    /// Poison anywhere else, which is a `Self` no call settled: the resolver
    /// has already said what that is, and a type standing for a key half of
    /// which is missing would agree with whatever is written around it.
    fn standinAwaitingInstantiation(
        self: *Checker,
        owner: node.DeclId,
        run: Run,
        at: TokenId,
    ) std.mem.Allocator.Error!Selected {
        if (!self.ast.declIsSignature(owner)) return .{};
        const trait = self.traitDeclaring(owner) orelse return .{};
        const held = self.self_at_call orelse return .{};
        if (held == .poison) return .{};
        const trait_args = self.traitArgumentsHere(trait);
        if (!self.builder.awaitsTypes(held, trait_args)) return .{};

        const sig = try self.declaredTypeNamed(trait, run, at) orelse return .{};
        return .{
            .ty = try self.builder.addSettledStandin(
                @intCast(trait.index()),
                trait_args,
                held,
                sig,
                self.ast.tokenText(at),
            ),
            .declared = sig,
            .named = at,
        };
    }

    /// The implementation a settled reference is read through, and the trait
    /// whose members it may name.
    /// The receiver is carried beside the row because what the implementation
    /// settled is written in the implementation's own parameters, and the
    /// receiver is what fills them.
    const Reading = struct {
        impl: types_mod.Implementation,
        trait: node.DeclId,
        impl_args: []const TypeId,
    };

    /// Which implementation answers a settled reference written inside `owner`.
    ///
    /// Two positions and one answer. A member of an implementation is read
    /// through the implementation it sits in; a signature is read through
    /// whichever implementation the call settled `Self` to, found by the key
    /// coherence makes unique -- the trait, what the call supplied for its
    /// parameters, and the type itself.
    ///
    /// Null where there is none to name: a trait's own signature away from any
    /// call, a call whose `Self` is a type parameter, and every position no
    /// implementation encloses -- where `Self` reaches nothing and the
    /// resolver has already said so.
    fn implementationReading(self: *Checker, owner: node.DeclId) std.mem.Allocator.Error!?Reading {
        if (owner == node.DeclId.none) return null;

        if (self.ast.declIsSignature(owner)) {
            const trait = self.traitDeclaring(owner) orelse return null;
            const held = self.self_at_call orelse return null;
            if (held == .poison) return null;
            // Header validation compares a default's members with its own
            // associated definitions, before any concrete receiver selects it.
            if (self.generic != .none and self.ast.declTag(self.generic) == .impl_) {
                if (self.rowFor(self.generic)) |row| {
                    if (row.head == .default_ and row.trait == trait.index() and row.ty == held)
                        return .{ .impl = row.*, .trait = trait, .impl_args = self.param_types[self.generic.index()] };
                }
            }
            const choice = try self.builder.implementationChoiceWithin(
                self.generic,
                trait,
                self.traitArgumentsHere(trait),
                held,
            ) orelse return null;
            const implementation = choice.declaredImplementation() orelse return null;
            const row = self.builder.implementations[implementation.index()];
            if (row.isAmbient()) return null;
            return .{ .impl = row, .trait = trait, .impl_args = choice.impl_args };
        }

        const found = self.enclosingRow(owner) orelse return null;
        // A settled reference is a trait's declared type read through the
        // implementation that settles it, and an inherent `impl` declares no
        // trait to have settled one.
        if (!found.ofATrait()) return null;
        // The head as the implementation declared it, which is what a member
        // written inside it is written against: its parameters are in scope
        // here, so substituting through it leaves what the member wrote.
        return .{ .impl = found, .trait = node.DeclId.at(found.trait), .impl_args = self.param_types[found.decl.index()] };
    }

    /// The declaration a settled reference's name reached, or null where it
    /// reached none.
    fn memberNamed(self: *const Checker, at: TokenId) ?node.DeclId {
        const b = self.res.writtenAt(at);
        if (b == BindingId.none) return null;
        const d = self.res.declIfDeclared(b);
        return if (d == node.DeclId.none) null else d;
    }

    /// `[T; N]`, resolved with `owner`'s parameters in scope.
    ///
    /// The length is a written expression, so [T-ArraySize] is asked of it by
    /// the routine that folds a constant expression wherever one is read -- a
    /// length read at run time cannot say what a type is.
    ///
    /// Every refusal here is one coherence declined to key: the walk that
    /// compares implementations leaves an array whose length counts nothing
    /// out of the comparison entirely, because neither answer it could give
    /// for one is sound. So this is where such a program is refused, and
    /// softening any of these into an accepted type would admit two
    /// implementations of what may be one type with declaration order deciding
    /// which a call reaches.
    fn arrayTypeOf(
        self: *Checker,
        m: ModuleId,
        owner: node.DeclId,
        ref: node.TypeRef,
    ) std.mem.Allocator.Error!TypeId {
        const written = self.ast.typeArgs(ref.args);
        const element = if (written.len == 0)
            TypeId.poison
        else
            try self.typeOfRefOf(m, owner, written[0]);

        return self.arrayTypeWithElement(ref, element);
    }

    /// Resolves a binding's written type, counting each `_` length from the
    /// array literal the binding is initialized with. Local bindings and
    /// constants both read their type here, before their elements are
    /// checked. Each dimension reads only its first row; ordinary checking
    /// then verifies every row against the resulting concrete array type.
    fn bindingTypeCountingLiteral(self: *Checker, written: node.TypeRef, initializer: ExprId) std.mem.Allocator.Error!TypeId {
        const ref = self.ast.withoutTypeGroups(written);
        if (ref.kind != .array) return self.typeOfRef(ref);
        const arguments = self.ast.typeArgs(ref.args);
        if (arguments.len != 1) return .poison;
        const literal = if (initializer == .none) ExprId.none else self.ast.withoutGroups(initializer);
        const items: ?[]const ExprId = if (literal != .none and self.ast.exprTag(literal) == .array_literal)
            self.ast.call(literal).args
        else
            null;
        const inferred = ref.inferred_length != .none;
        if (inferred and items == null) return self.refuseArrayInference(ref, true);
        const element_initializer = if (items) |elements|
            (if (elements.len == 0) ExprId.none else elements[0])
        else
            ExprId.none;
        // An element type that names nothing leaves the length still read,
        // as it is wherever an array type is written.
        const element = try self.bindingTypeCountingLiteral(arguments[0], element_initializer);
        if (inferred) return self.builder.arrayOf(element, @intCast(items.?.len));
        return self.arrayTypeWithElement(ref, element);
    }

    /// Reports a `_` length with no array literal to count. `in_binding`
    /// says whether the marker stands in a binding's own type, where a
    /// literal initializer would have supplied the count.
    fn refuseArrayInference(self: *Checker, ref: node.TypeRef, in_binding: bool) std.mem.Allocator.Error!TypeId {
        if (self.refusedBefore(ref.inferred_length)) return .poison;
        try self.noteRefused(ref.inferred_length);
        self.reportAtToken(
            .t_array_size,
            ref.inferred_length,
            if (in_binding)
                "an inferred array length needs an array literal to count"
            else
                "an inferred array length belongs to a binding initialized with an array literal",
            if (in_binding)
                "supply an array literal or write an explicit length"
            else
                "write an explicit length in this type",
            null,
        );
        return .poison;
    }

    fn refuseUncountedLength(self: *Checker, length: ExprId) TypeId {
        return self.report(
            .t_array_size,
            length,
            "an array's length is a count, and a count is a number",
            .{},
            "this is not a number",
        );
    }

    /// Concrete lengths share constant folding and validation in declarations
    /// and bindings. An inference marker reaches here only outside a binding
    /// initialized with an array literal.
    fn arrayTypeWithElement(self: *Checker, ref: node.TypeRef, element: TypeId) std.mem.Allocator.Error!TypeId {
        if (ref.inferred_length != .none) return self.refuseArrayInference(ref, false);
        if (ref.length == ExprId.none) return .poison;
        const length = try self.arrayLength(ref.length) orelse return .poison;
        return self.builder.arrayOf(element, length);
    }

    /// What the length written in an array type counts, or null where it was
    /// refused.
    ///
    /// Checked once per written length. A written type is read again wherever
    /// it is named -- a structure's field types are read each time it is laid
    /// out -- and checking the length again would report each mistake in it
    /// again and record each value of an interpolated literal again.
    fn arrayLength(self: *Checker, length: ExprId) std.mem.Allocator.Error!?u32 {
        if (self.array_lengths.get(length)) |counted| return counted;
        // Null until counted, so a length whose own check reads it again
        // reads a refusal rather than counting itself.
        try self.array_lengths.put(self.gpa, length, null);
        const counted = try self.countLength(length);
        try self.array_lengths.put(self.gpa, length, counted);
        return counted;
    }

    fn countLength(self: *Checker, length: ExprId) std.mem.Allocator.Error!?u32 {
        const written_as = try self.check(length, null);

        // The routine that folds a constant expression wherever one is read,
        // and not this pass's own table of what it has folded so far: which
        // implementations a program holds is decided by lengths before this
        // pass runs, so a length worth one thing there and another here would
        // be two answers to what a type is.
        //
        // A count is a number, and being a constant expression is not enough
        // to be one: only the integer variant supplies a length. Boolean and
        // text constants are different domains. A length that is not a
        // constant at all is told which of the two it failed, since a form the
        // definition does not admit may be no number either.
        const folded = switch (try self.worth(length)) {
            // A newtype's constant folds to the integer it holds, and is still
            // its own type rather than a number.
            .integer => |v| if (written_as != .poison and self.builder.get(written_as) == .newtype) {
                _ = self.refuseUncountedLength(length);
                return null;
            } else v,
            .truth, .string, .aggregate => {
                _ = self.refuseUncountedLength(length);
                return null;
            },
            .not_constant, .absent => {
                if (written_as != .poison and written_as.integerInfo() == null) {
                    _ = self.refuseUncountedLength(length);
                } else _ = self.report(
                    .t_array_size,
                    length,
                    "an array's length is part of its type, so it is settled where the type is written",
                    .{},
                    "this is not a constant",
                );
                return null;
            },
        };
        if (folded < 0) {
            _ = self.report(
                .t_array_size,
                length,
                "an array's length is a count, and a count is not negative",
                .{},
                "this is negative",
            );
            return null;
        }

        if (folded > std.math.maxInt(u32)) {
            _ = self.report(
                .t_array_size,
                length,
                "an array's length is part of its type, and this one is too wide to be",
                .{},
                "no array holds this many elements",
            );
            return null;
        }

        return @intCast(folded);
    }

    /// A written type, resolved with `owner`'s parameters in scope.
    ///
    /// A signature belongs to the declaration that wrote it, so reading a
    /// callee's from the caller has to say whose parameters `T` means. The
    /// arguments come with it: dropping them leaves a generic type resolving
    /// to its own template, which is not a type.
    fn settleRef(
        self: *Checker,
        m: ModuleId,
        owner: node.DeclId,
        tok: TokenId,
        args: node.TypeRefRange,
    ) std.mem.Allocator.Error!TypeId {
        // `Self` inside an implementation whose head applies arguments is that
        // head, arguments and all -- an instantiation, not the constructor it
        // names. It is applied already, so no declaration is left to
        // instantiate and it takes none of its own whatever its constructor
        // declares: a written argument is refused against that count.
        if (self.selfAppliedHere(owner, tok)) |applied| {
            return self.settledWith(m, owner, tok, applied, null, args);
        }

        if (self.aliasWritten(owner, tok)) |alias| {
            return self.appliedAlias(m, owner, tok, alias, args);
        }

        return self.settledWith(
            m,
            owner,
            tok,
            self.typeOfTokenOf(m, owner, tok),
            self.declOfType(m, owner, tok),
            args,
        );
    }

    /// A head and the arguments written after it, settled into one type.
    ///
    /// The head is handed in rather than looked up, because how a name reaches
    /// its declaration is what the two spellings differ in and nothing else
    /// is: a name in scope reaches one through this module, and a dotted one
    /// through the module its head names. What a head does with arguments is
    /// the same question either way, so it is answered here once -- and the
    /// arguments are read in the module doing the writing, which is where the
    /// names in them are written.
    fn settledWith(
        self: *Checker,
        m: ModuleId,
        owner: node.DeclId,
        tok: TokenId,
        head: TypeId,
        of: ?node.DeclId,
        args: node.TypeRefRange,
    ) std.mem.Allocator.Error!TypeId {
        const wanted: u32 = if (of) |d|
            @intCast(self.ast.declTypeParams(d).len)
        else
            0;
        const required: u32 = if (of) |d| self.ast.declRequiredTypeParams(d) else 0;
        const written = args.len();

        if (wanted == 0 and written == 0) return head;
        if (head == .poison) return .poison;

        if (written > wanted or written < required) {
            if (self.refusedBefore(tok)) return .poison;
            try self.noteRefused(tok);
            try self.refuseTypeArity(self.ast.tokenSpan(tok), tok, required, wanted, written, null);
            return .poison;
        }

        const decl = of orelse return .poison;
        if (written < wanted and try self.refusedDefaultedAllocator(owner, tok, .none, decl, written)) return .poison;

        const supplied = try self.gpa.alloc(TypeId, wanted);
        defer self.gpa.free(supplied);
        for (self.ast.typeArgs(args), 0..) |a, i| {
            supplied[i] = try self.typeOfRefOf(m, owner, a);
        }
        try self.fillDefaults(decl, supplied, written);
        for (written..wanted) |i| try self.checkCarriedOmission(owner, tok, decl, i);
        const made = try self.builder.instantiate(head, decl, supplied);

        // Bound validation waits until representations and callable effects
        // are complete, so declaration order cannot change their evidence.
        if (self.callable_effects_ready) try self.bound_sites.append(self.gpa, .{ .ty = made, .at = tok, .within = owner });
        return made;
    }

    /// The arguments a written type omitted, read from the defaults the
    /// declaration gives its trailing parameters.
    ///
    /// A default is read where its declaration is, so it means the same type
    /// from every module that omits it. A default that is itself refused
    /// poisons the type, which its declaration already reported.
    fn fillDefaults(self: *Checker, decl: node.DeclId, supplied: []TypeId, written: usize) std.mem.Allocator.Error!void {
        for (supplied[written..], written..) |*slot, i| slot.* = try self.defaultAt(decl, i);
    }

    /// [T-DefaultedAllocator] for a written type that omits the allocator its
    /// declaration defaults, inside a declaration that declares an allocator
    /// parameter of its own.
    ///
    /// Such a declaration is generic over where memory comes from, and a type
    /// written without it would silently mean the system allocator and exclude
    /// every other. The remedy is to write the parameter, or to write the
    /// default out where the system allocator is meant. A declaration that
    /// declares no allocator parameter writes the short form freely.
    ///
    /// `callee` is the whole path a call names, underlined as one, where the
    /// default was taken by a call; a written type has none and is underlined
    /// at `tok`.
    fn refusedDefaultedAllocator(
        self: *Checker,
        owner: node.DeclId,
        tok: TokenId,
        callee: ExprId,
        decl: node.DeclId,
        written: usize,
    ) std.mem.Allocator.Error!bool {
        const allocator = self.allocator_decl orelse return false;
        const parameters = self.ast.declTypeParams(decl);
        const omitted = for (parameters[written..], written..) |parameter, i| {
            if (self.isBoundedBy(parameter, allocator)) break i;
        } else return false;
        const declared = self.allocatorParameterOf(owner, allocator) orelse {
            // A call takes its type's or its function's default wherever it
            // is written; only a written type is held to a library's rule.
            if (callee != ExprId.none) return false;
            // The type is the system form all the same, so it settles as
            // written and nothing downstream is refused because of it.
            if (try self.publicLibrarySignature(owner, tok)) {
                if (self.refusedBefore(tok)) return false;
                try self.noteRefused(tok);
                try self.reportLibraryDefault(owner, tok, self.ast.tokenText(tok), null);
                return false;
            }
            try self.recordCarriedOmission(owner, null, tok);
            return false;
        };
        if (self.refusedBefore(tok)) return true;
        try self.noteRefused(tok);
        const default = try self.defaultAt(decl, omitted);
        try self.sink.addErrorFmt(
            .t_defaulted_allocator,
            self.ast.fileOf(tok),
            if (callee == ExprId.none) self.ast.tokenSpan(tok) else self.ast.exprSpan(callee),
            try std.fmt.allocPrint(self.sink.arena, "write the allocator: `{s}`, or `{s}` where the system allocator is meant", .{ self.ast.tokenText(declared), try self.typeName(default) }),
            "`{s}` leaves its allocator `{s}` to a default, and this declaration is generic over an allocator itself",
            .{ if (callee == ExprId.none) self.ast.tokenText(tok) else self.ast.exprText(callee), self.ast.tokenText(parameters[omitted].name) },
        );
        return true;
    }

    /// Where a declaration carries an omission a public signature cannot
    /// see: `inside`, explained by `why`.
    const Carried = struct { inside: TokenId, why: []const u8 };

    /// The key `carried_omissions` gives an alias's written type.
    const alias_body: u64 = 0xffff_ffff;

    fn carriedKey(decl: node.DeclId, slot: u64) u64 {
        return (@as(u64, decl.index()) << 32) | slot;
    }

    /// Records that `owner`, a declaration of a library root that is not
    /// public, leaves an allocator to its default: in the default of its type
    /// parameter being read, or in an alias's written type. `reached` is what
    /// a type `owner` wrote carries, where the omission sits further in;
    /// otherwise it sits at `inside`, written in `owner` itself. A public
    /// signature that reaches it is refused where it names `owner`. The one
    /// place such an omission is recorded, whether `owner` wrote it or reached
    /// it through another alias or default.
    fn recordCarriedOmission(self: *Checker, owner: node.DeclId, reached: ?Carried, inside: TokenId) std.mem.Allocator.Error!void {
        if (owner == node.DeclId.none or !self.program.inLibraryRoot(self.program.moduleOf(owner))) return;
        const key = if (self.reading_default) |reading| (if (reading >> 32 == owner.index()) reading else null) else null;
        if (key) |reading| {
            // A default that names a parameter of its own list was refused
            // where it is written, and carries nothing further.
            const parameter = self.ast.declTypeParams(owner)[@intCast(reading & 0xffff_ffff)];
            if (self.mentionsTypeParameter(owner, parameter.default)) return;
        }
        const slot = key orelse if (self.ast.declTag(owner) == .alias) carriedKey(owner, alias_body) else return;
        const held = try self.carried_omissions.getOrPut(self.gpa, slot);
        if (held.found_existing) return;
        held.value_ptr.* = reached orelse .{
            .inside = inside,
            .why = if (key != null) "this default leaves the allocator to its default" else "the alias leaves the allocator to its default here",
        };
    }

    /// [T-DefaultedAllocator] where a type written at `tok` in `owner` reaches
    /// an omission `decl` carries in `slot`, or records it on `owner` when
    /// that is not a public signature either.
    fn checkCarriedOmission(self: *Checker, owner: node.DeclId, tok: TokenId, decl: node.DeclId, slot: u64) std.mem.Allocator.Error!void {
        const carried = self.carried_omissions.get(carriedKey(decl, slot)) orelse return;
        if (try self.publicLibrarySignature(owner, tok)) {
            if (self.refusedBefore(tok)) return;
            try self.noteRefused(tok);
            try self.reportLibraryDefault(owner, tok, self.ast.tokenText(carried.inside), carried);
            return;
        }
        try self.recordCarriedOmission(owner, carried, carried.inside);
    }

    /// [T-DefaultedAllocator] for a public signature of a library that leaves
    /// an allocator to a default: `name` is the type whose allocator the
    /// signature does not state, written at `at` in `owner`. `through` is
    /// where an alias or a default the signature reaches left it, where it
    /// did.
    fn reportLibraryDefault(self: *Checker, owner: node.DeclId, at: TokenId, name: []const u8, through: ?Carried) std.mem.Allocator.Error!void {
        // A type a trait implementation settles cannot take an allocator
        // parameter, which nothing in the implementation's key would recover,
        // so only the explicit spelling is offered there.
        const label = if (self.ast.declTag(owner) == .associated_type)
            "Specify `mem.SystemAllocator` to make this restriction intentional."
        else
            "Specify `mem.SystemAllocator` to make this restriction intentional, or make the allocator a generic parameter to preserve allocator polymorphism.";
        try self.reportLibraryDefaultAt(self.ast.fileOf(at), self.ast.tokenSpan(at), name, label, through);
    }

    fn reportLibraryDefaultAt(self: *Checker, file: FileId, span: Span, name: []const u8, label: []const u8, through: ?Carried) std.mem.Allocator.Error!void {
        const labels = try self.sink.arena.alloc(Label, if (through == null) 1 else 2);
        labels[0] = .{ .file = file, .span = span, .message = label };
        if (through) |carried| labels[1] = .{
            .file = self.ast.fileOf(carried.inside),
            .span = self.ast.tokenSpan(carried.inside),
            .message = carried.why,
            .style = .secondary,
        };
        try self.sink.add(.{
            .severity = .err,
            .code = .t_defaulted_allocator,
            .message = try std.fmt.allocPrint(self.sink.arena, "Public library signature uses the default allocator for `{s}`.", .{name}),
            .labels = labels,
        });
    }

    /// Whether `tok`, a type written in declaration `owner`, is part of a
    /// signature a library publishes to the roots that depend on it: a public
    /// function's or a public trait's signature up to its body, an inherent
    /// implementation's head or its public members' signatures where the type
    /// is public, a type a public type settles for a trait, a public
    /// structure's fields or enumeration's payloads, or a public alias,
    /// newtype or constant. A trait implementation's members are its trait's
    /// signatures, checked where the trait is declared.
    ///
    /// **Bound:** constant work per written type, after one pass over the
    /// declarations that finds the implementations with a public member.
    fn publicLibrarySignature(self: *Checker, owner: node.DeclId, tok: TokenId) std.mem.Allocator.Error!bool {
        if (owner == node.DeclId.none) return false;
        if (!self.program.inLibraryRoot(self.program.moduleOf(owner))) return false;
        switch (self.ast.declTag(owner)) {
            .function => {
                if (self.ast.declIsExtern(owner)) return false;
                const body = self.ast.declBody(owner);
                if (body != ExprId.none and self.ast.tokenSpan(tok).start >= self.ast.exprSpan(body).start) return false;
                if (self.traitDeclaring(owner)) |trait| return publishes(self.ast.declVisibility(trait));
                if (self.implEnclosing(owner)) |implementation| {
                    if (self.ast.declTrait(implementation) != TokenId.none) return false;
                    return publishes(self.ast.declVisibility(owner)) and self.implementedTypeIsPublic(implementation);
                }
                return publishes(self.ast.declVisibility(owner));
            },
            .impl_ => {
                if (self.ast.declTrait(owner) != TokenId.none) return false;
                if (!self.implementedTypeIsPublic(owner)) return false;
                try self.collectImplsPublishing();
                return self.impls_publishing.contains(owner);
            },
            .associated_type => {
                const implementation = self.implEnclosing(owner) orelse return false;
                return self.implementedTypeIsPublic(implementation);
            },
            .struct_, .enum_, .alias, .newtype, .constant => return self.ast.declVisibility(owner) == .pub_,
            else => return false,
        }
    }

    fn publishes(visibility: node.Visibility) bool {
        return visibility == .pub_ or visibility == .opaque_;
    }

    /// Whether the type an implementation's head names is reachable from
    /// another root. A head naming no declared type is the library's own
    /// primitive, which every root reaches.
    fn implementedTypeIsPublic(self: *const Checker, implementation: node.DeclId) bool {
        const head = self.ast.declHead(implementation);
        const declared = self.declOfType(self.program.moduleOf(implementation), implementation, head.name) orelse return true;
        return publishes(self.ast.declVisibility(declared));
    }

    fn collectImplsPublishing(self: *Checker) std.mem.Allocator.Error!void {
        if (self.impls_publishing_ready) return;
        self.impls_publishing_ready = true;
        for (0..self.ast.declCount()) |i| {
            const member = node.DeclId.at(@intCast(i));
            if (!publishes(self.ast.declVisibility(member))) continue;
            const implementation = self.implEnclosing(member) orelse continue;
            try self.impls_publishing.put(self.gpa, implementation, {});
        }
    }

    /// [T-DefaultedAllocator] for a public library function whose type
    /// parameter bounded by `Allocator` writes a default: a caller that omits
    /// the argument takes the system allocator without writing it.
    fn checkLibraryFunctionDefaults(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!void {
        const allocator = self.allocator_decl orelse return;
        for (self.ast.declTypeParams(d)) |parameter| {
            if (!parameter.default.wasWritten()) continue;
            if (!self.isAllocatorParameter(d, parameter, allocator)) continue;
            if (!try self.publicLibrarySignature(d, parameter.name)) return;
            if (self.refusedBefore(parameter.default.at)) continue;
            try self.noteRefused(parameter.default.at);
            const name = self.ast.tokenText(self.ast.declName(d));
            // The pair's two names come from the function's own, whichever of
            // the two it is.
            const base = if (std.mem.endsWith(u8, name, "_in")) name[0 .. name.len - 3] else name;
            const params = self.ast.declParams(d);
            const where = if (params.len > 0 and std.mem.eql(u8, self.ast.tokenText(params[0].name), "self")) "first after the receiver" else "first";
            const label = try std.fmt.allocPrint(self.sink.arena, "drop the default; offer `{s}` over `mem.SystemAllocator` beside `{s}_in`, which takes the allocator {s}", .{ base, base, where });
            try self.reportLibraryDefaultAt(self.ast.fileOf(parameter.default.at), self.ast.writtenSpan(parameter.default), name, label, null);
        }
    }

    /// Whether a type parameter of `owner` is bounded by `Allocator`, where it
    /// is declared or in `owner`'s `where` clause.
    fn isAllocatorParameter(self: *const Checker, owner: node.DeclId, parameter: node.TypeParam, allocator: node.DeclId) bool {
        if (self.isBoundedBy(parameter, allocator)) return true;
        for (self.ast.declWherePredicates(owner)) |predicate| {
            const subject = predicate.subject;
            if (subject.kind != .named or subject.args.len() != 0 or subject.name == TokenId.none) continue;
            if (self.ast.tokenName(subject.name) != self.ast.tokenName(parameter.name)) continue;
            if (self.boundsReach(self.ast.boundsIn(predicate.bounds), allocator, 0)) return true;
        }
        return false;
    }

    /// The type a declaration's parameter defaults to, read where the
    /// declaration is. A default that reaches itself again while it is read,
    /// through a type it omits an argument of, is [T-ArgumentDefault] and
    /// poison.
    fn defaultAt(self: *Checker, decl: node.DeclId, index: usize) std.mem.Allocator.Error!TypeId {
        const parameter = self.ast.declTypeParams(decl)[index];
        const key = (@as(u64, decl.index()) << 32) | index;
        if (self.defaults_reading.contains(key)) {
            if (self.refusedBefore(parameter.default.at)) return .poison;
            try self.noteRefused(parameter.default.at);
            try self.sink.addErrorFmt(
                .t_argument_default,
                self.ast.fileOf(parameter.default.at),
                self.ast.writtenSpan(parameter.default),
                "write the arguments this type takes, so its default does not need itself",
                "the default of `{s}` reaches itself",
                .{self.ast.tokenText(parameter.name)},
            );
            return .poison;
        }
        try self.defaults_reading.put(self.gpa, key, {});
        defer _ = self.defaults_reading.remove(key);
        const outer = self.reading_default;
        self.reading_default = carriedKey(decl, index);
        defer self.reading_default = outer;
        return self.typeOfRefOf(self.program.moduleOf(decl), decl, parameter.default);
    }

    /// The receiver of a call, as the value written for it, when argument `j`
    /// is another argument of a call on a value that came from a call taking a
    /// default, and the parameter's declared type uses what the default
    /// filled; otherwise none.
    fn receiverArgument(self: *Checker, d: node.DeclId, args: []const ExprId, params: []const node.Param, j: usize, declared: TypeId) std.mem.Allocator.Error!ExprId {
        if (self.defaulted_calls.count() == 0) return .none;
        if (j == 0 or args[0] == ExprId.none) return .none;
        const written = self.ast.withoutTypeGroups(params[0].written);
        if (written.kind != .named or !resolve_mod.namesSelf(self.ast, written.name)) return .none;
        const receiver = if (self.ast.exprTag(args[0]) == .marked) self.ast.unaryOperand(args[0]) else args[0];
        const call = self.defaultingCallOf(receiver) orelse return .none;
        const fill = self.defaulted_calls.get(call).?;
        if (!self.mentionsFilledPosition(d, declared, fill)) return .none;
        return receiver;
    }

    /// A type parameter a call left to its type's default.
    const DefaultedFill = struct {
        parameter: TokenId,
        filled: TypeId,
        /// The type declaration, and the position in its parameters, that
        /// the default filled.
        decl: node.DeclId,
        position: u32,
        /// Whether `decl` is the called function itself, whose type
        /// parameter the call left to its default, rather than a type.
        of_function: bool = false,
    };

    /// Whether `ty` is `needle` or holds it as a part. Each distinct type is
    /// visited once, so the walk is linear in the distinct types `ty` holds.
    fn holdsType(self: *Checker, ty: TypeId, needle: TypeId) std.mem.Allocator.Error!bool {
        const Find = struct {
            checker: *Checker,
            needle: TypeId,
            seen: std.AutoHashMapUnmanaged(TypeId, void) = .empty,
            found: bool = false,

            fn visit(find: *@This(), inside: TypeId) std.mem.Allocator.Error!void {
                if (find.found) return;
                if (inside == find.needle) {
                    find.found = true;
                    return;
                }
                if ((try find.seen.getOrPut(find.checker.gpa, inside)).found_existing) return;
                try find.checker.builder.visitParts(inside, find);
            }

            pub fn part(find: *@This(), inside: TypeId) std.mem.Allocator.Error!void {
                try find.visit(inside);
            }
        };
        var find: Find = .{ .checker = self, .needle = needle };
        defer find.seen.deinit(self.gpa);
        try find.visit(ty);
        return find.found;
    }

    /// Whether the declared type of a parameter of `member` mentions the
    /// parameter of `member`'s implementation that stands for the position
    /// of the type parameter `fill` defaulted.
    fn mentionsFilledPosition(self: *Checker, member: node.DeclId, declared: TypeId, fill: DefaultedFill) bool {
        const id = self.builder.view().implementationIdOf(member) orelse return false;
        const implementation = self.implementations[id.index()];
        const instance = self.builder.instanceOf(implementation.ty) orelse return false;
        if (instance.decl != fill.decl) return false;
        return switch (self.builder.get(self.builder.argsOf(instance)[fill.position])) {
            .parameter => |written| self.mentionsParameterAt(declared, implementation.decl, .stops, written.index),
            else => false,
        };
    }

    /// The call that left a parameter to its default and made the value `e`:
    /// `e` is that call, or a use of a binding written without a type that
    /// the call initialised.
    fn defaultingCallOf(self: *const Checker, e: ExprId) ?ExprId {
        if (self.defaulted_calls.count() == 0) return null;
        const bare = self.ast.withoutGroups(e);
        if (self.defaulted_calls.contains(bare)) return bare;
        const used = self.res.targetOf(bare);
        if (used == BindingId.none) return null;
        return self.defaulted_bindings.get(used);
    }

    /// The note a mismatch carries when the value it is about came from a call
    /// that took a default: the value found is such a value and its type holds
    /// the default, or it is an argument of a call on such a value and the
    /// parameter's type holds the default.
    fn defaultedFillNote(self: *Checker, id: ExprId, actual: TypeId, want: Expected) std.mem.Allocator.Error!?[]const u8 {
        const from_found = self.defaultingCallOf(id);
        const from_receiver = if (want.receiver != ExprId.none) self.defaultingCallOf(want.receiver) else null;
        const call = from_found orelse from_receiver orelse return null;
        const fill = self.defaulted_calls.get(call).?;
        const explained = if (from_found != null) blk: {
            // The default is the difference when both types are the same
            // declaration and differ where the default filled; for a
            // function's type parameter, when the value has the default's type
            // and the type wanted is another.
            if (fill.of_function) break :blk actual == fill.filled and want.ty != fill.filled;
            const found = self.builder.instanceOf(actual) orelse break :blk false;
            const wanted = self.builder.instanceOf(want.ty) orelse break :blk false;
            if (found.decl != fill.decl or wanted.decl != fill.decl) break :blk false;
            break :blk self.builder.argsOf(found)[fill.position] == fill.filled and
                self.builder.argsOf(wanted)[fill.position] != fill.filled;
        } else try self.holdsType(want.ty, fill.filled);
        if (!explained) return null;
        return try std.fmt.allocPrint(
            self.sink.arena,
            "`{s}` left `{s}` to its default `{s}`; write the type of the binding to choose another",
            .{ self.ast.exprText(call), self.ast.tokenText(fill.parameter), try self.typeName(fill.filled) },
        );
    }

    /// The default a call takes for type parameter `index` of `decl`, which the
    /// call leaves to it. A default allocator taken inside a declaration
    /// generic over an allocator is [T-DefaultedAllocator] at the call's whole
    /// callee, so the allocator is passed or written; the call is recorded as
    /// having taken a default, so a mismatch it causes names it.
    fn takeDefault(self: *Checker, call: ExprId, decl: node.DeclId, index: usize) std.mem.Allocator.Error!TypeId {
        const parameters = self.ast.declTypeParams(decl);
        if (self.allocator_decl) |allocator| {
            if (self.isBoundedBy(parameters[index], allocator)) {
                // A type's default is blamed on the type the call names, a
                // function's on the whole path that names the function.
                const callee: ExprId = if (self.ast.declTag(decl) == .function) self.ast.withoutGroups(self.ast.call(call).callee) else .none;
                _ = try self.refusedDefaultedAllocator(self.generic, self.ast.exprMain(call), callee, decl, index);
            }
        }
        const filled = try self.defaultAt(decl, index);
        if (filled != .poison) try self.recordDefaultTaken(call, decl, index, filled);
        return filled;
    }

    fn recordDefaultTaken(self: *Checker, call: ExprId, decl: node.DeclId, index: usize, filled: TypeId) std.mem.Allocator.Error!void {
        try self.defaulted_calls.put(self.gpa, call, .{
            .parameter = self.ast.declTypeParams(decl)[index].name,
            .filled = filled,
            .decl = decl,
            .position = @intCast(index),
            .of_function = self.ast.declTag(decl) == .function,
        });
    }

    /// The default of the type parameter that parameter `index` of the
    /// implementation enclosing `member` stands alone for in the
    /// implementation's head, or null where the head writes it elsewhere or
    /// the type gives that parameter no default. A default allocator taken
    /// inside a declaration generic over an allocator is [T-DefaultedAllocator]
    /// at `call`.
    fn headDefaultOf(self: *Checker, call: ExprId, member: node.DeclId, index: u32) std.mem.Allocator.Error!?TypeId {
        const id = self.builder.view().implementationIdOf(member) orelse return null;
        const implementation = self.implementations[id.index()];
        const instance = self.builder.instanceOf(implementation.ty) orelse return null;
        const parameters = self.ast.declTypeParams(instance.decl);
        for (self.builder.argsOf(instance), 0..) |argument, i| {
            switch (self.builder.get(argument)) {
                .parameter => |written| {
                    if (written.owner != implementation.decl.index() or written.index != index) continue;
                    if (!parameters[i].default.wasWritten()) return null;
                    const filled = try self.takeDefault(call, instance.decl, i);
                    if (filled == .poison) return null;
                    return filled;
                },
                else => {},
            }
        }
        return null;
    }

    /// Whether a parameter is bounded by the library's `Allocator`, written on
    /// the parameter.
    fn isBoundedBy(self: *const Checker, parameter: node.TypeParam, allocator: node.DeclId) bool {
        return self.boundsReach(self.ast.boundsOf(parameter), allocator, 0);
    }

    /// Whether a run of bounds names `Allocator` or a trait that requires it.
    ///
    /// **Bound:** the supertrait chain of each bound, cut at a fixed depth
    /// because a trait cannot require itself.
    fn boundsReach(self: *const Checker, bounds: []const node.TraitBound, allocator: node.DeclId, depth: u32) bool {
        for (bounds) |bound| {
            if (bound.kind != .named) continue;
            const trait = traitAt(self.ast, self.res, bound.named.name) orelse continue;
            if (trait == allocator) return true;
            if (depth < 8 and self.boundsReach(self.ast.declBounds(trait), allocator, depth + 1)) return true;
        }
        return false;
    }

    /// The name of the first parameter bounded by `Allocator` that `owner`
    /// declares, on itself or on the implementation or trait it is a member
    /// of: bounded where it is declared or in a trailing `where` clause.
    fn allocatorParameterOf(self: *const Checker, owner: node.DeclId, allocator: node.DeclId) ?TokenId {
        const scopes = [_]node.DeclId{
            owner,
            self.implEnclosing(owner) orelse node.DeclId.none,
            self.traitDeclaring(owner) orelse node.DeclId.none,
        };
        for (scopes) |scope| {
            if (scope == node.DeclId.none) continue;
            for (self.ast.declTypeParams(scope)) |parameter| {
                if (self.isAllocatorParameter(scope, parameter, allocator)) return parameter.name;
            }
        }
        return null;
    }

    /// The alias a bare type name reaches from `owner` in `m`, or null where
    /// it reaches anything else, read from what the resolver bound there.
    fn aliasWritten(self: *const Checker, owner: node.DeclId, tok: TokenId) ?node.DeclId {
        return self.res.aliasReachedBy(self.writtenAs(owner, tok));
    }

    /// The type an alias names: what it wrote after `=`, read in the module
    /// that wrote it with its own parameters in scope.
    ///
    /// The one place an alias becomes a type. Every name reaching an alias,
    /// bare or through its module, is answered here, so nothing below the
    /// checker ever meets one -- a written alias and the type it names are
    /// one handle in the pool.
    ///
    /// Kept apart before callable effects are settled and after; see
    /// `alias_types`. An alias reached again while its own type is read is a
    /// cycle, answered with poison: the resolver reported it.
    fn aliasedType(self: *Checker, alias: node.DeclId) std.mem.Allocator.Error!TypeId {
        if (self.settledAlias(alias)) |held| return held;
        const kept = if (self.callable_effects_ready) &self.alias_types else &self.alias_shapes;
        if (kept.get(alias)) |held| return held;
        if (self.aliases_reading.contains(alias)) {
            // The resolver reports an alias that names itself. One reached
            // again through the default of a type it names is not visible to
            // it, so the cycle is reported where the default is read.
            if (self.defaults_reading.count() != 0) {
                const name = self.ast.declName(alias);
                if (!self.refusedBefore(name)) {
                    try self.noteRefused(name);
                    try self.sink.addErrorFmt(
                        .t_argument_default,
                        self.ast.fileOf(name),
                        self.ast.tokenSpan(name),
                        "write the arguments the type takes, so its default does not name this alias",
                        "`{s}` reaches itself through the default of a type it names",
                        .{self.ast.tokenText(name)},
                    );
                }
            }
            return .poison;
        }
        try self.aliases_reading.put(self.gpa, alias, {});
        defer _ = self.aliases_reading.remove(alias);

        const outer = self.generic;
        defer self.generic = outer;
        self.generic = alias;
        // Refused for growing or holding itself, like any part: reading it
        // would not terminate.
        const written = self.ast.declReturnRef(alias);
        // Kept like any answer, so a refused alias is scanned for once.
        for (self.refused_parts.items) |seen| {
            if (seen != written.at) continue;
            try kept.put(self.gpa, alias, .poison);
            return .poison;
        }
        const named = try self.typeOfRefOf(self.program.moduleOf(alias), alias, written);
        try kept.put(self.gpa, alias, named);
        return named;
    }

    /// The type an alias names, where it is already settled: every alias is
    /// read once callable effects are, which is before any body is checked.
    fn settledAlias(self: *const Checker, alias: node.DeclId) ?TypeId {
        if (self.alias_types.get(alias)) |held| return held;
        if (self.isRetained(alias)) return self.retained.?.typing.aliased.get(alias);
        return null;
    }

    /// The alias a bound names, where its name reaches one rather than a
    /// trait: `F: Step` bounds `F` by the function type `Step` names.
    fn boundAlias(self: *const Checker, bound: node.TraitBound) ?node.DeclId {
        if (bound.kind != .named) return null;
        return self.res.aliasReachedBy(bound.named.name);
    }

    /// Whether a bound names a function type, written out or through an alias.
    fn isCallableBound(self: *const Checker, bound: node.TraitBound) bool {
        return bound.kind == .callable or self.boundAlias(bound) != null;
    }

    /// The function type a callable bound names, read in `module` with
    /// `owner`'s parameters in scope. An alias there is applied to what the
    /// bound gives it; one naming anything but a function type is refused,
    /// since a bound names a trait or a function type.
    fn boundSignature(self: *Checker, module: ModuleId, owner: node.DeclId, bound: node.TraitBound) std.mem.Allocator.Error!TypeId {
        const alias = self.boundAlias(bound) orelse
            return self.callableBoundTypeOf(module, owner, self.ast.callableRef(bound.callable));
        const at = bound.named.name;
        const applied = try self.appliedAlias(module, owner, at, alias, bound.named.args);
        if (applied == .poison) return .poison;
        const written = self.aliasedFunctionRef(alias) orelse {
            if (self.refusedBefore(at)) return .poison;
            try self.noteRefused(at);
            try self.sink.addErrorFmt(
                .n_type_alias,
                self.ast.fileOf(at),
                self.ast.tokenSpan(at),
                "bound it by a trait, or by an alias of a function type",
                "`{s}` is an alias of `{s}`, and a bound names a trait or a function type",
                .{ self.ast.tokenText(at), try self.typeName(applied) },
            );
            return .poison;
        };
        return self.carriedUnlessDeclined(applied, written);
    }

    /// The function type an alias writes, followed through the aliases it
    /// names, or null where it names another kind of type.
    fn aliasedFunctionRef(self: *const Checker, alias: node.DeclId) ?node.TypeRef {
        const written = writtenThroughAliases(self.ast, self.res, self.ast.declReturnRef(alias));
        return if (written.kind == .callable) written else null;
    }

    /// The type a name heading a path stands for when it is an alias: the
    /// type the alias names, with a generic alias's own parameters left open
    /// for the call to settle. Null for any name that is not an alias.
    fn aliasPathType(self: *const Checker, b: BindingId) ?TypeId {
        if (b == BindingId.none or self.res.kindOf(b) != .type_alias) return null;
        return self.settledAlias(self.res.declaredBy(b)) orelse .poison;
    }

    /// A generic alias heading a path, and what the path settles of it.
    const AliasHeading = struct {
        alias: node.DeclId,
        /// What the alias's target applies at each argument position, in the
        /// alias's own parameters.
        written: []const TypeId,
        /// The alias's parameters as the path settled them; `.poison` is open.
        found: []TypeId,
    };

    /// The alias heading a call's path and the type it stands for, where the
    /// callee is `Alias.op` -- which settles the implementation's head the way
    /// the type written out at that path would.
    fn calledThroughAlias(self: *const Checker, call: ExprId) ?struct { alias: node.DeclId, held: TypeId } {
        const callee = self.ast.withoutGroups(self.ast.call(call).callee);
        if (callee == ExprId.none or self.ast.exprTag(callee) != .field) return null;
        const b = self.res.targetOf(self.ast.unaryOperand(callee));
        const held = self.aliasPathType(b) orelse return null;
        return .{ .alias = self.res.declaredBy(b), .held = held };
    }

    /// The generic alias a name heading a path reaches, or null for any other.
    fn genericAliasHead(self: *const Checker, b: BindingId) ?node.DeclId {
        if (b == BindingId.none or self.res.kindOf(b) != .type_alias) return null;
        const alias = self.res.declaredBy(b);
        return if (self.ast.declTypeParams(alias).len != 0) alias else null;
    }

    /// The type a variant written through the qualifier `q` stands for where
    /// the qualifier is an alias, or null where it is not. A generic alias is
    /// settled by the type expected where the variant is written, as the
    /// declaration's own parameters are, and refused where that type is not
    /// one the alias writes.
    fn aliasVariantType(self: *Checker, id: ExprId, q: ExprId, expected: ?Expected) std.mem.Allocator.Error!?TypeId {
        if (q == ExprId.none) return null;
        const b = self.res.targetOf(q);
        const aliased = self.aliasPathType(b) orelse return null;
        const alias = self.genericAliasHead(b) orelse return aliased;
        if (aliased == .poison) return .poison;
        const d = self.declaringType(aliased) orelse return .poison;
        const instance = self.instanceFor(d, expected) orelse return null;
        const heading: AliasHeading = .{
            .alias = alias,
            .written = &.{aliased},
            .found = try self.openAliasArguments(alias),
        };
        if (!try self.settleAliasHeading(id, self.ast.exprMain(q), heading, &.{instance})) return .poison;
        return instance;
    }

    fn openAliasArguments(self: *Checker, alias: node.DeclId) std.mem.Allocator.Error![]TypeId {
        const found = try self.sink.arena.alloc(TypeId, self.ast.declTypeParams(alias).len);
        @memset(found, .poison);
        return found;
    }

    /// The alias's parameters as a settling list, for the questions asked of a
    /// type about them.
    fn aliasSettling(self: *const Checker, heading: AliasHeading) [1]Settling {
        return .{.{ .owner = heading.alias, .generics = self.ast.declTypeParams(heading.alias), .found = heading.found }};
    }

    /// Whether the alias writes a parameter of its own at this position of its
    /// target. A position that writes none is fixed by the alias alone.
    fn writesParameter(self: *const Checker, heading: AliasHeading, position: TypeId) bool {
        return self.mentionsSettling(position, &self.aliasSettling(heading));
    }

    /// The alias parameter a position of its target is exactly, so a report
    /// about an unsettled position names the parameter the program wrote.
    fn aliasParameterAt(self: *const Checker, heading: AliasHeading, position: usize) ?TokenId {
        if (position >= heading.written.len) return null;
        const written = switch (self.builder.get(heading.written[position])) {
            .parameter => |p| p,
            else => return null,
        };
        if (written.owner != heading.alias.index()) return null;
        return self.ast.declTypeParams(heading.alias)[written.index].name;
    }

    /// Settles each position the alias fixes in the call's own list, which has
    /// one slot per argument position of the alias's target.
    fn seedAliasHeading(self: *const Checker, heading: AliasHeading, slots: []TypeId) void {
        if (slots.len != heading.written.len) return;
        for (heading.written, slots) |position, *slot| {
            if (!self.writesParameter(heading, position)) slot.* = position;
        }
    }

    /// Settles a generic alias's parameters from the positions its path has
    /// settled, then settles the positions the alias determines from them: an
    /// alias writing `Map[String[A], UInt64, A]` has its key settled by the
    /// allocator the call was given.
    fn closeAliasHeading(self: *Checker, heading: AliasHeading, found: []TypeId) std.mem.Allocator.Error!void {
        const open = self.aliasSettling(heading);
        for (heading.written, found) |pattern, got| {
            if (got == .poison or !self.writesParameter(heading, pattern)) continue;
            var clash: ?Clash = null;
            _ = try self.settle(pattern, got, heading.alias, heading.found, &clash);
        }
        for (heading.written, found) |pattern, *slot| {
            if (slot.* != .poison or !self.writesParameter(heading, pattern) or self.hasOpenParameter(pattern, &open)) continue;
            slot.* = try self.builder.substitute(pattern, @intCast(heading.alias.index()), heading.found);
        }
    }

    /// Settles a generic alias's parameters from what its path produced at
    /// each argument position of the alias's target, refuses a position the
    /// alias writes differently, and holds the settled arguments to the
    /// alias's bounds. False where the path was refused.
    ///
    /// A position the alias writes without its parameters was settled before
    /// the call was read; the others are matched here, so a parameter that
    /// appears twice, or inside another type, is one type at every position.
    fn settleAliasHeading(self: *Checker, at: ExprId, head: TokenId, heading: AliasHeading, got: []const TypeId) std.mem.Allocator.Error!bool {
        const generics = self.ast.declTypeParams(heading.alias);
        // The call's arguments are final here, with integers defaulted, so the
        // alias's parameters are read afresh from them.
        @memset(heading.found, .poison);
        for (heading.written, got) |pattern, actual| {
            if (!self.writesParameter(heading, pattern)) continue;
            var clash: ?Clash = null;
            if (try self.settle(pattern, actual, heading.alias, heading.found, &clash)) continue;
            const was = clash.?;
            const got_name = try self.typeName(was.got);
            _ = self.report(
                .t_mismatch,
                at,
                "`{s}` was already settled as `{s}` here, and this is {s} `{s}`",
                .{ self.ast.tokenText(generics[was.index].name), try self.typeName(was.was), article.before(got_name), got_name },
                "one type parameter, two types",
            );
            return false;
        }
        for (heading.written, got) |pattern, actual| {
            if (!self.writesParameter(heading, pattern)) continue;
            const read = if (std.mem.indexOfScalar(TypeId, heading.found, .poison) != null)
                TypeId.poison
            else
                try self.builder.substitute(pattern, @intCast(heading.alias.index()), heading.found);
            if (read == actual) continue;
            const wrote = try self.typeName(pattern);
            const got_name = try self.typeName(actual);
            _ = self.report(
                .t_mismatch,
                at,
                "`{s}` writes `{s}` here, and this is {s} `{s}`",
                .{ self.ast.tokenText(self.ast.declName(heading.alias)), wrote, article.before(got_name), got_name },
                "the alias fixes this type",
            );
            return false;
        }
        if (self.callable_effects_ready) {
            const args_start: u32 = @intCast(self.alias_site_args.items.len);
            try self.alias_site_args.appendSlice(self.gpa, heading.found);
            try self.bound_sites.append(self.gpa, .{
                .ty = .poison,
                .at = head,
                .within = self.generic,
                .alias = heading.alias,
                .args_start = args_start,
                .args_len = @intCast(heading.found.len),
            });
        }
        return true;
    }

    /// An alias applied to the arguments written after it.
    ///
    /// An alias with parameters names a type holding them, and applying it
    /// substitutes the arguments for them. The count is the alias's own, and
    /// a wrong one is refused as it is for any other type, so `Meters[UInt8]`
    /// and a bare generic alias read the same as a struct would.
    fn appliedAlias(
        self: *Checker,
        m: ModuleId,
        owner: node.DeclId,
        tok: TokenId,
        alias: node.DeclId,
        args: node.TypeRefRange,
    ) std.mem.Allocator.Error!TypeId {
        const wanted = self.ast.declTypeParams(alias).len;
        const required = self.ast.declRequiredTypeParams(alias);
        const written = args.len();
        if (written > wanted or written < required) {
            if (self.refusedBefore(tok)) return .poison;
            try self.noteRefused(tok);
            try self.refuseTypeArity(self.ast.tokenSpan(tok), tok, required, wanted, written, null);
            return .poison;
        }
        if (written < wanted and try self.refusedDefaultedAllocator(owner, tok, .none, alias, written)) return .poison;

        const named = try self.aliasedType(alias);
        try self.checkCarriedOmission(owner, tok, alias, alias_body);
        if (wanted == 0 or named == .poison) return named;

        // Read into a run of this application's own before any is kept: an
        // argument may itself apply an alias, which keeps its arguments first.
        const supplied = try self.gpa.alloc(TypeId, wanted);
        defer self.gpa.free(supplied);
        for (self.ast.typeArgs(args), supplied[0..written]) |a, *t| t.* = try self.typeOfRefOf(m, owner, a);
        try self.fillDefaults(alias, supplied, written);
        for (written..wanted) |i| try self.checkCarriedOmission(owner, tok, alias, i);
        for (supplied) |t| if (t == .poison) return .poison;
        if (self.callable_effects_ready) {
            const args_start: u32 = @intCast(self.alias_site_args.items.len);
            try self.alias_site_args.appendSlice(self.gpa, supplied);
            try self.bound_sites.append(self.gpa, .{
                .ty = .poison,
                .at = tok,
                .within = owner,
                .alias = alias,
                .args_start = args_start,
                .args_len = @intCast(wanted),
            });
        }
        return self.builder.substitute(named, @intCast(alias.index()), supplied);
    }

    /// Refuses a written type given a number of type arguments its head does
    /// not take.
    ///
    /// One sentence for both heads a type is written with. A name the module
    /// declares says how many it takes with a parameter list; a type a trait
    /// declares is written without one and so takes none. Both ask whether
    /// what was supplied is what the head admits, and a second wording of that
    /// answer would be the same rule reported two ways.
    ///
    /// `named` is what the message calls the head, and `span` is what a reader
    /// is pointed at -- the two part company for a settled reference, whose
    /// head is one name of a run the whole of which is what was written wrong.
    fn refuseTypeArity(
        self: *Checker,
        span: Span,
        named: TokenId,
        required: usize,
        wanted: usize,
        written: usize,
        label_override: ?[]const u8,
    ) std.mem.Allocator.Error!void {
        const label = label_override orelse if (wanted == 0) "this type takes no arguments" else "give it the arguments it declares";
        if (required == wanted) {
            try self.sink.addErrorFmt(
                .t_bound,
                self.ast.fileOf(named),
                span,
                label,
                "`{s}` takes {d} type argument(s), and was given {d}",
                .{ self.ast.tokenText(named), wanted, written },
            );
        } else {
            try self.sink.addErrorFmt(
                .t_bound,
                self.ast.fileOf(named),
                span,
                label,
                "`{s}` takes {d} to {d} type argument(s), and was given {d}",
                .{ self.ast.tokenText(named), required, wanted, written },
            );
        }
    }

    /// Refuses a call given a number of type arguments its function does not
    /// declare: the rule a written type answers to, in the same sentence.
    ///
    /// The help says which rule the count broke: a call names every one of
    /// its function's own type parameters or none, the parameters of a
    /// generic implementation's head are settled by the receiver or the path,
    /// and a trait operation's `Self` by the arguments or the expected type.
    fn refuseCallArity(
        self: *Checker,
        bracket: ExprId,
        d: node.DeclId,
        written: usize,
    ) std.mem.Allocator.Error!void {
        const span: Span = .{
            .start = self.ast.tokenSpan(self.ast.exprMain(bracket)).start,
            .end = self.ast.exprSpan(bracket).end,
        };
        const generics = self.ast.declTypeParams(d);
        const arena = self.sink.arena;
        var names: std.ArrayList(u8) = .empty;
        for (generics, 0..) |generic, i| {
            if (i > 0) try names.appendSlice(arena, ", ");
            try names.print(arena, "`{s}`", .{self.ast.tokenText(generic.name)});
        }
        const help: []const u8 = help: {
            if (written < generics.len)
                break :help try std.fmt.allocPrint(arena, "name all {d} of {s}, or none to let the call settle them", .{ generics.len, names.items });
            const head = self.headParametersOf(d);
            if (head != node.DeclId.none) {
                const params = self.ast.declTypeParams(head);
                break :help try std.fmt.allocPrint(arena, "`{s}` belongs to the implementation of `{s}`, and the receiver or the path settles it", .{
                    self.ast.tokenText(params[0].name),
                    self.ast.implHeadText(head),
                });
            }
            if (self.res.selectsThroughTrait(self.ast.binary(bracket).lhs)) {
                const operation = self.ast.tokenText(self.ast.declName(d));
                if (generics.len == 0)
                    break :help try std.fmt.allocPrint(arena, "`Self` is the type written before `.{s}`, and `{s}` declares no type parameters of its own", .{ operation, operation });
                break :help try std.fmt.allocPrint(arena, "`Self` is the type written before `.{s}`, and the brackets name only {s}", .{ operation, names.items });
            }
            if (self.ast.declIsSignature(d) or self.traitDeclaring(d) != null)
                break :help "`Self` is settled by the arguments or by the type the call is expected to have, such as an annotation";
            if (generics.len == 0) break :help "this function declares no type parameters, so its call names none";
            break :help try std.fmt.allocPrint(arena, "it declares only {s}", .{names.items});
        };
        try self.sink.addErrorFmt(
            .t_bound,
            self.ast.fileOfExpr(bracket),
            span,
            help,
            "`{s}` takes {d} type argument(s), and was given {d}",
            .{ self.ast.tokenText(self.ast.declName(d)), generics.len, written },
        );
    }

    /// Refuses every written type whose arguments its parameters' bounds do
    /// not admit, once every capability is settled.
    ///
    /// Each site is checked back inside the declaration it was written in.
    /// This runs after every body, so the enclosing declaration is no longer
    /// the one being walked -- and without it a parameter cannot discharge a
    /// bound it carries, which would make a bounded generic type writable and
    /// unusable from any generic function.
    fn reportBrokenBounds(self: *Checker) std.mem.Allocator.Error!void {
        const outer = self.generic;
        const outer_module = self.current;
        defer {
            self.generic = outer;
            self.current = outer_module;
        }

        for (self.bound_sites.items) |site| {
            self.generic = site.within;
            // Read in the module the type was written in, so the report
            // writes types as that module does.
            self.current = self.res.moduleOfFile(self.ast.fileOf(site.at));
            if (site.alias != node.DeclId.none) {
                try self.checkArgumentBounds(
                    site.alias,
                    self.alias_site_args.items[site.args_start..][0..site.args_len],
                    null,
                    site.at,
                );
                continue;
            }
            const inst = self.builder.instanceOf(site.ty) orelse continue;
            try self.checkArgumentBounds(
                inst.decl,
                self.builder.argsOf(inst),
                null,
                site.at,
            );
        }
        try self.reportBrokenTraitBounds();
    }

    /// Refuses every trait a bound names at arguments its own parameters'
    /// bounds do not admit: `C: Conv[U]` where `trait Conv[T: Owned]` needs
    /// `U` to be `Owned`, as a written `Pool[U]` does. Asked of every place a
    /// bound is written: a parameter's or `where` clause's bounds, a trait's
    /// supertrait list and an associated type's bounds. Checked inside the
    /// declaration whose bound it is, so its parameters discharge what they
    /// promise, and with a trait signature's `Self` read as that signature
    /// reads it.
    ///
    /// **Bound:** each written bound is read once, and its arguments are
    /// checked through the one routine a written type's are.
    fn reportBrokenTraitBounds(self: *Checker) std.mem.Allocator.Error!void {
        const outer_self = self.self_at_call;
        defer self.self_at_call = outer_self;
        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            self.generic = d;
            self.current = self.program.moduleOf(d);
            self.self_at_call = if (self.ast.declIsSignature(d)) try self.signatureSelfType(d) else null;
            const range = self.constraints.rangeOfDeclaration(d);
            for (range.start..range.end) |at| {
                try self.reportBrokenBoundList(d, self.constraints.requirementsOf(self.constraints.records[at]));
            }
            try self.reportBrokenBoundList(d, self.ast.declBounds(d));
        }
    }

    fn reportBrokenBoundList(self: *Checker, d: node.DeclId, bounds: []const node.TraitBound) std.mem.Allocator.Error!void {
        for (bounds) |bound| {
            if (bound.kind != .named or bound.named.args.len() == 0) continue;
            const trait = traitAt(self.ast, self.res, bound.named.name) orelse continue;
            const args = try self.internedBoundArgs(.{ .module = self.current, .owner = d }, bound);
            defer if (args.len > 0) self.gpa.free(args);
            try self.checkArgumentBounds(trait, args, null, bound.named.name);
        }
    }

    /// Refuses a type argument its parameter's bounds do not admit.
    ///
    /// A bound constrains what may be supplied, and a body is checked once
    /// under what the bound promised -- so an argument that breaks it makes
    /// that one check wrong for this instantiation and every rule below it
    /// reads a capability the body was never checked against. A `[T: Copyable]`
    /// body may copy and may drop, so a Linear argument is duplicated and
    /// leaked with nothing to say so.
    ///
    /// Copyable permits duplication and discard; Discardable permits discard.
    /// An unrestricted parameter guarantees neither operation. The settled
    /// argument must meet the capability and trait evidence promised here.
    fn checkArgumentBounds(
        self: *Checker,
        d: node.DeclId,
        args: []const TypeId,
        enclosing: ?BoundSettlement,
        at: TokenId,
    ) std.mem.Allocator.Error!void {
        if (self.refusedBefore(at)) return;
        _ = try self.argumentBoundsUnmet(d, args, enclosing, at, &.{}, .report);
    }

    /// Whether `args` meet every bound `d` declares on its parameters, asked
    /// without reporting: the question `checkArgumentBounds` refuses a call
    /// by, for a report that suggests a call and must suggest one that is
    /// accepted.
    fn argumentsMeetBounds(self: *Checker, d: node.DeclId, args: []const TypeId) std.mem.Allocator.Error!bool {
        return !try self.argumentBoundsUnmet(d, args, null, self.ast.declName(d), &.{}, .ask);
    }

    /// Whether a bound is reported where it is unmet, or only answered.
    const BoundMode = enum { report, ask };

    /// Whether some bound `d` declares is not met by `args`, reporting the
    /// first such bound at `at` in `.report` mode.
    fn argumentBoundsUnmet(
        self: *Checker,
        d: node.DeclId,
        args: []const TypeId,
        enclosing: ?BoundSettlement,
        at: TokenId,
        /// The types a call wrote in its brackets for `d`'s parameters, in
        /// order, or empty. A bound on one of them is reported at the type.
        written: []const node.TypeRef,
        mode: BoundMode,
    ) std.mem.Allocator.Error!bool {

        // The parameter's own interned type, read for the arguments its bound
        // named a trait at: `traitsBounding` settled them once, when this
        // declaration's parameters were interned, and a type argument checked
        // against the bound is checked against that reading rather than a
        // second one of the tokens that wrote it.
        const own = if (@as(usize, @intCast(d.index())) < self.param_types.len)
            self.param_types[@intCast(d.index())]
        else
            &.{};

        const constraint_range = self.constraints.rangeOfDeclaration(d);
        for (constraint_range.start..constraint_range.end) |constraint_at| {
            const constraint = self.constraints.records[constraint_at];
            const held, const source: ?OwnBound = switch (constraint.subject) {
                .parameter => |i| value: {
                    if (i >= args.len) continue;
                    break :value .{
                        args[i],
                        if (i < own.len) .{
                            .source = .{ .parameter = own[i] },
                            .decl = d,
                            .settled = args,
                            .enclosing = enclosing,
                        } else null,
                    };
                },
                .written => value: {
                    // A subject projected from a type still holding the
                    // caller's parameters, `Filter[S.Iter, F].Iter`, is
                    // selected under the caller's `where` clauses, which are
                    // what prove its implementation applies.
                    var subject = try self.builder.substituteWithin(self.generic, self.constraint_subjects[constraint_at], d.index(), args);
                    if (enclosing) |outer| {
                        subject = try self.builder.substituteWithin(self.generic, subject, outer.decl.index(), outer.settled);
                    }
                    // A subject the call could not settle was reported where
                    // it failed to settle, and no bound on it can be judged.
                    // Skipping it is sound only because that report exists.
                    if (subject == .poison) {
                        std.debug.assert(self.sink.error_count > 0);
                        continue;
                    }
                    break :value .{
                        subject,
                        .{
                            .source = .{ .scope = .{ .module = self.program.moduleOf(d), .owner = d } },
                            .decl = d,
                            .settled = args,
                            .enclosing = enclosing,
                        },
                    };
                },
            };

            const site: TokenId, const span: Span = switch (constraint.subject) {
                .parameter => |i| if (i < written.len) .{ written[i].at, self.ast.writtenSpan(written[i]) } else .{ at, self.ast.tokenSpan(at) },
                .written => .{ at, self.ast.tokenSpan(at) },
            };

            // Every subject is discharged through this one reader. A projected
            // subject differs only in requiring substitution before it arrives.
            const reported = self.sink.items().len;
            // A written subject is named in full, so a projection says what it
            // projects from: `Self.Iter.Item`, not `Item`.
            const spelled = switch (constraint.subject) {
                .written => |written_subject| try spellWrittenOwned(self.sink.arena, self.ast, written_subject),
                .parameter => self.ast.tokenText(constraint.named),
            };
            if (try self.undischarged(
                spelled,
                self.constraints.requirementsOf(constraint),
                source,
                held,
                site,
                span,
                mode,
                switch (constraint.subject) {
                    .written => if (self.ast.declTag(d) == .function) .{
                        .name = self.ast.tokenText(self.ast.declName(d)),
                        .reason = self.disposalReason(d),
                    } else null,
                    .parameter => null,
                },
            )) {
                switch (constraint.subject) {
                    .written => |subject| try self.citeWhereClause(reported, subject),
                    .parameter => {},
                }
                return true;
            }
        }
        if (d == self.raw_accesses.closure and args.len == 2 and self.builder.erasedSignature(args[0]) == null and
            self.builder.get(args[0]) != .parameter and args[0] != .poison)
        {
            if (mode == .ask) return true;
            try self.noteRefused(at);
            try self.sink.addErrorFmt(
                .t_bound,
                self.ast.fileOf(at),
                self.ast.tokenSpan(at),
                "write the `fn` or `inout fn` type the closure is called as",
                "`Closure` takes a `fn` or `inout fn` type, and `{s}` is not one",
                .{(try self.typeName(args[0]))},
            );
            return true;
        }
        if (self.raw_accesses.opensClosure(d) and args.len == 1) if (enclosing) |outer| if (outer.settled.len > 0) {
            const callback = args[0];
            const signature = outer.settled[0];
            if (callback == .poison or signature == .poison) return false;
            // Opening erases the callback's type, so what it is called as has
            // to be a signature here, not a parameter an instantiation
            // settles later: nothing could then check the callback against it.
            if (self.builder.erasedSignature(signature) == null) {
                if (mode == .ask) return true;
                try self.noteRefused(at);
                const hint = switch (self.builder.get(signature)) {
                    .parameter => "open it where the `fn` or `inout fn` type it is called as is written",
                    .callable => "a kept closure is called in place, so give the callback read or `inout` invocation",
                    else => "write the `fn` or `inout fn` type the closure is called as",
                };
                try self.sink.addErrorFmt(
                    .t_bound,
                    self.ast.fileOf(at),
                    self.ast.tokenSpan(at),
                    hint,
                    "a closure is opened at a `fn` or `inout fn` type, and `{s}` is not one",
                    .{(try self.typeName(signature))},
                );
                return true;
            }
            // A closure that may be dropped without a release, as one in an
            // arena may, cannot own what must be released: the obligation
            // would be dropped with it, unseen by its type.
            if (outer.settled.len == 2 and !try self.closureMustBeReleased(outer.settled) and
                !try self.builder.meetsCapabilityWithin(self.generic, callback, .discardable))
            {
                if (mode == .ask) return true;
                try self.noteRefused(at);
                const pool = self.builder.view();
                const allocator = try writtenTypeName(self.sink.arena, self.ast, self.program, self.res, &pool, self.current, outer.settled[1]);
                const capture = try self.capturePreventing(callback, .discardable);
                const owner = if (capture) |held|
                    try std.fmt.allocPrint(self.sink.arena, "this closure captures `{s}`, {s} {s} that must be released", .{ held.name, article.before(held.ty), held.ty })
                else
                    "this callback owns what must be released";
                const hint = if (capture) |held|
                    try std.fmt.allocPrint(self.sink.arena, "capture `{s}` by `read`, or keep the closure with `mem.Closure.open(closure)`, whose memory is released", .{held.name})
                else
                    "capture nothing that must be released, or keep the closure with `mem.Closure.open(closure)`, whose memory is released";
                try self.sink.addErrorFmt(
                    .t_bound,
                    self.ast.fileOf(at),
                    self.ast.tokenSpan(at),
                    hint,
                    "{s}, and a closure kept in memory from `{s}` may be dropped without releasing it",
                    .{ owner, allocator },
                );
                return true;
            }
            const wanted = try self.builder.carriedByCallee(signature);
            if (!try self.dischargesCallable(callback, wanted, .{ .file = self.ast.fileOf(at), .span = self.ast.tokenSpan(at) })) {
                if (mode == .ask) return true;
                try self.noteRefused(at);
                if (try self.retainsIntoCapture(callback)) {
                    try self.sink.addErrorFmt(
                        .t_bound,
                        self.ast.fileOf(at),
                        self.ast.tokenSpan(at),
                        "keep what it is given outside the closure, or keep the closure's own type",
                        "this closure keeps its arguments in what it captured, and the `fn` type `{s}` it is kept as cannot say so",
                        .{(try self.typeName(signature))},
                    );
                    return true;
                }
                try self.sink.addErrorFmt(
                    .t_bound,
                    self.ast.fileOf(at),
                    self.ast.tokenSpan(at),
                    "give it a callable with exactly that signature",
                    "the closure is called as `{s}`, and `{s}` cannot be called that way",
                    .{ (try self.typeName(signature)), (try self.typeName(callback)) },
                );
                return true;
            }
        };
        return false;
    }

    test "a where clause projected from the caller's parameters is judged under the caller's clauses" {
        const program =
            \\trait Source { type Item }
            \\trait Pipe {
            \\    type Out
            \\    fn drain(_self: Self) where Self.Out: Discardable {}
            \\}
            \\struct Wrap[I] { inner: I }
            \\impl[I: Source] Pipe for Wrap[I] where I.Item: Discardable { type Out = I }
            \\fn _run[S: Source](wrap: Wrap[S]) where S.Item: Discardable { wrap.drain() }
            \\fn main() -> UInt8 { 0 }
        ;
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        var sink = Sink.init(arena.allocator());
        _ = try checkSourceInto(arena.allocator(), program, &sink);
        try testing.expectEqual(@as(u32, 1), sink.error_count);
        try testing.expect(diagnosticSays(&sink, .t_bound, "does not have that capability"));

        var proven = Sink.init(arena.allocator());
        const discardable = try std.mem.replaceOwned(u8, arena.allocator(), program, "where S.Item: Discardable", "where S: Discardable, S.Item: Discardable");
        _ = try checkSourceInto(arena.allocator(), discardable, &proven);
        if (proven.error_count > 0) for (proven.items()) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.message });
        try testing.expectEqual(@as(u32, 0), proven.error_count);
    }

    test "an operation's own Discardable clause explains what the operation does with the value" {
        const program =
            \\trait Source { type Item }
            \\trait Pipe {
            \\    type Out
            \\    fn eat(sink self: Self) where Self.Out: Discardable
            \\}
            \\@linear
            \\struct Ingot { id: UInt8 }
            \\struct Belt {}
            \\impl Pipe for Belt {
            \\    type Out = Ingot
            \\    fn eat(sink self: Belt) { let Belt {} = self }
            \\}
            \\fn main() -> UInt8 {
            \\    Belt {}.eat()
            \\    0
            \\}
        ;
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        var sink = Sink.init(arena.allocator());
        _ = try checkSourceInto(arena.allocator(), program, &sink);
        try testing.expect(diagnosticSays(&sink, .t_bound, "`eat` may dispose of an `Ingot`, so it requires the type to be Discardable; give the value to an operation that keeps it, or settle it before"));
    }

    /// Points the refusal reported since the sink held `reported` items at the
    /// `where` predicate whose subject is `subject`. The predicate sits on the
    /// callee, often in another module, and is what the call failed to meet.
    fn citeWhereClause(self: *Checker, reported: usize, subject: node.TypeRef) std.mem.Allocator.Error!void {
        const items = self.sink.mutableItems();
        if (items.len <= reported) return;
        const last = &items[items.len - 1];
        const labels = try self.sink.arena.alloc(Label, last.labels.len + 1);
        @memcpy(labels[0..last.labels.len], last.labels);
        labels[last.labels.len] = .{
            .file = self.ast.fileOf(subject.at),
            .span = self.ast.writtenSpan(subject),
            .message = "required by this `where` clause",
            .style = .secondary,
        };
        last.labels = labels;
    }

    /// Whether a `Closure` at these arguments must be released wherever it is
    /// held: its type is linear, and its allocator names no type parameter an
    /// instantiation could settle to one whose buffers may be dropped.
    fn closureMustBeReleased(self: *Checker, args: []const TypeId) std.mem.Allocator.Error!bool {
        if (self.mentionsAnyParameter(args[1])) return false;
        const closure = try self.builder.instantiate(self.type_of_decl.get(self.raw_accesses.closure), self.raw_accesses.closure, args);
        return try self.builder.capabilityOfWithin(self.generic, closure) == .linear;
    }

    /// Whether a closure of type `ty` stores an argument in one of its own
    /// captures, which a structural callable type has no way to state.
    fn retainsIntoCapture(self: *Checker, ty: TypeId) std.mem.Allocator.Error!bool {
        const closure = switch (self.builder.get(ty)) {
            .closure => |closure| closure,
            else => return false,
        };
        const signature = self.builder.get(try self.builder.closureSignature(closure)).callable;
        for (signature.contracts) |contract| {
            if (contract.kind == .retains) if (contract.destination) |destination| if (destination.root == .capture) return true;
        }
        return false;
    }

    /// Whether `ty` names a type parameter anywhere in it.
    fn mentionsAnyParameter(self: *Checker, ty: TypeId) bool {
        switch (self.builder.get(ty)) {
            .parameter => return true,
            .borrow => |b| return self.mentionsAnyParameter(b.referent),
            .array => |a| return self.mentionsAnyParameter(a.element),
            .callable => |signature| {
                for (self.builder.callableParams(signature)) |param| if (self.mentionsAnyParameter(param.ty)) return true;
                return self.mentionsAnyParameter(signature.result);
            },
            else => {},
        }
        const origin = self.builder.instanceOf(ty) orelse return false;
        for (self.builder.argsOf(origin)) |arg| if (self.mentionsAnyParameter(arg)) return true;
        return false;
    }

    /// The signature a call through an erased closure of type `ty` checks
    /// against, or null where `ty` is not a `mem.Closure` at a callable type.
    /// Its result may carry what the closure carries, as a call through a
    /// generic callable bound's may.
    fn erasedCallSignature(self: *Checker, ty: TypeId) std.mem.Allocator.Error!?TypeId {
        const origin = self.builder.instanceOf(ty) orelse return null;
        if (self.raw_accesses.closure == .none or origin.decl != self.raw_accesses.closure) return null;
        const args = self.builder.argsOf(origin);
        if (args.len != 2 or self.builder.erasedSignature(args[0]) == null) return null;
        return try self.builder.carriedByCallee(args[0]);
    }

    /// Whether this written type has already been refused.
    fn refusedBefore(self: *const Checker, at: TokenId) bool {
        return self.bounds_reported.contains(at);
    }

    fn noteRefused(self: *Checker, at: TokenId) std.mem.Allocator.Error!void {
        const entry = try self.bounds_reported.getOrPut(self.gpa, at);
        if (!entry.found_existing) try self.bounds_reported_order.append(self.gpa, at);
    }

    /// Records `demand`, whose trait arguments the caller may free once this
    /// returns: the order list keeps its own copy.
    fn noteRefusedDemand(self: *Checker, demand: types_mod.RefusedDemand) std.mem.Allocator.Error!void {
        const entry = try self.refused_demands.getOrPut(self.gpa, demand);
        if (entry.found_existing) return;
        var owned = demand;
        if (owned.lacks == .trait and owned.lacks.trait.args.len > 0) {
            owned.lacks.trait.args = self.gpa.dupe(TypeId, owned.lacks.trait.args) catch |err| {
                self.refused_demands.removeByPtr(entry.key_ptr);
                return err;
            };
        }
        entry.key_ptr.* = owned;
        self.refused_demands_order.append(self.gpa, owned) catch |err| {
            self.refused_demands.removeByPtr(entry.key_ptr);
            freeRefusedDemand(self.gpa, owned);
            return err;
        };
    }

    /// Where the refusal and demand order lists stood, so a speculative scope
    /// can forget what it noted.
    const RefusalMark = struct { refusals: usize, demands: usize };

    fn refusalMark(self: *const Checker) RefusalMark {
        return .{ .refusals = self.bounds_reported_order.items.len, .demands = self.refused_demands_order.items.len };
    }

    /// Forgets every refusal and refused demand noted since `mark`.
    fn forgetRefusalsSince(self: *Checker, mark: RefusalMark) void {
        for (self.bounds_reported_order.items[mark.refusals..]) |at| _ = self.bounds_reported.remove(at);
        self.bounds_reported_order.shrinkRetainingCapacity(mark.refusals);
        for (self.refused_demands_order.items[mark.demands..]) |demand| {
            _ = self.refused_demands.remove(demand);
            freeRefusedDemand(self.gpa, demand);
        }
        self.refused_demands_order.shrinkRetainingCapacity(mark.demands);
    }

    /// Where the arguments a bound names are read from, and what to
    /// substitute through them where one of those arguments is itself a
    /// parameter of the declaration that wrote the bound.
    const BoundSettlement = struct {
        decl: node.DeclId,
        settled: []const TypeId,

        /// The parameters a function's bound may name besides its own, as
        /// one use settled them. A member of an implementation generic over
        /// its head names the head's; a trait's operation names the trait's.
        /// A call and a function value both read a bound through this, so an
        /// operation is offered at the same arguments however it is reached.
        fn enclosing(
            head: node.DeclId,
            head_settled: []const TypeId,
            trait: node.DeclId,
            trait_settled: []const TypeId,
        ) ?BoundSettlement {
            if (head != node.DeclId.none) return .{ .decl = head, .settled = head_settled };
            if (trait != node.DeclId.none) return .{ .decl = trait, .settled = trait_settled };
            return null;
        }
    };

    test "a bound's enclosing parameters are the head's, else the trait's" {
        const head_args = [_]TypeId{.u8};
        const trait_args = [_]TypeId{.bool_};
        const head = BoundSettlement.enclosing(node.DeclId.at(1), &head_args, node.DeclId.at(2), &trait_args).?;
        try testing.expectEqual(node.DeclId.at(1), head.decl);
        try testing.expectEqual(@as(usize, 1), head.settled.len);
        try testing.expectEqual(TypeId.u8, head.settled[0]);
        const trait = BoundSettlement.enclosing(node.DeclId.none, &.{}, node.DeclId.at(2), &trait_args).?;
        try testing.expectEqual(node.DeclId.at(2), trait.decl);
        try testing.expectEqual(TypeId.bool_, trait.settled[0]);
        try testing.expect(BoundSettlement.enclosing(node.DeclId.none, &.{}, node.DeclId.none, &.{}) == null);
    }

    const OwnBound = struct {
        source: ArgsFrom,
        /// The declaration whose own parameters a bound's arguments may
        /// name -- `[I, C: Lookup[I]]` names `I`, which belongs to the same
        /// declaration `C` does, and `trait Fancy[X]: Lookup[X]` names `X`,
        /// which belongs to the trait.
        decl: node.DeclId,
        /// What this call, instantiation or implementation settled `decl`'s
        /// own parameters to, position for position with
        /// `self.ast.declTypeParams(decl)`.
        settled: []const TypeId,
        /// Parameters declared by an implementation enclosing `decl`, where a
        /// member's bound may name both its own parameters and its head's.
        enclosing: ?BoundSettlement = null,

        /// A bound's arguments are interned once, and this says which reading
        /// holds them: a parameter carries its own, and a bound written on a
        /// declaration rather than on a parameter has none to read, so its
        /// arguments are settled in the scope that wrote them.
        const ArgsFrom = union(enum) {
            /// The parameter's own interned type, read for the arguments its
            /// bound named each trait at: `traitsBounding` settled them when
            /// the declaration's parameters were interned.
            parameter: TypeId,
            /// The scope a declaration's own bounds were written in, which is
            /// the declaration itself.
            scope: BoundInterning,
        };
    };

    /// The arguments one written bound names, settled by what filled the
    /// declaration that wrote it, and empty where the caller holds no reading
    /// of them. The caller owns the slice.
    fn settledBoundArgs(
        self: *Checker,
        own: ?OwnBound,
        bound: node.TraitBound,
    ) std.mem.Allocator.Error![]const TypeId {
        const o = own orelse return &.{};
        switch (o.source) {
            .parameter => |ty| {
                const t = traitAt(self.ast, self.res, bound.named.name) orelse return &.{};
                const raw = self.boundArgsWritten(ty, t, bound);
                return self.substitutedOwnBoundArgs(raw, o);
            },
            .scope => |ctx| {
                const raw = try self.internedBoundArgs(ctx, bound);
                defer if (raw.len > 0) self.gpa.free(raw);
                return self.substitutedOwnBoundArgs(raw, o);
            },
        }
    }

    fn substituteOwnBoundType(self: *Checker, ty: TypeId, own: OwnBound) std.mem.Allocator.Error!TypeId {
        const settled = try self.builder.substitute(ty, own.decl.index(), own.settled);
        const enclosing = own.enclosing orelse return settled;
        return self.builder.substitute(settled, enclosing.decl.index(), enclosing.settled);
    }

    fn substitutedOwnBoundArgs(
        self: *Checker,
        raw: []const TypeId,
        own: OwnBound,
    ) std.mem.Allocator.Error![]const TypeId {
        if (raw.len == 0) return raw;
        const out = try self.gpa.alloc(TypeId, raw.len);
        errdefer self.gpa.free(out);
        for (raw, out) |arg, *slot| slot.* = try self.substituteOwnBoundType(arg, own);
        return out;
    }

    /// Reports the first bound in `bounds` that `held` does not discharge, and
    /// says whether it reported one.
    ///
    /// One reader for every position a bound is checked in -- a type argument
    /// standing for a parameter, the type an implementation settles a declared
    /// type to, and the type an implementation names for a trait that bounds
    /// itself. A bound admits the same types wherever it is written, so a
    /// second reader would be a second answer to what one means, and the two
    /// would agree until somebody wrote the type neither was tested on.
    ///
    /// Both halves of a bound, because a run of them is one demand: the traits
    /// it names, each discharged by an implementation existing, and the
    /// capability requirement, discharged by the type's effective capabilities.
    ///
    /// A bound naming no trait is left alone here: what it names is the
    /// resolver's question, and it reports the name that reaches nothing.
    ///
    /// **Bound:** the bounds written on the one name.
    fn reportUndischarged(
        self: *Checker,
        named: TokenId,
        bounds: []const node.TraitBound,
        /// Null wherever `held` is being checked against a bound with nothing
        /// to settle its arguments by, which discharges arg-blind.
        own: ?OwnBound,
        held: TypeId,
        at: TokenId,
        span: Span,
    ) std.mem.Allocator.Error!bool {
        return self.undischarged(self.ast.tokenText(named), bounds, own, held, at, span, .report, null);
    }

    /// A function whose own `where` clause demands `Discardable`, as the
    /// report names it.
    const Operation = struct {
        name: []const u8,
        /// Why the operation disposes of a value when its name does not say,
        /// appended to the general help.
        reason: ?[]const u8,
    };

    /// Refuses `held` for the `Owned` bound written at `bound`, naming the
    /// parts walked from it to what carries the dependency. The path is found
    /// over the edges the containment answer was computed from, so it names
    /// the reason that answer gave, and it stops at the outermost part whose
    /// inside the reader cannot select: a sealed type's fields or a newtype's
    /// base. The label is the edit `editForOwned` finds, with dropping the
    /// bound offered only where the program wrote it.
    fn reportNotOwned(self: *Checker, subject: []const u8, held: TypeId, bound: TokenId, at: TokenId, span: Span) std.mem.Allocator.Error!void {
        const witness = (try self.builder.dependencyWitness(self.gpa, held)) orelse unreachable;
        defer witness.deinit(self.gpa);
        if (self.refused_owned_subjects.contains(.{ .decl = self.generic, .subject = witness.seed })) return;
        const held_name = try self.typeName(held);
        const seed_name = try self.typeName(witness.seed);
        var help = self.unmetBoundHelp(bound);
        help.another_value = "pass a value whose type owns everything it holds";
        const label = try self.unmetLabel(help, try self.editForOwned(held, witness.seed));
        const file = self.ast.fileOf(at);

        const visible = self.selectableSteps(held, witness);
        const path = try self.witnessPath(witness.steps[0..visible]);
        const truncated = visible < witness.steps.len;
        const part_name = if (visible == 0) held_name else try self.typeName(witness.parts[visible - 1]);
        const what: []const u8 = if (self.builder.get(witness.seed) == .parameter)
            try std.fmt.allocPrint(self.sink.arena, "`{s}`, which may stand for a type that carries one", .{seed_name})
        else if (self.builder.get(witness.seed) == .borrow)
            "an observation of another value"
        else if (self.builder.view().declOfType(witness.seed) == self.raw_accesses.slice)
            "a view of storage it does not own"
        else
            "raw storage another value owns";

        if (truncated) {
            if (visible == 0) return self.sink.addErrorFmt(
                .t_bound,
                file,
                span,
                label,
                "`{s}` requires `Owned`, and `{s}` can carry a borrow: it holds {s}",
                .{ subject, held_name, what },
            );
            return self.sink.addErrorFmt(
                .t_bound,
                file,
                span,
                label,
                "`{s}` requires `Owned`, and `{s}` can carry a borrow: `{s}` is {s} `{s}`, which holds {s}",
                .{ subject, held_name, path, article.before(part_name), part_name, what },
            );
        }
        if (self.builder.get(witness.seed) == .parameter) {
            if (visible == 0) return self.sink.addErrorFmt(
                .t_bound,
                file,
                span,
                label,
                "`{s}` requires `Owned`, and `{s}` may stand for a type that carries a borrow",
                .{ subject, held_name },
            );
            return self.sink.addErrorFmt(
                .t_bound,
                file,
                span,
                label,
                "`{s}` requires `Owned`, and `{s}` can carry a borrow: `{s}` is {s}",
                .{ subject, held_name, path, what },
            );
        }
        if (visible == 0) return self.sink.addErrorFmt(
            .t_bound,
            file,
            span,
            label,
            "`{s}` requires `Owned`, and `{s}` is {s}",
            .{ subject, held_name, what },
        );
        try self.sink.addErrorFmt(
            .t_bound,
            file,
            span,
            label,
            "`{s}` requires `Owned`, and `{s}` can carry a borrow: `{s}` is {s} `{s}`, {s}",
            .{ subject, held_name, path, article.before(seed_name), seed_name, what },
        );
    }

    /// How many leading steps of `witness` name parts this module can
    /// select. A sealed type's fields and a newtype's base are reached by no
    /// selection here, and neither are the elements certified storage holds
    /// or a type argument, so the path stops before each of them.
    fn selectableSteps(self: *const Checker, held: TypeId, witness: types_mod.DependencyWitness) usize {
        var owner = held;
        for (witness.steps, witness.parts, 0..) |step, part, index| {
            switch (step) {
                .base, .stored, .argument => return index,
                .field, .variant, .element, .environment => {},
            }
            if (self.sealedHere(owner)) return index;
            owner = part;
        }
        return witness.steps.len;
    }

    /// A witness path as the parts a reader would select: fields and
    /// variants by name, elements as `[_]`.
    fn witnessPath(self: *Checker, steps: []const types_mod.ContainmentStep) std.mem.Allocator.Error![]const u8 {
        var out: std.ArrayList(u8) = .empty;
        for (steps) |step| {
            const name: []const u8 = switch (step) {
                .field => |field| field,
                .variant => |variant| variant,
                .element => {
                    try out.appendSlice(self.sink.arena, "[_]");
                    continue;
                },
                .environment => continue,
                .base, .stored, .argument => unreachable,
            };
            if (out.items.len > 0) try out.append(self.sink.arena, '.');
            try out.appendSlice(self.sink.arena, name);
        }
        return out.items;
    }

    /// The reason a library operation disposes of a value, where the trait that
    /// provides it records one.
    fn disposalReason(self: *Checker, d: node.DeclId) ?[]const u8 {
        const owner = self.res.signatures.traitOf(self.ast, d) orelse return null;
        if (owner != sequenceDecl(self.ast, self.res)) return null;
        return disposalReasonOf(self.ast.tokenText(self.ast.declName(d)));
    }

    /// `Sequence`'s operations that dispose of a value as a consequence of
    /// their order of evaluation, with the sentence saying so.
    const sequence_disposals = [_]struct { operation: []const u8, reason: []const u8 }{
        .{
            .operation = "zip",
            .reason = "`zip` draws an item from the first sequence before asking the second, and if the second sequence ends first it disposes of that first item, so the first sequence's items must be Discardable; zip in the other order, with the sequence whose items are Discardable first, or walk both sequences by hand",
        },
    };

    fn disposalReasonOf(operation: []const u8) ?[]const u8 {
        for (sequence_disposals) |entry| {
            if (std.mem.eql(u8, entry.operation, operation)) return entry.reason;
        }
        return null;
    }

    test "only an operation with a recorded order of evaluation carries a disposal reason" {
        try testing.expect(disposalReasonOf("zip") != null);
        try testing.expect(disposalReasonOf("skip") == null);
        try testing.expect(disposalReasonOf("filter") == null);
    }

    /// `reportUndischarged`, and in `.ask` mode the same answer with nothing
    /// reported.
    fn undischarged(
        self: *Checker,
        /// What the headline calls what is bounded: the name a bound is
        /// written on, or a written subject in full, `Self.Iter.Item`.
        subject: []const u8,
        bounds: []const node.TraitBound,
        own: ?OwnBound,
        held: TypeId,
        at: TokenId,
        span: Span,
        mode: BoundMode,
        /// The function whose own `where` clause wrote these bounds on a
        /// written subject, where one did: an unmet `Discardable` there is
        /// explained by what the function does with the value.
        operation: ?Operation,
    ) std.mem.Allocator.Error!bool {
        for (bounds) |bound| {
            if (self.isCallableBound(bound)) {
                const expected = try self.settledCallableBound(own, bound);
                if (expected == .poison or try self.dischargesCallable(held, expected, .{ .file = self.ast.fileOf(at), .span = span })) continue;

                const asks = try spellBound(self.gpa, self.ast, bound);
                defer self.gpa.free(asks);
                if (mode == .ask) return true;
                try self.noteRefused(at);
                try self.noteRefusedDemand(.{ .ty = held, .lacks = .{ .callable = expected } });
                try self.sink.addErrorFmt(
                    .t_bound,
                    self.ast.fileOf(at),
                    span,
                    "give it the exact callable type the bound names",
                    "`{s}` requires `{s}`, and `{s}` is not that callable type",
                    .{ subject, asks, (try self.typeName(held)) },
                );
                return true;
            }
            const args = try self.settledBoundArgs(own, bound);
            defer if (args.len > 0) self.gpa.free(args);
            if (try self.discharges(held, bound.named.name, args)) continue;
            if (!self.namesATrait(bound.named.name)) continue;

            // The bound is named at its arguments, because that is what the
            // type failed to implement: `Board` implementing `Lookup[UInt64]`
            // and not `Lookup[Bool]` is told it does not implement the trait
            // otherwise, which is a sentence the program contradicts.
            const asks = try self.builder.spellInstance(self.ast.tokenText(bound.named.name), args);
            defer self.gpa.free(asks);

            if (mode == .ask) return true;
            // A generic function named as a value has no parameters settled
            // yet, and says what is missing where it is used: the report
            // there is the cause, and this one would only precede it.
            if (self.builder.view().mentionsOpenType(held)) return true;
            try self.noteRefused(at);
            if (traitAt(self.ast, self.res, bound.named.name)) |refused_trait|
                try self.noteRefusedDemand(.{ .ty = held, .lacks = .{ .trait = .{ .decl = refused_trait, .args = args } } });
            try self.reportUnmet(
                self.ast.fileOf(at),
                span,
                self.unmetBoundHelp(bound.named.name),
                "`{s}` requires `{s}`, and `{s}` does not implement it",
                .{ subject, asks, (try self.heldName(held)) },
                traitAt(self.ast, self.res, bound.named.name) orelse .none,
                args,
                held,
            );
            return true;
        }

        const admits = try self.traitsBounding(null, bounds);
        defer types_mod.freeBoundTraits(self.gpa, admits);
        const requirement = capabilityDemandedBy(self.ast, self.res, bounds, admits);
        if (integerDemandedBy(self.ast, self.res, bounds, admits) and held != .poison and !self.builder.isIntegerWithin(self.generic, held)) {
            if (mode == .ask) return true;
            try self.noteRefused(at);
            try self.sink.addErrorFmt(.t_bound, self.ast.fileOf(at), span, "supply a built-in integer type or an Integer-constrained parameter", "`{s}` requires `Integer`, and `{s}` is not a built-in integer type", .{ subject, (try self.typeName(held)) });
            return true;
        }
        if (ownedBound(self.ast, self.res, bounds)) |bound| if (held != .poison and try self.builder.mayCarryDependencies(held)) {
            if (mode == .ask) return true;
            if (self.builder.view().mentionsOpenType(held)) return true;
            try self.noteRefused(at);
            try self.reportNotOwned(subject, held, bound, at, span);
            return true;
        };
        if (try self.builder.meetsCapabilityWithin(self.generic, held, requirement)) return false;
        const demanded: []const u8 = switch (requirement) {
            .copyable => "Copyable",
            .discardable => "Discardable",
            .unrestricted => unreachable,
        };
        if (mode == .ask) return true;
        try self.noteRefused(at);
        try self.noteRefusedDemand(.{ .ty = held, .lacks = .{ .capability = requirement } });
        // A closure's capability is its captures', so the report names the
        // capture that fails the bound: the closure itself has no name a
        // reader could change, and neither has a bound in another module.
        if (try self.capturePreventing(held, requirement)) |capture| {
            const why, const lacks = switch (requirement) {
                .copyable => .{ "a value of it may be copied", "cannot be copied" },
                .discardable => .{ "a value of it may be dropped without a release", "must be released" },
                .unrestricted => unreachable,
            };
            try self.sink.addErrorFmt(
                .t_bound,
                self.ast.fileOf(at),
                span,
                switch (requirement) {
                    .copyable => try std.fmt.allocPrint(self.sink.arena, "capture `{s}` by `read`, or capture a copyable value taken from it", .{capture.name}),
                    else => try std.fmt.allocPrint(self.sink.arena, "capture `{s}` by `read`, or build it in memory that is dropped with its owner, such as an arena's", .{capture.name}),
                },
                "`{s}` requires `{s}`, because {s}, and this closure captures `{s}`, {s} {s} that {s}",
                .{ subject, demanded, why, capture.name, article.before(capture.ty), capture.ty, lacks },
            );
            return true;
        }
        const help = if (operation != null and requirement == .discardable) help: {
            const held_name = try self.typeName(held);
            const general = try std.fmt.allocPrint(self.sink.arena, "`{s}` may dispose of {s} `{s}`, so it requires the type to be Discardable; give the value to an operation that keeps it, or settle it before", .{ operation.?.name, article.before(held_name), held_name });
            break :help if (operation.?.reason) |reason|
                try std.fmt.allocPrint(self.sink.arena, "{s}. {s}", .{ general, reason })
            else
                general;
        } else help: {
            // The edit a capability bound offers is the one every other unmet
            // bound's help is built from: through the parameter's bounds, a
            // declaration this program can mark, or another value, and the
            // bound dropped only where the program wrote it.
            var offered = self.unmetBoundHelp(capabilityToken(self.ast, self.res, bounds) orelse at);
            offered.another_value = try std.fmt.allocPrint(self.sink.arena, "pass a value whose type is `{s}`", .{demanded});
            break :help try self.unmetLabel(offered, try self.editForCapability(requirement, held));
        };
        try self.sink.addErrorFmt(
            .t_bound,
            self.ast.fileOf(at),
            span,
            help,
            "`{s}` requires `{s}`, and `{s}` does not have that capability",
            .{ subject, demanded, (try self.typeName(held)) },
        );
        return true;
    }

    /// The first capture of the closure type `held` whose type does not meet
    /// `requirement`, by the name the lambda gives it and its type as this
    /// module writes it; null where `held` is not a closure or no capture is
    /// at fault.
    fn capturePreventing(self: *Checker, held: TypeId, requirement: types_mod.CapabilityRequirement) std.mem.Allocator.Error!?struct { name: []const u8, ty: []const u8 } {
        const closure = switch (self.builder.get(held)) {
            .closure => |closure| closure,
            else => return null,
        };
        if (closure.environment == .unit) return null;
        for (self.res.closureCaptures(closure.closure), 0..) |capture, index| {
            const ty = self.builder.fieldType(closure.environment, @intCast(index));
            // The observation an `inout` capture stores is copyable, and the
            // exclusive lend it stands for is not.
            if (capture.convention == .inout and requirement == .copyable) return .{
                .name = self.ast.tokenText(self.res.captureNameToken(capture.binding)),
                .ty = "place lent `inout`",
            };
            if (try self.builder.meetsCapabilityWithin(self.generic, ty, requirement)) continue;
            const pool = self.builder.view();
            return .{
                .name = self.ast.tokenText(self.res.captureNameToken(capture.binding)),
                .ty = try std.fmt.allocPrint(self.sink.arena, "`{s}`", .{try writtenTypeName(self.sink.arena, self.ast, self.program, self.res, &pool, self.current, ty)}),
            };
        }
        return null;
    }

    fn dischargesCallable(self: *Checker, unresolved_held: TypeId, unresolved_expected: TypeId, at: open_types_mod.Site) !bool {
        // A closure minted while an open integer was unsettled names it; read
        // both sides as the types their open integers settled on.
        const held = try self.builder.resolveOpen(unresolved_held, &self.open_types);
        const expected = try self.builder.resolveOpen(unresolved_expected, &self.open_types);
        if (self.builder.view().callableSatisfies(held, expected) or self.builder.carriesCallableBoundWithin(self.generic, held, expected)) return true;
        // The bound is a type the callable's signature must equal, so an open
        // integer on either side settles on what the other names: one in a
        // closure's signature on the bound's, and one in the bound -- read
        // through a receiver whose literals are still open -- on the
        // signature a function value was declared with.
        const written = switch (self.builder.get(held)) {
            .closure => |closure| try self.builder.closureSignature(closure),
            .callable => held,
            else => return false,
        };
        if (self.builder.get(expected) == .callable) _ = try self.meet(written, expected, at);
        const signature = try self.builder.resolveOpen(written, &self.open_types);
        return self.builder.view().callableSatisfies(signature, try self.builder.resolveOpen(expected, &self.open_types));
    }

    /// Whether a bound names a trait rather than a capability.
    ///
    /// Through `boundNames`, which is where the order the language decides
    /// that in is written: a spelling reserved for a capability still names a
    /// trait where the program declared one. This pass and the resolver both
    /// ask it there, and each supplies the trait its own lookup reached --
    /// which is the one thing the two cannot share, because the resolver asks
    /// while the scope chain is still being built and this reads the table
    /// that chain became.
    fn namesATrait(self: *const Checker, bound: TokenId) bool {
        return switch (resolve_mod.boundNames(self.ast, bound, traitAt(self.ast, self.res, bound))) {
            .trait => true,
            .capability, .integer, .owned, .unknown => false,
        };
    }

    /// What a bound names, read from the tables the resolver left.
    ///
    /// The other half of `boundDeclaring`'s pair: the rule about which bound a
    /// settled reference is read through is written once, and each pass hands
    /// it the lookups it has.
    const BoundsRead = struct {
        checker: *const Checker,

        pub fn traitBoundAt(self: BoundsRead, tok: TokenId) ?node.DeclId {
            const ast = self.checker.ast;
            return switch (resolve_mod.boundNames(ast, tok, traitAt(ast, self.checker.res, tok))) {
                .trait => |d| d,
                .capability, .integer, .owned, .unknown => null,
            };
        }

        pub const Error = std.mem.Allocator.Error;

        pub fn sameArgs(self: BoundsRead, a: node.TypeRefRange, b: node.TypeRefRange) Error!bool {
            return self.checker.sameBoundArgs(a, b);
        }

        pub fn hashArgs(self: BoundsRead, args: node.TypeRefRange) Error!u64 {
            return resolve_mod.hashBoundArgs(self.checker.ast, self.checker.settledWritten(), args) catch unreachable;
        }

        pub fn allocator(self: BoundsRead) std.mem.Allocator {
            return self.checker.gpa;
        }

        /// **Bound:** the members that trait declares, through the index this
        /// pass already holds them by.
        pub fn declaresMember(self: BoundsRead, trait: node.DeclId, name: StringId) bool {
            const ast = self.checker.ast;
            for (self.checker.decls.ownedBy(ast.declName(trait))) |m| {
                if (ast.tokenName(ast.declName(m)) == name) return true;
            }
            return false;
        }
    };

    /// Whether `held` discharges the bound `trait`, at `args`.
    ///
    /// `args` empty for a trait that declares arguments falls back to `Reach`'s
    /// arg-blind reading, over a snapshot of the pool as it stands. An
    /// argumentless trait has one exact empty key. Exact keys route through
    /// `Builder.implementationRow` over the open pool rather than a snapshot: finding an
    /// implementation generic over its own head substitutes through what the
    /// receiver supplies, which mints where the substitution moves and a
    /// snapshot cannot. The row rather than only a declaration,
    /// because an implementation the compiler provides -- an array's `Index`
    /// -- discharges a bound with no declaration to name; `checkImplementationExists`
    /// asks the same way, for the same reason.
    fn discharges(
        self: *Checker,
        held: TypeId,
        trait: TokenId,
        args: []const TypeId,
    ) std.mem.Allocator.Error!bool {
        const declared = traitAt(self.ast, self.res, trait) orelse return false;
        return self.dischargesDeclared(held, declared, args);
    }

    fn dischargesDeclared(self: *Checker, held: TypeId, declared: node.DeclId, args: []const TypeId) std.mem.Allocator.Error!bool {
        if (try self.dischargesOnce(held, declared, args)) return true;
        if (!try self.fallBackOpenParts(held, args)) return false;
        const settled_args = try self.gpa.alloc(TypeId, args.len);
        defer self.gpa.free(settled_args);
        for (args, settled_args) |argument, *settled| settled.* = try self.builder.resolveOpen(argument, &self.open_types);
        return self.dischargesOnce(try self.builder.resolveOpen(held, &self.open_types), declared, settled_args);
    }

    fn dischargesOnce(self: *Checker, held: TypeId, declared: node.DeclId, args: []const TypeId) std.mem.Allocator.Error!bool {
        if (args.len == 0 and self.ast.declTypeParams(declared).len != 0) {
            try self.builder.prepareTraitLookupWithin(self.generic, declared, held);
            const pool = try self.builder.capabilityView();
            return self.reaching(&pool).answers(self.gpa, held, declared);
        }
        const pool = try self.builder.capabilityView();
        if (rendersDisplayItself(&pool, self.display_decl, held, declared)) return true;
        return try self.builder.implementationChoiceWithin(self.generic, declared, args, held) != null;
    }

    /// What a postfix call may reach from here, over the pool as it stands.
    ///
    /// The view is the caller's, because it names the pool's current arrays and
    /// interning a type moves them.
    fn reaching(self: *const Checker, pool: *const Typing) Reach {
        return .{
            .ast = self.ast,
            .source_program = self.program.source,
            .expanded_program = self.program,
            .res = self.res,
            .typing = pool,
            .index = &self.impl_index,
            .impls = self.implementations,
            .signatures = self.decl_signatures,
            .from = self.current,
            .scope = self.generic,
            .display = self.display_decl,
        };
    }

    /// `sought` says which members count: those a postfix call passes its
    /// receiver to, or every operation, which a call written after a type's
    /// name reaches. `declaring`, when given, receives each trait in this
    /// module's scope that declares `wanted` as such a member, so a report
    /// asking about them reads this walk rather than walking the trait names
    /// again.
    fn prepareNamedLookup(self: *Checker, held: TypeId, wanted: StringId, elsewhere: bool, sought: Reach.MemberSought, declaring: ?*std.ArrayList(node.DeclId)) !void {
        // Inherent names need the receiver's representation. Trait operations
        // additionally need applicability for signatures with this name. A
        // transparent observation forwards individual read operations, even
        // when their trait also declares mutating ones, so every referent layer
        // receives the same preparation that candidate enumeration reads.
        //
        // The traits read are the rows under the name: this module's where the
        // call is what is being resolved, and every module's -- each trait
        // once -- where a report is asking what an import would reach.
        var receiver = held;
        while (receiver != .poison) {
            try self.builder.prepareCapabilityWithin(self.generic, receiver);
            var rows = if (elsewhere) self.res.traitMembersNamedAnywhere(wanted) else self.res.traitMembersNamed(self.current, wanted);
            while (rows.next()) |row| {
                if (!memberSought(self.ast, row.member, sought)) continue;
                try self.builder.prepareTraitLookupWithin(self.generic, row.trait, receiver);
            }
            receiver = switch (self.builder.get(receiver)) {
                .borrow => |observation| observation.referent,
                else => break,
            };
        }
        if (declaring) |out| {
            var rows = self.res.traitMembersNamed(self.current, wanted);
            var last: node.DeclId = .none;
            while (rows.next()) |row| {
                if (row.trait == last or !memberSought(self.ast, row.member, sought)) continue;
                last = row.trait;
                try out.append(self.gpa, row.trait);
            }
        }
    }

    /// What a call through a trait settles the signature's `Self` to.
    ///
    /// `Self` is the trait's own type parameter in all but spelling. An
    /// argument standing where one is written settles it; where the signature
    /// writes it only in what it returns, the type the call is asked for does,
    /// because a constructor reached through a trait has no argument to read.
    /// Whatever settles it must implement the trait: a signature has no body,
    /// so a type with no implementation names an operation that does not exist
    /// -- and nothing further down could recover it, because the body a call
    /// runs is found from exactly this type.
    ///
    /// Null where the signature writes no `Self` at all, which settles nothing
    /// and is nothing to report. Poison where one is written and nothing here
    /// settles it: the type it would need is unknowable, and that is said at
    /// the call rather than left to spread as a type nobody named.
    const SelfSettlement = struct {
        ty: TypeId,
        implementation: ?usize = null,
    };

    fn settleSelf(
        self: *Checker,
        id: ExprId,
        d: node.DeclId,
        args: []const ExprId,
        walked: []bool,
        expected: ?Expected,
        /// The type a call written after a type's name was written after,
        /// which is `Self` whatever the arguments say.
        written: ?TypeId,
    ) std.mem.Allocator.Error!?SelfSettlement {
        const trait = self.ast.declOwner(d);
        if (trait == TokenId.none) return null;
        if (written) |held| {
            // Reported at the type the call was written after, in front of
            // any type arguments.
            const callee = self.ast.call(id).callee;
            const field = if (self.ast.exprTag(callee) == .index) self.ast.binary(callee).lhs else callee;
            return try self.settledSelf(id, d, trait, held, self.locOf(self.ast.unaryOperand(field)));
        }

        try self.ensureSignature(d);
        const signature = switch (self.builder.get(self.decl_signatures.get(d))) {
            .callable => |callable| callable,
            else => return .{ .ty = .poison },
        };
        // Declaration signatures place symbolic Self after their own generic
        // parameters. Match that position through the shared type unifier.
        const self_index: u32 = @intCast(self.ast.declTypeParams(d).len);
        const found = try self.gpa.alloc(TypeId, self_index + 1);
        defer self.gpa.free(found);

        // Prefer arguments with known types before contextual constructors.
        for ([_]bool{ true, false }) |speaking| {
            if (!speaking) {
                @memset(found, .poison);
                try self.settleResultContexts(signature.result, &.{.{ .owner = d, .generics = self.ast.declTypeParams(d), .found = found }}, expected, self.successExpectationAt(id), self.failureExpectationAt(id), self.methodExpectationAt(id), .{ .callee = d, .args = args });
                if (found[self_index] != .poison) {
                    return try self.settledSelf(id, d, trait, found[self_index], self.locOf(id));
                }
            }

            for (self.ast.declParams(d), 0..) |_, j| {
                if (j >= args.len) break;
                // A parameter the call omitted settles nothing: what fills it is a
                // constant written in the declaration, which is a value of a type
                // already fixed rather than one this call decides.
                if (args[j] == ExprId.none) continue;
                const declared = self.builder.callableParams(signature)[j].ty;
                if (!self.mentionsParameterAt(declared, d, .stops, self_index)) continue;

                // Checked with nothing expected, exactly as inference checks the
                // argument settling a type parameter: what the parameter demands is
                // what this argument is about to decide.
                const marked = self.ast.exprTag(args[j]) == .marked;
                const value = if (marked) self.ast.unaryOperand(args[j]) else args[j];
                // An argument already walked, such as a postfix call's
                // receiver, is read as it was checked: checking it again would
                // mint fresh open types for its literals, and a call inside it
                // would keep the instance it recorded the first time while
                // this call settled the second.
                if (!walked[j] and self.determinesItsOwnType(value) != speaking) continue;
                const held = if (walked[j]) self.builder.exprType(value) else try self.check(value, null);
                walked[j] = true;
                if (held == .poison) return .{ .ty = .poison };

                @memset(found, .poison);
                var clash: ?Clash = null;
                _ = try self.settle(declared, held, d, found, &clash);
                if (found[self_index] == .poison) continue;
                return try self.settledSelf(id, d, trait, found[self_index], .{
                    .file = self.ast.fileOfExpr(value),
                    .span = self.ast.exprSpan(value),
                });
            }
        }

        // A call that passes the wrong number of arguments has nothing
        // standing where `Self` is written because it is wrong about how many
        // arguments there are, and that is the mistake to report. Left to the
        // arity rule, which is about to run.
        if (self.ast.declParams(d).len != args.len) return null;

        // A poisoned expectation, such as an annotation naming no type, was
        // reported where it is written. Where the result writes `Self`, that
        // expectation is what would have settled it, so reporting the call as
        // well describes one mistake twice. A result without `Self` could not
        // have been settled by any annotation, and that is a mistake of its own.
        if (expected) |want| if (want.ty == .poison and self.mentionsParameterAt(signature.result, d, .stops, self_index))
            return .{ .ty = .poison };

        // Every trait signature needs a concrete receiver to select a body,
        // even when neither its parameters nor its result mention Self.
        try self.sink.addErrorFmt(
            .t_bound,
            self.ast.fileOfExpr(id),
            self.ast.exprSpan(id),
            "pass what `Self` stands for, or say what the call returns",
            "nothing here settles `{s}`'s `Self`",
            .{self.ast.tokenText(trait)},
        );
        return .{ .ty = .poison };
    }

    /// What a call settles its trait's parameters to.
    ///
    /// A trait's parameter stands in a signature's parameter position, so the
    /// argument standing there settles it -- the same question a generic
    /// function's own parameter answers, asked of the list the trait declares
    /// rather than the list the signature does. Where it stands only in the
    /// return type, the expectation settles it, which is how `Self` in that
    /// position is already reached.
    ///
    /// A parameter neither reaches is refused where the call is written, the
    /// way `Self` in that position already is: the implementation a call runs
    /// is keyed by what it settled, so one that settled nothing names no body,
    /// and left as poison it is a call the checker accepts and lowering emits
    /// as a value nothing computed. The caller owns the slice.
    fn settleTraitArgs(
        self: *Checker,
        id: ExprId,
        d: node.DeclId,
        args: []const ExprId,
        walked: []bool,
        expected: ?Expected,
    ) std.mem.Allocator.Error![]TypeId {
        const trait = self.traitDeclaring(d) orelse return &.{};
        const params = self.ast.declTypeParams(trait);
        if (params.len == 0) return &.{};

        const out = try self.gpa.alloc(TypeId, params.len);
        errdefer self.gpa.free(out);
        @memset(out, .poison);
        self.seedTraitArgsFromBound(trait, out);

        const signature = switch (self.builder.get(self.decl_signatures.get(d))) {
            .callable => |callable| callable,
            else => return out,
        };
        const settling = [_]Settling{.{ .owner = trait, .generics = params, .found = out }};
        // Settle the trait's parameters together, from known arguments, result
        // context, then waiting literals. Each argument is checked at most once.
        var argument_poisoned = false;
        for ([_]bool{ true, false }) |speaking| {
            if (!speaking) {
                try self.settleResultContexts(signature.result, &settling, expected, self.successExpectationAt(id), self.failureExpectationAt(id), self.methodExpectationAt(id), .{ .callee = d, .args = args });
                try self.seedTraitArgsFromImplementation(trait, signature, args, out);
            }
            for (0..signature.param_count) |j| {
                if (j >= args.len) break;
                // Checking an argument can grow the signature storage.
                const param = self.builder.callableParams(signature)[j];
                if (args[j] == .none) continue;
                if (!self.mentionsParameter(param.ty, trait, .stops)) continue;
                const value = if (self.ast.exprTag(args[j]) == .marked) self.ast.unaryOperand(args[j]) else args[j];
                if (self.determinesItsOwnType(value) != speaking) continue;
                if (!speaking and !self.hasOpenParameter(param.ty, &settling)) continue;
                const got = if (walked[j]) self.builder.exprType(value) else try self.check(value, null);
                walked[j] = true;
                if (got == .poison) {
                    argument_poisoned = true;
                    continue;
                }
                var ignored: ?Clash = null;
                _ = try self.settle(param.ty, got, trait, out, &ignored);
            }
        }
        for (params, 0..) |tp, k| {
            if (out[k] != .poison or argument_poisoned) continue;

            // An expectation that was reported settles nothing, and the reason
            // this parameter has no type is that mistake rather than the
            // absence of anything to settle it.
            if (expected) |want| if (want.ty == .poison) continue;

            // A `Self` this call could not settle already took the call with
            // it, and every parameter written in terms of the trait is
            // unknowable for that one reason.
            if (self.self_at_call) |held| if (held == .poison) continue;

            try self.sink.addErrorFmt(
                .t_bound,
                self.ast.fileOfExpr(id),
                self.ast.exprSpan(id),
                "pass what it stands for, or say what the call returns",
                "nothing here settles `{s}`'s `{s}`",
                .{ self.ast.tokenText(self.ast.declName(trait)), self.ast.tokenText(tp.name) },
            );
        }
        return out;
    }

    /// Fills `out` with the arguments the call's receiver's bound gives `trait`.
    ///
    /// A receiver known only through a type parameter reaches the
    /// implementation its bound names, so where the parameter carries exactly
    /// one bound on the trait, that bound's arguments are the call's, before
    /// any argument is read. An argument whose type the trait's parameter
    /// decides, such as a variant written without its enum, then takes it
    /// from the bound, and an operation whose parameters never mention the
    /// trait's is still a call at the bound's arguments. A parameter bounded
    /// on the trait at several argument lists leaves `out` alone, and the
    /// call's arguments settle which list it means.
    ///
    /// **Bound:** the bounds written on the one parameter.
    fn seedTraitArgsFromBound(self: *const Checker, trait: node.DeclId, out: []TypeId) void {
        const receiver = self.self_at_call orelse return;
        if (receiver == .poison) return;
        const named: u32 = @intCast(trait.index());
        var only: ?[]const TypeId = null;
        for (self.builder.boundsOn(receiver)) |bound| {
            if (bound.trait != named) continue;
            if (only != null) return;
            only = bound.args;
        }
        const args = only orelse return;
        if (args.len != out.len) return;
        @memcpy(out, args);
    }

    /// Fills a trait parameter an argument waits on from the one
    /// implementation of `trait` the call's `Self` has. `Money.from(1250)`
    /// converts from the one type `Money` implements `From` for, so the
    /// literal takes that type rather than the default integer. Asked after
    /// every argument that decides its own type, so such an argument still
    /// says which implementation it means. A parameter no argument stands at
    /// is left alone, since nothing at the call waits on it, and a `Self`
    /// with several implementations leaves `out` to the remaining arguments.
    ///
    /// **Bound:** the implementations of `trait` for `Self`'s head, the bounds
    /// on `Self` where it is a parameter, and the signature's parameters once
    /// per trait parameter.
    fn seedTraitArgsFromImplementation(
        self: *Checker,
        trait: node.DeclId,
        signature: types_mod.CallableSignature,
        args: []const ExprId,
        out: []TypeId,
    ) std.mem.Allocator.Error!void {
        const receiver = self.self_at_call orelse return;
        if (receiver == .poison) return;
        if (std.mem.indexOfScalar(TypeId, out, .poison) == null) return;
        // Every implementation for the receiver's head is prepared, so the
        // count below sees each of them rather than the ones asked so far.
        try self.builder.prepareLookupWithin(self.generic, receiver);
        const pool = try self.builder.capabilityView();
        var keys: std.ArrayList([]const TypeId) = .empty;
        defer keys.deinit(self.gpa);
        const open = try self.impl_index.keys(self.gpa, self.implementations, &pool, trait, receiver, self.generic, &keys);
        if (open or keys.items.len != 1 or keys.items[0].len != out.len) return;
        for (out, keys.items[0], 0..) |*slot, settled, k| {
            if (slot.* != .poison) continue;
            for (0..@min(signature.param_count, args.len)) |j| {
                if (args[j] == .none) continue;
                const param = self.builder.callableParams(signature)[j];
                if (!self.mentionsParameterAt(param.ty, trait, .stops, @intCast(k))) continue;
                slot.* = settled;
                break;
            }
        }
    }

    /// The key a call named has an implementation.
    ///
    /// A bound admits the type because it answers the trait, and which of its
    /// implementations runs is settled here -- so a type answering `Holds[UInt8]`
    /// admits a call that settled `T` to `Bool` and then reaches nothing.
    /// Reported here rather than left to lowering, which has no diagnostic to
    /// give and would emit a call to a body that does not exist.
    ///
    /// Only where `Self` is a concrete type. Inside a generic body it is a
    /// parameter, and which implementation that is is not known until the body
    /// is instantiated.
    fn checkImplementationExists(
        self: *Checker,
        id: ExprId,
        rec: types_mod.CallImpl,
    ) std.mem.Allocator.Error!void {
        if (rec.args.len == 0) return;
        if (rec.self_ty == .poison) return;
        for (rec.args) |a| if (a == .poison) return;
        if (self.builder.awaitsTypes(rec.self_ty, rec.args)) return;

        const trait = node.DeclId.at(rec.trait);
        if (self.rendersItself(rec.self_ty, trait)) return;
        // The row rather than the declaration it names: what this asks is
        // whether an implementation exists, and one the compiler provides
        // exists without a source having declared it.
        if (try self.builder.implementationChoiceWithin(self.generic, trait, rec.args, rec.self_ty) != null) return;
        if (try self.fallBackOpenParts(rec.self_ty, rec.args)) {
            const settled_args = try self.gpa.alloc(TypeId, rec.args.len);
            defer self.gpa.free(settled_args);
            for (rec.args, settled_args) |argument, *settled| settled.* = try self.builder.resolveOpen(argument, &self.open_types);
            const settled_self = try self.builder.resolveOpen(rec.self_ty, &self.open_types);
            if (try self.builder.implementationChoiceWithin(self.generic, trait, settled_args, settled_self) != null) return;
        }

        try reportMissingImplementation(
            self.gpa,
            self.sink,
            self.ast,
            &self.builder,
            trait,
            rec.args,
            rec.self_ty,
            self.ast.fileOfExpr(id),
            self.ast.exprSpan(id),
            try self.unmetLabel(.{ .otherwise = "", .another_value = "settle them to ones that are" }, try self.editFor(trait, rec.args, rec.self_ty, false, 0)),
        );
    }

    fn inherentReceiver(self: *Checker, d: node.DeclId, held: TypeId) !TypeId {
        const implementation = self.builder.view().implementationIdOf(d) orelse return held;
        var receiver = held;
        while (true) {
            if (try self.builder.implementationArgumentsWithin(self.generic, implementation, &.{}, receiver) != null) return receiver;
            receiver = switch (self.builder.get(receiver)) {
                .borrow => |observation| observation.referent,
                else => return held,
            };
        }
    }

    fn operationReceiver(self: *Checker, d: node.DeclId, held: TypeId, args: []const TypeId) !TypeId {
        const params = self.ast.declParams(d);
        if (params.len == 0 or !readsSelf(self.ast, params[0])) return held;
        const trait = self.traitDeclaring(d) orelse return held;
        var receiver = held;
        while (true) {
            if (try self.builder.implementationChoiceWithin(self.generic, trait, args, receiver)) |choice| return choice.receiver;
            receiver = switch (self.builder.get(receiver)) {
                .borrow => |observation| observation.referent,
                else => return held,
            };
        }
    }

    fn settledSelf(
        self: *Checker,
        id: ExprId,
        operation: node.DeclId,
        trait: TokenId,
        written: TypeId,
        at: Loc,
    ) std.mem.Allocator.Error!SelfSettlement {
        const held = try self.receiverType(written, self.literalSite(id));
        const declared_trait = traitAt(self.ast, self.res, trait);
        const has_trait_arguments = if (declared_trait) |declared| self.ast.declTypeParams(declared).len != 0 else false;
        const receiver = if (has_trait_arguments) held else try self.operationReceiver(operation, held, &.{});
        if (!has_trait_arguments and !try self.discharges(receiver, trait, &.{})) {
            try self.reportSelfUnimplemented(at, trait, held);
            return .{ .ty = .poison };
        }

        // The trait's declaration and what settled `Self`, for lowering to
        // resolve. The type rather than the implementation: a call inside a
        // generic body settles `Self` to a type parameter, and which
        // implementation that is is not known until the body is instantiated.
        // The declaration rather than the token, because which trait a name
        // reaches is settled here and asking again there is a second answer.
        if (traitAt(self.ast, self.res, trait)) |declared| {
            const implementation = self.call_impls.items.len;
            try self.call_impls.append(self.gpa, .{
                .call = @intCast(id.index()),
                .trait = @intCast(declared.index()),
                .self_ty = receiver,
            });
            return .{ .ty = receiver, .implementation = implementation };
        }
        return .{ .ty = receiver };
    }

    /// The type a receiver, or a `match`'s scrutinee, is looked up by. What
    /// an operation or a field reaches, and what a match's arms compare,
    /// depends on the head, so one that is itself an open integer, through
    /// any observation of it, takes the default type here. An open integer
    /// inside a known head, `Range[open]`, stays open where nothing has
    /// settled it yet: the head decides what is reached, a trait query over
    /// the open key answers only where every integer type does, and the
    /// call's arguments settle the rest, as they settle a generic function's
    /// parameters. One something already settled is read as what it settled
    /// to, so the call is keyed by the type it has.
    fn receiverType(self: *Checker, t: TypeId, at: open_types_mod.Site) std.mem.Allocator.Error!TypeId {
        var head = t;
        while (true) switch (self.builder.get(head)) {
            .open_integer, .open_type => return self.forceInteger(t, at),
            .borrow => |observation| head = observation.referent,
            else => return self.builder.resolveOpen(t, &self.open_types),
        };
    }

    /// A trait operation reached at a `Self` that does not implement its trait.
    fn reportSelfUnimplemented(self: *Checker, at: Loc, trait: TokenId, held: TypeId) std.mem.Allocator.Error!void {
        const trait_decl = traitAt(self.ast, self.res, trait) orelse .none;
        try self.reportUnmet(
            at.file,
            at.span,
            unmet_self_help,
            "`{s}` requires `Self` to implement it, and `{s}` does not",
            .{ self.ast.tokenText(trait), (try self.typeName(held)) },
            trait_decl,
            &.{},
            held,
        );
    }

    /// How many type parameters the declaration a token names takes.
    fn paramCountOf(self: *const Checker, m: ModuleId, owner: node.DeclId, tok: TokenId) u32 {
        const d = self.declOfType(m, owner, tok) orelse return 0;
        return @intCast(self.ast.declTypeParams(d).len);
    }

    /// How many arguments a written type must give the declaration a token
    /// names: its parameters before the first default.
    fn requiredParamCountOf(self: *const Checker, m: ModuleId, owner: node.DeclId, tok: TokenId) u32 {
        const d = self.declOfType(m, owner, tok) orelse return 0;
        return self.ast.declRequiredTypeParams(d);
    }

    /// The declaration a written type names, by index, or null where it names
    /// a builtin, a type parameter or nothing. An alias is the declaration its
    /// name reaches; what it stands for is `aliasedType`'s to say.
    ///
    /// Read from what the resolver bound at the token rather than looked up
    /// by name again: a type parameter spelled like a module's type is the
    /// parameter there, and a second lookup by name found the type instead.
    fn declOfType(self: *const Checker, m: ModuleId, owner: node.DeclId, tok: TokenId) ?node.DeclId {
        if (tok == .none) return null;
        if (self.ast.tokenTag(tok) != .identifier) return null;
        if (m == .none) return null;

        const b = self.res.writtenAt(self.writtenAs(owner, tok));
        if (b == BindingId.none) return null;
        return switch (self.res.kindOf(b)) {
            .declared_type, .type_alias => self.res.declaredBy(b),
            else => null,
        };
    }

    /// The declaration a written type names, by index, however its name was
    /// written: a word this module holds, or a word after the name of the
    /// module holding it. Null where it names a builtin, a parameter or
    /// nothing.
    ///
    /// One routine, because everything asking this asks it of the type rather
    /// than of the spelling -- what a declaration holds, what it instantiates,
    /// and which type an annotation is.
    fn declOfWritten(
        self: *const Checker,
        m: ModuleId,
        owner: node.DeclId,
        ref: node.TypeRef,
    ) ?node.DeclId {
        if (self.qualifiedTypeName(ref)) |at| {
            const d = self.declaredThroughModule(at) orelse return null;
            return d;
        }
        if (ref.kind == .selection) return null;
        return self.declOfType(m, owner, ref.name);
    }

    /// The type a name written after a module's name reaches, as its
    /// declaration. Null where it reaches nothing, or reaches something that
    /// is not a type -- the resolver reports both.
    ///
    /// Read off what that pass settled: the crossing is checked there, and a
    /// second lookup here is the answer that could come apart from it.
    fn declaredThroughModule(self: *const Checker, at: TokenId) ?node.DeclId {
        const named = self.res.writtenAt(at);
        if (named == BindingId.none) return null;
        const kind = self.res.kindOf(named);
        if (kind != .declared_type and kind != .type_alias) return null;
        return self.res.declaredBy(named);
    }

    /// The head an implementation applies its own parameters to, where `tok`
    /// is a `Self` written inside one of its members.
    ///
    /// `Self` is the head the implementation names, and a head applying
    /// arguments is an instantiation with those arguments free -- `Holder[T]`,
    /// not `Holder`. Read off what the implementation recorded, so the head at
    /// the `impl`, the receiver a call binds against and a `Self` in a member
    /// are one type rather than three readings of one spelling.
    ///
    /// Null everywhere else, including a head applying nothing: there the
    /// constructor is the whole type and the lookup below already answers it.
    ///
    /// **Bound:** one index into the row an implementation's member records.
    fn selfAppliedHere(self: *const Checker, owner: node.DeclId, tok: TokenId) ?TypeId {
        if (!namesSelf(self.ast, tok)) return null;
        if (owner == self.symbolic_self_owner or self.ast.declIsSignature(owner)) return null;

        _ = self.implEnclosing(owner) orelse return null;

        // The head applies arguments, so `Self` is the instantiation and never
        // the constructor. Where nothing was recorded for the implementation
        // its head or its trait named nothing, which is reported where it is
        // written -- and reading `Self` as the constructor there asks a member
        // that wrote `Self` correctly for the arguments it did not omit.
        return (self.enclosingRow(owner) orelse return .poison).ty;
    }

    /// The token a written type is looked up under.
    ///
    /// Every token is itself but `Self`, which is the type the implementation
    /// that wrote it names. It is a type name rather than a receiver: it sits
    /// in an ordinary parameter position, and what it stands for is decided
    /// where the parameter is written rather than at any call.
    ///
    /// Whose `Self` it is, is the declaration the annotation was written in --
    /// which is not the one being walked. Read against the walk, a callee's
    /// `Self` meant the caller's `impl`, so one type's constructor called from
    /// inside another's returned the caller's type.
    ///
    /// A signature's stands for whatever implements the trait, which no token
    /// names: a signature has no body, so there is nothing to resolve it
    /// against until a call settles it.
    fn writtenAs(self: *const Checker, owner: node.DeclId, tok: TokenId) TokenId {
        if (!namesSelf(self.ast, tok)) return tok;
        if (owner == node.DeclId.none) return tok;
        if (self.ast.declIsSignature(owner)) return tok;

        const of = self.ast.declOwner(owner);
        return if (of == TokenId.none) tok else of;
    }

    /// A type named in `m`, which is not always the module being checked.
    ///
    /// A signature is written in the module that declares it, so its types are
    /// looked up there. Reading a callee's return type in the caller's module
    /// finds nothing, and nothing is poison -- which is not a diagnosis, it is
    /// a type that quietly infects everything the call touches.
    fn typeOfTokenIn(self: *const Checker, m: ModuleId, tok: TokenId) TypeId {
        return self.typeOfTokenOf(m, self.generic, tok);
    }

    /// A type parameter a written name reaches: what it stands for, and what
    /// was written on it.
    ///
    /// Both, because a name reaching a parameter is one lookup and two
    /// questions -- which type it is, and what its bounds promise -- and
    /// finding it twice is two answers to which parameter a name reaches.
    const Parameter = struct { ty: TypeId, written: node.TypeParam };

    fn typeParamSlotKey(owner: node.DeclId, name: StringId) u64 {
        return (@as(u64, owner.index()) << 32) | @intFromEnum(name);
    }

    fn indexTypeParams(self: *Checker) std.mem.Allocator.Error!void {
        try self.type_param_slots.ensureTotalCapacity(self.gpa, @intCast(self.ast.type_params.len));
        for (0..self.ast.declCount()) |i| {
            const owner = node.DeclId.at(@intCast(i));
            for (self.ast.declTypeParams(owner), 0..) |parameter, position| {
                const entry = self.type_param_slots.getOrPutAssumeCapacity(
                    typeParamSlotKey(owner, self.ast.tokenName(parameter.name)),
                );
                if (!entry.found_existing) entry.value_ptr.* = @intCast(position);
            }
        }
    }

    /// A type named in `m`, with `owner`'s type parameters in scope.
    ///
    /// The owner is passed rather than read from the walk, because a
    /// signature is written in the declaration that declares it: reading a
    /// callee's parameter type from the caller would look for the callee's
    /// `T` among the caller's, find nothing, and poison a call that was fine.
    /// The type a declaration's own parameter of that name stands for.
    fn parameterOf(self: *const Checker, owner: node.DeclId, tok: TokenId) ?Parameter {
        const at = owner.index();
        if (at >= self.param_types.len) return null;

        const k = self.type_param_slots.get(typeParamSlotKey(owner, self.ast.tokenName(tok))) orelse return null;
        const params = self.ast.declTypeParams(owner);
        if (k >= params.len or k >= self.param_types[at].len) return null;
        return .{ .ty = self.param_types[at][k], .written = params[k] };
    }

    /// The type parameter a written name reaches from inside `owner`.
    ///
    /// A parameter of the declaration being read answers first. It is the
    /// nearest thing of that name, and a module-level type sharing it is not
    /// what an annotation inside a generic declaration means. A signature is
    /// written inside a trait, whose parameters are in scope in it, and its
    /// own answer comes first there too: a signature may be generic on its own
    /// account, and both lists stand in the same place.
    fn headParameter(self: *const Checker, owner: node.DeclId, tok: TokenId) ?Parameter {
        if (owner == node.DeclId.none) return null;
        if (self.parameterOf(owner, tok)) |p| return p;
        if (!self.ast.declIsSignature(owner)) {
            // A member of an implementation generic over its head reads the
            // parameters that head applies: `Self` and the head written out
            // longhand are one type, so the name in the second stands for what
            // the first is applied to.
            const impl = self.implEnclosing(owner) orelse return null;
            return self.parameterOf(impl, tok);
        }

        const trait = self.traitDeclaring(owner) orelse return null;
        return self.parameterOf(trait, tok);
    }

    /// The implementation a declaration is a member of, or null where none is.
    ///
    /// The resolver's relation, which is the one that says it: an
    /// implementation the collection below recorded nothing for still encloses
    /// its members, and its head is still what they were written against.
    fn implEnclosing(self: *const Checker, d: node.DeclId) ?node.DeclId {
        const impl = self.res.implEnclosing(d);
        return if (impl == node.DeclId.none) null else impl;
    }

    /// What was recorded for the implementation a declaration is a member of.
    ///
    /// One index: the relation above followed by the row, filled once where
    /// the implementations are collected.
    fn enclosingRow(self: *const Checker, d: node.DeclId) ?types_mod.Implementation {
        if (d == node.DeclId.none) return null;
        if (d.index() >= self.impl_of_decl.len) return null;
        const row = self.impl_of_decl[d.index()];
        if (row == impl_of_none) return null;
        return self.implementations[row];
    }

    /// The trait a signature is written in.
    fn traitDeclaring(self: *const Checker, sig: node.DeclId) ?node.DeclId {
        return self.res.signatures.traitOf(self.ast, sig);
    }

    fn typeOfTokenOf(
        self: *const Checker,
        m: ModuleId,
        owner: node.DeclId,
        tok: TokenId,
    ) TypeId {
        if (tok == .none) return .poison;

        if (owner == self.symbolic_self_owner and namesSelf(self.ast, tok)) {
            return self.self_at_call orelse .poison;
        }

        // A builtin is its own type, and `Self` inside an implementation for
        // one names it -- so the question is asked of what the token stands
        // for rather than of the token. Asked here because there is no
        // declaration to reach: the lookup below answers with what a module
        // declared, and no module declares a builtin.
        const written = self.writtenAs(owner, tok);
        // `()` is Unit written out, and its token is the `(` that opens it --
        // punctuation, so it names nothing and no lookup answers for it.
        if (self.ast.tokenTag(written) == .l_paren) return .unit;
        if (self.res.builtinNamed(m, self.ast.tokenName(written))) |t| return t;
        if (self.ast.tokenTag(tok) != .identifier) return .poison;

        // A signature's `Self` is settled by the call reaching it, and only
        // there: a signature has no body, so this is the one place a written
        // `Self` stands for a type that no token in the declaration names.
        if (self.self_at_call) |held| {
            if (self.ast.declIsSignature(owner)) {
                if (namesSelf(self.ast, tok)) return held;
            }
        }

        // A parameter in scope answers before anything a module declared, and
        // through the one lookup that decides which parameter a name reaches.
        if (self.headParameter(owner, tok)) |p| return p.ty;

        // Which declaration a name means is the resolver's question, and it
        // answered it for every name this module can write -- its own, what it
        // re-exported, and what the prelude gave it. Rescanning declarations
        // here found the first of those and silently missed the rest, so a
        // re-exported type read as poison and every check about it was
        // skipped. Through the one routine that asks, so a type read here and
        // a parameter count read there cannot disagree about which
        // declaration a name reached.
        const d = self.declOfType(m, owner, tok) orelse return .poison;
        if (self.ast.declTag(d) == .alias) return self.settledAlias(d) orelse .poison;
        return self.type_of_decl.get(d);
    }

    /// Reports every cycle among the types' inline parts, breaking each.
    ///
    /// Breaking is not tidying. A diagnosed type is still in the pool, and
    /// every pass below here asks for a layout; one that cannot terminate does
    /// not stop being asked because it was reported.
    fn reportLayoutCycles(self: *Checker, type_of_decl: types_mod.Returns) !void {
        // Each recovery removes at least one inline edge and adds none, so
        // the finite graph bounds the number of iterations.
        while (true) {
            const cycle = (try self.builder.firstCycle(self.gpa)) orelse return;
            defer self.gpa.free(cycle.path);

            try self.reportCycle(cycle, type_of_decl);
            self.breakCycle(cycle);
        }
    }

    /// Only an explicit copyable policy promises conditional duplication.
    /// Open parameters are permitted; a known noncopyable owned part is not.
    fn reportCopyabilityDeclarations(self: *Checker, type_of_decl: types_mod.Returns) !void {
        var walking = type_of_decl.pairs();
        while (walking.next()) |each| {
            const d = each.id;
            const t = each.value;
            if (t == .poison or self.ast.declOwnershipPolicy(d) != .copyable) continue;
            const count = self.builder.fieldCount(t);
            var failed: ?struct { ty: TypeId, at: TokenId } = null;
            switch (self.builder.get(t)) {
                .struct_ => {
                    const declared = self.ast.declFields(d);
                    for (0..count) |i| {
                        const part = self.builder.fieldType(t, @intCast(i));
                        if (!try self.builder.knownNoncopyable(part)) continue;
                        failed = .{ .ty = part, .at = if (i < declared.len) declared[i].name else self.ast.declName(d) };
                        break;
                    }
                },
                .enum_ => |sum| outer: {
                    const declared = self.ast.declVariants(d);
                    for (0..sum.variant_count) |i| {
                        const variant_at = sum.first_variant + i;
                        const first = self.builder.variants.items(.first_field)[variant_at];
                        const len = self.builder.variants.items(.field_count)[variant_at];
                        for (self.builder.fields.items(.ty)[first..][0..len]) |part| {
                            if (!try self.builder.knownNoncopyable(part)) continue;
                            failed = .{ .ty = part, .at = if (i < declared.len) declared[i].name else self.ast.declName(d) };
                            break :outer;
                        }
                    }
                },
                .newtype => |nominal| {
                    if (try self.builder.knownNoncopyable(nominal.base)) failed = .{ .ty = nominal.base, .at = self.ast.declReturnRef(d).at };
                },
                else => {},
            }
            const bad = failed orelse continue;
            try self.sink.addErrorFmt(
                .o_universe,
                self.ast.fileOf(bad.at),
                self.ast.tokenSpan(bad.at),
                "remove `copyable`, or hold a copyable part",
                "a copyable declaration owns `{s}`, which cannot be copied",
                .{(try self.typeName(bad.ty))},
            );
        }
    }

    fn reportCycle(self: *Checker, cycle: Cycle, type_of_decl: types_mod.Returns) !void {
        // The cycle rather than the category: a reader has to know which edge
        // to break, and "recursive type" does not say.
        var how: std.ArrayList(u8) = .empty;
        defer how.deinit(self.gpa);
        try how.appendSlice(self.gpa, (try self.typeName(cycle.path[0])));
        if (cycle.path.len == 1) {
            try how.appendSlice(self.gpa, " contains itself");
        } else {
            for (cycle.path[1..]) |t| {
                try how.appendSlice(self.gpa, " contains ");
                try how.appendSlice(self.gpa, (try self.typeName(t)));
            }
            try how.appendSlice(self.gpa, " contains ");
            try how.appendSlice(self.gpa, (try self.typeName(cycle.path[0])));
        }

        // The declaration the cycle's first type came from. An instantiation
        // was written by substitution and has no source of its own, so what a
        // reader is pointed at is the declaration it instantiates -- which is
        // the text they can change.
        const declared: ?node.DeclId = if (self.builder.instanceOf(cycle.path[0])) |i|
            i.decl
        else blk: {
            var walking = type_of_decl.pairs();
            while (walking.next()) |each| {
                if (each.value == cycle.path[0]) break :blk each.id;
            }
            break :blk null;
        };

        const at: Loc = if (declared) |d|
            .{ .file = self.ast.fileOfDecl(d), .span = self.ast.declNameSpan(d) }
        else
            .{ .file = self.program.source.primaryFile(), .span = Span.empty };

        try self.sink.addErrorFmt(
            .t_infinite_layout,
            at.file,
            at.span,
            "a value of this type would have to hold one, so it has no size",
            "{s}",
            .{try how.toOwnedSlice(self.gpa)},
        );
    }

    /// Poisons every copy of an owning edge in the cycle, so a layout can be computed.
    ///
    /// The edge broken leaves a declared type wherever the cycle has one. An
    /// instantiation's parts are filled again from its template once every
    /// implementation has settled what it declares, which would restore an
    /// edge broken there and report the cycle a second time. An array is
    /// interned, so its element type is shared by every other use of it and
    /// its edge is never the one. A cycle of instantiations alone breaks at
    /// the last of them.
    fn breakCycle(self: *Checker, cycle: Cycle) void {
        var edge: ?usize = null;
        var at = cycle.path.len;
        while (at > 0) {
            at -= 1;
            if (self.builder.get(cycle.path[at]) == .array) continue;
            if (edge == null) edge = at;
            if (self.builder.instanceOf(cycle.path[at]) == null) {
                edge = at;
                break;
            }
        }
        const last = cycle.path[edge.?];
        const back = cycle.path[(edge.? + 1) % cycle.path.len];

        switch (self.builder.get(last)) {
            .newtype => {
                if (self.builder.baseOf(last) == back) self.builder.setNewtypeBase(last, .poison);
                return;
            },
            else => {},
        }

        for (0..self.builder.fieldCount(last)) |i| {
            if (self.builder.fieldType(last, @intCast(i)) != back) continue;
            self.builder.setFieldType(last, @intCast(i), .poison);
        }
        for (0..self.builder.variantCount(last)) |i| {
            for (0..self.builder.variantFieldCount(last, @intCast(i))) |f| {
                if (self.builder.variantFieldType(last, @intCast(i), @intCast(f)) != back) continue;
                self.builder.setVariantFieldType(last, @intCast(i), @intCast(f), .poison);
            }
        }
    }

    test "a cycle through an instantiation is reported once" {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        _ = try typingOf(gpa,
            \\struct Wrap[T] { inner: T }
            \\struct Node { next: Wrap[Node] }
            \\enum Tree { Leaf, Branch(Wrap[Tree]) }
            \\fn _keep(_n: Node, _t: Tree) -> UInt8 { 1 }
            \\fn main() -> UInt8 { 0 }
            \\
        , &sink);
        var node_reports: usize = 0;
        var tree_reports: usize = 0;
        for (sink.items()) |diagnostic| {
            if (diagnostic.code != .t_infinite_layout) continue;
            if (std.mem.indexOf(u8, diagnostic.message, "Node") != null) node_reports += 1;
            if (std.mem.indexOf(u8, diagnostic.message, "Tree") != null) tree_reports += 1;
        }
        try testing.expectEqual(@as(usize, 1), node_reports);
        try testing.expectEqual(@as(usize, 1), tree_reports);
    }

    fn setBindingType(self: *Checker, binding: BindingId, ty: TypeId) void {
        self.binding_types.set(binding, ty);
        self.binding_owners[binding.index()] = self.generic;
    }

    fn prepareValueQueries(self: *Checker, prepare_completions: bool) !void {
        for (self.expression_owners, 0..) |owner, index| {
            const expression = ExprId.at(@intCast(index));
            try self.builder.prepareCapabilityWithin(owner, self.builder.exprType(expression));
            // Completion and import fixes query the receiver of a written
            // selection, including a selection whose field name is incomplete.
            // Other values need ownership capabilities, not every possible
            // implementation's substituted argument types.
            if (prepare_completions and self.ast.exprTag(expression) == .field) {
                const receiver = self.ast.unaryOperand(expression);
                try self.builder.prepareLookupWithin(self.expression_owners[receiver.index()], self.builder.exprType(receiver));
            }
        }
        // Completion at a written type's dot, finished or not, lists what the
        // checked base answers. A parameter's written type is read before
        // implementation predicates are installed, which clears every
        // prepared lookup, so the bases are prepared here, after the last
        // clear. Once per recorded dot.
        if (prepare_completions) {
            var selections = self.type_selections.valueIterator();
            while (selections.next()) |selection| try self.builder.prepareLookupWithin(selection.owner, selection.base);
        }
        for (self.binding_owners, 0..) |owner, index| {
            const binding = BindingId.at(@intCast(index));
            const ty = self.binding_types.get(binding);
            try self.builder.prepareCapabilityWithin(owner, ty);
            // A binding that owns a value it must settle may be reported as
            // left unsettled, and the report names the operations that would
            // settle it. Whether an implementation under the type's head
            // applies to it is the lookup's answer, so those rows are prepared
            // here, where the lookup can run. A `read` parameter lends its
            // value and never owns it, so nothing is prepared for one.
            //
            // The cost is the rows under the type's own head, once per
            // (lookup scope, type) an owning binding holds, however many
            // bindings hold it; blanket and default rows are never walked.
            // Each row substitutes its trait arguments for the type, so the
            // bound is what that type's family implements, times the distinct
            // owned types each scope declares. A generic `impl` whose `self`
            // is read therefore prepares nothing for its receiver, however
            // many implementations its head carries.
            if (ty == .poison or self.res.parameterConvention(self.ast, binding) == .read) continue;
            if (!try self.builder.mustConsumeWithin(owner, ty)) continue;
            try self.builder.prepareHeadLookupWithin(owner, ty);
            try self.prepareSettlingResults(owner, ty);
        }
        // An abandoned walk's help names what settles its iterator, as a leak
        // report does for a binding, so its type is prepared the same way.
        for (self.walk_helps.items) |help| {
            try self.builder.prepareHeadLookupWithin(help.owner, help.iter);
            try self.prepareSettlingResults(help.owner, help.iter);
        }
        // A trait's own signature has no receiver arguments to substitute, so
        // a report asks whether its result owes under the trait's bounds.
        // Those are prepared once per trait member.
        for (0..self.ast.declCount()) |index| {
            const trait = node.DeclId.at(@intCast(index));
            if (self.ast.declTag(trait) != .trait_) continue;
            var signatures = self.res.signatures.of(self.ast, trait);
            while (signatures.next()) |sig| {
                const returns = self.decl_returns.get(sig);
                if (returns != .poison) try self.builder.prepareCapabilityWithin(trait, returns);
            }
        }
    }

    /// Decides, for each operation the type of an owning binding declares
    /// that takes its receiver by `sink`, whether calling it leaves a result
    /// that still owes in `owner`: the result with the receiver's block
    /// arguments substituted. A leak report names an operation as settling
    /// the value only where this says the result owes nothing.
    ///
    /// An operation with bounds of its own is left undecided, which a report
    /// reads as owing: nothing here checks those bounds for the receiver.
    ///
    /// Costs the members the type's declaration holds, once per (owner,
    /// type); each answer is kept, so a second binding of the type in the
    /// same function reads it.
    fn prepareSettlingResults(self: *Checker, owner: DeclId, ty: TypeId) !void {
        const origin = self.builder.view().declOfType(ty) orelse return;
        var members = self.res.membersOfType(origin);
        while (members.next()) |b| {
            const sig = self.res.declaredBy(b);
            const params = self.ast.declParams(sig);
            if (params.len == 0 or params[0].convention != .sink) continue;
            if (declaresOwnBounds(self.constraints, sig)) continue;
            try self.builder.prepareSettlingResult(owner, ty, sig, self.decl_returns.get(sig));
        }
        try self.prepareTraitSettlingResults(owner, ty);
    }

    /// Decides, for each signature taking its receiver by `sink` in a trait
    /// an implementation under `ty`'s head or a blanket implementation may
    /// supply for `ty`, whether calling it on `ty` in `owner` leaves a result
    /// that still owes. The implementation that answers is the one a call
    /// selects, so a blanket `impl[I: Iterator] Sequence for I` answers
    /// `iterate` with the iterator itself, which is not settled by it.
    ///
    /// Costs the rows under `ty`'s head, which `prepareHeadLookupWithin`
    /// already decided, plus the program's blanket rows, and one lookup per
    /// sink signature of each row's trait. Once per (owner, type) that an
    /// owning binding or an abandoned walk holds, as `prepareSettlingResults`
    /// is. The blanket rows are not sized by `ty`: a program declaring many
    /// blanket implementations pays their number once per such pair.
    fn prepareTraitSettlingResults(self: *Checker, owner: DeclId, ty: TypeId) !void {
        const head = self.builder.headOf(ty);
        const heads = [_]types_mod.Head{ head, .parameter };
        const count: usize = if (head == .parameter) 1 else 2;
        for (heads[0..count]) |under| {
            var rows = self.builder.impl_index.membersOfHead(under);
            while (rows.next()) |at| {
                const row = self.builder.implementations[at];
                if (!row.ofATrait() or !row.valid_key or !row.head.same(under)) continue;
                var signatures = self.res.signatures.of(self.ast, DeclId.at(row.trait));
                while (signatures.next()) |sig| {
                    const params = self.ast.declParams(sig);
                    if (params.len == 0 or params[0].convention != .sink) continue;
                    if (declaresOwnBounds(self.constraints, sig)) continue;
                    try self.builder.prepareTraitSettlingResult(owner, ty, @enumFromInt(at), sig);
                }
            }
        }
    }

    /// Replaces every open integer type the checker recorded with the type
    /// it settled on. Every body has fallen back by now; a variable created
    /// outside any body falls back here. The type pool itself is left alone:
    /// resolving a type mints its settled form rather than editing it.
    fn resolveAllOpen(self: *Checker) std.mem.Allocator.Error!void {
        // A value named outside every body is read here, once what named it
        // has been checked.
        try self.closeScope(.{ .open = .{ .start = 0 }, .values = 0 });
        self.open_types.fallbackAll(TypeId.literal_default);
        try self.checkSettledRanges();
        // A closure's environment record is minted while its captures may be
        // open, and it is laid out from its fields, so their types are
        // resolved where they are stored. Each record belongs to one closure
        // and is never interned, so editing it in place changes no other type.
        for (self.closure_descriptors) |descriptor| {
            const t = descriptor.environment;
            const shape = switch (self.builder.get(t)) {
                .struct_ => |shape| shape,
                else => continue,
            };
            var field: u32 = 0;
            while (field < shape.field_count) : (field += 1) {
                const held = self.builder.fields.items(.ty)[shape.first_field + field];
                if (!try self.builder.mentionsOpen(held)) continue;
                self.builder.setFieldType(t, field, try self.builder.resolveOpen(held, &self.open_types));
            }
        }
        const Resolve = struct {
            checker: *Checker,
            pub fn map(ctx: @This(), t: TypeId) std.mem.Allocator.Error!TypeId {
                return ctx.checker.builder.resolveOpen(t, &ctx.checker.open_types);
            }
        };
        const ctx: Resolve = .{ .checker = self };
        inline for (std.meta.fields(Checker)) |field| {
            if (comptime std.mem.eql(u8, field.name, "builder") or std.mem.eql(u8, field.name, "open_types")) continue;
            try open_types_mod.rewriteTypeIds(ctx, &@field(self, field.name));
        }
        inline for (.{ "expr_types", "construction_types", "closure_descriptors", "implementation_selections", "decl_returns" }) |name| {
            try open_types_mod.rewriteTypeIds(ctx, &@field(self.builder, name));
        }
        // Prepared lookups are left as they are: an answer is derived from
        // its key, so a concrete key holds a concrete answer, and a key that
        // mentions an open type is never asked again once every recorded type
        // is resolved. Their argument vectors are also interned set keys,
        // which an in-place rewrite would invalidate.
        for (self.builder.expr_types.items, 0..) |t, at| if (try self.builder.mentionsOpen(t)) {
            const span = self.ast.exprSpan(ExprId.at(@intCast(at)));
            std.debug.panic("compiler defect: an open integer type survived type checking at bytes {d}..{d}", .{ span.start, span.end });
        };
    }

    /// Reports each value folded while its type was open that its final type
    /// cannot hold, where the value was written and labelled where the type
    /// was chosen. Checked once every variable has its final type, so
    /// settling, joining and falling back all reach it.
    fn checkSettledRanges(self: *Checker) std.mem.Allocator.Error!void {
        // An argument checked in both passes of a call queues its value twice;
        // one site is reported once.
        var reported: std.AutoHashMapUnmanaged(ExprId, void) = .empty;
        defer reported.deinit(self.gpa);
        for (self.open_types.pending.items) |waiting| {
            const t = self.open_types.settled(waiting.v).?;
            if (self.integerLiteralFits(t, waiting.value)) continue;
            if ((try reported.getOrPut(self.gpa, waiting.expr)).found_existing) continue;
            self.folds.set(waiting.expr, .absent);
            switch (waiting.rule) {
                .literal, .negation => {
                    const message = try std.fmt.allocPrint(self.gpa, "`{s}` cannot hold {d}", .{ (try self.typeName(t)), waiting.value });
                    const primary = if (waiting.rule == .literal) "literal is out of range for its type" else "value is out of range for its type";
                    _ = self.reportWithOrigin(.t_literal, waiting.expr, message, primary, try self.chosenLabel(waiting.v));
                },
                .operation => _ = self.reportAtOp(
                    .t_overflow,
                    waiting.expr,
                    "this operation overflows `{s}`",
                    .{(try self.typeName(t))},
                    "the result is not representable",
                ),
            }
        }
    }

    /// Where an open integer's type was chosen: the use that settled it, or
    /// the operation that needed a type before any use did. A variable that
    /// fell back at the end of its body has no such place.
    fn chosenLabel(self: *Checker, v: u32) std.mem.Allocator.Error!?Label {
        const chosen = self.open_types.origin(v) orelse return null;
        const t = self.open_types.settled(v).?;
        return .{
            .file = chosen.site.file,
            .span = chosen.site.span,
            .message = if (chosen.forced)
                try std.fmt.allocPrint(self.gpa, "fell back to `{s}` here, where an operation needed a type", .{(try self.typeName(t))})
            else
                try std.fmt.allocPrint(self.gpa, "settled to `{s}` here", .{(try self.typeName(t))}),
            .style = .secondary,
        };
    }

    /// A type an operation needs now. Every open integer inside it falls
    /// back to the default here, and the site is kept to label a later
    /// conflict with where the fallback happened.
    fn forceInteger(self: *Checker, t: TypeId, at: open_types_mod.Site) std.mem.Allocator.Error!TypeId {
        if (!try self.builder.mentionsOpen(t)) return t;
        try self.forceLeaves(t, at);
        return self.builder.resolveOpen(t, &self.open_types);
    }

    /// Falls back every open integer inside `t`, naming `at` as the reason
    /// where there is one. An open type has no fallback and stays open, unless
    /// it was joined with an open integer.
    fn forceLeaves(self: *Checker, t: TypeId, at: ?open_types_mod.Site) std.mem.Allocator.Error!void {
        if (!try self.builder.mentionsOpen(t)) return;
        switch (self.builder.get(t)) {
            .open_integer, .open_type => |v| return if (at) |site|
                self.open_types.forced(v, TypeId.literal_default, site)
            else
                self.open_types.fallback(v, TypeId.literal_default),
            else => {},
        }
        const Force = struct {
            checker: *Checker,
            at: ?open_types_mod.Site,
            pub fn part(force: *const @This(), inside: TypeId) std.mem.Allocator.Error!void {
                try force.checker.forceLeaves(inside, force.at);
            }
        };
        try self.builder.visitParts(t, &Force{ .checker = self, .at = at });
    }

    /// A fresh open integer type for a literal no expected type reached.
    fn openLiteral(self: *Checker) std.mem.Allocator.Error!TypeId {
        const v = try self.open_types.create(self.gpa);
        const t = try self.builder.openInteger(v);
        self.open_types.name(v, t);
        return t;
    }

    fn literalSite(self: *const Checker, id: ExprId) open_types_mod.Site {
        return .{ .file = self.ast.fileOfExpr(id), .span = self.ast.exprSpan(id) };
    }

    /// Whether two types agree once open types are settled or joined.
    /// Settling is equality: an open integer takes an integer type, an open
    /// type takes any type, and two open variables become one. Nothing
    /// converts.
    fn meet(self: *Checker, actual: TypeId, want: TypeId, at: ?open_types_mod.Site) std.mem.Allocator.Error!bool {
        const a = try self.builder.resolveOpen(actual, &self.open_types);
        const w = try self.builder.resolveOpen(want, &self.open_types);
        // An open type abandoned after a report agrees with everything.
        if (a == w or a == .poison or w == .poison) return true;
        const av = self.openVariable(a);
        const wv = self.openVariable(w);
        if (av != null and wv != null) return self.open_types.join(av.?, wv.?) != .conflict;
        if (av) |v| return self.settleOpen(v, w, at);
        if (wv) |v| return self.settleOpen(v, a, at);
        if (!(try self.builder.mentionsOpen(a)) and !(try self.builder.mentionsOpen(w))) return false;
        return self.meetStructurally(a, w, at);
    }

    /// The variable `t` stands for, where it is an open integer or open type.
    fn openVariable(self: *const Checker, t: TypeId) ?u32 {
        return switch (self.builder.get(t)) {
            .open_integer, .open_type => |v| v,
            else => null,
        };
    }

    /// Two types of one shape agree where their parts do. The parts meet
    /// pairwise, and the two must then be one type, which also compares
    /// everything a part walk does not reach: a callable's conventions, an
    /// interpolation's formats.
    fn meetStructurally(self: *Checker, a: TypeId, w: TypeId, at: ?open_types_mod.Site) std.mem.Allocator.Error!bool {
        if (std.meta.activeTag(self.builder.get(a)) != std.meta.activeTag(self.builder.get(w))) return false;
        // Refused before any part meets, so a mismatch settles nothing.
        if (self.builder.instanceOf(a)) |ai| {
            const wi = self.builder.instanceOf(w) orelse return false;
            if (ai.decl != wi.decl) return false;
        }
        const Collect = struct {
            gpa: std.mem.Allocator,
            parts: std.ArrayList(TypeId) = .empty,
            pub fn part(collect: *@This(), inside: TypeId) std.mem.Allocator.Error!void {
                try collect.parts.append(collect.gpa, inside);
            }
        };
        var of_a: Collect = .{ .gpa = self.gpa };
        defer of_a.parts.deinit(self.gpa);
        var of_w: Collect = .{ .gpa = self.gpa };
        defer of_w.parts.deinit(self.gpa);
        try self.builder.visitParts(a, &of_a);
        try self.builder.visitParts(w, &of_w);
        if (of_a.parts.items.len != of_w.parts.items.len) return false;
        for (of_a.parts.items, of_w.parts.items) |x, y| if (!try self.meet(x, y, at)) return false;
        return try self.builder.resolveOpen(a, &self.open_types) == try self.builder.resolveOpen(w, &self.open_types);
    }

    fn settleOpen(self: *Checker, v: u32, to: TypeId, at: ?open_types_mod.Site) std.mem.Allocator.Error!bool {
        if (self.open_types.isInteger(v)) {
            const is_integer = to.bounds() != null or self.builder.isIntegerWithin(self.generic, to);
            if (!is_integer) return false;
        } else if (to == .poison or to == .never or try self.mentionsVariable(to, self.open_types.find(v))) {
            // A type holding the variable it would settle is no type at all.
            return false;
        }
        return self.open_types.settle(v, to, at) != .conflict;
    }

    /// Whether `t` mentions the open variable whose root is `root`.
    fn mentionsVariable(self: *Checker, t: TypeId, root: u32) std.mem.Allocator.Error!bool {
        if (!try self.builder.mentionsOpen(t)) return false;
        if (self.openVariable(t)) |v| return self.open_types.find(v) == root;
        const Find = struct {
            checker: *Checker,
            root: u32,
            found: bool = false,
            pub fn part(find: *@This(), inside: TypeId) std.mem.Allocator.Error!void {
                if (!find.found and try find.checker.mentionsVariable(inside, find.root)) find.found = true;
            }
        };
        var find: Find = .{ .checker = self, .root = self.open_types.find(root) };
        try self.builder.visitParts(t, &find);
        return find.found;
    }

    /// Records the type of `id`. A poison type is a refusal: the checker built
    /// no value here. `recordMismatch` is the other way to record poison.
    fn record(self: *Checker, id: ExprId, t: TypeId) TypeId {
        if (t == .poison) {
            self.refused.put(self.gpa, id, {}) catch {};
        } else if (self.refused.count() != 0) _ = self.refused.remove(id);
        return self.recordType(id, t);
    }

    /// Records poison for a value that was built and does not fit the type its
    /// context expects, which the diagnostic has already named. It is not a
    /// refusal: the value exists, and what it takes or reads is unchanged.
    fn recordMismatch(self: *Checker, id: ExprId) TypeId {
        if (self.refused.count() != 0) _ = self.refused.remove(id);
        self.mismatched = id;
        return self.recordType(id, .poison);
    }

    fn recordType(self: *Checker, id: ExprId, t: TypeId) TypeId {
        self.expression_owners[id.index()] = self.generic;
        if (t == .poison) self.folds.set(id, .absent);
        self.builder.setExpr(id, t);
        return t;
    }

    /// Records that a node the definition admits has no value.
    ///
    /// It is a constant expression exactly where its operands are, so a
    /// failure over an operand that is not one leaves the node not one either
    /// -- and the program is told what is actually wrong with it rather than
    /// told twice about a value it never claimed to have.
    fn foldFailed(self: *Checker, id: ExprId, operands: []const ExprId) void {
        for (operands) |o| if (!self.folds.get(o).isConstant()) return;
        self.folds.set(id, .absent);
    }

    /// How a closure's invocation reads in a sentence: how it is declared, or
    /// how it is called. A `sink` closure is called once, which is worth
    /// saying of the call and reads oddly of the declaration.
    fn invocationSpelling(convention: node.Convention, side: enum { declared, called }) []const u8 {
        return switch (convention) {
            .read => "for reading",
            .inout => "`inout`",
            .sink => if (side == .called) "`sink`, once" else "`sink`",
        };
    }

    fn report(
        self: *Checker,
        code: Code,
        id: ExprId,
        comptime fmt: []const u8,
        args: anytype,
        label: []const u8,
    ) TypeId {
        const before = self.sink.items().len;
        self.sink.addErrorFmt(code, self.ast.fileOfExpr(id), self.ast.exprSpan(id), label, fmt, args) catch {};
        self.explainShadowedHead(id, before) catch {};
        return self.record(id, .poison);
    }

    /// Adds to the one diagnostic reported at the selection `id` since the
    /// sink held `before` that its head is a local shadowing an imported
    /// module, where the resolver recorded one: the writer may have meant the
    /// module, which an alias reaches.
    fn explainShadowedHead(self: *Checker, id: ExprId, before: usize) std.mem.Allocator.Error!void {
        if (!self.res.headShadowsAnImport(id)) return;
        const items = self.sink.mutableItems();
        if (items.len != before + 1) return;
        const reported = &items[before];

        const base = self.ast.unaryOperand(id);
        const head = self.ast.exprMain(base);
        const name = self.ast.tokenText(head);
        const arena = self.sink.arena;

        const path = self.importedPath(head) orelse name;
        const local = self.res.targetOf(base);
        const kind = if (local == BindingId.none) "binding" else shadowingKindName(self.res.kindOf(local));
        if (local != BindingId.none) {
            const declared = self.res.declaringToken(local);
            if (declared != TokenId.none) {
                const labels = try arena.alloc(Label, reported.labels.len + 1);
                @memcpy(labels[0..reported.labels.len], reported.labels);
                labels[reported.labels.len] = .{
                    .file = self.ast.fileOf(declared),
                    .span = self.ast.tokenSpan(declared),
                    .message = try std.fmt.allocPrint(arena, "this {s} `{s}` shadows `{s}`, the import of `{s}`", .{ kind, name, name, path }),
                    .style = .secondary,
                };
                reported.labels = labels;
            }
        }

        const notes = try arena.alloc([]const u8, reported.notes.len + 1);
        @memcpy(notes[0..reported.notes.len], reported.notes);
        notes[reported.notes.len] = try std.fmt.allocPrint(
            arena,
            "inside this scope `{s}` is the {s}, not the module; write `import {s} as` another name to reach the module here",
            .{ name, kind, path },
        );
        reported.notes = notes;
    }

    /// What a diagnostic calls a binding that shadows an import.
    fn shadowingKindName(kind: resolve_mod.Kind) []const u8 {
        return switch (kind) {
            .parameter => "parameter",
            .local => "local",
            .binder => "pattern binding",
            .capture => "capture",
            .type_parameter => "type parameter",
            else => "binding",
        };
    }

    /// The path of the import that binds the name `head` spells in its file.
    /// Costs one step per import the enclosing module writes.
    fn importedPath(self: *const Checker, head: TokenId) ?[]const u8 {
        const file = self.ast.fileOf(head);
        const writing = self.res.moduleOfFile(file);
        if (writing == .none) return null;
        const wanted = self.ast.tokenName(head);
        for (self.program.get(writing).imports) |imported| {
            if (imported.module == .none) continue;
            const binds = self.ast.declName(imported.decl);
            if (self.ast.fileOf(binds) != file or self.ast.tokenName(binds) != wanted) continue;
            return self.program.modulePath(imported.module);
        }
        return null;
    }

    /// Reports at the operator rather than the whole expression, which is
    /// where an arithmetic failure actually happened.
    fn reportAtOp(
        self: *Checker,
        code: Code,
        id: ExprId,
        comptime fmt: []const u8,
        args: anytype,
        label: []const u8,
    ) TypeId {
        const span = self.ast.tokenSpan(self.ast.exprMain(id));
        self.sink.addErrorFmt(code, self.ast.fileOfExpr(id), span, label, fmt, args) catch {};
        return self.record(id, .poison);
    }

    /// What a refused trait requirement's help offers besides the edit that
    /// would meet it. The label itself is chosen where the report is built,
    /// once the notes say which requirement an edit would have to meet.
    const UnmetHelp = struct {
        /// The alternative edit, such as dropping the bound, or empty.
        otherwise: []const u8,
        /// What to offer where no edit of the program can meet the
        /// requirement, or null where `otherwise` already says it.
        another_value: ?[]const u8,
    };

    /// The help a refused bound gives. Dropping the bound is offered only
    /// where the program wrote it: not in the library, and not in a
    /// declaration a derive generated.
    fn unmetBoundHelp(self: *Checker, bound_name: TokenId) UnmetHelp {
        const file = self.ast.fileOf(bound_name);
        const bound_module = self.res.moduleOfFile(file);
        const written = bound_module != .none and !self.program.get(bound_module).library and
            self.program.file_origins.get(file) == null;
        return .{ .otherwise = if (written) "drop the bound" else "", .another_value = "pass a value whose type implements it" };
    }

    /// The help a trait operation reached at a `Self` that does not
    /// implement the trait gives.
    const unmet_self_help: UnmetHelp = .{ .otherwise = "reach the operation on one that does", .another_value = null };

    /// The help an operator whose operand type does not implement the trait
    /// the operator calls gives.
    const unmet_operator_help: UnmetHelp = .{ .otherwise = "", .another_value = "compare values of a type that implements it" };

    /// The edit that would make a type meet a requirement, or why no edit of
    /// this program can.
    const Edit = union(enum) {
        edit: []const u8,
        refused: resolve_mod.ImplRefusal,
    };

    /// The label of a refused requirement: the edit `edit` names, or why
    /// there is none and what `help` offers instead.
    fn unmetLabel(self: *Checker, help: UnmetHelp, edit: Edit) std.mem.Allocator.Error![]const u8 {
        const sep: []const u8 = if (help.otherwise.len > 0) ", or " else "";
        switch (edit) {
            .edit => |text| return std.fmt.allocPrint(self.sink.arena, "{s}{s}{s}", .{ text, sep, help.otherwise }),
            .refused => |refusal| {
                if (refusal.instead orelse help.another_value) |instead|
                    return std.fmt.allocPrint(self.sink.arena, "{s}; {s}{s}{s}", .{ refusal.reason, instead, sep, help.otherwise });
                if (help.otherwise.len == 0) return refusal.reason;
                return std.fmt.allocPrint(self.sink.arena, "{s}; {s}", .{ refusal.reason, help.otherwise });
            },
        }
    }

    /// Who owns the type side of an implementation for `held`, read from
    /// the head the implementation index looks `held` up by. The heads the
    /// resolver admits are the heads that index records, so a type whose head
    /// no written `impl` produces, a closure's or an array's, is unnameable.
    fn implTypeSide(self: *const Checker, held: TypeId) resolve_mod.ImplTypeSide {
        return switch (self.builder.headOf(held)) {
            .applied => |d| .{ .declared = self.program.moduleOf(d) },
            .array => .unnameable,
            .borrow_, .callable_, .parameter, .default_ => .unowned,
            .whole => if (self.declaringType(held)) |d| .{ .declared = self.program.moduleOf(d) } else switch (self.builder.get(held)) {
                .integer, .boolean, .float, .never => .primitive,
                .unit, .parameter => .unowned,
                else => .unnameable,
            },
        };
    }

    /// The edit that would make `held` implement `trait` at `args`, naming
    /// only edits this program can make. `direct` says `held` is the type the
    /// report names, which the edit calls "that type"; otherwise the edit
    /// names the trait and the type.
    ///
    /// **Bound:** a closure's captures are followed `max_capture_depth`
    /// closures deep.
    fn editFor(self: *Checker, trait: node.DeclId, args: []const TypeId, held: TypeId, direct: bool, depth: u8) std.mem.Allocator.Error!Edit {
        const spelled = try self.builder.spellInstance(self.ast.tokenText(self.ast.declName(trait)), args);
        defer self.gpa.free(spelled);
        const trait_name = try self.sink.arena.dupe(u8, spelled);
        const type_name = try self.typeName(held);
        if (self.builder.get(held) == .parameter) return self.boundsEdit(trait_name, held);
        // A closure releases what it captures, so the edit is the one its
        // first capture that does not release needs.
        if (self.builder.closure_release) |release| if (release.trait == trait and depth < max_capture_depth) {
            if (try self.unreleasedCapture(held, trait)) |capture| {
                const prefix = try std.fmt.allocPrint(self.sink.arena, "it captures `{s}`; ", .{capture.name});
                return switch (try self.editFor(trait, args, capture.ty, false, depth + 1)) {
                    .edit => |text| .{ .edit = try std.mem.concat(self.sink.arena, u8, &.{ prefix, text }) },
                    .refused => |refusal| .{ .refused = .{ .reason = try std.mem.concat(self.sink.arena, u8, &.{ prefix, refusal.reason }), .instead = refusal.instead } },
                };
            }
        };
        const side = self.implTypeSide(held);
        if (side == .unnameable) return .{ .refused = try resolve_mod.implRefusal(self.sink.arena, side, type_name, trait_name) };
        // An implementation already matches and fails a requirement of its
        // own, which another implementation for the same type would overlap.
        if (try self.builder.unmetRequirement(trait, args, held)) |matching| {
            self.gpa.free(matching.args);
            return .{ .refused = .{
                .reason = try std.fmt.allocPrint(self.sink.arena, "another implementation of `{s}` for `{s}` would overlap the one that matches it", .{ trait_name, type_name }),
                .instead = null,
            } };
        }
        // The only modules that can own a side of the implementation are the
        // trait's and the type's, so the ownership rule is asked of each that
        // the program wrote.
        const trait_module = self.program.moduleOf(trait);
        var writers: [2]ModuleId = undefined;
        var count: usize = 0;
        const candidates = [_]ModuleId{ trait_module, if (side == .declared) side.declared else .none };
        for (candidates) |writer| {
            if (writer == .none or self.program.get(writer).library) continue;
            if (count == 1 and writers[0] == writer) continue;
            if (!resolve_mod.ownsAnImplSide(writer, false, side, trait_module)) continue;
            writers[count] = writer;
            count += 1;
        }
        if (count == 0) return .{ .refused = try resolve_mod.implRefusal(self.sink.arena, side, type_name, trait_name) };
        const what = if (direct)
            "implement it for that type"
        else
            try std.fmt.allocPrint(self.sink.arena, "implement `{s}` for `{s}`", .{ trait_name, type_name });
        for (writers[0..count]) |writer| if (writer == self.current) return .{ .edit = what };
        // The module being checked may not write it, so the edit says which
        // modules may.
        if (count == 1) return .{ .edit = try std.fmt.allocPrint(self.sink.arena, "{s} in `{s}`", .{ what, self.program.get(writers[0]).name }) };
        return .{ .edit = try std.fmt.allocPrint(self.sink.arena, "{s} in `{s}` or `{s}`", .{ what, self.program.get(writers[0]).name, self.program.get(writers[1]).name }) };
    }

    /// How many closures deep `editFor` follows a capture that does not
    /// release: a closure capturing a closure that captures one.
    const max_capture_depth = 4;

    /// The edit that would give `held` `capability`. Only a type this program
    /// declares can be changed, and a parameter gains it through its bounds.
    fn editForCapability(self: *Checker, capability: types_mod.CapabilityRequirement, held: TypeId) std.mem.Allocator.Error!Edit {
        const required: []const u8 = switch (capability) {
            .copyable => "Copyable",
            .discardable => "Discardable",
            .unrestricted => unreachable,
        };
        if (self.builder.get(held) == .parameter) return self.boundsEdit(required, held);
        const type_name = try self.typeName(held);
        // The attribute is written on the declaration, so it is named there,
        // without the arguments an instantiation supplies.
        // A declaration already marked is not `Copyable` here because of what
        // it was given, which marking it again does not change.
        if (capability == .copyable) if (self.declaringType(held)) |d| if (!self.declaredInLibrary(d) and self.ast.declOwnershipPolicy(d) != .copyable)
            return .{ .edit = try std.fmt.allocPrint(self.sink.arena, "mark `{s}` `@copyable`", .{self.ast.tokenText(self.ast.declName(d))}) };
        return .{ .refused = .{ .reason = try std.fmt.allocPrint(self.sink.arena, "`{s}` is not `{s}`", .{ type_name, required }), .instead = null } };
    }

    /// The edit that would make `held` `Owned`, where `seed` is the part its
    /// carrying path ends at. A parameter gains it through its bounds. No
    /// implementation can make a type `Owned`, because the bound is decided
    /// by what the type holds.
    fn editForOwned(self: *Checker, held: TypeId, seed: TypeId) std.mem.Allocator.Error!Edit {
        if (self.builder.get(seed) == .parameter) return self.boundsEdit("Owned", seed);
        return .{ .refused = .{ .reason = try std.fmt.allocPrint(self.sink.arena, "`{s}` is not `Owned`", .{try self.typeName(held)}), .instead = null } };
    }

    /// Inside a generic body a parameter meets what its bounds promise and
    /// nothing else, so the edit adds `required` to them. An associated type
    /// read through a parameter, `I.Item`, has no bound list of its own, and
    /// its declaration promises it in a `where` clause.
    fn boundsEdit(self: *Checker, required: []const u8, parameter: TypeId) std.mem.Allocator.Error!Edit {
        const name = try self.typeName(parameter);
        // A trait signature's `Self` is bounded by the trait's supertrait
        // list, which may not name `Owned`.
        if (self.builder.standinOf(parameter) == null and std.mem.eql(u8, name, "Self")) {
            if (std.mem.eql(u8, required, "Owned")) return .{ .refused = .{ .reason = "a trait's `Self` cannot be bounded `Owned`", .instead = null } };
            return .{ .edit = try std.fmt.allocPrint(self.sink.arena, "add `{s}` to the trait's supertraits", .{required}) };
        }
        if (self.builder.standinOf(parameter) == null)
            return .{ .edit = try std.fmt.allocPrint(self.sink.arena, "add `{s}` to `{s}`'s bounds", .{ required, name }) };
        // The clause that can promise it is the one of the declaration whose
        // parameter it is read through: an implementation's, for its own
        // parameter, which no member's clause may bound. A clause already
        // there takes one more predicate; a second `where` would not parse.
        const implementation = self.implementationOwning(parameter);
        const clause_of = implementation orelse self.generic;
        const has_clause = clause_of != .none and self.ast.declWhereToken(clause_of) != .none;
        const text = if (implementation != null)
            (if (has_clause)
                try std.fmt.allocPrint(self.sink.arena, "add `{s}: {s}` to the implementation's `where` clause", .{ name, required })
            else
                try std.fmt.allocPrint(self.sink.arena, "add `where {s}: {s}` to the implementation", .{ name, required }))
        else if (has_clause)
            try std.fmt.allocPrint(self.sink.arena, "add `{s}: {s}` to the `where` clause", .{ name, required })
        else
            try std.fmt.allocPrint(self.sink.arena, "add `where {s}: {s}`", .{ name, required });
        return .{ .edit = text };
    }

    /// The implementation whose parameter `subject`, an associated type read
    /// through a parameter, is read through; null where that parameter is
    /// not an implementation's.
    fn implementationOwning(self: *const Checker, subject: TypeId) ?node.DeclId {
        if (self.builder.standinOf(subject) == null) return null;
        var root = subject;
        while (self.builder.standinOf(root)) |standin| root = standin.held;
        const owner = switch (self.builder.get(root)) {
            .parameter => |p| p.owner,
            else => return null,
        };
        if (owner >= self.ast.declCount()) return null;
        const d = node.DeclId.at(@intCast(owner));
        return if (self.ast.declTag(d) == .impl_) d else null;
    }

    /// The first capture `held`, a closure, owns whose type does not
    /// implement `trait`, or null.
    fn unreleasedCapture(self: *Checker, held: TypeId, trait: node.DeclId) std.mem.Allocator.Error!?struct { name: []const u8, ty: TypeId } {
        const closure = switch (self.builder.get(held)) {
            .closure => |closure| closure,
            else => return null,
        };
        if (closure.environment == .unit) return null;
        const captures = self.res.closureCaptures(closure.closure);
        for (self.builder.closureOf(closure.closure).owned_fields) |field| {
            // A literal captured before its uses settled it names an open
            // integer, which reads as what it settled on.
            const ty = try self.builder.resolveOpen(self.builder.fieldType(closure.environment, field.index()), &self.open_types);
            if (try self.answersTrait(ty, trait)) continue;
            return .{ .name = self.ast.tokenText(self.res.captureNameToken(captures[field.index()].binding)), .ty = ty };
        }
        return null;
    }

    /// Reports that `held` does not implement `trait`, with a note naming the
    /// requirement of a matching implementation that its arguments fail:
    /// `Labelled[T]` implements `Equatable` when `T` does, and `Token` does
    /// not. Where that requirement is itself unmet through an implementation,
    /// the next note explains it, down to a type no implementation matches.
    /// A type no implementation's head matches gets no note.
    ///
    /// **Bound:** `unmet_requirement_depth` notes.
    fn reportUnimplemented(
        self: *Checker,
        file: FileId,
        span: Span,
        label: []const u8,
        comptime fmt: []const u8,
        fmt_args: anytype,
        trait: node.DeclId,
        trait_args: []const TypeId,
        held: TypeId,
    ) std.mem.Allocator.Error!void {
        return self.reportLabelled(file, span, label, fmt, fmt_args, trait, trait_args, held, null);
    }

    /// `reportUnimplemented` for a refused trait requirement, labelled with
    /// the edits `help` and the ownership rule leave this program. Where a
    /// note names a matching implementation's unmet requirement, implementing
    /// the trait again would overlap that implementation, so the label is
    /// about the deepest requirement the notes name.
    fn reportUnmet(
        self: *Checker,
        file: FileId,
        span: Span,
        help: UnmetHelp,
        comptime fmt: []const u8,
        fmt_args: anytype,
        trait: node.DeclId,
        trait_args: []const TypeId,
        held: TypeId,
    ) std.mem.Allocator.Error!void {
        return self.reportLabelled(file, span, "", fmt, fmt_args, trait, trait_args, held, help);
    }

    /// The report `reportUnimplemented` and `reportUnmet` both make: labelled
    /// `label`, or, given `help`, by `unmetLabel` once the notes are known.
    fn reportLabelled(
        self: *Checker,
        file: FileId,
        span: Span,
        label: []const u8,
        comptime fmt: []const u8,
        fmt_args: anytype,
        trait: node.DeclId,
        trait_args: []const TypeId,
        held: TypeId,
        help: ?UnmetHelp,
    ) std.mem.Allocator.Error!void {
        const labels = try self.sink.arena.alloc(Label, 1);
        var notes: std.ArrayList([]const u8) = .empty;
        var deepest: ?UnmetDeepest = null;
        _ = try self.unmetNotes(&notes, trait, trait_args, held, &deepest);
        const message = if (help) |offered| try self.unmetLabel(offered, if (deepest) |requirement| switch (requirement) {
            .trait => |unmet| try self.editFor(unmet.trait, unmet.args, unmet.held, false, 0),
            .capability => |unmet| try self.editForCapability(unmet.capability, unmet.held),
        } else try self.editFor(trait, trait_args, held, true, 0)) else label;
        labels[0] = .{ .file = file, .span = span, .message = message, .style = .primary };
        try self.callableHeadNotes(&notes, trait, trait_args, held);
        try self.sink.add(.{
            .severity = .err,
            .code = .t_bound,
            .message = try std.fmt.allocPrint(self.sink.arena, fmt, fmt_args),
            .labels = labels,
            .notes = notes.items,
        });
    }

    /// A callable type as a bound failure names it: with the names its
    /// parameters were declared with, so a contract reads as written rather
    /// than by position.
    fn heldName(self: *const Checker, held: TypeId) std.mem.Allocator.Error![]const u8 {
        if (self.builder.get(held) != .callable) return self.typeName(held);
        // Names are only worth printing where a contract refers to them; the
        // ones a signature carries are those it was first interned with, which
        // another function may have written.
        const signature = self.builder.get(held).callable;
        if (signature.contracts.len == 0) return self.typeName(held);
        const parameters = self.builder.callableParams(signature);
        const names = try self.gpa.alloc([]const u8, parameters.len);
        defer self.gpa.free(names);
        for (parameters, names) |parameter, *name| {
            if (parameter.spelling.len == 0) return self.typeName(held);
            name.* = parameter.spelling;
        }
        const text = try self.builder.view().spellCallable(self.gpa, held, names);
        defer self.gpa.free(text);
        return self.sink.arena.dupe(u8, text);
    }

    /// The conventions of a callable type's parameters before its trailing
    /// run of `read` parameters, as `inout, sink`, and how long that run is.
    const ConventionRun = struct { prefix: []const u8, reads: u32 };

    fn conventionRunOf(self: *const Checker, ty: TypeId) std.mem.Allocator.Error!ConventionRun {
        const parameters = self.builder.callableParams(self.builder.get(ty).callable);
        var reads: u32 = 0;
        while (reads < parameters.len and parameters[parameters.len - 1 - reads].convention == .read) reads += 1;
        var prefix: std.ArrayList(u8) = .empty;
        for (parameters[0 .. parameters.len - reads], 0..) |parameter, at| {
            if (at > 0) try prefix.appendSlice(self.sink.arena, ", ");
            try prefix.appendSlice(self.sink.arena, @tagName(parameter.convention));
        }
        return .{ .prefix = prefix.items, .reads = reads };
    }

    /// Spells a run as `(inout, read×2)`: the conventions before the trailing
    /// `read` parameters, then how many of those there are, or `1..7` where
    /// the trait answers for several counts.
    fn spellConventionRun(self: *const Checker, out: *std.ArrayList(u8), prefix: []const u8, fewest: u32, most: u32) std.mem.Allocator.Error!void {
        try out.append(self.sink.arena, '(');
        if (prefix.len > 0) {
            try out.appendSlice(self.sink.arena, prefix);
            if (most > 0) try out.appendSlice(self.sink.arena, ", ");
        }
        if (most == 1 and fewest == 1) {
            try out.appendSlice(self.sink.arena, "read");
        } else if (most > 0 and fewest == most) {
            try out.print(self.sink.arena, "read×{d}", .{most});
        } else if (most > 0) {
            try out.print(self.sink.arena, "read×{d}..{d}", .{ fewest, most });
        }
        try out.append(self.sink.arena, ')');
    }

    /// Says which of an implementation's parameters the callable type and the
    /// bound's trait arguments bind to different types, as in
    /// `S` is `Counter` from the function and `()` from the bound; null where
    /// they agree and something else differs.
    fn parameterDisagreement(self: *Checker, row: types_mod.Implementation, trait_args: []const TypeId, held: TypeId) std.mem.Allocator.Error!?[]const u8 {
        if (row.parameters == 0 or row.args.len != trait_args.len) return null;
        const bindings = try self.gpa.alloc(TypeId, row.parameters);
        defer self.gpa.free(bindings);
        @memset(bindings, .poison);
        var pool = self.builder.view();
        if (!types_mod.ImplIndex.bindKey(&pool, held, row.ty, row.decl.index(), bindings)) return null;
        for (row.args, trait_args) |written, asked| {
            const parameter = switch (self.builder.get(written)) {
                .parameter => |p| p,
                else => continue,
            };
            if (parameter.owner != row.decl.index() or parameter.index >= bindings.len) continue;
            const found = bindings[parameter.index];
            if (found == .poison or found == asked) continue;
            const names = self.ast.declTypeParams(row.decl);
            return try std.fmt.allocPrint(self.sink.arena, "the implementation takes `{s}` from the function as `{s}`, and the bound asks for `{s}`", .{
                self.ast.tokenText(names[parameter.index].name),
                try self.typeName(found),
                try self.typeName(asked),
            });
        }
        return null;
    }

    /// Appends to `notes` why a callable type fails a trait that is
    /// implemented for callable types: a closure matches none of them, a
    /// function of another shape is told which shapes the trait answers for,
    /// and one of a shape the trait answers for fails on its parameter types,
    /// which `unmetNotes` has already said where an extractor-style
    /// requirement is the cause.
    ///
    /// **Bound:** the trait's implementations, once.
    fn callableHeadNotes(self: *Checker, notes: *std.ArrayList([]const u8), trait: node.DeclId, trait_args: []const TypeId, held: TypeId) std.mem.Allocator.Error!void {
        const kind = self.builder.get(held);
        if (kind != .callable and kind != .closure) return;
        const wanted: ?types_mod.Head = if (kind == .callable) self.builder.headOf(held) else null;
        const Family = struct { head: types_mod.Head, prefix: []const u8, fewest: u32, most: u32 };
        var families: std.ArrayList(Family) = .empty;
        defer families.deinit(self.gpa);
        var same = false;
        var disagreement: ?[]const u8 = null;
        var walk = self.impl_index.membersOfTrait(@intCast(trait.index()));
        while (walk.next()) |at| {
            const row = self.implementations[at];
            if (row.trait != @as(u32, @intCast(trait.index())) or row.head != .callable_ or row.ty == .poison) continue;
            if (wanted) |w| if (row.head.same(w)) {
                same = true;
                if (disagreement == null) disagreement = try self.parameterDisagreement(row, trait_args, held);
            };
            const run = try self.conventionRunOf(row.ty);
            for (families.items) |*family| {
                if (!std.mem.eql(u8, family.prefix, run.prefix)) continue;
                family.fewest = @min(family.fewest, run.reads);
                family.most = @max(family.most, run.reads);
                break;
            } else try families.append(self.gpa, .{ .head = row.head, .prefix = run.prefix, .fewest = run.reads, .most = run.reads });
        }
        if (families.items.len == 0) return;
        const trait_name = self.ast.tokenText(self.ast.declName(trait));
        if (kind == .closure) {
            try notes.append(self.sink.arena, try std.fmt.allocPrint(self.sink.arena, "a closure's type is its own, so it matches none of the callable types `{s}` is implemented for; pass a named function", .{trait_name}));
            return;
        }
        if (same) {
            if (notes.items.len == 0) try notes.append(self.sink.arena, disagreement orelse try std.fmt.allocPrint(self.sink.arena, "its parameter conventions are ones `{s}` is implemented for, so its parameter types or its contract differ from the implementation's", .{trait_name}));
            return;
        }
        var shapes: std.ArrayList(u8) = .empty;
        for (families.items, 0..) |family, at| {
            if (at > 0) try shapes.appendSlice(self.sink.arena, ", ");
            try shapes.append(self.sink.arena, '`');
            try self.spellConventionRun(&shapes, family.prefix, family.fewest, family.most);
            try shapes.append(self.sink.arena, '`');
        }
        var own: std.ArrayList(u8) = .empty;
        const run = try self.conventionRunOf(held);
        try self.spellConventionRun(&own, run.prefix, run.reads, run.reads);
        try notes.append(self.sink.arena, try std.fmt.allocPrint(self.sink.arena, "this function's parameters are `{s}`, and `{s}` is implemented only for callable types whose parameters are {s}{s}", .{ own.items, trait_name, shapes.items, if (std.mem.indexOf(u8, shapes.items, "×") != null or std.mem.indexOf(u8, own.items, "×") != null) " (`read×N` is N parameters taken by `read`)" else "" }));
    }

    /// Appends to `notes` the requirement of a matching implementation of
    /// `trait` that the arguments of `held` fail, then the one that
    /// requirement fails in turn, down to a type no implementation matches.
    /// A requirement is either a trait the subject lacks or a capability it
    /// does not have, which ends the chain. The one routine every report of a
    /// missing implementation reads its reason from. Says whether some note
    /// speaks of an implementation written for a named type, which is what
    /// separates a type that fails an implementation's requirement from one no
    /// implementation was written for.
    ///
    /// `deepest` is set to the last requirement a note names, a trait or a
    /// capability: the one an edit of the program would meet.
    ///
    /// **Bound:** `unmet_requirement_depth` notes.
    fn unmetNotes(
        self: *Checker,
        notes: *std.ArrayList([]const u8),
        trait: node.DeclId,
        trait_args: []const TypeId,
        held: TypeId,
        deepest: ?*?UnmetDeepest,
    ) std.mem.Allocator.Error!bool {
        var named = false;
        var asked_trait = trait;
        var asked_args: []const TypeId = trait_args;
        var asked_type = held;
        var owned_args: ?[]const TypeId = null;
        defer if (owned_args) |owned| self.gpa.free(owned);
        while (notes.items.len < unmet_requirement_depth) {
            const found = try self.builder.unmetRequirement(asked_trait, asked_args, asked_type) orelse break;
            if (found.argument == held and found.trait == trait) {
                self.gpa.free(found.args);
                break;
            }
            // A type sealed from here keeps its field types out of view, so
            // its note speaks of its own arguments instead.
            const unmet = if (self.sealedHere(asked_type))
                try self.throughSealed(asked_type, found) orelse break
            else
                found;
            const implemented = try self.builder.spellInstance(self.ast.tokenText(self.ast.declName(asked_trait)), asked_args);
            defer self.gpa.free(implemented);
            if (unmet.capability) |capability| {
                const required = switch (capability) {
                    .copyable => "Copyable",
                    .discardable => "Discardable",
                    .unrestricted => unreachable,
                };
                try notes.append(self.sink.arena, try std.fmt.allocPrint(
                    self.sink.arena,
                    "`{s}` implements `{s}` when `{s}` is `{s}`, and `{s}` is not",
                    .{ (try self.heldName(unmet.head)), implemented, (try self.typeName(unmet.subject)), required, (try self.typeName(unmet.argument)) },
                ));
                self.gpa.free(unmet.args);
                if (deepest) |out| out.* = .{ .capability = .{ .capability = capability, .held = unmet.argument } };
                return true;
            }
            const required = try self.builder.spellInstance(self.ast.tokenText(self.ast.declName(unmet.trait)), unmet.args);
            defer self.gpa.free(required);
            // An implementation for every type names no type a reader could
            // look for, so its note speaks of every type meeting the requirement.
            const every_type = self.builder.get(unmet.head) == .parameter and unmet.subject == unmet.head;
            named = named or !every_type;
            try notes.append(self.sink.arena, if (every_type)
                try std.fmt.allocPrint(
                    self.sink.arena,
                    "every type implementing `{s}` implements `{s}`, and `{s}` does not implement `{s}`",
                    .{ required, implemented, (try self.typeName(unmet.argument)), required },
                )
            else
                try std.fmt.allocPrint(
                    self.sink.arena,
                    "`{s}` implements `{s}` when `{s}` implements `{s}`, and `{s}` does not",
                    .{ (try self.heldName(unmet.head)), implemented, (try self.typeName(unmet.subject)), required, (try self.typeName(unmet.argument)) },
                ));
            if (owned_args) |owned| self.gpa.free(owned);
            owned_args = unmet.args;
            asked_trait = unmet.trait;
            asked_args = unmet.args;
            asked_type = unmet.argument;
            if (deepest) |out| out.* = .{ .trait = .{ .trait = asked_trait, .args = try self.sink.arena.dupe(TypeId, asked_args), .held = asked_type } };
        }
        return named;
    }

    /// The last trait requirement a chain of unmet-requirement notes names.
    const UnmetDeepest = union(enum) {
        trait: struct { trait: node.DeclId, args: []const TypeId, held: TypeId },
        capability: struct { capability: types_mod.CapabilityRequirement, held: TypeId },
    };

    /// Adds to the diagnostic the sink holds at `at` the notes saying which
    /// requirement keeps `held` from implementing `trait`, where it fails one
    /// an implementation written for its own type states.
    fn explainMissing(self: *Checker, at: usize, trait: node.DeclId, held: TypeId) std.mem.Allocator.Error!void {
        var notes: std.ArrayList([]const u8) = .empty;
        defer notes.deinit(self.gpa);
        if (!try self.unmetNotes(&notes, trait, &.{}, held, null)) return;
        for (notes.items) |note| try self.addNote(at, note);
    }

    /// Follows an unmet requirement of a sealed type's implementation down to
    /// the one that fails on one of the sealed type's own arguments, and
    /// states it against the matching parameter of the implementation's head:
    /// `Outer[T]` implements `Equatable` when `T` does, and `Token` does not.
    /// Null where no requirement down the chain fails on an argument, which
    /// leaves nothing the reader can see to name. Takes ownership of
    /// `unmet.args`; the result's `args` belong to the caller.
    ///
    /// **Bound:** `unmet_requirement_depth` steps.
    fn throughSealed(self: *Checker, sealed: TypeId, unmet: types_mod.UnmetRequirement) std.mem.Allocator.Error!?types_mod.UnmetRequirement {
        // A capability demanded of a parameter's associated type is written in
        // the implementation's public head, so it names no hidden field.
        if (unmet.capability != null and self.builder.standinOf(unmet.subject) != null) return unmet;
        const arguments = self.builder.appliedTo(sealed);
        const parameters = self.builder.appliedTo(unmet.head);
        var inner = unmet;
        var steps: usize = 0;
        while (steps < unmet_requirement_depth) : (steps += 1) {
            for (arguments, 0..) |argument, at| {
                if (argument != inner.argument or at >= parameters.len) continue;
                return .{ .head = unmet.head, .subject = parameters[at], .argument = argument, .trait = inner.trait, .args = inner.args, .capability = inner.capability };
            }
            const next = try self.builder.unmetRequirement(inner.trait, inner.args, inner.argument) orelse break;
            self.gpa.free(inner.args);
            inner = next;
        }
        self.gpa.free(inner.args);
        return null;
    }

    /// Limits how many unmet requirements one report follows. A requirement chain
    /// through a recursive type does not end, so the notes stop here.
    const unmet_requirement_depth = 4;

    /// Reports a type mismatch at the expression, and again at whatever asked
    /// for the type.
    ///
    /// The second label is the useful one: the expression is where the
    /// mismatch was noticed, but the requirement is what a reader has to
    /// change, and it is usually on another line.
    fn reportMismatch(
        self: *Checker,
        id: ExprId,
        actual: TypeId,
        want: Expected,
        primary: []const u8,
    ) TypeId {
        return self.reportMismatchChosen(id, actual, want, primary, null);
    }

    /// A mismatch, also labelled where an open integer on either side had
    /// its type chosen when that is what the two disagree about.
    fn reportMismatchChosen(
        self: *Checker,
        id: ExprId,
        actual: TypeId,
        want: Expected,
        primary: []const u8,
        chosen: ?Label,
    ) TypeId {
        // An `else` block may take either of two shapes, so its headline
        // names both.
        const wanted = self.typeName(want.ty) catch return self.recordMismatch(id);
        const found = self.typeName(actual) catch return self.recordMismatch(id);
        // Two closures spell alike, `<closure>`, so naming both says nothing:
        // the headline states why they differ instead.
        const closures = self.builder.get(want.ty) == .closure and self.builder.get(actual) == .closure;
        const at_expr = (if (closures)
            std.fmt.allocPrint(self.gpa, "each closure has its own type, so this closure is not the one expected", .{})
        else if (want.reason == .unwrapped)
            std.fmt.allocPrint(self.gpa, "expected a block that leaves or yields `{s}`, found `{s}`", .{ wanted, found })
        else
            std.fmt.allocPrint(self.gpa, "expected `{s}`, found `{s}`", .{ wanted, found })) catch return self.recordMismatch(id);

        const at_source = self.expectationSource(want) catch return self.recordMismatch(id);

        // Built in the order this pass has them and ordered by the renderer,
        // which holds the file table: a span is an offset into its own file,
        // so comparing two here ordered a diagnostic by the length of a file
        // it was not about.
        const expr_span = self.ast.exprSpan(id);
        const expr_label: Label = .{
            .file = self.ast.fileOfExpr(id),
            .span = expr_span,
            .message = if (primary.len > 0) primary else if (closures) "a different closure" else at_expr,
            .style = .primary,
        };
        const source_label: Label = .{
            .file = want.at.file,
            .span = want.at.span,
            .message = at_source,
            .style = .secondary,
        };

        // The sink holds the slice rather than copying it, so the labels
        // outlive this call and cannot live on the stack.
        const labels = self.gpa.alloc(Label, if (chosen == null) 2 else 3) catch return self.recordMismatch(id);
        labels[0] = expr_label;
        labels[1] = source_label;
        if (chosen) |label| labels[2] = label;
        const computed_note = "one literal borrows a variable it cannot copy and the other holds a value computed in its braces; bind the computed value with `let` first, so both borrow a variable";
        const observation_note = "one literal borrows a variable it cannot copy and the other holds a copy of a `borrow` of it; interpolate the variable in both, or the `borrow` in both";
        const closure_note = if (closures) self.closuresNote(want.ty, actual) catch return self.recordMismatch(id) else "";
        const notes: []const []const u8 = if (closures)
            self.sink.arena.dupe([]const u8, &.{closure_note}) catch return self.recordMismatch(id)
        else if (self.builder.view().holdingDifference(want.ty, actual)) |difference|
            if (difference.computed and difference.observation)
                &.{ computed_note, observation_note }
            else if (difference.computed)
                &.{computed_note}
            else
                &.{observation_note}
        else
            &.{};
        const fill_note = self.defaultedFillNote(id, actual, want) catch return self.recordMismatch(id);
        const allocator_note = self.allocatorPassedNote(actual, want) catch return self.recordMismatch(id);
        var extra: [2][]const u8 = undefined;
        var extras: usize = 0;
        if (fill_note) |text| {
            extra[extras] = text;
            extras += 1;
        }
        if (allocator_note) |text| {
            extra[extras] = text;
            extras += 1;
        }
        const all_notes: []const []const u8 = if (extras > 0) blk: {
            const joined = self.sink.arena.alloc([]const u8, notes.len + extras) catch return self.recordMismatch(id);
            @memcpy(joined[0..notes.len], notes);
            @memcpy(joined[notes.len..], extra[0..extras]);
            break :blk joined;
        } else notes;

        self.sink.add(.{
            .severity = .err,
            // Which rule was broken is what the expectation came from. An
            // operand disagreeing with the operand beside it is not a value
            // failing to match a context: nothing here required either type,
            // and the left one settles it only by being first. A condition is
            // the other way about -- the type is the language's own demand,
            // stated by the rule that makes it.
            .code = switch (want.reason) {
                .operand => .t_operands,
                .condition => .t_condition,
                else => .t_mismatch,
            },
            .message = at_expr,
            .labels = labels,
            .notes = all_notes,
        }) catch {};
        return self.recordMismatch(id);
    }

    /// What two different closures can be kept as. Closures called alike --
    /// one satisfies the other's signature as a callable bound, which is what
    /// `mem.Closure.open` asks of its callback -- are kept together as one
    /// `mem.Closure`; closures called differently are named by their
    /// signatures, since no one type holds both.
    fn closuresNote(self: *Checker, wanted: TypeId, found: TypeId) std.mem.Allocator.Error![]const u8 {
        const wanted_signature = try self.withoutEnvironmentContracts(try self.callbackValueSignature(wanted));
        const found_signature = try self.withoutEnvironmentContracts(try self.callbackValueSignature(found));
        if (self.builder.view().callableSatisfies(found_signature, wanted_signature)) {
            return "closures called alike are kept together as `mem.Closure` values: open each with `mem.Closure.open(closure)`; closures that capture nothing also convert to a written `fn` type";
        }
        return std.fmt.allocPrint(
            self.sink.arena,
            "the two are called differently, as `{s}` and as `{s}`, so no one type holds both",
            .{ try self.typeName(wanted_signature), try self.typeName(found_signature) },
        );
    }

    /// Reports at a span, and again at whatever explains it.
    ///
    /// Every diagnostic that can name a second location does. A value that
    /// broke a rule almost always came from somewhere else, and that
    /// somewhere is what a reader has to change.
    fn reportWithOrigin(
        self: *Checker,
        code: Code,
        id: ExprId,
        message: []const u8,
        primary: []const u8,
        origin: ?Label,
    ) TypeId {
        return self.reportWithOriginNotes(code, id, message, primary, origin, &.{});
    }

    fn reportWithOriginNotes(
        self: *Checker,
        code: Code,
        id: ExprId,
        message: []const u8,
        primary: []const u8,
        origin: ?Label,
        notes: []const []const u8,
    ) TypeId {
        const at = self.ast.exprSpan(id);
        const here: Label = .{ .file = self.ast.fileOfExpr(id), .span = at, .message = primary, .style = .primary };

        if (origin) |o| {
            // Built here, ordered by the renderer. A `Label` carries the file
            // its span belongs to and comparing the spans alone ignores it.
            const labels = self.gpa.alloc(Label, 2) catch return self.record(id, .poison);
            labels[0] = here;
            labels[1] = o;
            self.sink.add(.{
                .severity = .err,
                .code = code,
                .message = message,
                .labels = labels,
                .notes = notes,
            }) catch {};
        } else {
            const labels = self.gpa.alloc(Label, 1) catch return self.record(id, .poison);
            labels[0] = here;
            self.sink.add(.{
                .severity = .err,
                .code = code,
                .message = message,
                .labels = labels,
                .notes = notes,
            }) catch {};
        }
        return self.record(id, .poison);
    }

    /// Where a folded value was written down, when it reached this expression
    /// through a binding rather than being spelled here.
    fn originOfFold(self: *Checker, id: ExprId) ?Label {
        if (self.ast.exprTag(id) != .name_ref) return null;
        const target = self.res.targetOf(id);
        if (target == BindingId.none) return null;
        const at = self.binding_value_locs[target.index()];
        if (at.isNowhere()) return null;
        return .{ .file = at.file, .span = at.span, .message = "the value comes from here", .style = .secondary };
    }

    /// Whether control reaches the local continuation.
    ///
    /// A body that always returns has no trailing expression and needs none:
    /// nothing reaches the end for a value to come from. This is syntactic and
    /// deliberately conservative -- it answers "certainly" and never "probably"
    /// -- because a body it fails to recognise is reported rather than
    /// miscompiled.
    fn completionReaches(self: *const Checker, id: ExprId) bool {
        if (id == ExprId.none) return true;
        if (self.builder.exprType(id) == .never) return false;
        return switch (self.ast.exprTag(id)) {
            .return_ => false,

            .block => blk: {
                const b = self.ast.blockOf(id);
                for (self.ast.blockStmts(b)) |s| {
                    switch (self.ast.stmtTag(s)) {
                        // A statement leaves where the expression it evaluates
                        // does, and a `let`'s initialiser is evaluated like any
                        // other: the value it would have bound leaves instead,
                        // so there is no binding and no rest of the block.
                        .expr_stmt, .let_decl, .let_destructure, .let_read_destructure => {},
                        // What a `defer` schedules may not leave at all --
                        // [S-Defer] -- so it never carries the block out.
                        .defer_stmt, .defer_release, .err => continue,
                    }
                    if (!self.completionReaches(self.ast.stmtData(s).init)) break :blk false;
                }
                break :blk b.tail == ExprId.none or self.completionReaches(b.tail);
            },

            // One reaching arm reaches the boundary. An absent arm does too.
            .conditional => blk: {
                const c = self.ast.conditional(id);
                if (c.otherwise == ExprId.none) break :blk true;
                break :blk self.completionReaches(c.then) or self.completionReaches(c.otherwise);
            },

            else => true,
        };
    }

    /// The expression whose value a block yields, or the block itself where it
    /// yields nothing.
    ///
    /// A message about what a block *produced* points at what produced it. The
    /// block's own extent is `{ ... }`, which is the right answer to "where is
    /// this block" and the wrong one to "where did this value come from".
    fn resultOf(self: *const Checker, id: ExprId) ExprId {
        if (self.ast.exprTag(id) != .block) return id;
        const tail = self.ast.blockOf(id).tail;
        return if (tail == ExprId.none) id else tail;
    }

    /// Where an expression is, as a position that survives leaving the tree.
    fn locOf(self: *const Checker, id: ExprId) Loc {
        return .{ .file = self.ast.fileOfExpr(id), .span = self.ast.exprSpan(id) };
    }

    /// The alias a written type is headed by, or `.none` where its head
    /// names anything else. What a report reads to say what an alias names
    /// beside the annotation that wrote it.
    fn aliasHeading(self: *const Checker, owner: node.DeclId, ref: node.TypeRef) node.DeclId {
        const written = self.ast.withoutTypeGroups(ref);
        const found = switch (written.kind) {
            .named => self.aliasWritten(owner, written.name),
            .selection => self.res.aliasReachedBy(written.name),
            else => null,
        };
        return found orelse .none;
    }

    /// Why a type was expected, as the label beside where it was written
    /// says it: the reason, and what an alias written there names.
    fn expectationSource(self: *Checker, want: Expected) std.mem.Allocator.Error![]const u8 {
        if (want.alias == node.DeclId.none) return want.reason.describe();
        return std.fmt.allocPrint(self.sink.arena, "{s}; `{s}` is an alias of `{s}`", .{
            want.reason.describe(),
            self.ast.tokenText(self.ast.declName(want.alias)),
            try self.typeName(want.ty),
        });
    }

    /// Where a written type points when it imposes an expectation.
    fn locOfWritten(self: *const Checker, ref: node.TypeRef) Loc {
        if (ref.inferred_length != .none) return .{
            .file = self.ast.fileOf(ref.inferred_length),
            .span = self.ast.tokenSpan(ref.inferred_length),
        };
        return .{ .file = self.ast.fileOf(ref.at), .span = self.ast.writtenSpan(ref) };
    }

    fn checkBody(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const b = self.ast.blockOf(id);

        for (self.ast.blockStmts(b)) |s| try self.checkStmt(s);

        if (b.tail == ExprId.none) {
            // A body with no trailing expression has no value where control
            // reaches its continuation. Where it leaves instead, no value has
            // to inhabit the surrounding expectation and no Unit reaches the
            // other arm to disagree with it.
            const falls_through = self.completionReaches(id);
            if (!falls_through) return self.record(id, .never);
            if (expected) |want| {
                if (!want.unit_test_success and want.ty != .unit and want.ty != .poison) {
                    _ = self.reportMismatch(id, .unit, want, "this body produces nothing");
                }
            }
            return self.record(id, .unit);
        }

        const t = try self.checkResult(id, b.tail, expected);

        return self.record(id, t);
    }

    /// Whether a written head names the declaration a type came from.
    ///
    /// An instantiation's own name carries its arguments, and a pattern writes
    /// none, so the two are compared through the declaration rather than
    /// through the spelling.
    /// The head is resolved where it was written, and what it reaches there
    /// decides. A name is unique only within a module, so two modules may each
    /// declare one and only the declaration tells them apart -- compared by
    /// spelling, a pattern took apart a value of a type its own module had
    /// never named, while the `let` form of the same two modules was refused
    /// because that path resolves the head.
    ///
    /// Where the head reaches nothing here the spelling is all there is, and
    /// that is not a fallback to the old rule but the rest of this one: a
    /// pattern cannot qualify its head, so a module holding no type of that
    /// name is still entitled to take apart a value another module declared.
    fn namesTheSameType(self: *const Checker, head: TokenId, of: TypeId) bool {
        // An alias names the declaration of the type it names, so a head
        // spelled as one is compared through that type.
        if (self.aliasWritten(self.generic, head)) |alias| {
            const named = self.settledAlias(alias) orelse return false;
            const declared = self.declaringType(named) orelse return false;
            return self.declaringType(of) == declared;
        }
        const pool = self.view();
        return namesTheType(
            self.ast,
            &pool,
            head,
            of,
            self.declOfType(self.current, self.generic, head),
            self.declaringType(of),
        );
    }

    /// A pattern, against the type of what it takes apart.
    ///
    /// The one routine every construct checks a pattern with -- a `match`
    /// arm, a destructuring `let`, a walk's binder and a lambda's parameter --
    /// and it recurses into every part, so a pattern reads one way at every
    /// depth. `at` is the place the value sits at, where the construct lends
    /// or the `match` takes one: the scrutinee for the outermost pattern, and
    /// the pattern node itself for a pattern nested in it, whose own place is
    /// recorded in `pattern_places`. It is none where the construct takes
    /// the value apart and keeps no place.
    ///
    /// Answers whether the pattern is sound. An unsound one was reported, or
    /// sits over a value that was, and takes no part in coverage.
    fn checkPattern(self: *Checker, pattern: ExprId, of: TypeId, at: ExprId) std.mem.Allocator.Error!bool {
        return switch (self.ast.exprTag(pattern)) {
            .struct_pattern => self.checkStructPattern(pattern, of, at),
            .tuple_pattern => self.checkTuplePattern(pattern, of, at),
            .call => if (self.builder.get(of) == .newtype)
                self.checkNewtypePattern(pattern, of, at)
            else
                self.checkVariantPattern(pattern, of, at),
            .name_ref => if (isCatchAll(self.ast, pattern)) blk: {
                _ = self.record(pattern, of);
                break :blk true;
            } else self.checkVariantPattern(pattern, of, at),
            // The parser said what is wrong here; a second report about the
            // hole it left would describe the recovery, not the program.
            .err => blk: {
                _ = self.record(pattern, .poison);
                break :blk false;
            },
            else => self.checkLiteralPattern(pattern, of),
        };
    }

    /// One part of a pattern: a binder, which takes the part's type and
    /// stands for its place, or a pattern nested there, checked in turn.
    /// `step` selects the part from the value at `at`.
    fn checkPart(self: *Checker, part: ExprId, ty: TypeId, at: ExprId, step: Step) std.mem.Allocator.Error!bool {
        if (self.ast.partBinds(part)) {
            _ = self.record(part, ty);
            const b = self.res.targetOf(part);
            if (b == BindingId.none) return true;
            self.setBindingType(b, ty);
            if (at != ExprId.none) self.binder_places[b.index()] = .{ .of = at, .step = step };
            return true;
        }
        if (at == ExprId.none) return self.checkPattern(part, ty, ExprId.none);
        try self.pattern_places.put(self.gpa, part, .{ .of = at, .step = step });
        return self.checkPattern(part, ty, part);
    }

    /// Gives every binder of a pattern the poison type, where what it would
    /// take apart was already reported, so nothing reports about it again.
    fn poisonPattern(self: *Checker, pattern: ExprId) void {
        self.settlePatternAs(pattern, .poison);
    }

    /// Gives every part of a pattern the one type `ty`: `Never` over a walk
    /// that yields nothing, or poison over a value already reported.
    fn settlePatternAs(self: *Checker, pattern: ExprId, ty: TypeId) void {
        _ = self.record(pattern, ty);
        if (self.ast.partBinds(pattern)) {
            const b = self.res.targetOf(pattern);
            if (b != BindingId.none) self.setBindingType(b, ty);
            return;
        }
        var parts = self.ast.patternParts(pattern);
        while (parts.next()) |part| self.settlePatternAs(part, ty);
    }

    /// A variant's pattern: `None`, or `Some(p)` taking apart what it carries.
    ///
    /// A pattern takes apart as many parts as the variant carries, or none at
    /// all: an arm that does not want the payload says so by not naming it,
    /// which is what a name is for. Naming more than one, or naming where
    /// there is nothing to name, is the arity rule a call already states.
    fn checkVariantPattern(self: *Checker, pattern: ExprId, of: TypeId, at: ExprId) std.mem.Allocator.Error!bool {
        const binds = self.ast.exprTag(pattern) == .call;
        const parts: []const ExprId = if (binds) self.ast.call(pattern).args else &.{};
        const name = self.ast.tokenText(self.ast.exprMain(pattern));
        _ = self.record(pattern, of);
        if (binds) _ = self.record(self.ast.call(pattern).callee, of);

        const fail = struct {
            fn poisoned(checker: *Checker, held: []const ExprId) bool {
                for (held) |part| checker.poisonPattern(part);
                return false;
            }
        }.poisoned;

        // The value was already reported, so nothing is known about what the
        // parts name -- and nothing more to say about it.
        if (of == .poison) return fail(self, parts);

        if (of.bounds() != null) {
            _ = self.report(
                .t_mismatch,
                pattern,
                "a match over `{s}` takes a literal or a range, not a name",
                .{(try self.typeName(of))},
                "not a literal or a range",
            );
            return fail(self, parts);
        }

        // Taking a sealed type apart is reaching its representation, which is
        // the same rule a literal breaks by building one.
        if (self.sealedHere(of)) {
            _ = self.reportSealed(pattern, of, "only its own module can take one apart");
            return fail(self, parts);
        }

        // A view is read through, and a pattern takes the value itself apart.
        if (self.builder.get(of) == .borrow) {
            const shown = try self.typeName(of);
            _ = self.report(
                .t_mismatch,
                pattern,
                "this takes `{s}` apart, and the value is {s} `{s}`",
                .{ name, article.before(shown), shown },
                "a pattern takes a value apart, not a view of one",
            );
            return fail(self, parts);
        }

        const k = (try self.variantNamed(of, name)) orelse {
            _ = self.report(.n_variant, pattern, "the enum has no such variant", .{}, "not a variant of what is matched");
            return fail(self, parts);
        };
        const carries = self.builder.variantFieldCount(of, k);

        // Every part or none. A prefix would take the first parts and leave
        // the rest unnamed, which reads as a choice and is a miscount.
        if (parts.len != 0 and parts.len != carries) {
            _ = self.report(
                .t_arity,
                pattern,
                "expected {d} name(s), found {d}",
                .{ carries, parts.len },
                "the wrong number of names",
            );
            return fail(self, parts);
        }

        // Ownership reads what the pattern leaves unnamed; lowering reads
        // which variant it selects. Both facts belong to the checked pattern.
        try self.variant_uses.put(self.gpa, pattern, .{
            .ordinal = @enumFromInt(k),
            .drops_payload = parts.len == 0 and carries != 0,
        });

        var sound = true;
        for (parts, 0..) |part, j| {
            const ty = self.builder.variantFieldType(of, k, @intCast(j));
            const step: Step = .{ .carried = .{ .variant = k, .index = @intCast(j) } };
            if (!try self.checkPart(part, ty, at, step)) sound = false;
        }
        return sound;
    }

    /// An integer literal or range: a pattern that compares. Its bounds are
    /// read through the fold table, and a range written backwards matches
    /// nothing, which is what [T-Unreachable] says of an arm no value reaches.
    fn checkLiteralPattern(self: *Checker, pattern: ExprId, of: TypeId) std.mem.Allocator.Error!bool {
        _ = self.record(pattern, of);
        if (of == .poison) return false;
        // A column whose type is already an integer compares as it is; only
        // an open one is settled here, where the literal compares it.
        const settled = if (of.bounds() != null) of else try self.receiverType(of, self.literalSite(pattern));
        _ = self.record(pattern, settled);
        switch (self.ast.exprTag(pattern)) {
            .int_literal, .negate, .range => {},
            else => {
                _ = self.report(
                    .t_mismatch,
                    pattern,
                    "a match over `{s}` takes a literal or a range, not a name",
                    .{(try self.typeName(settled))},
                    "not a literal or a range",
                );
                return false;
            },
        }
        if (settled.bounds() == null) {
            _ = self.report(
                .t_mismatch,
                pattern,
                "a `{s}` is not compared against a literal or a range",
                .{(try self.typeName(settled))},
                "only an integer is compared in a pattern",
            );
            return false;
        }
        const iv = try self.intArmInterval(pattern, settled) orelse return false;
        if (iv.lo > iv.hi) {
            _ = self.report(.t_unreachable, pattern, "no value reaches this arm", .{}, "this range matches nothing");
            return false;
        }
        return true;
    }

    /// A struct pattern, against the type of what it is taking apart.
    ///
    /// The one place a pattern's field list is resolved, so a destructuring
    /// `let` and a `match` arm are one world rather than two that drift. It is
    /// the mirror of a structure literal: a literal gives every field a value
    /// and this takes every field's value out, so the same three mistakes --
    /// an unknown field, a repeated one, a missing one -- are the same three
    /// diagnostics.
    fn checkStructPattern(
        self: *Checker,
        pattern: ExprId,
        of: TypeId,
        at: ExprId,
    ) std.mem.Allocator.Error!bool {
        const p = self.ast.call(pattern);
        _ = self.record(pattern, of);
        if (p.callee != ExprId.none) _ = self.record(p.callee, of);

        const fail = struct {
            fn poisoned(checker: *Checker, held: []const ExprId) bool {
                var i: usize = 1;
                while (i < held.len) : (i += 2) checker.poisonPattern(held[i]);
                return false;
            }
        }.poisoned;
        if (of == .poison) return fail(self, p.args);

        // The head names the type being taken apart, and naming a different
        // one is a mistake about what this value is.
        // Compared against the declaration a type came from rather than
        // against its spelling: an instantiation is named `Cell[u8]` and the
        // pattern writes `Cell`, which names the same declaration.
        const head_tok = if (p.callee != ExprId.none) self.ast.exprMain(p.callee) else TokenId.none;
        if (head_tok != TokenId.none and !self.namesTheSameType(head_tok, of)) {
            _ = self.report(
                .t_mismatch,
                pattern,
                "this takes {s} `{s}` apart, and the value is {s} `{s}`",
                .{ article.before(self.ast.tokenText(head_tok)), self.ast.tokenText(head_tok), article.before(try self.typeName(of)), (try self.typeName(of)) },
                "the pattern names a different type",
            );
            return fail(self, p.args);
        }

        // A generic alias heading the pattern writes the type it takes apart,
        // as it does for a path: the value must be that type at the alias's
        // arguments.
        if (head_tok != TokenId.none) if (self.aliasWritten(self.generic, head_tok)) |alias| {
            const written = self.settledAlias(alias) orelse .poison;
            if (written != .poison and self.ast.declTypeParams(alias).len != 0) {
                const heading: AliasHeading = .{
                    .alias = alias,
                    .written = &.{written},
                    .found = try self.openAliasArguments(alias),
                };
                if (!try self.settleAliasHeading(pattern, head_tok, heading, &.{of})) return fail(self, p.args);
            }
        };

        // Taking a sealed type apart is reaching its representation, which is
        // the same rule a literal breaks by building one.
        if (self.sealedHere(of)) {
            _ = self.reportSealed(pattern, of, "only its own module can take one apart");
            return fail(self, p.args);
        }

        if (self.builder.get(of) != .struct_) {
            _ = self.report(.t_unknown_field, pattern, "`{s}` is not a struct", .{(try self.typeName(of))}, "only a struct is taken apart with braces");
            return fail(self, p.args);
        }

        const count = self.builder.fieldCount(of);
        var named = try self.gpa.alloc(bool, count);
        defer self.gpa.free(named);
        @memset(named, false);

        var sound = true;
        var i: usize = 0;
        while (i + 1 < p.args.len) : (i += 2) {
            const name = self.ast.tokenText(self.ast.exprMain(p.args[i]));
            _ = self.record(p.args[i], .unit);

            const field = if (self.builder.lookupField(of, name)) |found| found.index else {
                _ = self.report(
                    .t_unknown_field,
                    p.args[i],
                    "`{s}` has no field `{s}`",
                    .{ (try self.typeName(of)), name },
                    "not a field of this type",
                );
                self.poisonPattern(p.args[i + 1]);
                sound = false;
                continue;
            };

            try self.field_names.put(self.gpa, self.ast.exprMain(p.args[i]), .{ .receiver = of, .field = @enumFromInt(field) });

            if (named[field]) {
                _ = self.report(.t_duplicate_field, p.args[i], "`{s}` is named twice", .{name}, "already named above");
                sound = false;
            }
            named[field] = true;

            const step: Step = .{ .field = self.ast.tokenName(self.ast.exprMain(p.args[i])) };
            if (!try self.checkPart(p.args[i + 1], self.builder.fieldType(of, field), at, step)) sound = false;
        }

        // Whole-struct: every field is named exactly once. There are no
        // partial moves, so a field left out is a part of the value that
        // nothing became responsible for.
        for (named, 0..) |had, f| {
            if (had) continue;
            _ = self.report(
                .t_missing_field,
                pattern,
                "`{s}` is not named",
                .{self.builder.fieldName(of, @intCast(f))},
                "every field is named exactly once",
            );
            sound = false;
        }
        return sound;
    }

    /// `(a, b)` as a pattern: a tuple taken apart by position.
    ///
    /// The value must be a tuple, and the pattern names exactly as many parts
    /// as it has components; each part takes its component's type. A binder
    /// is recorded against its component as a struct pattern's field token is
    /// recorded against its field, so a report about what `_` did not settle
    /// can name the component.
    fn checkTuplePattern(
        self: *Checker,
        pattern: ExprId,
        of: TypeId,
        at: ExprId,
    ) std.mem.Allocator.Error!bool {
        const p = self.ast.call(pattern);
        _ = self.record(pattern, of);

        const fail = struct {
            fn poisoned(checker: *Checker, held: []const ExprId) bool {
                for (held) |part| checker.poisonPattern(part);
                return false;
            }
        }.poisoned;
        if (of == .poison) return fail(self, p.args);

        // A pattern of an arity the parser refused was reported at the `(`,
        // and is held against nothing more: not the value's kind, and not
        // its arity, which is what the refusal already said.
        if (!node.isTupleArity(p.args.len)) return fail(self, p.args);

        const settled = try self.builder.resolveOpen(of, &self.open_types);
        const instance = self.builder.instanceOf(settled);
        if (instance == null or !self.builder.isTupleDecl(instance.?.decl)) {
            const name = try self.typeName(settled);
            _ = self.report(
                .t_mismatch,
                pattern,
                "this takes a tuple apart, and the value is {s} `{s}`",
                .{ article.before(name), name },
                "a tuple pattern takes a tuple apart",
            );
            return fail(self, p.args);
        }

        // The arity is the declaration's, read off the value.
        const count = self.builder.fieldCount(settled);
        if (p.args.len != count) {
            _ = self.report(
                .t_arity,
                pattern,
                "expected {d} name(s), found {d}",
                .{ count, p.args.len },
                "a tuple pattern binds every component by position",
            );
            return fail(self, p.args);
        }

        // The arity check above is what makes a part's position a field of
        // the declaration.
        var sound = true;
        for (p.args, 0..) |part, i| {
            if (self.ast.partBinds(part)) {
                try self.field_names.put(self.gpa, self.ast.exprMain(part), .{ .receiver = settled, .field = @enumFromInt(i) });
            }
            const step: Step = .{ .field = self.ast.declFieldName(instance.?.decl, i) };
            if (!try self.checkPart(part, self.builder.fieldType(settled, @intCast(i)), at, step)) sound = false;
        }
        return sound;
    }

    test "a tuple pattern records each binder's component, the wildcard included" {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        const checked = try typingAsPrelude(gpa, own_tuple2 ++
            \\fn main() -> UInt8 {
            \\    let pair: (UInt8, Bool) = (1, true)
            \\    let (n, _) = pair
            \\    n
            \\}
            \\
        , &sink);
        try testing.expectEqual(@as(u32, 0), sink.error_count);
        const ast = &checked.res.expanded.ast;
        var binders: usize = 0;
        for (0..ast.exprCount()) |i| {
            const id = ExprId.at(@intCast(i));
            if (ast.exprTag(id) != .tuple_pattern) continue;
            for (ast.call(id).args, 0..) |binder, position| {
                const selected = checked.typing.fieldSelection(ast.exprMain(binder)) orelse return error.TestExpectedEqual;
                try testing.expectEqual(@as(u32, @intCast(position)), selected.field.index());
                try testing.expectEqualStrings("(UInt8, Bool)", checked.typing.nameOf(selected.receiver));
                binders += 1;
            }
            try testing.expectEqual(TypeId.u8, checked.typing.exprType(ast.call(id).args[0]));
            try testing.expectEqual(TypeId.bool_, checked.typing.exprType(ast.call(id).args[1]));
        }
        try testing.expectEqual(@as(usize, 2), binders);
    }

    /// `N(p)`: a newtype's pattern, taken apart to its base value.
    ///
    /// Erasure is representational, so nothing here re-examines what the
    /// base holds. `dischargeRefinement` is the only place a proof is asked
    /// for, and a pattern runs only once one already exists -- the part takes
    /// the base's type and the operand's value with no comparison in between,
    /// the mirror of how a direct construction passes the operand straight
    /// through.
    fn checkNewtypePattern(
        self: *Checker,
        pattern: ExprId,
        of: TypeId,
        at: ExprId,
    ) std.mem.Allocator.Error!bool {
        const p = self.ast.call(pattern);
        _ = self.record(pattern, of);
        _ = self.record(p.callee, of);

        const fail = struct {
            fn poisoned(checker: *Checker, held: []const ExprId) bool {
                for (held) |part| checker.poisonPattern(part);
                return false;
            }
        }.poisoned;
        if (of == .poison) return fail(self, p.args);

        // The head names the type being taken apart, compared against the
        // declaration `of` came from -- the same reason a struct pattern
        // does, so an instantiation's own spelling is never the question.
        const head_tok = self.ast.exprMain(p.callee);
        const head = self.ast.tokenText(head_tok);
        if (!self.namesTheSameType(head_tok, of)) {
            _ = self.report(
                .t_mismatch,
                pattern,
                "this takes {s} `{s}` apart, and the value is {s} `{s}`",
                .{ article.before(head), head, article.before(try self.typeName(of)), (try self.typeName(of)) },
                "the pattern names a different type",
            );
            return fail(self, p.args);
        }

        // Taking a sealed type apart is reaching its representation, the
        // same rule a literal breaks by building one.
        if (self.sealedHere(of)) {
            _ = self.reportSealed(pattern, of, "only its own module can take one apart");
            return fail(self, p.args);
        }

        // `namesTheSameType` answers by spelling as well as by declaration,
        // so a name that matches without a newtype behind it -- an enum
        // sharing the spelling, say -- reaches here rather than `baseOf`,
        // which holds only for a newtype's own descriptor.
        const decl = self.declaringType(of);
        if (decl == null or self.ast.declTag(decl.?) != .newtype) {
            _ = self.report(
                .t_mismatch,
                pattern,
                "`{s}` has no base to read this way",
                .{(try self.typeName(of))},
                "only a newtype's pattern takes a value apart like this",
            );
            return fail(self, p.args);
        }

        if (p.args.len != 1) {
            _ = self.report(
                .t_arity,
                pattern,
                "expected {d} name(s), found {d}",
                .{ 1, p.args.len },
                "a newtype's pattern binds exactly the value it wraps",
            );
            return fail(self, p.args);
        }

        if (!try self.checkPart(p.args[0], self.builder.baseOf(of), at, .{ .field = self.ast.tokenName(head_tok) })) return false;

        // A literal or range outside the refinement names a value the base
        // never holds, so no value reaches the arm.
        const compares = switch (self.ast.exprTag(p.args[0])) {
            .int_literal, .negate, .range => true,
            else => false,
        };
        if (compares and self.builder.isRefined(of)) {
            const r = self.refinedValues(of) orelse return true;
            if (self.foldedInterval(p.args[0])) |iv| if (iv.hi < r.lo or iv.lo > r.hi) {
                _ = self.report(
                    .t_unreachable,
                    p.args[0],
                    "no value reaches this arm",
                    .{},
                    try std.fmt.allocPrint(self.sink.arena, "no `{s}` holds this value", .{head}),
                );
                return false;
            };
        }
        return true;
    }

    /// The values a refined newtype `t` admits, as its patterns are judged:
    /// its clause's interval within what its base can hold. Null where the
    /// declaration was refused for [T-Refine] with no value left to judge
    /// against -- a base that is not an integer, or a clause admitting none
    /// of the base's values -- since a judgement then would repeat the
    /// declaration's mistake at every pattern.
    fn refinedValues(self: *const Checker, t: TypeId) ?usefulness.Interval {
        const base = self.builder.baseOf(t).bounds() orelse return null;
        const r = self.builder.refinementOf(t);
        const lo = @max(r.lo, base.min);
        const hi = @min(r.hi, base.max);
        return if (lo <= hi) .{ .lo = lo, .hi = hi } else null;
    }

    /// The variant of `t` named `name`, or null. An enum of a few variants is
    /// scanned; a wider one is indexed by name the first time it is asked
    /// about, so a `match` naming each of n variants costs n lookups rather
    /// than n scans of n names.
    fn variantNamed(self: *Checker, t: TypeId, name: []const u8) std.mem.Allocator.Error!?u32 {
        const count = switch (self.builder.get(t)) {
            .enum_ => |e| e.variant_count,
            else => return self.builder.variantIndexOf(t, name),
        };
        if (count <= 16) return self.builder.variantIndexOf(t, name);
        const found = try self.variant_names.getOrPut(self.gpa, t);
        if (!found.found_existing) {
            found.value_ptr.* = .empty;
            const pool = self.view();
            for (0..count) |i| try found.value_ptr.put(self.gpa, pool.variantName(t, @intCast(i)), @intCast(i));
        }
        return found.value_ptr.get(name);
    }

    /// Refuses a pattern that misses a value of its type, where nothing else
    /// would take that value: the pattern of a `let`, a `let read`, a
    /// `let ... else`, a walk or a lambda's parameter ([T-Refutable]).
    fn refuseRefutable(self: *Checker, pattern: ExprId, of: TypeId) std.mem.Allocator.Error!void {
        if (of == .poison or of == .never) return;
        var state = std.heap.ArenaAllocator.init(self.gpa);
        defer state.deinit();
        var coverage: PatternCoverage = .{ .context = .{ .checker = self }, .arena = state.allocator() };
        const row = try coverage.arena.alloc(PatternCoverage.Cell, 1);
        row[0] = .{ .pattern = try self.coveragePattern(coverage.arena, pattern, of), .ty = of };
        const outcome = coverage.check(&.{row}, of) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            error.TooIntricate => {
                _ = self.report(.t_cover_limit, pattern, "this pattern is too intricate to check", .{}, "take it apart in more than one step");
                return;
            },
            // A refused refinement's values are unknown, and its declaration
            // is where that was said.
            error.Refused => return,
        };
        if (outcome.missing.len == 0) return;
        const missed = outcome.missing[0];
        var text: std.ArrayList(u8) = .empty;
        defer text.deinit(self.gpa);
        try self.witnessText(missed, &text);
        const label = try std.fmt.allocPrint(self.sink.arena, "`{s}` is not matched", .{text.items});
        const message = try std.fmt.allocPrint(self.sink.arena, "this pattern does not match every `{s}`", .{try self.typeName(of)});
        // A variant of `Option` or `Result` at the head names what a success
        // carries, which `let ... else` binds while handling the other case.
        const unwraps = self.variant_uses.contains(pattern) and self.carrierOf(of) != null;
        const unwrap_help: []const []const u8 = &.{"bind what it carries with `let ... else`, or take it apart with `match`"};
        const match_help: []const []const u8 = &.{"take it apart with `match`, which has an arm for every case"};
        _ = self.reportWithOriginNotes(.t_refutable, self.missedPart(pattern, missed, of), message, label, null, if (unwraps) unwrap_help else match_help);
    }

    /// The part of a pattern a missed value first fails to match, read along
    /// the value: a variant naming another variant, or a literal leaving the
    /// value out. The whole pattern where no part says so. Bounded by the
    /// pattern's size.
    fn missedPart(self: *Checker, pattern: ExprId, missed: PatternCoverage.Witness, of: TypeId) ExprId {
        if (isCatchAll(self.ast, pattern) or self.ast.partBinds(pattern)) return pattern;
        const types: PatternTypes = .{ .checker = self };
        switch (self.ast.exprTag(pattern)) {
            .name_ref, .call => if (self.variant_uses.get(pattern)) |use| {
                const k: u32 = @intFromEnum(use.ordinal);
                const parts = switch (missed.shape) {
                    .variant => |v| if (v.index == k) v.args else return pattern,
                    else => return pattern,
                };
                if (self.ast.exprTag(pattern) != .call) return pattern;
                for (self.ast.call(pattern).args, 0..) |part, j| {
                    if (j >= parts.len) break;
                    if (self.partMisses(part, parts[j])) return self.missedPart(part, parts[j], types.part(of, .{ .variant = k }, @intCast(j)));
                }
                return pattern;
            } else {
                // A newtype: a refined one's value is its base's, read in place.
                const inner = self.ast.call(pattern).args[0];
                const base = switch (missed.shape) {
                    .product => |parts| if (parts.len == 1) parts[0] else return pattern,
                    .integers => return inner,
                    else => return pattern,
                };
                return if (self.partMisses(inner, base)) self.missedPart(inner, base, types.part(of, .product, 0)) else pattern;
            },
            .tuple_pattern => {
                const parts = switch (missed.shape) {
                    .product => |p| p,
                    else => return pattern,
                };
                for (self.ast.call(pattern).args, 0..) |part, i| {
                    if (i >= parts.len) break;
                    if (self.partMisses(part, parts[i])) return self.missedPart(part, parts[i], types.part(of, .product, @intCast(i)));
                }
                return pattern;
            },
            .struct_pattern => {
                const parts = switch (missed.shape) {
                    .product => |p| p,
                    else => return pattern,
                };
                const written = self.ast.call(pattern).args;
                var i: usize = 0;
                while (i + 1 < written.len) : (i += 2) {
                    const field = self.field_names.get(self.ast.exprMain(written[i])) orelse continue;
                    const at = field.field.index();
                    if (at >= parts.len) continue;
                    if (self.partMisses(written[i + 1], parts[at])) return self.missedPart(written[i + 1], parts[at], types.part(of, .product, at));
                }
                return pattern;
            },
            else => return pattern,
        }
    }

    /// Whether a part of a pattern leaves out a missed value: a binder or `_`
    /// takes anything, and a pattern takes only what it names.
    fn partMisses(self: *Checker, part: ExprId, missed: PatternCoverage.Witness) bool {
        if (isCatchAll(self.ast, part) or self.ast.partBinds(part)) return false;
        if (missed.isWild()) return false;
        return switch (self.ast.exprTag(part)) {
            .name_ref, .call => if (self.variant_uses.get(part)) |use| switch (missed.shape) {
                .variant => |v| v.index != @intFromEnum(use.ordinal) or self.anyPartMisses(part, v.args),
                else => true,
            } else true,
            .tuple_pattern => switch (missed.shape) {
                .product => |parts| self.anyPartMisses(part, parts),
                else => true,
            },
            .int_literal, .negate, .range => switch (missed.shape) {
                .integers => |iv| if (self.foldedInterval(part)) |range| !(range.lo <= iv.lo and iv.hi <= range.hi) else true,
                else => true,
            },
            else => true,
        };
    }

    fn anyPartMisses(self: *Checker, pattern: ExprId, parts: []const PatternCoverage.Witness) bool {
        if (self.ast.exprTag(pattern) != .call and self.ast.exprTag(pattern) != .tuple_pattern) return false;
        for (self.ast.call(pattern).args, 0..) |part, i| {
            if (i < parts.len and self.partMisses(part, parts[i])) return true;
        }
        return false;
    }

    /// Checks coverage questions with the checker's own types.
    const PatternCoverage = usefulness.Coverage(PatternTypes);

    /// What coverage asks of a type: what constructors build it, and the
    /// type of each part.
    const PatternTypes = struct {
        checker: *Checker,
        pub const Ty = TypeId;

        /// The type coverage splits a column of `ty` by: an observation's
        /// referent, and an open type's settlement. Only the head is
        /// settled, since each part is asked about where its own column is
        /// split, so a column costs the same at every depth.
        fn settled(self: PatternTypes, ty: TypeId) TypeId {
            var t = ty;
            while (true) switch (self.checker.builder.get(t)) {
                .borrow => |observation| t = observation.referent,
                .open_integer => return TypeId.literal_default,
                .open_type => {
                    const resolved = self.checker.builder.resolveOpen(t, &self.checker.open_types) catch return t;
                    if (resolved == t) return t;
                    t = resolved;
                },
                else => return t,
            };
        }

        pub fn kind(self: PatternTypes, ty: TypeId) usefulness.Kind {
            const t = self.settled(ty);
            if (t.bounds()) |b| return .{ .integer = .{ .lo = b.min, .hi = b.max } };
            return switch (self.checker.builder.get(t)) {
                .enum_ => |e| .{ .variants = e.variant_count },
                .struct_ => .{ .product = self.checker.builder.fieldCount(t) },
                // A refined newtype is the integers its refinement admits, so
                // its pattern is read as its base's.
                .newtype => |nt| if (!nt.refined)
                    .{ .product = 1 }
                else if (self.checker.refinedValues(t)) |values|
                    .{ .integer = values }
                else
                    .refused,
                else => .opaque_,
            };
        }

        pub fn arity(self: PatternTypes, ty: TypeId, c: usefulness.Ctor) u32 {
            const t = self.settled(ty);
            return switch (c) {
                .variant => |k| self.checker.builder.variantFieldCount(t, k),
                .product => if (self.checker.builder.get(t) == .newtype) 1 else self.checker.builder.fieldCount(t),
                .integers => 0,
            };
        }

        pub fn part(self: PatternTypes, ty: TypeId, c: usefulness.Ctor, i: u32) TypeId {
            const t = self.settled(ty);
            return switch (c) {
                .variant => |k| self.checker.builder.variantFieldType(t, k, i),
                .product => if (self.checker.builder.get(t) == .newtype) self.checker.builder.baseOf(t) else self.checker.builder.fieldType(t, i),
                .integers => .poison,
            };
        }
    };

    /// A checked, sound pattern as coverage reads it.
    fn coveragePattern(self: *Checker, arena: std.mem.Allocator, pattern: ExprId, of: TypeId) std.mem.Allocator.Error!*const usefulness.Pattern {
        // A variant's record is the checker's answer to what a bare name is:
        // at a `match` arm's head a caseless name such as `_1` names one.
        if (!self.variant_uses.contains(pattern) and (isCatchAll(self.ast, pattern) or self.ast.partBinds(pattern))) return &usefulness.wild;
        const types: PatternTypes = .{ .checker = self };
        const out = try arena.create(usefulness.Pattern);
        switch (self.ast.exprTag(pattern)) {
            .name_ref, .call => if (self.variant_uses.get(pattern)) |use| {
                const k: u32 = @intFromEnum(use.ordinal);
                const written: []const ExprId = if (self.ast.exprTag(pattern) == .call) self.ast.call(pattern).args else &.{};
                const args = try arena.alloc(*const usefulness.Pattern, written.len);
                for (written, 0..) |part, j| args[j] = try self.coveragePattern(arena, part, types.part(of, .{ .variant = k }, @intCast(j)));
                out.* = .{ .variant = .{ .index = k, .args = args } };
            } else if (self.builder.get(types.settled(of)) == .newtype and types.kind(of) == .integer) {
                // A refined newtype's column is its base's integers, so the
                // pattern is what it holds.
                return self.coveragePattern(arena, self.ast.call(pattern).args[0], of);
            } else {
                // A newtype's pattern: its one constructor, around its base.
                const args = try arena.alloc(*const usefulness.Pattern, 1);
                args[0] = try self.coveragePattern(arena, self.ast.call(pattern).args[0], types.part(of, .product, 0));
                out.* = .{ .product = args };
            },
            .tuple_pattern => {
                const written = self.ast.call(pattern).args;
                const args = try arena.alloc(*const usefulness.Pattern, written.len);
                for (written, 0..) |part, i| args[i] = try self.coveragePattern(arena, part, types.part(of, .product, @intCast(i)));
                out.* = .{ .product = args };
            },
            .struct_pattern => {
                const args = try arena.alloc(*const usefulness.Pattern, types.arity(of, .product));
                @memset(args, &usefulness.wild);
                const written = self.ast.call(pattern).args;
                var i: usize = 0;
                while (i + 1 < written.len) : (i += 2) {
                    const field = self.field_names.get(self.ast.exprMain(written[i])) orelse continue;
                    const at = field.field.index();
                    args[at] = try self.coveragePattern(arena, written[i + 1], types.part(of, .product, at));
                }
                out.* = .{ .product = args };
            },
            else => out.* = .{ .integers = self.foldedInterval(pattern) orelse return &usefulness.wild },
        }
        return out;
    }

    /// A checked literal or range pattern's interval, read from the fold
    /// table its check filled, or null where a bound folded to nothing.
    fn foldedInterval(self: *const Checker, pattern: ExprId) ?usefulness.Interval {
        if (self.ast.exprTag(pattern) != .range) {
            const v = self.folds.get(pattern).valueOf() orelse return null;
            return .{ .lo = v, .hi = v };
        }
        const ends = self.ast.rangeEnds(pattern);
        const lo = self.folds.get(ends.lhs).valueOf() orelse return null;
        const hi_written = self.folds.get(ends.rhs).valueOf() orelse return null;
        return .{ .lo = lo, .hi = if (self.ast.rangeInclusive(pattern)) hi_written else hi_written - 1 };
    }

    /// A pattern for a value coverage found, as a program would write it. A
    /// variant carrying nothing in particular is written bare, as a pattern
    /// leaving its payload unnamed is.
    fn witnessText(self: *Checker, w: PatternCoverage.Witness, out: *std.ArrayList(u8)) std.mem.Allocator.Error!void {
        if (w.isWild()) return out.append(self.gpa, '_');
        const types: PatternTypes = .{ .checker = self };
        const t = types.settled(w.ty);
        switch (w.shape) {
            .wild => try out.append(self.gpa, '_'),
            .integers => |iv| {
                // A refined newtype's integers are written inside its name.
                const wrapped = self.builder.get(t) == .newtype;
                if (wrapped) try out.print(self.gpa, "{s}(", .{self.ast.tokenText(self.ast.declName(self.declaringType(t).?))});
                if (iv.lo == iv.hi)
                    try out.print(self.gpa, "{d}", .{iv.lo})
                else
                    try out.print(self.gpa, "{d}..={d}", .{ iv.lo, iv.hi });
                if (wrapped) try out.append(self.gpa, ')');
            },
            .variant => |v| {
                try out.appendSlice(self.gpa, self.view().variantName(t, v.index));
                const named = for (v.args) |a| {
                    if (!a.isWild()) break true;
                } else false;
                if (!named) return;
                try out.append(self.gpa, '(');
                for (v.args, 0..) |a, i| {
                    if (i > 0) try out.appendSlice(self.gpa, ", ");
                    try self.witnessText(a, out);
                }
                try out.append(self.gpa, ')');
            },
            .product => |parts| {
                const decl = self.declaringType(t);
                const tuple = if (self.builder.instanceOf(t)) |inst| self.builder.isTupleDecl(inst.decl) else false;
                if (tuple or decl == null) {
                    try out.append(self.gpa, '(');
                    for (parts, 0..) |a, i| {
                        if (i > 0) try out.appendSlice(self.gpa, ", ");
                        try self.witnessText(a, out);
                    }
                    return out.append(self.gpa, ')');
                }
                try out.appendSlice(self.gpa, self.ast.tokenText(self.ast.declName(decl.?)));
                if (self.builder.get(t) == .newtype) {
                    try out.append(self.gpa, '(');
                    try self.witnessText(parts[0], out);
                    return out.append(self.gpa, ')');
                }
                try out.appendSlice(self.gpa, " { ");
                for (parts, 0..) |a, i| {
                    if (i > 0) try out.appendSlice(self.gpa, ", ");
                    try out.print(self.gpa, "{s}: ", .{self.builder.fieldName(t, @intCast(i))});
                    try self.witnessText(a, out);
                }
                try out.appendSlice(self.gpa, " }");
            },
        }
    }

    /// Exhaustive on purpose. A statement kind added later has to be given an
    /// answer here rather than falling through a chain of tests and reaching
    /// none -- which is a statement whose expression is never checked, so
    /// nothing in it is typed and every rule that reads a type is silent about
    /// it.
    fn checkStmt(self: *Checker, s: StmtId) !void {
        switch (self.ast.stmtTag(s)) {
            // Already diagnosed by the parser.
            .err => {},
            .let_destructure, .let_read_destructure => try self.checkDestructure(s),
            // A `defer` schedules an expression evaluated for its effect, which
            // is what a statement's is -- so both answer to the same rule about
            // a value computed and thrown away.
            .expr_stmt => try self.checkForEffect(s),
            .defer_stmt => {
                try self.refuseAbruptSchedule(s);
                try self.checkForEffect(s);
            },
            .let_decl => try self.checkLet(s),
            .defer_release => try self.checkDeferRelease(s),
        }
    }

    /// The release a `defer let` schedules, checked as the postfix call
    /// `x.release()` it stands for.
    ///
    /// The operation is found by `postfixOperation`, the lookup a written
    /// `x.release()` is answered by, restricted to `Release.release`. A type
    /// that answers only with an inherent `release`, or with none, is refused
    /// here: nothing says that is the one ending the keyword may schedule.
    fn checkDeferRelease(self: *Checker, s: StmtId) !void {
        const id = self.ast.stmtData(s).init;
        const receiver = self.ast.call(id).args[0];
        const release = self.builder.closure_release orelse return self.refuseDeferLet(id, receiver, null);
        const wanted = self.ast.tokenName(self.ast.declName(release.member));
        switch (try self.postfixOperation(id, id, receiver, wanted, release.member, &.{}, null)) {
            .settled => |settled| _ = try self.checkCallOf(id, settled.sig, settled.args, .postfix, null, &.{}),
            .absent => |held| try self.refuseDeferLet(id, receiver, held),
            .refused, .poisoned => _ = self.record(id, .poison),
        }
    }

    fn refuseDeferLet(self: *Checker, id: ExprId, receiver: ExprId, held: ?TypeId) !void {
        _ = self.record(receiver, held orelse .poison);
        _ = self.report(
            .t_defer_let,
            id,
            "`{s}` implements no `Release`, so it has no single ending `defer let` may choose",
            .{if (held) |ty| try self.typeName(ty) else "this type"},
            "write `let`, then `defer` the operation that ends it on every path",
        );
    }

    fn checkDestructure(self: *Checker, s: StmtId) !void {
        {
            const d = self.ast.stmtData(s);

            // The pattern names the type being taken apart, so that type flows
            // into what is being taken apart, exactly as an annotation's does.
            // Without this `let S { a: x } = .{ a = 1 };` was [T-Infer] --
            // and the message said to name a type, which the pattern already
            // did. What the head names is checked below either way: a pattern
            // naming the wrong type is a mistake about the value, not about
            // where the type came from.
            const named: ?Expected = blk: {
                if (d.pattern == ExprId.none) break :blk null;
                if (self.ast.exprTag(d.pattern) != .struct_pattern) break :blk null;
                const callee = self.ast.call(d.pattern).callee;
                if (callee == ExprId.none) break :blk null;
                const head = self.ast.exprMain(callee);
                // A generic type's name alone is a template rather than a
                // type. The pattern carries no arguments and should not have
                // to: which instantiation is being taken apart is what the
                // value is, so the value says, and the head is checked against
                // it below like any other.
                if (self.paramCountOf(self.current, self.generic, head) > 0) break :blk null;
                const ty = self.typeOfToken(head);
                if (ty == .poison) break :blk null;
                break :blk .{
                    .ty = ty,
                    .at = .{ .file = self.ast.fileOf(head), .span = self.ast.tokenSpan(head) },
                    .reason = .annotation,
                };
            };

            const of = try self.check(d.init, named);
            // A consuming `let` takes the value apart, so each name owns what
            // it holds and is a place of its own. A `let read` observes the
            // place instead, so each name stands for the part the pattern
            // selects, exactly as a `match read` arm's binders do.
            var taken = ExprId.none;
            if (self.ast.stmtTag(s) == .let_read_destructure and d.init != ExprId.none and of != .poison and of != .never) {
                // A lend names storage that outlives the statement. A
                // temporary has none, and extending its lifetime would be a
                // storage decision the program never wrote.
                if (self.isAPlace(d.init)) {
                    taken = d.init;
                } else {
                    _ = self.report(.t_lend, d.init, "a borrowed pattern requires a place", .{}, "bind the value before reading it apart");
                }
            }
            // A call-shaped head names a newtype, or one variant of the
            // value's own enum -- a pattern that may not match, which
            // [T-Refutable] says once it is checked. Any other spelling is
            // the newtype check's to refuse.
            const sound = if (self.ast.exprTag(d.pattern) == .call and
                (try self.variantNamed(of, self.ast.tokenText(self.ast.exprMain(d.pattern)))) == null)
                try self.checkNewtypePattern(d.pattern, of, taken)
            else
                try self.checkPattern(d.pattern, of, taken);
            if (sound) try self.refuseRefutable(d.pattern, of);
        }
    }

    /// A scheduled expression may not itself leave the scope.
    ///
    /// A `defer` runs where control leaves, so an expression that leaves from
    /// inside one is a jump out of a scope exit -- a shape the language has
    /// nothing to say about, and one both the ownership builder and lowering
    /// walk into forever because the schedule is still on the stack that
    /// placed it.
    ///
    /// Read from the tree rather than from a lattice: which forms leave is a
    /// question about what was written, and the same question a `break` inside
    /// a loop operand already answers by where it sits.
    fn refuseAbruptSchedule(self: *Checker, s: StmtId) !void {
        const scheduled = self.ast.stmtData(s).init;
        if (scheduled == ExprId.none) return;

        try self.findTheLeaves();
        const extent = self.ast.exprTokens(scheduled);

        // The first one written inside the extent. An expression's tokens are
        // contiguous and a sub-expression's sit within its parent's, so what
        // a `defer` encloses is a range of this array rather than a scan of
        // the program: the answer to "is anything here" is where the search
        // lands.
        var lo: usize = 0;
        var hi: usize = self.leaves.items.len;
        while (lo < hi) {
            const mid = lo + (hi - lo) / 2;
            if (self.leaves.items[mid].at < extent.start.index()) lo = mid + 1 else hi = mid;
        }
        if (lo == self.leaves.items.len) return;

        const found = self.leaves.items[lo];
        if (found.at >= extent.end.index()) return;

        _ = self.report(
            .s_defer,
            found.id,
            "a `defer` runs where control leaves, so what it schedules may not leave as well",
            .{},
            try std.fmt.allocPrint(self.sink.arena, "{s} inside a `defer`", .{found.what}),
        );
    }

    /// Every expression that leaves, in the order they are written.
    ///
    /// Built once and searched per `defer`. Asked the other way round -- every
    /// expression in the program, once for each `defer` -- this was the whole
    /// program walked per statement, which is the same question asked as many
    /// times as there are askers.
    fn findTheLeaves(self: *Checker) std.mem.Allocator.Error!void {
        if (self.leaves_built) return;
        self.leaves_built = true;

        for (0..self.ast.exprCount()) |i| {
            const id = ExprId.at(@intCast(i));
            const what: []const u8 = switch (self.ast.exprTag(id)) {
                .return_ => "`return`",
                .break_ => "`break`",
                .continue_ => "`continue`",
                .try_ => "`?`",
                else => continue,
            };
            try self.leaves.append(self.gpa, .{
                .at = self.ast.exprTokens(id).start.index(),
                .id = id,
                .what = what,
            });
        }

        std.mem.sort(Leave, self.leaves.items, {}, struct {
            fn before(_: void, a: Leave, b: Leave) bool {
                return a.at < b.at;
            }
        }.before);
    }

    fn checkForEffect(self: *Checker, s: StmtId) !void {
        {
            const e = self.ast.stmtData(s).init;
            if (e == ExprId.none) return;
            const t = try self.check(e, null);

            // A value computed and not bound is a value thrown away.
            if (t != .unit and t != .never and t != .poison) {
                // `let _` is the deliberate discard for every value but one.
                // Advising it for a `Result` would send the reader to
                // [T-DiscardFailure], so the hint names what that rule accepts
                // instead: one diagnostic must not recommend the next.
                const reports_failure = if (self.carrierOf(t)) |c| c.kind == .result else false;
                // A function named on its own line was almost always meant to
                // be called.
                const named = self.res.targetOf(self.ast.withoutGroups(e));
                const names_function = named != BindingId.none and self.res.kindOf(named) == .function;
                _ = self.report(
                    .t_discard,
                    e,
                    "this expression produces {s} `{s}` that is discarded",
                    .{ article.before(try self.typeName(t)), (try self.typeName(t)) },
                    if (reports_failure)
                        "match it, hand it on with `?`, or return it"
                    else if (names_function)
                        "call it with `(...)`, or bind it with `let _ =` to discard it deliberately"
                    else
                        "bind it with `let _ =` to discard it deliberately",
                );
            }
            return;
        }
    }

    fn checkLet(self: *Checker, s: StmtId) !void {
        const d = self.ast.stmtData(s);
        const b = self.res.bindingOf(s);

        const annotated: ?Expected = if (!d.annotation.wasWritten()) null else blk: {
            // An annotation that names nothing, or that the parser could not
            // read, was reported where it is written, and it still gives the
            // initialiser its context: poison, so a literal that needs a type
            // is not reported as lacking one, and nothing in the value is
            // held against a type nobody knows.
            const ty = try self.bindingTypeCountingLiteral(d.annotation, d.init);
            break :blk .{
                .ty = ty,
                .at = self.locOfWritten(d.annotation),
                .reason = .annotation,
                .alias = self.aliasHeading(self.generic, d.annotation),
            };
        };

        const t = if (d.init == ExprId.none)
            TypeId.poison
        else
            try self.check(d.init, annotated);

        // `let _ = e` is how a program says it does not want a value, and for
        // every value but one that is a complete answer. A `Result` is a report
        // that something may not have happened, and binding it to `_` is the
        // only way left to receive that report and say nothing -- [T-Discard]
        // catches the bare statement and [N-Unused] catches a name nothing
        // reads, so this is the last hole and it is the one that looks
        // deliberate.
        //
        // What this asks for is acknowledgement rather than observation. A
        // `match` whose only arm is `_` still passes, because it is written
        // down: the program named the alternatives and chose to treat them
        // alike, which a reader sees. `let _` says the value was never there.
        if (d.pattern == ExprId.none and std.mem.eql(u8, self.ast.tokenText(d.name), "_")) {
            if (self.carrierOf(t)) |c| {
                if (c.kind == .result) {
                    _ = self.report(
                        .t_discard_failure,
                        d.init,
                        "this `{s}` reports a failure, and `_` discards it",
                        .{(try self.typeName(t))},
                        "match it, hand it on with `?`, or return it",
                    );
                }
            }
        }

        if (b != BindingId.none and d.init != ExprId.none and !d.annotation.wasWritten()) {
            const made_by = self.ast.withoutGroups(d.init);
            if (self.defaulted_calls.contains(made_by)) try self.defaulted_bindings.put(self.gpa, b, made_by);
        }

        if (b != BindingId.none) {
            // A written annotation that could not be read leaves the binding
            // poisoned rather than typed by its initialiser, so its uses report
            // nothing more.
            const bound = if (annotated) |a| a.ty else if (d.annotation.wasWritten()) TypeId.poison else t;
            self.setBindingType(b, bound);
            const labels = if (d.annotation.wasWritten())
                self.labelSources().ofWritten(d.annotation, bound)
            else if (d.init != ExprId.none) self.calleeLabels(d.init) else null;
            if (labels) |params| try self.binding_labels.put(self.gpa, b, self.ast.paramRangeOf(params));

            if (d.init != ExprId.none) {
                self.binding_value_locs[b.index()] = .{
                    .file = self.ast.fileOfExpr(d.init),
                    .span = self.ast.exprSpan(d.init),
                };
            }
        }
    }

    const ConstantDependencies = struct { bindings: []const BindingId, next: usize = 0 };

    /// Takes a constant as far as knowing what it is worth, once.
    ///
    /// Called wherever a name reaching a constant needs what it stands for,
    /// which is what makes the answer the same whichever order the
    /// declarations were written in. A constant whose initialiser names
    /// another takes that one first, so the value is there by the time the
    /// name is read.
    ///
    /// The site is marked open while its initialiser is taken, and a name
    /// reaching an open site is what a ring is. That mark is the fold's own, so
    /// the walk that types a constant and the walk that works out what it is
    /// worth test against one mark rather than one apiece.
    /// A chain of constants naming one another is followed down and back with
    /// a list rather than by taking each one inside the last: the definition
    /// says nothing about how long such a chain may be, so a walk asking one
    /// frame deeper per link bounds a program by what a stack holds.
    fn ensureConstant(self: *Checker, b: BindingId) std.mem.Allocator.Error!void {
        if (self.constant_taken[b.index()]) return;
        if (self.folded.isOpen(self.siteOf(b))) return self.reportRing(b);

        const floor = self.constant_ring.items.len;
        try self.openConstant(b);
        while (self.constant_ring.items.len > floor) {
            const top = self.constant_ring.getLast();
            // Taken innermost first, so by the time an initialiser is checked
            // every constant it names is already worth something and the walk
            // that reads one comes straight back.
            if (self.nextConstantDependency()) |next| {
                try self.openConstant(next);
                continue;
            }
            try self.checkConstant(top);
            self.closeConstant();
        }
    }

    fn openConstant(self: *Checker, b: BindingId) std.mem.Allocator.Error!void {
        var dependencies: std.ArrayList(BindingId) = .empty;
        defer dependencies.deinit(self.gpa);
        const declaration = self.res.declaredBy(b);
        try self.constantDependenciesWithinRef(self.ast.declReturnRef(declaration), &dependencies);
        try self.constantDependenciesWithin(self.ast.declInit(declaration), &dependencies);
        const bindings = try dependencies.toOwnedSlice(self.gpa);
        errdefer self.gpa.free(bindings);
        try self.constant_ring.ensureUnusedCapacity(self.gpa, 1);
        try self.constant_dependencies.ensureUnusedCapacity(self.gpa, 1);
        try self.folded.open(self.gpa, self.siteOf(b));
        self.constant_ring.appendAssumeCapacity(b);
        self.constant_dependencies.appendAssumeCapacity(.{ .bindings = bindings });
    }

    fn closeConstant(self: *Checker) void {
        const b = self.constant_ring.pop().?;
        self.gpa.free(self.constant_dependencies.pop().?.bindings);
        // Given up rather than settled: what this walk took the initialiser for
        // was its type, and what it is worth stays the fold's to say.
        self.folded.close(self.siteOf(b));
        self.constant_taken[b.index()] = true;
    }

    /// Each initializer is scanned once. Open dependencies are diagnosed by
    /// ordinary checking at the reference that closes the shared fold ring.
    fn nextConstantDependency(self: *Checker) ?BindingId {
        const work = &self.constant_dependencies.items[self.constant_dependencies.items.len - 1];
        while (work.next < work.bindings.len) {
            const target = work.bindings[work.next];
            work.next += 1;
            if (!self.constant_taken[target.index()] and !self.folded.isOpen(self.siteOf(target))) return target;
        }
        return null;
    }

    fn constantDependenciesWithinRef(self: *Checker, ref: node.TypeRef, out: *std.ArrayList(BindingId)) std.mem.Allocator.Error!void {
        try self.constantDependenciesWithin(ref.length, out);
        for (self.ast.typeArgs(ref.args)) |arg| try self.constantDependenciesWithinRef(arg, out);
    }

    fn constantDependenciesWithin(self: *Checker, id: ExprId, out: *std.ArrayList(BindingId)) std.mem.Allocator.Error!void {
        if (id == .none) return;
        const target = self.res.targetOf(id);
        if (target != .none and self.res.kindOf(target) == .constant) try out.append(self.gpa, target);
        switch (self.ast.exprTag(id).payload()) {
            .none => {},
            .unary => try self.constantDependenciesWithin(self.ast.unaryOperand(id), out),
            .binary => {
                const two = self.ast.binary(id);
                try self.constantDependenciesWithin(two.lhs, out);
                try self.constantDependenciesWithin(two.rhs, out);
            },
            .conditional => {
                const conditional = self.ast.conditional(id);
                try self.constantDependenciesWithin(conditional.cond, out);
                try self.constantDependenciesWithin(conditional.then, out);
                try self.constantDependenciesWithin(conditional.otherwise, out);
            },
            .range => {
                const ends = self.ast.rangeEnds(id);
                try self.constantDependenciesWithin(ends.lhs, out);
                try self.constantDependenciesWithin(ends.rhs, out);
            },
            .call => {
                const call = self.ast.call(id);
                try self.constantDependenciesWithin(call.callee, out);
                for (call.args) |arg| try self.constantDependenciesWithin(arg, out);
            },
            .interpolation => {
                for (self.ast.interpolation(id).pieces) |piece| try self.constantDependenciesWithin(piece, out);
            },
            .lambda => {
                const lambda = self.ast.lambda(id);
                for (lambda.captures) |capture| try self.constantDependenciesWithin(capture.source, out);
                for (lambda.params) |param| try self.constantDependenciesWithin(param.default, out);
                try self.constantDependenciesWithin(lambda.body, out);
            },
            .block => {
                const body = self.ast.blockOf(id);
                for (self.ast.blockStmts(body)) |statement| {
                    const held = self.ast.stmtData(statement);
                    try self.constantDependenciesWithin(held.init, out);
                    try self.constantDependenciesWithin(held.pattern, out);
                }
                try self.constantDependenciesWithin(body.tail, out);
            },
        }
    }

    /// Where a binding was declared, in the terms the fold keys a site by.
    fn siteOf(self: *const Checker, b: BindingId) constfold.Reach {
        return .{ .decl = self.res.declaredBy(b) };
    }

    /// Preserve type-dependent non-constant classification in both consumers.
    fn markNotConstant(self: *Checker, id: ExprId) std.mem.Allocator.Error!void {
        self.folds.set(id, .not_constant);
        try self.folded.recordNotConstant(self.gpa, id);
    }

    /// What an expression is worth, remembered by the shared constant folder.
    fn worth(self: *Checker, id: ExprId) std.mem.Allocator.Error!constfold.Value {
        return constfold.foldConstant(self.gpa, self.ast, self.res.nameSites(), &self.folded, id);
    }

    /// Whether a folded value was admitted as a constant of a type, and where
    /// it was not because a type it is built from is not copyable, which one.
    /// That type is what a report names, since marking it copyable is the fix.
    const Planned = union(enum) {
        planned,
        refused,
        uncopyable: TypeId,
    };

    /// Admit concrete Copyable data and record its typed materialization.
    /// A scalar held by a newtype is planned like data, because the newtype's
    /// own capability decides whether it may be a constant.
    fn validateConstant(self: *Checker, value: types_mod.ConstantValue, ty: TypeId) std.mem.Allocator.Error!Planned {
        return switch (value) {
            .aggregate => |id| self.planConstant(id, ty),
            else => if (ty != .poison and self.builder.get(ty) == .newtype)
                self.planConstant(try value.node(self.gpa, &self.folded.pool), ty)
            else
                .planned,
        };
    }

    fn planConstant(self: *Checker, id: types_mod.constants.ConstantId, ty: TypeId) std.mem.Allocator.Error!Planned {
        const key: types_mod.ConstantMaterializationKey = .{ .value = id, .ty = ty };
        if (self.constant_materializations.contains(key)) return .planned;
        if (ty == .poison or !try self.constant_groundness.check(self.gpa, &self.builder, ty)) return .refused;
        // A newtype's constant is its base's value under the newtype's name.
        // Every read builds it afresh, so the newtype must itself be Copyable
        // whatever it holds; lowering erases the name and materializes the
        // base's plan.
        if (self.builder.get(ty) == .newtype) {
            if (try self.builder.capabilityOf(ty) != .copyable) return .{ .uncopyable = ty };
            return self.planConstant(id, self.builder.baseOf(ty));
        }
        const stored = self.folded.pool.get(id);
        if (stored != .variant and try self.builder.capabilityOf(ty) != .copyable) return .{ .uncopyable = ty };
        const shape = self.builder.get(ty);
        var plan: types_mod.ConstantMaterialization = .{};
        errdefer self.gpa.free(plan.fields);
        switch (stored) {
            .integer => if (ty.integerInfo() == null) return .refused,
            .truth => if (shape != .boolean) return .refused,
            .string => {},
            .unit => if (shape != .unit) return .refused,
            .array => |values| {
                if (shape != .array or shape.array.count != values.len) return .refused;
                for (values) |child| {
                    const planned = try self.planConstant(child, shape.array.element);
                    if (planned != .planned) return planned;
                }
            },
            .record => |fields| {
                if (shape != .struct_ or self.builder.fieldCount(ty) != fields.len) return .refused;
                const ordinals = try self.gpa.alloc(types_mod.FieldOrdinal, fields.len);
                plan.fields = ordinals;
                for (fields, ordinals) |field, *ordinal| {
                    const selected = self.builder.lookupField(ty, field.name) orelse {
                        self.gpa.free(plan.fields);
                        return .refused;
                    };
                    ordinal.* = @enumFromInt(selected.index);
                    const planned = try self.planConstant(field.value, selected.ty);
                    if (planned != .planned) {
                        self.gpa.free(plan.fields);
                        return planned;
                    }
                }
            },
            .variant => |variant| {
                if (shape != .enum_) return .refused;
                const ordinal = (try self.variantNamed(ty, variant.name)) orelse return .refused;
                const declared = self.builder.variantFieldCount(ty, ordinal);
                if (declared != variant.payloads.len) return .refused;
                // A variant the enum declares without fields stores nothing, so
                // it duplicates freely even where a sibling's payload leaves the
                // enum affine.
                if (declared != 0 and try self.builder.capabilityOf(ty) != .copyable) return .{ .uncopyable = ty };
                plan.variant = @enumFromInt(ordinal);
                for (variant.payloads, 0..) |child, i| {
                    const planned = try self.planConstant(child, self.builder.variantFieldType(ty, ordinal, @intCast(i)));
                    if (planned != .planned) return planned;
                }
            },
        }
        try self.constant_materializations.put(self.gpa, key, plan);
        return .planned;
    }

    /// A constant's initializer supplies its type unless an annotation
    /// constrains it, and must be a constant expression.
    ///
    /// Nothing runs where a constant is declared, so an initialiser the
    /// language cannot work out has no value to bind.
    ///
    fn checkConstant(self: *Checker, b: BindingId) std.mem.Allocator.Error!void {
        const d = self.res.declaredBy(b);
        const init_expr = self.ast.declInit(d);
        if (init_expr == ExprId.none) return;

        // Saved rather than cleared, because this runs inside the check of
        // whichever constant named this one and that check has more to do.
        const outer_module = self.current;
        const outer_generic = self.generic;
        self.current = self.program.moduleOf(d);
        self.generic = d;
        defer {
            self.current = outer_module;
            self.generic = outer_generic;
        }

        const annotation = self.ast.declReturnRef(d);
        const want = self.binding_types.get(b);
        const annotated: ?Expected = if (!annotation.wasWritten() or want == .poison) null else .{
            .ty = want,
            // The written type and not its first token: a settled reference
            // underlined by its head is `Self`, which is a different type from
            // the one the expectation came from.
            .at = self.locOfWritten(annotation),
            .reason = .annotation,
            .alias = self.aliasHeading(self.generic, annotation),
        };
        if (self.ast.declTag(d) == .traversal_) {
            const params = self.ast.declParams(d);
            if (params.len > 1 or (params.len == 1 and
                (params[0].convention != .read or !refNamesSelf(self.ast, params[0].written) or
                    params[0].written.args.len() != 0 or params[0].default != .none)))
            {
                _ = self.report(.t_lend, init_expr, "a traversal receiver is one `read` parameter of type `Self` without a default", .{}, "omit the receiver or declare `(self: Self)`");
            }
        }
        // A constant's type is settled before anything outside its
        // initializer reads it, so its open literals fall back here.
        const scope = self.openScope();
        const initializer_type = try self.check(init_expr, annotated);
        try self.closeScope(scope);
        const inferred = try self.builder.resolveOpen(initializer_type, &self.open_types);
        if (!annotation.wasWritten()) self.setBindingType(b, inferred);
        // A written type that failed to resolve was reported where it is
        // written, and a constant with no type has no value to check.
        if (annotation.wasWritten() and want == .poison) return;

        // An initialiser the checker poisoned has already been told what is
        // wrong with it, and whether the definition admits its form is a
        // question about an expression that no longer exists.
        if (self.builder.exprType(init_expr) == .poison) return;

        // A traversal binds a name to an expression the same way, and is held
        // to a different demand: what it names is an iterator a walk runs,
        // built where the walk is, so nothing works it out where it is
        // written and there is no value for a constant expression to be.
        if (self.ast.declTag(d) == .traversal_) return self.checkTraversal(init_expr);

        // Whether the form is one the definition admits, decided by the routine
        // that folds a constant expression wherever one is read and by nothing
        // here. A constant on a ring is worth nothing rather than off the list,
        // so it is not told separately that its form is wrong -- the ring is
        // the whole of what is wrong with it, and that was reported where it
        // closed.
        const value = try self.worth(init_expr);
        if (value.checked()) |checked| {
            if (try self.refuseObligedConstant(.t_const, init_expr, self.binding_types.get(b))) return;
            switch (try self.validateConstant(checked, self.binding_types.get(b))) {
                .planned => {
                    try self.constant_values.put(self.gpa, b, checked);
                    return;
                },
                .uncopyable => |ty| return self.reportUncopyableConstant(.t_const, init_expr, ty, "a constant is copied wherever it is read"),
                .refused => {},
            }
        } else if (value.isConstant()) return;
        try self.sink.addErrorFmt(
            .t_const,
            self.ast.fileOfExpr(init_expr),
            self.ast.exprSpan(init_expr),
            if (self.holdsEmptyBlock(init_expr))
                empty_block_is_not_a_constant
            else
                "give it something the language can work out without running anything",
            "`{s}` is not a constant expression",
            .{self.ast.tokenText(self.ast.declName(d))},
        );
    }

    /// A constant reached from its own initialiser, directly or around a ring
    /// of constants naming each other.
    ///
    /// Nothing orders one declaration against another, so a ring is written
    /// rather than caught by a scope, and it has no value: every member waits
    /// on the next and the last waits on the first. Reported once, where the
    /// ring closes, and every member is marked so none of them is told
    /// separately that its initialiser is not a constant expression -- that is
    /// true of all of them and explains none of them.
    ///
    /// A member is worth nothing rather than worth an answer withheld, so its
    /// entry says so before the walk unwinds through it. That is what a name
    /// outside the ring reads, and a constant naming one is a constant naming
    /// a binding that cannot be assigned again -- the ring is the whole of
    /// what is wrong there too, and it has been said already.
    fn reportRing(self: *Checker, b: BindingId) std.mem.Allocator.Error!void {
        const closes = std.mem.indexOfScalar(BindingId, self.constant_ring.items, b).?;
        const ring = self.constant_ring.items[closes..];

        // Marked whether or not this ring is the one reported, because every
        // constant on it is without a value either way. A second ring closing
        // on a constant already reported for one is the same thing wrong with
        // the same name: `a = a + a` comes back around twice and has one fault.
        const said = self.ring_said[b.index()];
        for (ring) |m| self.ring_said[m.index()] = true;
        if (said) return;

        // The reference that closed the ring, which is the one being checked:
        // the constant it names is the one the ring comes back to, and the
        // constant holding it is the last one the walk entered.
        const d = self.res.declaredBy(b);
        const through = self.res.declaredBy(self.constant_ring.items[self.constant_ring.items.len - 1]);
        const at = self.ast.declInit(through);
        const name = self.ast.tokenText(self.ast.declName(d));

        if (ring.len == 1) {
            try self.sink.addErrorFmt(
                .t_const,
                self.ast.fileOfExpr(at),
                self.ast.exprSpan(at),
                "a constant's value cannot be worked out from itself",
                "`{s}` names itself",
                .{name},
            );
            return;
        }
        try self.sink.addErrorFmt(
            .t_const,
            self.ast.fileOfExpr(at),
            self.ast.exprSpan(at),
            "a constant's value cannot be worked out from itself",
            "`{s}` names itself through `{s}`",
            .{ name, self.ast.tokenText(self.ast.declName(through)) },
        );
    }

    /// Forward a result constraint only into a construct's value-producing
    /// child, never its conditions, statements, or scrutinee.
    fn checkResult(self: *Checker, parent: ExprId, child: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const previous = self.success_expected;
        defer self.success_expected = previous;
        if (previous) |want| if (want.target == self.ast.withoutGroups(parent)) {
            self.success_expected = .{
                .target = self.ast.withoutGroups(child),
                .depth = want.depth,
                .expected = want.expected,
            };
        };
        const previous_failure = self.failure_expected;
        defer self.failure_expected = previous_failure;
        if (previous_failure) |want| if (want.target == self.ast.withoutGroups(parent)) {
            self.failure_expected = .{ .target = self.ast.withoutGroups(child), .depth = want.depth, .expected = want.expected };
        };
        return self.check(child, expected);
    }

    fn check(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        if (expected) |want| if (self.builder.get(want.ty) == .open_type) {
            // A type a function value's uses are settling flows in as what it
            // settled to. Until it settles it says nothing about the
            // expression, which is checked on its own and then met with it.
            var settled = want;
            settled.ty = try self.builder.resolveOpen(want.ty, &self.open_types);
            const open = self.openVariable(settled.ty) orelse return self.check(id, settled);
            const actual = try self.checkInner(id, null);
            // An expression already reported settles nothing, and the type it
            // would have settled stands for poison rather than being reported
            // again as one no use settled.
            if (actual == .poison) {
                self.open_types.abandon(open);
                return actual;
            }
            return self.expect(id, actual, settled);
        };
        if (expected) |want| if (!want.callable_context) if (want.inference) |settling| {
            const resolved = try self.callableContext(want.ty, settling);
            var context = want;
            context.ty = resolved;
            if (!self.hasOpenParameter(resolved, settling)) {
                context.inference = null;
                return self.checkInner(id, context);
            }
            const actual = try self.checkInner(id, if (self.builder.get(resolved) == .parameter) null else context);
            if (actual == .poison or actual == .never) return actual;
            for (settling) |slot| {
                var clash: ?Clash = null;
                if (!try self.settleByInContext(resolved, actual, slot.owner, slot.found, &clash, .signature_types, settling))
                    return self.reportMismatch(id, actual, want, "");
            }
            const settled_actual = try self.callableContext(actual, settling);
            context.ty = try self.callableContext(resolved, settling);
            context.inference = null;
            return self.expect(id, settled_actual, context);
        };
        return self.checkInner(id, expected);
    }

    /// Checks one expression. A poison result no mismatch report accounts for
    /// is a refusal, whether or not the refusing path recorded it against `id`.
    fn checkInner(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const checked = try self.checkExpression(id, expected);
        if (checked == .poison and self.mismatched != id) self.refused.put(self.gpa, id, {}) catch {};
        return checked;
    }

    fn checkExpression(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        return switch (self.ast.exprTag(id)) {
            // Already diagnosed by the parser.
            .err, .reflection_root => self.record(id, .poison),

            .block => self.checkBody(id, expected),

            .lambda => self.checkLambda(id, expected),

            .conditional => self.checkConditional(id, expected),

            .int_literal => self.checkLiteral(id, expected),

            .float_literal => self.checkFloatLiteral(id, expected),

            .str_literal => self.checkStrLiteral(id, expected),
            .embed, .embed_bytes => self.checkEmbed(id, expected),

            .bool_literal => self.checkBoolLiteral(id, expected),

            .unit_literal => self.expect(id, .unit, expected),

            .eq, .ne, .lt, .le, .gt, .ge => self.checkComparison(id, expected),

            .name_ref => blk: {
                const target = self.res.targetOf(id);
                if (target == BindingId.none) break :blk self.record(id, .poison);

                if (self.res.kindOf(target) == .function) {
                    if (try self.selectFunctionValue(id, self.res.declaredBy(target), expected, null)) |selected| {
                        break :blk selected;
                    }
                }

                // A name that reaches a test, an `extern`, a type, a trait or
                // a module is one written where a value belongs: a call
                // resolves its own callee and a written type is read as a
                // type, so what is left here is the value position. There is
                // nothing for such a name to evaluate to, and it is the one
                // shape a discarded expression can take that T-Discard cannot
                // see, because it has no type to report as discarded.
                const refused = if (self.res.kindOf(target) == .function)
                    self.ineligibleFunction(self.res.declaredBy(target))
                else
                    notAValue(self.res.kindOf(target));
                if (refused) |what| {
                    try self.sink.addErrorFmt(
                        .n_not_a_value,
                        self.ast.fileOfExpr(id),
                        self.ast.exprSpan(id),
                        what.hint,
                        "`{s}` is {s}, and {s} is not a value",
                        .{ self.ast.tokenText(self.ast.exprMain(id)), what.noun, what.noun },
                    );
                    break :blk self.record(id, .poison);
                }

                // A name reaching a constant is what its initialiser is worth,
                // and that is asked for here rather than settled beforehand:
                // nothing orders one declaration against another, so the
                // constant this reaches may be written below the one reading
                // it and may not have been taken yet.
                if (self.res.kindOf(target) == .constant) try self.ensureConstant(target);

                const t = self.binding_types.get(target);
                self.folds.set(id, .of(try self.worth(id)));
                break :blk try self.expect(id, t, expected);
            },

            .grouped => blk: {
                const operand = self.ast.unaryOperand(id);
                const t = try self.check(operand, expected);
                self.folds.set(id, self.folds.get(operand));
                if (!self.folds.get(operand).isConstant()) try self.markNotConstant(id);

                break :blk self.record(id, t);
            },

            .negate => self.checkNegate(id, expected),
            .not => self.checkNot(id, expected),
            .from_end => self.checkFromEnd(id, expected),
            .logical_and, .logical_or => self.checkLogical(id, expected),

            .add, .sub, .mul, .div, .rem => self.checkBinary(id, expected),

            .range => self.checkRange(id, expected),

            .while_ => self.checkWhile(id, expected),

            .for_, .for_read, .for_inout => self.checkFor(id, expected),

            .loop_ => self.checkLoop(id, expected),

            .break_ => self.checkBreak(id, expected),

            .return_ => self.checkReturn(id, expected),

            .continue_ => self.checkContinue(id, expected),

            .assign => self.checkAssign(id, expected),

            .add_assign, .sub_assign, .mul_assign, .div_assign, .rem_assign => self.checkCompoundAssign(id, expected),

            .call => self.checkCall(id, expected),

            .match_, .match_read => self.checkMatch(id, expected),
            .copy_ => self.checkCopy(id, expected),
            .borrow => self.checkBorrow(id, expected),
            .dereference => self.checkDereference(id, expected),
            .panic => self.checkPanic(id),
            .try_ => self.checkTry(id, expected),
            .unwrap_else => self.checkUnwrapElse(id, expected),
            // Reached only through whatever destructures it, which types the
            // pattern against the value it is taking apart.
            .struct_pattern, .tuple_pattern => self.record(id, .poison),
            // Typed with its parameter, where the lambda is checked.
            .param_argument => self.record(id, .poison),
            .tuple_literal => self.checkTupleLiteral(id, expected),

            .field => self.checkSelection(id, expected),

            .struct_literal => self.checkStructLiteral(id, expected),

            .interp => self.checkInterp(id, expected),
            .array_literal => self.checkArrayLiteral(id, expected),

            .index => self.checkIndex(id, expected),

            // A variant has its enum's type. `.Red` with no qualifier takes
            // the type from context, which is the same rule a struct literal
            // uses: a leading `.` means the type is the one expected here.
            .variant_ref => blk: {
                if (try self.selectConstructorValue(id, expected)) |selected| break :blk selected;
                const target = self.res.targetOf(id);
                if (target != BindingId.none) {
                    const d = self.res.declaredBy(target);
                    const q = self.ast.unaryOperand(id);
                    const t = try self.aliasVariantType(id, q, expected) orelse self.instanceFor(d, expected) orelse
                        break :blk self.reportWrongInstance(id, d, expected);
                    if (t == .poison) break :blk self.record(id, .poison);
                    // The qualifier names the type rather than a value, and
                    // every expression ends with exactly one type.
                    if (q != ExprId.none) _ = self.record(q, t);
                    if (self.buildsSealedVariant(t, self.variantOrdinal(id)))
                        break :blk self.reportSealed(id, t, "only its own module can build one");
                    if (self.variantOrdinal(id)) |ordinal| if (self.missingPayload(id, t, ordinal, expected)) |refused| break :blk refused;
                    break :blk try self.foldVariantReference(id, try self.expect(id, t, expected));
                }
                if (Expected.typeOf(expected)) |want| {
                    if (want == .poison) break :blk self.record(id, .poison);

                    // Taken on trust this lowers to a tag the enum does not
                    // have, and the `match` it feeds falls through every arm.
                    // The qualified form has always looked the name up; this
                    // is the same question asked of the type context supplies.
                    const spelling = self.ast.tokenText(self.ast.exprMain(id));
                    const ordinal = (try self.variantNamed(want, spelling)) orelse {
                        break :blk self.report(
                            .n_variant,
                            id,
                            "`{s}` is not a variant of `{s}`",
                            .{ spelling, (try self.typeName(want)) },
                            "not a variant of the type expected here",
                        );
                    };
                    if (self.buildsSealedVariant(want, ordinal))
                        break :blk self.reportSealed(id, want, "only its own module can build one");
                    try self.variant_uses.put(self.gpa, id, .{ .ordinal = @enumFromInt(ordinal) });
                    if (self.missingPayload(id, want, @intCast(ordinal), expected)) |refused| break :blk refused;
                    break :blk try self.foldVariantReference(id, self.record(id, want));
                }
                break :blk self.report(
                    .t_infer,
                    id,
                    "the type of this variant cannot be determined",
                    .{},
                    "name its enum, or give the binding a type",
                );
            },

            .marked => blk: {
                _ = try self.check(self.ast.unaryOperand(id), expected);
                break :blk self.report(.s_mutation, id, "`&` marks an argument passed for mutation, or the iterator a plain `for` walks", .{}, "it belongs at a call site or directly after `in`, and nowhere else");
            },
        };
    }

    /// An integer literal is a constant expression whatever it says, so every
    /// way of failing here leaves one with no value rather than something the
    /// definition does not admit.
    /// A string literal is the library's `Str`, reached the way `Option` is.
    ///
    /// Nothing about text is the compiler's to define: what a literal *is* is
    /// declared in `std/text/`, and all the compiler knows is which
    /// declaration to name and where to put the bytes.
    fn checkStrLiteral(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const d = self.str_decl orelse return self.report(
            .t_literal,
            id,
            "text has no type here: the prelude declares no `Str`",
            .{},
            "build against a library that declares it",
        );

        return try self.expect(id, self.type_of_decl.get(d), expected);
    }

    /// `embed` is text, typed as a string literal is; `embed_bytes` is the
    /// library's byte slice, `mem.Slice[UInt8]`. A refused embed has its type
    /// all the same: the loader reported it, and what uses it is still checked.
    fn checkEmbed(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        if (self.ast.exprTag(id) == .embed) return self.checkStrLiteral(id, expected);
        const d = self.raw_accesses.slice;
        if (d == .none) return self.report(
            .t_literal,
            id,
            "bytes have no type here: the library declares no `mem.Slice`",
            .{},
            "build against a library that declares it",
        );
        const bytes = try self.builder.instantiate(self.type_of_decl.get(d), d, &.{.u8});
        return try self.expect(id, bytes, expected);
    }

    fn checkPanic(self: *Checker, id: ExprId) std.mem.Allocator.Error!TypeId {
        const d = self.str_decl orelse return self.report(
            .t_literal,
            id,
            "panic has no message type here: the prelude declares no `Str`",
            .{},
            "build against a library that declares it",
        );
        _ = try self.check(self.ast.unaryOperand(id), .{
            .ty = self.type_of_decl.get(d),
            .at = self.locOf(id),
            .reason = .panic_message,
        });
        return self.record(id, .never);
    }

    /// `lo..hi` or `lo..=hi`: a construction of `Range`, reached the way
    /// `Option` and `Result` are, at the instantiation the ends settle.
    ///
    /// Though `Range` is an ordinary generic struct, only an integer
    /// instantiation is ever constructed this way -- an end of some other
    /// type is refused here, at the one place that decides it.
    fn checkRange(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const ends = self.ast.rangeEnds(id);

        // `Range[T]` flows `T` into both ends the way an expected type
        // always flows into a construction's parts. Anything else expected
        // here says nothing about either end, and is left to the ordinary
        // mismatch this range's own instantiation reports at the close.
        const end_expected: ?Expected = blk: {
            const want = expected orelse break :blk null;
            if (want.ty == .poison) break :blk null;
            const decl = self.range_decl orelse break :blk null;
            const inst = self.builder.instanceOf(want.ty) orelse break :blk null;
            if (inst.decl != decl) break :blk null;
            break :blk .{ .ty = self.builder.argsOf(inst)[0], .at = want.at, .reason = want.reason };
        };

        // Check a known endpoint before defaulting a waiting literal. Scalar
        // strings are numeric literals here, unlike ordinary string arguments.
        // This chooses typing order only; the AST retains evaluation order.
        const lhs_known = self.ast.exprTag(ends.lhs) != .str_literal and self.determinesItsOwnType(ends.lhs);
        const rhs_known = self.ast.exprTag(ends.rhs) != .str_literal and self.determinesItsOwnType(ends.rhs);
        const right_first = end_expected == null and !lhs_known and rhs_known;
        const first = if (right_first) ends.rhs else ends.lhs;
        const second = if (right_first) ends.lhs else ends.rhs;
        const first_type = try self.checkRangeEnd(first, end_expected);
        const second_type = try self.checkRangeEnd(second, if (first_type == .never) null else end_expected orelse Expected{
            .ty = first_type,
            .at = self.locOf(first),
            .reason = .range_end,
        });
        const lhs = if (right_first) second_type else first_type;
        const rhs = if (right_first) first_type else second_type;

        // A poisoned end already reported what is wrong with it; the range
        // built from it has nothing further to say.
        if (lhs == .poison or rhs == .poison) return self.record(id, .poison);
        if (lhs == .never or rhs == .never) return self.expect(id, .never, expected);

        if (lhs.integerInfo() == null and self.builder.get(lhs) != .open_integer) {
            return self.reportAtOp(
                .t_mismatch,
                id,
                "a range's ends are integers, and `{s}` is not",
                .{(try self.typeName(lhs))},
                "not an integer type",
            );
        }

        const decl = self.range_decl orelse return self.report(
            .t_literal,
            id,
            "a range has no type here: the prelude declares no `Range`",
            .{},
            "build against a library that declares it",
        );

        const made = try self.builder.instantiate(self.type_of_decl.get(decl), decl, &.{lhs});
        return self.expect(id, made, expected);
    }

    /// Folds one of a refinement clause's bounds into the value it names.
    ///
    /// The bound is a literal by the v0 rule, so this is the same parse
    /// `checkLiteral` runs on a literal expression -- without the fold table,
    /// because there is no expression here to route through it, only the
    /// tokens the parser read. The minus is applied here rather than parsed
    /// into the digits: a bound is a sign and a magnitude wherever one is
    /// written, and the sign is a token of its own in both places.
    fn foldRefinementBound(self: *Checker, bound: node.Bound) i128 {
        const text = self.ast.tokenText(bound.digits);
        const magnitude = constfold.literalValue(text) orelse blk: {
            self.sink.addError(
                .t_literal,
                self.ast.fileOf(bound.digits),
                self.ast.tokenSpan(bound.digits),
                "integer literal is too large",
                "no integer type can hold this",
            ) catch {};
            break :blk 0;
        };
        return if (bound.minus == TokenId.none) magnitude else -magnitude;
    }

    /// Parses and range-checks the Float64 value once. Its rounded value is
    /// retained for emission without admitting floats as constant expressions.
    fn checkFloatLiteral(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        self.folds.set(id, .not_constant);

        const text = self.ast.tokenText(self.ast.exprMain(id));
        const v = std.fmt.parseFloat(f64, text) catch {
            // Only an unfinished literal fails to parse, and the lexer
            // already reported it where it was written; a second message
            // here would describe one mistake twice.
            return self.record(id, .poison);
        };
        if (!std.math.isFinite(v)) {
            return self.report(
                .t_literal,
                id,
                "float literal is too large",
                .{},
                "no float type can hold this",
            );
        }

        try self.literal_values.put(self.gpa, id, .{ .float = v });
        return self.expect(id, .f64, expected);
    }

    fn checkLiteral(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const text = self.ast.tokenText(self.ast.exprMain(id));
        const v = constfold.literalValue(text) orelse {
            self.folds.set(id, .absent);
            return self.report(
                .t_literal,
                id,
                "integer literal is too large",
                .{},
                "no integer type can hold this",
            );
        };
        return self.checkIntegerValue(id, v, expected);
    }

    /// An integer value against what a position expects, defaulting the way
    /// an integer literal already does when nothing does. Shared by an
    /// ordinary integer literal and by a one-scalar string literal in a range
    /// end, which is the same value from here on -- one routine for "is this
    /// number the right shape for where it sits," asked by either spelling.
    fn integerLiteralFits(self: *const Checker, t: TypeId, value: i128) bool {
        if (self.isSymbolicInteger(t)) {
            // The closed family shares the nonnegative range of its smallest
            // signed member. Literal typing must be valid for every member.
            return value >= TypeId.u8.bounds().?.min and value <= TypeId.i8.bounds().?.max;
        }
        return self.builder.holds(t, value);
    }

    fn checkIntegerValue(self: *Checker, id: ExprId, v: i128, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const t = if (Expected.typeOf(expected)) |want| want else try self.openLiteral();
        const open = self.builder.get(t) == .open_integer;

        // A type that is not an integer has no range for a value to be
        // outside of, so this is a value in the wrong place rather than one
        // out of range -- "`Bool` cannot hold 1" describes a range that does
        // not exist.
        const symbolic_integer = self.isSymbolicInteger(t);
        if (t != .poison and !open and t.bounds() == null and !symbolic_integer) {
            self.folds.set(id, .absent);
            return self.reportMismatch(id, .literal_default, expected.?, "");
        }

        if (!open and !self.integerLiteralFits(t, v)) {
            self.folds.set(id, .absent);
            const message = std.fmt.allocPrint(self.gpa, "`{s}` cannot hold {d}", .{
                (try self.typeName(t)), v,
            }) catch return self.record(id, .poison);

            // The type came from somewhere: an annotation, a return type, or
            // the left operand. Naming it is what makes the error actionable,
            // since that is what a reader changes.
            const origin: ?Label = if (expected) |want| .{
                .file = want.at.file,
                .span = want.at.span,
                .message = try self.expectationSource(want),
                .style = .secondary,
            } else null;

            return self.reportWithOrigin(
                .t_literal,
                id,
                message,
                "literal is out of range for its type",
                origin,
            );
        }

        if (open) try self.open_types.awaitRange(self.gpa, .{ .v = self.builder.get(t).open_integer, .expr = id, .value = v, .rule = .literal });
        self.folds.set(id, .{ .value = v });
        try self.literal_values.put(self.gpa, id, .{ .integer = v });
        return self.record(id, t);
    }

    /// A string literal's Unicode scalar, where it names exactly one --
    /// `null` where it does not, in which case the caller falls back to the
    /// literal's ordinary `Str` typing.
    fn oneScalarOf(self: *Checker, id: ExprId) std.mem.Allocator.Error!?i128 {
        var decoded: std.ArrayList(u8) = .empty;
        defer decoded.deinit(self.gpa);
        // A literal whose escapes cannot be read was already reported.
        if (!try self.ast.literalText(self.gpa, &decoded, id)) return null;
        const scalar = literal_text.oneScalar(decoded.items) orelse return null;
        return @as(i128, scalar);
    }

    /// A range end, expression or pattern: a string literal of exactly one
    /// Unicode scalar denotes that scalar's number here, in the integer type
    /// the position expects, and defaults the way an integer literal
    /// defaults where nothing does. Anywhere else a string literal is
    /// untouched, ordinary `Str` -- this is the one call site the conversion
    /// reaches, matching every other end through the ordinary literal
    /// machinery it now shares.
    fn checkRangeEnd(self: *Checker, end: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        if (self.ast.exprTag(end) == .str_literal) {
            if (try self.oneScalarOf(end)) |v| {
                return self.checkIntegerValue(end, v, expected);
            }
        }
        return self.check(end, expected);
    }

    /// `true` and `false`, which are constant expressions.
    ///
    /// A truth value is worked out without running anything, so it is worth
    /// what it says wherever it is written: a module constant may hold one and
    /// a parameter may default to one, through the same table every other
    /// constant is answered from. It is carried as 1 and 0, and which of the
    /// two types it is is the declared type's to say, exactly as an integer
    /// literal's is.
    ///
    /// The literal is admitted and nothing built over it: `!` and `&&` over
    /// constants are not constant expressions, and neither is a variant of an
    /// enum. The definition is a list, and a form is admitted by being on it
    /// or not admitted at all -- it grows when something demands that it grow.
    fn checkBoolLiteral(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const t = try self.expect(id, .bool_, expected);
        if (t == .bool_) self.folds.set(id, .{ .truth = self.ast.boolIsTrue(id) });
        return t;
    }

    /// `!e`. The operand is a condition in all but name: `!` is defined over
    /// `Bool` and nothing else, so the rule a user sees is the one a condition
    /// would have given them.
    fn checkNot(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const inner = try self.checkCondition(self.ast.unaryOperand(id), id);
        if (inner == .never) return self.expect(id, .never, expected);
        return self.expect(id, .bool_, expected);
    }

    /// `a && b` is `if a { b } else { false }`, so its left operand is a
    /// condition and its right must agree with a `false`. That is the same
    /// requirement stated twice, and it is the conditional's requirement --
    /// which is why no rule of its own is needed.
    fn checkLogical(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const b = self.ast.binary(id);
        const lhs = try self.checkCondition(b.lhs, id);
        _ = try self.checkCondition(b.rhs, id);
        if (lhs == .never) return self.expect(id, .never, expected);
        return self.expect(id, .bool_, expected);
    }

    fn checkNegate(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const operand = self.ast.unaryOperand(id);

        // The operand is checked without a range test, because -128 is a value
        // i8 holds even though 128 is a literal it does not. Folding therefore
        // has to happen before the range check, not after.
        const inner = try self.checkForNegation(operand, expected);
        if (inner == .poison) {
            self.foldFailed(id, &.{operand});
            return self.record(id, .poison);
        }
        if (inner == .never) {
            self.foldFailed(id, &.{operand});
            return self.expect(id, .never, expected);
        }

        // The same rule the binary operators hold to: a negation is an
        // operation over numbers, so it takes one. Left out when they were
        // checked, which left every failure they close reachable through this
        // -- a structure negating its own address, an enum becoming a tag no
        // variant has and falling out of an exhaustive `match`.
        if (!self.arithmeticHolds(inner)) {
            self.foldFailed(id, &.{operand});
            return self.reportAtOp(
                .t_operands,
                id,
                "`{s}` is not a number",
                .{(try self.typeName(inner))},
                "negation is defined over integers",
            );
        }

        const t = Expected.typeOf(expected) orelse inner;
        if (self.isSymbolicInteger(t) and self.ast.exprTag(self.ast.withoutGroups(operand)) != .int_literal) {
            try self.markNotConstant(id);
            return self.record(id, t);
        }
        if (self.folds.get(operand).valueOf()) |v| {
            const negated = -v;
            switch (self.builder.get(t)) {
                .open_integer => |open| try self.open_types.awaitRange(self.gpa, .{ .v = open, .expr = id, .value = negated, .rule = .negation }),
                else => {},
            }
            if (!self.integerLiteralFits(t, negated)) {
                self.folds.set(id, .absent);
                return self.report(
                    .t_literal,
                    id,
                    "`{s}` cannot hold {d}",
                    .{ (try self.typeName(t)), negated },
                    "value is out of range for its type",
                );
            }
            self.folds.set(id, .{ .value = negated });
            if (self.ast.exprTag(self.ast.withoutGroups(operand)) == .int_literal) try self.literal_values.put(self.gpa, id, .{ .integer = negated });
        } else self.foldFailed(id, &.{operand});
        return self.record(id, t);
    }

    /// A literal under a negation is range-checked against the negated value,
    /// so the literal itself is folded without testing it.
    fn checkForNegation(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        // Parentheses do not change what is negated, so `-(128)` is checked
        // as `-128`. The group keeps its own record and fold, as `check` does.
        if (self.ast.exprTag(id) == .grouped) {
            const operand = self.ast.unaryOperand(id);
            const t = try self.checkForNegation(operand, expected);
            self.folds.set(id, self.folds.get(operand));
            if (!self.folds.get(operand).isConstant()) try self.markNotConstant(id);
            return self.record(id, t);
        }
        if (self.ast.exprTag(id) != .int_literal) return self.check(id, expected);

        const text = self.ast.tokenText(self.ast.exprMain(id));
        const v = constfold.literalValue(text) orelse {
            self.folds.set(id, .absent);
            return self.report(
                .t_literal,
                id,
                "integer literal is too large",
                .{},
                "no integer type can hold this",
            );
        };
        self.folds.set(id, .{ .value = v });
        try self.literal_values.put(self.gpa, id, .{ .integer = v });
        return self.record(id, Expected.typeOf(expected) orelse try self.openLiteral());
    }

    /// `UInt8(x)`: a call whose callee names a primitive.
    ///
    /// The target comes from the caller because deciding which calls these are
    /// is the resolver's answer, read once and passed in rather than worked out
    /// again here.
    fn checkConversion(
        self: *Checker,
        id: ExprId,
        target: TypeId,
        expected: ?Expected,
    ) std.mem.Allocator.Error!TypeId {
        try self.conversion_targets.put(self.gpa, id, target);
        // The callee names the type rather than a value, and every expression
        // must have one: a type it names is what it carries, exactly as a
        // qualifier naming a type does.
        _ = self.record(self.ast.call(id).callee, target);

        // A conversion reaches no signature, so nothing declares a parameter
        // for a name to fill.
        try self.refuseNames(id, self.ast.tokenText(self.ast.exprMain(self.ast.call(id).callee)));

        const args = self.ast.call(id).args;
        // The definition covers a conversion, which takes one value. A call
        // spelled with any other number of them is not one, so it is left not
        // a constant expression rather than a constant with no value.
        if (args.len != 1) {
            for (args) |a| _ = try self.check(a, null);
            return self.report(
                .t_convert,
                id,
                "`{s}` converts one value",
                .{(try self.typeName(target))},
                "a conversion takes exactly one argument",
            );
        }
        const operand = args[0];

        // No expectation flows inward: a conversion takes whatever it is given.
        // The operand is checked before the target constrains it, so an open
        // literal takes the default here, where the conversion needs a type.
        const from = try self.forceInteger(try self.check(operand, null), self.literalSite(operand));

        if (from == .poison or target == .poison) {
            self.foldFailed(id, &.{operand});
            return self.record(id, .poison);
        }
        if (from == .never) {
            self.foldFailed(id, &.{operand});
            return self.expect(id, .never, expected);
        }

        // A conversion is between numeric domains. `Bool` is a pair of names,
        // so there is no value of it to convert and none to convert into one.
        const from_numeric = self.builder.isIntegerWithin(self.generic, from) or from == .f64;
        const target_numeric = self.builder.isIntegerWithin(self.generic, target) or target == .f64;
        if (!from_numeric or !target_numeric) {
            self.foldFailed(id, &.{operand});
            return self.report(
                .t_convert,
                id,
                "`{s}` does not convert to `{s}`",
                .{ (try self.typeName(from)), (try self.typeName(target)) },
                "a conversion is between numbers",
            );
        }

        if (self.builder.get(from) == .parameter or self.builder.get(target) == .parameter) {
            try self.markNotConstant(id);
            return self.expect(id, target, expected);
        }

        // A conversion to a float is defined for every value and may round,
        // so there is no range to test. It also never folds: the table holds
        // an integer, and the result is not one.
        if (target == .f64) {
            self.foldFailed(id, &.{operand});
            return self.expect(id, target, expected);
        }

        if (self.folds.get(operand).valueOf()) |v| {
            if (!self.builder.holds(target, v)) {
                self.folds.set(id, .absent);
                const message = std.fmt.allocPrint(self.gpa, "`{s}` cannot hold {d}", .{
                    (try self.typeName(target)), v,
                }) catch return self.record(id, .poison);
                return self.reportWithOrigin(
                    .t_convert,
                    id,
                    message,
                    "this conversion cannot succeed",
                    self.originOfFold(operand),
                );
            }
            self.folds.set(id, .{ .value = v });
        } else self.foldFailed(id, &.{operand});

        return self.expect(id, target, expected);
    }

    /// What discharging a refined newtype's proof found.
    ///
    /// v0's proof is a folded operand inside the range; a later interval
    /// analysis widens what counts as `.proven` without moving where it is
    /// asked, because this is the only place that asks.
    const RefinementProof = union(enum) {
        /// The operand folded to a value the range admits.
        proven: i128,
        /// The operand folded to a value the range excludes.
        excluded: i128,
        /// The operand did not fold: proof does not reach this value today.
        unavailable,
    };

    /// Whether a refined newtype's contract is satisfied by an operand, and
    /// by what evidence.
    ///
    /// **The only place a proof is consumed.** Construction is the sole
    /// caller, and every refinement violation -- an excluded value or a
    /// missing proof -- is found here and nowhere downstream ever asks
    /// again: once a `Percent` exists, that existence is the proof. A second
    /// caller would be a second place the answer could drift from this one.
    fn dischargeRefinement(self: *const Checker, newtype: TypeId, operand: ExprId) RefinementProof {
        const v = self.folds.get(operand).valueOf() orelse return .unavailable;
        if (self.builder.holds(newtype, v)) return .{ .proven = v };
        return .{ .excluded = v };
    }

    /// `Name(e)` or `Name?(e)`, where `Name` names a newtype: construction,
    /// which the parser reads rather than a call reaching a function.
    ///
    /// An unrefined newtype admits every base value, so `Name(e)` is total
    /// and `Name?(e)` asserts something false -- nothing about it could ever
    /// decline. A refined newtype's `Name(e)` requires `dischargeRefinement`
    /// to answer `.proven`; its `Name?(e)` types as `Option[Name]` and asks
    /// nothing of the operand's value, because proof being unavailable is the
    /// whole reason the form exists.
    fn checkNewtypeConstruct(
        self: *Checker,
        id: ExprId,
        decl: node.DeclId,
        expected: ?Expected,
    ) std.mem.Allocator.Error!TypeId {
        const c = self.ast.call(id);
        const newtype = self.type_of_decl.get(decl);
        // The callee names the type rather than a value, and every
        // expression must have one -- the same bookkeeping a conversion's
        // callee gets. What qualifies it is named the same way, for the same
        // reason: a module written before the dot is a node in the tree and
        // stands for no value.
        self.noteQualifier(c.callee);
        _ = self.record(c.callee, newtype);

        // Reaching a sealed type's representation, the same rule a literal
        // or a pattern breaks. Both construction forms are this one call, so
        // one check answers for `Name(e)` and `Name?(e)` alike.
        if (self.sealedHere(newtype)) {
            for (c.args) |a| _ = try self.check(a, null);
            return self.reportSealed(id, newtype, "only its own module can build one");
        }

        if (c.args.len != 1) {
            for (c.args) |a| _ = try self.check(a, null);
            return self.report(
                .t_arity,
                id,
                "expected {d} value(s), found {d}",
                .{ 1, c.args.len },
                "a construction takes exactly one value",
            );
        }
        const operand = c.args[0];
        const base = self.builder.baseOf(newtype);
        const from = try self.check(operand, .{
            .ty = base,
            .at = .{ .file = self.ast.fileOfExpr(c.callee), .span = self.ast.exprSpan(c.callee) },
            .reason = .conversion,
        });
        const fallible = self.ast.callFallible(id);

        if (from == .never) {
            self.foldFailed(id, &.{operand});
            return self.expect(id, .never, expected);
        }

        if (!self.builder.isRefined(newtype)) {
            if (fallible) {
                return self.report(
                    .t_refine,
                    id,
                    "`{s}` has no refinement for `?` to decline",
                    .{(try self.typeName(newtype))},
                    "every base value is already legal here; drop the `?`",
                );
            }
            if (from == .poison) {
                self.foldFailed(id, &.{operand});
                return self.record(id, .poison);
            }
            if (self.folds.get(operand).valueOf()) |v|
                self.folds.set(id, .{ .value = v })
            else
                self.foldFailed(id, &.{operand});
            return self.expect(id, newtype, expected);
        }

        if (fallible) {
            // The result is `Option[Name]`, a value, never a constant: what
            // it holds is not decided until the program runs.
            self.foldFailed(id, &.{operand});
            if (from == .poison) return self.record(id, .poison);

            const opt = self.option_decl orelse return self.report(
                .t_literal,
                id,
                "`{s}?` has no type here: the prelude declares no `Option`",
                .{(try self.typeName(newtype))},
                "build against a library that declares it",
            );
            const made = try self.builder.instantiate(self.type_of_decl.get(opt), opt, &.{newtype});
            return self.expect(id, made, expected);
        }

        if (from == .poison) {
            self.foldFailed(id, &.{operand});
            return self.record(id, .poison);
        }

        switch (self.dischargeRefinement(newtype, operand)) {
            .proven => |v| {
                self.folds.set(id, .{ .value = v });
                return self.expect(id, newtype, expected);
            },
            .excluded => |v| {
                self.folds.set(id, .absent);
                const b = self.builder.refinementOf(newtype);
                return self.report(
                    .t_refine,
                    id,
                    "{d} is not in {d}..={d} for {s}",
                    .{ v, b.lo, b.hi, (try self.typeName(newtype)) },
                    "this value is outside the type's range",
                );
            },
            .unavailable => {
                self.folds.set(id, .absent);
                const b = self.builder.refinementOf(newtype);
                // The operand as it was written, whole. Its main token is the
                // operator where the operand is one, so `Percent(n + 1)` was
                // reported as `+` and offered `Percent?(+)` as the fix -- a
                // spelling that appears nowhere in the program.
                const spelling = self.ast.exprText(operand);
                const fix = std.fmt.allocPrint(
                    self.gpa,
                    "make it fallible: `{s}?({s})`",
                    .{ (try self.typeName(newtype)), spelling },
                ) catch return self.record(id, .poison);
                return self.report(
                    .t_refine,
                    id,
                    "`{s}` is not known to be in {d}..={d}",
                    .{ spelling, b.lo, b.hi },
                    fix,
                );
            },
        }
    }

    /// A condition is a `Bool`, and asks for one.
    ///
    /// One routine for every construct that takes a condition, so a second
    /// construct cannot come to disagree with the first about what a condition
    /// is -- nor about what flows into one. `Bool` is the language's own demand
    /// here rather than a type someone wrote, so it is known at this position
    /// and travels inward like any other expectation: a call standing in a
    /// condition settles what it returns from it, which is what reaches a
    /// signature writing a trait's parameter only as its return type. A
    /// condition that handed nothing over would leave such a call settled by
    /// nothing, and a call that settled nothing reaches no body.
    ///
    /// The mismatch is reported by the expectation rather than here. The rule
    /// is one sentence, and stating it twice is two places to say it
    /// differently.
    fn checkCondition(
        self: *Checker,
        cond: ExprId,
        construct: ExprId,
    ) std.mem.Allocator.Error!TypeId {
        return self.check(cond, .{
            .ty = .bool_,
            .at = .{
                .file = self.ast.fileOf(self.ast.exprMain(construct)),
                .span = self.ast.tokenSpan(self.ast.exprMain(construct)),
            },
            .reason = .condition,
        });
    }

    /// `while c { … }` is Unit whatever its body: it may run zero times, so
    /// there is no value it could produce. The body is evaluated for its
    /// effect and, when it completes, must be Unit for the same reason any
    /// other such expression must be. A `Never` body does not complete to
    /// hand the loop a value to discard.
    fn checkWhile(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const w = self.ast.binary(id);

        const condition = try self.checkCondition(w.lhs, id);

        // Settled to Unit before the body is entered: a `while` yields Unit
        // whatever its body, so a `break` carrying a value out of one is
        // rejected by break-site agreement rather than by its own rule.
        try self.loops.append(self.gpa, .{
            .settled = .{
                .ty = .unit,
                .at = .{ .file = self.ast.fileOf(self.ast.exprMain(id)), .span = self.ast.tokenSpan(self.ast.exprMain(id)) },
                .reason = .while_loop,
            },
            .broke = false,
        });
        const body = try self.check(w.rhs, null);
        _ = self.loops.pop();
        if (body != .unit and body != .never and body != .poison) {
            _ = self.report(
                .t_discard,
                self.resultOf(w.rhs),
                "this body produces {s} `{s}` that is discarded",
                .{ article.before(try self.typeName(body)), (try self.typeName(body)) },
                "a `while` runs its body for its effect",
            );
        }

        return self.expect(id, if (condition == .never) .never else .unit, expected);
    }

    /// The elements a value's `Sequence` implementation yields, or poison
    /// where it names no walk this construct can run.
    ///
    /// Two associated types and one question. `Sequence` settles `Iter` for
    /// the value written after `in`, and `Iterator` settles `Item` for that
    /// iterator -- so what a binder is bound to is read through the same
    /// machinery a settled reference written by hand is read through, and no
    /// second answer to "what does this walk yield" exists.
    ///
    /// Both demands are bounds, so both are asked through the routine a bound
    /// is asked through: whether a type answers a trait at all is a different
    /// question from which of its implementations a call reaches, and a `for`
    /// asks the first. A type parameter carrying the bound answers it, which
    /// is what lets a walk be written in a body generic over what it walks.
    ///
    /// The iterator must be Discardable, which is [O-LinearWalk] rather than a type
    /// rule: a walk ends by running out, and what has run out is abandoned
    /// where the loop ends, so an iterator obliging disposal would be a value
    /// the loop holds at an exit with nothing written to take it.
    ///
    /// **Bound:** two bound lookups and two substitutions, per `for`.
    fn elementWalkedBy(
        self: *Checker,
        loop: ExprId,
        at: ExprId,
        walked: TypeId,
    ) std.mem.Allocator.Error!TypeId {
        if (walked == .poison) return .poison;

        const sequence = self.sequence_decl orelse return self.report(
            .t_for,
            at,
            "a `for` has nothing to walk here: the prelude declares no `Sequence`",
            .{},
            "build against a library that declares it",
        );
        if (self.iterator_decl == null) return self.report(
            .t_for,
            at,
            "a `for` has nothing to walk here: the prelude declares no `Iterator`",
            .{},
            "build against a library that declares it",
        );
        const iter_sig = self.sequence_iter orelse return .poison;

        if (!try self.answersTrait(walked, self.sequence_decl)) {
            // A `Sequence` implementation that fails only on demands a bound
            // refusal reported follows from that refusal.
            if (try self.refusalExplains(sequence, walked)) return .poison;
            const before = self.sink.items().len;
            const reported = self.report(
                .t_for,
                at,
                "`{s}` implements no `Sequence`",
                .{(try self.typeName(walked))},
                "a `for` walks what a `Sequence` says how to walk",
            );
            try self.explainMissing(before, sequence, walked);
            if (try self.walksOffered(loop, walked, sequence)) |help| try self.addNote(before, help);
            return reported;
        }

        // The question above may have settled open integers in what is walked
        // -- by what already settled them, or by falling back -- so the walk
        // is read at the type it answered for. Read at the open key, the
        // implementation it selected is not the one it answered with.
        const settled = try self.builder.resolveOpen(walked, &self.open_types);
        const iter = try self.builder.settledAt(
            @intCast(sequence.index()),
            &.{},
            settled,
            iter_sig,
            "Iter",
        );
        if (iter == .poison) return .poison;

        if (!try self.abandonable(iter)) return self.reportAbandonedWalk(loop, walked, iter);

        return try self.itemYieldedBy(iter) orelse return self.report(
            .t_for,
            at,
            "walking {s} `{s}` builds {s} `{s}`, which implements no `Iterator`",
            .{ article.before(try self.typeName(walked)), (try self.typeName(walked)), article.before(try self.typeName(iter)), (try self.typeName(iter)) },
            "settle the sequence's `Iter` to something that implements it",
        );
    }

    /// [T-Call] for a lambda parameter that differs from parameter `position`
    /// of the callable its context expects, reported at the parameter's name.
    /// The first difference is named with both sides spelled out -- the
    /// convention, then the written type, then the default -- and the label
    /// writes the parameter as the context expects it. Whether it reported.
    fn reportLambdaParameterMismatch(
        self: *Checker,
        param: node.Param,
        ty: TypeId,
        default: types_mod.CallableDefault,
        want: types_mod.CallableParam,
        position: usize,
    ) std.mem.Allocator.Error!bool {
        const arena = self.sink.arena;
        const name = self.ast.paramSpelling(param);
        const file = self.ast.fileOf(param.name);
        const span = if (param.pattern != ExprId.none) self.ast.exprSpan(param.pattern) else self.ast.tokenSpan(param.name);
        if (param.convention != want.convention) {
            // `read` is what a parameter with no convention written takes, and
            // writing it is refused as redundant, so the fix is to drop the
            // written one.
            const fix = if (want.convention == .read)
                try std.fmt.allocPrint(arena, "write `{s}` with no convention", .{name})
            else
                try std.fmt.allocPrint(arena, "write `{s} {s}`", .{ @tagName(want.convention), name });
            try self.sink.addErrorFmt(
                .t_call,
                file,
                span,
                fix,
                "this lambda takes `{s}` as `{s}`, and the expected callable passes parameter {d} as `{s}`",
                .{ name, @tagName(param.convention), position, @tagName(want.convention) },
            );
            return true;
        }
        if (ty != .poison and ty != want.ty) {
            const expected_type = try self.typeName(want.ty);
            try self.sink.addErrorFmt(
                .t_call,
                file,
                span,
                try std.fmt.allocPrint(arena, "write `{s}: {s}`, or leave the type out", .{ name, expected_type }),
                "this lambda gives `{s}` the type `{s}`, and parameter {d} of the expected callable is `{s}`",
                .{ name, (try self.typeName(ty)), position, expected_type },
            );
            return true;
        }
        if (default.eql(want.default)) return false;
        switch (want.default) {
            .absent => try self.sink.addErrorFmt(
                .t_call,
                file,
                span,
                "remove the default",
                "this lambda gives `{s}` a default, and parameter {d} of the expected callable has none",
                .{ name, position },
            ),
            .value => |wanted| {
                const wanted_text = try wanted.text(arena, &self.folded.pool);
                const label = try std.fmt.allocPrint(arena, "write `{s} = {s}`", .{ name, wanted_text });
                switch (default) {
                    .absent => try self.sink.addErrorFmt(
                        .t_call,
                        file,
                        span,
                        label,
                        "this lambda gives `{s}` no default, and parameter {d} of the expected callable defaults to `{s}`",
                        .{ name, position, wanted_text },
                    ),
                    .value => |have| try self.sink.addErrorFmt(
                        .t_call,
                        file,
                        span,
                        label,
                        "this lambda defaults `{s}` to `{s}`, and parameter {d} of the expected callable defaults to `{s}`",
                        .{ name, (try have.text(arena, &self.folded.pool)), position, wanted_text },
                    ),
                }
            },
        }
        return true;
    }

    /// The help for a plain `for` over `walked`, which implements no
    /// `Sequence`: the walks it does offer, spelled with the loop's own binder
    /// and head. A lending walk where a traversal reaches it -- `for inout`
    /// only where the head is a writable place -- a walk over its `as_slice()`
    /// view, and its `drain()`, each where `walked` has one; null where it has
    /// none of them, or where the head is no place.
    ///
    /// **Bound:** one traversal lookup and two scans of the operations
    /// `walked`'s declaration holds; asked only while reporting.
    fn walksOffered(self: *Checker, loop: ExprId, walked: TypeId, sequence: node.DeclId) std.mem.Allocator.Error!?[]const u8 {
        const f = self.ast.call(loop);
        // A lending walk, a view and a drain of a value no place holds each
        // outlive it or leave it unsettled, so none is a walk to suggest.
        if (self.res.placeRoot(self.ast, f.callee) == BindingId.none) return null;
        const binder = self.ast.exprText(f.args[0]);
        const head = self.ast.exprText(f.callee);
        var ways: std.ArrayList([]const u8) = .empty;
        defer ways.deinit(self.gpa);
        const arena = self.sink.arena;
        if (try self.traversalReaching(walked) == .found) {
            try ways.append(self.gpa, try std.fmt.allocPrint(arena, "look at each element with `for read {s} in {s}`", .{ binder, head }));
            // `for inout` writes through the head, which only a writable
            // place allows.
            if (self.res.placeIsMutable(self.ast, f.callee))
                try ways.append(self.gpa, try std.fmt.allocPrint(arena, "change each in place with `for inout {s} in {s}`", .{ binder, head }));
        }
        if (try self.operationImplementing(walked, "as_slice", sequence))
            try ways.append(self.gpa, try std.fmt.allocPrint(arena, "walk a view of it with `for {s} in {s}.as_slice()`", .{ binder, head }));
        if (try self.operationImplementing(walked, "drain", sequence))
            try ways.append(self.gpa, try std.fmt.allocPrint(arena, "take its elements out with `{s}.drain()`", .{head}));
        if (ways.items.len == 0) return null;

        var help: std.ArrayList(u8) = .empty;
        const w = &help;
        for (ways.items, 0..) |way, i| {
            if (i > 0) try w.appendSlice(arena, if (i + 1 == ways.items.len) (if (ways.items.len > 2) ", or " else " or ") else ", ");
            try w.appendSlice(arena, way);
        }
        return help.items;
    }

    /// [O-LinearWalk]: the loop ends holding a linear iterator, however it
    /// ends. The report says what the iterator owes and teaches the lent walk,
    /// which leaves the iterator with its owner to settle after the loop.
    fn reportAbandonedWalk(self: *Checker, loop: ExprId, walked: TypeId, iter: TypeId) std.mem.Allocator.Error!TypeId {
        const f = self.ast.call(loop);
        const iter_name = try self.typeName(iter);
        const before = self.sink.items().len;
        const reported = if (walked == iter) self.report(
            .o_linear_walk,
            f.callee,
            "walking {s} `{s}` abandons it where the walk ends, and it is linear",
            .{ article.before(iter_name), iter_name },
            try self.owedBy(iter),
        ) else self.report(
            .o_linear_walk,
            f.callee,
            "walking {s} `{s}` builds {s} `{s}` and abandons it where the walk ends, and it is linear",
            .{ article.before(try self.typeName(walked)), (try self.typeName(walked)), article.before(iter_name), iter_name },
            try self.owedBy(iter),
        );
        // What settles the iterator is `Settlers`' answer, which reads the
        // finished typing, so the help is written once checking has ended.
        if (self.sink.items().len == before + 1) try self.walk_helps.append(self.gpa, .{
            .report = before,
            .loop = loop,
            .walked = walked,
            .iter = iter,
            .owner = self.generic,
        });
        return reported;
    }

    /// What a linear iterator owes when a walk abandons it: linear items it
    /// has not handed over, or storage from an allocator, read through the
    /// type's arguments so an opaque type's fields stay unnamed.
    fn owedBy(self: *Checker, iter: TypeId) std.mem.Allocator.Error![]const u8 {
        const arena = self.sink.arena;
        if (self.builder.instanceOf(iter)) |inst| {
            const args = self.builder.argsOf(inst);
            const item = try self.itemYieldedBy(iter);
            for (args) |arg| {
                if (!try self.builder.mustConsumeWithin(self.generic, arg)) continue;
                const name = try self.typeName(arg);
                if (item != null and item.? == arg)
                    return std.fmt.allocPrint(arena, "it still holds the `{s}` items it has not handed over, and `{s}` is linear", .{ name, name });
                return std.fmt.allocPrint(arena, "it holds {s} `{s}`, which is linear", .{ article.before(name), name });
            }
            if (self.allocator_decl != null) for (args) |arg| {
                if (!try self.answersTrait(arg, self.allocator_decl)) continue;
                return std.fmt.allocPrint(arena, "it holds storage from `{s}`, which must be released", .{try self.typeName(arg)});
            };
        }
        return std.fmt.allocPrint(arena, "`{s}` is linear, and nothing settles it here", .{try self.typeName(iter)});
    }

    /// How a walk keeps what it cannot abandon with its owner: walk the
    /// iterator lent, `for x in &name`, and settle it after the loop. A head
    /// that is not a name is bound to one first, written out in full, and a
    /// sequence's iterator is asked for with `iterate()`. `settling` says how
    /// the iterator is settled after the loop.
    fn lendingHelp(self: *Checker, loop: ExprId, walked: TypeId, iter: TypeId, settling: []const u8) std.mem.Allocator.Error![]const u8 {
        const f = self.ast.call(loop);
        const arena = self.sink.arena;
        const binder = if (self.ast.exprTag(f.args[0]) == .name_ref) self.ast.tokenText(self.ast.exprMain(f.args[0])) else "item";
        const head = self.ast.withoutGroups(f.callee);
        if (walked == iter and self.ast.exprTag(head) == .name_ref) {
            const name = self.ast.tokenText(self.ast.exprMain(head));
            return std.fmt.allocPrint(arena, "walk it lent with `for {s} in &{s}`, then settle `{s}` {s}", .{ binder, name, name, settling });
        }
        const text = self.ast.exprText(f.callee);
        // A name the head does not already use, so the suggestion reads as a
        // new binding rather than a shadowing one.
        const fresh = for ([_][]const u8{ "pending", "remaining", "walked" }) |candidate| {
            if (std.mem.indexOf(u8, text, candidate) == null) break candidate;
        } else "iterator";
        return std.fmt.allocPrint(arena, "bind it, `var {s} = {s}{s}`, walk it lent with `for {s} in &{s}`, then settle `{s}` {s}", .{
            fresh,
            text,
            if (walked == iter) "" else ".iterate()",
            binder,
            fresh,
            fresh,
            settling,
        });
    }

    /// Writes each abandoned walk's help, naming what settles its iterator as
    /// a leak report would: the operations `Settlers` finds, and otherwise
    /// one that hands the iterator back, such as `finish`.
    fn writeWalkHelps(self: *Checker, typing: *const Typing) std.mem.Allocator.Error!void {
        for (self.walk_helps.items) |help| {
            const settling = settling: {
                if (help.owner == .none) break :settling "after the loop";
                var reach = reachIn(self.ast, self.program.source, self.res, typing, self.program.moduleOf(help.owner), help.owner);
                reach.expanded_program = self.program;
                const settlers: Settlers = .{ .ast = self.ast, .res = self.res, .typing = typing, .reach = reach, .owner = help.owner };
                var found: [1]node.DeclId = undefined;
                const op = if (try settlers.operations(self.gpa, help.iter, &found) > 0) found[0] else try settlers.handingBack(self.gpa, help.iter) orelse break :settling "after the loop";
                break :settling try std.fmt.allocPrint(self.sink.arena, "with `{s}()`", .{self.ast.tokenText(self.ast.declName(op))});
            };
            try self.addNote(help.report, try self.lendingHelp(help.loop, help.walked, help.iter, settling));
        }
    }

    /// Adds a note to the diagnostic the sink holds at `at`.
    fn addNote(self: *Checker, at: usize, note: []const u8) std.mem.Allocator.Error!void {
        const items = self.sink.mutableItems();
        if (at >= items.len) return;
        const reported = &items[at];
        const notes = try self.sink.arena.alloc([]const u8, reported.notes.len + 1);
        @memcpy(notes[0..reported.notes.len], reported.notes);
        notes[reported.notes.len] = note;
        reported.notes = notes;
    }

    /// Whether an iterator a walk ends holding is one it may end holding.
    ///
    /// One routine and two askers, because a walk builds its iterator two ways
    /// and abandons it the same way either: a `for` asks it of what a
    /// `Sequence` vends, and a traversal asks it of the positions it is bound
    /// to. A walk ends by running out, and what has run out is abandoned where
    /// the loop ends -- so an iterator obliging disposal would be a value the
    /// loop holds at an exit with nothing written to take it, which is
    /// [O-LinearWalk]. Two readings of it would refuse one walk and drop the
    /// other's iterator without a word.
    fn abandonable(self: *Checker, iter: TypeId) !bool {
        return try self.builder.mayDiscardWithin(self.generic, iter);
    }

    /// What an `Iterator` hands over, or null where the type implements none.
    ///
    /// One routine, because two constructs ask it: a `for` asks what the
    /// iterator a `Sequence` vends yields, and a traversal is an iterator
    /// written down. Two readings of "what does this yield" would settle a
    /// binder at one type and a position at another.
    ///
    /// Null rather than a report, because the two callers name different
    /// things in the sentence -- what a sequence built, and what a traversal
    /// was given.
    ///
    /// **Bound:** one bound lookup and one substitution, per call.
    fn itemYieldedBy(self: *Checker, iter: TypeId) std.mem.Allocator.Error!?TypeId {
        if (iter == .poison) return TypeId.poison;
        const iterator = self.iterator_decl orelse return null;
        const item_sig = self.iterator_item orelse return TypeId.poison;
        return self.associatedTypeOf(iterator, item_sig, "Item", iter);
    }

    /// The type `held`'s implementation of `trait` settles the associated
    /// type `member`, spelled `name`, to: read off a declared implementation,
    /// or off the bound in scope that supplies it. Null where `held`
    /// implements `trait` through neither; poison where the implementation
    /// settles nothing.
    ///
    /// **Bound:** one implementation lookup and one substitution, per call.
    fn associatedTypeOf(self: *Checker, trait: node.DeclId, member: node.DeclId, name: []const u8, held: TypeId) std.mem.Allocator.Error!?TypeId {
        const choice = try self.builder.implementationChoiceWithin(self.generic, trait, &.{}, held) orelse return null;
        if (choice.declaredImplementation()) |implementation|
            return try self.builder.settledBy(self.implementations[implementation.index()], member, choice.impl_args);
        return try self.builder.settledAt(@intCast(trait.index()), &.{}, held, member, name);
    }

    /// A traversal's positions: an `Iterator` handing over integers.
    ///
    /// Held here rather than at each walk that finds one, because it is a
    /// statement about the declaration: a position is what a bracket is
    /// written with, so a traversal yielding anything else names places no
    /// projection could be indexed by. A walk over such a type would be
    /// refused once per loop for a mistake made once.
    ///
    /// **Bound:** one bound lookup and one substitution, per traversal.
    fn checkTraversal(self: *Checker, positions: ExprId) std.mem.Allocator.Error!void {
        const errors_before = self.sink.error_count;
        try self.checkTraversalType(try self.builder.resolveOpen(self.builder.exprType(positions), &self.open_types), self.locOf(positions));
        if (self.sink.error_count != errors_before) _ = self.record(positions, .poison);
    }

    fn checkTraversalType(self: *Checker, walks: TypeId, at: Loc) std.mem.Allocator.Error!void {
        if (walks == .poison) return;
        const item = try self.itemYieldedBy(walks) orelse {
            try self.sink.addErrorFmt(.t_lend, at.file, at.span, "a traversal is the positions a walk asks for one at a time", "`{s}` implements no `Iterator`", .{(try self.typeName(walks))});
            return;
        };
        if (item == .poison) return;
        if (!self.builder.isIntegerWithin(self.generic, item)) try self.sink.addErrorFmt(.t_lend, at.file, at.span, "a position is what a bracket is written with, and a projection is indexed by one", "this traversal yields `{s}`, and a position is an integer", .{(try self.typeName(item))});
        if (!try self.abandonable(walks)) try self.sink.addErrorFmt(.o_linear_walk, at.file, at.span, "a walk abandons its positions where it ends, so a traversal is Discardable", "a walk through this traversal builds {s} `{s}`, which is linear", .{ article.before(try self.typeName(walks)), (try self.typeName(walks)) });
    }

    /// Check the declaration once, retaining its range even if no loop uses it.
    fn checkDelegatedTraversal(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!void {
        const target = self.ast.declDelegation(d);
        const at: Loc = .{ .file = self.ast.fileOf(target), .span = self.ast.tokenSpan(target) };
        const impl = self.res.implEnclosing(d);
        const row = (self.rowFor(impl) orelse return).*;
        const previous_module = self.current;
        const previous_generic = self.generic;
        self.current = self.program.moduleOf(d);
        self.generic = impl;
        defer {
            self.current = previous_module;
            self.generic = previous_generic;
        }
        if (self.ast.declParams(d).len != 0 or self.ast.declInit(d) != .none or self.ast.declBody(d) != .none) {
            try self.traversalDelegationError(at, "a forwarded traversal takes no receiver, initializer, or body");
            return;
        }
        const declaration = self.declaringType(row.ty) orelse {
            try self.traversalDelegationError(at, "a forwarded traversal requires a named type with stored fields");
            return;
        };
        if (self.program.moduleOf(declaration) != self.current) {
            try self.traversalDelegationError(at, "declare field forwarding in the type's defining module");
            return;
        }
        const field = self.builder.lookupField(row.ty, self.ast.tokenText(target)) orelse {
            try self.traversalDelegationError(at, "the forwarded name is not a stored field of this type");
            return;
        };
        try self.field_names.put(self.gpa, target, .{ .receiver = row.ty, .field = @enumFromInt(field.index) });
        const array = switch (self.builder.get(field.ty)) {
            .array => |value| value,
            else => {
                try self.traversalDelegationError(at, "a forwarded traversal requires a fixed-size array field");
                return;
            },
        };
        const key = switch (try self.integerIndexKey(impl, row.ty)) {
            .one => |key| key,
            .many => {
                try self.traversalDelegationError(at, "a forwarded traversal has more than one applicable integer indexing key");
                return;
            },
            .none => {
                try self.traversalDelegationError(at, "a forwarded traversal has no applicable integer indexing key");
                return;
            },
        };
        // A symbolic Integer key must represent the endpoint for every member
        // of its domain, including the narrowest signed integer.
        var maximum: u128 = std.math.maxInt(u128);
        for (TypeId.primitives) |integer| {
            const info = integer.integerInfo() orelse continue;
            if (key.integerInfo() != null and integer != key) continue;
            const magnitude_bits: u7 = @intCast(info.bits - @intFromBool(info.signed));
            maximum = @min(maximum, (@as(u128, 1) << magnitude_bits) - 1);
        }
        if (array.count > maximum) {
            try self.traversalDelegationError(at, "the array length is not representable as this key's exclusive range bound");
            return;
        }
        const range = self.range_decl orelse {
            try self.traversalDelegationError(at, "a forwarded traversal requires the prelude's `Range` type");
            return;
        };
        const iterator = try self.builder.instantiate(self.type_of_decl.get(range), range, &.{key});
        const errors_before = self.sink.error_count;
        try self.checkTraversalType(iterator, at);
        if (self.sink.error_count != errors_before) return;
        try self.traversal_positions.put(self.gpa, d, .{ .array = .{ .key = key, .count = array.count, .iterator = iterator } });
    }

    const IntegerIndexKey = union(enum) {
        none,
        one: TypeId,
        /// Two of the applicable keys, named in the refusal.
        many: [2]TypeId,
    };

    /// The integer key `receiver` is indexed by within `owner`, when exactly
    /// one applies. Both a bare literal in a bracket and a forwarded traversal
    /// ask this, so they agree on which key a wrapper has.
    ///
    /// Candidates are the integer arguments of the receiver's own `Index`
    /// bounds, which keeps a symbolic key symbolic; the keys recovered from
    /// the implementations under the receiver's head; and each primitive
    /// integer, which covers an implementation whose key the receiver does not
    /// determine. A candidate counts only when the ordinary lookup selects an
    /// implementation for it, so failed prerequisites and defaults follow the
    /// same rules as an explicitly typed key. `FromEnd` and other non-integer
    /// keys are never candidates.
    ///
    /// A receiver that still names a type parameter can meet more
    /// implementations once it is substituted, because a prerequisite on that
    /// parameter is undecided here. Every implementation whose head matches
    /// therefore counts towards ambiguity, so a generic body refuses exactly
    /// the literal a concrete instance would refuse; the chosen key still
    /// needs evidence.
    ///
    /// **Bound:** the receiver's bounds, the implementations chained under
    /// its head for `Index`, and the fixed primitive list, with one lookup per
    /// distinct candidate. Deduplication compares each candidate with those
    /// before it, so it is quadratic in that per-receiver count and
    /// independent of the program's other implementations.
    fn integerIndexKey(self: *Checker, owner: DeclId, receiver: TypeId) std.mem.Allocator.Error!IntegerIndexKey {
        const trait = self.index_decl orelse return .none;
        var candidates: std.ArrayList(TypeId) = .empty;
        defer candidates.deinit(self.gpa);
        {
            var bounds: std.ArrayList([]const TypeId) = .empty;
            defer bounds.deinit(self.gpa);
            try self.builder.boundArgumentsWithin(owner, receiver, trait.index(), &bounds);
            for (bounds.items) |args| {
                if (args.len == 1 and self.builder.isIntegerWithin(owner, args[0]))
                    try candidates.append(self.gpa, args[0]);
            }
        }
        const head = self.builder.headOf(receiver);
        const ground = try self.builder.allGround(&.{receiver});
        var potential: ?TypeId = null;
        var implementations = self.impl_index.membersOf(trait.index(), head);
        while (implementations.next()) |i| {
            const candidate = self.implementations[i];
            if (candidate.trait != trait.index() or !candidate.head.same(head)) continue;
            const args = try self.builder.receiverTraitArguments(@enumFromInt(i), receiver) orelse continue;
            if (args.len != 1 or !self.builder.isIntegerWithin(owner, args[0])) continue;
            try candidates.append(self.gpa, args[0]);
            if (!ground) {
                if (potential) |first| {
                    if (first != args[0]) return .{ .many = .{ first, args[0] } };
                } else potential = args[0];
            }
        }
        for (TypeId.primitives) |key| {
            if (key.integerInfo() != null) try candidates.append(self.gpa, key);
        }
        var selected: ?TypeId = null;
        for (candidates.items, 0..) |key, at| {
            if (std.mem.indexOfScalar(TypeId, candidates.items[0..at], key) != null) continue;
            if (try self.builder.implementationChoiceWithin(owner, trait, &.{key}, receiver) == null) continue;
            if (selected) |first| return .{ .many = .{ first, key } };
            selected = key;
        }
        return if (selected) |key| .{ .one = key } else .none;
    }

    fn traversalDelegationError(self: *Checker, at: Loc, message: []const u8) std.mem.Allocator.Error!void {
        try self.sink.addErrorFmt(.t_lend, at.file, at.span, "write an ordinary traversal with an explicitly typed range", "{s}", .{message});
    }

    const TraversalReach = union(enum) {
        /// `walked` names no declared type.
        no_declaration,
        /// Its declaration's implementations declare no `trav`.
        none_declared,
        /// The implementation declaring one does not answer for `walked`.
        not_covered,
        found: Traversal,
    };

    /// The traversal a lending walk over `walked` runs through, or why there
    /// is none. A lending walk and the help a refused plain walk writes both
    /// ask here, so the help names `for read` exactly where one is accepted.
    ///
    /// **Bound:** one lookup in the traversal index and one coverage check.
    fn traversalReaching(self: *Checker, walked: TypeId) std.mem.Allocator.Error!TraversalReach {
        const declares = self.view().declOfType(walked) orelse return .no_declaration;
        const found = self.traversal_of_type.get(declares) orelse return .none_declared;
        // The head names a family, and the implementation that declares the
        // traversal need not answer for all of it: `impl Pair[UInt8]` covers
        // one member, and a bounded one covers what its bounds admit. Asked
        // through the index's own routine, so a traversal is reached on
        // exactly the terms every other member of an implementation is.
        if (!try self.impl_index.covers(
            self.gpa,
            self.implementations,
            &self.builder,
            found.row,
            walked,
            self.generic,
        )) return .not_covered;
        return .{ .found = found };
    }

    /// The element a lending walk names at each position, or poison where the
    /// type says nothing about how its places are reached.
    ///
    /// Two halves and one rule. An array carries both: its positions are the
    /// language's own and every one of them is a place the compiler already
    /// addresses, so nothing is declared and nothing is looked for. Everything
    /// else declares them -- `trav` names the positions and `proj at` says what
    /// place each stands for -- and neither is a walk without the other, which
    /// is [T-Lend].
    ///
    /// The projection is found through the routine a bracket finds one through,
    /// and recorded against the loop the way a bracket's is recorded against
    /// the bracket. A second lookup would be free to reach a different
    /// implementation from the one whose element the binder was checked
    /// against, and lowering would splice a path for the other.
    ///
    /// **Bound:** one lookup in the traversal index, and what a bracket costs.
    fn elementLentBy(
        self: *Checker,
        id: ExprId,
        walked: TypeId,
        places: ?TypeId,
    ) std.mem.Allocator.Error!TypeId {
        if (walked == .poison) return .poison;
        if (places) |element| return element;

        const anchor = self.ast.call(id).callee;
        const found = switch (try self.traversalReaching(walked)) {
            .found => |found| found,
            .no_declaration => return self.report(
                .t_lend,
                anchor,
                "`{s}` declares no traversal",
                .{(try self.typeName(walked))},
                "a lending walk runs through the positions a `trav` names",
            ),
            .none_declared => return self.report(
                .t_lend,
                anchor,
                "`{s}` declares no traversal",
                .{(try self.typeName(walked))},
                "declare one with `trav`, beside the projection its positions index",
            ),
            .not_covered => return self.report(
                .t_lend,
                anchor,
                "`{s}` declares no traversal",
                .{(try self.typeName(walked))},
                "the implementation that declares one does not answer for this type",
            ),
        };

        const traversal = found.member;

        // What the traversal yields, which is what the projection is indexed
        // by. Read through the routine that answered it where the traversal
        // was checked, so a walk is indexed by the positions the declaration
        // itself was held to.
        const positions_plan: types_mod.TraversalPositions = if (self.ast.declDelegation(traversal) != .none)
            self.traversal_positions.get(traversal) orelse return .poison
        else
            .{ .expression = self.ast.declInit(traversal) };
        const positions = switch (positions_plan) {
            // The traversal's own initializer has fallen back already; read
            // its positions as the type they settled on.
            .expression => |expression| try self.builder.resolveOpen(self.builder.exprType(expression), &self.open_types),
            .array => |array| array.iterator,
        };
        const arguments = try self.builder.implementationArgumentsWithin(self.generic, @enumFromInt(found.row), &.{}, walked) orelse return .poison;
        const concrete_positions = try self.builder.substitute(positions, self.implementations[found.row].decl.index(), arguments);
        const item = try self.itemYieldedBy(concrete_positions) orelse return .poison;
        if (item == .poison) return .poison;

        {
            const impl_args = try self.gpa.dupe(TypeId, arguments);
            errdefer self.gpa.free(impl_args);
            try self.traversals.append(self.gpa, .{
                .at = @intCast(id.index()),
                .decl = traversal,
                .impl_args = impl_args,
                .positions = positions_plan,
            });
        }

        return switch (try self.projectionAt(id, walked, item)) {
            .place => |element| element,
            .unusable => .poison,
            .no_trait, .unimplemented => self.report(
                .t_lend,
                anchor,
                "`{s}` declares a traversal and no place a position reaches",
                .{(try self.typeName(walked))},
                "implement `Index` for it, indexed by what the traversal yields",
            ),
        };
    }

    /// Whether the parser reported a pattern: it holds a part the parser could
    /// not read, at any depth, or a tuple naming a count of parts no tuple
    /// has.
    fn refusedByParser(self: *const Checker, pattern: ExprId) bool {
        if (self.ast.exprTag(pattern) == .err) return true;
        if (self.ast.exprTag(pattern) == .tuple_pattern and !node.isTupleArity(self.ast.call(pattern).args.len)) return true;
        var parts = self.ast.patternParts(pattern);
        while (parts.next()) |part| if (self.refusedByParser(part)) return true;
        return false;
    }

    /// A lambda parameter written as a tuple pattern takes its argument apart
    /// where the body begins, as `let (a, b) = argument` does for a `sink`
    /// parameter and `let read (a, b) = argument` does for a `read` or `inout`
    /// one: the components are owned under `sink`, and lent from the
    /// argument's place otherwise. The body cannot name the argument, so the
    /// checker records no place for a lent component: two components are
    /// bindings of their own, which is all its overlap rules ask of them.
    fn checkParameterPattern(self: *Checker, param: node.Param, ty: TypeId) std.mem.Allocator.Error!void {
        _ = self.record(param.argument, ty);
        if (try self.checkTuplePattern(param.pattern, ty, ExprId.none)) try self.refuseRefutable(param.pattern, ty);
    }

    test checkParameterPattern {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        const checked = try typingAsPrelude(gpa, own_tuple2 ++
            \\fn apply[F: fn(sink pair: (UInt8, Bool)) -> UInt8](sink pair: (UInt8, Bool), take: F) -> UInt8 {
            \\    take(pair)
            \\}
            \\fn main() -> UInt8 {
            \\    apply((1, true), |sink (n, _)| n)
            \\}
            \\
        , &sink);
        try testing.expectEqual(@as(u32, 0), sink.error_count);
        const ast = &checked.res.expanded.ast;
        var patterns: usize = 0;
        for (0..ast.exprCount()) |i| {
            const id = ExprId.at(@intCast(i));
            if (ast.exprTag(id) != .lambda) continue;
            const param = ast.lambda(id).params[0];
            // The argument is the parameter's own type, and each binder takes
            // its component's.
            try testing.expectEqualStrings("(UInt8, Bool)", checked.typing.nameOf(checked.typing.exprType(param.argument)));
            try testing.expectEqual(TypeId.u8, checked.typing.exprType(ast.call(param.pattern).args[0]));
            try testing.expectEqual(TypeId.bool_, checked.typing.exprType(ast.call(param.pattern).args[1]));
            patterns += 1;
        }
        try testing.expectEqual(@as(usize, 1), patterns);
    }

    /// Gives a walk's binder the element type: a name takes the element, and a
    /// tuple pattern takes it apart through the routine `let` and `match`
    /// use, each part receiving its component. `place` is the place a
    /// lending walk's element is.
    fn bindWalked(self: *Checker, binder: ExprId, element: TypeId, place: ?BinderPlace) std.mem.Allocator.Error!void {
        if (self.ast.exprTag(binder) != .tuple_pattern) {
            _ = self.record(binder, element);
            const target = self.res.targetOf(binder);
            if (target != BindingId.none) {
                self.setBindingType(target, element);
                if (place) |p| self.binder_places[target.index()] = p;
            }
            return;
        }

        // A walk that never yields takes nothing apart: each part is
        // `Never`, as a name binder is, and nothing is reported.
        if (element == .never) return self.settlePatternAs(binder, .never);

        // A lending walk's pattern takes the walked place apart: the pattern
        // stands for that place, and each binder for its part of it.
        var at = ExprId.none;
        if (place) |p| {
            try self.pattern_places.put(self.gpa, binder, p);
            at = binder;
        }
        if (try self.checkTuplePattern(binder, element, at)) try self.refuseRefutable(binder, element);
    }

    /// Lends the places a lending walk's binders name for the extent of its
    /// body, and answers how many were taken. Each binder of a pattern lends
    /// its own part, so they are held apart from one another as any two
    /// places are.
    fn walkLendBegin(self: *Checker, at: ExprId, binder: ExprId, writable: bool) std.mem.Allocator.Error!usize {
        if (self.ast.exprTag(binder) != .tuple_pattern) {
            try self.lendBegin(at, binder, writable);
            return 1;
        }
        var taken: usize = 0;
        try self.lendPatternBinders(at, binder, writable, &taken);
        return taken;
    }

    /// Lends each binder of a pattern the body reads, at every depth. `_`
    /// binds a slot nothing names, and lending it would hold every write
    /// beside it against it.
    fn lendPatternBinders(self: *Checker, at: ExprId, pattern: ExprId, writable: bool, taken: *usize) std.mem.Allocator.Error!void {
        var parts = self.ast.patternParts(pattern);
        while (parts.next()) |part| {
            if (!self.ast.partBinds(part)) {
                if (self.ast.exprTag(part) != .name_ref) try self.lendPatternBinders(at, part, writable, taken);
                continue;
            }
            const b = self.res.targetOf(part);
            if (b == BindingId.none) continue;
            // Only what the pattern bound to a place. A name reaching none is
            // lending nothing, and asking `overlaps` about it would compare a
            // path against something that is not one.
            if (self.binder_places[b.index()] == null) continue;
            // And only what the body reads. A whole-struct pattern names
            // every field, so an arm reaching for one part binds the rest to
            // `_` -- and lending those refused every write to the value the
            // match stands over, which is the ordinary way to write such an
            // arm.
            if (!self.res.isReferenced(b)) continue;
            try self.lendBegin(at, part, writable);
            taken.* += 1;
        }
    }

    /// Ends the lends `walkLendBegin` took, last first, checking the body
    /// against each.
    fn walkLendEnd(self: *Checker, body: ExprId, writable: bool, taken: usize) std.mem.Allocator.Error!void {
        var left = taken;
        while (left > 0) : (left -= 1) {
            const held = self.lent_now.items[self.lent_now.items.len - 1].place;
            try self.lendEnd(held, body, writable);
        }
    }

    /// `for x in xs { … }` walks what it names, taking it.
    ///
    /// The binder is bound to what the walk yields, once per element, and its
    /// scope is the body -- so the type it carries is the array's element or
    /// the sequence's `Item` and nothing about the loop decides it. Either way
    /// it is recorded against the binder here, which is where every later pass
    /// reads it from: a walk that settled the binder's type twice would settle
    /// it at two widths.
    ///
    /// What the loop yields says what happened. A walk that runs out produced
    /// no element to hand back, so a `for` whose every exit carries nothing is
    /// Unit, exactly as a `while` is; and a `for` a `break e` can leave is
    /// `Option[E]`, which is the one type that says both "it stopped at this"
    /// and "it ran out". Break sites agree among themselves by the rule that
    /// governs every other loop, so `E` is settled once and every other
    /// `break` answers to it.
    fn checkFor(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const f = self.ast.call(id);

        // `for x in &it` lends the iterator `it` to the walk: the loop calls
        // `next` through the lend and abandons nothing, so what `it` still
        // holds stays with its owner.
        const lent_iterator: ?ExprId = if (self.ast.exprTag(id) == .for_ and self.ast.exprTag(f.callee) == .marked)
            self.ast.unaryOperand(f.callee)
        else
            null;
        if (lent_iterator) |iterator| return self.checkLentWalk(id, iterator, expected);

        const walked = try self.check(f.callee, null);
        if (walked == .never) {
            try self.bindWalked(f.args[0], .never, null);
            _ = try self.check(f.args[1], null);
            return self.expect(id, .never, expected);
        }

        // An array carries its own places, and its length is part of its type,
        // so what a walk over one yields is settled by the type itself. That is
        // asked before any bound is: [T-For] governs a value whose traversal a
        // `Sequence` has to supply, and an array's is the language's own.
        const places: ?TypeId = switch (self.view().get(walked)) {
            .array => |a| a.element,
            else => null,
        };

        // A lending walk asks a different question of the same value. What it
        // takes is nothing, so a `Sequence` -- which hands over what it built
        // and takes the collection to build it -- says nothing about one: the
        // walk names each place where it lives, and that is the traversal and
        // the projection together.
        const lends = self.ast.exprTag(id) != .for_;
        const element = if (lends)
            try self.elementLentBy(id, walked, places)
        else
            places orelse try self.elementWalkedBy(id, f.callee, walked);

        const binder = f.args[0];

        // A lending binder names a place inside what is walked rather than a
        // value of its own, and which position is not known statically -- so
        // its place is conservatively every element, which is the answer that
        // is wrong in the safe direction wherever two places are compared. A
        // tuple pattern's binders each take that whole-element place and not
        // their component's: the walk does not know the element's type until
        // here, and a write to one component while another is in use is
        // refused rather than proven disjoint. The imprecision is in the
        // place; the comparison stays exact, and nothing here reaches the
        // program that runs.
        try self.bindWalked(binder, element, if (lends) .{ .of = f.callee, .step = .{ .element = null } } else null);

        // A walk lending its places writably writes through each of them, so
        // it asks of a projection exactly what an assignment through a bracket
        // asks. The site is the loop: it names one place per position and
        // writes no bracket for the walk over ceilings to find.
        if (self.ast.exprTag(id) == .for_inout and element != .poison) {
            try self.written.append(self.gpa, .{ .at = id, .refused = "this walk lends the places it reaches" });
        }

        // `Option[E]` expected here flows `E` into the break sites, the way
        // `Range[T]` flows `T` into a range's ends: an annotated binding tells
        // each site what it must be rather than leaving them to agree among
        // themselves and disagree with the annotation afterwards.
        const settled: ?Expected = blk: {
            const want = expected orelse break :blk null;
            if (want.ty == .poison) break :blk null;
            const opt = self.option_decl orelse break :blk null;
            const inst = self.builder.instanceOf(want.ty) orelse break :blk null;
            if (inst.decl != opt) break :blk null;
            break :blk .{ .ty = self.builder.argsOf(inst)[0], .at = want.at, .reason = want.reason };
        };

        try self.loops.append(self.gpa, .{
            .settled = settled,
            .broke = false,
        });
        const writable = self.ast.exprTag(id) == .for_inout;
        const lent = if (lends) try self.walkLendBegin(id, binder, writable) else 0;
        const body = try self.check(f.args[1], null);
        if (lends) try self.walkLendEnd(f.args[1], writable, lent);
        const frame = self.loops.pop().?;

        if (body != .unit and body != .never and body != .poison) {
            _ = self.report(
                .t_discard,
                self.resultOf(f.args[1]),
                "this body produces {s} `{s}` that is discarded",
                .{ article.before(try self.typeName(body)), (try self.typeName(body)) },
                "a `for` runs its body once per element",
            );
        }

        if (element == .poison or body == .poison) return self.record(id, .poison);

        // A walk over places the compiler carries moves each element out as it
        // reaches it, so control leaving before the last position leaves those
        // places holding values nothing took. The array as a whole was taken at
        // the head, and there is nothing left to take it apart -- disposal is
        // what would lift this, and there is none.
        //
        // The array's capability and not its element's. What an early exit
        // abandons is the residue of the array, and the array is what says
        // whether that residue owes anything: an array of no places is Copyable
        // however linear its element, because there is no place in it to
        // leave anything at. Asking the element instead refuses a walk over
        // `[T; 0]` for a residue it cannot have -- one question with two
        // answers, and the shorter one is wrong at exactly one length.
        //
        // A lending walk is exempt, and not by exception: it moves nothing out
        // of any place it reaches, so a place it never reached is a place
        // holding what it always held, owed by whatever owns the array.
        if (places) |e| {
            if (!lends and (frame.broke or frame.unwound) and try self.builder.mustConsumeWithin(self.generic, walked)) {
                return self.report(
                    .o_linear_tail,
                    f.callee,
                    "this walk can end early, abandoning the `{s}` at every place it did not reach",
                    .{(try self.typeName(e))},
                    "a walk over an array runs to its end where the element is linear, because nothing takes the places it never reached",
                );
            }
        }

        if (frame.poisoned) return self.record(id, .poison);
        if (!frame.carried) return self.expect(id, .unit, expected);

        const carried = if (frame.settled) |t| t.ty else TypeId.unit;
        if (carried == .poison) return self.record(id, .poison);

        const opt = self.option_decl orelse return self.report(
            .t_for,
            id,
            "a `for` a `break` leaves with a value has no type here: the prelude declares no `Option`",
            .{},
            "build against a library that declares it",
        );
        const made = try self.builder.instantiate(self.type_of_decl.get(opt), opt, &.{carried});
        return self.expect(id, made, expected);
    }

    /// The errors checking `statement` in `main`, beside a `var total` and an
    /// array `xs` of pairs, reports.
    fn errorsOfPairStatement(gpa: std.mem.Allocator, statement: []const u8) !u32 {
        var sink = Sink.init(gpa);
        const text = try std.mem.concat(gpa, u8, &.{
            own_tuple2,
            "fn main() -> UInt8 {\n    var total: UInt8 = 0\n    var xs = [(1, 2), (3, 4)]\n    ",
            statement,
            "\n    total\n}\n",
        });
        _ = try typingAsPrelude(gpa, text, &sink);
        return sink.error_count;
    }

    test "a walk with a tuple pattern takes each component's type, and a mismatch is reported once" {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        for ([_]struct { statement: []const u8, errors: u32 }{
            .{ .statement = "for (i, x) in xs {\n        total = total + i + x\n    }", .errors = 0 },
            .{ .statement = "for read (i, x) in xs {\n        total = total + i + x\n    }", .errors = 0 },
            .{ .statement = "for inout (i, _) in xs {\n        i = i + 1\n    }", .errors = 0 },
            .{ .statement = "for (i, x, y) in xs {\n        total = total + i + x + y\n    }", .errors = 1 },
        }) |case| {
            try testing.expectEqual(case.errors, try errorsOfPairStatement(gpa, case.statement));
        }
    }

    /// `for x in &it { … }` walks the iterator `it` through a writable lend
    /// for the extent of the loop, calling `next` on it once per element. The
    /// loop abandons nothing, so [O-LinearWalk] does not apply and the body
    /// may leave it at any point; what `it` still holds is its owner's to
    /// settle, which [O-Leak] checks at each exit. The lend is exclusive: the
    /// body may neither read nor write `it` by its name.
    fn checkLentWalk(self: *Checker, id: ExprId, iterator: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const f = self.ast.call(id);
        const walked = try self.check(iterator, null);
        _ = self.record(f.callee, walked);
        try self.decideMark(f.callee, .lent);

        const element: TypeId = element: {
            if (walked == .poison) break :element .poison;
            if (!self.isAPlace(iterator)) break :element self.report(
                .t_lend,
                iterator,
                "a walk lends the iterator it advances, so it walks a place",
                .{},
                "bind the iterator to a name and walk `&` that name",
            );
            if (self.iterator_decl == null or !try self.answersTrait(walked, self.iterator_decl)) {
                // An `Iterator` implementation that fails only on demands a
                // bound refusal reported follows from that refusal.
                if (self.iterator_decl) |declared| if (try self.refusalExplains(declared, walked)) break :element .poison;
                const before = self.sink.items().len;
                const reported = self.report(
                    .t_for,
                    iterator,
                    "`{s}` is no `Iterator`, so it has nothing to lend to a walk",
                    .{(try self.typeName(walked))},
                    "walk it without `&`, or lend the walk an iterator over it",
                );
                if (self.iterator_decl) |declared| try self.explainMissing(before, declared, walked);
                break :element reported;
            }
            break :element try self.itemYieldedBy(walked) orelse .poison;
        };
        try self.written.append(self.gpa, .{ .at = iterator, .refused = "this walk advances the iterator it lends" });

        const binder = f.args[0];
        try self.bindWalked(binder, element, null);

        const settled: ?Expected = blk: {
            const want = expected orelse break :blk null;
            if (want.ty == .poison) break :blk null;
            const opt = self.option_decl orelse break :blk null;
            const inst = self.builder.instanceOf(want.ty) orelse break :blk null;
            if (inst.decl != opt) break :blk null;
            break :blk .{ .ty = self.builder.argsOf(inst)[0], .at = want.at, .reason = want.reason };
        };

        try self.loops.append(self.gpa, .{ .settled = settled, .broke = false });
        try self.lendBegin(id, iterator, true);
        const body = try self.check(f.args[1], null);
        _ = self.lent_now.pop();
        const frame = self.loops.pop().?;

        const touched = self.sharedMutation(f.args[1], iterator, false, BindingId.none);
        if (touched != ExprId.none and !self.aliased.contains(touched)) {
            _ = self.report(
                .o_lent,
                touched,
                "this uses the iterator the walk around it is advancing",
                .{},
                "the walk holds it until the loop ends; use it after the loop",
            );
        } else if (self.mentionAt(f.args[1], iterator, BindingId.none) != ExprId.none) {
            _ = self.report(
                .o_lent,
                self.mentionAt(f.args[1], iterator, BindingId.none),
                "this reads the iterator the walk around it is advancing",
                .{},
                "the walk holds it until the loop ends; read it after the loop",
            );
        }

        if (body != .unit and body != .never and body != .poison) {
            _ = self.report(
                .t_discard,
                self.resultOf(f.args[1]),
                "this body produces {s} `{s}` that is discarded",
                .{ article.before(try self.typeName(body)), (try self.typeName(body)) },
                "a `for` runs its body once per element",
            );
        }
        if (element == .poison or body == .poison or frame.poisoned) return self.record(id, .poison);

        if (!frame.carried) return self.expect(id, .unit, expected);
        const carried = if (frame.settled) |t| t.ty else TypeId.unit;
        if (carried == .poison) return self.record(id, .poison);
        const opt = self.option_decl orelse return self.report(
            .t_for,
            id,
            "a `for` a `break` leaves with a value has no type here: the prelude declares no `Option`",
            .{},
            "build against a library that declares it",
        );
        const made = try self.builder.instantiate(self.type_of_decl.get(opt), opt, &.{carried});
        return self.expect(id, made, expected);
    }

    /// `loop { … }` ends only through `break`, so its type is the one its
    /// break sites agree on.
    ///
    /// A loop with no break site does not complete, so it has type Never rather
    /// than Unit: no value exists for a following expression to use.
    fn checkLoop(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        // The expectation flows into the break sites, so an annotated binding
        // tells each what it must be rather than leaving them to agree among
        // themselves and disagree with it afterwards.
        try self.loops.append(self.gpa, .{
            .settled = expected,
            .broke = false,
        });

        const body = try self.check(self.ast.unaryOperand(id), null);
        const frame = self.loops.pop().?;

        if (body == .poison or frame.poisoned) return self.record(id, .poison);

        if (!frame.broke) {
            return self.expect(id, .never, expected);
        }

        const answer = if (frame.settled) |s| s.ty else TypeId.unit;
        return self.expect(id, answer, expected);
    }

    /// `break` or `break e`, leaving the nearest enclosing loop of either kind.
    fn checkBreak(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        if (self.loops.items.len == 0) {
            if (self.closure_hides_loops) return self.report(
                .s_break,
                id,
                "`break` cannot leave a loop outside the closure it is written in",
                .{},
                "a closure's body is a function of its own; return a value that tells the loop to stop",
            );
            return self.report(
                .s_break,
                id,
                "`break` is outside a loop",
                .{},
                "there is no loop for this to leave",
            );
        }

        const value = self.ast.unaryOperand(id);
        const frame = &self.loops.items[self.loops.items.len - 1];

        // Checked against whatever settled the loop's type, so a disagreement
        // reports here and points at what decided. A bare `break` yields Unit
        // and answers to that rule like any other exit -- otherwise it would
        // agree with every type by carrying nothing.
        const t = if (value == ExprId.none) blk: {
            if (frame.settled) |want| {
                if (want.ty != .unit and want.ty != .poison) {
                    break :blk self.reportMismatch(id, .unit, want, "this `break` carries no value");
                }
            }
            break :blk TypeId.unit;
        } else try self.check(value, frame.settled);

        // A value that does not complete never reaches the transfer itself, so
        // it neither settles nor exits the loop.
        if (value != ExprId.none and !self.completionReaches(value)) {
            return self.record(id, .never);
        }

        frame.broke = true;
        if (value != ExprId.none and t == .poison) frame.poisoned = true;
        if (value != ExprId.none) {
            frame.carried = true;
        }
        if (frame.settled == null and t != .poison) {
            frame.settled = .{
                .ty = t,
                .at = .{ .file = self.ast.fileOfExpr(id), .span = self.ast.exprSpan(id) },
                .reason = .break_site,
            };
        }

        _ = expected;
        return self.record(id, .never);
    }

    /// Records that control can leave every loop currently being checked.
    ///
    /// A `return` and a `?` leave the function, so they leave every loop
    /// between here and it -- unlike a `break`, which leaves exactly one and
    /// marks exactly one frame.
    ///
    /// **Bound:** the loop stack holds one frame per enclosing loop of the
    /// expression being checked, so this is the nesting depth of one function
    /// and not a count of anything the program holds. Every frame has to be
    /// marked, so there is no index that would answer instead.
    fn unwindsEveryLoop(self: *Checker) void {
        for (self.loops.items) |*frame| frame.unwound = true;
    }

    /// `return` or `return e`, leaving the function.
    ///
    /// The value answers to what the function declares, not to whatever the
    /// surrounding expression wanted -- a `return` inside an arm is not the
    /// arm's value, it is the function's.
    fn checkReturn(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const value = self.ast.unaryOperand(id);

        const t = if (value == ExprId.none) blk: {
            if (self.current_return) |want| {
                if (want.unit_test_success) {
                    try self.implicit_test_successes.put(self.gpa, id, want.ty);
                } else if (want.ty != .unit and want.ty != .poison) {
                    break :blk self.reportMismatch(id, .unit, want, "this `return` carries no value");
                }
            }
            break :blk TypeId.unit;
        } else blk: {
            var return_expected = self.current_return;
            if (return_expected) |*want| want.unit_test_success = false;
            break :blk try self.check(value, return_expected);
        };
        _ = t;

        // A value that does not complete leaves before `return` itself can.
        if (value != ExprId.none and !self.completionReaches(value)) {
            return self.record(id, .never);
        }

        self.unwindsEveryLoop();

        // The carried value was checked against the function result above;
        // locally, `return` has no continuation and therefore answers Never.
        _ = expected;
        return self.record(id, .never);
    }

    /// A type `?` works over: which of the two it is, and where its
    /// alternatives sit.
    ///
    /// One answer rather than three, and deliberately coupled. Recognising the
    /// type and finding its alternatives cannot be separately true here: a
    /// `Result` whose alternatives are not `Ok` and `Err` is not one `?` can
    /// use, and saying so in one place means no caller carries a "recognised
    /// but unusable" case. That case is what produced a poison type with
    /// nothing reported, and a comparison of two poisons that agreed.
    ///
    /// The coupling has a cost worth stating: renaming `Err` in the library
    /// stops `Result` being recognised at all, and every `?` over one then
    /// reports [T-Try] -- a message naming the type it is refusing. The
    /// library is what is broken there, and the diagnostic blames the program.
    /// Splitting the two answers apart would let the message say which it is,
    /// at the price of the case above; the fix is to check the library's shape
    /// where the prelude is loaded, and neither is owed until a `?` over a
    /// library nobody has edited can reach it.
    const Carrier = struct {
        /// The type this was read from, so the two travel together: every
        /// question below is about a variant *of this type*, and a caller
        /// pairing them by hand is a pair that can be mismatched.
        ty: TypeId,
        kind: Kind,
        success: u32,
        failure: u32,

        const Kind = enum { option, result };

        /// Whether a failure carries anything a caller has to agree about.
        fn carriesAnError(self: Carrier) bool {
            return self.kind == .result;
        }
    };

    fn view(self: *const Checker) Typing {
        return self.builder.view();
    }

    /// `e?`, which yields what a successful `Option` or `Result` carries.
    ///
    /// Two rules, in this order because the second reads what the first
    /// settled: [T-Try] that the operand is one of the two types, and
    /// [T-TryAnswer] that the enclosing function answers with what a failure
    /// would return.
    fn checkTry(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const operand = self.ast.unaryOperand(id);
        const previous = self.success_expected;
        defer self.success_expected = previous;
        self.success_expected = self.successContextOf(id, operand, expected);
        const previous_failure = self.failure_expected;
        defer self.failure_expected = previous_failure;
        self.failure_expected = null;
        if (self.current_return) |answer| if (self.carrierOf(answer.ty)) |carrier| {
            if (carrier.kind == .result) self.failure_expected = .{
                .target = self.ast.withoutGroups(operand),
                .depth = 0,
                .expected = self.errorTypeOf(carrier),
            };
        };
        if (previous_failure) |outer| if (outer.target == id) {
            self.failure_expected = .{
                .target = self.ast.withoutGroups(operand),
                .depth = outer.depth + 1,
                .expected = outer.expected,
            };
        };
        // The carrier comes from the operand. Its open success and failure
        // slots receive only their corresponding enclosing constraints.
        const t = try self.check(operand, null);
        if (t == .poison) return self.record(id, .poison);
        if (t == .never) return self.expect(id, .never, expected);

        const carrier = self.carrierOf(t) orelse return self.report(
            .t_try,
            id,
            "`?` needs an `Option` or a `Result`, and this is `{s}`",
            .{(try self.typeName(t))},
            "`?` works over exactly those two types",
        );

        const want = self.current_return orelse return self.report(
            .t_try_answer,
            id,
            "this `?` may return `{s}`, and the function answers with nothing",
            .{(try self.typeName(t))},
            "`?` returns from the function it is written in",
        );

        // The payload types are free to differ: the failing path of an
        // `Option` carries nothing, so nothing about a payload reaches the
        // caller. A `Result`'s failing path carries an error that does, which
        // is the whole of the asymmetry.
        const answers = self.carrierOf(want.ty);
        if (answers == null or answers.?.kind != carrier.kind) return self.report(
            .t_try_answer,
            id,
            "this `?` may return `{s}`, and the function answers with `{s}`",
            .{ (try self.typeName(t)), (try self.typeName(want.ty)) },
            "`?` returns from the function it is written in",
        );

        // A different error type converts through the function's own error
        // type's `From` implementation, so the target is never in question.
        // An error type the operand's call left open, an open callback
        // result or an integer literal argument's type, already settled on
        // the function's through the failure context above, so conversion
        // is reached only by a known, different type.
        if (carrier.carriesAnError()) {
            const failure = self.errorTypeOf(carrier);
            const answered = self.errorTypeOf(answers.?);
            if (failure != answered and failure != .poison and answered != .poison) {
                const conversion = try self.errorConversion(failure, answered) orelse
                    return self.reportUnconverted(id, failure, answered);
                try self.try_conversions.put(self.gpa, id, conversion);
            }
        }

        // `?` is a `return` on the failing path, so it leaves the loops a
        // `return` leaves. Marked here rather than where it is lowered: what a
        // construct does to the loops around it is a fact about the construct,
        // and one answer to it.
        self.unwindsEveryLoop();

        return self.expect(id, self.payloadTypeOf(carrier), expected);
    }

    /// Returns what the operand of `e?` or `e else { … }` is expected to carry
    /// on success. The construct's own expectation passes to the operand one
    /// success projection deeper, as does one already aimed at the construct.
    fn successContextOf(self: *const Checker, projection: ExprId, operand: ExprId, expected: ?Expected) ?SuccessExpectation {
        const target = self.ast.withoutGroups(operand);
        if (self.success_expected) |outer| if (outer.target == projection) {
            return .{ .target = target, .depth = outer.depth + 1, .expected = outer.expected };
        };
        const want = expected orelse return null;
        return .{ .target = target, .depth = 1, .expected = want };
    }

    /// Checks `e else |error| { … }`, which yields what a successful `Option`
    /// or `Result` carries and runs the block on a failure.
    ///
    /// It reports [T-LetElse] when the operand is neither type or the binder
    /// does not fit what the failure carries, and [T-Mismatch] when the block
    /// completes with something other than the success type.
    fn checkUnwrapElse(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const u = self.ast.unwrapElse(id);
        const t = blk: {
            const previous = self.success_expected;
            defer self.success_expected = previous;
            self.success_expected = self.successContextOf(id, u.operand, expected);
            // The failure is handled here, so nothing outside constrains it.
            const previous_failure = self.failure_expected;
            defer self.failure_expected = previous_failure;
            self.failure_expected = null;
            break :blk try self.check(u.operand, null);
        };

        const carrier = if (t == .poison or t == .never) null else self.carrierOf(t);
        if (carrier == null) {
            self.bindFailure(u, .poison, null);
            _ = try self.check(u.body, null);
            if (t == .never) return self.expect(id, .never, expected);
            if (t != .poison) _ = self.report(
                .t_let_else,
                u.operand,
                "`else` unwraps an `Option` or a `Result`, and this is `{s}`",
                .{(try self.typeName(t))},
                "only an `Option` or a `Result` can fail",
            );
            return self.record(id, .poison);
        }
        const c = carrier.?;

        // A binder the parser could not read has already been reported.
        const written = u.binder != ExprId.none and self.ast.exprTag(u.binder) != .err;
        var poisoned = false;
        switch (c.kind) {
            .option => if (written) {
                _ = self.report(
                    .t_let_else,
                    u.binder,
                    "a failed `{s}` carries nothing to bind",
                    .{(try self.typeName(t))},
                    "write `else { … }` with no binder",
                );
                self.bindFailure(u, .poison, null);
                poisoned = true;
            } else self.bindFailure(u, .poison, null),
            // An `else` the parser could not finish has already been reported.
            .result => if (u.binder == ExprId.none and self.ast.exprTag(u.body) != .err) {
                _ = self.reportAtOp(
                    .t_let_else,
                    id,
                    "a failed `{s}` carries an error, and this `else` binds none",
                    .{(try self.typeName(t))},
                    "name it with `else |error|`, or discard it with `else |_|`",
                );
                poisoned = true;
            } else self.bindFailure(u, self.errorTypeOf(c), c.failure),
        }

        const success = self.payloadTypeOf(c);
        const body = try self.check(u.body, .{
            .ty = success,
            .at = .{ .file = self.ast.fileOfExpr(id), .span = self.ast.tokenSpan(self.ast.exprMain(id)) },
            .reason = .unwrapped,
        });
        if (poisoned or body == .poison) return self.record(id, .poison);
        return self.expect(id, success, expected);
    }

    /// Gives the binder of `e else |error| { … }`, where one is written, the
    /// type of what the failure carries, and records where that value came
    /// from.
    fn bindFailure(self: *Checker, u: Ast.UnwrapElse, ty: TypeId, failure: ?u32) void {
        if (u.binder == ExprId.none) return;
        _ = self.record(u.binder, ty);
        const target = self.res.targetOf(u.binder);
        if (target == BindingId.none) return;
        self.setBindingType(target, ty);
        if (failure) |k| self.binder_places[target.index()] = .{
            .of = u.operand,
            .step = .{ .carried = .{ .variant = k, .index = 0 } },
        };
    }

    /// The type `?` works over that this is, or null for neither.
    ///
    /// Nominal, and the name is resolved the way every ambient name is: the
    /// prelude's own declarations. There is one answer to which declaration
    /// `Option` is, and it is the one every reference to `Option` finds -- a
    /// path to the library's directory would be a second, and would tie this
    /// to where the library keeps its files.
    ///
    /// The alternatives are found here too, so being recognised and being
    /// usable are one answer. A library whose `Result` does not spell its
    /// alternatives `Ok` and `Err` is one `?` cannot use, and every `?` over
    /// it reports [T-Try] rather than yielding a type nothing reported.
    fn carrierOf(self: *const Checker, t: TypeId) ?Carrier {
        const d = self.builder.view().declOfType(t) orelse return null;
        const kind: Carrier.Kind = blk: {
            if (self.option_decl) |o| {
                if (d == o) break :blk .option;
            }
            if (self.result_decl) |r| {
                if (d == r) break :blk .result;
            }
            return null;
        };
        const v = self.view();
        return .{
            .ty = t,
            .kind = kind,
            .success = v.successVariantOf(t) orelse return null,
            .failure = v.failureVariantOf(t) orelse return null,
        };
    }

    /// What a successful one carries: the payload of `Some` or of `Ok`.
    ///
    /// Total, because a `Carrier` is only made where both alternatives were
    /// found. A fallible one answering `.poison` put a poison type on a node
    /// nothing had reported, which is the one thing poison is not allowed to
    /// mean.
    fn payloadTypeOf(self: *const Checker, c: Carrier) TypeId {
        return self.builder.variantFieldType(c.ty, c.success, 0);
    }

    /// What a failing `Result` carries.
    fn errorTypeOf(self: *const Checker, c: Carrier) TypeId {
        return self.builder.variantFieldType(c.ty, c.failure, 0);
    }

    /// Reports a `?` whose failure the function's error type does not
    /// convert from. Where the failure implements `Settle` and its reason is
    /// the function's error type or converts to it, `settled()` before `?`
    /// is what makes the `?` work, and the help says so.
    fn reportUnconverted(self: *Checker, id: ExprId, failure: TypeId, answered: TypeId) std.mem.Allocator.Error!TypeId {
        const failure_name = try self.typeName(failure);
        const message = try std.fmt.allocPrint(
            self.sink.arena,
            "this `?` may fail with `{s}`, and no `From[{s}] for {s}` implementation converts it to the function's error type",
            .{ failure_name, failure_name, try self.typeName(answered) },
        );
        const labels = try self.sink.arena.alloc(Label, 1);
        labels[0] = .{
            .file = self.ast.fileOfExpr(id),
            .span = self.ast.exprSpan(id),
            .message = "`?` converts a different error through `From`: implement it, or convert the error before `?`",
            .style = .primary,
        };
        const notes: []const []const u8 = if (try self.settledReason(failure)) |reason|
            if (reason == answered or try self.errorConversion(reason, answered) != null)
                try self.sink.arena.dupe([]const u8, &.{try std.fmt.allocPrint(
                    self.sink.arena,
                    "call `.settled()` before `?`: it releases what `{s}` hands back and keeps its reason, `{s}`",
                    .{ failure_name, try self.typeName(reason) },
                )})
            else
                &.{}
        else
            &.{};
        self.sink.add(.{ .severity = .err, .code = .t_try_answer, .message = message, .labels = labels, .notes = notes }) catch {};
        return self.record(id, .poison);
    }

    /// The reason `settled()` reduces `failure` to: its `Settle`
    /// implementation's `Reason`, or null where it implements none.
    fn settledReason(self: *Checker, failure: TypeId) std.mem.Allocator.Error!?TypeId {
        const settle_trait = self.settle_decl orelse return null;
        const reason = self.settle_reason orelse return null;
        const settled = try self.associatedTypeOf(settle_trait, reason, "Reason", failure) orelse return null;
        return if (settled == .poison) null else settled;
    }

    /// The `From` operation that converts `failure` into `answered`, where
    /// an implementation or a bound in scope supplies `From[failure]` for
    /// `answered`; null where nothing does.
    fn errorConversion(self: *Checker, failure: TypeId, answered: TypeId) std.mem.Allocator.Error!?types_mod.TryConversion {
        const trait = self.from_decl orelse return null;
        const member = self.from_member orelse return null;
        if (!try self.dischargesDeclared(answered, trait, &.{failure})) return null;
        return .{ .trait = trait, .member = member, .source = failure, .target = answered };
    }

    fn checkContinue(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        if (self.loops.items.len == 0) {
            if (self.closure_hides_loops) return self.report(
                .s_break,
                id,
                "`continue` cannot reach a loop outside the closure it is written in",
                .{},
                "a closure's body is a function of its own; return from the closure instead",
            );
            return self.report(
                .s_break,
                id,
                "`continue` is outside a loop",
                .{},
                "there is no loop for this to continue",
            );
        }
        _ = expected;
        return self.record(id, .never);
    }

    /// `x = e` is Unit. Returning the value assigned would admit `f(x = 3)`,
    /// which reads as a comparison in every language that allows it.
    /// What the place on the left of an assignment holds.
    ///
    /// Both assignments ask it, and it is one routine because it is one
    /// question: a place is a place whether the thing written through it
    /// replaces what is there or is computed from it.
    fn placeType(self: *Checker, written: ExprId) std.mem.Allocator.Error!TypeId {
        // Parentheses name the same place, so they are stepped through before
        // either shape is asked for. Without this `(n) = 7` matched neither,
        // and the poison below silenced it: nothing had gone wrong, so nothing
        // was reported, and lowering then emitted no store for a statement
        // that parsed and type-checked.
        const lhs = self.ast.withoutGroups(written);

        // A place is a name or a path. A path is checked the way it is read --
        // there is one rule for what `o.inner.y` means, and which side of an
        // assignment it is on does not change it.
        const place: TypeId = if (self.ast.exprTag(lhs) == .field or self.ast.exprTag(lhs) == .index or self.ast.exprTag(lhs) == .dereference)
            try self.check(lhs, null)
        else blk: {
            const target = self.res.targetOf(lhs);
            if (target == BindingId.none) break :blk .poison;
            const t = self.binding_types.get(target);
            _ = self.record(lhs, t);
            break :blk t;
        };

        // The parentheses are a node too, and every node carries exactly one
        // type: an expression left without one reads as poison, which is the
        // suite's signal that a pass swallowed an error.
        if (lhs != written) _ = self.record(written, place);

        // Written, so the ceiling of every projection the path runs through
        // has to admit a write. Kept until every body is checked, because a
        // projection this path composes may be declared below the line that
        // writes through it.
        try self.written.append(self.gpa, .{ .at = lhs, .refused = "this place cannot be assigned" });
        return place;
    }

    /// `p += e`, and the three like it.
    ///
    /// The place is typed as `=` types it, and the operand is then held to the
    /// rule `+` reports: checked against the place's type, so a mismatch is
    /// named where `a + b` names it. No arithmetic rule is added, so a place
    /// that is not a number is refused by [T-Operands] exactly as the left of a
    /// `+` is, and the whole is Unit because it is an assignment.
    fn checkCompoundAssign(
        self: *Checker,
        id: ExprId,
        expected: ?Expected,
    ) std.mem.Allocator.Error!TypeId {
        const a = self.ast.binary(id);
        const place = try self.placeType(a.lhs);

        if (place == .poison) {
            _ = try self.check(a.rhs, null);
            return self.record(id, .poison);
        }
        if (place == .never) {
            _ = try self.check(a.rhs, null);
            return self.expect(id, .never, expected);
        }

        const rhs = try self.check(a.rhs, .{
            .ty = place,
            .at = .{ .file = self.ast.fileOfExpr(a.lhs), .span = self.ast.exprSpan(a.lhs) },
            .reason = .operand,
        });
        if (rhs == .poison) return self.record(id, .poison);
        if (rhs == .never) return self.expect(id, .never, expected);

        if (!self.arithmeticHolds(place)) {
            return self.reportAtOp(
                .t_operands,
                id,
                "`{s}` is not a number",
                .{(try self.typeName(place))},
                operandHint(&self.builder, place) orelse "arithmetic is defined over integers",
            );
        }

        if (self.ast.exprTag(id) == .rem_assign and !remainderHoldsIn(place)) {
            return self.reportNoRemainder(id);
        }

        return self.expect(id, .unit, expected);
    }

    /// `%` is truncated modulo, which is what a division leaves. A float
    /// division leaves nothing to be left over from, and the operation IEEE
    /// 754 supplies instead is a different one -- so the operator would mean
    /// two things depending on its operands' type. One reporter for the
    /// operator and its compound assignment, so the two spell one refusal.
    fn reportNoRemainder(self: *Checker, id: ExprId) TypeId {
        return self.reportAtOp(
            .t_operands,
            id,
            "`%` is not defined for `Float64`",
            .{},
            "a float division leaves no remainder to take",
        );
    }

    fn checkAssign(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const a = self.ast.binary(id);
        const lhs = self.ast.withoutGroups(a.lhs);

        // The other position that uses a place whole. A compound assignment is
        // not one: it reads the place and writes it back, and reading a range
        // place is not among the two things one is for.
        const place = blk: {
            const outer = self.whole_place;
            self.whole_place = lhs;
            defer self.whole_place = outer;
            break :blk try self.placeType(a.lhs);
        };

        if (place == .poison) {
            // Undefined, immutable, not a name, or not a field: already
            // reported where it went wrong.
            _ = try self.check(a.rhs, null);
            return self.record(id, .poison);
        }
        if (place == .never) {
            _ = try self.check(a.rhs, null);
            return self.expect(id, .never, expected);
        }

        // The place's type flows into the value, so an assignment is checked
        // the way an initialiser is and reports against the declaration.
        const value = try self.check(a.rhs, .{
            .ty = place,
            .at = .{ .file = self.ast.fileOf(self.ast.exprMain(lhs)), .span = self.ast.tokenSpan(self.ast.exprMain(lhs)) },
            .reason = .assignment,
        });
        if (value == .never) return self.expect(id, .never, expected);

        return self.expect(id, .unit, expected);
    }

    /// `f(a, b)`. Arity is checked before types: a count that does not match
    /// makes every per-argument report noise.
    /// Whether a type's representation is sealed against the module being
    /// checked.
    ///
    /// Boundary-relative: inside the declaring module a sealed type is an
    /// ordinary one. Asked by every site that reaches a representation, which
    /// is why it is a predicate rather than a rule written six times.
    /// What an `extern` may say, which is less than what a function may.
    ///
    /// Two questions, and they are separate mistakes. *Where* it is written:
    /// an `extern` is a signature the compiler believes rather than a body it
    /// checked, and what makes that tolerable is that the believed surface is
    /// small and ships with the compiler -- so a program declaring its own is
    /// refused. And *what it says*: only a type whose representation the
    /// language fixes may cross. An integer's width and signedness are the
    /// whole of its representation; where a structure's fields sit is the
    /// compiler's to decide, and handing one to C would fix that at the
    /// boundary and make observable a layout the corpus reorders declarations
    /// to prove nothing observes.
    /// What an `export` may be, which is one concrete foreign entry point.
    ///
    /// A generic designates none until something instantiates it, and a
    /// program has no foreign surface for one to sit on. Both are this rule
    /// read at a different declaration, which is why they share a name: what
    /// is wrong in each is that nothing outside could link against what was
    /// written.
    fn checkExport(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!void {
        // An entry point is something a caller calls, so only a function can
        // be one. Asked first, because every rule below reads a signature: a
        // type or a constant carries none, so the questions after this one are
        // not questions about it.
        if (self.ast.declTag(d) != .function) {
            try self.sink.addErrorFmt(
                .m_export,
                self.ast.fileOf(self.ast.declName(d)),
                self.ast.tokenSpan(self.ast.declName(d)),
                "export a function, which is what a caller calls",
                "only a function designates a foreign entry point",
                .{},
            );
            return;
        }

        // The root is the surface something outside reaches, and nothing
        // outside can name a module below it -- the same boundary [M-Vis]
        // draws. Refused here rather than left to lowering, which seeds its
        // walk from the root alone: an export below it would otherwise be
        // accepted, exempt from [N-Unused], and absent from the object, with
        // whether it was published turning on whether something in the root
        // happened to reach it.
        if (self.current != self.program.source.primary) {
            try self.sink.addErrorFmt(
                .m_export,
                self.ast.fileOf(self.ast.declName(d)),
                self.ast.tokenSpan(self.ast.declName(d)),
                "publish it from the root, which is what a library's caller reaches",
                "an `export` sits in a library's root module, and this is a module below it",
                .{},
            );
            return;
        }

        if (self.program.kind != .library) {
            try self.sink.addErrorFmt(
                .m_export,
                self.ast.fileOf(self.ast.declName(d)),
                self.ast.tokenSpan(self.ast.declName(d)),
                "a program is entered through `main`",
                "an `export` publishes a library's entry point, and this root is a program",
                .{},
            );
            return;
        }

        if (self.ast.declTypeParams(d).len > 0) {
            try self.sink.addErrorFmt(
                .m_export,
                self.ast.fileOf(self.ast.declName(d)),
                self.ast.tokenSpan(self.ast.declName(d)),
                "export a function that names the types it works on",
                "a generic designates no entry point until something instantiates it",
                .{},
            );
            return;
        }

        // An `extern` is a signature this compiler believes instead of a body
        // it read, so there is nothing for a thunk to wrap and nothing to
        // publish. The two modifiers name opposite directions across one
        // boundary, and a declaration cannot face both ways.
        if (self.ast.declIsExtern(d)) {
            try self.sink.addErrorFmt(
                .m_export,
                self.ast.fileOf(self.ast.declName(d)),
                self.ast.tokenSpan(self.ast.declName(d)),
                "an `extern` is already a symbol something else defines",
                "an `export` publishes a body this compiler read, and an `extern` has none",
                .{},
            );
            return;
        }

        // A test is a body the compiler calls and nothing that ships contains,
        // so there is nothing for an outside caller to link against. The two
        // modifiers answer the same question about who reaches a body, and
        // they answer it differently.
        if (self.ast.declIsTest(d)) {
            try self.sink.addErrorFmt(
                .m_export,
                self.ast.fileOf(self.ast.declName(d)),
                self.ast.tokenSpan(self.ast.declName(d)),
                "a test is run where it is declared, and an export ships",
                "a `test` is called by the compiler, so nothing outside links against it",
                .{},
            );
            return;
        }

        // What crosses is decided by the boundary and not by the direction, so
        // this is the routine `extern` asks; only the rule it is reported
        // under differs.
        try self.checkForeignSignature(d, .t_export);
    }

    fn checkExtern(self: *Checker, d: node.DeclId, granted: bool, library: bool) std.mem.Allocator.Error!void {
        if (!granted) {
            try self.sink.addErrorFmt(
                .m_extern,
                self.ast.fileOf(self.ast.declName(d)),
                self.ast.tokenSpan(self.ast.declName(d)),
                "call it through the standard library, which declares the ones that exist",
                "an `extern` is only declared in a root whose manifest grants `\"extern\": true`",
                .{},
            );
        }

        try self.checkRuntimeSymbol(d, library);

        if (library and self.float_math_candidates.operationOf(d) != null) {
            if (self.float_math.operationOf(d) != null) return;
            return self.sink.addError(.t_extern, self.ast.fileOf(self.ast.declName(d)), self.ast.tokenSpan(self.ast.declName(d)), "a scalar math primitive must have its compiler-defined signature", "restore the private scalar declaration with read Float64 parameters and result");
        }
        if (library and self.raw_accesses.typed(d)) {
            const saved = self.generic;
            self.generic = d;
            defer self.generic = saved;
            if (try self.validStorageSignature(d)) return;
            return self.sink.addError(.t_extern, self.ast.fileOf(self.ast.declName(d)), self.ast.tokenSpan(self.ast.declName(d)), "a typed storage primitive must have its compiler-defined signature", "restore the private storage declaration's parameter and result types");
        }
        try self.checkForeignSignature(d, .t_extern);
    }

    /// Holds an `extern` naming a `linea_` symbol to the signature the runtime
    /// gives it ([T-ExternRuntime]). The namespace is the runtime's, so the
    /// rule reads the symbol and never which root declared it: the standard
    /// library's declarations answer to the table as anyone's do. The symbols
    /// the compiler owns outright are [T-Extern]'s.
    fn checkRuntimeSymbol(self: *Checker, d: node.DeclId, library: bool) std.mem.Allocator.Error!void {
        const name = self.ast.tokenText(self.ast.declName(d));
        if (!std.mem.startsWith(u8, name, runtime_symbols.namespace) or runtime_symbols.holds(name)) return;
        const file = self.ast.fileOf(self.ast.declName(d));
        const span = self.ast.tokenSpan(self.ast.declName(d));
        const expected = runtime_symbols.signatureOf(name) orelse {
            return self.sink.addErrorFmt(
                .t_extern_runtime,
                file,
                span,
                "name a function the runtime provides, or give yours a name outside the `linea_` prefix",
                "the runtime declares no function `{s}`, and the `linea_` names are the runtime's",
                .{name},
            );
        };
        // Lowering replaces the standard library's own `mem` declaration and
        // no other, so that declaration is held to the table like any other
        // and every other one has nothing to link against.
        if (expected.provider == .lowering and !(library and self.program.libraryDeclIn("mem", name) == d)) {
            return self.sink.addErrorFmt(
                .t_extern_runtime,
                file,
                span,
                "reach it through the standard library's checked storage operations",
                "`{s}` is replaced by the compiler where the standard library declares it, so the runtime defines nothing to link against",
                .{name},
            );
        }
        const declared = self.checkedExternSignature(d) orelse return;
        if (intrinsics.matchesRuntime(&self.builder.view(), declared, expected.*)) return;
        var spelled: std.ArrayList(u8) = .empty;
        defer spelled.deinit(self.gpa);
        try spelled.appendSlice(self.gpa, "fn(");
        for (expected.parameters, 0..) |parameter, i| {
            if (i > 0) try spelled.appendSlice(self.gpa, ", ");
            if (parameter.passing == .inout) try spelled.appendSlice(self.gpa, "inout ");
            try spelled.appendSlice(self.gpa, runtimeScalarName(parameter.scalar));
        }
        try spelled.append(self.gpa, ')');
        if (expected.result != .unit) {
            try spelled.appendSlice(self.gpa, " -> ");
            try spelled.appendSlice(self.gpa, runtimeScalarName(expected.result));
        }
        try self.sink.addErrorFmt(
            .t_extern_runtime,
            file,
            span,
            "declare it with the runtime's parameter types, conventions and result",
            "the runtime gives `{s}` the signature `{s}`",
            .{ name, spelled.items },
        );
    }

    /// Groups `extern` declarations by the symbol they name. The runtime
    /// provides one function per symbol, so a later declaration of a symbol
    /// stands for the first and must agree with it on every parameter's type
    /// and convention and on the result. Walks every declaration, retained
    /// library ones included, because a program's own modules may repeat a
    /// symbol the library declared.
    fn settleExternSymbols(self: *Checker) std.mem.Allocator.Error!void {
        var first: std.StringHashMapUnmanaged(node.DeclId) = .empty;
        defer first.deinit(self.gpa);
        for (0..self.program.modules.len) |mi| {
            for (self.program.declsOf(ModuleId.from(mi))) |d| {
                if (!self.ast.declIsExtern(d)) continue;
                const seen = try first.getOrPut(self.gpa, self.ast.tokenText(self.ast.declName(d)));
                if (!seen.found_existing) {
                    seen.value_ptr.* = d;
                    continue;
                }
                const earlier = seen.value_ptr.*;
                // A signature carrying poison was already refused, and
                // comparing it would only repeat that refusal.
                const agrees = self.externsAgree(earlier, d) orelse continue;
                if (agrees) {
                    try self.extern_symbols.put(self.gpa, d, earlier);
                } else if (runtime_symbols.signatureOf(self.ast.tokenText(self.ast.declName(d))) != null) {
                    // [T-ExternRuntime] holds each declaration to the runtime's
                    // own signature, which answers for the disagreement.
                } else if (!self.isRetained(d) or !self.isRetained(earlier)) {
                    // A library declaration is not the program's to change,
                    // so the report lands on the program's own one.
                    const reported, const other = if (self.declaredInLibrary(d) and !self.declaredInLibrary(earlier)) .{ earlier, d } else .{ d, earlier };
                    try self.sink.addErrorFmt(
                        .t_extern_agreement,
                        self.ast.fileOf(self.ast.declName(reported)),
                        self.ast.tokenSpan(self.ast.declName(reported)),
                        "declare it with the parameter types, conventions and result of the other declaration",
                        "`{s}` is declared with another signature in module `{s}`, and one runtime symbol has one signature",
                        .{ self.ast.tokenText(self.ast.declName(reported)), self.program.modules[self.program.moduleOf(other).index()].name },
                    );
                }
            }
        }
    }

    /// Whether two extern signatures agree, or null when either carries
    /// poison and so cannot be compared.
    fn externsAgree(self: *Checker, one: node.DeclId, other: node.DeclId) ?bool {
        const a = self.checkedExternSignature(one) orelse return null;
        const b = self.checkedExternSignature(other) orelse return null;
        if (a.result != b.result) return false;
        const a_params = self.builder.callableParams(a);
        const b_params = self.builder.callableParams(b);
        if (a_params.len != b_params.len) return false;
        for (a_params, b_params) |x, y| {
            if (x.ty != y.ty or x.convention != y.convention) return false;
        }
        return true;
    }

    fn checkedExternSignature(self: *Checker, d: node.DeclId) ?types_mod.CallableSignature {
        const signature = switch (self.builder.get(self.decl_signatures.get(d))) {
            .callable => |callable| callable,
            else => return null,
        };
        if (signature.result == .poison) return null;
        for (self.builder.callableParams(signature)) |param| if (param.ty == .poison) return null;
        return signature;
    }

    fn checkStorageCertificates(self: *Checker, declarations: types_mod.Returns) !void {
        const raw = self.raw_accesses;
        if (raw.slice != .none) {
            const d = raw.slice;
            const ty = declarations.get(d);
            const valid = self.ast.declTag(d) == .struct_ and
                self.ast.declVisibility(d) == .opaque_ and self.ast.declOwnershipPolicy(d) == .copyable and
                self.ast.declTypeParams(d).len == 1 and self.builder.fieldCount(ty) == 2 and
                std.mem.eql(u8, self.builder.fieldName(ty, 0), "at") and self.builder.fieldType(ty, 0) == .u64 and
                std.mem.eql(u8, self.builder.fieldName(ty, 1), "len") and self.builder.fieldType(ty, 1) == .u64;
            if (!valid) self.reportAtToken(.t_borrow_contract, self.ast.declName(d), "the Slice certificate requires an opaque copyable address-and-length descriptor", "declare at and len as UInt64 fields and exactly one element parameter", null);
        }
        if (raw.storage != .none) {
            const d = raw.storage;
            const ty = declarations.get(d);
            var valid = self.ast.declTag(d) == .struct_ and
                self.ast.declVisibility(d) == .private and self.ast.declOwnershipPolicy(d) != .copyable and
                self.ast.declTypeParams(d).len == 2 and self.builder.fieldCount(ty) == 4;
            if (valid) {
                const optional = self.builder.fieldType(ty, 0);
                const optional_args = self.builder.appliedTo(optional);
                const allocator = self.param_types[d.index()][1];
                valid = std.mem.eql(u8, self.builder.fieldName(ty, 0), "buffer") and self.option_decl != null and
                    self.builder.view().declOfType(optional) == self.option_decl and optional_args.len == 1 and
                    std.mem.eql(u8, self.builder.fieldName(ty, 1), "allocator") and self.builder.fieldType(ty, 1) == allocator and
                    std.mem.eql(u8, self.builder.fieldName(ty, 2), "at") and self.builder.fieldType(ty, 2) == .u64 and
                    std.mem.eql(u8, self.builder.fieldName(ty, 3), "len") and self.builder.fieldType(ty, 3) == .u64;
                if (valid) {
                    const buffer = optional_args[0];
                    const args = self.builder.appliedTo(buffer);
                    valid = raw.buffer != .none and self.builder.view().declOfType(buffer) == raw.buffer and
                        args.len == 1 and args[0] == allocator;
                }
            }
            if (!valid) self.reportAtToken(.t_borrow_contract, self.ast.declName(d), "the Storage certificate requires private move-only typed buffer containment", "declare Storage[T, A] with buffer: Option[Buffer[A]], allocator: A, at: UInt64, and len: UInt64 fields", null);
        }
        if (raw.closure != .none) {
            const d = raw.closure;
            if (!self.certifiedClosure(declarations, d)) self.reportAtToken(.t_borrow_contract, self.ast.declName(d), "the Closure certificate requires an opaque affine entry, release, address, length and buffer", "declare Closure[S, A] with entry: ClosureEntry[S], settle: fn(at: UInt64, len: UInt64), at: UInt64, len: UInt64, and storage: Option[Buffer[A]] fields", null);
        }
    }

    /// Lowering reads a `Closure`'s entry, address and length by name and
    /// generates what its entry and release point at, so the library's
    /// declaration must hold exactly those fields: a private field-less
    /// `ClosureEntry[S]`, the release signature, and the buffer that owns the
    /// stored callable's bytes.
    fn certifiedClosure(self: *Checker, declarations: types_mod.Returns, d: DeclId) bool {
        const raw = self.raw_accesses;
        const ty = declarations.get(d);
        if (self.ast.declTag(d) != .struct_ or self.ast.declVisibility(d) != .opaque_ or
            self.ast.declOwnershipPolicy(d) != .affine or self.ast.declTypeParams(d).len != 2 or
            self.builder.fieldCount(ty) != 5 or raw.closure_entry_type == .none or raw.buffer == .none) return false;
        const entry_decl = raw.closure_entry_type;
        const entry_template = declarations.get(entry_decl);
        if (self.ast.declTag(entry_decl) != .struct_ or self.ast.declVisibility(entry_decl) != .private or
            self.ast.declTypeParams(entry_decl).len != 1 or self.builder.fieldCount(entry_template) != 0) return false;
        const signature = self.param_types[d.index()][0];
        const allocator = self.param_types[d.index()][1];
        const names = [_][]const u8{ "entry", "settle", "at", "len", "storage" };
        for (names, 0..) |name, i| {
            if (!std.mem.eql(u8, self.builder.fieldName(ty, @intCast(i)), name)) return false;
        }
        const entry = self.builder.fieldType(ty, 0);
        const entry_args = self.builder.appliedTo(entry);
        if (self.builder.view().declOfType(entry) != entry_decl or entry_args.len != 1 or entry_args[0] != signature) return false;
        const release = switch (self.builder.get(self.builder.fieldType(ty, 1))) {
            .callable => |release| release,
            else => return false,
        };
        const release_params = self.builder.callableParams(release);
        if (release.result != .unit or release.invocation != .read or release_params.len != 2 or
            release_params[0].ty != .u64 or release_params[1].ty != .u64) return false;
        if (self.builder.fieldType(ty, 2) != .u64 or self.builder.fieldType(ty, 3) != .u64) return false;
        const optional = self.builder.fieldType(ty, 4);
        const optional_args = self.builder.appliedTo(optional);
        if (self.option_decl == null or self.builder.view().declOfType(optional) != self.option_decl or optional_args.len != 1) return false;
        const buffer_args = self.builder.appliedTo(optional_args[0]);
        if (self.builder.view().declOfType(optional_args[0]) != raw.buffer or buffer_args.len != 1 or buffer_args[0] != allocator) return false;
        // Each opener's callback is bounded by the implementation's first
        // parameter, which must be `S`, and it is the one type parameter the
        // opener declares. `open_in` takes the allocator and then the callback;
        // `open`, on the system closure, takes the callback alone.
        return self.validClosureOpener(raw.closure_open_in, .{ .head = 2, .params = 2 }) and
            self.validClosureOpener(raw.closure_open, .{ .head = 1, .params = 1 });
    }

    fn validClosureOpener(self: *const Checker, open: DeclId, shape: struct { head: usize, params: usize }) bool {
        if (open == .none) return true;
        const head = self.headParametersOf(open);
        const params = self.ast.declParams(open);
        return head != .none and self.ast.declTypeParams(head).len == shape.head and self.ast.declTypeParams(open).len == 1 and
            params.len == shape.params and params[shape.params - 1].convention == .sink;
    }

    fn validStorageEffects(self: *const Checker, d: DeclId) bool {
        const signature = self.builder.get(self.decl_signatures.get(d));
        if (signature != .callable) return false;
        const raw = self.raw_accesses;
        const contracts = signature.callable.contracts;
        if (d == raw.stride or raw.processText(d) != null) return contracts.len == 0;
        if (contracts.len != 1) return false;
        const effect = contracts[0];
        if (effect.target.len != 0 or effect.source.fields.len != 0 or effect.borrows_source) return false;
        if (d == raw.put) return effect.kind == .retains and effect.source.root == .parameter and effect.source.root.parameter == 4 and
            effect.destination != null and effect.destination.?.root == .parameter and effect.destination.?.root.parameter == 0 and effect.destination.?.fields.len == 0;
        return effect.destination == null and effect.source.root == .parameter and effect.source.root.parameter == 0 and
            effect.kind == (if (d == raw.span or d == raw.buffer_span) @as(@FieldType(types_mod.CallableContract, "kind"), .borrows) else .carries);
    }

    fn validStorageSignature(self: *Checker, d: DeclId) !bool {
        if (self.raw_accesses.erasure(d)) return self.validErasureSignature(d);
        if (!self.validStorageEffects(d)) return false;
        const raw = self.raw_accesses;
        if (d == raw.span or d == raw.buffer_span or d == raw.subspan or d == raw.slice_place or raw.processText(d) != null) return self.validSpanSignature(d);
        const count: usize = if (d == raw.stride) 1 else 2;
        const tps = self.ast.declTypeParams(d);
        if (tps.len != count or self.ast.declVisibility(d) != .private) return false;
        const result = try self.declaredResultType(d);
        const ps = self.ast.declParams(d);
        if (d == raw.stride) {
            const shape = try self.declaredParamType(d, 0);
            const declared = self.program.libraryDeclIn("mem", "SlotType") orelse return false;
            const applied = self.builder.appliedTo(shape);
            return result == .u64 and ps[0].convention == .read and self.builder.view().declOfType(shape) == declared and
                applied.len == 1 and applied[0] == self.param_types[d.index()][0];
        }
        const element = self.param_types[d.index()][0];
        const allocator = self.param_types[d.index()][1];
        const owner = try self.declaredParamType(d, 0);
        const applied = self.builder.appliedTo(owner);
        if (raw.storage == .none or self.builder.view().declOfType(owner) != raw.storage or
            applied.len != 2 or applied[0] != element or applied[1] != allocator or
            ps[0].convention != (if (d == raw.place) node.Convention.read else .inout)) return false;
        const scalar_end: usize = if (d == raw.place) 5 else 4;
        for (ps[1..scalar_end], 1..) |p, k| {
            if (try self.declaredParamType(d, k) != .u64 or p.convention != .read) return false;
        }
        if (d == raw.put) return result == .unit and ps[4].convention == .sink and
            try self.declaredParamType(d, 4) == element;
        return result == element;
    }

    /// `closure_size[F]` answers a `UInt64`, `closure_settle[F]` the release
    /// `fn(at: UInt64, len: UInt64)`, and `closure_entry[S, F]` a
    /// `ClosureEntry[S]`. Each reads its callable type `F` off a `SlotType[F]`
    /// and promises nothing about dependencies.
    fn validErasureSignature(self: *Checker, d: DeclId) !bool {
        const raw = self.raw_accesses;
        const signature = self.builder.get(self.decl_signatures.get(d));
        if (signature != .callable or signature.callable.contracts.len != 0) return false;
        const tps = self.ast.declTypeParams(d);
        const ps = self.ast.declParams(d);
        const count: usize = if (d == raw.closure_entry) 2 else 1;
        if (tps.len != count or ps.len != 1 or ps[0].convention != .read or self.ast.declVisibility(d) != .private) return false;
        const callable = self.param_types[d.index()][count - 1];
        const shape = try self.declaredParamType(d, 0);
        const slot_type = self.program.libraryDeclIn("mem", "SlotType") orelse return false;
        const applied = self.builder.appliedTo(shape);
        if (self.builder.view().declOfType(shape) != slot_type or applied.len != 1 or applied[0] != callable) return false;
        const result = try self.declaredResultType(d);
        if (d == raw.closure_size) return result == .u64;
        if (d == raw.closure_entry) {
            const entry_args = self.builder.appliedTo(result);
            return raw.closure_entry_type != .none and self.builder.view().declOfType(result) == raw.closure_entry_type and
                entry_args.len == 1 and entry_args[0] == self.param_types[d.index()][0];
        }
        const release = switch (self.builder.get(result)) {
            .callable => |release| release,
            else => return false,
        };
        const params = self.builder.callableParams(release);
        return release.result == .unit and release.invocation == .read and release.contracts.len == 0 and params.len == 2 and
            params[0].ty == .u64 and params[0].convention == .read and params[1].ty == .u64 and params[1].convention == .read;
    }

    fn validSpanSignature(self: *Checker, d: DeclId) !bool {
        const raw = self.raw_accesses;
        const ps = self.ast.declParams(d);
        const tps = self.ast.declTypeParams(d);
        const process_text = raw.processText(d) != null;
        const count: usize = if (process_text) 0 else if (d == raw.span) 2 else 1;
        if (tps.len != count or self.ast.declVisibility(d) != .private or raw.slice == .none) return false;
        for (ps) |param| if (param.convention != .read or param.default != .none) return false;
        const element = if (d == raw.buffer_span or process_text) TypeId.u8 else self.param_types[d.index()][0];
        const result = try self.declaredResultType(d);
        if (d == raw.slice_place) {
            if (result != element) return false;
        } else {
            const result_args = self.builder.appliedTo(result);
            if (self.builder.view().declOfType(result) != raw.slice or result_args.len != 1 or result_args[0] != element) return false;
        }
        if (process_text) return try self.declaredParamType(d, 0) == .u64;
        const owner = try self.declaredParamType(d, 0);
        const owner_args = self.builder.appliedTo(owner);
        const owner_decl = if (d == raw.span) raw.storage else if (d == raw.buffer_span) self.program.libraryDeclIn("mem", "Buffer") orelse return false else raw.slice;
        if (self.builder.view().declOfType(owner) != owner_decl) return false;
        if (d == raw.span) {
            if (owner_args.len != 2 or owner_args[0] != element or owner_args[1] != self.param_types[d.index()][1]) return false;
        } else if (d == raw.buffer_span) {
            if (owner_args.len != 1 or owner_args[0] != self.param_types[d.index()][0]) return false;
        } else if (owner_args.len != 1 or owner_args[0] != element) return false;
        for (1..ps.len) |k| if (try self.declaredParamType(d, k) != .u64) return false;
        return true;
    }

    /// Whether this declaration's signature may cross the foreign boundary.
    ///
    /// An integer's width and its signedness are the whole of its
    /// representation, so both sides of the boundary already agree about it.
    /// Neither an aggregate nor a linear value may cross, and which way it was
    /// going does not enter into it: where a structure's fields sit is the
    /// compiler's to decide either way, and ownership can no more read a
    /// caller this compiler did not compile than a callee.
    ///
    /// One predicate with two callers rather than two that agree. `category`
    /// is the whole of what the two directions do not share -- it names where
    /// the mistake was made, so a programmer writing an `export` is not sent
    /// to a rule about `extern`.
    fn checkForeignSignature(
        self: *Checker,
        d: node.DeclId,
        category: Code,
    ) std.mem.Allocator.Error!void {
        // The bare source name is what a C header spells, so it steps outside
        // the prefix that keeps every other symbol this language defines clear
        // of the runtime's. Refused here, which is the only place that can say
        // so against the declaration a person wrote: left to the linker it is a
        // redefinition reported against generated code, and left to neither it
        // is a call that reaches the wrong body.
        if (runtime_symbols.holds(self.ast.tokenText(self.ast.declName(d)))) {
            // Accepted compiler primitives bypass the foreign ABI above.
            // A remaining extern must not reach one under a different signature.
            if (category == .t_extern) {
                return self.sink.addErrorFmt(
                    .t_extern,
                    self.ast.fileOf(self.ast.declName(d)),
                    self.ast.tokenSpan(self.ast.declName(d)),
                    "use the checked standard-library operation",
                    "`{s}` is a compiler-owned runtime symbol and cannot be declared with this foreign signature",
                    .{self.ast.tokenText(self.ast.declName(d))},
                );
            }
            try self.sink.addErrorFmt(
                .m_export,
                self.ast.fileOf(self.ast.declName(d)),
                self.ast.tokenSpan(self.ast.declName(d)),
                "publish it under a name of your own",
                "`{s}` is a symbol the runtime defines, so nothing may export it",
                .{self.ast.tokenText(self.ast.declName(d))},
            );
            return;
        }

        // `foreignWidth` and not an arithmetic predicate: what may cross is
        // decided by what a boundary can agree about, not by what an operator
        // accepts. The two differ on `Float64`, which every operator takes and
        // no ABI here fixes -- and the backend, which asks `foreignWidth`,
        // would have been handed a type it cannot print.
        for (self.ast.declParams(d), 0..) |p, k| {
            const t = try self.declaredParamType(d, k);
            if (t == .poison or t.foreignWidth() != null) continue;
            if (p.written.kind == .callable) {
                const name = try spellWrittenOwned(self.gpa, self.ast, p.written);
                defer self.gpa.free(name);
                try self.reportForeignType(d, category, self.ast.writtenSpan(p.written), name);
            } else {
                try self.reportForeignType(d, category, self.ast.tokenSpan(p.name), (try self.typeName(t)));
            }
        }

        const written_answer = self.ast.declReturnRef(d);
        const answers = try self.declaredResultType(d);
        if (answers != .poison and answers != .unit and answers.foreignWidth() == null) {
            if (written_answer.kind == .callable) {
                const name = try spellWrittenOwned(self.gpa, self.ast, written_answer);
                defer self.gpa.free(name);
                try self.reportForeignType(d, category, self.ast.writtenSpan(written_answer), name);
            } else {
                try self.reportForeignType(d, category, self.ast.tokenSpan(self.ast.declName(d)), (try self.typeName(answers)));
            }
        }
    }

    /// Builds a function declaration's signature once, in its own module and
    /// generic scope, whichever of its readers asks first.
    fn ensureSignature(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!void {
        if (self.signature_built[d.index()]) return;
        self.signature_built[d.index()] = true;
        try self.ensureDefaults(d);

        const outer_module = self.current;
        const outer_generic = self.generic;
        self.current = self.program.moduleOf(d);
        self.generic = d;
        defer {
            self.current = outer_module;
            self.generic = outer_generic;
        }
        self.decl_signatures.set(d, try self.callableSignatureOf(d));
    }

    /// Each default this declaration writes: typed against the parameter it
    /// belongs to, and folded to the value a call omitting that parameter
    /// receives.
    ///
    /// Once per declaration, which is the only place a default can be worked
    /// out at all. There is no evaluation site at a call -- nothing there is in
    /// scope for the expression, and an omission runs nothing -- so the value
    /// is settled here or nowhere, and every call omitting the parameter reads
    /// this one answer. Whether a parameter has a default is read off the tree;
    /// what it is worth is read from here, and neither is worked out twice.
    ///
    /// **Bound:** one walk of this declaration's own parameters, and the check
    /// of each default it writes. Nothing here is sized by the program.
    fn ensureDefaults(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!void {
        if (self.defaults_folded[d.index()]) return;
        self.defaults_folded[d.index()] = true;

        const outer_module = self.current;
        const outer_generic = self.generic;
        self.current = self.program.moduleOf(d);
        self.generic = d;
        defer {
            self.current = outer_module;
            self.generic = outer_generic;
        }
        try self.foldDefaults(d);
    }

    fn foldDefaults(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!void {
        const params = self.ast.declParams(d);
        // Walked from the bindings rather than from the parameters, because
        // the type is the binding's. Every index this yields is in range: the
        // resolver numbers each binding by its position in this same list, so
        // a binding exists for a subset of the parameters and names one of
        // them. The direction lowering walks is the other one and can miss,
        // which is why it defends and this does not.
        for (self.res.parametersOf(d)) |sym| {
            const at = self.res.paramIndexOf(sym);
            const p = params[at];
            if (!hasDefault(p)) continue;

            // The parameter's declared type, read from where this pass
            // recorded it rather than settled a second time from the
            // annotation: a default is checked against exactly the type an
            // argument in that position is checked against.
            // A parameter typed by a type parameter that has a default holds
            // that default's constants, since a call that settles nothing else
            // takes the default type.
            const bound = self.binding_types.get(sym);
            const declared = (try self.defaultedTypeParameter(d, bound)) orelse bound;
            const want: ?Expected = if (declared == .poison) null else .{
                .ty = declared,
                .at = .{ .file = self.ast.fileOf(p.name), .span = self.ast.tokenSpan(p.name) },
                .reason = .parameter,
            };
            if (try self.rejectParameterDefault(p.default, declared)) continue;
            const scope = self.openScope();
            _ = try self.check(p.default, want);
            try self.closeScope(scope);

            // A default is worth what the parameter's type says it is worth, so
            // where there is no type to check it against there is no default:
            // recording one splices a value nothing held to the parameter's
            // shape into every call that omits it, and an integer folded
            // against no expectation is what reached a parameter the size of a
            // struct. A signature's `Self` is the one such type that arrives
            // here undiagnosed -- it stands for whatever implements the trait,
            // settled by the call -- so it is reported here, and every other
            // way a parameter's type is unknown was reported where the
            // annotation was read.
            if (declared == .poison) {
                if (self.ast.declIsSignature(d) and namesSelf(self.ast, p.written.name)) {
                    _ = self.report(
                        .t_default,
                        p.default,
                        "`{s}`'s type is settled by the call, so a default has no value to be",
                        .{self.ast.tokenText(p.name)},
                        "`Self` stands for whatever implements the trait",
                    );
                }
                continue;
            }

            // What the value is, in the type the parameter declares: a default
            // outside that type is refused where it is written, so what a call
            // fills in is a value that type holds.
            const folded = try self.worth(p.default);
            if (folded.checked()) |value| {
                // An `inout` default is refused for that alone, which says
                // all there is to say about it.
                if (p.convention != .inout and try self.refuseObligedConstant(.t_default, p.default, declared)) continue;
                const planned = try self.validateConstant(value, declared);
                if (planned == .planned) {
                    try self.defaults.note(self.gpa, @intCast(d.index()), at, value);
                    continue;
                }
                if (planned == .uncopyable) {
                    try self.reportDefaultNotConstant(p.default, planned);
                    continue;
                }
            }

            // Reported for the form and not for the absence, exactly as
            // [T-Const] is: an expression the checker poisoned has already been
            // told what is wrong with it, and whether the definition admits a
            // form is a question about an expression that no longer exists. A
            // default whose type is a type parameter lands there -- there is no
            // constant of an abstract type for the literal to have been, which
            // its own typing says before this is asked.
            if (self.builder.exprType(p.default) == .poison) continue;

            if (folded == .absent) continue;
            try self.reportDefaultNotConstant(p.default, .refused);
        }
    }

    /// Said the same way in both directions, because what is wrong is the same
    /// thing: the language does not fix this type's representation, so the two
    /// sides could not agree about it whichever way it travelled.
    fn reportForeignType(
        self: *Checker,
        d: node.DeclId,
        category: Code,
        span: @import("../support/span.zig").Span,
        name: []const u8,
    ) std.mem.Allocator.Error!void {
        try self.sink.addErrorFmt(
            category,
            self.ast.fileOf(self.ast.declName(d)),
            span,
            "pass what it is made of, as integers",
            "`{s}` may not cross the foreign boundary: only an integer's representation is the language's to fix",
            .{name},
        );
    }

    /// Records what a checked variant reference folds to, so an enclosing
    /// group or alias reads the same answer the shared folder gives.
    fn foldVariantReference(self: *Checker, id: ExprId, t: TypeId) std.mem.Allocator.Error!TypeId {
        if (t != .poison) self.folds.set(id, .of(try self.worth(id)));
        return t;
    }

    /// Whether a variant reference builds a value of a type sealed here. A
    /// payload-free variant is built by the reference itself; a variant with
    /// a payload is built by its call, which answers for the seal there.
    fn buildsSealedVariant(self: *const Checker, ty: TypeId, ordinal: ?u32) bool {
        const k = ordinal orelse return false;
        if (!self.sealedHere(ty)) return false;
        return self.builder.variantFieldCount(ty, k) == 0;
    }

    /// How this module writes the name of `ty`'s declaration, as every other
    /// report of a type writes it: the bare name where the module declares or
    /// imports it under that name, and otherwise the module name its import
    /// binds, so the path resolves where it is read.
    fn pathToType(self: *const Checker, spelled: []const u8, ty: TypeId) std.mem.Allocator.Error![]const u8 {
        const d = self.declaringType(ty) orelse return spelled;
        var out: std.Io.Writer.Allocating = .init(self.gpa);
        errdefer out.deinit();
        writeDeclaredName(&out.writer, self.ast, self.program, self.res, self.current, d) catch return error.OutOfMemory;
        return out.toOwnedSlice();
    }

    fn sealedHere(self: *const Checker, ty: TypeId) bool {
        const d = self.declaringType(ty) orelse return false;
        if (self.ast.declVisibility(d) != .opaque_) return false;
        return self.program.moduleOf(d) != self.current;
    }

    /// The declaration a type came from, whether it is the type that
    /// declaration entered or an instantiation of it.
    ///
    /// An instantiation is a pool entry of its own, so a scan for the handle
    /// the declaration entered never matches one -- and a question asked about
    /// `Account[u8]` was answered about no declaration at all. `opaque` seals
    /// what a declaration says, so a type parameter cannot be what decides
    /// whether it is sealed.
    fn declaringType(self: *const Checker, ty: TypeId) ?node.DeclId {
        if (ty == .poison) return null;
        if (self.builder.instanceOf(ty)) |i| return i.decl;
        return self.decl_of_type.get(ty);
    }

    /// Reports reaching a sealed type's representation, and poisons.
    ///
    /// The message names where the representation *is* visible rather than
    /// only that it is not visible here: what a reader does next is call
    /// something in that module, and the message says which.
    /// A variant that carries values, written where a finished value of its
    /// enum is expected, names no payload to store. Refused here so no later
    /// `match` reads one that was never written. A construction's callee and
    /// a constructor callback reach their variant through other paths. With
    /// nothing expected, the name is neither a construction nor a constructor
    /// value, so what is missing is the context rather than the payload.
    fn missingPayload(self: *Checker, id: ExprId, ty: TypeId, ordinal: u32, expected: ?Expected) ?TypeId {
        if (id == self.construction_callee) return null;
        const carries = self.builder.variantFieldCount(ty, ordinal);
        if (carries == 0) return null;
        if (expected == null) return self.report(
            .t_infer,
            id,
            "`{s}` carries {d} value(s), and nothing here says whether this builds it or names its constructor",
            .{ self.ast.tokenText(self.ast.exprMain(id)), carries },
            "supply its values, or give the binding a callable type",
        );
        return self.report(
            .t_arity,
            id,
            "`{s}` carries {d} value(s), and this builds it with none",
            .{ self.ast.tokenText(self.ast.exprMain(id)), carries },
            "supply its values, such as `Variant(value)`",
        );
    }

    fn reportSealed(self: *Checker, at: ExprId, ty: TypeId, what: []const u8) TypeId {
        const before = self.sink.items().len;
        self.sealedAt(self.ast.fileOfExpr(at), self.ast.exprSpan(at), ty, what);
        self.explainShadowedHead(at, before) catch {};
        return self.record(at, .poison);
    }

    /// A contract path naming a sealed field or variant. The path is part of a
    /// signature, so it is reported at the name rather than at an expression.
    fn reportSealedAtToken(self: *Checker, at: TokenId, ty: TypeId) void {
        self.sealedAt(self.ast.fileOf(at), self.ast.tokenSpan(at), ty, "only its own module's contracts can name its parts");
    }

    fn sealedAt(self: *Checker, file: FileId, span: Span, ty: TypeId, what: []const u8) void {
        // The declaration's own name, not the pool's: a compound type is
        // spelled `<compound>` there, which names nothing a reader can look up.
        var named: []const u8 = "the type";
        var owner: []const u8 = "its module";
        if (self.declaringType(ty)) |d| {
            named = self.ast.tokenText(self.ast.declName(d));
            owner = self.program.get(self.program.moduleOf(d)).name;
        }
        self.sink.addErrorFmt(.m_opaque, file, span, what, "`{s}` is opaque outside `{s}`", .{ named, owner }) catch {};
    }

    /// Gives the qualifiers of a name a type.
    ///
    /// `a` in `a.f()` and `Account` in `Account.open()` are not values and
    /// nothing reads them, but the tree holds nodes for them and every
    /// expression must have a type -- one without a type is indistinguishable
    /// from one a pass forgot, which is a property the suite checks.
    fn noteQualifier(self: *Checker, id: ExprId) void {
        var root = id;
        while (self.ast.exprTag(root) == .field) root = self.ast.unaryOperand(root);

        const t = self.res.targetOf(root);
        if (t == BindingId.none) return;

        // A type name carries its own type, as it does wherever else one is
        // selected from. A kind that carries no value takes unit, from the one
        // predicate the server also reads -- a kind added to its list here and
        // not there would be hovered as `()`.
        const kind = self.res.kindOf(t);
        const at_root: TypeId = if (resolve_mod.carriesNoValue(kind)) .unit else switch (kind) {
            .declared_type => self.type_of_decl.get(self.res.declaredBy(t)),
            // A primitive carries no declaration to read a type off, because no
            // module declares one -- the binding holds the type itself.
            .builtin_type => self.res.builtinOf(t) orelse return,
            .type_alias => self.aliasPathType(t) orelse return,
            else => return,
        };

        var at = id;
        while (self.ast.exprTag(at) == .field) {
            at = self.ast.unaryOperand(at);
            _ = self.record(at, if (at == root) at_root else .unit);
        }
    }

    fn checkCall(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const marked = self.ast.callMarked(id);
        const result = try self.checkCallTarget(id, expected, marked);
        // A marked postfix call lends its receiver, which the operation's
        // own parameter list answers for; only a marked invocation is asked
        // for a mutable callable here.
        if (marked and result != .poison and self.lentBy(id) == ExprId.none) {
            const at = self.call_of[id.index()];
            if (at == no_call or self.calls.items[at].callee_convention != .inout) {
                // `&` marks the first call after it, so `&make().change()`
                // marks `make()`. A function or an operation reached through
                // its type is no place, so the report names the call it marked.
                if (self.res.marksNoPlace(id))
                    return self.report(.s_mutation, id, "`&` marks this call, and a function holds nothing a call writes to", .{}, "bind its result with `var`, then mark the call that changes it");
                return self.report(.s_mutation, id, "`&` invocation requires a callable value", .{}, "bind the callback before invoking it mutably");
            }
        }
        return result;
    }

    fn checkCallTarget(self: *Checker, id: ExprId, expected: ?Expected, invocation_marked: bool) std.mem.Allocator.Error!TypeId {
        const c = self.ast.call(id);

        // `?` marks a newtype's construction declining, and nothing else --
        // asked here, before the callee is read as a function, a primitive or
        // another declared type, so every kind that is not a newtype meets
        // one refusal rather than one per branch below.
        //
        // A `?` the parser did not read as part of a construction carries as
        // an ordinary `try_` instead of the flag, which is every head that is
        // not a path: `f()?()` and `a[0]?()` arrive in that shape. It is the
        // same mistake, and asking both here is what keeps it one refusal:
        // read as a call whose head is an expression, each fell through every
        // branch below to the fallback, which recorded poison and reported
        // nothing.
        const declines = self.ast.callFallible(id) or self.ast.exprTag(c.callee) == .try_;
        if (declines and resolve_mod.constructionOf(self.ast, self.res, id) == null) {
            for (c.args) |a| try self.checkRecoveredArgument(a);
            return self.report(
                .t_refine,
                id,
                "`?` declines a newtype's construction, and this call constructs none",
                .{},
                "drop the `?`",
            );
        }

        if (namesAVariant(self.ast, self.res, self.ast.withoutGroups(c.callee))) return self.checkConstruct(id, expected);

        // A call whose callee names a primitive converts. There is no second
        // syntax for one, so which calls those are is asked here rather than
        // decided by a node the parser built.
        if (resolve_mod.conversionTo(self.ast, self.res, id)) |to| {
            return self.checkConversion(id, to, expected);
        }

        // A call whose callee names a newtype constructs, in one of the two
        // forms the parser can have built. The same question read the same
        // way, so a struct or an enum named the same way still falls through
        // to the "not callable" report below.
        if (resolve_mod.constructionOf(self.ast, self.res, id)) |decl| {
            return self.checkNewtypeConstruct(id, decl, expected);
        }

        if (self.res.bracketReading(c.callee)) |reading| switch (try self.checkBracketCall(id, reading, expected)) {
            .checked => |result| return result,
            .index => {},
        } else if (try self.valuesBeforeAnOperation(id, expected)) |refused| return refused;

        const target = self.res.targetOf(c.callee);
        if (self.discardedRelease(id, target)) |discard| return self.checkCallOf(id, discard, c.args, .named, expected, &.{});
        if (target != .none and self.res.kindOf(target) == .type_parameter) {
            return self.checkConversion(id, self.namespaceType(target), expected);
        }

        if (target == BindingId.none) {
            if (self.ast.exprTag(c.callee) == .field and self.res.selectsThroughTrait(c.callee))
                return self.checkCallThroughType(id, c.callee, c.args, expected);

            // `x.name(args)` reaches an operation of `x`'s type -- its own or a
            // trait's -- and never a field. Only this pass can say which
            // operation: which the type declares is a question about the
            // value's type, and which traits declare it is a question about
            // what the module can see.
            const postfix = isPostfixCallee(self.ast, self.res, c.callee);
            if (postfix) {
                const field = c.callee;
                const receiver = self.ast.unaryOperand(field);
                const name = self.ast.tokenText(self.ast.exprMain(field));
                // Checked once here; `postfixCall` and the selection below
                // read what this recorded.
                const receiver_type = try self.checkReceiver(id, receiver, self.ast.tokenName(self.ast.exprMain(field)), expected);
                if (std.mem.eql(u8, name, types_mod.array_view_name)) {
                    if (self.builder.view().arrayViewReceiver(receiver_type)) |adjustment|
                        return self.checkArrayView(id, receiver, adjustment, expected, invocation_marked);
                }
                if (std.mem.eql(u8, name, types_mod.array_length_name)) {
                    const adjustment = self.builder.view().observedReceiver(receiver_type);
                    if (self.builder.get(adjustment.receiver) == .array)
                        return self.checkArrayLength(id, receiver, adjustment, expected, invocation_marked);
                }
                if (std.mem.eql(u8, name, "into_captures") and self.builder.get(receiver_type) == .closure)
                    return self.checkClosureRecovery(id, receiver, receiver_type, expected, invocation_marked);
                switch (try self.postfixCall(id, c.callee, c.args, expected)) {
                    .settled => |settled| return self.checkCallOf(id, settled.sig, settled.args, .postfix, expected, &.{}),
                    .absent => {},
                    .refused, .poisoned => {
                        for (c.args) |a| try self.checkRecoveredArgument(a);
                        return self.record(id, .poison);
                    },
                }
            }
            const outer = self.callee;
            const outer_arguments = self.callee_arguments;
            self.callee = if (postfix) c.callee else ExprId.none;
            self.callee_arguments = c.args.len;
            defer {
                self.callee = outer;
                self.callee_arguments = outer_arguments;
            }
            const callee_type = try self.check(c.callee, null);
            switch (self.builder.get(callee_type)) {
                .closure => |closure| return self.checkClosureCall(id, closure, expected, invocation_marked),
                .callable => return self.checkCallableValueCall(id, .{ .indirect = c.callee }, callee_type, expected, invocation_marked),
                else => {},
            }
            if (try self.erasedCallSignature(callee_type)) |signature|
                return self.checkCallableValueCall(id, .{ .erased = c.callee }, signature, expected, invocation_marked);
            const callable_bounds = self.builder.callableBoundsOn(callee_type);
            if (callable_bounds.len == 1) {
                return self.checkCallableValueCall(id, .{ .generic_callable = callee_type }, callable_bounds[0], expected, invocation_marked);
            }
            if (callable_bounds.len == 0) {
                if (self.contextual_constraints.singleCallable(self.generic, callee_type)) |signature| {
                    return self.checkCallableValueCall(id, .{ .generic_callable = callee_type }, signature, expected, invocation_marked);
                }
            }
            for (c.args) |a| try self.checkRecoveredArgument(a);

            // A name or path that reaches nothing was already reported by
            // whichever pass looked for it, and checked to poison. An
            // expression that did check has a value but no callable signature,
            // which is the mistake to name. That includes a field selected in
            // parentheses, `(b.f)()`, whose value is what the call reaches.
            if (callee_type != .poison) {
                return self.report(
                    .n_not_callable,
                    c.callee,
                    "this expression has type `{s}`, which carries no callable signature",
                    .{(try self.typeName(callee_type))},
                    if (self.ast.exprTag(self.ast.withoutGroups(c.callee)) == .field)
                        "this field holds no callable value"
                    else
                        "call a function or callable value",
                );
            }
            return self.record(id, .poison);
        }

        // Asserted below rather than assumed: the kind is what makes
        // `declaredBy` meaningful, and a wrong kind here would produce a valid
        // handle into the wrong declaration.
        const kind = self.res.kindOf(target);
        if (kind != .function) {
            if (notAValue(kind) == null) {
                const callee_type = try self.check(c.callee, null);
                switch (self.builder.get(callee_type)) {
                    .closure => |closure| return self.checkClosureCall(id, closure, expected, invocation_marked),
                    .callable => return self.checkCallableValueCall(id, .{ .indirect = c.callee }, callee_type, expected, invocation_marked),
                    else => {},
                }
                if (try self.erasedCallSignature(callee_type)) |signature|
                    return self.checkCallableValueCall(id, .{ .erased = c.callee }, signature, expected, invocation_marked);
                const callable_bounds = self.builder.callableBoundsOn(callee_type);
                if (callable_bounds.len == 1) {
                    return self.checkCallableValueCall(id, .{ .generic_callable = callee_type }, callable_bounds[0], expected, invocation_marked);
                }
                if (callable_bounds.len == 0) {
                    if (self.contextual_constraints.singleCallable(self.generic, callee_type)) |signature| {
                        return self.checkCallableValueCall(id, .{ .generic_callable = callee_type }, signature, expected, invocation_marked);
                    }
                }
                if (callee_type == .poison) {
                    for (c.args) |a| try self.checkRecoveredArgument(a);
                    return self.record(id, .poison);
                }
            } else {
                _ = self.record(c.callee, .unit);
                self.noteQualifier(c.callee);
            }
            for (c.args) |a| try self.checkRecoveredArgument(a);
            // A conversion is a call, so a programmer meets this where a parse
            // error used to stand. What the name *is* is what tells them which
            // of the parentheses and the name to change.
            const what: []const u8 = switch (kind) {
                // An alias reaching here names no primitive and no newtype,
                // which is what a call on it would have converted or built.
                .declared_type, .type_alias => "names a type, and only a primitive converts",
                .trait => "names a trait, and an operation is reached through it",
                .module => "names a module",
                .constant => "names a constant, which is a value and is read rather than called",
                else => "does not refer to a function",
            };
            return self.report(
                .n_not_callable,
                c.callee,
                "this name {s}",
                .{what},
                "only a function can be called",
            );
        }

        if (self.res.declaredBy(target) == self.raw_accesses.place or self.res.declaredBy(target) == self.raw_accesses.slice_place) {
            const body = if (self.generic != .none) self.ast.declBody(self.generic) else ExprId.none;
            const permitted = self.generic != .none and self.ast.declTag(self.generic) == .projection and
                body != .none and self.ast.exprTag(body) == .block and self.ast.withoutGroups(self.ast.blockOf(body).tail) == id;
            if (!permitted) return self.report(.t_projection, id, "a storage place is only formed by a projection", .{}, "name the element through indexing");
        }
        return self.checkCallOf(id, self.res.declaredBy(target), c.args, .named, expected, &.{});
    }

    const BracketCall = union(enum) {
        /// The call was checked with the brackets as type arguments, or
        /// refused.
        checked: TypeId,
        /// The bracket indexes its head, and the call is a call of the
        /// element.
        index,
    };

    /// A call whose callee is written with brackets that also read as types.
    ///
    /// Which reading applies is decided here and nowhere else. A head naming a
    /// function, as the resolver recorded, takes the brackets as type
    /// arguments, and so does a name selected from a value that `postfixCall`
    /// finds to be an operation of the value's type. A name that is a field,
    /// like every other head, is indexed.
    fn checkBracketCall(self: *Checker, id: ExprId, reading: resolve_mod.Resolution.BracketReading, expected: ?Expected) std.mem.Allocator.Error!BracketCall {
        const c = self.ast.call(id);
        const bracket = c.callee;
        const head = self.ast.binary(bracket).lhs;
        switch (reading) {
            .type_arguments => {
                if (self.res.selectsThroughTrait(head)) {
                    const through = try self.operationThroughType(head, expected, true) orelse {
                        for (c.args) |a| try self.checkRecoveredArgument(a);
                        self.recordTypeWrittenAsIndex(self.ast.binary(bracket).rhs);
                        _ = self.record(bracket, .poison);
                        return .{ .checked = self.record(id, .poison) };
                    };
                    _ = self.record(head, .unit);
                    const written = (try self.writtenTypeArguments(bracket, through.sig)) orelse {
                        for (c.args) |a| try self.checkRecoveredArgument(a);
                        return .{ .checked = self.record(id, .poison) };
                    };
                    return .{ .checked = try self.checkCallOf(id, through.sig, c.args, through.form(), expected, written) };
                }
                const d = self.res.declaredBy(self.res.targetOf(head));
                const written = (try self.writtenTypeArguments(bracket, d)) orelse {
                    for (c.args) |a| try self.checkRecoveredArgument(a);
                    return .{ .checked = self.record(id, .poison) };
                };
                return .{ .checked = try self.checkCallOf(id, d, c.args, .named, expected, written) };
            },
            .member => |deferred| switch (try self.postfixCall(id, head, c.args, expected)) {
                .settled => |settled| {
                    for (deferred.type_reports) |deferred_report| try self.sink.add(deferred_report);
                    const written = (try self.writtenTypeArguments(bracket, settled.sig)) orelse {
                        for (c.args) |a| try self.checkRecoveredArgument(a);
                        return .{ .checked = self.record(id, .poison) };
                    };
                    return .{ .checked = try self.checkCallOf(id, settled.sig, settled.args, .postfix, expected, written) };
                },
                .absent => {
                    // A name that is neither an operation nor a field of the
                    // receiver's type is refused as the postfix call it is
                    // written as, which says what the type lacks.
                    const receiver = self.builder.exprType(self.ast.withoutGroups(self.ast.unaryOperand(head)));
                    const name = self.ast.tokenText(self.ast.exprMain(head));
                    if (self.builder.lookupField(self.builder.view().observedReceiver(receiver).receiver, name) == null) {
                        for (deferred.type_reports) |deferred_report| try self.sink.add(deferred_report);
                        const outer = self.callee;
                        const outer_arguments = self.callee_arguments;
                        self.callee = head;
                        self.callee_arguments = c.args.len;
                        defer {
                            self.callee = outer;
                            self.callee_arguments = outer_arguments;
                        }
                        _ = try self.check(head, null);
                        for (c.args) |a| try self.checkRecoveredArgument(a);
                        return .{ .checked = self.record(id, .poison) };
                    }
                    for (deferred.index_reports) |deferred_report| try self.sink.add(deferred_report);
                },
                // Two traits declare the name, so it is an operation and the
                // brackets were read as types. A receiver already reported
                // leaves nothing to say about the brackets.
                .refused, .poisoned => {
                    if (self.builder.exprType(self.ast.withoutGroups(self.ast.unaryOperand(head))) != .poison)
                        for (deferred.type_reports) |deferred_report| try self.sink.add(deferred_report);
                    self.recordTypeWrittenAsIndex(self.ast.binary(bracket).rhs);
                    _ = self.record(bracket, .poison);
                    for (c.args) |a| try self.checkRecoveredArgument(a);
                    return .{ .checked = self.record(id, .poison) };
                },
            },
            .unresolved => {
                _ = try self.check(head, null);
                self.recordTypeWrittenAsIndex(self.ast.binary(bracket).rhs);
                _ = self.record(bracket, .poison);
                for (c.args) |a| try self.checkRecoveredArgument(a);
                return .{ .checked = self.record(id, .poison) };
            },
            .index => {},
        }
        // Contents that read only as types form no index, and only a generic
        // function's or method's call takes types.
        if (self.ast.exprTag(self.ast.binary(bracket).rhs) == .err) {
            for (c.args) |a| try self.checkRecoveredArgument(a);
            return .{ .checked = self.report(
                .t_index,
                bracket,
                "this bracket holds types, and only a generic function's or method's call takes them",
                .{},
                "an index is one value",
            ) };
        }
        return .index;
    }

    /// Refuses brackets holding a value before the call of an operation,
    /// `"7".parse[3]()`, or null where the call is anything else.
    ///
    /// Such brackets have no type reading, so the resolver recorded no
    /// reading for them, and a selection they follow is decided here by the
    /// lookup every postfix call uses: an operation's brackets hold types, and
    /// a field is indexed as before.
    fn valuesBeforeAnOperation(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!?TypeId {
        const c = self.ast.call(id);
        if (self.ast.exprTag(c.callee) != .index) return null;
        const head = self.ast.binary(c.callee).lhs;
        if (!isPostfixCallee(self.ast, self.res, head)) return null;
        switch (try self.postfixCall(id, head, c.args, expected)) {
            .absent => return null,
            .settled => {
                const index = self.ast.binary(c.callee).rhs;
                _ = self.record(head, .unit);
                try self.checkRecoveredArgument(index);
                _ = self.report(.n_not_a_type, index, "the brackets before `{s}`'s call hold its type arguments, and this is a value", .{self.ast.tokenText(self.ast.exprMain(head))}, "the brackets before a call hold types");
            },
            .refused, .poisoned => {},
        }
        _ = self.record(c.callee, .poison);
        for (c.args) |a| try self.checkRecoveredArgument(a);
        return self.record(id, .poison);
    }

    /// Records unit for the index reading of brackets that hold type
    /// arguments. Its nodes are the type's names, which hold no value, and
    /// what the brackets mean is read from the type reading.
    fn recordTypeWrittenAsIndex(self: *Checker, id: ExprId) void {
        if (id == ExprId.none) return;
        _ = self.record(id, .unit);
        switch (self.ast.exprTag(id)) {
            .field, .grouped => self.recordTypeWrittenAsIndex(self.ast.unaryOperand(id)),
            .index => {
                const b = self.ast.binary(id);
                self.recordTypeWrittenAsIndex(b.lhs);
                self.recordTypeWrittenAsIndex(b.rhs);
            },
            else => {},
        }
    }

    /// The type arguments a call's brackets write, checked against the type
    /// parameters its function declares, or null where they were refused.
    fn writtenTypeArguments(self: *Checker, bracket: ExprId, d: node.DeclId) std.mem.Allocator.Error!?[]const TypeId {
        const refs = self.ast.typeArgs(self.ast.bracketTypes(bracket).?);
        const generics = self.ast.declTypeParams(d);
        const head = self.ast.binary(bracket).lhs;
        _ = self.record(head, .unit);
        if (self.res.bracketReading(bracket).? == .type_arguments) self.noteQualifier(head);
        self.recordTypeWrittenAsIndex(self.ast.binary(bracket).rhs);
        const written = try self.sink.arena.alloc(TypeId, refs.len);
        var valid = true;
        for (refs, written) |ref, *ty| {
            ty.* = try self.typeOfRef(ref);
            if (ty.* == .poison) valid = false;
        }
        if (refs.len != generics.len) {
            try self.refuseCallArity(bracket, d, refs.len);
            return null;
        }
        if (!valid) return null;
        return written;
    }

    /// The receiver a checked marked call lends, or `.none`, told by the
    /// call's record whether it reached an operation with its type arguments
    /// written.
    fn lentBy(self: *const Checker, call: ExprId) ExprId {
        const at = self.call_of[call.index()];
        const names_type_arguments = at != no_call and self.calls.items[at].written_type_arguments;
        return lentReceiver(self.ast, self.res, call, names_type_arguments);
    }

    fn checkArrayView(self: *Checker, id: ExprId, receiver: ExprId, adjustment: types_mod.ReceiverAdjustment, expected: ?Expected, invocation_marked: bool) std.mem.Allocator.Error!TypeId {
        const call = self.ast.call(id);
        if (call.args.len != 0) {
            for (call.args) |arg| try self.checkRecoveredArgument(arg);
            return self.report(.t_arity, id, "expected 0 argument(s), found {d}", .{call.args.len}, "an array view takes no arguments");
        }
        if (invocation_marked)
            return self.report(.s_mutation, id, "an array view reads its receiver", .{}, "remove `&` from this call");
        const array = self.builder.get(adjustment.receiver).array;
        const declaration = self.raw_accesses.slice;
        const result_type = try self.builder.instantiate(self.type_of_decl.get(declaration), declaration, &.{array.element});
        const parameters = [_]types_mod.CallableParam{.{ .spelling = "source", .convention = .read, .ty = adjustment.receiver, .default = .absent, .stable_address = true }};
        const contracts = [_]types_mod.CallableContract{.{ .kind = .borrows, .source = .{ .root = .{ .parameter = 0 }, .spelling = "source" } }};
        const signature = try self.builder.internCallable(&parameters, result_type, &contracts, .read);
        const observations = [_]?types_mod.ReceiverAdjustment{adjustment};
        try self.checkStableArguments(&.{receiver}, &parameters, &observations);
        _ = self.record(call.callee, signature);
        const result = try self.expect(id, result_type, expected);
        if (result == .poison or self.call_of[id.index()] != no_call) return result;
        const index: u32 = @intCast(self.calls.items.len);
        const args = try self.gpa.dupe(ExprId, &.{receiver});
        errdefer self.gpa.free(args);
        const adjustments = try self.gpa.dupe(?types_mod.ReceiverAdjustment, &observations);
        errdefer self.gpa.free(adjustments);
        try self.calls.append(self.gpa, .{
            .at = id,
            .target = .array_view,
            .signature = signature,
            .args = args,
            .receiver_adjustments = adjustments,
        });
        self.call_of[id.index()] = index;
        return result;
    }

    /// `a.length()` on an array reads the count its type holds. The receiver
    /// is read in place rather than consumed, and the result borrows nothing.
    fn checkArrayLength(self: *Checker, id: ExprId, receiver: ExprId, adjustment: types_mod.ReceiverAdjustment, expected: ?Expected, invocation_marked: bool) std.mem.Allocator.Error!TypeId {
        const call = self.ast.call(id);
        if (call.args.len != 0) {
            for (call.args) |arg| try self.checkRecoveredArgument(arg);
            return self.report(.t_arity, id, "expected 0 argument(s), found {d}", .{call.args.len}, "an array's length takes no arguments");
        }
        if (invocation_marked)
            return self.report(.s_mutation, id, "an array's length reads its receiver", .{}, "remove `&` from this call");
        const parameters = [_]types_mod.CallableParam{.{ .spelling = "self", .convention = .read, .ty = adjustment.receiver, .default = .absent }};
        const signature = try self.builder.internCallable(&parameters, .u64, &.{}, .read);
        _ = self.record(call.callee, signature);
        const result = try self.expect(id, .u64, expected);
        if (result == .poison or self.call_of[id.index()] != no_call) return result;
        const index: u32 = @intCast(self.calls.items.len);
        const args = try self.gpa.dupe(ExprId, &.{receiver});
        errdefer self.gpa.free(args);
        const adjustments = try self.gpa.dupe(?types_mod.ReceiverAdjustment, &.{adjustment});
        errdefer self.gpa.free(adjustments);
        try self.calls.append(self.gpa, .{
            .at = id,
            .target = .array_length,
            .signature = signature,
            .args = args,
            .receiver_adjustments = adjustments,
        });
        self.call_of[id.index()] = index;
        return result;
    }

    fn checkClosureRecovery(self: *Checker, id: ExprId, receiver: ExprId, receiver_type: TypeId, expected: ?Expected, invocation_marked: bool) std.mem.Allocator.Error!TypeId {
        const call = self.ast.call(id);
        if (call.args.len != 0) {
            for (call.args) |arg| try self.checkRecoveredArgument(arg);
            return self.report(.t_arity, id, "expected 0 argument(s), found {d}", .{call.args.len}, "capture recovery takes no arguments");
        }
        if (invocation_marked)
            return self.report(.s_mutation, id, "capture recovery consumes its receiver", .{}, "remove `&` from this call");
        const result_type = try self.builder.captureRecord(self.builder.get(receiver_type).closure);
        const signature = try self.builder.internCallable(&.{.{ .spelling = "self", .convention = .sink, .ty = receiver_type, .default = .absent }}, result_type, &.{}, .read);
        _ = self.record(call.callee, signature);
        const result = try self.expect(id, result_type, expected);
        if (result == .poison or self.call_of[id.index()] != no_call) return result;
        const index: u32 = @intCast(self.calls.items.len);
        try self.calls.append(self.gpa, .{ .at = id, .target = .closure_recovery, .signature = signature, .args = try self.gpa.dupe(ExprId, &.{receiver}) });
        self.call_of[id.index()] = index;
        return result;
    }

    fn checkLambda(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const lambda = self.ast.lambda(id);
        const closure = self.res.closures.closureOf(id);
        std.debug.assert(closure != .none);

        const unavailable_context = if (expected) |want| want.callable_context and want.ty == .poison else false;
        var refused = unavailable_context;
        const resolved_captures = self.res.closureCaptures(closure);
        const environment_fields = try self.gpa.alloc(types_mod.Field, resolved_captures.len);
        defer self.gpa.free(environment_fields);
        for (lambda.captures, resolved_captures, environment_fields) |capture, resolved, *field| {
            try self.field_name_spellings.put(self.gpa, self.ast.tokenName(capture.name), self.ast.tokenText(capture.name));
            const source_type = try self.check(capture.source, null);
            self.setBindingType(resolved.binding, source_type);
            if (self.calleeLabels(capture.source)) |params| try self.binding_labels.put(self.gpa, resolved.binding, self.ast.paramRangeOf(params));
            // A read or `inout` capture stores an observation of its source;
            // a sink capture stores the value itself.
            field.* = .{ .name = self.ast.tokenText(capture.name), .ty = if (capture.convention == .sink) source_type else try self.builder.borrowOf(source_type) };
            if (capture.convention != .sink and source_type != .poison and !self.isAPlace(capture.source)) {
                _ = self.report(.t_lend, capture.source, "{s} capture requires a place", .{if (capture.convention == .read) "a read" else "an `inout`"}, "bind the value before capturing it");
                refused = true;
            } else if (capture.convention == .inout) {
                // Only a closure called `inout` or `sink` has the exclusive
                // access to its environment that writing through a lend needs;
                // a closure called for reading may be called through several
                // observations of it at once.
                if (lambda.invocation == .read) {
                    _ = self.report(.o_capture, capture.source, "an `inout` capture needs a closure called `inout` or `sink`", .{}, "write `inout` before the capture list, so each call may change what the capture lends");
                    refused = true;
                }
                if (source_type != .poison) try self.written.append(self.gpa, .{ .at = capture.source, .refused = "this place cannot be lent `inout`" });
            }
            refused = refused or source_type == .poison;
        }
        const free = self.res.freeReferenceOf(closure);
        if (free != .none) refused = true;

        const contextual: ?types_mod.CallableSignature = if (expected) |want| switch (self.builder.get(want.ty)) {
            .callable => |signature| signature,
            else => null,
        } else null;
        if (contextual) |wanted| {
            const compatible = if (expected.?.callable_context)
                types_mod.invocationCompatible(lambda.invocation, wanted.invocation)
            else
                lambda.invocation == wanted.invocation;
            if (!compatible) {
                const callee = expected.?.callee;
                if (wanted.invocation == .read and lambda.invocation == .inout and callee != .none) {
                    const name = self.ast.tokenText(self.ast.declName(callee));
                    _ = self.report(.t_call, id, "this closure is declared `inout`, and `{s}` calls it for reading", .{name}, try std.fmt.allocPrint(self.sink.arena, "`{s}` calls its callback for reading, so the callback cannot change its captures; pass the closure to a function whose callback is an `inout fn`, or keep what changes in a value `{s}` lends it", .{ name, name }));
                } else if (wanted.invocation == .read and lambda.invocation == .inout) {
                    _ = self.report(.t_call, id, "this closure is declared `inout`, and it is called for reading", .{}, "the type it is given calls it for reading, so it cannot change its captures; give it an `inout fn` type, and call it with `&`");
                } else {
                    _ = self.report(.t_call, id, "this closure is declared {s}, and it is called {s}", .{ invocationSpelling(lambda.invocation, .declared), invocationSpelling(wanted.invocation, .called) }, "declare it the way it is called");
                }
                refused = true;
            }
        }
        if (contextual != null and resolved_captures.len != 0 and !expected.?.callable_context) {
            _ = self.report(.o_capture, id, "a capturing closure cannot become a function pointer", .{}, "keep its environment with `mem.Closure.open(closure)`, or take a generic callable parameter");
            refused = true;
        }
        const expected_params = try self.gpa.dupe(types_mod.CallableParam, if (contextual) |signature|
            self.builder.callableParams(signature)
        else
            &.{});
        defer self.gpa.free(expected_params);

        if (contextual != null and expected_params.len != lambda.params.len) {
            _ = self.report(
                .t_call,
                id,
                "this lambda declares {d} parameter{s}, but the expected callable declares {d}",
                .{ lambda.params.len, if (lambda.params.len == 1) "" else "s", expected_params.len },
                "make the lambda's parameter list match the expected callable",
            );
            refused = true;
        }

        const bindings = self.res.closureParameters(closure);

        var signature_params = try self.gpa.alloc(types_mod.CallableParam, lambda.params.len);
        defer self.gpa.free(signature_params);
        for (lambda.params, 0..) |param, i| {
            const flowed = if (i < expected_params.len) expected_params[i].ty else TypeId.poison;
            const ty = if (param.written.wasWritten())
                try self.typeOfRef(param.written)
            else if (flowed != .poison)
                flowed
            else if (unavailable_context or (param.pattern != ExprId.none and self.refusedByParser(param.pattern)))
                TypeId.poison
            else blk: {
                _ = self.report(
                    .t_infer,
                    id,
                    "the type of parameter `{s}` cannot be inferred without an expected callable type",
                    .{self.ast.paramSpelling(param)},
                    "write the parameter type",
                );
                refused = true;
                break :blk TypeId.poison;
            };

            if (i < bindings.len) self.setBindingType(bindings[i], ty);
            if (param.pattern != ExprId.none) try self.checkParameterPattern(param, ty);
            var default: types_mod.CallableDefault = .absent;
            if (param.default != .none) {
                try self.checkCallableDefault(.{
                    .module = self.current,
                    .owner = self.generic,
                    .expr = param.default,
                    .parameter = param.name,
                    .convention = param.convention,
                    .ty = ty,
                });
                if ((try self.worth(param.default)).checked()) |value|
                    default = .{ .value = value }
                else
                    refused = true;
            }

            if (i < expected_params.len) {
                if (try self.reportLambdaParameterMismatch(param, ty, default, expected_params[i], i + 1)) refused = true;
            }
            signature_params[i] = .{
                .spelling = self.ast.paramSpelling(param),
                .convention = param.convention,
                .ty = ty,
                .default = default,
            };
        }

        const written_result = if (lambda.result.wasWritten()) try self.typeOfRef(lambda.result) else null;
        const result_expected: ?Expected = if (written_result) |result| .{
            .ty = result,
            .at = self.locOfWritten(lambda.result),
            .reason = .return_type,
            .alias = self.aliasHeading(self.generic, lambda.result),
        } else if (contextual != null) .{
            .ty = contextual.?.result,
            .at = expected.?.at,
            .reason = expected.?.reason,
            .inference = if (expected.?.infer_lambda_result) expected.?.inference else null,
        } else null;
        const written_before_body = self.written.items.len;
        const body_result = checked: {
            const previous_return = self.current_return;
            const previous_failure = self.failure_expected;
            self.current_return = result_expected;
            self.failure_expected = null;
            defer self.current_return = previous_return;
            defer self.failure_expected = previous_failure;
            // A closure's body is a function of its own: a `break` or
            // `continue` in it has no loop to leave, and its `return` and `?`
            // leave the closure rather than the loops around it.
            const enclosing_loops = self.loops;
            const hid_loops = self.closure_hides_loops;
            self.closure_hides_loops = hid_loops or enclosing_loops.items.len > 0;
            self.loops = .empty;
            defer {
                self.loops.deinit(self.gpa);
                self.loops = enclosing_loops;
                self.closure_hides_loops = hid_loops;
            }
            break :checked try self.check(lambda.body, result_expected);
        };
        // Reported once the body is checked, because the capture it suggests
        // depends on what the body's calls do with the name.
        // Whether the body changes the name it did not capture, read from
        // the places the checker recorded as written; ownership reports the
        // refusal, since what the body takes is decided by position there.
        const uncaptured_changed = free != .none and self.writesBinding(self.res.targetOf(free), self.written.items[written_before_body..]);
        const result = if (body_result == .never and result_expected != null) result_expected.?.ty else body_result;
        if (written_result != null and contextual != null) {
            if (try self.expect(id, result, .{
                .ty = contextual.?.result,
                .at = expected.?.at,
                .reason = expected.?.reason,
                .inference = if (expected.?.infer_lambda_result) expected.?.inference else null,
            }) == .poison) refused = true;
        }
        self.closure_descriptors[closure.index()].invocation = lambda.invocation;
        // An omitted clause inherits the contextual parameter contract. Authored
        // clauses describe the actual closure and must fit that promise unchanged.
        var outcome: ContractOutcome = .{};
        const authored_contracts = if (contextual != null and lambda.contracts.start == lambda.contracts.end)
            null
        else
            try self.normalizeContracts(signature_params, lambda.params, result, self.ast.contracts[lambda.contracts.start..lambda.contracts.end], self.ast.exprMain(id), closure, &outcome);
        defer if (authored_contracts) |contracts| types_mod.freeContracts(self.gpa, contracts);
        var inherited_contracts: std.ArrayList(types_mod.CallableContract) = .empty;
        defer inherited_contracts.deinit(self.gpa);
        if (authored_contracts == null) {
            for (contextual.?.contracts) |contract| {
                if (contract.source.root != .callee) {
                    try inherited_contracts.append(self.gpa, contract);
                    continue;
                }
                std.debug.assert(contract.kind == .carries and contract.destination == null and contract.source.fields.len == 0);
                if (!try self.builder.mayCarryDependencies(result)) continue;
                for (resolved_captures, 0..) |capture, index| {
                    // A result never depends on a place lent `inout`: the
                    // next call may change it.
                    if (capture.convention == .inout) continue;
                    if (capture.convention == .sink and !try self.builder.mayCarryDependencies(self.binding_types.get(capture.binding))) continue;
                    const name = self.res.captureNameToken(capture.binding);
                    var concrete = contract;
                    concrete.kind = if (capture.convention == .read) .borrows else .carries;
                    concrete.source = .{ .root = .{ .capture = .{ .closure = closure, .field = @enumFromInt(index) } }, .spelling = self.ast.tokenText(name) };
                    try inherited_contracts.append(self.gpa, concrete);
                }
            }
        }
        const contracts = authored_contracts orelse inherited_contracts.items;
        if (contextual != null and signature_params.len == expected_params.len) for (signature_params, expected_params) |*param, expected_param| {
            param.stable_address = param.stable_address or expected_param.stable_address;
        };
        const signature = try self.builder.internCallable(signature_params, result, contracts, lambda.invocation);
        if (contextual) |wanted| {
            if (!types_mod.contractsWithin(self.builder.get(signature).callable.contracts, wanted.contracts)) {
                _ = self.report(.t_borrow_contract, id, "this closure's effects exceed the callable requirement", .{}, "declare the effects on the callable requirement or remove them from the closure");
                refused = true;
            }
        }
        const enclosing_args: []const TypeId = if (self.generic == .none)
            &.{}
        else
            self.param_types[self.generic.index()];
        // The closure's type holds what its enclosing body is instantiated
        // over, so substituting it wherever that body is instantiated reaches
        // its captures: an implementation's parameters and receiver, or a
        // provided operation's trait parameters and symbolic `Self`. The
        // symbolic `Self` is asked of the declaration rather than read from
        // `self_at_call`, which inside a call's argument holds that call's
        // `Self`.
        const typing = self.view();
        const parameters = bodyParametersOf(self.ast, self.res, &typing, self.generic);
        const implementation_args: []const TypeId = if (parameters.owner != .none) self.param_types[parameters.owner.index()] else &.{};
        const receiver = if (parameters.provided)
            try self.signatureSelfType(self.generic)
        else if (self.enclosingRow(self.generic)) |implementation| implementation.ty else TypeId.poison;
        var environment = self.closure_descriptors[closure.index()].environment;
        if (resolved_captures.len != 0 and environment == .unit) {
            const name = try std.fmt.allocPrint(self.gpa, "captures.{d}", .{closure.index()});
            self.builder.owned_names.append(self.gpa, name) catch |err| {
                self.gpa.free(name);
                return err;
            };
            // Copying a closure would duplicate an `inout` capture's
            // exclusive lend, so an environment holding one is affine.
            const lends = for (resolved_captures) |capture| {
                if (capture.convention == .inout) break true;
            } else false;
            environment = try self.builder.addStruct(name, if (lends) .affine else .copyable, environment_fields);
        }
        self.closure_descriptors[closure.index()] = .{
            .owned_fields = self.closure_descriptors[closure.index()].owned_fields,
            .environment = environment,
            .invocation = lambda.invocation,
            .enclosing = self.generic,
            .parameters = parameters,
            .expr = id,
            .body = lambda.body,
            .signature = signature,
            .contract_declined = outcome.declined,
            .default_carrier = outcome.carrier,
            .uncaptured_changed = uncaptured_changed,
        };
        const closure_type = try self.builder.internClosure(closure, enclosing_args, implementation_args, receiver);
        if (refused or result == .poison) return self.record(id, .poison);
        if (expected != null and expected.?.callable_context) return self.record(id, closure_type);
        if (contextual != null) {
            // A body that settled the contextual result's open parameters
            // converts to the signature with those parameters substituted.
            const converted = if (expected.?.infer_lambda_result)
                try self.callableContext(expected.?.ty, expected.?.inference orelse &.{})
            else
                expected.?.ty;
            try self.function_values.append(self.gpa, .{
                .at = id,
                .target = .{ .closure = closure },
                .signature = converted,
                .closure_type = closure_type,
            });
            return self.record(id, converted);
        }
        return self.expect(id, closure_type, expected);
    }

    /// Whether any of `written` -- places the body assigns or lends to be
    /// changed -- is rooted in `binding`.
    fn writesBinding(self: *const Checker, binding: BindingId, written: []const Written) bool {
        if (binding == BindingId.none) return false;
        for (written) |w| {
            if (self.res.pathBinding(self.ast, w.at) == binding) return true;
        }
        return false;
    }

    /// A rejected call still owns its argument markers. Check the value even
    /// when no parameter convention can be established for the argument.
    fn checkRecoveredArgument(self: *Checker, argument: ExprId) std.mem.Allocator.Error!void {
        const marked = self.ast.exprTag(argument) == .marked;
        const value = if (marked) self.ast.unaryOperand(argument) else argument;
        // The call was refused, so no parameter says what a callback's inputs
        // are. That refusal was reported; a lambda is checked with its
        // unwritten parameter types unknown rather than asked for them again.
        const context: ?Expected = if (self.needsCallableContext(value))
            .{ .ty = .poison, .at = self.locOf(value), .reason = .parameter, .callable_context = true }
        else
            null;
        const ty = try self.check(value, context);
        if (marked) _ = self.record(argument, ty);
    }

    fn checkInvocation(self: *Checker, id: ExprId, actual: node.Convention, marked: bool) !bool {
        if (actual == .inout and !marked) {
            _ = self.report(.s_mutation, id, "this callback mutates its environment, so its invocation is marked `&`", .{}, "write `&` before the callback invocation");
            return false;
        }
        if (actual == .sink and marked) {
            _ = self.report(.s_mutation, id, "this callback consumes its environment", .{}, "invoke it without `&`");
            return false;
        }
        if (marked) {
            const call = self.ast.call(id);
            if (!self.isAPlace(call.callee)) {
                _ = self.report(.t_lend, call.callee, "mutable invocation requires a callable place", .{}, "bind the callback before invoking it with `&`");
                return false;
            }
            try self.written.append(self.gpa, .{ .at = call.callee, .refused = "this callback cannot be lent for mutable invocation" });
            for (call.args) |arg| {
                if (self.mentions(arg, call.callee, .none)) {
                    _ = self.report(.n_aliased, arg, "this argument also accesses the callback being invoked mutably", .{}, "keep the callback exclusive during its invocation");
                    return false;
                }
            }
        }
        return true;
    }

    fn checkClosureCall(
        self: *Checker,
        id: ExprId,
        closure_type: types_mod.ClosureType,
        expected: ?Expected,
        invocation_marked: bool,
    ) std.mem.Allocator.Error!TypeId {
        const diagnostics_before = self.sink.error_count;
        const descriptor = &self.closure_descriptors[closure_type.closure.index()];
        const signature_ty = try self.builder.closureSignature(closure_type);
        const signature = self.builder.get(signature_ty).callable;
        const params = self.builder.callableParams(signature);
        const source_params = self.ast.lambda(descriptor.expr).params;
        const call = self.ast.call(id);
        const target: types_mod.CallTarget = .{ .closure = closure_type.closure };
        const matched = (try self.matchArguments(id, .{ .closure = closure_type.closure }, target, call.args)) orelse {
            for (call.args) |arg| try self.checkRecoveredArgument(arg);
            return self.record(id, .poison);
        };
        const args = if (matched.owned)
            @constCast(matched.args)
        else
            try self.gpa.dupe(ExprId, matched.args);
        defer self.gpa.free(args);

        var refused = !try self.checkInvocation(id, descriptor.invocation, invocation_marked);
        var argument_diverges = false;
        for (args, source_params, 0..) |*arg, param, i| {
            if (arg.* == .none) {
                std.debug.assert(param.default != .none);
                std.debug.assert(params[i].default != .absent);
                continue;
            }

            const marked = self.ast.exprTag(arg.*) == .marked;
            const value = if (marked) self.ast.unaryOperand(arg.*) else arg.*;
            if ((params[i].convention == .inout) != marked) {
                if (params[i].convention == .inout) {
                    _ = self.report(.s_mutation, arg.*, "this argument is mutated, so it is marked `&`", .{}, "expected `&` here");
                } else {
                    _ = self.report(.s_mutation, arg.*, "this argument is not mutated, so it takes no `&`", .{}, "unexpected `&`");
                    try self.decideMark(arg.*, .refused);
                }
                refused = true;
            } else if (marked) try self.decideMark(arg.*, .lent);
            const found = try self.check(value, .{
                .ty = params[i].ty,
                .at = .{ .file = self.ast.fileOf(source_params[i].name), .span = self.ast.tokenSpan(source_params[i].name) },
                .reason = .parameter,
            });
            if (marked) {
                _ = self.record(arg.*, found);
            }
            if (found == .poison) refused = true;
            if (found == .never) argument_diverges = true;
        }

        try self.checkStableArguments(args, params, &.{});
        try self.checkExclusivity(args, ExprId.none);

        const result_type = if (argument_diverges)
            TypeId.never
        else
            signature.result;
        const result = try self.expect(id, result_type, expected);
        if (refused or result == .poison or self.sink.error_count != diagnostics_before) {
            try self.retainRecoveredMatched(id, .{ .closure = closure_type.closure }, target, args);
            return result;
        }
        if (self.call_of[id.index()] != no_call) return result;

        const at: u32 = @intCast(self.calls.items.len);
        try self.calls.append(self.gpa, .{
            .at = id,
            .target = .{ .closure = closure_type.closure },
            .callee_convention = if (invocation_marked) .inout else descriptor.invocation,
            .signature = signature_ty,
            .args = try self.gpa.dupe(ExprId, args),
        });
        self.call_of[id.index()] = at;
        return result;
    }

    fn checkCallableValueCall(
        self: *Checker,
        id: ExprId,
        target: types_mod.CallTarget,
        signature_ty: TypeId,
        expected: ?Expected,
        invocation_marked: bool,
    ) std.mem.Allocator.Error!TypeId {
        const diagnostics_before = self.sink.error_count;
        const call = self.ast.call(id);
        const signature = self.builder.get(signature_ty).callable;
        const params = self.builder.callableParams(signature);
        const owner: CallParameters = if (self.calleeLabels(call.callee)) |labels|
            if (labels.len == params.len)
                .{ .labelled = .{ .signature = signature_ty, .params = labels } }
            else
                .{ .signature = signature_ty }
        else
            .{ .signature = signature_ty };
        const matched = (try self.matchArguments(id, owner, target, call.args)) orelse {
            for (call.args) |arg| try self.checkRecoveredArgument(arg);
            return self.record(id, .poison);
        };
        const args = matched.args;
        var args_owned = matched.owned;
        defer if (args_owned) self.gpa.free(args);

        var refused = !try self.checkInvocation(id, signature.invocation, invocation_marked);
        var argument_diverges = false;
        for (args, params) |arg, param| {
            if (arg == .none) continue;
            const marked = self.ast.exprTag(arg) == .marked;
            const value = if (marked) self.ast.unaryOperand(arg) else arg;
            if ((param.convention == .inout) != marked) {
                if (param.convention == .inout) {
                    _ = self.report(.s_mutation, arg, "this argument is mutated, so it is marked `&`", .{}, "expected `&` here");
                } else {
                    _ = self.report(.s_mutation, arg, "this argument is not mutated, so it takes no `&`", .{}, "unexpected `&`");
                    try self.decideMark(arg, .refused);
                }
                refused = true;
            } else if (marked) try self.decideMark(arg, .lent);
            const found = try self.check(value, .{
                .ty = param.ty,
                .at = self.locOf(call.callee),
                .reason = .parameter,
            });
            if (marked) {
                _ = self.record(arg, found);
                try self.written.append(self.gpa, .{ .at = value, .refused = "this place cannot be lent" });
            }
            if (found == .poison) refused = true;
            if (found == .never) argument_diverges = true;
        }
        try self.checkStableArguments(args, params, &.{});
        try self.checkExclusivity(args, ExprId.none);

        // The arguments may have settled open types the result names.
        const result_type = if (argument_diverges)
            TypeId.never
        else
            try self.builder.resolveOpen(signature.result, &self.open_types);
        const result = try self.expect(id, result_type, expected);
        if (refused or result == .poison or self.sink.error_count != diagnostics_before) {
            try self.retainRecoveredMatched(id, owner, target, args);
            return result;
        }
        if (self.call_of[id.index()] != no_call) return result;

        const normalized_args = if (args_owned) take: {
            args_owned = false;
            break :take args;
        } else try self.gpa.dupe(ExprId, args);
        errdefer self.gpa.free(normalized_args);
        const at: u32 = @intCast(self.calls.items.len);
        try self.calls.append(self.gpa, .{
            .at = id,
            .target = target,
            .signature = signature_ty,
            .callee_convention = if (invocation_marked) .inout else signature.invocation,
            .args = normalized_args,
        });
        self.call_of[id.index()] = at;
        return result;
    }

    /// The signature a postfix call reaches, and what it takes.
    ///
    /// The sugar applies where the callee is written `x.name` with a value on
    /// the left, and the type declares an operation of that name or a trait
    /// the module can see declares one with `Self` first. That parameter is
    /// what the value becomes; the rest of the arguments follow it. Fields
    /// play no part: a call reaches an operation, never a field.
    ///
    /// Three answers, because "no trait answers" and "two do" are different
    /// things to have found and the caller has to do different things with
    /// them.
    const Postfixed = union(enum) {
        /// The operation the form reaches, and the arguments with the receiver
        /// in front.
        settled: struct { sig: node.DeclId, args: []const ExprId },
        /// No operation answers, which is not a mistake here: the caller
        /// reports the name as an operation the type does not have, which is
        /// what it is. Holds the receiver's type.
        absent: TypeId,
        /// The receiver did not check, and whatever was wrong with it has
        /// already been said. The caller reaches the same expression again to
        /// report the name, so it would say one mistake twice.
        poisoned,
        /// Two traits answer and the type declares no operation of its own
        /// under the name, and that has been said. Reporting the name as one the
        /// type does not have would contradict it -- the name was found twice,
        /// not zero times -- and send a reader looking for a field.
        refused,
    };

    fn postfixCall(
        self: *Checker,
        id: ExprId,
        field: ExprId,
        given: []const ExprId,
        expected: ?Expected,
    ) std.mem.Allocator.Error!Postfixed {
        return self.postfixOperation(id, field, self.ast.unaryOperand(field), self.ast.tokenName(self.ast.exprMain(field)), .none, given, expected);
    }

    /// `postfixCall` for a receiver and a name, wherever they were written.
    ///
    /// The one place an operation is found for `receiver.wanted(…)`: the
    /// written call `x.release()` reaches it through its `field`, and the
    /// release a `defer let` schedules reaches it with the binding's name
    /// and no field at all, so both are answered by the same lookup.
    /// `at` is what a report about the lookup underlines, and `only`
    /// restricts the answer to one signature, `.none` taking any.
    fn postfixOperation(
        self: *Checker,
        id: ExprId,
        at: ExprId,
        receiver: ExprId,
        wanted: StringId,
        only: DeclId,
        given: []const ExprId,
        expected: ?Expected,
    ) std.mem.Allocator.Error!Postfixed {
        // The receiver decides which implementations are in play, so it is
        // checked before anything is looked for.
        const held = try self.checkReceiver(id, receiver, wanted, expected);
        if (held == .poison) {
            // Whether the call reaches an operation cannot be decided, so a
            // free function its name reaches counts as named rather than as
            // unused on the strength of an error already reported.
            if (self.res.postfixFunction(at)) |named| try self.notePostfixFunctionNamed(named);
            return .poisoned;
        }

        // What the form could reach, which is one enumeration an editor reads
        // the same way, and which of those it does reach, which is one rule
        // an editor reads the same way: `NameReach.reaches`.
        var applicable: std.ArrayList(Applicable) = .empty;
        defer applicable.deinit(self.gpa);

        try self.prepareNamedLookup(held, wanted, false, .operation, null);
        const pool = try self.builder.capabilityView();
        try self.reaching(&pool).named(self.gpa, held, wanted, &applicable);
        if (only != .none) {
            var kept: usize = 0;
            for (applicable.items) |a| {
                if (a.sig != only) continue;
                applicable.items[kept] = a;
                kept += 1;
            }
            applicable.shrinkRetainingCapacity(kept);
        }

        if (applicable.items.len == 0) return .{ .absent = held };
        var name_reach: NameReach = .{};
        for (applicable.items) |a| name_reach.note(a);
        const sig = for (applicable.items) |a| {
            if (name_reach.reaches(a)) break a.sig;
        } else {
            try self.reportAmbiguous(at, held, applicable.items, true);
            return .refused;
        };

        const args = try self.gpa.alloc(ExprId, given.len + 1);
        errdefer self.gpa.free(args);
        args[0] = self.ast.withoutGroups(receiver);
        @memcpy(args[1..], given);
        try self.postfix.append(self.gpa, .{
            .call = @intCast(id.index()),
            .args = args,
        });
        return .{ .settled = .{ .sig = sig, .args = args } };
    }

    /// The type of `receiver` where `receiver.wanted` is written, checked
    /// once.
    ///
    /// A postfix call is tried as several forms -- an array's or a closure's
    /// built-in operation, a declared or trait operation, then the selection
    /// that reports a name the type lacks -- and every one reads its receiver
    /// through here. The first records the type and the rest read it: a
    /// receiver checked again would report its mistakes again and record each
    /// value of an interpolated literal again.
    ///
    /// What the call `id` is expected to produce reaches the receiver through
    /// the operation's result, so a generic call as the receiver can settle
    /// what its arguments left open. A selection that is not called passes
    /// `.none` and expects nothing.
    ///
    /// The parentheses a reader wrote around the receiver are nodes of their
    /// own, and the receiver is checked inside them: the argument a call takes
    /// is the expression the parentheses hold. A group is worth what is inside
    /// it here as everywhere else, so each records the receiver's type.
    fn checkReceiver(self: *Checker, id: ExprId, receiver: ExprId, wanted: StringId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const base = self.ast.withoutGroups(receiver);
        if ((try self.receivers_checked.getOrPut(self.gpa, base)).found_existing) return self.builder.exprType(base);

        const held = blk: {
            const previous = self.method_expected;
            defer self.method_expected = previous;
            const success = if (id == ExprId.none) null else self.successExpectationAt(id);
            self.method_expected = if (id != ExprId.none and (expected != null or success != null))
                .{ .target = base, .name = wanted, .expected = expected, .success = success }
            else
                null;
            break :blk self.record(base, try self.receiverType(try self.check(base, null), self.literalSite(base)));
        };
        var group = receiver;
        while (self.ast.exprTag(group) == .grouped) : (group = self.ast.unaryOperand(group)) {
            _ = self.record(group, held);
        }
        return held;
    }

    /// One key for a declaration and a name, so one table serves the program.
    fn slotKey(decl: u32, name: StringId) u64 {
        return (@as(u64, decl) << 32) | @intFromEnum(name);
    }

    const CallParameters = union(enum) {
        declaration: node.DeclId,
        closure: resolve_mod.ClosureId,
        /// A structural signature with no parameter names of its own: a
        /// call through it passes its arguments by position.
        signature: TypeId,
        /// A structural signature called through a value declared with
        /// parameter names: those of the type written there, or of the
        /// function or lambda the value was bound to.
        labelled: Labelled,

        const Labelled = struct { signature: TypeId, params: []const node.Param };

        fn signatureOf(owner: CallParameters) ?TypeId {
            return switch (owner) {
                .signature => |signature| signature,
                .labelled => |labelled| labelled.signature,
                .declaration, .closure => null,
            };
        }

        fn invocation(owner: CallParameters, self: *const Checker) node.Convention {
            return switch (owner) {
                .declaration => .read,
                .closure => |closure| self.closure_descriptors[closure.index()].invocation,
                .signature, .labelled => self.builder.get(owner.signatureOf().?).callable.invocation,
            };
        }

        fn sourceParams(owner: CallParameters, self: *const Checker) ?[]const node.Param {
            return switch (owner) {
                .declaration => |decl| self.ast.declParams(decl),
                .closure => |closure| self.ast.lambda(self.res.closures.exprOf(closure)).params,
                .signature, .labelled => null,
            };
        }

        /// The parameters a named argument is matched against.
        fn labels(owner: CallParameters, self: *const Checker) ?[]const node.Param {
            return switch (owner) {
                .labelled => |labelled| labelled.params,
                else => owner.sourceParams(self),
            };
        }

        fn signatureParams(owner: CallParameters, self: *const Checker) []const types_mod.CallableParam {
            return self.builder.callableParams(self.builder.get(owner.signatureOf().?).callable);
        }

        fn len(owner: CallParameters, self: *const Checker) usize {
            if (owner.sourceParams(self)) |params| return params.len;
            return owner.signatureParams(self).len;
        }

        fn paramName(owner: CallParameters, self: *const Checker, at: usize) StringId {
            if (owner.labels(self)) |params| return self.ast.tokenName(params[at].name);
            return .none;
        }

        fn paramSpelling(owner: CallParameters, self: *const Checker, at: usize) []const u8 {
            if (owner.labels(self)) |params| return self.ast.paramSpelling(params[at]);
            return "_";
        }

        fn paramToken(owner: CallParameters, self: *const Checker, at: usize) ?TokenId {
            if (owner.labels(self)) |params| return params[at].name;
            return null;
        }

        fn paramConvention(owner: CallParameters, self: *const Checker, at: usize) node.Convention {
            if (owner.sourceParams(self)) |params| return params[at].convention;
            return owner.signatureParams(self)[at].convention;
        }

        fn directTarget(owner: CallParameters) node.DeclId {
            return switch (owner) {
                .declaration => |decl| decl,
                .closure, .signature, .labelled => .none,
            };
        }

        fn hasDefaultAt(owner: CallParameters, self: *const Checker, at: usize) bool {
            if (owner.sourceParams(self)) |params| return hasDefault(params[at]);
            return owner.signatureParams(self)[at].default != .absent;
        }

        /// Keys the name-to-slot table a named argument is looked up in. A
        /// labelled signature has none: its labels are a written parameter
        /// list, searched where a call names one.
        fn key(owner: CallParameters, self: *const Checker) u32 {
            return switch (owner) {
                .declaration => |decl| @intCast(decl.index()),
                .closure => |closure| @intCast(self.ast.declCount() + closure.index()),
                .signature => |signature| @intCast(self.ast.declCount() + self.res.closures.count() + @intFromEnum(signature)),
                .labelled => unreachable,
            };
        }

        fn name(owner: CallParameters, self: *const Checker) []const u8 {
            return switch (owner) {
                .declaration => |decl| self.ast.tokenText(self.ast.declName(decl)),
                .closure => "this lambda",
                // A signature is written the same way from every module.
                .signature => |signature| self.builder.nameOf(signature),
                // A signature described through a value is spelled with the
                // labels its calls use.
                .labelled => |labelled| spelled: {
                    const names = self.sink.arena.alloc([]const u8, labelled.params.len) catch break :spelled self.builder.nameOf(labelled.signature);
                    for (labelled.params, names) |param, *spelled| spelled.* = self.ast.paramSpelling(param);
                    break :spelled self.builder.view().spellCallable(self.sink.arena, labelled.signature, names) catch self.builder.nameOf(labelled.signature);
                },
            };
        }

        fn origin(owner: CallParameters, self: *const Checker) ?Label {
            return switch (owner) {
                .declaration => |decl| .{
                    .file = self.ast.fileOfDecl(decl),
                    .span = self.ast.declNameSpan(decl),
                    .message = "declared here",
                    .style = .secondary,
                },
                .closure => |closure| blk: {
                    const expr = self.res.closures.exprOf(closure);
                    break :blk .{
                        .file = self.ast.fileOfExpr(expr),
                        .span = self.ast.exprSpan(expr),
                        .message = "declared here",
                        .style = .secondary,
                    };
                },
                .signature, .labelled => null,
            };
        }
    };

    /// Which parameter a callable body gives a name to, or null where it
    /// declares none by that name.
    ///
    /// The declaration's whole name-to-index table is laid in on the first ask
    /// about it -- one entry per parameter, written once however many calls
    /// name into it -- so a named argument costs one lookup rather than a walk
    /// of the parameter list, and a call costs its own argument count. The
    /// table is therefore sized by the parameters of the declarations calls
    /// actually name, never by the program.
    fn paramSlot(
        self: *Checker,
        owner: CallParameters,
        name: StringId,
    ) std.mem.Allocator.Error!?u32 {
        if (owner == .labelled) {
            for (owner.labelled.params, 0..) |param, j| {
                if (self.ast.tokenName(param.name) == name) return @intCast(j);
            }
            return null;
        }
        const key = owner.key(self);
        if (!self.param_slots_built.contains(key)) {
            for (0..owner.len(self)) |j| {
                // A parameter is named by whatever token stood where its name
                // belonged, so a malformed one carries the token it was
                // written with rather than nothing at all. Every report below
                // spells a parameter by this token, and the frontend never
                // fails, so this holds over a tree parsed from anything.
                // The first parameter of a name wins, which is the one a
                // reader of the signature reaches first.
                const gop = try self.param_slots.getOrPut(self.gpa, slotKey(key, owner.paramName(self, j)));
                if (!gop.found_existing) gop.value_ptr.* = @intCast(j);
            }
            try self.param_slots_built.put(self.gpa, key, {});
        }
        return self.param_slots.get(slotKey(key, name));
    }

    /// Reports at a written token, with whatever settles the question beside it.
    ///
    /// A name occupies tokens the argument's own span does not cover, so
    /// pointing at the expression would point past the mistake being reported.
    fn reportAtToken(
        self: *Checker,
        code: Code,
        at: TokenId,
        message: []const u8,
        primary: []const u8,
        origin: ?Label,
    ) void {
        const here: Label = .{
            .file = self.ast.fileOf(at),
            .span = self.ast.tokenSpan(at),
            .message = primary,
            .style = .primary,
        };
        const labels = self.gpa.alloc(Label, if (origin == null) 1 else 2) catch return;
        labels[0] = here;
        if (origin) |o| labels[1] = o;
        self.sink.add(.{
            .severity = .err,
            .code = code,
            .message = message,
            .labels = labels,
        }) catch {};
    }

    /// A name written where nothing declares parameters: a conversion, or a
    /// variant being built.
    ///
    /// Both are spelled like a call and neither reaches a signature, so the
    /// matcher never sees them and the name has to be refused here. `what` is
    /// what the call named, which is the only thing a reader could have
    /// believed declared the parameter.
    fn refuseNames(
        self: *Checker,
        id: ExprId,
        what: []const u8,
    ) std.mem.Allocator.Error!void {
        for (self.ast.callNames(id)) |name| {
            if (name == TokenId.none) continue;
            self.reportAtToken(
                .t_unknown_parameter,
                name,
                try std.fmt.allocPrint(self.gpa, "`{s}` declares no parameter `{s}`", .{
                    what,
                    self.ast.tokenText(name),
                }),
                "no such parameter",
                null,
            );
        }
    }

    /// A call's arguments in the order its callee declares its parameters.
    ///
    /// `owned` says whether the list is this match's own allocation or the
    /// tree's, handed back untouched because nothing needed reordering. The
    /// caller either transfers or frees the first and must not free the second;
    /// the normalized row duplicates an unowned list when it commits it.
    const Matched = struct { args: []const ExprId, owned: bool };

    fn retainRecoveredGiven(
        self: *Checker,
        id: ExprId,
        owner: CallParameters,
        target: types_mod.CallTarget,
        given: []const ExprId,
        slots: ?[]const ?u32,
    ) std.mem.Allocator.Error!void {
        if (self.recovery_of[id.index()]) return;
        try self.recovered_calls.ensureUnusedCapacity(self.gpa, 1);
        try self.recovered_call_args.ensureUnusedCapacity(self.gpa, given.len);
        for (given, 0..) |argument, i| {
            const parameter = if (slots) |known| known[i] else null;
            self.recovered_call_args.appendAssumeCapacity(.{
                .call = id,
                .argument = argument,
                .target = owner.directTarget(),
                .parameter = parameter,
                .convention = if (parameter) |at| owner.paramConvention(self, at) else .read,
            });
        }
        self.recovered_calls.appendAssumeCapacity(.{ .at = id, .target = target, .callee_convention = owner.invocation(self) });
        self.recovery_of[id.index()] = true;
    }

    fn retainRecoveredMatched(
        self: *Checker,
        id: ExprId,
        owner: CallParameters,
        target: types_mod.CallTarget,
        args: []const ExprId,
    ) std.mem.Allocator.Error!void {
        if (self.recovery_of[id.index()]) return;
        var written: usize = 0;
        for (args) |argument| if (argument != .none) {
            written += 1;
        };
        try self.recovered_calls.ensureUnusedCapacity(self.gpa, 1);
        try self.recovered_call_args.ensureUnusedCapacity(self.gpa, written);
        for (args, 0..) |argument, at| {
            if (argument == .none) continue;
            self.recovered_call_args.appendAssumeCapacity(.{
                .call = id,
                .argument = argument,
                .target = owner.directTarget(),
                .parameter = @intCast(at),
                .convention = owner.paramConvention(self, at),
            });
        }
        self.recovered_calls.appendAssumeCapacity(.{ .at = id, .target = target, .callee_convention = owner.invocation(self) });
        self.recovery_of[id.index()] = true;
    }

    /// Which argument fills which parameter, as one list in declaration order.
    ///
    /// The one matcher. Every rule below indexes the argument list by parameter
    /// position -- inference, `Self`, a trait's own arguments, the per-argument
    /// check, and, after this pass, ownership and lowering -- so the list is put
    /// in declaration order here, once, and each of them reads that. A reader
    /// pairing arguments with parameters itself would be a second answer to the
    /// question of which argument fills which slot.
    ///
    /// A parameter the call omitted and whose declaration carries a default is
    /// `ExprId.none` in the list, rather than absent from it: the value is
    /// spliced at lowering, so the list every pass reads is already the full
    /// arity and a hole is what says which slot the declaration fills.
    ///
    /// Null where the pairing was refused: a name no parameter answers to, a
    /// parameter given twice, a parameter given nothing and declaring no
    /// default, or more positional arguments than there are parameters. The
    /// caller walks the arguments and poisons the call, because a list refused
    /// has no parameter to check its arguments against.
    fn matchArguments(
        self: *Checker,
        id: ExprId,
        owner: CallParameters,
        target: types_mod.CallTarget,
        given: []const ExprId,
    ) std.mem.Allocator.Error!?Matched {
        const param_count = owner.len(self);
        const names = self.ast.callNames(id);

        // A postfix call's receiver is an argument the tree does not spell, so
        // the written names are short by one against the list this pass was
        // handed. The receiver is pinned to parameter zero and is never named.
        std.debug.assert(given.len == names.len or given.len == names.len + 1);
        const receiver = given.len - names.len;

        // A positional argument after a named one is [S-Args], which the parser
        // has already reported. Pairing remains meaningful before that point,
        // but not at or after it: position stopped meaning anything there.
        var named_one = false;
        var pairing_end: ?usize = null;
        for (names, 0..) |n, j| {
            if (n != TokenId.none) {
                named_one = true;
                continue;
            }
            if (named_one) {
                pairing_end = receiver + j;
                break;
            }
        }

        // Nothing is named, so each argument fills the parameter at its own
        // position and the tree's list already is the answer. Nearly every call
        // in a program takes this path, and none of them allocates.
        if (!named_one) return self.positionalArguments(id, owner, target, given, receiver);

        // A value nothing declared names for has no labels to match, so
        // its call takes arguments by position, and that is the one thing
        // to say about every name it was given.
        if (owner == .signature) {
            for (names) |n| if (n != TokenId.none) {
                self.sink.add(.{
                    .severity = .err,
                    .code = .t_unknown_parameter,
                    .message = "a call through this value passes its arguments by position",
                    .labels = try self.sink.arena.dupe(Label, &.{.{
                        .file = self.ast.fileOf(n),
                        .span = self.ast.tokenSpan(n),
                        .message = "nothing that declared this value names its parameters",
                        .style = .primary,
                    }}),
                    .notes = try self.sink.arena.dupe([]const u8, &.{"drop the label, or bind the value with a written `fn` type"}),
                }) catch {};
                break;
            };
            return null;
        }

        const filled = try self.gpa.alloc(ExprId, param_count);
        errdefer self.gpa.free(filled);
        @memset(filled, ExprId.none);
        const recovered_slots = try self.gpa.alloc(?u32, given.len);
        defer self.gpa.free(recovered_slots);
        @memset(recovered_slots, null);

        var refused = pairing_end != null;
        var surplus = false;

        // Where the next positional argument lands. Positional arguments form
        // a prefix in declaration order, so counting them is the whole of what
        // says which parameter each one fills.
        var next: usize = 0;

        for (given, 0..) |a, j| {
            if (pairing_end) |end| if (j >= end) continue;
            const name = if (j < receiver) TokenId.none else names[j - receiver];

            if (name == TokenId.none) {
                if (next >= param_count) {
                    surplus = true;
                    continue;
                }
                recovered_slots[j] = @intCast(next);
                // A positional argument reaching a parameter a name already
                // filled is [S-Args] as well -- position stopped meaning
                // anything once a name was written -- and it is still a
                // parameter given twice.
                if (filled[next] != ExprId.none) {
                    _ = self.report(
                        .t_duplicate_parameter,
                        a,
                        "`{s}` is already given",
                        .{owner.paramSpelling(self, next)},
                        "given twice",
                    );
                    refused = true;
                    next += 1;
                    continue;
                }
                filled[next] = a;
                next += 1;
                continue;
            }

            const at = (try self.paramSlot(owner, self.ast.tokenName(name))) orelse {
                self.reportAtToken(
                    .t_unknown_parameter,
                    name,
                    try std.fmt.allocPrint(self.gpa, "`{s}` declares no parameter `{s}`", .{
                        owner.name(self),
                        self.ast.tokenText(name),
                    }),
                    "no such parameter",
                    owner.origin(self),
                );
                refused = true;
                continue;
            };
            recovered_slots[j] = at;

            // The pairing, kept whether or not the argument goes on to fill the
            // parameter. A name written twice names the parameter twice, and a
            // rename that rewrote only the first would leave the program saying
            // something the programmer never wrote.
            try self.named.append(self.gpa, .{
                .name = name,
                .param = owner.paramToken(self, at) orelse TokenId.none,
                .call = id,
                .slot = @intCast(at),
            });

            if (filled[at] != ExprId.none) {
                self.reportAtToken(
                    .t_duplicate_parameter,
                    name,
                    try std.fmt.allocPrint(self.gpa, "`{s}` is already given", .{self.ast.tokenText(name)}),
                    "given twice",
                    .{
                        .file = self.ast.fileOfExpr(filled[at]),
                        .span = self.ast.exprSpan(filled[at]),
                        .message = "given here",
                        .style = .secondary,
                    },
                );
                refused = true;
                continue;
            }
            filled[at] = a;
        }

        if (pairing_end == null and surplus) {
            try self.reportSurplus(id, owner, param_count, given.len, receiver);
            refused = true;
        }

        if (pairing_end == null) {
            for (filled, 0..) |f, at| {
                if (f != ExprId.none) continue;
                if (owner.hasDefaultAt(self, at)) continue;
                try self.reportMissing(id, owner, at);
                refused = true;
            }
        }

        if (refused) {
            try self.retainRecoveredGiven(id, owner, target, given, recovered_slots);
            self.gpa.free(filled);
            return null;
        }
        return .{ .args = filled, .owned = true };
    }

    /// The pairing where the call names nothing, which is nearly every call.
    ///
    /// Each argument fills the parameter at its own position, so the tree's own
    /// list already is the list in declaration order and there is nothing to
    /// build. What is left is the two ways a count can be wrong, reported
    /// through the same two functions the named path reports them through.
    ///
    /// A call stopping short of the parameters that declare a default is not
    /// one of them: the parameters it left out are filled from their
    /// declarations, so the list is padded to the full arity with a hole where
    /// each omission sits. The hole is what every pass below reads as "this one
    /// was omitted", and it is why the padded list is recorded while an exact
    /// positional call still records nothing.
    fn positionalArguments(
        self: *Checker,
        id: ExprId,
        owner: CallParameters,
        target: types_mod.CallTarget,
        given: []const ExprId,
        receiver: usize,
    ) std.mem.Allocator.Error!?Matched {
        const param_count = owner.len(self);
        if (given.len > param_count) {
            try self.reportSurplus(id, owner, param_count, given.len, receiver);
            const slots = try self.gpa.alloc(?u32, given.len);
            defer self.gpa.free(slots);
            for (slots, 0..) |*slot, i| slot.* = if (i < param_count) @intCast(i) else null;
            try self.retainRecoveredGiven(id, owner, target, given, slots);
            return null;
        }
        if (given.len < param_count) {
            var refused = false;
            for (given.len..param_count) |at| {
                if (owner.hasDefaultAt(self, at)) continue;
                try self.reportMissing(id, owner, at);
                refused = true;
            }
            if (refused) {
                const slots = try self.gpa.alloc(?u32, given.len);
                defer self.gpa.free(slots);
                for (slots, 0..) |*slot, i| slot.* = @intCast(i);
                try self.retainRecoveredGiven(id, owner, target, given, slots);
                return null;
            }

            const filled = try self.gpa.alloc(ExprId, param_count);
            @memcpy(filled[0..given.len], given);
            @memset(filled[given.len..], ExprId.none);
            return .{ .args = filled, .owned = true };
        }
        return .{ .args = given, .owned = false };
    }

    /// More arguments than there are parameters.
    ///
    /// Counted rather than named, because there is no name to report one by: an
    /// argument past the end of the parameter list fills nothing, and how many
    /// were written is what the programmer can see. A postfix call's receiver
    /// is not written between the parentheses, so both counts leave it out; a
    /// call through the type writes the receiver first and counts it.
    fn reportSurplus(
        self: *Checker,
        id: ExprId,
        owner: CallParameters,
        wanted: usize,
        found: usize,
        receiver: usize,
    ) std.mem.Allocator.Error!void {
        const note = if (found == wanted + 1) try self.allocatorFormNote(owner) else null;
        const notes: []const []const u8 = if (note) |text| try self.sink.arena.dupe([]const u8, &.{text}) else &.{};
        _ = self.reportWithOriginNotes(
            .t_arity,
            id,
            try std.fmt.allocPrint(self.gpa, "expected {d} argument(s), found {d}", .{ wanted -| receiver, found -| receiver }),
            "the wrong number of arguments",
            owner.origin(self),
            notes,
        );
    }

    /// The help that names the `_in` partner of the declaration a call
    /// reaches, for a call that gave the system form an allocator.
    fn allocatorFormNote(self: *Checker, owner: CallParameters) std.mem.Allocator.Error!?[]const u8 {
        const name = (try self.allocatorFormOf(owner)) orelse return null;
        return try std.fmt.allocPrint(self.sink.arena, "`{s}` uses the system allocator; use `{s}(allocator, …)` to choose the allocator", .{ name[0 .. name.len - 3], name });
    }

    /// An allocator passed where a parameter of another type stands, to a
    /// declaration with an `_in` partner: the call most often meant the
    /// partner. Asked only when the argument was already refused.
    fn allocatorPassedNote(self: *Checker, actual: TypeId, want: Expected) std.mem.Allocator.Error!?[]const u8 {
        if (want.reason != .parameter or want.passed_to == .none or self.allocator_decl == null) return null;
        if (actual == .poison or want.ty == .poison) return null;
        if (!try self.answersTrait(actual, self.allocator_decl)) return null;
        if (try self.answersTrait(want.ty, self.allocator_decl)) return null;
        return try self.allocatorFormNote(.{ .declaration = want.passed_to });
    }

    /// The name of the declaration beside `owner` that takes the allocator
    /// first, `x_in` beside `x`, when there is one: a call that passed `x` one
    /// argument too many most often meant to choose the allocator. Asked only
    /// on this error path, of the declarations of the callee's own module.
    fn allocatorFormOf(self: *Checker, owner: CallParameters) std.mem.Allocator.Error!?[]const u8 {
        const d = switch (owner) {
            .declaration => |d| d,
            else => return null,
        };
        const name = self.ast.declName(d);
        if (name == .none) return null;
        const wanted = try std.fmt.allocPrint(self.sink.arena, "{s}_in", .{self.ast.tokenText(name)});
        const owned_by = self.ast.declOwner(d);
        for (self.program.declsOf(self.program.moduleOf(d))) |other| {
            const other_name = self.ast.declName(other);
            if (other_name == .none or !std.mem.eql(u8, self.ast.tokenText(other_name), wanted)) continue;
            const other_owner = self.ast.declOwner(other);
            if ((owned_by == .none) != (other_owner == .none)) continue;
            if (owned_by != .none and !std.mem.eql(u8, self.ast.tokenText(owned_by), self.ast.tokenText(other_owner))) continue;
            return wanted;
        }
        return null;
    }

    /// A parameter no argument filled and no declaration fills, named rather
    /// than counted.
    ///
    /// Both pairings ask this of the same parameter list and neither asks it of
    /// a parameter carrying a default: what such a parameter receives is
    /// written where it is declared, so a call leaving it out is complete.
    fn reportMissing(
        self: *Checker,
        id: ExprId,
        owner: CallParameters,
        at: usize,
    ) std.mem.Allocator.Error!void {
        _ = self.reportWithOrigin(
            .t_missing_argument,
            id,
            try std.fmt.allocPrint(self.gpa, "`{s}` receives no argument", .{owner.paramSpelling(self, at)}),
            "every parameter receives one",
            if (owner.paramToken(self, at)) |param| .{
                .file = self.ast.fileOf(param),
                .span = self.ast.tokenSpan(param),
                .message = "declared here",
                .style = .secondary,
            } else null,
        );
    }

    /// How a call names the operation it runs.
    const CallForm = union(enum) {
        /// A function's name or a path to it: `f(x)`, `Measure.of(x)`.
        named,
        /// `x.op()`. The receiver is an argument the tree does not spell: it
        /// was checked to learn which implementations were in play, and the
        /// matcher pins it to parameter zero.
        postfix,
        /// `Limits.default()`: a trait's operation reached through the type
        /// written before the dot, which is the call's `Self`.
        through_type: TypeId,
    };

    /// `Limits.default()` or `T.default()`: a call of the operation
    /// `operationThroughType` finds, with its `Self` settled to the type
    /// written before the dot.
    fn checkCallThroughType(
        self: *Checker,
        id: ExprId,
        field: ExprId,
        given: []const ExprId,
        expected: ?Expected,
    ) std.mem.Allocator.Error!TypeId {
        const through = try self.operationThroughType(field, expected, true) orelse {
            for (given) |a| try self.checkRecoveredArgument(a);
            return self.record(id, .poison);
        };
        return self.checkCallOf(id, through.sig, given, through.form(), expected, &.{});
    }

    /// `create[UInt8]`: a generic function, or a trait's operation named
    /// through its trait, as the value of the instance its brackets name.
    /// The written type arguments settle the function's own parameters before
    /// any use does, as they do before a call's arguments are read.
    fn checkWrittenFunctionValue(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const head = self.ast.binary(id).lhs;
        if (self.res.selectsThroughTrait(head)) {
            const through = try self.operationThroughType(head, null, false) orelse {
                self.recordTypeWrittenAsIndex(self.ast.binary(id).rhs);
                return self.record(id, .poison);
            };
            const written = (try self.writtenTypeArguments(id, through.sig)) orelse return self.record(id, .poison);
            return try self.selectWrittenFunctionValue(id, through.sig, expected, if (through.own) null else through.held, written);
        }
        const d = self.res.declaredBy(self.res.targetOf(head));
        const written = (try self.writtenTypeArguments(id, d)) orelse return self.record(id, .poison);
        return try self.selectWrittenFunctionValue(id, d, expected, null, written);
    }

    fn selectWrittenFunctionValue(
        self: *Checker,
        id: ExprId,
        d: node.DeclId,
        expected: ?Expected,
        written_self: ?TypeId,
        written: []const TypeId,
    ) std.mem.Allocator.Error!TypeId {
        if (try self.selectFunctionValueWith(id, d, expected, written_self, written)) |selected| return selected;
        const what = self.ineligibleFunction(d) orelse notAValue(.function).?;
        return self.report(
            .n_not_a_value,
            id,
            "`{s}` is {s}, and {s} is not a value",
            .{ self.ast.tokenText(self.ast.exprMain(self.ast.binary(id).lhs)), what.noun, what.noun },
            what.hint,
        );
    }

    /// `Limits.default` where a function is expected: the operation
    /// `operationThroughType` finds, as a function value whose `Self` is the
    /// type written before the dot.
    fn checkValueThroughType(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const through = try self.operationThroughType(id, null, false) orelse return self.record(id, .poison);
        return try self.selectFunctionValue(id, through.sig, expected, if (through.own) null else through.held) orelse self.report(
            .n_not_a_value,
            id,
            "`{s}` is not a function value",
            .{self.ast.tokenText(self.ast.exprMain(id))},
            "call it",
        );
    }

    /// An operation reached through a type, and the type it was reached
    /// through, which is its `Self`.
    const ThroughType = struct {
        sig: node.DeclId,
        held: TypeId,
        /// Whether the operation is the type's own rather than a trait's.
        own: bool,

        /// A trait's operation is called with `Self` settled to the type; the
        /// type's own is an ordinary call of the member.
        fn form(self: ThroughType) CallForm {
            return if (self.own) .named else .{ .through_type = self.held };
        }
    };

    /// What `Limits.default` or `T.default` names, where the type's own
    /// namespace holds no `default`: the operation of a trait in scope that
    /// the type implements, or that a bound on the parameter promises. The
    /// type's own declarations were settled by the resolver and never reach
    /// here, so they come first, as they do for the postfix form. Which trait
    /// answers is `Reach.namespaced` read through `NameReach.reaches`, the rule
    /// the postfix form reads, so two traits answering are ambiguous.
    ///
    /// Null where nothing answers, reported here, with the selection and the
    /// type before it recorded.
    fn operationThroughType(self: *Checker, field: ExprId, expected: ?Expected, called: bool) std.mem.Allocator.Error!?ThroughType {
        const base = self.ast.unaryOperand(field);
        const named = self.res.targetOf(base);
        const wanted = self.ast.tokenName(self.ast.exprMain(field));
        const name = self.ast.tokenText(self.ast.exprMain(field));

        // A generic type named where nothing says which instantiation is
        // meant still reaches its own operations, whose block settles its
        // parameters from the call; which traits apply waits on the
        // instantiation, so they are asked only where one is known.
        //
        // A generic alias is read through the declaration its target names:
        // the alias's own parameters are settled by the call and checked
        // against what the alias writes there.
        const named_decl: ?node.DeclId = if (self.res.kindOf(named) == .declared_type)
            self.res.declaredBy(named)
        else if (self.genericAliasHead(named) != null)
            self.declaringType(self.aliasPathType(named).?)
        else
            null;
        const generic_template: ?node.DeclId = if (named_decl) |d|
            (if (self.instanceFor(d, expected) == null) d else null)
        else
            null;
        // A non-generic alias names its instantiation, so nothing is left for
        // the call to settle about the type.
        const held: TypeId = if (named_decl) |d|
            self.instanceFor(d, expected) orelse self.type_of_decl.get(d)
        else if (self.aliasPathType(named)) |aliased| aliased else self.namespaceType(named);
        // A module path before the type, `json.ParseLimits.default()`, names
        // no value and holds unit, as it does before any qualified name.
        self.noteQualifier(base);
        _ = self.record(base, held);
        if (held == .poison or self.argumentPoisoned(held)) {
            _ = self.record(field, .poison);
            return null;
        }

        var declaring: std.ArrayList(node.DeclId) = .empty;
        defer declaring.deinit(self.gpa);
        var applicable: std.ArrayList(Applicable) = .empty;
        defer applicable.deinit(self.gpa);
        var dropped: ?Reach.Dropped = null;
        if (generic_template == null) try self.prepareNamedLookup(held, wanted, true, .namespaced, &declaring);
        const pool = try self.builder.capabilityView();
        try self.reaching(&pool).namespaced(self.gpa, held, wanted, generic_template == null, &applicable, &dropped);

        var reached: std.ArrayList(Applicable) = .empty;
        defer reached.deinit(self.gpa);
        try reached.appendSlice(self.gpa, applicable.items);
        try keepReached(self.gpa, self.ast, &reached);
        if (reached.items.len == 1) {
            const a = reached.items[0];
            return .{ .sig = a.sig, .held = held, .own = a.trait == node.DeclId.none };
        }
        _ = self.record(field, .poison);
        if (applicable.items.len != 0) {
            try self.reportAmbiguous(field, held, applicable.items, called);
        } else if (dropped) |own| {
            _ = try self.reportDropped(field, held, own);
        } else if (generic_template) |d| {
            _ = self.reportWrongInstance(base, d, expected);
        } else {
            _ = try self.reportNothingThroughType(field, named, held, name, declaring.items);
        }
        return null;
    }

    /// Whether an instantiation was given a type already reported, so what
    /// it reaches was said wrong where that type was written.
    fn argumentPoisoned(self: *const Checker, held: TypeId) bool {
        const instance = self.builder.instanceOf(held) orelse return false;
        return std.mem.indexOfScalar(TypeId, self.builder.argsOf(instance), .poison) != null;
    }

    /// Two or more traits answering the type declare the operation a postfix
    /// call or a name written after the type's name reaches, and the type
    /// declares none itself. A diagnostic rather than an order of preference:
    /// a rule that silently picked one would let an import or a bound change
    /// what an existing call means. Which one was meant is written by naming
    /// the trait instead, and the report writes that spelling for each trait
    /// answering, as this module can write it.
    fn reportAmbiguous(
        self: *Checker,
        at: ExprId,
        held: TypeId,
        answering: []const Applicable,
        called: bool,
    ) std.mem.Allocator.Error!void {
        const arena = self.sink.arena;
        const operation = self.ast.tokenText(self.ast.declName(answering[0].sig));
        var traits: std.ArrayList(u8) = .empty;
        var spellings: std.ArrayList(u8) = .empty;
        for (answering, 0..) |a, k| {
            const separator: []const u8 = if (k == 0) "" else if (k + 1 == answering.len) " and " else ", ";
            const spoken: []const u8 = if (k == 0) "" else if (k + 1 == answering.len) " or " else ", ";
            const trait = self.ast.tokenText(self.ast.declName(a.trait));
            try traits.print(arena, "{s}`{s}`", .{ separator, trait });
            // A trait reached through a bound alone is not in scope by its own
            // name, so its spelling is qualified by the module a `use` would
            // name.
            if (self.res.seesTrait(self.current, a.trait)) {
                try spellings.print(arena, "{s}`{s}.{s}{s}`", .{ spoken, trait, operation, if (called) "(…)" else "" });
            } else {
                const route = self.res.useRoute(self.program.source, self.ast, self.ast.fileOfExpr(at), a.trait);
                try spellings.print(arena, "{s}`{s}.{s}.{s}{s}`", .{ spoken, route.module, trait, operation, if (called) "(…)" else "" });
            }
        }
        try self.sink.addErrorFmt(
            .n_ambiguous,
            self.ast.fileOfExpr(at),
            self.ast.exprSpan(at),
            try std.fmt.allocPrint(arena, "write {s}, which says which trait it goes through", .{spellings.items}),
            "{s} {s} declare `{s}` for `{s}`",
            .{ traits.items, if (answering.len == 2) "both" else "all", operation, (try self.typeName(held)) },
        );
    }

    /// A call written after a type's name that no trait operation answers.
    /// A trait out of scope that would answer is named with the `use` that
    /// brings it; a trait in scope declaring the name is named as the one to
    /// implement; a type parameter is told its bounds promise no such
    /// operation.
    fn reportNothingThroughType(
        self: *Checker,
        field: ExprId,
        named: BindingId,
        held: TypeId,
        name: []const u8,
        declaring: []const node.DeclId,
    ) std.mem.Allocator.Error!TypeId {
        const base = self.ast.unaryOperand(field);
        if (self.res.kindOf(named) == .type_parameter) {
            return self.report(
                .t_unknown_field,
                field,
                "type parameter `{s}` has no member `{s}`",
                .{ self.ast.tokenText(self.ast.exprMain(base)), name },
                "the declared constraints do not provide this member",
            );
        }
        const pool = try self.builder.capabilityView();
        const elsewhere = try self.reaching(&pool).namespacedElsewhere(self.gpa, held, self.ast.tokenName(self.ast.exprMain(field)));
        if (elsewhere != node.DeclId.none) return self.reportOutOfScope(field, name, elsewhere);
        const spelled = try self.typeName(held);
        if (declaring.len != 0) {
            return self.report(
                .n_undefined,
                field,
                "`{s}` declares no `{s}`, and implements no trait in scope that does",
                .{ spelled, name },
                switch (try self.editFor(declaring[0], &.{}, held, false, 0)) {
                    .edit => |edit| try std.fmt.allocPrint(self.gpa, "`{s}` declares `{s}`; {s} to reach it here", .{ self.ast.tokenText(self.ast.declName(declaring[0])), name, edit }),
                    .refused => |refusal| try std.fmt.allocPrint(self.gpa, "`{s}` declares `{s}`, and {s}", .{ self.ast.tokenText(self.ast.declName(declaring[0])), name, refusal.reason }),
                },
            );
        }
        return self.report(
            .n_undefined,
            field,
            "`{s}` declares no `{s}`",
            .{ spelled, name },
            "and no trait it implements declares one",
        );
    }

    /// One call, however it was written and whatever named its callee.
    ///
    /// The two spellings differ in how the callee and the arguments are found
    /// and in nothing after that, so they are found above and everything the
    /// language says about a call is said once, here.
    fn checkCallOf(
        self: *Checker,
        id: ExprId,
        d: node.DeclId,
        given: []const ExprId,
        form: CallForm,
        expected: ?Expected,
        /// The type arguments the call's brackets name, which settle the
        /// function's own type parameters before any argument is read. Empty
        /// where the call names none.
        written: []const TypeId,
    ) std.mem.Allocator.Error!TypeId {
        const c = self.ast.call(id);
        const params = self.ast.declParams(d);
        const diagnostics_before = self.sink.error_count;
        try self.ensureDefaults(d);
        _ = self.record(c.callee, .unit);
        // A postfix callee selects from its receiver, which is a value rather
        // than a path naming the operation, and a call through a type recorded
        // the type it was written after.
        const postfix = form == .postfix;
        if (form == .named) self.noteQualifier(c.callee);
        // The name the call was written with, in front of any type arguments.
        const named = self.ast.exprMain(if (written.len > 0) self.ast.binary(c.callee).lhs else c.callee);

        // A projection is not callable. Its braces hold a place rather than
        // code, so a call has nothing to run: what reaches one is a bracket,
        // which becomes the path the projection names.
        //
        // Refused here, where every spelling of a call arrives, so the postfix
        // form and the trait's own name are answered by one rule. It has to be
        // refused rather than merely unreachable, and this is why: a call is
        // what queues a body for lowering, so an admitted one emits the path as
        // an ordinary function -- whose parts the ownership pass never walks,
        // because it walks functions. A projection reached by a call was a
        // linear part moved out of a container with nothing to say so.
        if (memberKind(self.ast, d) == .projection) {
            for (c.args) |a| try self.checkRecoveredArgument(a);
            return self.report(
                .t_projection,
                id,
                "`{s}` is a projection, and a projection is reached through a bracket rather than a call",
                .{self.ast.tokenText(self.ast.declName(d))},
                "write the bracket its trait gives the value",
            );
        }

        // Before anything indexes the arguments, because everything below
        // indexes them by parameter position. What was written is put in
        // declaration order once and every reader takes that list.
        const target: types_mod.CallTarget = .{ .declared = d };
        const matched = (try self.matchArguments(id, .{ .declaration = d }, target, given)) orelse {
            // Past the receiver, which a postfix call checked to learn which
            // implementations were in play at all. Walking it again reports
            // whatever is wrong inside it a second time -- a mutation of a
            // place, a copy with no effect -- for a mistake made in the
            // argument list beside it.
            for (given[given.len - self.ast.callNames(id).len ..]) |a| try self.checkRecoveredArgument(a);
            return self.record(id, .poison);
        };
        const args = matched.args;

        // The normalized row owns its complete argument run. An allocation the
        // matcher already made transfers there; a tree or postfix slice is
        // duplicated only when the row is committed.
        var args_owned = matched.owned;
        defer if (args_owned) self.gpa.free(args);

        // A generic function's parameters are settled by the arguments that
        // determine them, before any argument is checked against one -- a
        // parameter's declared type is not a type until it is.
        // Which arguments inference already walked. Walking one again to
        // check it against the parameter it settled doubles the cost at every
        // level of nesting, and reports whatever is wrong inside it twice --
        // including, for a call within a call, a second record of what that
        // inner call instantiated.
        const walked = try self.gpa.alloc(bool, args.len);
        defer self.gpa.free(walked);
        @memset(walked, false);
        if (postfix) walked[0] = true;

        // A call reaching a signature settles its `Self` before any parameter
        // is read, for the reason a generic call settles its parameters first:
        // until it is settled, a parameter written `Self` has no type to check
        // an argument against. Saved and restored rather than cleared, because
        // an argument may itself be a call through a trait.
        // What this call answers for the trait's parameters, and the trait
        // that declares them. A signature is written over both its own type
        // parameters and its trait's, and each list is settled by whatever
        // stands where its members are written.
        var trait_decl: node.DeclId = .none;
        var trait_args: []const TypeId = &.{};

        const enclosing_self = self.self_at_call;
        const enclosing_args = self.trait_args_at_call;
        const enclosing_settled = self.self_settled;
        defer {
            self.self_at_call = enclosing_self;
            self.trait_args_at_call = enclosing_args;
            self.self_settled = enclosing_settled;
        }
        var implementation_at: ?usize = null;
        if (self.ast.declIsSignature(d)) {
            const self_settlement = try self.settleSelf(id, d, args, walked, expected, switch (form) {
                .through_type => |held| held,
                .named, .postfix => null,
            });
            self.self_at_call = if (self_settlement) |settled_self| settled_self.ty else null;
            self.self_settled = true;
            implementation_at = if (self_settlement) |settled_self| settled_self.implementation else null;
            trait_decl = self.traitDeclaring(d) orelse node.DeclId.none;
            trait_args = try self.settleTraitArgs(id, d, args, walked, expected);
            // The other half of the key an implementation is found by. A
            // settled reference written in this signature is read through the
            // implementation this call reaches, and the arguments are as much
            // of what picks it as the type is.
            self.trait_args_at_call = trait_args;
            if (implementation_at) |at| {
                const receiver = try self.operationReceiver(d, self.call_impls.items[at].self_ty, trait_args);
                self.call_impls.items[at].self_ty = receiver;
                self.self_at_call = receiver;
                self.call_impls.items[at].args = trait_args;
                try self.checkImplementationExists(id, self.call_impls.items[at]);
            }

            // A `Self` that was reported takes the call with it. Every
            // parameter written in terms of it is a type nobody named, and
            // checking an argument against one says the argument is wrong when
            // what is wrong was already said.
            if (self.self_at_call == TypeId.poison) {
                for (args, 0..) |a, j| {
                    // A hole is a parameter the call omitted, which no walk
                    // above reached and no walk here can: there is no
                    // expression at this call to check, and the constant that
                    // fills it was checked where it is declared.
                    if (a == ExprId.none) continue;
                    if (!walked[j]) try self.checkRecoveredArgument(a);
                }
                try self.retainRecoveredMatched(id, .{ .declaration = d }, target, args);
                return self.record(id, .poison);
            }
        }

        // A member of an implementation generic over its head is written in
        // that implementation's parameters as much as in its own, and each call
        // binds them from what it was handed. A callee that is a member of no
        // such implementation binds one list, which is the same walk with
        // nothing in the second.
        const over = self.headParametersOf(d);
        const settled = (try self.inferCall(id, d, over, args, walked, expected, written)) orelse {
            try self.retainRecoveredMatched(id, .{ .declaration = d }, target, args);
            return self.record(id, .poison);
        };
        const supplied = settled.own;
        const errors_before_bounds = self.sink.error_count;
        if (self.constraints.rangeOfDeclaration(d).len() > 0) {
            // The arguments a call settled are as much an instantiation as the
            // ones a written type spells, and a bound constrains both. A
            // trait's operation is written in the trait's parameters as an
            // implementation's member is in the implementation's, and the call
            // settled them as it settled the head.
            const enclosing = BoundSettlement.enclosing(over, settled.head, trait_decl, trait_args);
            const bounded = try self.withSettledSelf(d, supplied);
            defer if (bounded.ptr != supplied.ptr) self.gpa.free(bounded);
            if (written.len > 0) {
                // A type argument written in the call's brackets is refused
                // where it was written.
                if (!self.refusedBefore(named))
                    _ = try self.argumentBoundsUnmet(d, bounded, enclosing, named, self.ast.typeArgs(self.ast.bracketTypes(c.callee).?), .report);
            } else try self.checkArgumentBounds(d, bounded, enclosing, named);
        }
        if (settled.head.len > 0) {
            // The bounds an implementation writes on its own parameters say
            // which members of the family it answers for, and a call naming one
            // it does not answer for reaches no body.
            try self.checkArgumentBounds(over, settled.head, null, named);
            implementation_at = try self.noteSettledHead(id, over, settled.head);
        }
        // One mistake, one report: a bound the declaration refused is not
        // reported again at the alias that heads the path.
        if (self.sink.error_count != errors_before_bounds and self.calledThroughAlias(id) != null) {
            const callee = self.ast.withoutGroups(self.ast.call(id).callee);
            try self.noteRefused(self.ast.exprMain(self.ast.unaryOperand(callee)));
        }

        // A parameter's type flows into its argument, so a literal argument
        // takes it exactly as it would take an annotation's.
        var callable_params = try self.gpa.alloc(types_mod.CallableParam, params.len);
        defer self.gpa.free(callable_params);
        var signature_valid = true;
        var arguments_valid = true;
        var argument_diverges = false;
        const receiver_adjustments = try self.gpa.alloc(?types_mod.ReceiverAdjustment, args.len);
        @memset(receiver_adjustments, null);
        var observations_owned = true;
        defer if (observations_owned) self.gpa.free(receiver_adjustments);
        for (args, params, 0..) |a, p, j| {
            const parameter_ty = try self.throughTrait(
                try self.throughCall(try paramType(self, d, j), d, over, settled),
                trait_decl,
                trait_args,
            );
            var default: types_mod.CallableDefault = .absent;
            if (hasDefault(p)) {
                if (self.defaults.get(@intCast(d.index()), @intCast(j))) |value| {
                    default = .{ .value = value };
                } else {
                    signature_valid = false;
                }
            }
            if (parameter_ty == .poison) signature_valid = false;
            callable_params[j] = .{
                .spelling = self.ast.tokenText(p.name),
                .convention = p.convention,
                .ty = parameter_ty,
                .default = default,
            };

            // An omitted parameter receives the constant its declaration
            // writes, which was checked against this same parameter where it
            // was written. There is no argument here to check, no convention
            // for one to break, and nothing at this call site the value could
            // have come from.
            if (a == ExprId.none) continue;

            // A postfix call's receiver is marked by the `&` written before
            // the whole call, `&x.op(args)`, where an argument carries its own.
            const receiver = postfix and j == 0;
            const written_mark = self.ast.exprTag(a) == .marked;
            const marked = written_mark or (receiver and self.ast.callMarked(id));
            const value = if (written_mark) self.ast.unaryOperand(a) else a;
            const declared: Label = .{
                .file = self.ast.fileOf(p.name),
                .span = self.ast.tokenSpan(p.name),
                .message = switch (p.convention) {
                    .inout => "declared `inout`",
                    .sink => "declared `sink`",
                    .read => "declared `read`",
                },
                .style = .secondary,
            };

            if (marked and p.convention == .inout) try self.decideMark(if (written_mark) a else id, .lent);
            switch (p.convention) {
                .inout => if (!marked) {
                    arguments_valid = false;
                    if (receiver and self.isAPlace(a)) {
                        _ = self.reportWithOrigin(
                            .s_mutation,
                            a,
                            "this receiver is mutated, so the call is marked `&`",
                            try std.fmt.allocPrint(self.sink.arena, "write `&{s}.{s}(...)`", .{
                                self.ast.exprText(a),
                                self.ast.tokenText(named),
                            }),
                            declared,
                        );
                    } else if (receiver) {
                        // A `&` lends a place, and a call's result is none, so
                        // marking this call would not reach the value it changes.
                        _ = self.reportWithOrigin(
                            .s_mutation,
                            a,
                            "this receiver is mutated, and a value that is not a place cannot be lent",
                            "bind the value to a `var`, then call the operation on it with `&`",
                            declared,
                        );
                    } else {
                        _ = self.reportWithOrigin(.s_mutation, a, "this argument is mutated, so it is marked `&`", "expected `&` here", declared);
                    }
                },
                // Neither lends: `read` may not be written through and `sink`
                // is given away outright, so `&` says nothing true of either.
                .read, .sink => if (marked) {
                    arguments_valid = false;
                    if (receiver) {
                        _ = self.reportWithOrigin(.s_mutation, a, "this receiver is not mutated, so the call takes no `&`", "remove the `&` before it", declared);
                        try self.decideMark(id, .refused);
                    } else {
                        _ = self.reportWithOrigin(.s_mutation, a, "this argument is not mutated, so it takes no `&`", "unexpected `&`", declared);
                        try self.decideMark(a, .refused);
                    }
                },
            }

            const want: Expected = .{
                .ty = parameter_ty,
                .at = .{ .file = self.ast.fileOf(p.name), .span = self.ast.tokenSpan(p.name) },
                .reason = .parameter,
                .receiver = try self.receiverArgument(d, args, params, j, try paramType(self, d, j)),
                .passed_to = d,
            };
            var adjusted: ?types_mod.ReceiverAdjustment = null;
            if (readsSelf(self.ast, p)) {
                // Known observation descriptors retain their own type for
                // forwarding; waiting literals use the settled receiver type.
                const got = if (walked[j]) self.builder.exprType(value) else try self.check(value, if (self.determinesItsOwnType(value)) null else want);
                walked[j] = true;
                // Both sides are settled here, so the parameter is held to
                // what is left by identity.
                const Same = struct {
                    want: TypeId,
                    fn fits(same: @This(), left: TypeId) bool {
                        return left == same.want;
                    }
                };
                // Settling `Self` may have settled an integer literal the
                // argument holds, so the argument is compared as settled.
                const settled_got = try self.builder.resolveOpen(got, &self.open_types);
                if (observationsPassing(&self.builder, self.ast, p, settled_got, Same{ .want = parameter_ty })) |layers| {
                    const selection: types_mod.ReceiverAdjustment = .{
                        .observations = layers,
                        .receiver = parameter_ty,
                        .selection = if (self.ast.declIsSignature(d)) .implementation else .static,
                    };
                    if (layers > 0 or selection.selection == .implementation) adjusted = selection;
                }
            }
            receiver_adjustments[j] = adjusted;
            const at = if (adjusted != null) parameter_ty else if (walked[j])
                try self.expect(value, self.builder.exprType(value), want)
            else
                try self.check(value, want);
            if (at == .poison) arguments_valid = false;
            if (at == .never) argument_diverges = true;
            // The marker is not an operation: it has the type of the place it
            // marks, so nothing below it sees a distinct kind of value.
            if (written_mark) _ = self.record(a, at);
            // A lend is a write the callee may make, so it asks of a
            // projection exactly what an assignment asks.
            if (marked) try self.written.append(self.gpa, .{ .at = value, .refused = "this place cannot be lent" });
        }

        const source_signature = self.builder.get(self.decl_signatures.get(d));
        const contracts = if (source_signature == .callable) source_signature.callable.contracts else &.{};
        if (source_signature == .callable) {
            for (callable_params, self.builder.callableParams(source_signature.callable)) |*param, source_param| param.stable_address = source_param.stable_address;
        }
        try self.checkStableArguments(args, callable_params, receiver_adjustments);
        try self.checkExclusivity(args, if (postfix) lentReceiver(self.ast, self.res, id, written.len > 0) else ExprId.none);

        const returns = try self.throughTrait(
            try self.throughCall(try returnType(self, d), d, over, settled),
            trait_decl,
            trait_args,
        );
        const result_type = if (argument_diverges)
            TypeId.never
        else
            returns;
        const result = try self.expect(id, result_type, expected);

        // Only a complete accepted check becomes a downstream semantic row.
        // Some diagnostics deliberately return no status, while a poisoned
        // argument can be accumulated without stopping this walk, so both the
        // sink delta and the values checked above belong to this gate.
        if (!arguments_valid or
            !signature_valid or
            returns == .poison or
            result == .poison or
            self.sink.error_count != diagnostics_before)
        {
            try self.retainRecoveredMatched(id, .{ .declaration = d }, target, args);
            return result;
        }

        // A call checked again is still one expression and therefore one
        // semantic answer. The first complete row is the one every index reads.
        if (self.call_of[id.index()] != no_call) return result;

        const normalized_args = if (args_owned) take: {
            args_owned = false;
            break :take args;
        } else try self.gpa.dupe(ExprId, args);
        errdefer self.gpa.free(normalized_args);

        const own_args = if (settled.own.len == 0) &.{} else try self.gpa.dupe(TypeId, settled.own);
        errdefer if (own_args.len > 0) self.gpa.free(own_args);
        var implementation_args = settled.head;
        if (implementation_at) |row| {
            const selected = self.call_impls.items[row];
            if (selected.ofATrait()) {
                if (try self.builder.implementationChoiceWithin(self.generic, node.DeclId.at(selected.trait), selected.args, selected.self_ty)) |choice| implementation_args = choice.impl_args;
            }
        }
        const impl_args = try self.gpa.dupe(TypeId, implementation_args);
        errdefer self.gpa.free(impl_args);

        var implementation: ?types_mod.CallImpl = null;
        if (implementation_at) |at| {
            var selected = self.call_impls.items[at];
            if (selected.args.len > 0) selected.args = try self.gpa.dupe(TypeId, selected.args);
            implementation = selected;
        }
        errdefer if (implementation) |selected| if (selected.args.len > 0) self.gpa.free(selected.args);

        const signature = try self.builder.internCallable(callable_params, returns, contracts, .read);

        const at: u32 = @intCast(self.calls.items.len);
        try self.calls.append(self.gpa, .{
            .at = id,
            .target = .{ .declared = d },
            .signature = signature,
            .args = normalized_args,
            .receiver_adjustments = receiver_adjustments,
            .selection = .{
                .own_args = own_args,
                .implementation = implementation,
                .impl_args = impl_args,
            },
            .written_type_arguments = written.len > 0,
        });
        observations_owned = false;
        self.call_of[id.index()] = at;
        return result;
    }

    fn writesBackToTheCaller(self: *const Checker, place: ExprId) bool {
        return self.res.parameterConvention(self.ast, self.res.pathBinding(self.ast, place)) == .inout;
    }

    fn settledCallableBound(
        self: *Checker,
        own: ?OwnBound,
        bound: node.TraitBound,
    ) std.mem.Allocator.Error!TypeId {
        const o = own orelse return self.boundSignature(self.current, self.generic, bound);
        const raw = switch (o.source) {
            .parameter => try self.boundSignature(self.program.moduleOf(o.decl), o.decl, bound),
            .scope => |ctx| try self.boundSignature(ctx.module, ctx.owner, bound),
        };
        return self.substituteOwnBoundType(raw, o);
    }

    /// How many steps a place takes before reaching the name it is rooted at.
    fn pathDepth(self: *const Checker, id: ExprId) u32 {
        var n: u32 = 0;
        var at = self.ast.withoutGroups(id);
        while (self.placeBase(at) != ExprId.none) : (n += 1) at = self.placeBase(at);
        return n;
    }

    /// The place one step inside this one, or `.none` where this is a root.
    ///
    /// A pattern's name is a step rather than a root of its own, and so is a
    /// pattern nested inside the one that took its root apart.
    /// `match read e { V(p) => ... }` binds `p` to part of `e`, so the two are
    /// names for memory one write reaches -- and a binder that answered as its
    /// own root shared a root with nothing, which made `f(&e, p)` two places
    /// the rule could not see were one.
    ///
    /// A bracket is a step for the same reason a selection is: what it names
    /// is part of the place it sits over, whether the bracket indexes an array
    /// or expands into a projection's path. A bracket that answered as a root
    /// shared a root with the binding it was written on, which made `f(&a[0],
    /// a)` two places -- and a projection reaching its own receiver made them
    /// one place with nothing to see it. Which element the bracket reached is
    /// the step's, not the base's, so `a[0]` and `a[1]` share this base and
    /// part at the step above it.
    fn placeBase(self: *const Checker, id: ExprId) ExprId {
        const at = self.ast.withoutGroups(id);
        switch (self.ast.exprTag(at)) {
            .field, .dereference => return self.ast.withoutGroups(self.ast.unaryOperand(at)),
            .index => return self.ast.withoutGroups(self.ast.binary(at).lhs),
            .name_ref => {
                const b = self.res.targetOf(at);
                if (b == BindingId.none) return ExprId.none;
                const from = self.binder_places[b.index()] orelse return ExprId.none;
                return self.ast.withoutGroups(from.of);
            },
            .call, .tuple_pattern, .struct_pattern => {
                const from = self.pattern_places.get(at) orelse return ExprId.none;
                return self.ast.withoutGroups(from.of);
            },
            else => return ExprId.none,
        }
    }

    /// The step this place takes from the one inside it, or null where it
    /// takes none.
    fn placeStep(self: *const Checker, id: ExprId) ?Step {
        const at = self.ast.withoutGroups(id);
        switch (self.ast.exprTag(at)) {
            .field => return .{ .field = self.ast.tokenName(self.ast.exprMain(at)) },
            .dereference => return .observed,
            .index => return .{ .element = self.settledElement(at) },
            .name_ref => {
                const b = self.res.targetOf(at);
                if (b == BindingId.none) return null;
                const from = self.binder_places[b.index()] orelse return null;
                return from.step;
            },
            .call, .tuple_pattern, .struct_pattern => {
                const from = self.pattern_places.get(at) orelse return null;
                return from.step;
            },
            else => return null,
        }
    }

    /// Whether two expressions name places that overlap.
    ///
    /// Two places overlap when they share a root and one path is a prefix of
    /// the other: writing through `o.inner` changes what `o` and `o.inner.y`
    /// name, and changes nothing `o.z` names. A step parts them only where it
    /// cannot be the other's, so two elements part where both settled and
    /// settled apart and nowhere else.
    ///
    /// The tree runs from the leaf inwards, so the paths are compared in that
    /// direction. The longer one drops its extra steps first, and what remains
    /// on each side is the prefix the rule asks about.
    fn overlaps(self: *const Checker, a: ExprId, b: ExprId) bool {
        var x = self.ast.withoutGroups(a);
        var y = self.ast.withoutGroups(b);
        var dx = self.pathDepth(x);
        var dy = self.pathDepth(y);
        while (dx > dy) : (dx -= 1) x = self.placeBase(x);
        while (dy > dx) : (dy -= 1) y = self.placeBase(y);

        while (dx > 0) : (dx -= 1) {
            const sx = self.placeStep(x) orelse return false;
            const sy = self.placeStep(y) orelse return false;
            if (!sx.conflicts(sy)) return false;
            x = self.placeBase(x);
            y = self.placeBase(y);
        }

        if (self.ast.exprTag(x) != .name_ref or self.ast.exprTag(y) != .name_ref) return false;
        const root = self.res.targetOf(x);
        return root != BindingId.none and root == self.res.targetOf(y);
    }

    /// Whether an expression names a place overlapping `marked`, anywhere
    /// within it.
    fn mentions(self: *const Checker, id: ExprId, marked: ExprId, except: BindingId) bool {
        return self.mentionAt(id, marked, except) != ExprId.none;
    }

    /// The first place within an expression that overlaps `marked`, or none:
    /// what `mentions` answers, with the place a report points at.
    fn mentionAt(self: *const Checker, id: ExprId, marked: ExprId, except: BindingId) ExprId {
        if (id == ExprId.none) return ExprId.none;
        const tag = self.ast.exprTag(id);

        // A place is compared whole, by the walk every rule about a path is
        // driven by. Descending into a step's base would find the bare `o`
        // inside `o.z`, which overlaps everything rooted at `o`, and the bare
        // `a` inside `a[1]`, which overlaps `a[0]` -- so a step's own answer
        // would never be reached. What is left to walk is what the place is
        // not: a bracket's index, which is an ordinary expression and may name
        // a place of its own, and a base that is no place at all, as in
        // `f(x).y`.
        if (tag == .name_ref or tag == .field or tag == .index) {
            // A use of the lend itself is the lend being used.
            if (self.isThroughLend(id, except)) return ExprId.none;
            if (self.overlaps(id, marked)) return id;
            var steps = self.ast.placeSteps(id);
            while (steps.next()) |step| {
                if (self.ast.exprTag(step) != .index) continue;
                const found = self.mentionAt(self.ast.binary(step).rhs, marked, except);
                if (found != ExprId.none) return found;
            }
            if (self.ast.exprTag(steps.at) == .name_ref) return ExprId.none;
            return self.mentionAt(steps.at, marked, except);
        }

        return switch (tag.payload()) {
            .none => ExprId.none,
            .unary => self.mentionAt(self.ast.unaryOperand(id), marked, except),
            .binary => blk: {
                const b = self.ast.binary(id);
                break :blk self.firstMention(&.{ self.mentionAt(b.lhs, marked, except), self.mentionAt(b.rhs, marked, except) });
            },
            .conditional => blk: {
                const c = self.ast.conditional(id);
                break :blk self.firstMention(&.{ self.mentionAt(c.cond, marked, except), self.mentionAt(c.then, marked, except), self.mentionAt(c.otherwise, marked, except) });
            },
            .call => blk: {
                const c = self.ast.call(id);
                // A postfix call's callee is no place: `x.op` names the
                // operation, and what the call reads is its receiver `x`.
                const callee = if (isPostfixCallee(self.ast, self.res, c.callee)) fieldBase(self.ast, c.callee) else c.callee;
                {
                    const found = self.mentionAt(callee, marked, except);
                    if (found != ExprId.none) break :blk found;
                }
                for (c.args) |a| {
                    {
                        const found = self.mentionAt(a, marked, except);
                        if (found != ExprId.none) break :blk found;
                    }
                }
                break :blk ExprId.none;
            },
            .interpolation => blk: {
                for (self.ast.interpolation(id).pieces) |piece| {
                    {
                        const found = self.mentionAt(piece, marked, except);
                        if (found != ExprId.none) break :blk found;
                    }
                }
                break :blk ExprId.none;
            },
            .lambda => blk: {
                for (self.ast.lambda(id).captures) |capture| {
                    const found = self.mentionAt(capture.source, marked, except);
                    if (found != ExprId.none) break :blk found;
                }
                for (self.ast.lambda(id).params) |p| {
                    {
                        const found = self.mentionAt(p.default, marked, except);
                        if (found != ExprId.none) break :blk found;
                    }
                }
                break :blk ExprId.none;
            },
            .block => blk: {
                const b = self.ast.blockOf(id);
                for (self.ast.blockStmts(b)) |s| {
                    {
                        const found = self.mentionAt(self.ast.stmtData(s).init, marked, except);
                        if (found != ExprId.none) break :blk found;
                    }
                }
                break :blk self.mentionAt(b.tail, marked, except);
            },
            .range => blk: {
                const ends = self.ast.rangeEnds(id);
                break :blk self.firstMention(&.{ self.mentionAt(ends.lhs, marked, except), self.mentionAt(ends.rhs, marked, except) });
            },
        };
    }

    fn firstMention(_: *const Checker, found: []const ExprId) ExprId {
        for (found) |f| if (f != ExprId.none) return f;
        return ExprId.none;
    }

    /// The same question of a structure literal's values, which sit every
    /// other entry beside their field names, followed by its base.
    fn checkLiteralExclusivity(self: *Checker, id: ExprId) std.mem.Allocator.Error!void {
        const c = self.ast.call(id);
        var values: std.ArrayList(ExprId) = .empty;
        defer values.deinit(self.gpa);
        var i: usize = 1;
        while (i < c.args.len) : (i += 2) try values.append(self.gpa, c.args[i]);
        if (self.ast.structLiteralBase(id)) |base| try values.append(self.gpa, base);
        try self.checkExclusivity(values.items, ExprId.none);
    }

    /// A place an argument mutates may not overlap any other argument's
    /// places.
    ///
    /// Checked from the argument list alone -- no inference, no lifetimes --
    /// which is what keeps this a local rule rather than the beginning of a
    /// borrow checker. It is also what makes the representation the
    /// compiler's to choose: nothing can observe whether the argument was
    /// passed as an address or copied in and back.
    ///
    /// Asked of everything the language evaluates as one list: a call's
    /// arguments, what a variant carries, and a literal's field values. A `&`
    /// cannot sit at the top of the last two -- it belongs at a call site --
    /// but it sits inside one of their values as readily as inside an
    /// argument, and `Shape.Round(bump(&p), p)` decides its second value by
    /// the order the first happened to run in.
    ///
    /// A hole in the list is a parameter the call omitted. What fills it is a
    /// constant spliced at lowering, which names no place: it mutates nothing
    /// and nothing reaches it, so it belongs to no pair this rule is about.
    /// Takes a lend of the place `binder` names for the whole of `body`, and
    /// reports what that lend cannot hold.
    ///
    /// Two questions, both answered by `overlaps`. A lend already live and
    /// either of the two writable is a second path to one place -- which is
    /// what `N-Aliased` refuses between two arguments, asked here between two
    /// constructs. And a mutation anywhere in the body naming a place the
    /// lend covers is the same fault written the other way round.
    ///
    /// The body is asked once rather than every write being hooked, because
    /// `sharedMutation` is already the walk that finds a mutation naming a
    /// given place.
    /// Lends the places an arm's binders name, for as long as its body can
    /// read them, and answers how many were taken.
    ///
    /// The binders and not the scrutinee: a pattern names parts, and a rule
    /// lending the whole would refuse writing one part while another is bound
    /// -- an ordinary thing to write, and the reason a step is compared rather
    /// than only the root a path is rooted at.
    fn armLends(self: *Checker, at: ExprId, pattern: ExprId) std.mem.Allocator.Error!usize {
        var taken: usize = 0;
        try self.lendPatternBinders(at, pattern, false, &taken);
        return taken;
    }

    /// Ends `taken` lends an arm opened, checking each against its body.
    fn armEnds(
        self: *Checker,
        pattern: ExprId,
        body: ExprId,
        taken: usize,
    ) std.mem.Allocator.Error!void {
        _ = pattern;
        var left = taken;
        while (left > 0) : (left -= 1) {
            const held = self.lent_now.items[self.lent_now.items.len - 1].place;
            try self.lendEnd(held, body, false);
        }
    }

    fn lendBegin(
        self: *Checker,
        at: ExprId,
        binder: ExprId,
        writable: bool,
    ) std.mem.Allocator.Error!void {
        for (self.lent_now.items) |held| {
            if (!held.writable and !writable) continue;
            // A place reached through a writable lend's own binder is that
            // lend being used, as a marked call through it is: a lent walk
            // over a `for inout` binder advances the element it names.
            if (held.writable and self.isThroughLend(binder, self.res.targetOf(held.place))) continue;
            if (!self.overlaps(binder, held.place)) continue;
            _ = self.report(
                .o_lent,
                at,
                "this lends a place something is already lending",
                .{},
                "one of them has to end before the other begins",
            );
            break;
        }

        try self.lent_now.append(self.gpa, .{ .place = binder, .writable = writable, .at = at });
    }

    /// Ends the lend, and reports a mutation the body made through it.
    ///
    /// Asked once over the body rather than at every write, because
    /// `sharedMutation` is already the walk that finds a mutation naming a
    /// given place -- the same walk `N-Aliased` drives over an argument.
    fn lendEnd(
        self: *Checker,
        binder: ExprId,
        body: ExprId,
        writable: bool,
    ) std.mem.Allocator.Error!void {
        _ = self.lent_now.pop();

        const except = self.res.targetOf(binder);
        const wrote = self.sharedMutation(body, binder, false, except);
        if (wrote != ExprId.none and !self.aliased.contains(wrote)) {
            _ = self.report(
                .o_lent,
                wrote,
                "this writes a place the construct around it is lending",
                .{},
                "write it after the construct ends, or take what it names instead of lending it",
            );
            // Another binder of the same construct ends next and would find
            // this write again.
            try self.aliased.put(self.gpa, wrote, {});
            return;
        }

        // A lend that may write is the only path to what it names, so a read
        // by another path is a second view of what one path is changing --
        // the same answer `N-Aliased` gives an argument read beside one
        // passed `&`. A `read` lend shares, so nothing else is asked of it.
        if (writable and !self.aliased.contains(body) and self.mentions(body, binder, except)) {
            _ = self.report(
                .o_lent,
                body,
                "this reads a place the walk around it lends writably",
                .{},
                "read it through the binder, or lend it with `for read`",
            );
            // Every binder of one pattern ends over the same body, and the
            // body is said once.
            try self.aliased.put(self.gpa, body, {});
        }
    }

    /// Refuses a call whose arguments name one place where one of them
    /// mutates it. `lent` is the receiver a marked postfix call lends, one of
    /// `args`, or none: it is a place mutated exactly as an argument passed
    /// `&` is, though the mark is written before the call.
    fn checkExclusivity(self: *Checker, args: []const ExprId, lent: ExprId) std.mem.Allocator.Error!void {

        // Once per pair, not once per direction: two arguments naming one
        // place is one mistake.
        // A pair is a mistake only where one of the two mutates something, and
        // ordinary code mutates nothing inside an argument. Whether any of them
        // does is one walk of each; the pairs below are a walk of every two, so
        // they are entered only once the answer is yes.
        var mutates = lent != ExprId.none;
        if (!mutates) for (args) |a| {
            if (a == ExprId.none) continue;
            if (self.sharedMutation(a, ExprId.none, true, BindingId.none) != ExprId.none) {
                mutates = true;
                break;
            }
        };
        if (!mutates) return;

        for (args, 0..) |a, i| {
            if (a == ExprId.none) continue;
            for (args[i + 1 ..]) |b| {
                if (b == ExprId.none) continue;
                var mutation = self.argumentMutation(a, b, lent);
                var other = b;
                if (mutation == ExprId.none) {
                    mutation = self.argumentMutation(b, a, lent);
                    other = a;
                }
                if (mutation == ExprId.none) continue;

                // Which of the mutations it is decides the wording and nothing
                // else: a reader sent to the other argument needs to be told
                // what to look for there.
                const receiver = mutation == lent;
                const marked = receiver or self.ast.exprTag(mutation) == .marked or self.ast.exprTag(mutation) == .call;
                try self.aliased.put(self.gpa, mutation, {});
                _ = self.reportWithOrigin(
                    .n_aliased,
                    other,
                    "this names a place another argument mutates",
                    if (receiver)
                        "already lent as the receiver of this `&` call"
                    else if (self.ast.exprTag(mutation) == .call)
                        "this argument accesses the same place"
                    else if (marked)
                        "already passed `&` here"
                    else
                        "already assigned here",
                    .{
                        .file = self.ast.fileOfExpr(mutation),
                        .span = self.ast.exprSpan(mutation),
                        .message = if (receiver)
                            "mutated as the receiver"
                        else if (marked)
                            "mutated by this argument"
                        else
                            "assigned by this argument",
                        .style = .secondary,
                    },
                );
            }
        }
    }

    /// The mutation inside argument `within` whose place `other` also names,
    /// or none. The lent receiver is itself that mutation where `other` names
    /// its place, as an argument passed `&` is.
    fn argumentMutation(self: *const Checker, within: ExprId, other: ExprId, lent: ExprId) ExprId {
        if (within == lent and self.namesPlace(other, within, false, BindingId.none)) return within;
        return self.sharedMutation(within, other, false, BindingId.none);
    }

    /// The first mutation inside `within` whose place `other` also names.
    ///
    /// A place is mutated two ways -- passed `&`, and assigned to -- and
    /// either sits anywhere inside an argument rather than only at its top.
    /// Exclusivity is about one call's arguments and everything they contain:
    /// `f(g(&p), p)` names one place twice exactly as `f(&p, p)` does, and a
    /// block is an expression, so `f(p, { p.x = 9  0 })` names it twice as
    /// well. What the callee sees would otherwise depend on the order its
    /// arguments happen to be evaluated in.
    /// Whether `other` names `place`, or -- when `any` -- whether anything
    /// would. Asking with `any` is asking whether a mutation is here at all,
    /// which is the same walk over the same nodes and so the same answer to
    /// what counts as one.
    fn namesPlace(
        self: *const Checker,
        other: ExprId,
        place: ExprId,
        any: bool,
        except: BindingId,
    ) bool {
        // A write through the lend itself is the lend being used, not a second
        // path to what it names: `for inout x in xs { x = x * 2 }` is what the
        // form is for. Only a write reaching the same place another way is the
        // fault, so the binder's own writes are passed over here rather than
        // by a second walk that would have to agree with this one.
        if (self.isThroughLend(place, except)) return false;
        if (any) return true;
        // Nothing excluded here: what is walked is the lend's own place, and
        // excluding it would be excluding the very thing being looked for.
        // Which write is passed over was decided above, on the written place.
        return self.mentions(other, place, BindingId.none);
    }

    /// Whether a written place reaches what `lend` names through `lend`
    /// itself: its root is the lend, or a pattern binder whose recorded place
    /// is rooted at the lend, as `let read P { x } = p` is inside a walk
    /// lending `p`. Such a use is the lend being used, not a second path.
    ///
    /// **Bound:** one step per pattern binder in the chain, each of which
    /// names a place bound before it, so the walk ends at a name with no
    /// recorded place; and per binder, one step per pattern it is nested in.
    ///
    /// The root is the name as written, not `placeBase`'s: that resolves a
    /// binder to the place it names, which is exactly what has to be *not*
    /// followed here. `x` in `for inout x in xs` is written as `x` however it
    /// is stored.
    fn isThroughLend(self: *const Checker, place: ExprId, lend: BindingId) bool {
        if (lend == BindingId.none) return false;
        var root = self.res.pathBinding(self.ast, place);
        while (root != BindingId.none) {
            if (root == lend) return true;
            const from = self.binder_places[root.index()] orelse return false;
            root = self.res.pathBinding(self.ast, self.patternRoot(from.of));
        }
        return false;
    }

    /// What a place a binder was recorded against is rooted at, past the
    /// patterns nested between the binder and the value its construct took
    /// apart. Bounded by the pattern's depth.
    fn patternRoot(self: *const Checker, of: ExprId) ExprId {
        var at = of;
        while (self.pattern_places.get(at)) |outer| at = outer.of;
        return at;
    }

    fn sharedMutation(
        self: *const Checker,
        within: ExprId,
        other: ExprId,
        any: bool,
        except: BindingId,
    ) ExprId {
        if (within == ExprId.none) return ExprId.none;
        const tag = self.ast.exprTag(within);

        // A mark's operand is a place, and a place holds no further mutation.
        if (tag == .marked) {
            const place = self.ast.unaryOperand(within);
            return if (self.namesPlace(other, place, any, except)) within else ExprId.none;
        }

        if (tag == .call) {
            const lent = self.lentBy(within);
            if (lent != ExprId.none) {
                if (self.namesPlace(other, lent, any, except)) return within;
            } else {
                const at = self.call_of[within.index()];
                if (at != no_call and self.calls.items[at].callee_convention == .inout) {
                    const callee = self.ast.call(within).callee;
                    if (self.namesPlace(other, callee, any, except)) return within;
                }
            }
        }

        // An assignment's left side is the place it writes, and holds no
        // mutation of its own; its right side is an ordinary expression and
        // may hold one.
        if (tag == .assign) {
            const p = self.ast.binary(within);
            if (self.namesPlace(other, p.lhs, any, except)) return within;
            return self.sharedMutation(p.rhs, other, any, except);
        }

        return switch (tag.payload()) {
            .none => ExprId.none,
            .unary => self.sharedMutation(self.ast.unaryOperand(within), other, any, except),
            .binary => blk: {
                const p = self.ast.binary(within);
                const l = self.sharedMutation(p.lhs, other, any, except);
                break :blk if (l != ExprId.none) l else self.sharedMutation(p.rhs, other, any, except);
            },
            .conditional => blk: {
                const c = self.ast.conditional(within);
                const cond = self.sharedMutation(c.cond, other, any, except);
                if (cond != ExprId.none) break :blk cond;
                const then = self.sharedMutation(c.then, other, any, except);
                break :blk if (then != ExprId.none) then else self.sharedMutation(c.otherwise, other, any, except);
            },
            .call => blk: {
                const c = self.ast.call(within);
                const callee = self.sharedMutation(c.callee, other, any, except);
                if (callee != ExprId.none) break :blk callee;
                for (c.args) |arg| {
                    const found = self.sharedMutation(arg, other, any, except);
                    if (found != ExprId.none) break :blk found;
                }
                break :blk ExprId.none;
            },
            .interpolation => blk: {
                for (self.ast.interpolation(within).pieces) |piece| {
                    const found = self.sharedMutation(piece, other, any, except);
                    if (found != ExprId.none) break :blk found;
                }
                break :blk ExprId.none;
            },
            .lambda => blk: {
                for (self.ast.lambda(within).captures) |capture| {
                    const found = self.sharedMutation(capture.source, other, any, except);
                    if (found != .none) break :blk found;
                }
                for (self.ast.lambda(within).params) |p| {
                    const found = self.sharedMutation(p.default, other, any, except);
                    if (found != ExprId.none) break :blk found;
                }
                break :blk ExprId.none;
            },
            .block => blk: {
                const b = self.ast.blockOf(within);
                for (self.ast.blockStmts(b)) |st| {
                    const found = self.sharedMutation(self.ast.stmtData(st).init, other, any, except);
                    if (found != ExprId.none) break :blk found;
                }
                break :blk self.sharedMutation(b.tail, other, any, except);
            },
            .range => blk: {
                const ends = self.ast.rangeEnds(within);
                const lo = self.sharedMutation(ends.lhs, other, any, except);
                break :blk if (lo != ExprId.none) lo else self.sharedMutation(ends.rhs, other, any, except);
            },
        };
    }

    /// `copy(p)`: a value independent of the place it names.
    ///
    /// Its type is the place's, so a copy is invisible to everything above it.
    /// What it asserts is checked here and in the ownership pass; what it
    /// costs is decided by lowering.
    fn isAPlace(self: *const Checker, operand: ExprId) bool {
        // A constant is held in static storage for the whole program, so it is
        // a place a borrow may observe with no limit, whether it is written
        // bare or reached through a module or a type.
        if (self.res.constantReached(self.ast, operand)) return true;
        var steps = self.ast.placeSteps(operand);
        while (steps.next()) |step| {
            if ((if (self.place_projections.get(step)) |projection| projection.observations > 0 else false) or self.carried_places.contains(step)) return true;
        }
        const at = steps.at;
        if (self.ast.exprTag(at) != .name_ref) return false;
        const binding = self.res.targetOf(at);
        if (binding == .none) return false;
        return switch (self.res.kindOf(binding)) {
            .local, .parameter, .capture, .binder => true,
            else => false,
        };
    }

    fn checkStableArguments(self: *Checker, args: []const ExprId, params: []const types_mod.CallableParam, observations: []const ?types_mod.ReceiverAdjustment) !void {
        for (args, params, 0..) |arg, param, i| {
            if (!param.stable_address or param.convention != .read) continue;
            if (arg == .none) continue;
            if (self.builder.exprType(arg) == .never) continue;
            if (i < observations.len) if (observations[i]) |adjustment| if (adjustment.observations > 0) continue;
            try self.noteBorrowed(arg);
        }
    }

    /// Records a value that is borrowed where it is written. A place,
    /// constants included, is borrowed where it lives; any other value is
    /// evaluated into a temporary that ends with its statement.
    fn noteBorrowed(self: *Checker, value: ExprId) !void {
        if (self.isAPlace(value)) return;
        try self.borrowed_temporaries.put(self.gpa, self.ast.withoutGroups(value), {});
    }

    fn checkBorrow(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const operand = self.ast.unaryOperand(id);
        const referent = try self.check(operand, null);
        if (referent == .poison) return self.record(id, .poison);
        if (!self.isAPlace(operand)) return self.report(.t_lend, id, "an observation requires a place", .{}, "bind the value before borrowing it");
        return self.expect(id, try self.builder.borrowOf(referent), expected);
    }

    fn checkCopy(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const of = self.ast.unaryOperand(id);

        // One of the two positions that use a place whole, marked for exactly
        // the expression it encloses: an operand nested inside this one is a
        // different expression and is not this position.
        const outer = self.whole_place;
        self.whole_place = self.ast.withoutGroups(of);
        defer self.whole_place = outer;

        const t = try self.check(of, expected);
        if (t == .poison) return self.record(id, .poison);
        if (t == .never) return self.expect(id, .never, expected);

        if (self.builder.isScalarSnapshot(t)) {
            return self.report(
                .o_scalar_copy,
                id,
                "`{s}` already produces a scalar snapshot when read",
                .{(try self.typeName(t))},
                "remove `copy` and read the value directly",
            );
        }

        if (!try self.builder.mayCopyWithin(self.generic, t)) {
            // A closure is copyable only as its captures are, so the report
            // names the capture that prevents it.
            if (try self.capturePreventing(t, .copyable)) |capture| return self.report(
                .o_copy,
                id,
                "this closure cannot be copied, because it captures `{s}`, {s} {s} that cannot be copied",
                .{ capture.name, article.before(capture.ty), capture.ty },
                "move the closure, or capture a copyable value instead",
            );
            return self.report(
                .o_copy,
                id,
                "`{s}` does not permit copying",
                .{(try self.typeName(t))},
                "move the value, or declare a copyable representation",
            );
        }

        return self.record(id, t);
    }

    /// `p.x`, or `Colour.Red`.
    ///
    /// A type on the left selects a variant and a value on the left selects a
    /// field. The resolver already answered which, by pointing this at the
    /// enum's symbol where it found one.
    fn namespaceType(self: *const Checker, binding: BindingId) TypeId {
        if (self.res.builtinOf(binding)) |primitive| return primitive;
        if (self.res.kindOf(binding) == .type_parameter) {
            const owner = self.res.typeParameterOwner(binding);
            return self.param_types[owner.index()][self.res.paramIndexOf(binding)];
        }
        return .poison;
    }

    fn checkDereference(self: *Checker, id: ExprId, expected: ?Expected) !TypeId {
        _ = self.selected_places.remove(id);
        _ = self.place_projections.remove(id);
        const base = self.ast.unaryOperand(id);
        const held = try self.check(base, null);
        if (held == .poison or held == .never) return self.expect(id, held, expected);
        const referent = switch (self.builder.get(held)) {
            .borrow => |observation| observation.referent,
            else => return self.report(.t_projection, id, "only an observation has a referent", .{}, "dereference an observation"),
        };
        try self.place_projections.put(self.gpa, id, .{ .base = base, .observations = 1, .receiver = referent });
        try self.readonly_places.put(self.gpa, id, {});
        return self.finishSelection(id, referent, expected);
    }

    fn checkSelection(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        _ = self.selected_places.remove(id);
        _ = self.place_projections.remove(id);
        const base = self.ast.unaryOperand(id);

        if (self.res.integerSelection(id)) |selected| {
            const receiver = self.namespaceType(selected.receiver);
            _ = self.record(base, receiver);
            if (!self.builder.isIntegerWithin(self.generic, receiver)) {
                return self.report(.t_unknown_field, id, "type `{s}` has no integer property `{s}`", .{ (try self.typeName(receiver)), @tagName(selected.endpoint) }, "declare an Integer constraint on the type parameter");
            }
            try self.integer_properties.put(self.gpa, id, .{ .receiver = receiver, .endpoint = selected.endpoint });
            if (selected.endpoint.value(receiver)) |value| {
                self.folds.set(id, .of(.{ .integer = value }));
            } else try self.markNotConstant(id);
            return self.expect(id, receiver, expected);
        }

        if (self.res.targetOf(id) != BindingId.none) {
            const target = self.res.targetOf(id);

            // A constant reached through the type that declares it. A value,
            // so it answers with what it holds and folds where it stands --
            // the same two things a bare name reaching one does, because it is
            // the same binding and only the spelling differs.
            if (self.res.kindOf(target) == .constant) {
                // A traversal is classified as a constant so its expression is
                // checked where every other constant's is, but it is not one:
                // it is the order a walk runs through, read by `for read` and
                // `for inout` and by nothing a program writes. Said here, or
                // the reference reads a type the traversal's own check never
                // recorded and lowering meets it as poison in an accepted
                // program.
                if (self.ast.declTag(self.res.declaredBy(target)) == .traversal_) {
                    return self.report(
                        .t_lend,
                        id,
                        "`{s}` names a traversal, which is walked rather than read",
                        .{self.ast.tokenText(self.ast.declName(self.res.declaredBy(target)))},
                        "walk the type with `for read` or `for inout`",
                    );
                }

                self.noteQualifier(id);
                try self.ensureConstant(target);
                self.folds.set(id, .of(try self.worth(id)));
                const t = self.binding_types.get(target);
                return self.expect(id, t, expected);
            }

            if (try self.selectConstructorValue(id, expected)) |selected| return selected;

            if (self.res.kindOf(target) == .function) {
                if (try self.selectFunctionValue(id, self.res.declaredBy(target), expected, null)) |selected| {
                    self.noteQualifier(id);
                    return selected;
                }
            }

            // Being reached through a namespace does not make a thing a
            // value. `Measure.Item` names what an implementation settled and
            // `Measure.of` names an operation, and neither is something a
            // binding can hold -- the same answer a bare name reaching either
            // gets, because the rule reads what the name reaches and never how
            // it is spelled. Said here rather than left as a type nothing
            // decided: such a type agrees with whatever is written around it,
            // so the program is accepted, runs, and answers.
            //
            // A genuine variant reference settles on its base's own binding
            // -- `Colour.Red` records `Colour` as what `Red` reached, the
            // same binding `Colour` alone would settle on -- so that
            // identity is the whole of what tells a variant apart from a
            // namespace member that merely happens to share its target's
            // kind. `pct.Thing` reaches `Thing` through `pct`, two different
            // bindings, and answers the wider question for the same reason
            // `Measure.Item` and `Measure.of` do: what was found is not what
            // the base itself names.
            const not_a_value = if (self.res.kindOf(target) == .function)
                self.ineligibleFunction(self.res.declaredBy(target))
            else if (target == self.res.throughAlias(self.res.targetOf(base)))
                memberNotAValue(self.res.kindOf(target))
            else
                notAValue(self.res.kindOf(target));
            if (not_a_value) |what| {
                _ = self.record(base, .poison);
                return self.report(
                    .n_not_a_value,
                    id,
                    "`{s}` is {s}, and {s} is not a value",
                    .{ self.ast.tokenText(self.ast.exprMain(id)), what.noun, what.noun },
                    what.hint,
                );
            }

            const d = self.res.declaredBy(target);
            const t = try self.aliasVariantType(id, base, expected) orelse self.instanceFor(d, expected) orelse
                return self.reportWrongInstance(id, d, expected);
            if (t == .poison) return self.record(id, .poison);
            // The left side names the type rather than a value, and every
            // expression ends with exactly one type.
            self.noteQualifier(id);
            _ = self.record(base, t);
            if (self.buildsSealedVariant(t, self.variantOrdinal(id)))
                return self.reportSealed(id, t, "only its own module can build one");
            if (self.variantOrdinal(id)) |ordinal| if (self.missingPayload(id, t, ordinal, expected)) |refused| return refused;
            return self.foldVariantReference(id, try self.expect(id, t, expected));
        }

        // What a name is selected from is not the value position: a namespace
        // is a legitimate thing to select from, so [N-NotAValue] is not the
        // rule here and the base is not checked as a value. Which name a
        // namespace holds is the resolver's question and it reported its own
        // answer, so a selection that reached nothing has already been said.
        //
        // Function values have no namespace. Type-parameter members depend
        // on checked constraints, so the resolver also leaves those for this
        // pass. Both need a diagnostic before recording a poisoned selection.
        //
        // A qualified base -- `pct.Thing` reached through a module, itself a
        // `.field` node -- names a namespace exactly as a bare name does, so
        // the same rule reads it: recursing into `check` below would report
        // [N-NotAValue] on a base whose own selection already said what is
        // wrong, or that the resolver or the parser already reported.
        if (self.ast.exprTag(base) == .name_ref or self.ast.exprTag(base) == .field) {
            const b = self.res.targetOf(base);
            if (b != BindingId.none and !resolve_mod.baseNamesAValue(self.res, self.ast, base)) {
                if (self.res.selectsThroughTrait(id)) return self.checkValueThroughType(id, expected);
                if (self.res.kindOf(b) == .type_parameter) {
                    _ = self.record(base, self.namespaceType(b));
                    return self.report(
                        .t_unknown_field,
                        id,
                        "type parameter `{s}` has no member `{s}`",
                        .{ self.ast.tokenText(self.ast.exprMain(base)), self.ast.tokenText(self.ast.exprMain(id)) },
                        "the declared constraints do not provide this member",
                    );
                }
                if (self.res.kindOf(b) == .function) {
                    return self.report(
                        .t_unknown_field,
                        base,
                        "`{s}` is a function, and a function has no parts",
                        .{self.ast.tokenText(self.ast.exprMain(base))},
                        "nothing to select from",
                    );
                }
                // The type named is recorded, so an editor asking what may
                // follow the dot reads the trait operations the type reaches.
                const named = if (self.res.kindOf(b) == .declared_type and self.ast.declTypeParams(self.res.declaredBy(b)).len == 0)
                    self.type_of_decl.get(self.res.declaredBy(b))
                else
                    self.namespaceType(b);
                _ = self.record(base, named);
                return self.record(id, .poison);
            }
        }

        var of = try self.checkReceiver(ExprId.none, base, self.ast.tokenName(self.ast.exprMain(id)), null);
        if (of == .poison) {
            // Whether a call on a value of no known type reaches an
            // operation cannot be decided, so a free function its name
            // reaches is taken as named rather than reported unused on the
            // strength of an error already reported.
            if (id == self.callee) if (self.res.postfixFunction(id)) |named| try self.notePostfixFunctionNamed(named);
            return self.record(id, .poison);
        }
        if (of == .never) return self.expect(id, .never, expected);

        // A `.` with nothing after it. The parser said so where the name
        // belongs, and naming the token that stands there as a field nobody
        // declared would describe one mistake twice.
        if (self.ast.tokenTag(self.ast.exprMain(id)) != .identifier) {
            return self.record(id, .poison);
        }

        // A field is read through an observation, so the type the field
        // is looked up on is the one the observations reach; an operation is
        // held to the receiver as the call passes it.
        const passed = of;
        const adjustment = self.builder.view().observedReceiver(of);
        of = adjustment.receiver;

        const name = self.ast.tokenText(self.ast.exprMain(id));

        const wanted = self.ast.tokenName(self.ast.exprMain(id));
        const field = self.builder.lookupField(of, name);
        var declaring: std.ArrayList(node.DeclId) = .empty;
        defer declaring.deinit(self.gpa);
        // A selection reaches a field, and the callee of a postfix call reaches
        // an operation and never a field. The postfix call already found no
        // operation it could take, so the callee is refused here for why: a
        // trait out of scope, the type's own operation out of the call's
        // reach, or no operation at all. Anywhere else the name is a field the
        // type lacks, so no trait is looked for and no call-shaped advice is
        // given.
        const callee = id == self.callee;
        if (callee) {
            // One walk of the trait names prepares every trait declaring the
            // name, in scope or not, and collects those in scope.
            try self.prepareNamedLookup(of, wanted, true, .operation, &declaring);

            // An operation a trait in scope declares, whose implementation for
            // this type asks for more than the type's arguments give it, is the
            // mistake here, whatever the type's parts are.
            const prepared = try self.builder.capabilityView();
            const unmet = try self.reaching(&prepared).unmetImplementation(self.gpa, of, wanted, declaring.items);
            if (unmet != node.DeclId.none) {
                // Unless what it asks for is a demand a bound refusal reported
                // unmet: then the missing implementation follows from that.
                if (try self.refusalExplains(unmet, of)) return self.record(id, .poison);
                try self.reportUnimplemented(
                    self.ast.fileOfExpr(id),
                    self.ast.exprSpan(id),
                    "its implementation's bounds are not met by this type's arguments",
                    "`{s}` comes from `{s}`, and `{s}` does not implement it",
                    .{ name, self.ast.tokenText(self.ast.declName(unmet)), (try self.typeName(of)) },
                    unmet,
                    &.{},
                    of,
                );
                return self.record(id, .poison);
            }
        }

        // A selection naming an operation the type declares, or one a trait
        // in scope declares, is looking for that operation, which has nothing
        // to do with the type's parts: saying they are sealed would send a
        // reader to the representation for a function value. It is reported
        // below as it is for any type.
        if (!callee and self.sealedHere(of)) {
            const names_an_operation = field == null and (self.aTraitInScopeDeclares(wanted) or
                try self.reaching(&(try self.builder.capabilityView())).ownDeclared(self.gpa, passed, wanted) != null);
            if (!names_an_operation) return self.reportSealed(id, of, "only its own module can read its parts");
        }

        if (!callee) if (field) |found| {
            try self.field_names.put(self.gpa, self.ast.exprMain(id), .{ .receiver = of, .field = @enumFromInt(found.index) });
            try self.place_projections.put(self.gpa, id, .{ .base = base, .observations = adjustment.observations, .receiver = of, .field = @enumFromInt(found.index) });
            if (adjustment.observations > 0) try self.readonly_places.put(self.gpa, id, {});
            return self.finishSelection(id, found.ty, expected);
        };

        const pool = try self.builder.capabilityView();
        if (callee) {
            // A name that is not a field may still be an operation the type
            // answers to, reached through a trait this module cannot see.
            // Saying the type has no such field is true of its fields and
            // false of the type, and leaves a reader looking for a spelling
            // mistake in a name that is spelled right. So the trait is named,
            // and with it the line that would bring it into scope -- which is
            // worth saying because the trait's name appears nowhere in the
            // source: what is missing cannot be found by reading what is
            // there. The walk above prepared it.
            const declared = try self.reaching(&pool).elsewhere(self.gpa, of, wanted);
            if (declared != node.DeclId.none) {
                return self.reportOutOfScope(id, name, declared);
            }

            // The type may declare the name itself as an operation the call
            // could not take. That the type has no such field is true of its
            // fields and false of the type, so the declaration says why.
            if (try self.reaching(&pool).ownDropped(self.gpa, passed, wanted)) |dropped| {
                return self.reportDropped(id, passed, dropped);
            }
            if (field == null) if (self.res.postfixFunction(id)) |named| return self.reportFreeFunctionCall(id, base, of, named);
            return self.reportNoOperation(id, of, name, if (field) |found| found.ty else null, if (declaring.items.len != 0) declaring.items[0] else .none);
        } else if (try self.reaching(&pool).ownDeclared(self.gpa, passed, wanted)) |own| {
            // The type declares the name as an operation, which is a function
            // where one is expected -- reached through the type's own name,
            // written as this module can write it -- and a method's receiver
            // is then its first parameter.
            const owner = self.ast.tokenText(self.ast.declOwner(own.sig));
            const path = try self.pathToType(owner, of);
            return self.report(
                .t_unknown_field,
                id,
                "`{s}` has no field `{s}`",
                .{ (try self.typeName(of)), name },
                if (own.takes_receiver)
                    try std.fmt.allocPrint(self.gpa, "`{s}` is an operation of `{s}`, not a field; where a function is expected, write `{s}.{s}`, which takes the receiver as its first argument", .{ name, owner, path, name })
                else
                    try std.fmt.allocPrint(self.gpa, "`{s}` is an operation of `{s}`, not a field; where a function is expected, write `{s}.{s}`", .{ name, owner, path, name }),
            );
        }

        return self.report(
            .t_unknown_field,
            id,
            "`{s}` has no field `{s}`",
            .{ (try self.typeName(of)), name },
            "not a field of this value",
        );
    }

    /// A postfix call whose type declares no operation under the call's name
    /// and whose visible traits declare none for it.
    ///
    /// A field of that name is not reached by the call. Where the type has
    /// one, the report says so; where it holds a callable value, the help
    /// spells the call that reaches it, the selection in parentheses. A sealed
    /// field is not mentioned outside its module, which cannot read it.
    /// Otherwise a trait in scope that declares the name for other receivers,
    /// `declaring`, is named, since its operation is what the call was
    /// written against.
    fn reportNoOperation(self: *Checker, id: ExprId, of: TypeId, name: []const u8, field: ?TypeId, declaring: node.DeclId) std.mem.Allocator.Error!TypeId {
        // A trait declaring the name whose implementation for this type
        // fails only on demands a bound refusal reported follows from that
        // refusal.
        if (try self.refusalExplains(declaring, of)) return self.record(id, .poison);
        // An implementation refused for its alias head declares this name,
        // and that refusal was the report.
        if (self.res.refused_operations.contains(self.ast.tokenName(self.ast.exprMain(id)))) return self.record(id, .poison);
        const visible = if (self.sealedHere(of)) null else field;
        const missing = visible == null and declaring != .none and !try self.answersDeclared(of, declaring);
        const help: []const u8 = if (visible) |held| help: {
            if (!self.holdsACallable(held))
                break :help try std.fmt.allocPrint(self.gpa, "`{s}` is a field holding `{s}`, and a call does not reach a field", .{ name, (try self.typeName(held)) });
            break :help try std.fmt.allocPrint(self.gpa, "`{s}` is a field; to call the function it holds, write `({s})(...)`", .{ name, self.ast.exprText(id) });
        } else if (declaring != .none) help: {
            const trait_name = self.ast.tokenText(self.ast.declName(declaring));
            // Where the receiver's type implements the trait, the operation is
            // one this receiver cannot take, such as a mutating one through an
            // observation; otherwise the missing implementation is the reason.
            if (try self.answersDeclared(of, declaring))
                break :help try std.fmt.allocPrint(self.gpa, "`{s}` declares it, but not for this receiver", .{trait_name});
            // A collection that does not implement the trait may offer a view
            // that does, as a `Vec` and an array offer their elements as a
            // slice; naming the view is the step the call is missing.
            if (try self.viewImplementing(of, declaring)) {
                const receiver = self.ast.exprText(self.ast.unaryOperand(id));
                break :help try std.fmt.allocPrint(self.gpa, "`{s}` declares it, and `{s}` does not implement `{s}`; `{s}.as_slice()` does", .{ trait_name, (try self.typeName(of)), trait_name, receiver });
            }
            break :help try std.fmt.allocPrint(self.gpa, "`{s}` declares it, and `{s}` does not implement `{s}`", .{ trait_name, (try self.typeName(of)), trait_name });
        } else "no operation of this name is declared for this type";
        const before = self.sink.items().len;
        const reported = self.report(
            .t_unknown_operation,
            id,
            "`{s}` has no operation `{s}`",
            .{ (try self.typeName(of)), name },
            help,
        );
        if (missing) try self.explainMissing(before, declaring, of);
        return reported;
    }

    /// Whether `of` lacks `trait` only because of demands a bound refusal
    /// already reported, so a report of the missing implementation would
    /// restate that refusal. The trait is asked at no arguments: for a trait
    /// that takes some, no implementation is keyed that way, so the answer is
    /// that nothing explains the report, and it is made.
    fn refusalExplains(self: *Checker, trait: node.DeclId, of: TypeId) std.mem.Allocator.Error!bool {
        return self.builder.explainedByRefusal(self.generic, trait, &.{}, of, &self.refused_demands);
    }

    test "a refusal explains a missing implementation that fails only on what it reported" {
        const shared =
            \\trait Shout { fn shout(_self: Self) -> UInt8 }
            \\struct Pair { left: UInt8 }
            \\struct Box[T] { item: T }
            \\impl[T: Copyable] Shout for Box[T] { fn shout(_self: Self) -> UInt8 { 1 } }
            \\fn keep[T: Copyable](sink value: T) -> Box[T] where carries(value) { .{ item = value } }
            \\
        ;
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        // The bound refuses `Pair` for `Copyable`; `Box[Pair]` lacks `Shout`
        // for that alone, and only the bound is reported.
        try testing.expectEqual(@as(u32, 1), try checkSource(arena.allocator(), shared ++
            \\fn main() -> UInt8 { let p: Pair = .{ left = 1 }; keep(p).shout() }
        ));
        // A `Box[Pair]` built without the refused call lacks `Shout` for the
        // same reason, and nothing was refused, so the implementation is
        // reported.
        try testing.expectEqual(@as(u32, 1), try checkSource(arena.allocator(), shared ++
            \\fn main() -> UInt8 { let b: Box[Pair] = .{ item = .{ left = 1 } }; b.shout() }
        ));
    }

    test "a refusal explains no implementation failing on a demand it did not report" {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        // `Lookup[Bool]` refused for `Board` says nothing about `Lookup[UInt8]`.
        try testing.expectEqual(@as(u32, 2), try checkSource(arena.allocator(),
            \\trait Lookup[I] { fn at(self: Self, i: I) -> UInt8 }
            \\trait Shout { fn shout(_self: Self) -> UInt8 }
            \\@copyable
            \\struct Board { cells: UInt8 }
            \\struct Box[T] { item: T }
            \\impl[T: Lookup[UInt8]] Shout for Box[T] { fn shout(_self: Self) -> UInt8 { 1 } }
            \\fn find[C: Lookup[Bool]](c: C) -> UInt8 { Lookup.at(c, true) }
            \\fn main() -> UInt8 {
            \\    let board = Board { cells = 1 }
            \\    let boxed: Box[Board] = .{ item = board }
            \\    find(board) + boxed.shout()
            \\}
        ));
        // `Pair` refused for `Copyable` says nothing about a closure whose
        // signature the implementation also requires.
        try testing.expectEqual(@as(u32, 2), try checkSource(arena.allocator(),
            \\trait Shout { fn shout(_self: Self) -> UInt8 }
            \\struct Pair { left: UInt8 }
            \\struct Holder[T, F] { item: T, check: F }
            \\impl[T: Copyable, F: fn(value: T) -> Bool] Shout for Holder[T, F] { fn shout(_self: Self) -> UInt8 { 1 } }
            \\fn keep[T: Copyable](sink value: T) -> T { value }
            \\fn hold[T, F](sink item: T, sink check: F) -> Holder[T, F] where carries(item, check) { .{ item = item, check = check } }
            \\fn main() -> UInt8 {
            \\    let p: Pair = .{ left = 1 }
            \\    let Pair { left } = keep(p)
            \\    let held = hold(Pair { left = 3 }, |value: UInt8| value > 2)
            \\    left + held.shout()
            \\}
        ));
    }

    test "a refused trait demand's arguments are freed with the checker" {
        // Under the testing allocator, an argument slice a demand still held
        // after the check would be reported as a leak.
        const gpa = testing.allocator;
        var arena = std.heap.ArenaAllocator.init(gpa);
        defer arena.deinit();
        var sink = Sink.init(arena.allocator());
        const source: Source = .{ .path = "t.lin", .text =
            \\trait Lookup[I] { fn at(self: Self, i: I) -> UInt8 }
            \\@copyable
            \\struct Board { cells: UInt8 }
            \\fn find[C: Lookup[Bool]](c: C) -> UInt8 { Lookup.at(c, true) }
            \\fn main() -> UInt8 { find(Board { cells = 1 }) }
        };
        var interner: Interner = .empty;
        defer interner.deinit(gpa);
        const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
        var ast = try parse(gpa, &source, .from(0), tokens, &sink);
        defer ast.deinit(gpa);
        var resolved = try resolveTree(gpa, &ast, &sink);
        defer resolved.deinit(gpa);
        const before = sink.error_count;
        var typing = try typecheckTree(gpa, &resolved, &sink);
        defer typing.deinit(gpa);
        try testing.expectEqual(@as(u32, 1), sink.error_count - before);
    }

    /// Whether `of` offers an `as_slice` view that implements `trait`: an
    /// array's slice view, or the result of an operation of `of`'s own named
    /// `as_slice` that takes only the receiver, read at `of`.
    ///
    /// **Bound:** the operations `of`'s declaration holds, once each; asked
    /// only while reporting.
    fn viewImplementing(self: *Checker, of: TypeId, trait: node.DeclId) std.mem.Allocator.Error!bool {
        if (self.builder.get(of) == .array) {
            const slice = try self.builder.arrayViewOf(of) orelse return false;
            return self.answersDeclared(slice, trait);
        }
        return self.operationImplementing(of, "as_slice", trait);
    }

    /// Whether an operation of `of`'s own named `name`, taking only the
    /// receiver, returns a value that implements `trait` when read at `of`.
    ///
    /// **Bound:** the operations `of`'s declaration holds, once each; asked
    /// only while reporting.
    fn operationImplementing(self: *Checker, of: TypeId, name: []const u8, trait: node.DeclId) std.mem.Allocator.Error!bool {
        const origin = self.builder.view().declOfType(of) orelse return false;
        var members = self.res.membersOfType(origin);
        while (members.next()) |b| {
            const sig = self.res.declaredBy(b);
            if (!std.mem.eql(u8, self.ast.tokenText(self.ast.declName(sig)), name)) continue;
            if (self.ast.declParams(sig).len != 1 or self.ast.declTypeParams(sig).len != 0) continue;
            const over = self.headParametersOf(sig);
            const head = try self.gpa.alloc(TypeId, if (over == node.DeclId.none) 0 else self.ast.declTypeParams(over).len);
            defer self.gpa.free(head);
            @memset(head, .poison);
            var ignored: ?Clash = null;
            if (over != node.DeclId.none) _ = try self.settle(try paramType(self, sig, 0), of, over, head, &ignored);
            const offered = try self.throughCall(try returnType(self, sig), sig, over, .{ .head = head });
            if (offered != .poison and try self.answersDeclared(offered, trait)) return true;
        }
        return false;
    }

    /// Whether a value of `ty` can be called: a closure, a function value, or
    /// a type parameter whose bounds give it one callable signature.
    fn holdsACallable(self: *Checker, ty: TypeId) bool {
        switch (self.builder.get(ty)) {
            .closure, .callable => return true,
            else => {},
        }
        const bounds = self.builder.callableBoundsOn(ty);
        if (bounds.len == 1) return true;
        return bounds.len == 0 and self.contextual_constraints.singleCallable(self.generic, ty) != null;
    }

    /// Reports the functions and imports the resolver left for this pass:
    /// nothing used them apart from postfix calls whose names reach them. Such
    /// a call that reached no operation was refused as naming a free function,
    /// which is a use of it; one that reached an operation did not name the
    /// function at all. So what every such call left unnamed is unused, and
    /// is reported as the resolver reports anything nothing names.
    fn reportDeferredUnused(self: *Checker) std.mem.Allocator.Error!void {
        for (self.res.deferred_unused) |b| {
            if (self.named_postfix_functions.contains(b)) continue;
            try resolve_mod.reportUnused(self.sink, self.ast, self.res.declaringToken(b), self.res.kindOf(b), self.res.isReExport(b));
        }
    }

    /// Reports the `let` bindings lent with `&` whose mark met no parameter,
    /// such as one on a call to an operation that does not exist.
    fn reportDeferredImmutable(self: *Checker) std.mem.Allocator.Error!void {
        for (self.res.deferred_immutable) |lent| {
            if (self.decided_marks.contains(lent.mark)) continue;
            try resolve_mod.reportImmutableBinding(self.sink, self.ast, lent.name, self.res.kindOf(lent.binding), self.res.declaringToken(lent.binding));
        }
    }

    /// Settles a `&` mark where it meets its parameter: lent to an `inout`
    /// parameter, a `let` it lends is reported there, in source order with
    /// what surrounds it; refused, the `&` is the one report. A mark no
    /// parameter ever meets is left for `reportDeferredImmutable`.
    fn decideMark(self: *Checker, mark: ExprId, how: enum { lent, refused }) std.mem.Allocator.Error!void {
        const entry = try self.decided_marks.getOrPut(self.gpa, mark);
        if (entry.found_existing) return;
        if (how == .refused) return;
        const at = self.deferred_marks.get(mark) orelse return;
        const lent = self.res.deferred_immutable[at];
        try resolve_mod.reportImmutableBinding(self.sink, self.ast, lent.name, self.res.kindOf(lent.binding), self.res.declaringToken(lent.binding));
    }

    /// Records that a postfix call named a free function and the import it is
    /// reached through, so neither is reported unused.
    fn notePostfixFunctionNamed(self: *Checker, named: resolve_mod.Resolution.PostfixFunction) std.mem.Allocator.Error!void {
        try self.named_postfix_functions.put(self.gpa, named.function, {});
        if (named.through != BindingId.none and !named.shadowed) try self.named_postfix_functions.put(self.gpa, named.through, {});
    }

    /// Reports a postfix call whose name reaches a free function and no
    /// operation: a free function is not an operation of any type.
    ///
    /// The call that runs the function is suggested only where the function's
    /// first parameter takes the value, so the suggestion type-checks. The
    /// function, and the import it is reached through, are what the call
    /// named, so neither is then reported unused.
    fn reportFreeFunctionCall(self: *Checker, id: ExprId, base: ExprId, of: TypeId, named: resolve_mod.Resolution.PostfixFunction) std.mem.Allocator.Error!TypeId {
        try self.notePostfixFunctionNamed(named);
        const arena = self.sink.arena;
        const function = self.ast.tokenText(self.res.declaringToken(named.function));
        const pool = self.builder.view();
        const type_name = try writtenTypeName(arena, self.ast, self.program, self.res, &pool, self.current, of);
        const declared = self.res.declaredBy(named.function);
        const bindings = try self.gpa.alloc(TypeId, self.ast.declTypeParams(declared).len);
        defer self.gpa.free(bindings);
        // The call form is suggested where the first parameter takes the
        // value and, where that settles every type parameter, the settled
        // arguments meet the function's bounds -- the check the suggested
        // call would itself be held to. A parameter the value does not settle
        // is settled by the other arguments, which the suggestion leaves out.
        const takes = self.reaching(&(try self.builder.capabilityView())).freeFunctionTakes(declared, of, bindings) and
            (std.mem.indexOfScalar(TypeId, bindings, .poison) != null or try self.argumentsMeetBounds(declared, bindings));
        const label = if (takes and named.shadowed) label: {
            const imported = self.res.declaringToken(named.through);
            const path = self.importedPath(imported) orelse self.ast.tokenText(imported);
            break :label try std.fmt.allocPrint(arena, "`{s}` is shadowed here; write `import {s} as` another name and call `{s}` through it", .{ self.ast.tokenText(imported), path, function });
        } else if (takes) label: {
            const qualifier = if (named.through == BindingId.none) "" else try std.fmt.allocPrint(arena, "{s}.", .{self.ast.tokenText(self.res.declaringToken(named.through))});
            const receiver = self.ast.exprText(base);
            const written = if (receiver.len <= 40 and std.mem.indexOfScalar(u8, receiver, '\n') == null) receiver else "…";
            break :label try std.fmt.allocPrint(arena, "call it as `{s}{s}({s}{s})`", .{ qualifier, function, written, if (self.callee_arguments > 0) ", …" else "" });
        } else "a dot calls an operation of the value, and a free function is not one";
        return self.report(
            .t_unknown_operation,
            id,
            "`{s}` is a function, not an operation of `{s}`",
            .{ function, type_name },
            label,
        );
    }

    /// Whether a trait this module can name declares `name` as an operation
    /// a postfix call passes its receiver to. Reads the rows the resolver
    /// indexed under this module and name, so it costs what those traits
    /// declare under the name.
    fn aTraitInScopeDeclares(self: *const Checker, name: StringId) bool {
        var rows = self.res.traitMembersNamed(self.current, name);
        while (rows.next()) |row| {
            if (postfixReaches(self.ast, row.member)) return true;
        }
        return false;
    }

    /// Why a postfix call could not take the operation the type declares
    /// under the call's name: out of this module's reach, under the rule a
    /// written path is held to; taking no argument at all, so nothing can be
    /// passed as the receiver; or taking something other than the receiver,
    /// reported as the mismatch the written call `Door.close(door)` makes,
    /// at the parameter that says what it takes.
    fn reportDropped(self: *Checker, id: ExprId, passed: TypeId, dropped: Reach.Dropped) std.mem.Allocator.Error!TypeId {
        const written = self.ast.exprMain(id);
        switch (dropped.why) {
            .inaccessible => |reach| {
                try resolve_mod.reportUnreachableName(self.sink, self.ast, written, self.program.get(self.program.moduleOf(dropped.sig)).name, reach);
                return self.record(id, .poison);
            },
            .receiver => {},
        }
        const params = self.ast.declParams(dropped.sig);
        if (params.len == 0) {
            return self.report(
                .t_arity,
                id,
                "`{s}.{s}` takes no arguments",
                .{ self.ast.tokenText(self.ast.declOwner(dropped.sig)), self.ast.tokenText(written) },
                "a postfix call passes its receiver as the first argument",
            );
        }
        // A signature that did not check was reported where it was declared,
        // and a call the head refuses adds nothing to that.
        const callable = switch (self.builder.get(self.decl_signatures.get(dropped.sig))) {
            .callable => |callable| callable,
            else => return self.record(id, .poison),
        };
        const first = self.builder.callableParams(callable)[0];
        _ = self.reportMismatch(self.ast.withoutGroups(self.ast.unaryOperand(id)), passed, .{
            .ty = first.ty,
            .at = .{ .file = self.ast.fileOf(params[0].name), .span = self.ast.tokenSpan(params[0].name) },
            .reason = .parameter,
        }, "");
        return self.record(id, .poison);
    }

    /// The type-parameter lists a function named as a value is written over:
    /// its own, with a trait operation's `Self` after them where its signature
    /// places it; the head of the generic inherent implementation it belongs
    /// to; and the parameters of the trait declaring it. Every list is settled
    /// by the same matching, so a value selects one body by one routine walked
    /// once per list.
    const ValueLists = struct {
        function: node.DeclId,
        /// The function's own parameters, counting a trait operation's `Self`.
        own: usize,
        head: node.DeclId,
        /// The trait declaring a trait operation, or none.
        trait: node.DeclId,

        fn owners(lists: ValueLists) [3]node.DeclId {
            return .{ lists.function, lists.head, lists.trait };
        }
    };

    fn valueLists(self: *const Checker, d: node.DeclId) ValueLists {
        const trait = if (self.ast.declIsTraitMember(d)) self.traitDeclaring(d) orelse node.DeclId.none else node.DeclId.none;
        return .{
            .function = d,
            .own = self.ast.declTypeParams(d).len + @intFromBool(trait != node.DeclId.none),
            .head = self.headParametersOf(d),
            .trait = trait,
        };
    }

    /// How many parameters list `k` of `lists` holds.
    fn valueListLen(self: *const Checker, lists: ValueLists, k: usize) usize {
        if (k == 0) return lists.own;
        const owner = lists.owners()[k];
        return if (owner == node.DeclId.none) 0 else self.ast.declTypeParams(owner).len;
    }

    /// The name of parameter `i` of list `k`, as a diagnostic spells it.
    fn valueParameterName(self: *const Checker, lists: ValueLists, k: usize, i: usize) []const u8 {
        const parameters = self.ast.declTypeParams(lists.owners()[k]);
        return if (i < parameters.len) self.ast.tokenText(parameters[i].name) else "Self";
    }

    /// A signature written over the lists, read through what each settled to.
    fn throughValue(self: *Checker, ty: TypeId, lists: ValueLists, settled: [3][]const TypeId) std.mem.Allocator.Error!TypeId {
        const through = try self.throughCall(ty, lists.function, lists.head, .{ .own = settled[0], .head = settled[1] });
        return self.throughTrait(through, lists.trait, settled[2]);
    }

    /// Where the body of a value is found: the trait and `Self` a trait
    /// operation was settled at, or the receiver a member of a generic
    /// inherent implementation was selected for. The same record a call to the
    /// declaration makes, so the two find one body by one lookup.
    fn valueImplementation(self: *Checker, id: ExprId, lists: ValueLists, settled: [3][]const TypeId) std.mem.Allocator.Error!?types_mod.CallImpl {
        if (lists.trait != node.DeclId.none) return .{
            .call = @intCast(id.index()),
            .trait = @intCast(lists.trait.index()),
            .args = settled[2],
            .self_ty = settled[0][lists.own - 1],
        };
        if (lists.head != node.DeclId.none) return .{
            .call = @intCast(id.index()),
            .trait = types_mod.Implementation.no_trait,
            .self_ty = try self.settledHead(lists.head, settled[1]) orelse TypeId.poison,
        };
        return null;
    }

    fn labelSources(self: *const Checker) LabelSources {
        return .{
            .ast = self.ast,
            .res = self.res,
            .typing = self.builder.view(),
            .binding_types = &self.binding_types,
            .field_names = &self.field_names,
            .binding_labels = &self.binding_labels,
        };
    }

    fn calleeLabels(self: *const Checker, callee: ExprId) ?[]const node.Param {
        return self.labelSources().ofCallee(callee);
    }

    /// A fresh open type for a parameter a function value leaves to its uses.
    fn openParameter(self: *Checker) std.mem.Allocator.Error!TypeId {
        const v = try self.open_types.createType(self.gpa);
        const t = try self.builder.openType(v);
        self.open_types.name(v, t);
        return t;
    }

    /// Selects the declaration a function name reaches as a value, or returns
    /// null where the name is not one.
    ///
    /// Where one exact structural signature flows in, it settles every list
    /// now. Where none does, each parameter becomes an open type for the
    /// value's later uses to settle, through the same meeting of types the rest
    /// of the body uses, and the value's bounds are checked when its body
    /// closes. A function with no parameters is its declared signature.
    fn selectFunctionValue(
        self: *Checker,
        id: ExprId,
        d: node.DeclId,
        expected: ?Expected,
        /// The type a trait's operation was named through, `Limits.default`,
        /// which is its `Self` rather than a parameter its uses settle.
        written_self: ?TypeId,
    ) std.mem.Allocator.Error!?TypeId {
        return self.selectFunctionValueWith(id, d, expected, written_self, &.{});
    }

    /// `selectFunctionValue`, with the function's own type parameters named
    /// in brackets, `create[UInt8]`, and so settled before any use.
    fn selectFunctionValueWith(
        self: *Checker,
        id: ExprId,
        d: node.DeclId,
        expected: ?Expected,
        written_self: ?TypeId,
        written: []const TypeId,
    ) std.mem.Allocator.Error!?TypeId {
        if (self.ineligibleFunction(d) != null) return null;
        const lists = self.valueLists(d);
        if (self.ast.declIsTraitMember(d) and lists.trait == node.DeclId.none) return null;
        // `Self` is the last of the function's own list.
        const self_slot: ?usize = if (written_self != null and lists.trait != node.DeclId.none) lists.own - 1 else null;
        try self.ensureSignature(d);
        const declared = self.decl_signatures.get(d);
        if (declared == .poison) return self.record(id, .poison);

        const context: ?Expected = if (expected) |want|
            if (self.builder.get(want.ty) == .callable) want else null
        else
            null;

        var found: [3][]TypeId = undefined;
        var allocated: usize = 0;
        defer for (found[0..allocated]) |list| self.gpa.free(list);
        for (&found, 0..) |*list, k| {
            list.* = try self.gpa.alloc(TypeId, self.valueListLen(lists, k));
            allocated += 1;
            @memset(list.*, .poison);
        }
        var open = false;
        if (self_slot) |slot| found[0][slot] = written_self.?;
        @memcpy(found[0][0..written.len], written);
        if (context) |want| {
            for (lists.owners(), found, 0..) |owner, list, k| {
                if (owner == node.DeclId.none or list.len == 0) continue;
                var clash: ?Clash = null;
                if (!try self.settleSignatureTypes(declared, want.ty, owner, list, &clash)) {
                    const conflict = clash.?;
                    return self.report(
                        .t_mismatch,
                        id,
                        "`{s}` would be both `{s}` and `{s}` under this callable signature",
                        .{
                            self.valueParameterName(lists, k, conflict.index),
                            (try self.typeName(conflict.was)),
                            (try self.typeName(conflict.got)),
                        },
                        "the expected signature does not select one instantiation",
                    );
                }
                for (list, 0..) |ty, i| {
                    if (ty != .poison) continue;
                    return self.report(
                        .t_infer,
                        id,
                        "the expected callable signature does not say what `{s}` is",
                        .{self.valueParameterName(lists, k, i)},
                        "no value represents an unselected function family",
                    );
                }
            }
        } else for (found, 0..) |list, k| for (list, 0..) |*ty, i| {
            if (k == 0 and (self_slot == i or i < written.len)) continue;
            ty.* = try self.openParameter();
            open = true;
        };

        const settled: [3][]const TypeId = .{ found[0], found[1], found[2] };
        if (!open and !try self.valueMeetsBounds(id, lists, settled)) return self.record(id, .poison);

        const signature = try self.throughValue(declared, lists, settled);
        var converted = signature;
        if (context) |want| {
            const fits = if (want.callable_context)
                self.builder.view().callableSatisfies(signature, want.ty)
            else
                self.builder.view().callableConverts(signature, want.ty);
            if (!fits) return self.reportMismatch(id, signature, want, "");
            if (!want.callable_context) converted = want.ty;
        }

        var implementation = try self.valueImplementation(id, lists, settled);
        const generics = self.ast.declTypeParams(d).len;
        const type_args = if (generics == 0) &.{} else try self.gpa.dupe(TypeId, found[0][0..generics]);
        errdefer if (type_args.len > 0) self.gpa.free(type_args);
        if (implementation) |*rec| if (rec.args.len > 0) {
            rec.args = try self.gpa.dupe(TypeId, rec.args);
        };
        errdefer if (implementation) |rec| if (rec.args.len > 0) self.gpa.free(rec.args);
        const value: u32 = @intCast(self.function_values.items.len);
        try self.function_values.append(self.gpa, .{
            .at = id,
            .target = .{ .declared = d },
            .signature = converted,
            .type_args = type_args,
            .implementation = implementation,
        });

        if (open) {
            var parameters: [3][]TypeId = .{ &.{}, &.{}, &.{} };
            errdefer for (parameters) |list| if (list.len > 0) self.gpa.free(list);
            for (&parameters, found) |*into, list| {
                if (list.len > 0) into.* = try self.gpa.dupe(TypeId, list);
            }
            try self.pending_values.append(self.gpa, .{ .value = value, .lists = lists, .parameters = parameters });
        }
        if (context != null) return self.record(id, converted);
        return try self.expect(id, signature, expected);
    }

    /// A function a name reaches that is not a value, and what to call it:
    /// a test is run only by the compiler, an `extern` has no body in this
    /// program to take the address of, and a projection names a place rather
    /// than computing a value.
    fn ineligibleFunction(self: *const Checker, d: node.DeclId) ?NotAValue {
        switch (self.ast.declTag(d)) {
            .function => {},
            .projection => return .{ .noun = "a projection", .hint = "reach the place it names through a bracket" },
            else => return notAValue(.function),
        }
        if (self.ast.declIsTest(d)) return .{ .noun = "a test", .hint = "a test is run by `linea test`, never named" };
        if (self.ast.declIsExtern(d)) return .{ .noun = "an `extern`", .hint = "call it; its body is outside this program" };
        return null;
    }

    /// Whether a value's settled parameters meet their bounds, and a trait
    /// operation's `Self` has an implementation whose body the value can name.
    /// Reports what is unmet.
    fn valueMeetsBounds(self: *Checker, id: ExprId, lists: ValueLists, settled: [3][]const TypeId) std.mem.Allocator.Error!bool {
        const before = self.sink.error_count;
        const main = self.ast.exprMain(id);
        const d = lists.function;
        // A bound on a type the brackets wrote, `heaviest[UInt8]`, is
        // reported at that type, as a call's is.
        const written: []const node.TypeRef = if (self.ast.exprTag(id) == .index and self.ast.bracketTypes(id) != null)
            self.ast.typeArgs(self.ast.bracketTypes(id).?)
        else
            &.{};
        if (!self.refusedBefore(main))
            _ = try self.argumentBoundsUnmet(d, settled[0], BoundSettlement.enclosing(lists.head, settled[1], lists.trait, settled[2]), main, written, .report);
        if (lists.head != node.DeclId.none) try self.checkArgumentBounds(lists.head, settled[1], null, main);
        if (self.sink.error_count != before) return false;
        if (lists.trait == node.DeclId.none) return true;
        const held = settled[0][lists.own - 1];
        if (held == .poison) return false;
        if (settled[2].len > 0) {
            try self.checkImplementationExists(id, (try self.valueImplementation(id, lists, settled)).?);
            if (self.sink.error_count != before) return false;
        } else if (!try self.dischargesDeclared(held, lists.trait, &.{})) {
            try self.reportSelfUnimplemented(self.locOf(id), self.ast.declName(lists.trait), held);
            return false;
        }
        if (self.builder.get(held) == .parameter) return true;
        // A concrete `Self` names its body now. A receiver that answers only
        // through an observation of itself has no body taking it as it is;
        // an array answering through its slice view has one generated.
        const choice = try self.builder.implementationChoiceWithin(self.generic, lists.trait, settled[2], held) orelse return true;
        if (choice.observations == 0) return true;
        try reportBodilessOperation(self.sink, self.ast.fileOfExpr(id), self.ast.exprSpan(id), self.ast.tokenText(self.ast.declName(d)), (try self.typeName(held)));
        _ = self.record(id, .poison);
        return false;
    }

    /// An open function value, waiting for its body to close before its
    /// parameters are read.
    const PendingValue = struct {
        /// Where the value sits in `function_values`.
        value: u32,
        lists: ValueLists,
        /// The open type each parameter was given, list by list.
        parameters: [3][]TypeId,

        fn deinit(pending: PendingValue, gpa: std.mem.Allocator) void {
            for (pending.parameters) |list| if (list.len > 0) gpa.free(list);
        }
    };

    /// A body's open integers and open function values, as prefixes of the
    /// tables that hold them.
    const OpenScope = struct {
        open: open_types_mod.Body,
        values: u32,
    };

    fn openScope(self: *const Checker) OpenScope {
        return .{ .open = self.open_types.pushBody(), .values = @intCast(self.pending_values.items.len) };
    }

    /// Closes a body: its open integers fall back, and each function value it
    /// named without a written type is read through what its uses settled.
    fn closeScope(self: *Checker, scope: OpenScope) std.mem.Allocator.Error!void {
        self.open_types.fallbackBody(scope.open, TypeId.literal_default);
        for (self.pending_values.items[scope.values..]) |pending| {
            defer pending.deinit(self.gpa);
            try self.settleValue(pending);
        }
        self.pending_values.shrinkRetainingCapacity(scope.values);
    }

    /// Reads an open function value's parameters as its uses settled them.
    /// A parameter no use settled is [T-Infer], named with the signature to
    /// write; a settled one must meet its bounds.
    fn settleValue(self: *Checker, pending: PendingValue) std.mem.Allocator.Error!void {
        const value = self.function_values.items[pending.value];
        var resolved: [3][]TypeId = .{ &.{}, &.{}, &.{} };
        defer for (resolved) |list| if (list.len > 0) self.gpa.free(list);
        var unsettled: ?struct { k: usize, i: usize } = null;
        for (pending.parameters, &resolved, 0..) |list, *into, k| {
            if (list.len == 0) continue;
            into.* = try self.gpa.alloc(TypeId, list.len);
            for (list, into.*, 0..) |open, *settled, i| {
                settled.* = try self.builder.resolveOpen(open, &self.open_types);
                if (unsettled == null and self.openVariable(settled.*) != null) unsettled = .{ .k = k, .i = i };
            }
        }
        const settled: [3][]const TypeId = .{ resolved[0], resolved[1], resolved[2] };
        if (self.builder.exprType(value.at) == .poison) unsettled = null else if (unsettled) |open| {
            // The signature with what the uses settled written in, and `_`
            // where a type is still open: the type the binding could be given.
            const signature = try self.throughValue(self.decl_signatures.get(pending.lists.function), pending.lists, settled);
            const written = self.ast.declParams(pending.lists.function);
            const names = try self.sink.arena.alloc([]const u8, written.len);
            for (written, names) |param, *spelled| spelled.* = self.ast.tokenText(param.name);
            const spelled = try self.builder.spellCallable(signature, names);
            defer self.gpa.free(spelled);
            _ = self.report(
                .t_infer,
                value.at,
                "nothing that uses `{s}` here says what `{s}` is",
                .{ self.ast.tokenText(self.ast.exprMain(value.at)), self.valueParameterName(pending.lists, open.k, open.i) },
                try std.fmt.allocPrint(self.sink.arena, "write the function type it is used as, with a type in place of each `_`: `{s}`", .{spelled}),
            );
        } else {
            const first = self.sink.items().len;
            _ = try self.valueMeetsBounds(value.at, pending.lists, settled);
            try self.labelSettlements(first, pending, settled);
            return;
        }
        // A value already refused, or one whose uses left a parameter open,
        // stands for poison wherever its open types reached.
        for (resolved) |list| for (list) |t| if (self.openVariable(t)) |v| self.open_types.abandon(v);
    }

    /// Points each report from `first` on at the uses that settled the
    /// value's parameters, since the value is where it was named and the
    /// type that failed came from later lines.
    fn labelSettlements(self: *Checker, first: usize, pending: PendingValue, settled: [3][]const TypeId) std.mem.Allocator.Error!void {
        if (self.sink.items().len == first) return;
        var added: std.ArrayList(Label) = .empty;
        defer added.deinit(self.gpa);
        for (pending.parameters, settled, 0..) |list, types, k| for (list, types, 0..) |open, ty, i| {
            const v = self.openVariable(open) orelse continue;
            const origin = self.open_types.origin(v) orelse continue;
            try added.append(self.gpa, .{
                .file = origin.site.file,
                .span = origin.site.span,
                .message = try std.fmt.allocPrint(self.sink.arena, "`{s}` settled to `{s}` here", .{ self.valueParameterName(pending.lists, k, i), (try self.typeName(ty)) }),
                .style = .secondary,
            });
        };
        if (added.items.len == 0) return;
        for (self.sink.mutableItems()[first..]) |*diagnostic| {
            if (diagnostic.severity != .err) continue;
            diagnostic.labels = try std.mem.concat(self.sink.arena, Label, &.{ diagnostic.labels, added.items });
        }
    }

    fn qualifiedConstructor(self: *const Checker, id: ExprId) bool {
        return self.res.targetOf(id) != .none and self.variantOrdinal(id) != null;
    }

    const ConstructorSelection = struct {
        declaration: node.DeclId,
        result: TypeId,
        ordinal: u32,
        qualified: bool,
        signature: TypeId = .poison,
    };

    const ConstructorShape = struct { ordinal: u32, payloads: u32 };

    fn constructorShape(self: *const Checker, id: ExprId, ty: TypeId) ConstructorShape {
        const ordinal = self.variantOrdinal(id) orelse unreachable;
        return .{ .ordinal = ordinal, .payloads = self.builder.variantFieldCount(ty, ordinal) };
    }

    fn constructorSelection(self: *Checker, id: ExprId, result: TypeId, report_missing: bool) ?ConstructorSelection {
        if (self.qualifiedConstructor(id)) {
            const declaration = self.res.declaredBy(self.res.targetOf(id));
            const qualifier = self.ast.unaryOperand(id);
            const through = if (qualifier == ExprId.none or self.genericAliasHead(self.res.targetOf(qualifier)) != null)
                null
            else
                self.aliasPathType(self.res.targetOf(qualifier));
            return .{
                .declaration = declaration,
                .result = through orelse self.type_of_decl.get(declaration),
                .ordinal = self.variantOrdinal(id).?,
                .qualified = true,
            };
        }
        if (self.ast.exprTag(id) != .variant_ref or self.ast.unaryOperand(id) != .none) return null;
        const declaration = self.declaringType(result) orelse return null;
        if (self.ast.declTag(declaration) != .enum_) return null;
        const spelling = self.ast.tokenText(self.ast.exprMain(id));
        // Out of memory for the index, the variants are scanned instead.
        const ordinal = (self.variantNamed(result, spelling) catch self.builder.variantIndexOf(result, spelling)) orelse {
            if (!report_missing) return null;
            _ = self.report(.n_variant, id, "`{s}` is not a variant of `{s}`", .{ spelling, self.typeName(result) catch return .{ .declaration = declaration, .result = .poison, .ordinal = 0, .qualified = false } }, "not a variant of the expected constructor result");
            return .{ .declaration = declaration, .result = .poison, .ordinal = 0, .qualified = false };
        };
        return .{ .declaration = declaration, .result = result, .ordinal = ordinal, .qualified = false };
    }

    const ConstructorCoveragePaths = struct {
        pool: *const Typing,

        pub fn isRoot(_: ConstructorCoveragePaths, path: []const types_mod.ResultSelector) bool {
            return path.len == 0;
        }

        pub fn head(_: ConstructorCoveragePaths, path: []const types_mod.ResultSelector) types_mod.ResultSelector {
            return path[0];
        }

        pub fn tail(_: ConstructorCoveragePaths, path: []const types_mod.ResultSelector) []const types_mod.ResultSelector {
            return path[1..];
        }

        pub fn arrayRange(_: ConstructorCoveragePaths, _: types_mod.ResultSelector, _: u32) ?types_mod.ArrayCoverageRange {
            return null;
        }

        pub fn childType(self: ConstructorCoveragePaths, ty: TypeId, step: types_mod.ResultSelector) ?TypeId {
            return switch (step) {
                .field => |field| if (field.index < self.pool.fieldCount(ty)) self.pool.fieldType(ty, field.index) else null,
                .payload => |payload| blk: {
                    const variant = @intFromEnum(payload.variant);
                    if (variant >= self.pool.variantCount(ty) or payload.index >= self.pool.variantFieldCount(ty, variant)) break :blk null;
                    break :blk self.pool.variantFieldType(ty, variant, payload.index);
                },
            };
        }
    };

    fn constructorContractsWithin(self: *Checker, payload: TypeId, ordinal: u32, promised: []const types_mod.CallableContract) !bool {
        const pool = try self.builder.dependencyView();
        if (!pool.mayCarryDependencies(payload)) return true;
        const actual = [_]types_mod.CallableContract{.{ .kind = .carries, .source = .{ .root = .{ .parameter = 0 } } }};
        const selected: types_mod.ResultSelector = .{ .payload = .{ .variant = @enumFromInt(ordinal), .index = 0 } };
        var paths: std.ArrayList([]const types_mod.ResultSelector) = .empty;
        defer paths.deinit(self.gpa);
        for (promised) |contract| {
            var source_promise = contract;
            source_promise.target = &.{};
            if (!types_mod.contractsWithin(&actual, &.{source_promise})) continue;
            if (contract.target.len == 0) return true;
            if (std.meta.eql(contract.target[0], selected)) try paths.append(self.gpa, contract.target[1..]);
        }
        return self.builder.coversDependencyPaths([]const types_mod.ResultSelector, payload, paths.items, ConstructorCoveragePaths{ .pool = &pool });
    }

    /// The payload and expected result settle the enum's parameters. A
    /// qualified name fixes the constructor directly; a leading-dot spelling
    /// takes that identity only from the callable result context.
    fn constructorSignature(self: *Checker, id: ExprId, context: TypeId, settling: []const Settling) std.mem.Allocator.Error!?ConstructorSelection {
        const wanted = switch (self.builder.get(context)) {
            .callable => |signature| signature,
            else => return null,
        };
        var selection = self.constructorSelection(id, wanted.result, true) orelse return null;
        if (selection.result == .poison) return selection;
        const parameters = try self.gpa.dupe(types_mod.CallableParam, self.builder.callableParams(wanted));
        defer self.gpa.free(parameters);
        if (parameters.len != 1 or parameters[0].convention != .sink or
            parameters[0].default != .absent or parameters[0].stable_address)
        {
            _ = self.report(.t_call, id, "an enum constructor requires one sink parameter without a default", .{}, "use a single consuming payload parameter");
            selection.result = .poison;
            return selection;
        }

        const declaration = selection.declaration;
        const template = self.type_of_decl.get(declaration);
        if (self.builder.variantFieldCount(selection.result, selection.ordinal) != 1) {
            _ = self.report(.t_call, id, "a callable enum constructor must carry exactly one payload", .{}, "use a closure for this variant");
            return .{ .declaration = declaration, .result = .poison, .ordinal = selection.ordinal, .qualified = selection.qualified };
        }

        var result = template;
        const generics = self.ast.declTypeParams(declaration);
        if (generics.len > 0) {
            const selected = try self.gpa.alloc(TypeId, generics.len);
            defer self.gpa.free(selected);
            @memset(selected, .poison);
            var clash: ?Clash = null;
            const payload = self.builder.variantFieldType(template, selection.ordinal, 0);
            var agrees = try self.settleSignatureTypes(payload, parameters[0].ty, declaration, selected, &clash);
            if (agrees) if (self.builder.instanceOf(wanted.result)) |instance| {
                if (instance.decl == declaration) {
                    for (self.param_types[declaration.index()], self.builder.argsOf(instance)) |parameter, argument| {
                        if (!try self.settleByInContext(parameter, argument, declaration, selected, &clash, .signature_types, settling)) {
                            agrees = false;
                            break;
                        }
                    }
                }
            };
            if (!agrees) {
                const conflict = clash.?;
                _ = self.report(.t_mismatch, id, "the callable signature makes `{s}` both `{s}` and `{s}`", .{
                    self.ast.tokenText(generics[conflict.index].name),
                    (try self.typeName(conflict.was)),
                    (try self.typeName(conflict.got)),
                }, "the payload parameter and the result must agree on each enum type argument");
                selection.result = .poison;
                return selection;
            }
            for (selected) |ty| if (ty == .poison) return null;
            const errors = self.sink.error_count;
            try self.checkArgumentBounds(declaration, selected, null, self.ast.exprMain(id));
            if (self.sink.error_count != errors) {
                selection.result = .poison;
                return selection;
            }
            result = try self.builder.instantiate(template, declaration, selected);
        }
        if (self.sealedHere(result)) {
            _ = self.reportSealed(id, result, "only its own module can build one");
            selection.result = .poison;
            return selection;
        }
        if (selection.qualified) {
            const q = self.ast.unaryOperand(id);
            if (q != ExprId.none) if (self.genericAliasHead(self.res.targetOf(q))) |alias| {
                const heading: AliasHeading = .{
                    .alias = alias,
                    .written = &.{self.aliasPathType(self.res.targetOf(q)).?},
                    .found = try self.openAliasArguments(alias),
                };
                if (!try self.settleAliasHeading(id, self.ast.exprMain(q), heading, &.{result})) {
                    selection.result = .poison;
                    return selection;
                }
            };
        }
        selection.result = result;
        const payload = self.builder.variantFieldType(result, selection.ordinal, 0);
        if (payload != parameters[0].ty) {
            _ = self.reportMismatch(id, payload, .{ .ty = parameters[0].ty, .at = self.locOf(id), .reason = .payload }, "");
            selection.result = .poison;
            return selection;
        }

        // Generated bodies have no source ownership walk. Check the actual
        // payload transfer against the callable's promised dependency paths.
        if (!try self.constructorContractsWithin(payload, selection.ordinal, wanted.contracts)) {
            _ = self.report(.t_borrow_contract, id, "the constructor result carries its payload's owner dependencies", .{}, "the callable contract must carry the payload into the result");
            selection.result = .poison;
            return selection;
        }
        selection.signature = try self.builder.internCallable(parameters, result, wanted.contracts, wanted.invocation);
        return selection;
    }

    fn selectConstructorValue(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!?TypeId {
        const want = expected orelse return null;
        if (!self.qualifiedConstructor(id) and self.ast.exprTag(id) != .variant_ref) return null;
        if (want.ty == .poison) return self.record(id, .poison);
        if (self.builder.get(want.ty) != .callable) return null;
        const selection = try self.constructorSignature(id, want.ty, &.{}) orelse
            return self.report(.t_infer, id, "the callable signature does not select one enum constructor", .{}, "settle every enum type parameter through the payload or result");
        const signature = selection.signature;
        if (selection.result == .poison or signature == .poison) return self.record(id, .poison);
        if (signature != want.ty) return self.reportMismatch(id, signature, want, "");
        if (selection.qualified) self.noteQualifier(id);
        try self.variant_uses.put(self.gpa, id, .{ .ordinal = @enumFromInt(selection.ordinal) });
        try self.function_values.append(self.gpa, .{
            .at = id,
            .target = .{ .constructor = .{ .id = @enumFromInt(self.constructor_count), .expr = id, .enclosing = self.generic, .ordinal = @enumFromInt(selection.ordinal) } },
            .signature = signature,
        });
        self.constructor_count += 1;
        return self.record(id, signature);
    }

    /// A name the type answers to through a trait nothing here imported.
    ///
    /// The module is spelled by its own name, which is the spelling an import
    /// binds it under: an import takes no alias, so there is one way to write
    /// the qualifier and no need to look up which the reader chose.
    fn reportOutOfScope(
        self: *Checker,
        id: ExprId,
        name: []const u8,
        trait: node.DeclId,
    ) std.mem.Allocator.Error!TypeId {
        const declares = self.ast.tokenText(self.ast.declName(trait));
        const file = self.ast.fileOf(self.ast.exprMain(id));
        const route = self.res.useRoute(self.program.source, self.ast, file, trait);

        return self.report(
            .t_unknown_operation,
            id,
            "`{s}` is declared by `{s}`, which is not in scope here",
            .{ name, declares },
            if (route.import) |needed| try std.fmt.allocPrint(
                self.gpa,
                "write `import {s}` and `use {s}.{s}`: an operation is reached through the trait that declares it",
                .{ needed, route.module, declares },
            ) else try std.fmt.allocPrint(
                self.gpa,
                "write `use {s}.{s}`: an operation is reached through the trait that declares it",
                .{ route.module, declares },
            ),
        );
    }

    fn rendersItself(self: *const Checker, ty: TypeId, trait: node.DeclId) bool {
        const pool = self.view();
        return rendersDisplayItself(&pool, self.display_decl, ty, trait);
    }

    /// Check that a value's format spec asks only for parts its type takes. A
    /// sign and zero padding lay out a number, and a precision counts the
    /// digits after a Float64's point; fill, alignment and width lay out any
    /// value. Reports the first part the type does not take.
    fn layoutFits(self: *Checker, piece: ExprId, t: TypeId, format: node.InterpolationFormat) bool {
        const shape = self.builder.view().layoutShape(self.generic, t);
        if ((format.plus or format.zero) and shape == .general) {
            _ = self.report(
                .t_format,
                piece,
                "`{s}` is not a number, so its format spec cannot ask for {s}",
                .{ self.typeName(t) catch return false, if (format.plus) "a `+` sign" else "zero padding" },
                "these lay out integers and Float64; pad other values with an alignment and a width, as in `>4`",
            );
            return false;
        }
        if (format.has_precision and shape != .float) {
            _ = self.report(
                .t_format,
                piece,
                "`{s}` is not a Float64, so its format spec cannot ask for a precision",
                .{self.typeName(t) catch return false},
                "a precision counts the digits after a Float64's point",
            );
            return false;
        }
        return true;
    }

    /// `"a{x}b"`: mint the type that holds its pieces.
    ///
    /// One type per literal, its fields alternating the text around the values
    /// and the values themselves, in the order they were written. Ordinary in
    /// every respect except that the compiler wrote it down: it is laid out,
    /// copied and bound as any structure is, and holding the values rather than
    /// rendering them on the spot is what makes an interpolation a value that
    /// can be passed and rendered twice.
    ///
    /// A value that can be copied is held as a copy, whether it is a place or
    /// computed, so two literals rendering the same types are one type. A
    /// place that cannot be copied is held by a read borrow, so a literal
    /// renders it and is used only while it lives. Any other computed value
    /// is moved into the literal, except one that must be settled: the
    /// literal cannot settle it, so it is borrowed as a temporary of the
    /// literal's statement.
    fn checkInterp(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const interpolation = self.ast.interpolation(id);
        const pieces = interpolation.pieces;
        // A literal is checked once, so a refusal has no earlier answer to
        // retract from `interpolation_positions`.
        if (std.debug.runtime_safety) for (pieces, 0..) |piece, i| {
            if (i % 2 == 1) std.debug.assert(!self.interpolation_positions.contains(piece));
        };

        var fields: std.ArrayList(types_mod.Field) = .empty;
        defer fields.deinit(self.gpa);
        var borrows: std.ArrayList(bool) = .empty;
        defer borrows.deinit(self.gpa);
        const Positioned = struct { piece: ExprId, position: types_mod.PiecePosition };
        var positions: std.ArrayList(Positioned) = .empty;
        defer positions.deinit(self.gpa);

        var poisoned = false;
        var diverges = false;
        for (pieces, 0..) |piece, i| {
            const t = try self.check(piece, null);
            if (t == .poison) poisoned = true;
            if (t == .never) diverges = true;

            // Even indices are the text, which is a `Str` by construction.
            // The odd ones are what was written between the braces.
            var held = t;
            if (i % 2 == 1 and t != .never) {
                if (t != .poison) {
                    const format = interpolation.formats[i / 2];
                    const target = self.formatting.target(format);
                    if (target.trait) |trait| {
                        // Check the trait as a bound is discharged, so a
                        // parameter's bounds, a literal held in another, a
                        // declared implementation and a `borrow T` forwarding
                        // to what it observes all satisfy it.
                        if (!try self.dischargesDeclared(t, trait, &.{})) {
                            const file = self.ast.fileOfExpr(piece);
                            const span = self.ast.exprSpan(piece);
                            if (format.debug) {
                                try self.reportUnimplemented(
                                    file,
                                    span,
                                    "it does not",
                                    "`{s}` uses `:?` in text, so it implements `Debug`",
                                    .{(try self.typeName(t))},
                                    trait,
                                    &.{},
                                    t,
                                );
                            } else {
                                try self.reportUnimplemented(
                                    file,
                                    span,
                                    "it does not",
                                    "`{s}` is written into text, so it implements `Display`",
                                    .{(try self.typeName(t))},
                                    trait,
                                    &.{},
                                    t,
                                );
                            }
                            _ = self.record(piece, .poison);
                            poisoned = true;
                        }
                    }
                    if (!self.layoutFits(piece, t, format)) poisoned = true;
                    // A value that can be copied is held, a `borrow T` value
                    // included, whose copy is the pointer; so is a computed
                    // value nothing else owns. A place that cannot be copied
                    // is borrowed, and so is a computed value that must be
                    // settled: the literal cannot settle it, so it stays a
                    // temporary of the statement.
                    const copied = try self.builder.mayCopyWithin(self.generic, t);
                    if (!copied and (self.isAPlace(piece) or !try self.builder.mayDiscardWithin(self.generic, t))) {
                        held = try self.builder.borrowOf(t);
                        try self.noteBorrowed(piece);
                        try positions.append(self.gpa, .{ .piece = piece, .position = .borrowed });
                    } else try positions.append(self.gpa, .{ .piece = piece, .position = if (copied) .copied else .moved });
                }
            }
            if (i % 2 == 1) try borrows.append(self.gpa, held != t);

            const name = try std.fmt.allocPrint(self.builder.gpa, "{d}", .{i});
            try fields.append(self.gpa, .{ .name = name, .ty = held });
        }
        if (diverges) return self.record(id, .never);
        // Still a type, even where a piece was refused. Answering poison would
        // stop the call around it settling, and the reader would be told about
        // an argument that has nothing wrong with it -- which is the thing
        // poison exists to prevent rather than to cause.
        if (poisoned) {
            for (fields.items) |*f| f.ty = .poison;
            @memset(borrows.items, false);
        } else for (positions.items) |held| try self.interpolation_positions.put(self.gpa, held.piece, held.position);

        const ty = try self.builder.internInterpolation(fields.items, interpolation.formats, borrows.items);
        return self.expect(id, ty, expected);
    }

    fn checkArrayLiteral(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const c = self.ast.call(id);

        // With nothing expected, the elements say what this is. Unlike a
        // braced literal -- where many types have an `x: Int64` and only the
        // context can say which was meant -- an array's type is its element's
        // and its count, and both are written here. `let xs = [1, 2, 3]` reads
        // like `let x = 1`, which is how most of a program is written.
        const want = Expected.typeOf(expected) orelse {
            if (c.args.len == 0) return self.report(
                .t_infer,
                id,
                "an empty array has no element to say what it holds",
                .{},
                "give the binding a type, or name one",
            );

            // From the first element that is not a bare literal. A literal
            // takes the type its context asks for -- that is what makes
            // `let x: UInt8 = 42` work -- and here its context is its
            // siblings. Reading the type off whichever element came first
            // made `[2, n]` and `[n, 2]` different verdicts about one array.
            var settles: usize = 0;
            for (c.args, 0..) |a, i| {
                if (self.ast.exprTag(a) != .int_literal) {
                    settles = i;
                    break;
                }
            }

            const element = try self.check(c.args[settles], null);
            if (element == .poison) {
                for (c.args, 0..) |a, i| {
                    if (i != settles) _ = try self.check(a, null);
                }
                return self.record(id, .poison);
            }
            if (element == .never) {
                for (c.args, 0..) |a, i| {
                    if (i != settles) _ = try self.check(a, null);
                }
                return self.expect(id, .never, expected);
            }

            // Checked here and not below: the shared path takes an expected
            // type, and running both reported every element's mismatch twice.
            var diverges = false;
            for (c.args, 0..) |a, i| {
                if (i == settles) continue;
                const found = try self.check(a, .{
                    .ty = element,
                    .reason = .element,
                    .at = self.locOf(c.args[settles]),
                });
                if (found == .never) diverges = true;
            }
            const of = try self.builder.arrayOf(element, @intCast(c.args.len));
            self.builder.setConstruction(id, of);
            if (diverges) return self.expect(id, .never, expected);
            return self.record(id, of);
        };
        if (want == .poison) {
            // Nothing known about the array says what an element must be, so
            // each is checked on its own under the same unknown context:
            // what is wrong inside one is still reported, and nothing is held
            // against a type nobody knows.
            for (c.args) |a| _ = try self.check(a, expected);
            return self.record(id, .poison);
        }

        const arr = switch (self.builder.view().get(want)) {
            .array => |a| blk: {
                self.builder.setConstruction(id, want);
                break :blk a;
            },
            else => {
                var diverges = false;
                for (c.args) |a| {
                    if (try self.check(a, null) == .never) diverges = true;
                }
                if (diverges) return self.expect(id, .never, expected);
                return self.expect(id, want, expected);
            },
        };

        var diverges = false;
        for (c.args) |a| {
            // An element answers to whatever gave the array its type, so a
            // mismatch points where that was written.
            const found = try self.check(a, .{ .ty = arr.element, .reason = expected.?.reason, .at = expected.?.at, .inference = expected.?.inference });
            if (found == .never) diverges = true;
        }

        if (c.args.len != arr.count) return self.report(
            .t_array_length,
            id,
            "an array's length is part of its type, so a literal has as many elements as the type says",
            .{},
            try std.fmt.allocPrint(
                self.sink.arena,
                "this has {d}, and the type says {d}",
                .{ c.args.len, arr.count },
            ),
        );
        if (diverges) return self.expect(id, .never, expected);

        return self.record(id, want);
    }

    /// `(a, b)`: a construction of the prelude's tuple declaration of that
    /// arity.
    ///
    /// An expected tuple of the same arity flows into the components, as a
    /// structure literal's field types flow into its values. Otherwise each
    /// component is checked on its own and the instance is built from what
    /// they are, which is how an array literal reads its type off its
    /// elements. The type being built is recorded before a component that
    /// leaves makes the literal `Never`, so a report about the unfinished
    /// value can name it.
    fn checkTupleLiteral(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const c = self.ast.call(id);

        // An arity the parser refused was reported at the `(`; one the
        // prelude declares no type for is reported here. The components are
        // still expressions whose own mistakes are reported.
        const decl = self.tupleDecl(c.args.len) orelse {
            for (c.args) |a| _ = try self.check(a, null);
            try self.reportUnpublishedTuple(c.args.len, self.ast.fileOfExpr(id), self.ast.exprSpan(id));
            return self.record(id, .poison);
        };

        if (Expected.typeOf(expected)) |want| {
            if (want == .poison) {
                // Nothing known about the tuple says what a component must
                // be, so each is checked under the same unknown context.
                for (c.args) |a| _ = try self.check(a, expected);
                return self.record(id, .poison);
            }
            if (self.builder.instanceOf(want)) |instance| if (instance.decl == decl) {
                // Copied, because checking a component may mint an
                // instantiation and move the arguments every instance keeps.
                var wanted: [node.max_tuple_arity]TypeId = undefined;
                @memcpy(wanted[0..c.args.len], self.builder.argsOf(instance));
                self.builder.setConstruction(id, want);
                var diverges = false;
                for (c.args, wanted[0..c.args.len]) |a, component| {
                    // A component answers to whatever gave the tuple its
                    // type, so a mismatch points where that was written.
                    const found = try self.check(a, .{
                        .ty = component,
                        .reason = expected.?.reason,
                        .at = expected.?.at,
                        .inference = expected.?.inference,
                    });
                    if (found == .never) diverges = true;
                }
                if (diverges) return self.expect(id, .never, expected);
                return self.record(id, want);
            };
        }

        var components: [node.max_tuple_arity]TypeId = undefined;
        var poisoned = false;
        var diverges = false;
        for (c.args, 0..) |a, i| {
            const found = try self.check(a, null);
            if (found == .poison) poisoned = true;
            if (found == .never) diverges = true;
            components[i] = found;
        }
        if (poisoned) return self.record(id, .poison);

        const of = try self.tupleType(decl, components[0..c.args.len]);
        self.builder.setConstruction(id, of);
        if (diverges) return self.expect(id, .never, expected);
        return self.expect(id, of, expected);
    }

    /// `a[i]`, which names an element.
    ///
    /// Two clauses and one rule: an array's index counts -- from the start, or
    /// back from the end -- and an index the compiler settles is one an element
    /// sits at. The second is what makes a settled index cost nothing when the
    /// program runs -- there is no check to emit for a value the compiler
    /// already knows.
    ///
    /// An array is what the language indexes by itself. Every other head names
    /// the place its own `Index` implementation projects, which is the same
    /// bracket written over a container the library rather than the compiler
    /// supplies -- and the settled clause is asked of that bracket too, of the
    /// array its path reaches, through the one routine below.
    fn checkIndex(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        _ = self.selected_places.remove(id);
        const b = self.ast.binary(id);
        if (self.res.bracketReading(id)) |reading| switch (reading) {
            .type_arguments => return self.checkWrittenFunctionValue(id, expected),
            .unresolved => {
                _ = try self.check(b.lhs, null);
                self.recordTypeWrittenAsIndex(b.rhs);
                return self.record(id, .poison);
            },
            // A called bracket whose head `checkBracketCall` found to be a
            // field, and so an index; its deferred reports are already made.
            .member => {},
            .index => if (self.ast.exprTag(b.rhs) == .err) {
                _ = try self.check(b.lhs, null);
                self.recordTypeWrittenAsIndex(b.rhs);
                return self.report(
                    .t_index,
                    id,
                    "this bracket holds a list, and an index is one value",
                    .{},
                    "index one position at a time, as in `grid[row][column]`",
                );
            },
        };
        const head = try self.check(b.lhs, null);
        if (head == .never) {
            _ = try self.check(b.rhs, null);
            return self.expect(id, .never, expected);
        }

        // The head decides which of the two rules this bracket is under, so it
        // settles first: an array's index is any whole number, and a
        // container's is the trait argument its implementation was written for,
        // which a bare number must settle to before there is a key to look up.
        const arr = switch (self.builder.view().get(head)) {
            .array => |a| a,
            else => {
                if (head == .poison) {
                    // Brackets after a type's name hold its arguments, which
                    // the report on the name already covers.
                    const named = self.res.targetOf(b.lhs);
                    if (named != BindingId.none and (resolve_mod.namesANamespace(self.res.kindOf(named)) or self.res.kindOf(named) == .type_alias))
                        self.recordTypeWrittenAsIndex(b.rhs)
                    else
                        _ = try self.check(b.rhs, null);
                    return self.record(id, .poison);
                }
                return self.checkProjected(id, head, expected);
            },
        };

        const checked_index = try self.check(b.rhs, try self.rangeIndexExpected(id, b.rhs));
        // An array counts its places in `UInt64`, so an index no use has
        // settled yet takes that type here.
        if (self.builder.get(checked_index) == .open_integer) _ = try self.meet(checked_index, .u64, self.literalSite(b.rhs));
        const index = try self.builder.resolveOpen(checked_index, &self.open_types);
        if (index == .poison) return self.record(id, .poison);
        if (index == .never) return self.expect(id, .never, expected);

        // A range names one place of several elements rather than one element,
        // and which it is is decided the way every other bracket's meaning is:
        // by what the index settled to, held against the relation that says
        // which values an array is indexed by.
        if (try self.rangeIndexType()) |key| {
            if (index == key and try self.arrayInterprets(head, index)) {
                return self.checkRangePlace(id, b.rhs, arr.element, arr.count, expected);
            }
        }

        // An array interprets a count back from its end itself: how many
        // elements there are is part of its type, so there is nothing else to
        // ask. The value is ordinary and reaches here however the site spelled
        // it -- the caret, a binding, what a call returned -- because what a
        // bracket means is decided by what the index settled to.
        if (self.fromEndType()) |counting_back| {
            if (index == counting_back and try self.arrayInterprets(head, index)) {
                // `^k` names the place `k` back from the end, so the settled
                // clause is asked of the index that names: one sentence for
                // both spellings, and a count no element sits at is refused by
                // the rule an index no element sits at is refused by.
                if (self.settledElement(id)) |at| {
                    if (try self.refuseSettledIndex(b.rhs, arr.count, at, .count_back)) {
                        return self.refusedElement(id, arr.element, expected);
                    }
                }
                return self.finishSelection(id, arr.element, expected);
            }
        }

        switch (self.builder.view().get(index)) {
            .integer => {},
            else => return self.report(
                .t_index,
                b.rhs,
                "an index counts elements, so it is a whole number",
                .{},
                try std.fmt.allocPrint(
                    self.sink.arena,
                    "this is {s} `{s}`",
                    .{ article.before(try self.typeName(index)), (try self.typeName(index)) },
                ),
            ),
        }

        if (self.settledElement(id)) |at| {
            if (try self.refuseSettledIndex(b.rhs, arr.count, at, .index)) return self.refusedElement(id, arr.element, expected);
        }

        return self.finishSelection(id, arr.element, expected);
    }

    /// A bracket whose settled index no element sits at. It names no place,
    /// so it records no selected place, but its type is still the element
    /// type: what is written around it is checked, and what the path's
    /// accepted steps name is still decided, as for a projected bracket the
    /// settled clause refuses after its path was typed.
    fn refusedElement(self: *Checker, id: ExprId, element: TypeId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        return self.expect(id, element, expected);
    }

    /// Records the resolved place before surrounding types can reject its value.
    fn finishSelection(self: *Checker, id: ExprId, ty: TypeId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        if (ty != .poison) {
            try self.selected_places.put(self.gpa, id, ty);
            if (self.ast.exprTag(id) == .index) try self.noteFoldedIndex(self.ast.binary(id).rhs);
            const base = self.placeBase(id);
            if (base != .none and self.readonly_places.contains(self.ast.withoutGroups(base))) try self.readonly_places.put(self.gpa, id, {});
            if (base != .none and self.ast.exprTag(id) == .index and self.raw_accesses.slice != .none and
                self.builder.view().declOfType(self.builder.exprType(base)) == self.raw_accesses.slice)
            {
                try self.readonly_places.put(self.gpa, id, {});
                try self.carried_places.put(self.gpa, id, {});
            }
        }
        return self.expect(id, ty, expected);
    }

    /// Publishes the number a bracket's index operand folds to, keyed by the
    /// operand or by the count under a `^`, so ownership and lowering read the
    /// answer the checker settled -- arithmetic over constants included --
    /// rather than folding the operand again.
    fn noteFoldedIndex(self: *Checker, operand: ExprId) std.mem.Allocator.Error!void {
        const written = self.ast.withoutGroups(operand);
        const counted = if (self.ast.exprTag(written) == .from_end) self.ast.withoutGroups(self.ast.unaryOperand(written)) else written;
        const value = self.folds.get(counted).valueOf() orelse return;
        const whole = std.math.cast(u64, value) orelse return;
        try self.folded_indices.put(self.gpa, counted, whole);
    }

    /// Whether the compiler provides an interpretation of this index type for
    /// arrays.
    ///
    /// Stated in the one relation, as one row per index type an array answers
    /// for, and read here through the lookup a bound is discharged through. So
    /// which values an array can be indexed by is written down once: a row
    /// nobody seeded is a bracket nobody can write, and a bracket the language
    /// admits is an implementation a bound naming the trait would find.
    ///
    /// **Bound:** one index lookup, on the path an index that does not count
    /// takes -- which is the from-end spelling and the refusal beside it.
    fn arrayInterprets(self: *Checker, head: TypeId, index: TypeId) std.mem.Allocator.Error!bool {
        const trait = self.index_decl orelse return false;
        const args = [_]TypeId{index};
        const row = try self.builder.implementationRow(
            trait,
            &args,
            head,
        );
        return row != null;
    }

    /// What a range written in an index position settles to.
    ///
    /// A range's ends settle from what is written unless a position says
    /// otherwise, and an index position says `UInt64` -- the same thing it says
    /// to a bare number, for the same reason: what a bracket is keyed on is the
    /// index's type, so an unstated one would make `a[0..2]` and `a[0..k]` two
    /// different keys over one array. Null for anything but a range, which
    /// settles on its own and is held to what it settled to.
    fn rangeIndexExpected(self: *Checker, id: ExprId, rhs: ExprId) std.mem.Allocator.Error!?Expected {
        _ = self.writtenRange(rhs) orelse return null;
        const key = try self.rangeIndexType() orelse return null;
        return .{
            .ty = key,
            .at = .{ .file = self.ast.fileOfExpr(id), .span = self.ast.exprSpan(id) },
            .reason = .index_position,
        };
    }

    /// The range a bracket's index was written as, or null where the index is a
    /// range that arrived some other way -- a binding, a call, a field.
    ///
    /// The one place the two questions about a range in a bracket are told
    /// apart. What settles the ends is what a position expects of them, which
    /// is a question about the expression; what a bracket *means* is decided by
    /// the type the index settled to, which is a question about the value. A
    /// range value has ends and no expressions for them, so this is what says
    /// there is nothing here to read a place's type off -- and the reader that
    /// hands the position its expectation and the reader that folds the bounds
    /// ask it once between them.
    fn writtenRange(self: *const Checker, rhs: ExprId) ?ExprId {
        const at = self.ast.withoutGroups(rhs);
        return if (self.ast.exprTag(at) == .range) at else null;
    }

    /// The one type a range in an index position is, or null where no library
    /// declares `Range`.
    ///
    /// One reader for both questions asked of it -- what a range in a bracket
    /// settles to, and which index type an array names a run of elements for --
    /// so a bracket cannot admit a range the position does not build, or refuse
    /// one it does. The pool interns an instantiation once, so asking here and
    /// asking at `lo..hi` are one answer.
    ///
    /// **Bound:** one hashed lookup of the instantiation, asked once per
    /// bracket over an array. Nothing is minted after the first ask, and the
    /// first is the row the compiler seeds before any body is walked.
    fn rangeIndexType(self: *Checker) std.mem.Allocator.Error!?TypeId {
        const decl = self.range_decl orelse return null;
        const template = self.type_of_decl.get(decl);
        if (template == .poison) return null;
        return try self.builder.instantiate(template, decl, &.{.u64});
    }

    /// `a[lo..hi]`, which names one place of several elements.
    ///
    /// The place is a single place of the array type its bounds name, and every
    /// rule that reaches it reaches it through that type: `copy` of it is the
    /// copy of an array, and an assignment into it is an assignment of one. So
    /// there is nothing range-shaped below here -- what a linear element makes
    /// of either is what a linear element makes of copying or writing over a
    /// `[Key; 2]`.
    ///
    /// Three things are refused, which is the whole of [T-RangePlace] plus the
    /// clause every settled index is held to. The use has to be whole, because
    /// a narrower one names nothing the language defines. The bounds have to
    /// settle here, because the place's type is what they name and `[T; ?]` is
    /// not a type. And the elements they name have to be elements the array
    /// has, which is [T-Index]'s settled clause asked of the first and the last
    /// through the routine that asks it of every other settled index.
    ///
    /// **Bound:** the two bounds of the one bracket, each read from the fold
    /// table by expression, and one entry appended per range place written.
    fn checkRangePlace(
        self: *Checker,
        id: ExprId,
        rhs: ExprId,
        element: TypeId,
        count: u32,
        expected: ?Expected,
    ) std.mem.Allocator.Error!TypeId {
        if (self.whole_place != id) return self.report(
            .t_range_place,
            id,
            "a range place is copied out of or assigned into whole",
            .{},
            "this use is neither, and a part of a range place names nothing",
        );

        // A range that arrived as a value has ends and no expressions for them,
        // so nothing here settles: the place's type would be read off a number
        // this bracket does not name. That is the settling clause and not a
        // clause of its own, reported at the index the reader wrote.
        const at = self.writtenRange(rhs) orelse return self.unsettledBound(id, rhs);
        const ends = self.ast.rangeEnds(at);
        const lo = self.foldedBound(ends.lhs) orelse return self.unsettledBound(id, ends.lhs);
        const hi = self.foldedBound(ends.rhs) orelse return self.unsettledBound(id, ends.rhs);

        // The last element the place names, which is what the bounds are held
        // against: an inclusive end names it and an exclusive end names the one
        // after it, and the difference is the whole of what the two spellings
        // are.
        const inclusive = self.ast.rangeInclusive(at);
        const last = if (inclusive) hi else hi - 1;

        if (last < lo) {
            _ = self.report(
                .t_range_place,
                at,
                "a range place is the elements between its bounds, and these name none",
                .{},
                "there is no array type of no elements for this to be",
            );
            return self.record(id, .poison);
        }

        if (try self.refuseSettledIndex(ends.lhs, count, lo, .index)) return self.record(id, .poison);
        const wrote: Wrote = if (inclusive) .index else .end;
        if (try self.refuseSettledIndex(ends.rhs, count, last, wrote)) return self.record(id, .poison);

        // Where the place begins, recorded where it was settled: lowering emits
        // that offset rather than folding the bounds again, which is the same
        // reason a routed bracket carries its expansion.
        try self.range_places.append(self.gpa, .{
            .at = @intCast(id.index()),
            .first = @intCast(lo),
        });

        const made = try self.builder.arrayOf(element, @intCast(last - lo + 1));
        return self.finishSelection(id, made, expected);
    }

    /// What a range place's bound settled to, or null where nothing settles it.
    ///
    /// The same table an index is settled through, read the same way: a bound
    /// is an index, so what settles one settles the other and there is one
    /// answer to what a written expression is worth.
    fn foldedBound(self: *const Checker, end: ExprId) ?i128 {
        return self.folds.get(self.ast.withoutGroups(end)).valueOf();
    }

    /// [T-RangePlace]'s settling clause, reported at the bound that failed it.
    fn unsettledBound(self: *Checker, id: ExprId, end: ExprId) TypeId {
        _ = self.report(
            .t_range_place,
            end,
            "a range place's bounds settle where the place is formed",
            .{},
            "this is not settled here, and the place's length is what the bounds name",
        );
        return self.record(id, .poison);
    }

    /// `^k`, the short spelling of a value that counts back from an end.
    ///
    /// This is the whole of the desugar, and it is the checker's: the tree
    /// keeps the caret so a formatter prints back what was written, and what
    /// reaches every pass below is a `FromEnd` like any other. So a container
    /// interpreting one interprets both spellings, and nothing under here has
    /// a second form to know about.
    ///
    /// What it counts by counts elements, so it settles the way an index does.
    fn checkFromEnd(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const count = try self.check(self.ast.unaryOperand(id), .{
            .ty = .u64,
            .at = self.locOf(id),
            .reason = .from_end_count,
        });

        const ty = self.fromEndType() orelse return self.report(
            .t_index,
            id,
            "counting back from an end has no type here: the prelude declares no `FromEnd`",
            .{},
            "build against a library that declares it",
        );
        if (count == .poison) return self.record(id, .poison);
        if (count == .never) return self.expect(id, .never, expected);
        return self.expect(id, ty, expected);
    }

    /// What `^k` is a value of, or null where no library declares one.
    ///
    /// One reader for both questions asked of it -- what the caret settles to,
    /// and which index type an array counts back for -- so a bracket cannot
    /// admit a value the caret does not build, or refuse one it does.
    fn fromEndType(self: *const Checker) ?TypeId {
        const decl = self.from_end_decl orelse return null;
        return self.type_of_decl.get(decl);
    }

    /// What a count back from the end was settled to be, or null where nothing
    /// settles it.
    ///
    /// The count sits under the caret, so this reads what was folded there. A
    /// value written out as a structure folds to nothing -- a field of one is
    /// not a constant this pass works out -- so such a bracket is held to the
    /// length where every other unsettled index is, when the program runs.
    fn foldedFromEnd(self: *const Checker, id: ExprId) ?i128 {
        const at = self.ast.withoutGroups(id);
        if (self.ast.exprTag(at) != .from_end) return null;
        return self.folds.get(self.ast.withoutGroups(self.ast.unaryOperand(at))).valueOf();
    }

    /// Which element of an array a bracket names, or null where nothing this
    /// pass folds settles it.
    ///
    /// One reader for every rule that asks which element a bracket reached --
    /// the settled clause, and whether two arguments name one place -- because
    /// a bracket admitted as the last element by one and treated as some other
    /// element by the other is two answers to one question. A caret counts back,
    /// so the element it names is the length less the count it wrote: the
    /// spelling is where the number came from and not which element it is.
    ///
    /// Null for a bracket over anything but an array. What a bracket over a
    /// container reaches is the implementation's path to decide -- a path that
    /// never reads its parameter names one place for every number, and one that
    /// computes over it can name one place for two -- so the site's number
    /// names no element on its own.
    fn settledElement(self: *const Checker, id: ExprId) ?i128 {
        const at = self.ast.withoutGroups(id);
        if (self.ast.exprTag(at) != .index) return null;
        const b = self.ast.binary(at);
        const count = switch (self.builder.view().get(self.builder.exprType(b.lhs))) {
            .array => |a| a.count,
            else => return null,
        };
        if (self.foldedFromEnd(b.rhs)) |k| return @as(i128, count) - k;
        return self.folds.get(b.rhs).valueOf();
    }

    /// `[T-Projection]`'s cycle clause: refuses an implementation whose own
    /// expansion never bottoms out, because its path reaches an implementation
    /// still being walked -- directly or through any chain of projections.
    ///
    /// A projection's body is checked exactly as any other, so `checkProjected`
    /// has already recorded, in `projected_at`, whatever implementation each
    /// bracket in that body routes through -- keyed by the bracket's expression
    /// id, the same table a write's ceiling reads. Termination is therefore a
    /// question about that one table: read the edges off every bracket the
    /// path holds, and refuse where the walk returns to an implementation
    /// still on it.
    ///
    /// Every bracket, because lowering splices every one of them: a bracket
    /// standing under a field selection routes as surely as the one written
    /// last, and an index expression is spliced into the site with the spine it
    /// sits in. An edge read off the path's outermost node alone would leave
    /// both reaching an implementation nothing here had seen.
    ///
    /// Run after every body, for the reason `checkProjectedIndexRanges` runs
    /// after every body: an implementation reached only through another's path
    /// may sit below it in the file, and asking while a body is still being
    /// checked would read a table not yet settled for one not yet reached.
    fn checkProjectionCycles(self: *Checker) std.mem.Allocator.Error!void {
        const state = try self.gpa.alloc(Visit, self.expansions.items.len);
        defer self.gpa.free(state);
        @memset(state, .unvisited);

        var chain: std.ArrayList(u32) = .empty;
        defer chain.deinit(self.gpa);

        for (0..self.expansions.items.len) |start| {
            if (state[start] != .unvisited) continue;
            try self.walkExpansion(@intCast(start), state, &chain);
        }
    }

    /// Where the cycle walk stands with one implementation: not yet reached,
    /// on the chain the walk is holding, or finished with.
    const Visit = enum(u2) { unvisited, in_progress, done };

    /// One implementation and everything its path reaches, marking the chain
    /// while it is on it.
    ///
    /// **Bound:** each expansion entered once however many chains reach it, and
    /// the brackets of its own path read once -- the brackets of the program in
    /// total, not the program's expansions per expansion.
    fn walkExpansion(
        self: *Checker,
        row: u32,
        state: []Visit,
        chain: *std.ArrayList(u32),
    ) std.mem.Allocator.Error!void {
        state[row] = .in_progress;
        try chain.append(self.gpa, row);
        defer {
            state[row] = .done;
            _ = chain.pop();
        }

        if (self.expansions.items[row].delegation) |delegate| {
            if (delegate.backing) |next| {
                if (state[next] == .in_progress) {
                    try self.delegationError(self.expansions.items[row].member, "a delegated projection reaches itself");
                } else if (state[next] != .done) {
                    try self.walkExpansion(next, state, chain);
                }
            }
            return;
        }
        var found: std.ArrayList(ExprId) = .empty;
        defer found.deinit(self.gpa);
        try self.bracketsOf(self.expansions.items[row].path, .whole, &found);

        for (found.items) |bracket| {
            const next = self.projected_at.get(bracket) orelse continue;
            if (state[next] == .in_progress) {
                const at = std.mem.indexOfScalar(u32, chain.items, next).?;
                try self.reportProjectionCycle(chain.items[at..], bracket);
                return;
            }
            if (state[next] == .done) continue;
            try self.walkExpansion(next, state, chain);
        }
    }

    /// `[T-Projection]`'s cycle sentence, naming the chain in the order the
    /// walk above reached it and closing it by repeating where it started.
    fn reportProjectionCycle(
        self: *Checker,
        chain: []const u32,
        closing: ExprId,
    ) std.mem.Allocator.Error!void {
        var names: std.ArrayList(u8) = .empty;
        defer names.deinit(self.gpa);
        for (chain) |row| {
            if (names.items.len != 0) try names.appendSlice(self.gpa, " -> ");
            try names.appendSlice(self.gpa, self.nameOfExpansion(row));
        }
        try names.appendSlice(self.gpa, " -> ");
        try names.appendSlice(self.gpa, self.nameOfExpansion(chain[0]));

        try self.sink.addErrorFmt(
            .t_projection,
            self.ast.fileOfExpr(closing),
            self.ast.exprSpan(closing),
            "this is where the chain returns to an implementation already on it",
            "a projection whose expansion reaches itself is refused: {s}",
            .{names.items},
        );
    }

    /// What a chain names an implementation as: the type the head after
    /// `impl` wrote, carried onto every member it declares including the
    /// projection whose row this is.
    fn nameOfExpansion(self: *const Checker, row: u32) []const u8 {
        const expansion = self.expansions.items[row];
        const member = expansion.member;
        if (expansion.delegation) |forward| {
            if (forward.field == null) return self.ast.tokenText(self.ast.declName(member));
            return self.ast.tokenText(self.ast.declHead(member).name);
        }
        return self.ast.tokenText(self.ast.declOwner(member));
    }

    /// How the place a bracket names was written, which is what the label
    /// under it states the room as.
    ///
    /// The clause is one and the sentence is three: an index counts up from the
    /// start, a caret counts back from the end, and an exclusive end names the
    /// place after the last element it takes -- so a reader told the last index
    /// after writing `^0` or `..4` would be told the wrong number for what is
    /// on the page.
    const Wrote = enum { index, count_back, end };

    /// `at` is the index a reader wrote, which for a routed bracket is the
    /// site's rather than the one inside the implementation. `value` is the
    /// place it names, which for a count back from the end is the length less
    /// the count -- so what is held against the array is an index either way.
    fn refuseSettledIndex(
        self: *Checker,
        at: ExprId,
        count: u32,
        value: i128,
        wrote: Wrote,
    ) std.mem.Allocator.Error!bool {
        if (value >= 0 and Typing.elementSlot(count, @intCast(value), false) != null) return false;
        try self.sink.addErrorFmt(
            .t_index,
            self.ast.fileOfExpr(at),
            self.ast.exprSpan(at),
            if (count == 0)
                "this array holds nothing, so no index names an element of it"
            else switch (wrote) {
                .index => try std.fmt.allocPrint(
                    self.sink.arena,
                    "the length is {d}, so the last index is {d}",
                    .{ count, count - 1 },
                ),
                .count_back => try std.fmt.allocPrint(
                    self.sink.arena,
                    "the length is {d}, so the greatest count back is {d}",
                    .{ count, count },
                ),
                .end => try std.fmt.allocPrint(
                    self.sink.arena,
                    "the length is {d}, so the greatest end is {d}",
                    .{ count, count },
                ),
            },
            "no element sits here, and the length is part of the type",
            .{},
        );
        return true;
    }

    /// The settled clause, asked of every bracket that routes.
    ///
    /// Run after every body, because the array a projection's path reaches is
    /// typed where that path was checked and a site may be written above the
    /// implementation it reaches -- asking at the site would read a type the
    /// walk had not settled yet, for a program whose declaration order happens
    /// to put the use first.
    ///
    /// Only a step whose index *is* the parameter this site fills: `self.a[i]`
    /// is the site's own number, and `self.a[i + 1]` is an expression over it
    /// that nothing here folds. Every other step of the path carries a value
    /// written inside the implementation, and the clause already refused that
    /// one where the body was checked.
    ///
    /// A site counting back from an end is held to the same clause and named
    /// the way it was written: an implementation whose body hands the count
    /// on reaches an array, and the array is what the count is against.
    ///
    /// A composing implementation hands the site's number on: where the step
    /// that names the slot is itself a bracket that routes, the array is one
    /// path further down and the number held against it is still the one the
    /// reader wrote. Stopping at the first path would refuse `g[9]` over an
    /// array and admit it over a container wrapping the same array.
    ///
    /// **Bound:** the routed brackets of the program, and for each one the
    /// brackets of the paths its chain runs through, each entered once.
    const RangeVisit = struct {
        row: u32,
        args: []const TypeId,
        from_end: bool,
        const Context = struct {
            pub fn hash(_: @This(), key: RangeVisit) u64 {
                return std.hash.Wyhash.hash((@as(u64, key.row) << 1) | @intFromBool(key.from_end), std.mem.sliceAsBytes(key.args));
            }
            pub fn eql(_: @This(), a: RangeVisit, b: RangeVisit) bool {
                return a.row == b.row and a.from_end == b.from_end and std.mem.eql(TypeId, a.args, b.args);
            }
        };
    };
    const RangeVisits = std.HashMapUnmanaged(RangeVisit, void, RangeVisit.Context, std.hash_map.default_max_load_percentage);

    fn checkProjectedIndexRanges(self: *Checker) std.mem.Allocator.Error!void {
        var arguments: std.AutoHashMapUnmanaged(ExprId, []const TypeId) = .empty;
        defer arguments.deinit(self.gpa);
        try arguments.ensureTotalCapacity(self.gpa, @intCast(self.projected.items.len));
        for (self.projected.items) |site| arguments.putAssumeCapacity(ExprId.at(site.at), site.impl_args);
        for (self.projected.items) |site| {
            if (self.ast.exprTag(ExprId.at(site.at)) != .index) continue;
            const found = self.expansions.items[site.expansion];
            if (found.delegation == null and found.index == types_mod.Expansion.no_binding) continue;
            const wrote = self.ast.binary(ExprId.at(site.at)).rhs;
            const counts_back = self.foldedFromEnd(wrote);
            const value = counts_back orelse self.folds.get(wrote).valueOf() orelse continue;
            var visited: RangeVisits = .empty;
            defer {
                var keys = visited.keyIterator();
                while (keys.next()) |key| self.gpa.free(key.args);
                visited.deinit(self.gpa);
            }
            if (try self.settleThrough(site.expansion, site.impl_args, &visited, &arguments, wrote, value, counts_back != null)) {
                _ = self.selected_places.remove(ExprId.at(site.at));
                _ = self.record(ExprId.at(site.at), .poison);
            }
        }
    }

    fn projectionType(self: *Checker, expansion: types_mod.Expansion, ty: TypeId, args: []const TypeId) std.mem.Allocator.Error!TypeId {
        const owner = if (expansion.delegation) |forward| forward.owner orelse expansion.member else self.res.implEnclosing(expansion.member);
        if (owner == .none) return ty;
        return self.builder.substitute(ty, @intCast(owner.index()), args);
    }

    /// Follow each distinct instantiated projection once. Argument keys retain
    /// finite nesting of the same generic wrapper while stopping true cycles.
    fn settleThrough(
        self: *Checker,
        row: u32,
        impl_args: []const TypeId,
        visited: *RangeVisits,
        arguments: *const std.AutoHashMapUnmanaged(ExprId, []const TypeId),
        wrote: ExprId,
        value: i128,
        from_end: bool,
    ) std.mem.Allocator.Error!bool {
        const visit: RangeVisit = .{ .row = row, .args = impl_args, .from_end = from_end };
        if (visited.contains(visit)) return false;
        {
            const owned = try self.gpa.dupe(TypeId, impl_args);
            errdefer self.gpa.free(owned);
            try visited.put(self.gpa, .{ .row = row, .args = owned, .from_end = from_end }, {});
        }
        const found = self.expansions.items[row];
        if (found.delegation) |delegate| {
            const field_type = try self.projectionType(found, delegate.field_type, impl_args);
            if (delegate.deferred_trait) |trait| {
                const key = try self.projectionType(found, delegate.key_type, impl_args);
                if (self.builder.awaitsTypes(field_type, &.{key})) return false;
                const choice = try self.builder.implementationChoice(trait, &.{key}, field_type) orelse return false;
                const selected = choice.declaredImplementation() orelse return false;
                const implementation = self.implementations[selected.index()];
                if (!implementation.isAmbient()) {
                    const next = self.expansion_of_impl.get(implementation.decl) orelse return false;
                    return self.settleThrough(next, choice.impl_args, visited, arguments, wrote, value, from_end);
                }
            } else if (delegate.backing) |next| {
                const args = try self.gpa.alloc(TypeId, delegate.backing_args.len);
                defer self.gpa.free(args);
                for (delegate.backing_args, args) |arg, *into| into.* = try self.projectionType(found, arg, impl_args);
                return self.settleThrough(next, args, visited, arguments, wrote, value, from_end);
            }
            const array = switch (self.builder.get(field_type)) {
                .array => |array| array,
                else => return false,
            };
            const at = if (from_end) @as(i128, array.count) - value else value;
            return self.refuseSettledIndex(wrote, array.count, at, if (from_end) .count_back else .index);
        }
        if (found.index == types_mod.Expansion.no_binding) return false;
        var refused = false;
        var steps: std.ArrayList(ExprId) = .empty;
        defer steps.deinit(self.gpa);
        try self.bracketsOf(found.path, .whole, &steps);
        for (steps.items) |step| {
            const parts = self.ast.binary(step);
            const fills = self.fillsTheSlot(parts.rhs, found.index) orelse continue;
            const back = from_end or fills == .back;
            const head = try self.projectionType(found, self.builder.exprType(parts.lhs), impl_args);
            switch (self.builder.get(head)) {
                .array => |array| {
                    const at = if (back) @as(i128, array.count) - value else value;
                    const rejected = try self.refuseSettledIndex(wrote, array.count, at, if (back) .count_back else .index);
                    refused = refused or rejected;
                },
                else => {
                    const next = self.projected_at.get(step) orelse continue;
                    const written_args = arguments.get(step) orelse &.{};
                    const args = try self.gpa.alloc(TypeId, written_args.len);
                    defer self.gpa.free(args);
                    for (written_args, args) |arg, *into| into.* = try self.projectionType(found, arg, impl_args);
                    const rejected = try self.settleThrough(next, args, visited, arguments, wrote, value, back);
                    refused = refused or rejected;
                },
            }
        }
        return refused;
    }

    /// Whether an expression is exactly the parameter a bracket fills, so what
    /// the site wrote stands where it is written.
    fn namesTheSlot(self: *const Checker, id: ExprId, binding: u32) bool {
        const at = self.ast.withoutGroups(id);
        if (self.ast.exprTag(at) != .name_ref) return false;
        const target = self.res.targetOf(at);
        return target != BindingId.none and target.index() == binding;
    }

    /// Whether the parameter this site fills stands in a bracket, and which end
    /// the path reads it from.
    ///
    /// A caret inside a path counts by the number the site wrote, so the place
    /// the bracket names is the length less that number -- and the clause is
    /// asked through the same reading the address is formed through, or an
    /// index the site settled reaches a place the array does not have with no
    /// check emitted to catch it.
    ///
    /// Only the parameter itself, at either end: `self.a[i]` and `self.a[^i]`
    /// are the site's own number, and `self.a[i + 1]` is an expression over it
    /// that nothing here folds. Every other step of the path carries a value
    /// written inside the implementation, and the clause already refused that
    /// one where the body was checked.
    fn fillsTheSlot(self: *const Checker, id: ExprId, binding: u32) ?enum { up, back } {
        const at = self.ast.withoutGroups(id);
        if (self.ast.exprTag(at) == .from_end) {
            return if (self.namesTheSlot(self.ast.unaryOperand(at), binding)) .back else null;
        }
        return if (self.namesTheSlot(at, binding)) .up else null;
    }

    /// How far into a place a rule reaches.
    ///
    /// A write lands through the spine alone: a bracket standing inside another
    /// bracket's index expression is read to work out an offset, so what it
    /// grants a site is a read. Everything else asks about the whole path,
    /// because an index expression is spliced into the site exactly as the
    /// spine it sits in is.
    const PathReach = enum { spine, whole };

    /// Every bracket a place expression holds, in the order the walk reaches
    /// them.
    ///
    /// One walk for every rule about a path, driven by the tree's own step
    /// walk: what the rules differ in is how far in they reach, which is the
    /// argument, and not which spellings are places. A rule that spelled the
    /// descent out for itself would hold for the formers its author had in mind
    /// and stop early at the one added afterwards -- which is a disagreement
    /// none of them could see, since each would still be right about the
    /// spellings it knew.
    ///
    /// **Bound:** the nodes of this one expression, each visited once.
    fn bracketsOf(
        self: *const Checker,
        id: ExprId,
        reach: PathReach,
        out: *std.ArrayList(ExprId),
    ) std.mem.Allocator.Error!void {
        var steps = self.ast.placeSteps(id);
        while (steps.next()) |step| {
            if (self.ast.exprTag(step) != .index) continue;
            try out.append(self.gpa, step);
            if (reach == .whole) try self.bracketsWithin(self.ast.binary(step).rhs, out);
        }
    }

    /// Every bracket an expression that is not itself a place holds.
    ///
    /// An index expression is an operator expression over what is in scope, so
    /// a bracket may sit anywhere inside one -- under an operator, or among an
    /// array literal's elements. The forms that would carry a block or a
    /// conditional are refused where the body is read, so there is nothing to
    /// descend into for those and no place a bracket could hide.
    fn bracketsWithin(
        self: *const Checker,
        id: ExprId,
        out: *std.ArrayList(ExprId),
    ) std.mem.Allocator.Error!void {
        if (id == ExprId.none) return;
        const at = self.ast.withoutGroups(id);
        const tag = self.ast.exprTag(at);
        switch (tag) {
            .field, .index, .dereference => return self.bracketsOf(at, .whole, out),
            else => {},
        }
        switch (tag.payload()) {
            .none, .block, .conditional, .lambda => {},
            .unary => try self.bracketsWithin(self.ast.unaryOperand(at), out),
            .binary => {
                const parts = self.ast.binary(at);
                try self.bracketsWithin(parts.lhs, out);
                try self.bracketsWithin(parts.rhs, out);
            },
            .range => {
                const ends = self.ast.rangeEnds(at);
                try self.bracketsWithin(ends.lhs, out);
                try self.bracketsWithin(ends.rhs, out);
            },
            .call => {
                for (self.ast.call(at).args) |a| try self.bracketsWithin(a, out);
                if (tag == .struct_literal) try self.bracketsWithin(self.ast.call(at).callee, out);
            },
            .interpolation => for (self.ast.interpolation(at).pieces) |piece| try self.bracketsWithin(piece, out),
        }
    }

    /// Opens a walk over the chains an expansion reaches. Every walk gets a
    /// number of its own, so what one reached says nothing about the next.
    fn beginReach(self: *Checker) void {
        self.reach_mark += 1;
    }

    /// Whether this walk is reaching an expansion for the first time.
    fn firstReach(self: *Checker, row: u32) std.mem.Allocator.Error!bool {
        if (self.reach_marks.items.len <= row) {
            try self.reach_marks.appendNTimes(self.gpa, 0, row + 1 - self.reach_marks.items.len);
        }
        if (self.reach_marks.items[row] == self.reach_mark) return false;
        self.reach_marks.items[row] = self.reach_mark;
        return true;
    }

    const LiteralSpelling = enum { not_literal, nonnegative, negated };

    /// Whether an expression is an integer literal under any parentheses and
    /// negations, which the literal and negation checks type from the position
    /// alone, and whether an odd number of negations applies to it.
    fn integerLiteralSpelling(self: *const Checker, id: ExprId) LiteralSpelling {
        var at = self.ast.withoutGroups(id);
        var negated = false;
        while (self.ast.exprTag(at) == .negate) {
            negated = !negated;
            at = self.ast.withoutGroups(self.ast.unaryOperand(at));
        }
        if (self.ast.exprTag(at) != .int_literal) return .not_literal;
        return if (negated) .negated else .nonnegative;
    }

    /// A bracket over a container: the place that type's `Index` implementation
    /// projects, and the element that implementation bound.
    ///
    /// Found through the lookup a bound is discharged through, keyed by the
    /// trait, what the index expression settled to, and the head -- so a
    /// bracket reaches exactly the implementation a bound naming `Index` would
    /// admit, and a head with none is refused by the rule a comparison over a
    /// type without `Comparable` is refused by.
    ///
    /// The expansion is recorded here and nowhere else. Lowering emits the path
    /// this names rather than asking again which implementation the bracket
    /// reached: a second routing rule would be free to reach a different
    /// implementation from the one whose element type the site was checked
    /// against.
    ///
    /// **Bound:** one index lookup per site, plus `integerIndexKey`'s
    /// per-receiver candidates for an integer literal, and one walk of a
    /// projection's own path the first time an implementation is reached.
    fn checkProjected(
        self: *Checker,
        id: ExprId,
        head: TypeId,
        expected: ?Expected,
    ) std.mem.Allocator.Error!TypeId {
        const b = self.ast.binary(id);

        // An integer literal has no type of its own, so it takes the one
        // integer key the container is indexed by. Several keys are refused
        // rather than chosen by whether the value happens to fit one; with
        // none the literal keeps `UInt64`, and the missing implementation is
        // reported as for any other key. Anything else settles on its own,
        // and what it settled to is the key.
        const spelling = self.integerLiteralSpelling(b.rhs);
        const literal_key: ?Expected = if (spelling != .not_literal) blk: {
            const inferred = try self.integerIndexKey(self.generic, head);
            const key: TypeId = switch (inferred) {
                .one => |key| key,
                // With no key, a nonnegative literal keeps the counting type,
                // and a negated one its own, so the missing implementation is
                // what is reported rather than the literal's range.
                .none => if (spelling == .negated) break :blk null else .u64,
                .many => |keys| {
                    _ = try self.check(b.rhs, null);
                    _ = self.report(
                        .t_infer,
                        b.rhs,
                        "`{s}` is indexed by more than one integer type, including `{s}` and `{s}`",
                        .{ (try self.typeName(head)), (try self.typeName(keys[0])), (try self.typeName(keys[1])) },
                        "write the key with the type you mean",
                    );
                    return self.record(id, .poison);
                },
            };
            break :blk .{
                .ty = key,
                .at = .{ .file = self.ast.fileOfExpr(id), .span = self.ast.exprSpan(id) },
                .reason = if (inferred == .one) .index_key else .index_position,
            };
        } else null;
        const checked_index = try self.check(b.rhs, literal_key orelse try self.rangeIndexExpected(id, b.rhs));
        if (checked_index == .poison) return self.record(id, .poison);
        if (checked_index == .never) return self.expect(id, .never, expected);
        // A key whose type is still open takes the one integer key the
        // container is indexed by, as a literal written there would; with
        // several it needs a type now.
        const index = if (self.builder.get(checked_index) == .open_integer) switch (try self.integerIndexKey(self.generic, head)) {
            .one => |key| settled: {
                _ = try self.meet(checked_index, key, self.literalSite(b.rhs));
                break :settled try self.builder.resolveOpen(checked_index, &self.open_types);
            },
            // With no key the counting type, except for a negated literal,
            // which keeps the type a negative value has.
            .none => if (spelling == .negated)
                try self.forceInteger(checked_index, self.literalSite(b.rhs))
            else settled: {
                _ = try self.meet(checked_index, .u64, self.literalSite(b.rhs));
                break :settled try self.builder.resolveOpen(checked_index, &self.open_types);
            },
            .many => try self.forceInteger(checked_index, self.literalSite(b.rhs)),
        } else checked_index;

        return switch (try self.projectionAt(id, head, index)) {
            .place => |settled| self.finishSelection(id, settled, expected),
            // No library declaring the trait, so no type implements it and the
            // answer is the one every head with no implementation gets.
            .no_trait => self.report(
                .t_bound,
                b.lhs,
                "`{s}` does not implement `Index`",
                .{(try self.typeName(head))},
                "index an array",
            ),
            .unimplemented => blk: {
                try reportMissingImplementation(
                    self.gpa,
                    self.sink,
                    self.ast,
                    &self.builder,
                    self.index_decl.?,
                    &.{index},
                    head,
                    self.ast.fileOfExpr(b.lhs),
                    self.ast.exprSpan(b.lhs),
                    try self.unmetLabel(.{ .otherwise = "", .another_value = "index it with a key it implements `Index` for" }, try self.editFor(self.index_decl.?, &.{index}, head, false, 0)),
                );
                break :blk self.record(id, .poison);
            },
            .unusable => self.record(id, .poison),
        };
    }

    /// What the implementation reached by a bracket over `head` at `index`
    /// answers with, recorded against `at` for lowering to splice.
    ///
    /// One routine, because two constructs reach a projection: a bracket a
    /// reader wrote, and a lending walk, which is a bracket per position. Two
    /// lookups would be free to reach different implementations, and the walk
    /// would splice a path whose element the binder was never checked against.
    ///
    /// Why nothing was found is answered rather than reported, because the two
    /// callers name different things in the sentence: a bracket says the head
    /// does not implement `Index`, and a walk says the type has no place a
    /// position reaches.
    ///
    /// **Bound:** one index lookup, and one walk of a projection's own path the
    /// first time an implementation is reached.
    const Projection = union(enum) {
        /// The element the place holds, with the expansion recorded.
        place: TypeId,
        /// No library declaring `Index`, so nothing implements it.
        no_trait,
        /// Nothing implements it for this head at this index.
        unimplemented,
        /// A row the compiler provides, or one whose projection was refused
        /// where its body was read: there is no path to splice either way.
        unusable,
    };

    fn projectionAt(
        self: *Checker,
        at: ExprId,
        head: TypeId,
        index: TypeId,
    ) std.mem.Allocator.Error!Projection {
        const trait = self.index_decl orelse return .no_trait;

        const args = [_]TypeId{index};
        const choice = try self.builder.implementationChoiceWithin(self.generic, trait, &args, head) orelse return .unimplemented;
        if (choice.supplier == .bound) {
            const elem = self.index_elem orelse return .unusable;
            const settled = try self.builder.settledAt(trait.index(), &args, head, elem, "Elem");
            const row: u32 = @intCast(self.expansions.items.len);
            const enclosing = self.res.implEnclosing(self.generic);
            const owner = if (enclosing != .none) enclosing else self.generic;
            try self.expansions.append(self.gpa, .{
                .member = self.generic,
                .path = .none,
                .receiver = types_mod.Expansion.no_binding,
                .index = types_mod.Expansion.no_binding,
                .delegation = .{
                    .owner = owner,
                    .deferred_trait = trait,
                    .field_type = head,
                    .key_type = index,
                },
            });
            {
                const impl_args = try self.gpa.dupe(TypeId, self.param_types[owner.index()]);
                errdefer self.gpa.free(impl_args);
                try self.projected.append(self.gpa, .{ .at = @intCast(at.index()), .expansion = row, .impl_args = impl_args });
            }
            try self.projected_at.put(self.gpa, at, row);
            return .{ .place = settled };
        }
        const found = self.implementations[(choice.declaredImplementation() orelse return .unusable).index()];
        // Concrete arrays use checkIndex's built-in path; an ambient row
        // has no authored projection to splice here.
        if (found.isAmbient()) return .unusable;

        // An implementation whose projection was refused has no path to splice,
        // and the refusal is already reported where the body was read.
        const row = try self.expansionOf(found.decl) orelse return .unusable;
        {
            const impl_args = try self.gpa.dupe(TypeId, choice.impl_args);
            errdefer self.gpa.free(impl_args);
            try self.projected.append(self.gpa, .{ .at = @intCast(at.index()), .expansion = row, .impl_args = impl_args });
        }
        try self.projected_at.put(self.gpa, at, row);

        const elem = self.index_elem orelse return .unusable;
        const settled = try self.builder.settledBy(found, elem, choice.impl_args) orelse return .unusable;
        return .{ .place = settled };
    }

    /// Where an implementation's expansion sits, worked out the first time a
    /// bracket reaches it.
    ///
    /// The path is the implementation's rather than the site's, so it is read
    /// off the tree once and named by every bracket over the type. What a site
    /// contributes is the two expressions filling its slots, which is why
    /// nothing here is keyed by an expression.
    fn expansionOf(self: *Checker, impl: node.DeclId) std.mem.Allocator.Error!?u32 {
        if (self.expansion_of_impl.get(impl)) |row| return row;

        if (self.ast.declDelegation(impl) != .none) return self.settleDelegation(impl);

        const sig = self.index_at orelse return null;
        // The pair the implementation walk settled, read rather than matched
        // again by the name the two share.
        const supplied = self.supply.memberOf(impl, sig) orelse return null;
        const member = supplied;

        const body = self.ast.declBody(member);
        if (body == .none or self.ast.exprTag(body) != .block) return null;
        const held = self.ast.blockOf(body);
        const path = held.tail;
        if (path == ExprId.none or self.ast.blockStmts(held).len != 0) return null;
        // A path rooted anywhere but the receiver is refused by
        // `checkProjectionBody`, and splicing it into a site would walk
        // whatever it names -- a local of the body, instantiated at a larger
        // type with every hop -- as if the receiver held it.
        if (!self.storagePlaceCall(self.ast.withoutGroups(path)) and !self.rootedAtReceiver(member, self.ast.withoutGroups(path))) return null;

        // The two slots, by position: the receiver the path is rooted at, and
        // the parameter a bracket's own index expression fills. A path built
        // from field selections alone names no index, and there is then nothing
        // for the second to fill.
        var receiver: u32 = types_mod.Expansion.no_binding;
        var index: u32 = types_mod.Expansion.no_binding;
        for (self.res.parametersOf(member)) |p| switch (self.res.paramIndexOf(p)) {
            0 => receiver = @intCast(p.index()),
            1 => index = @intCast(p.index()),
            else => {},
        };
        if (receiver == types_mod.Expansion.no_binding) return null;

        const row: u32 = @intCast(self.expansions.items.len);
        try self.expansions.append(self.gpa, .{
            .member = member,
            .path = path,
            .receiver = receiver,
            .index = index,
            .writable = self.ast.declParams(member).len != 0 and
                accessGranted(self.ast.declParams(member)[0].convention) >= accessGranted(.inout),
        });
        try self.expansion_of_impl.put(self.gpa, impl, row);
        return row;
    }

    /// Settle a field delegate in its implementation's generic environment.
    /// Each declaration is visited once; backing edges are followed recursively.
    fn settleDelegation(self: *Checker, impl: node.DeclId) std.mem.Allocator.Error!?u32 {
        if (self.expansion_of_impl.get(impl)) |row| return row;
        const field_token = self.ast.declDelegation(impl);
        if (field_token == .none) return null;
        if (self.delegation_state.get(impl)) |state| {
            if (state == .in_progress) try self.delegationError(impl, "a delegated projection reaches itself");
            return null;
        }
        try self.delegation_state.put(self.gpa, impl, .in_progress);
        defer self.delegation_state.getPtr(impl).?.* = .done;
        const implementation = (self.rowFor(impl) orelse return null).*;
        const trait = self.index_decl orelse return null;
        const elem = self.index_elem orelse return null;
        if (implementation.trait != trait.index() or implementation.args.len != 1) return null;
        const previous_module = self.current;
        const previous_generic = self.generic;
        self.current = self.program.moduleOf(impl);
        self.generic = impl;
        defer {
            self.current = previous_module;
            self.generic = previous_generic;
        }
        const declaration = self.declaringType(implementation.ty) orelse {
            try self.delegationError(impl, "field delegation requires a named type with stored fields");
            return null;
        };
        if (self.program.moduleOf(declaration) != self.current) {
            try self.delegationError(impl, "declare field delegation in the type's defining module");
            return null;
        }
        const field = self.builder.lookupField(implementation.ty, self.ast.tokenText(field_token)) orelse {
            try self.delegationError(impl, "the delegated name is not a stored field of this type");
            return null;
        };
        try self.field_names.put(self.gpa, field_token, .{ .receiver = implementation.ty, .field = @enumFromInt(field.index) });
        const key = implementation.args[0];
        var delegate: types_mod.DelegatedProjection = .{ .field_name = self.ast.tokenName(field_token), .field = field.index, .field_type = field.ty, .key_type = key };
        var settled: TypeId = .poison;
        switch (self.builder.get(field.ty)) {
            .array => |array| {
                const integer = self.builder.isIntegerWithin(impl, key);
                const from_end = if (self.fromEndType()) |back| key == back else false;
                if (!integer and !(from_end and try self.arrayInterprets(field.ty, key))) {
                    try self.delegationError(impl, "the backing array does not support this element indexing key");
                    return null;
                }
                settled = array.element;
            },
            else => {
                const choice = try self.builder.implementationChoiceWithin(impl, trait, &.{key}, field.ty) orelse {
                    try self.delegationError(impl, "the backing field does not implement `Index` for this key");
                    return null;
                };
                if (choice.supplier == .bound) {
                    delegate.deferred_trait = trait;
                    settled = try self.builder.settledAt(@intCast(trait.index()), &.{key}, field.ty, elem, "Elem");
                } else {
                    const selected = choice.declaredImplementation() orelse {
                        try self.delegationError(impl, "the backing field has no concrete indexing projection");
                        return null;
                    };
                    const backing = self.implementations[selected.index()];
                    delegate.backing = try self.expansionOf(backing.decl) orelse return null;
                    settled = try self.builder.settledBy(backing, elem, choice.impl_args) orelse return null;
                    delegate.backing_args = try self.gpa.dupe(TypeId, choice.impl_args);
                }
            },
        }
        errdefer self.gpa.free(delegate.backing_args);
        self.decl_returns.set(impl, settled);
        _ = try self.reportUndischarged(self.ast.declName(elem), self.ast.declBounds(elem), .{
            .source = .{ .scope = .{ .module = self.program.moduleOf(elem), .owner = elem } },
            .decl = elem,
            .settled = &.{},
        }, settled, field_token, self.ast.tokenSpan(field_token));
        const row: u32 = @intCast(self.expansions.items.len);
        try self.expansion_of_impl.put(self.gpa, impl, row);
        try self.expansions.append(self.gpa, .{
            .member = impl,
            .path = .none,
            .receiver = types_mod.Expansion.no_binding,
            .index = types_mod.Expansion.no_binding,
            .delegation = delegate,
        });
        return row;
    }

    fn delegationError(self: *Checker, impl: node.DeclId, message: []const u8) std.mem.Allocator.Error!void {
        const at = self.ast.declDelegation(impl);
        try self.sink.addErrorFmt(.t_projection, self.ast.fileOf(at), self.ast.tokenSpan(at), "delegate to a stored field with a valid indexing projection", "{s}", .{message});
    }

    /// Refuses a write through a place its implementation grants only a read
    /// of.
    ///
    /// The mode on a projection's receiver is a ceiling: the most a site's
    /// position may reach through the place the projection names. Reading sits
    /// below every ceiling a trait can declare, so this is asked exactly where
    /// a position writes -- an assignment's target and an argument lent
    /// `inout` -- and the root's own mutability is the part-write rule, which
    /// is unchanged and asked where it always was.
    ///
    /// The ceiling is asked of every implementation the write runs through,
    /// which is the site's own brackets and, for each, the brackets on the path
    /// it splices in. A container composing another writes through the inner
    /// one's place, so the inner one's `self` is as much a ceiling on the site
    /// as the outer one's -- otherwise any module defeats another's `read self`
    /// by wrapping the value in a structure of one field.
    ///
    /// The spine, because that is where the write lands: what a bracket's index
    /// expression reaches is read to work out an offset, and reading sits below
    /// every ceiling a trait can declare.
    ///
    /// Run after every body: an implementation a site composes may sit below
    /// that site in the file, and the brackets on its path are recorded where
    /// its own body is read.
    ///
    /// **Bound:** the brackets of this one path, and of each path its chain
    /// runs through, each entered once.
    fn checkWriteCeilings(self: *Checker) std.mem.Allocator.Error!void {
        var rows: std.AutoHashMapUnmanaged(ExprId, usize) = .empty;
        defer rows.deinit(self.gpa);
        try rows.ensureTotalCapacity(self.gpa, @intCast(self.projected.items.len));
        for (self.projected.items, 0..) |site, i| rows.putAssumeCapacity(ExprId.at(site.at), i);
        var found: std.ArrayList(ExprId) = .empty;
        defer found.deinit(self.gpa);

        for (self.written.items) |site| {
            if (self.readonly_places.contains(self.ast.withoutGroups(site.at))) {
                _ = self.report(.n_immutable, site.at, "an observation grants read-only access to its place", .{}, site.refused);
                continue;
            }
            found.clearRetainingCapacity();
            try self.bracketsOf(site.at, .spine, &found);

            self.beginReach();
            // The site may be the place itself rather than hold one. A lending
            // walk names one place per position and writes no bracket, so a
            // walk looking only for brackets would find nothing to hold it to.
            if (self.projected_at.get(site.at)) |row| {
                if (rows.get(site.at)) |i| self.projected.items[i].requires_write = true;
                _ = try self.refuseCeilingThrough(site.at, row, site.refused);
            }
            for (found.items) |bracket| {
                const row = self.projected_at.get(bracket) orelse continue;
                if (rows.get(bracket)) |i| self.projected.items[i].requires_write = true;
                _ = try self.refuseCeilingThrough(bracket, row, site.refused);
            }
        }
    }

    /// Whether some implementation on this chain refused the write, reported at
    /// the bracket the reader wrote rather than at the line inside the
    /// implementation that splices it.
    ///
    /// Stops at the first refusal on a chain: the outermost one names the
    /// declaration a reader has to change, and what sits under a place already
    /// refused is not a second mistake.
    fn refuseCeilingThrough(
        self: *Checker,
        at: ExprId,
        row: u32,
        refused: []const u8,
    ) std.mem.Allocator.Error!bool {
        if (!try self.firstReach(row)) return false;
        if (self.expansions.items[row].delegation) |delegate| {
            // Discovery discharges the recorded write requirement after the
            // bound's concrete backing implementation has been selected.
            if (delegate.deferred_trait != null) return false;
            if (delegate.backing) |next| return self.refuseCeilingThrough(at, next, refused);
            return false;
        }
        if (try self.reportCeiling(at, self.expansions.items[row].member, refused)) return true;

        var found: std.ArrayList(ExprId) = .empty;
        defer found.deinit(self.gpa);
        try self.bracketsOf(self.expansions.items[row].path, .spine, &found);

        for (found.items) |bracket| {
            const next = self.projected_at.get(bracket) orelse continue;
            if (try self.refuseCeilingThrough(at, next, refused)) return true;
        }
        return false;
    }

    /// Says that the implementation reached here hands its elements out to be
    /// read, naming the `self` that says so, and whether it said anything.
    ///
    /// The declaration is on another line and is what a reader has to change,
    /// which is the same reason an assignment to a `let` names the `let`.
    fn reportCeiling(
        self: *Checker,
        at: ExprId,
        member: node.DeclId,
        refused: []const u8,
    ) std.mem.Allocator.Error!bool {
        const params = self.ast.declParams(member);
        if (params.len == 0) return false;
        const receiver = params[0];
        if (accessGranted(receiver.convention) >= accessGranted(.inout)) return false;

        const labels = try self.sink.arena.alloc(Label, 2);
        labels[0] = .{
            .file = self.ast.fileOf(receiver.name),
            .span = self.ast.tokenSpan(receiver.name),
            .message = "declared `read` here",
            .style = .secondary,
        };
        labels[1] = .{
            .file = self.ast.fileOfExpr(at),
            .span = self.ast.exprSpan(at),
            .message = refused,
            .style = .primary,
        };
        try self.sink.add(.{
            .severity = .err,
            .code = .n_immutable,
            .message = "a bracket reaches as far as the implementation's `self` declares, and this one declares `read`",
            .labels = labels,
        });
        return true;
    }

    fn checkStructLiteral(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const c = self.ast.call(id);
        const base = self.ast.structLiteralBase(id);

        const want = if (self.ast.structLiteralHead(id)) |head|
            try self.typeOfRef(head)
        else
            Expected.typeOf(expected) orelse {
                try self.checkLiteralValues(id);
                return self.report(
                    .t_infer,
                    id,
                    "the type of this literal cannot be determined",
                    .{},
                    "give the binding a type, or name one",
                );
            };
        if (want == .poison) {
            // Nothing known about the literal says what a field must be, so
            // each value is checked on its own under the same unknown
            // context: what is wrong inside one is still reported, and
            // nothing is held against a type nobody knows.
            const unknown: Expected = .{
                .ty = .poison,
                .at = .{ .file = self.ast.fileOfExpr(id), .span = self.literalHeadSpan(id) },
                .reason = .field,
            };
            var i: usize = 1;
            while (i < c.args.len) : (i += 2) _ = try self.check(c.args[i], unknown);
            if (base) |written| _ = try self.check(written, unknown);
            return self.record(id, .poison);
        }
        self.builder.setConstruction(id, want);

        if (self.raw_accesses.slice != .none and self.builder.view().declOfType(want) == self.raw_accesses.slice) {
            try self.checkLiteralValues(id);
            return self.report(.t_borrow_contract, id, "a span must originate from a checked span primitive", .{}, "observe initialized storage or derive a subspan");
        }
        if (self.sealedHere(want)) {
            try self.checkLiteralValues(id);
            return self.reportSealed(id, want, "only its own module can build one");
        }

        const count = self.builder.fieldCount(want);
        const empty_struct = if (self.declaringType(want)) |declaration|
            self.ast.declTag(declaration) == .struct_
        else
            false;
        if (count == 0 and !empty_struct) {
            try self.checkLiteralValues(id);
            return self.report(
                .t_unknown_field,
                id,
                "`{s}` has no fields",
                .{(try self.typeName(want))},
                "only a struct is built this way",
            );
        }

        // Which fields were given, so a missing one and a repeated one are two
        // questions answered from one pass.
        var given = try self.gpa.alloc(bool, count);
        defer self.gpa.free(given);
        @memset(given, false);

        var poisoned = false;
        var diverges = false;
        var i: usize = 0;
        while (i + 1 < c.args.len) : (i += 2) {
            // A label the parser could not read was reported there; its value
            // is still an expression whose own mistakes are reported.
            if (self.ast.exprTag(c.args[i]) == .err) {
                _ = self.record(c.args[i], .poison);
                _ = try self.check(c.args[i + 1], null);
                poisoned = true;
                continue;
            }
            const name = self.ast.tokenText(self.ast.exprMain(c.args[i]));
            _ = self.record(c.args[i], .unit);

            const at = if (self.builder.lookupField(want, name)) |found| found.index else {
                _ = self.report(.t_unknown_field, c.args[i], "`{s}` has no field `{s}`", .{ (try self.typeName(want)), name }, "not a field of this type");
                _ = try self.check(c.args[i + 1], null);
                poisoned = true;
                continue;
            };

            try self.field_names.put(self.gpa, self.ast.exprMain(c.args[i]), .{ .receiver = want, .field = @enumFromInt(at) });

            if (given[at]) {
                _ = self.report(.t_duplicate_field, c.args[i], "`{s}` is given twice", .{name}, "already given above");
                poisoned = true;
            }
            given[at] = true;

            // The field's type flows into its value, so a literal takes it the
            // way an argument takes its parameter's type.
            const v = try self.check(c.args[i + 1], .{
                .ty = self.builder.fieldType(want, at),
                .at = .{ .file = self.ast.fileOfExpr(c.args[i]), .span = self.ast.exprSpan(c.args[i]) },
                .reason = .field,
                .inference = if (expected) |context| context.inference else null,
            });
            if (v == .poison) poisoned = true;
            if (v == .never) diverges = true;
        }

        // The base is written last and checked last, against the literal's
        // own type: every field it supplies is a field of that type.
        if (base) |written| {
            const b = try self.check(written, .{
                .ty = want,
                .at = .{ .file = self.ast.fileOfExpr(id), .span = self.literalHeadSpan(id) },
                .reason = .update_base,
                .inference = if (expected) |context| context.inference else null,
            });
            if (b == .poison) poisoned = true;
            if (b == .never) diverges = true;
        }

        // A literal's values form one exclusivity domain, as call arguments
        // do. Written evaluation order does not permit one initializer to
        // observe a place another mutates, and the base is one of the values.
        try self.checkLiteralExclusivity(id);

        if (base) |written| {
            // A base the literal takes none of would be consumed only to be
            // dropped.
            if (std.mem.indexOfScalar(bool, given, false) == null and !poisoned) {
                _ = self.report(
                    .t_unused_base,
                    written,
                    "`{s}` supplies no field",
                    .{self.ast.exprText(written)},
                    "every field is written, so nothing is taken from here",
                );
                poisoned = true;
            }
        } else for (given, 0..) |had, f| {
            if (had) continue;
            _ = self.report(
                .t_missing_field,
                id,
                "`{s}` is not given a value",
                .{self.builder.fieldName(want, @intCast(f))},
                "every field is given one",
            );
            poisoned = true;
        }

        if (poisoned) return self.record(id, .poison);
        if (diverges) return self.expect(id, .never, expected);

        return self.expect(id, want, expected);
    }

    /// Checks a structure literal's values and base with nothing expected, for
    /// a literal refused before its fields could be matched: each value is
    /// still an expression whose own mistakes are reported.
    fn checkLiteralValues(self: *Checker, id: ExprId) std.mem.Allocator.Error!void {
        const c = self.ast.call(id);
        var i: usize = 1;
        while (i < c.args.len) : (i += 2) _ = try self.check(c.args[i], null);
        if (self.ast.structLiteralBase(id)) |base| _ = try self.check(base, null);
    }

    /// Where a structure literal says what type it builds: its written head,
    /// or its opening `.{` where the type comes from context.
    fn literalHeadSpan(self: *const Checker, id: ExprId) Span {
        if (self.ast.structLiteralHead(id)) |head| return self.ast.writtenSpan(head);
        return self.ast.tokenSpan(self.ast.exprMain(id));
    }

    fn variantOrdinal(self: *const Checker, id: ExprId) ?u32 {
        return types_mod.variantOrdinalOf(&self.res.variant_ordinals, &self.variant_uses, id);
    }

    /// `Shape.Circle(3)`. A variant that carries something is built by handing
    /// it the value, which is the spelling its declaration already uses.
    fn checkConstruct(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const c = self.ast.call(id);
        // Parentheses around the callee do not change which variant it names.
        const callee = self.ast.withoutGroups(c.callee);
        self.noteQualifier(callee);

        // A variant carries values rather than filling parameters: nothing
        // here declares one for a name to reach.
        try self.refuseNames(id, self.ast.tokenText(self.ast.exprMain(callee)));

        // A generic enum named without arguments is a template, and a template
        // is not a type. Where nothing expects one, the payload says what the
        // arguments are -- so the expectation is manufactured here and the
        // ordinary path runs against a real instantiation.
        //
        // The values inference checked are read as it checked them on every
        // path below. Checking one again would report its mistakes again and
        // record each value of an interpolated literal again.
        const walked = try self.gpa.alloc(bool, c.args.len);
        defer self.gpa.free(walked);
        @memset(walked, false);
        const inferred = try self.inferConstruct(id, expected, walked);
        if (inferred == .reported) {
            for (c.args, walked) |a, w| if (!w) {
                _ = try self.check(a, null);
            };
            return self.record(id, .poison);
        }

        // The callee carries this call's expectation, so `.Circle(3)` takes
        // its enum from context exactly as `.Square` does.
        // An unknown type expected here leaves an unqualified variant
        // unknown too, which was reported where the type was written; its
        // values are then checked under that same unknown context.
        const unknown = if (expected) |want| want.ty == .poison and self.res.targetOf(callee) == BindingId.none else false;
        const variant_expected = if (expected) |want|
            if (unknown or self.builder.variantCount(want.ty) != 0) want else null
        else
            null;
        const previous_callee = self.construction_callee;
        self.construction_callee = callee;
        const t = try self.check(c.callee, switch (inferred) {
            .made => |m| m,
            else => variant_expected,
        });
        self.construction_callee = previous_callee;
        if (t == .poison) {
            for (c.args, walked) |a, w| if (!w) {
                _ = try self.check(a, if (unknown) expected else null);
            };
            return self.record(id, .poison);
        }

        if (self.sealedHere(t)) {
            for (c.args, walked) |a, w| if (!w) {
                _ = try self.check(a, null);
            };
            return self.reportSealed(id, t, "only its own module can build one");
        }

        const shape = self.constructorShape(callee, t);
        const k = shape.ordinal;
        const carries: usize = shape.payloads;
        if (c.args.len != carries) {
            for (c.args, walked) |a, w| if (!w) {
                _ = try self.check(a, null);
            };
            return self.report(
                .t_arity,
                id,
                "expected {d} value(s), found {d}",
                .{ carries, c.args.len },
                "the wrong number of values",
            );
        }

        // Each value's type flows into its argument, so a literal takes it the
        // way an argument to a function takes its parameter's type.
        var argument_diverges = false;
        for (c.args, walked, 0..) |a, w, j| {
            const want: Expected = .{
                .ty = self.builder.variantFieldType(t, k, @intCast(j)),
                .at = .{ .file = self.ast.fileOfExpr(c.callee), .span = self.ast.exprSpan(c.callee) },
                .reason = .payload,
                .inference = if (expected) |e| e.inference else null,
            };
            const found = if (w)
                try self.expect(a, self.builder.exprType(a), want)
            else
                try self.check(a, want);
            if (found == .never) argument_diverges = true;
        }

        if (argument_diverges) {
            try self.checkExclusivity(c.args, ExprId.none);
            return self.expect(id, .never, expected);
        }

        // What a variant carries is one list evaluated in some order, as a
        // call's arguments are.
        try self.checkExclusivity(c.args, ExprId.none);
        const settled = if (expected) |want| if (want.inference) |slots| try self.callableContext(t, slots) else t else t;
        _ = self.record(c.callee, settled);
        return self.expect(id, settled, expected);
    }

    /// Every implementation supplies exactly what its trait declares.
    ///
    /// Both halves are one walk, because both are answered by comparing two
    /// lists of names -- and a rule that read one list twice would be two
    /// rules that could come to disagree about which members an `impl` has.
    /// What an entry point answering `Result` must carry.
    ///
    /// The spelling is [S-Entry]'s and the resolver settles it; what the two
    /// alternatives hold is a question about types, so it is settled here. The
    /// success is the exit status, so it is a `UInt8` for the same reason the
    /// plain spelling is. The failure is rendered on the way out, so it
    /// implements `Display` -- and nothing else could render it, because a
    /// compiler spelling a message is not what a rendering trait is for.
    ///
    /// Both were assumed by lowering before they were checked here. A success
    /// of another type read a byte out of a payload that had none and became a
    /// compiler defect rather than a diagnosis, and a failure with no
    /// implementation rendered nothing at all.
    fn checkEntryAnswer(self: *Checker) std.mem.Allocator.Error!void {
        const d = self.res.entry;
        if (d == node.DeclId.none) return;

        const answers = self.decl_returns.get(d);
        const carrier = self.carrierOf(answers) orelse return;
        if (carrier.kind != .result) return;

        const at = self.ast.declReturnRef(d).name;
        if (at == TokenId.none) return;
        const file = self.ast.fileOfDecl(d);
        const held = self.view();

        const status = held.variantFieldType(answers, carrier.success, 0);
        if (status != .u8 and status != .poison) {
            try self.sink.addError(
                .s_entry,
                file,
                self.ast.tokenSpan(at),
                "a program's `main` answers `UInt8` on success, which is the exit status",
                try std.fmt.allocPrint(self.sink.arena, "this one answers `{s}`", .{(try self.typeName(status))}),
            );
        }

        try self.checkFailureRenders(
            d,
            at,
            held.variantFieldType(answers, carrier.failure, 0),
            "a failure leaving the program is rendered, so it implements `Display`",
        );
    }

    /// That a failure leaving a declaration can describe itself.
    ///
    /// Asked of the entry point and of every test, because both hand a failure
    /// to the same reporting and neither has anywhere else to put one. One
    /// routine rather than two: what it means for a value to describe itself is
    /// a single question, and a second answer to it is one that can come to
    /// disagree on the type nobody wrote a case for.
    ///
    /// The lead differs because what the failure is leaving differs; the rule
    /// and the code it reports do not.
    fn checkFailureRenders(
        self: *Checker,
        d: node.DeclId,
        at: TokenId,
        failure: TypeId,
        lead: []const u8,
    ) std.mem.Allocator.Error!void {
        if (failure == .poison) return;
        const display = self.display_decl orelse return;
        if (try implementsAnyOf(self.gpa, &self.impl_index, self.implementations, &self.builder, display, failure)) return;

        try self.sink.addError(
            .t_bound,
            self.ast.fileOfDecl(d),
            self.ast.tokenSpan(at),
            lead,
            try std.fmt.allocPrint(self.sink.arena, "`{s}` does not", .{(try self.typeName(failure))}),
        );
    }

    /// What a test answers.
    ///
    /// The entry point's rule with `()` where the exit status goes: a test has
    /// no status to report and no value anything could read, so what is left is
    /// whether it failed and what the failure was.
    fn checkTestAnswers(self: *Checker) std.mem.Allocator.Error!void {
        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            if (!self.ast.declIsTest(d)) continue;
            // An `extern` is a function by tag, so the tag alone does not
            // settle it, and the parser has already refused the modifier here.
            if (self.ast.declTag(d) != .function) continue;
            if (self.ast.declIsExtern(d)) continue;

            // Asked of the reference and not of its name token. An array is a
            // written type carrying no name, and reading that as "no return
            // type was written" is what let the entry point's own rule be
            // bypassed by answering `[UInt8; 3]`. The same guard here would
            // buy the same bypass.
            const written = self.ast.declReturnRef(d);
            if (!written.wasWritten()) continue;

            if (written.kind == .array) {
                const at = self.locOfWritten(written);
                try self.sink.addError(
                    .s_test,
                    at.file,
                    at.span,
                    "a test answers `Result[(), E]`, which is whether it failed",
                    "this is not a `Result`",
                );
                continue;
            }
            const at = written.at;

            const answers = self.decl_returns.get(d);

            // A type nothing settled was already reported by whatever failed to
            // settle it. Saying so again would name it `<unknown>`, which is
            // what this compiler calls a type it does not have rather than
            // anything a reader wrote.
            if (answers == .poison) continue;

            const carrier = self.carrierOf(answers) orelse {
                try self.sink.addError(
                    .s_test,
                    self.ast.fileOfDecl(d),
                    self.ast.writtenSpan(written),
                    "a test answers `Result[(), E]`, which is whether it failed",
                    try std.fmt.allocPrint(self.sink.arena, "this one answers `{s}`", .{(try self.typeName(answers))}),
                );
                continue;
            };
            if (carrier.kind != .result) {
                try self.sink.addError(
                    .s_test,
                    self.ast.fileOfDecl(d),
                    self.ast.tokenSpan(at),
                    "a test answers `Result[(), E]`, which is whether it failed",
                    try std.fmt.allocPrint(self.sink.arena, "this one answers `{s}`", .{(try self.typeName(answers))}),
                );
                continue;
            }

            const held = self.view();

            // Nothing reads what a test produces, so there is nothing for it to
            // answer with but the absence of a value.
            const success = held.variantFieldType(answers, carrier.success, 0);
            if (success != .unit and success != .poison) {
                try self.sink.addError(
                    .s_test,
                    self.ast.fileOfDecl(d),
                    self.ast.tokenSpan(at),
                    "a test answers `()` on success, because nothing reads what it produced",
                    try std.fmt.allocPrint(self.sink.arena, "this one answers `{s}`", .{(try self.typeName(success))}),
                );
            }

            try self.checkFailureRenders(
                d,
                at,
                held.variantFieldType(answers, carrier.failure, 0),
                "a test's failure is rendered when it fails, so it implements `Display`",
            );
        }
    }

    /// Which member of each implementation supplies which member of its trait.
    ///
    /// Settled before any body is walked, because a type written `Self.Item`
    /// is read through it: what an implementation settled is this pairing and
    /// the paired member's own written type, and a signature, an annotation or
    /// a call may each name one.
    ///
    /// The pair is written down here and nowhere else. A member sits in no
    /// namespace and is found by the name it shares with what it supplies, so
    /// a reader that wanted the pair and did not have it matched that name
    /// again -- which made the spelling the whole of the relation and stopped
    /// either name from being renameable.
    ///
    /// **Bound:** one declaration scan, then per implementation an O(log D)
    /// extent lookup and expected O(T + M) name indexing and pairing, for D
    /// program declarations, T trait members and M declarations in the extent.
    /// Temporary name storage is O(M), owned by the implementation's walk.
    fn pairImplementationMembers(self: *Checker) std.mem.Allocator.Error!void {
        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            if (self.ast.declTag(d) != .impl_) continue;

            const trait_token = self.ast.declTrait(d);
            if (trait_token == TokenId.none) continue;
            const trait_decl = traitAt(self.ast, self.res, trait_token) orelse continue;

            // With nothing for the trait's own parameters to stand for there
            // is nothing to pair a member against, and the mistake is the
            // arguments. Reported where the implementation is checked, and the
            // members left alone here as they are left alone there.
            if (!self.suppliesTheTraitsArguments(d, trait_decl)) continue;

            if (self.ast.declDelegation(d) != .none) {
                if (self.index_decl == null or trait_decl != self.index_decl.?) {
                    try self.sink.addErrorFmt(.t_impl, self.ast.fileOf(trait_token), self.ast.tokenSpan(trait_token), "write ordinary members for this trait", "field delegation is supported only for `Index`", .{});
                    continue;
                }
                if (self.index_elem) |elem| try self.supplied.append(self.gpa, .{ .impl = d, .sig = elem, .member = d });
                continue;
            }

            const members = self.decls.within(self.ast.declTokens(d));
            var members_by_name: std.AutoHashMapUnmanaged(StringId, node.DeclId) = .empty;
            defer members_by_name.deinit(self.gpa);
            for (members) |member| {
                if (member == d or !suppliesSomething(self.ast, member)) continue;
                const name = self.ast.tokenName(self.ast.declName(member));
                const slot = try members_by_name.getOrPut(self.gpa, name);
                // Source order chooses the first supplier even when duplicate
                // declarations have already made the implementation invalid.
                if (!slot.found_existing) slot.value_ptr.* = member;
            }
            for (self.decls.ownedBy(self.ast.declName(trait_decl))) |sig| {
                if (!asksForSomething(self.ast, sig)) continue;

                const member = members_by_name.get(self.ast.tokenName(self.ast.declName(sig))) orelse {
                    // An implementation refused as overlapping another has
                    // been reported once, for the overlap.
                    if (self.overlapping.contains(d)) continue;
                    // Nothing of that name at all: the hole a bound promises
                    // is filled by nothing, and a call through the trait would
                    // reach it. Said here, where the pairing found nothing,
                    // rather than by a second walk asking the same question of
                    // the same two lists.
                    try self.sink.addErrorFmt(
                        .t_impl,
                        self.ast.fileOf(trait_token),
                        self.ast.tokenSpan(trait_token),
                        if (settlesAType(self.ast, sig))
                            "settle it, or drop it from the trait"
                        else
                            "supply a body for it, or drop it from the trait",
                        "`{s}` declares `{s}`, and this implementation does not supply it",
                        .{ self.ast.tokenText(trait_token), self.ast.tokenText(self.ast.declName(sig)) },
                    );
                    continue;
                };

                // A trait declares operations, projections and types, and a
                // member answers the one it was declared as: a body where a
                // type was asked for settles nothing, a type where an
                // operation was asked for is a call with nothing to run, and a
                // function where a projection was asked for returns a value
                // where a bracket needs a place. Refused where the two are
                // paired, because a pair disagreeing about which kind it is is
                // not one -- and nothing below may read it as either.
                const asked = memberKind(self.ast, sig);
                const answered = memberKind(self.ast, member);
                if (asked != answered) {
                    try self.sink.addErrorFmt(
                        // A projection on either side makes this the rule that
                        // says what a projection is, and a reader sent to that
                        // prose learns why the two cannot stand for each other.
                        if (asked == .projection or answered == .projection) .t_projection else .t_impl,
                        self.ast.fileOf(self.ast.declName(member)),
                        self.ast.tokenSpan(self.ast.declName(member)),
                        "supply the member the trait declares",
                        "`{s}` declares `{s}` as {s}, and this implementation supplies {s}",
                        .{
                            self.ast.tokenText(trait_token),
                            self.ast.tokenText(self.ast.declName(sig)),
                            asked.noun(),
                            answered.noun(),
                        },
                    );
                    continue;
                }

                try self.supplied.append(self.gpa, .{
                    .impl = d,
                    .sig = sig,
                    .member = member,
                });
            }
        }
    }

    /// Whether an implementation supplies the number of arguments its trait
    /// declares.
    ///
    /// Asked by the walk that pairs the members and by the walk that checks
    /// them, because neither may look at a member until it is answered: with
    /// nothing for the trait's `T` to stand for, every member would be refused
    /// for taking a type the trait never asked for. One routine for the two,
    /// so they cannot come to disagree about which implementations those are.
    fn suppliesTheTraitsArguments(
        self: *const Checker,
        impl: node.DeclId,
        trait: node.DeclId,
    ) bool {
        return self.suppliedBy(impl).len == self.ast.declTypeParams(trait).len;
    }

    /// What each implementation settled each declared type to, and whether the
    /// bound its declaration carries admits that.
    ///
    /// Read once per pair and recorded where a declaration's written type is,
    /// because that is the answer every `Self.Item` is read through: worked out
    /// per settled reference instead, one question would have an answer per use
    /// of it. The bound is asked here for the same reason -- a settling is
    /// where a type stands against it, and asking again at each use would ask
    /// the same question of the same type.
    ///
    /// After the pairing is complete, so a settled type written in terms of
    /// another is read through the same record as any other settled reference.
    ///
    /// Representation filling and instance refilling precede this check so
    /// effective capabilities include every owned part and logical storage
    /// element. Unfilled fields cannot prove a capability bound.
    ///
    /// **Bound:** one written type per pair the walk above recorded, and one
    /// index lookup per bound that pair's declaration wrote.
    fn settleDeclaredTypes(self: *Checker) std.mem.Allocator.Error!void {
        // What an implementation settles a declared type to is read out of the
        // pool, so every instantiation in it must already hold what its
        // template holds. One minted earlier holds nothing, and a settling
        // read off it is an empty type rather than a wrong one -- which no
        // case can tell from a right one.
        std.debug.assert(self.builder.refilled);

        const outer_module = self.current;
        const outer_generic = self.generic;
        defer {
            self.current = outer_module;
            self.generic = outer_generic;
        }

        for (self.supplied.items) |pair| {
            const member = pair.member;
            if (!settlesAType(self.ast, member)) continue;

            const written = self.ast.declReturnRef(member);

            // A settled reference is read through what an implementation
            // settled, so one written here asks the question this line answers.
            // Refused rather than resolved: settling them in some order would
            // make what a type is depend on which of the trait's declarations
            // came first, and a chain the order ran backwards would settle to
            // nothing at all -- silently, because there is nothing left to
            // report it against.
            if (firstSelfSettledRef(self.ast, written)) |found| {
                self.decl_returns.set(pair.member, .poison);
                try self.sink.addErrorFmt(
                    .t_impl,
                    self.ast.fileOf(found.at),
                    self.ast.writtenSpan(found),
                    "write the type itself",
                    "a settled type is not written as a settled reference",
                    .{},
                );
                continue;
            }

            self.current = self.program.moduleOf(member);
            self.generic = member;
            const settled = try self.typeOfRefOf(self.current, member, written);
            self.decl_returns.set(pair.member, settled);
            if (settled == .poison) continue;

            // The bound the declaration carries, discharged here because here
            // is where a type stands against it: settling is what answers the
            // trait, and every `Self.Item` below reads that answer rather than
            // asking the question again per use.
            //
            // At the arguments the declaration wrote, read in the scope that
            // wrote them. Nothing open can stand there, so there is nothing to
            // substitute and the reading is the same one recorded on every
            // settled reference to this name.
            const declared = pair.sig;
            const bounds = self.ast.declBounds(declared);
            if (bounds.len == 0) continue;

            // What is underlined is the type as it was written. An array
            // writes no head, so what stands in for it there is the settling
            // declaration's own name -- the one token every settled type has.
            const wrote_a_head = written.name != TokenId.none;
            const at = if (wrote_a_head) written.name else self.ast.declName(member);
            const span = if (wrote_a_head)
                self.ast.writtenSpan(written)
            else
                self.ast.tokenSpan(at);

            _ = try self.reportUndischarged(
                self.ast.declName(declared),
                bounds,
                .{
                    .source = .{ .scope = .{ .module = self.program.moduleOf(declared), .owner = declared } },
                    .decl = declared,
                    .settled = &.{},
                },
                settled,
                at,
                span,
            );
        }
    }

    fn checkImplementations(self: *Checker) std.mem.Allocator.Error!void {
        const index = &self.decls;

        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            if (self.ast.declTag(d) != .impl_) continue;
            if (self.suppressed_generated_implementations.contains(d)) continue;

            const previous_generic = self.generic;
            const previous_module = self.current;
            self.generic = d;
            // Reports here are read in the implementation's module, so a type
            // is written as that module writes it.
            self.current = self.program.moduleOf(d);
            defer {
                self.generic = previous_generic;
                self.current = previous_module;
            }

            // Asked of every implementation, including one naming no trait: a
            // head is a written type wherever it stands, and an inherent
            // implementation names one too.
            try self.checkHeadArity(d);

            const trait_token = self.ast.declTrait(d);
            if (trait_token == TokenId.none) {
                if (self.ast.declDelegation(d) != .none)
                    try self.delegationError(d, "field delegation requires an `Index` trait implementation");
                try self.refuseInherentProjections(d);
                continue;
            }

            const trait_decl = traitAt(self.ast, self.res, trait_token) orelse continue;
            // An implementation the resolver refused, for being written where
            // neither its trait nor its type is declared, answers for nothing,
            // so what its trait requires of it is not asked: that refusal is
            // the one mistake.
            if (self.res.isRefusedImpl(d)) continue;

            // What this implementation answers for the trait's parameters,
            // read from the record that keys it. Computed once, where the
            // record is built: an implementation's arguments are what
            // coherence compares and what a symbol carries, so a second
            // reading here would be a second answer to the question those
            // depend on.
            const trait_args = self.suppliedBy(d);

            // A trait's parameters are as much of what it declares as its
            // signatures are, and an implementation supplying the wrong number
            // of them has nothing for a signature's parameter to be read as.
            // Reported here and the members left alone: every one of them
            // would then be refused for taking a type the trait never asked
            // for, which is a consequence of this rather than a second
            // mistake.
            const declares = self.ast.declTypeParams(trait_decl).len;
            if (!self.suppliesTheTraitsArguments(d, trait_decl)) {
                try self.sink.addErrorFmt(
                    .t_impl,
                    self.ast.fileOf(trait_token),
                    self.ast.tokenSpan(trait_token),
                    if (declares == 0) "this trait takes no arguments" else "supply the arguments it declares",
                    "`{s}` takes {d} type argument(s), and this supplies {d}",
                    .{ self.ast.tokenText(trait_token), declares, trait_args.len },
                );
                continue;
            }

            // A trailing predicate is part of the trait's contract just as a
            // bound beside one of its parameters is. The implementation's
            // supplied trait arguments settle both spellings.
            const receiver = (self.rowFor(d) orelse continue).ty;
            const trait_constraints = self.constraints.rangeOfDeclaration(trait_decl);
            for (trait_constraints.start..trait_constraints.end) |constraint_at| {
                const constraint = self.constraints.records[constraint_at];
                switch (constraint.subject) {
                    .parameter => |parameter_index| {
                        if (parameter_index >= trait_args.len) continue;
                        _ = try self.reportUndischarged(
                            constraint.named,
                            self.constraints.requirementsOf(constraint),
                            .{
                                .source = .{ .parameter = self.param_types[trait_decl.index()][parameter_index] },
                                .decl = trait_decl,
                                .settled = trait_args,
                            },
                            trait_args[parameter_index],
                            trait_token,
                            self.ast.tokenSpan(trait_token),
                        );
                    },
                    .written => |subject| {
                        const held = if (self.writtenTypeMentionsSelf(subject))
                            try self.selfConstraintAtImplementation(d, receiver, subject)
                        else
                            try self.builder.substitute(
                                self.constraint_subjects[constraint_at],
                                trait_decl.index(),
                                trait_args,
                            );
                        if (held == .poison) continue;
                        _ = try self.reportUndischarged(
                            constraint.named,
                            self.constraints.requirementsOf(constraint),
                            .{
                                .source = .{ .scope = .{ .module = self.program.moduleOf(trait_decl), .owner = trait_decl } },
                                .decl = trait_decl,
                                .settled = trait_args,
                            },
                            held,
                            trait_token,
                            self.ast.tokenSpan(trait_token),
                        );
                    },
                }
            }

            // What the trait itself requires of every type implementing it,
            // both halves of it.
            //
            // Discharged here because here is where a type stands against it:
            // a trait admitting the type promises the required trait's
            // operations exist on it, and a body bounded on this trait calls
            // them; a `Copyable` among the bounds promises the type owes nothing,
            // which is a promise about the very type this implementation
            // names. Asked through the reader every other bound list is read
            // through, so a trait's own bound admits the types a type
            // parameter's does.
            //
            // At the arguments the trait wrote them at: `trait Fancy:
            // Lookup[UInt64]` promises an implementation of `Lookup` at
            // `UInt64` and none of `Lookup` at anything else, and a body
            // bounded on `Fancy` calls the operation that promise names. Read
            // in the trait's own scope, since a required trait's arguments may
            // name the requiring trait's parameters, and settled by what this
            // implementation supplied for them.
            //
            // **Bound:** the bounds this one trait wrote, and one index lookup
            // each.
            _ = try self.reportUndischarged(
                self.ast.declName(trait_decl),
                self.ast.declBounds(trait_decl),
                .{
                    .source = .{ .scope = .{ .module = self.program.moduleOf(trait_decl), .owner = trait_decl } },
                    .decl = trait_decl,
                    .settled = trait_args,
                },
                receiver,
                trait_token,
                self.ast.tokenSpan(trait_token),
            );

            if (self.ast.declDelegation(d) != .none) continue;

            // Every signature the trait declares, found among this
            // implementation's members.
            const extent = self.ast.declTokens(d);
            const members = index.within(extent);
            var required_names: std.AutoHashMapUnmanaged(StringId, void) = .empty;
            defer required_names.deinit(self.gpa);
            // The operations the trait provides, which no implementation
            // supplies: one body answers for every type implementing it.
            var provided_names: std.AutoHashMapUnmanaged(StringId, void) = .empty;
            defer provided_names.deinit(self.gpa);
            for (index.ownedBy(self.ast.declName(trait_decl))) |sig| {
                if (self.ast.declIsProvided(sig)) try provided_names.put(self.gpa, self.ast.tokenName(self.ast.declName(sig)), {});
                if (!asksForSomething(self.ast, sig)) continue;
                // A declared name remains required even when its supplier's
                // kind prevents pairing or its signature is later refused.
                try required_names.put(self.gpa, self.ast.tokenName(self.ast.declName(sig)), {});

                // The pair the walk above settled, which is the same pair
                // lowering reads to find the body a call runs. Read rather
                // than found again: a rule that paired the members a second
                // time would be a second answer to which member supplies
                // which, and the two could come to disagree. A signature the
                // record does not pair is one the pairing already reported.
                const at = self.supply.memberOf(d, sig) orelse continue;

                // A settled type is the whole of what a declared type asked
                // for. There are no parameters to line up and no body to hold
                // to a signature, which is what the walk below compares.
                if (settlesAType(self.ast, sig)) continue;
                try self.checkMemberMatches(.t_impl, receiver, trait_token, trait_decl, trait_args, sig, at);
                try self.warnShadowed(d, receiver, sig, at);
            }

            // And nothing else. The local set takes O(T) storage and expected
            // O(T + M) name work across T signatures and M members.
            for (members) |mem| {
                // The `impl` itself carries the trait it names, and sits in
                // its own extent. It is what declares the members rather than
                // one of them.
                if (mem == d) continue;
                if (self.ast.declTrait(mem) != trait_token) continue;

                if (provided_names.contains(self.ast.tokenName(self.ast.declName(mem)))) {
                    try self.sink.addErrorFmt(
                        .t_impl,
                        self.ast.fileOf(self.ast.declName(mem)),
                        self.ast.tokenSpan(self.ast.declName(mem)),
                        "drop it: every type implementing the trait runs the trait's own body",
                        "`{s}` provides `{s}`, and an implementation does not supply it",
                        .{ self.ast.tokenText(trait_token), self.ast.tokenText(self.ast.declName(mem)) },
                    );
                    continue;
                }
                if (!required_names.contains(self.ast.tokenName(self.ast.declName(mem)))) {
                    const kind = memberKind(self.ast, mem);
                    try self.sink.addErrorFmt(
                        // An implementation may not introduce a projection its
                        // trait does not declare, which is the rule that says
                        // what a projection is rather than the one about what
                        // an implementation supplies.
                        if (kind == .projection) .t_projection else .t_impl,
                        self.ast.fileOf(self.ast.declName(mem)),
                        self.ast.tokenSpan(self.ast.declName(mem)),
                        switch (kind) {
                            .declared_type => "declare it on the trait, or drop it",
                            // An inherent `impl` is where a member a trait does
                            // not declare belongs, and a projection is the one
                            // member that may not go there.
                            .projection => "declare it on the trait, or drop it",
                            .operation => "declare it on the trait, or move it to an inherent `impl`",
                        },
                        "`{s}` declares no `{s}`",
                        .{ self.ast.tokenText(trait_token), self.ast.tokenText(self.ast.declName(mem)) },
                    );
                }
            }
        }
    }

    /// Whether `member`'s body is exactly a call of `own` -- written
    /// `Type.op(a, b)`, or `a.op(b)` -- passing the member's own parameters in
    /// order, so the member and the operation it would be shadowed by run the
    /// same code. The postfix form reaches `own` because `own` is the type's
    /// operation a postfix call in this module takes, which is the premise of
    /// the warning this answers.
    ///
    /// **Bound:** one look at the body's tail and one per parameter.
    fn forwardsToOwn(self: *const Checker, receiver: TypeId, member: node.DeclId, own: node.DeclId) bool {
        const ast = self.ast;
        const res = self.res;
        const body = ast.declBody(member);
        if (body == ExprId.none or ast.exprTag(body) != .block) return false;
        const block = ast.blockOf(body);
        if (ast.blockStmts(block).len != 0 or block.tail == ExprId.none) return false;
        const tail = ast.withoutGroups(block.tail);
        if (ast.exprTag(tail) != .call) return false;
        const c = ast.call(tail);
        const callee = ast.withoutGroups(c.callee);
        if (ast.exprTag(callee) != .field) return false;
        const params = ast.declParams(member);
        const base = ast.withoutGroups(ast.unaryOperand(callee));
        if (params.len > 0 and ast.exprTag(base) == .name_ref and ast.tokenName(ast.exprMain(base)) == ast.tokenName(params[0].name) and
            res.targetOf(base) != BindingId.none and res.kindOf(res.targetOf(base)) == .parameter)
        {
            if (ast.tokenName(ast.exprMain(callee)) != ast.tokenName(ast.declName(own))) return false;
            return passesInOrder(ast, c.args, params[1..]);
        }
        const target = res.targetOf(callee);
        if (target == BindingId.none) {
            // A name a trait also declares is left to the checker, which
            // settles the type's own operation first where this module may
            // name it -- and `own` is one this module may name.
            if (!res.selectsThroughTrait(callee)) return false;
            if (ast.tokenName(ast.exprMain(callee)) != ast.tokenName(ast.declName(own))) return false;
            if (!self.namesType(ast.unaryOperand(callee), receiver)) return false;
        } else if (res.kindOf(target) != .function or res.declaredBy(target) != own) return false;
        return passesInOrder(ast, c.args, params);
    }

    /// Whether a call's arguments are exactly the named parameters, in order.
    fn passesInOrder(ast: *const Ast, args: []const ExprId, params: []const node.Param) bool {
        if (args.len != params.len) return false;
        for (args, params) |arg, param| {
            const at = ast.withoutGroups(arg);
            if (ast.exprTag(at) != .name_ref) return false;
            if (ast.tokenName(ast.exprMain(at)) != ast.tokenName(param.name)) return false;
        }
        return true;
    }

    /// Whether `base`, the name in front of a selection, names the type
    /// `held`: a primitive by its binding, and a declared type by its
    /// declaration.
    fn namesType(self: *const Checker, base: ExprId, held: TypeId) bool {
        const b = self.res.targetOf(base);
        if (b == BindingId.none) return false;
        if (self.aliasPathType(b)) |aliased| {
            if (self.genericAliasHead(b) == null) return aliased == held;
            const origin = self.builder.view().declOfType(held) orelse return false;
            return origin == self.declaringType(aliased);
        }
        if (self.res.builtinOf(b)) |primitive| return primitive == held;
        if (self.res.kindOf(b) != .declared_type) return false;
        const origin = self.builder.view().declOfType(held) orelse return false;
        return origin == self.res.declaredBy(b);
    }

    /// Warns where `member`, supplying the trait's `sig` for `receiver` in
    /// the implementation `impl`, shares its name with an operation the type
    /// declares itself that a postfix call written in this module could
    /// take: such a call reaches the type's own, so the trait's is reached
    /// only written out. The enumeration a call reads decides it, asked from
    /// the implementation's own module.
    ///
    /// The written-out form spells the trait as the implementation's header
    /// spelled it, which is a name this module can write, and puts the
    /// member's own first parameter where the receiver goes.
    fn warnShadowed(self: *Checker, impl: node.DeclId, receiver: TypeId, sig: node.DeclId, member: node.DeclId) std.mem.Allocator.Error!void {
        if (receiver == .poison or !postfixReaches(self.ast, sig)) return;
        const name = self.ast.tokenName(self.ast.declName(sig));
        try self.builder.prepareCapabilityWithin(self.generic, receiver);
        const pool = try self.builder.capabilityView();
        var own: std.ArrayList(Applicable) = .empty;
        defer own.deinit(self.gpa);
        var reach = self.reaching(&pool);
        reach.from = self.program.moduleOf(impl);
        try reach.ownNamed(self.gpa, receiver, name, &own);
        if (own.items.len == 0) return;
        // A member that only calls the type's own operation runs the same code
        // whichever one a postfix call reaches, so there is nothing to warn of.
        if (self.forwardsToOwn(receiver, member, own.items[0].sig)) return;

        // Whether every caller's postfix call reaches the type's own: asked
        // from no module, only a public one is in reach, and the reason it
        // is dropped otherwise says where a call does reach it. Calls
        // elsewhere reach this implementation's, and the warning says so.
        // A private operation this implementation's module reaches is
        // declared in that module, which is where the warning points, so it
        // is "this module" rather than a name: a one-file program's module
        // is named after a directory, or nothing when the file is in the
        // working directory.
        reach.from = .none;
        const scope: []const u8 = if (try reach.ownDropped(self.gpa, receiver, name)) |dropped| scoped: {
            if (dropped.sig != own.items[0].sig) break :scoped "";
            break :scoped switch (dropped.why) {
                .inaccessible => |held| switch (held) {
                    .module => " in this module",
                    .root => " in its root",
                    .public => unreachable,
                },
                .receiver => "",
            };
        } else "";
        const elsewhere: []const u8 = if (scope.len == 0) "" else "; a call elsewhere reaches this one";
        const written = self.ast.declTraitRef(impl);
        const trait_spelling = if (written.path.len() == 0)
            self.ast.tokenText(written.name)
        else
            self.ast.rangeSpan(.{ .start = written.path.start, .end = TokenId.at(written.name.index() + 1) }).slice(self.ast.partOf(written.name).source);
        const params = self.ast.declParams(member);
        const receiver_name = if (params.len == 0) "x" else self.ast.tokenText(params[0].name);
        const labels = try self.sink.arena.alloc(Label, 1);
        labels[0] = .{
            .file = self.ast.fileOf(self.ast.declName(member)),
            .span = self.ast.tokenSpan(self.ast.declName(member)),
            .message = try std.fmt.allocPrint(self.sink.arena, "reach it as `{s}.{s}({s})`", .{ trait_spelling, self.ast.tokenText(self.ast.declName(sig)), receiver_name }),
            .style = .primary,
        };
        try self.sink.add(.{
            .severity = .warning,
            .code = .n_shadowed,
            .message = try std.fmt.allocPrint(self.sink.arena, "`{s}` declares `{s}` itself, so a postfix call{s} reaches that one rather than this{s}", .{ self.ast.tokenText(self.ast.declOwner(own.items[0].sig)), self.ast.tokenText(self.ast.declName(sig)), scope, elsewhere }),
            .labels = labels,
        });
    }

    test "a private operation shadowing a trait's names the module the warning is in" {
        var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        const source: Source = .{ .path = "shadow.lin", .text =
            \\trait Priced { fn cents(self: Self) -> UInt64 }
            \\struct Coffee { shots: UInt64 }
            \\impl Coffee { fn cents(self: Coffee) -> UInt64 { self.shots } }
            \\impl Priced for Coffee { fn cents(self: Coffee) -> UInt64 { self.shots + 1 } }
            \\fn main() -> UInt8 {
            \\    let latte = Coffee { shots = 2 }
            \\    UInt8(latte.cents() + Priced.cents(latte))
            \\}
            \\
        };
        var interner: Interner = .empty;
        const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
        var ast = try parse(gpa, &source, .from(0), tokens, &sink);
        const resolved = try resolve_mod.resolveTree(gpa, &ast, &sink);
        _ = try typecheckTree(gpa, &resolved, &sink);
        try std.testing.expectEqual(@as(u32, 0), sink.error_count);
        try std.testing.expectEqual(@as(usize, 1), sink.items().len);
        try std.testing.expectEqualStrings(
            "`Coffee` declares `cents` itself, so a postfix call in this module reaches that one rather than this; a call elsewhere reaches this one",
            sink.items()[0].message,
        );
    }

    /// Returns the open `Self` of a source template: one parameter after the
    /// template's own, bounded by nothing. A member's written `Self` and its
    /// signature's are both read as this parameter.
    fn templateSelf(self: *Checker, template: node.DeclId) std.mem.Allocator.Error!TypeId {
        return self.builder.addParameter(
            "Self",
            @intCast(template.index()),
            @intCast(self.ast.declTypeParams(template).len),
            .unrestricted,
            &.{},
        );
    }

    /// Holds every inactive source template member to the trait signature the
    /// resolver paired it with. No implementation row is created: symbolic
    /// `Self` is an open parameter used only by the shared compatibility check.
    fn checkTemplateMembers(self: *Checker) std.mem.Allocator.Error!void {
        const outer_module = self.current;
        const outer_generic = self.generic;
        const outer_symbolic_owner = self.symbolic_self_owner;
        defer {
            self.current = outer_module;
            self.generic = outer_generic;
            self.symbolic_self_owner = outer_symbolic_owner;
        }

        for (0..self.program.source.ast.declCount()) |index| {
            const template = DeclId.at(@intCast(index));
            if (self.ast.declTag(template) != .template_impl) continue;
            const trait = traitAt(self.ast, self.res, self.ast.declTrait(template)) orelse continue;
            if (!try self.templateParametersMatch(template, trait)) try self.invalid_templates.put(self.gpa, template, {});
        }
        for (self.program.template_members) |plan| {
            const symbolic_self = try self.templateSelf(plan.template);
            self.current = self.program.moduleOf(plan.member);
            self.generic = plan.member;
            self.symbolic_self_owner = plan.member;
            const errors_before = self.sink.error_count;
            try self.checkMemberMatches(
                .t_template,
                symbolic_self,
                self.ast.declTrait(plan.template),
                plan.trait,
                self.param_types[plan.template.index()],
                plan.signature,
                plan.member,
            );
            if (self.sink.error_count != errors_before) {
                try self.invalid_templates.put(self.gpa, plan.template, {});
            }
        }

        // Expansion precedes type checking, so a source template refused
        // above may already have produced implementations. They carry no
        // independent mistake: suppress each in one descriptor walk before
        // ordinary implementation compatibility is checked.
        if (self.invalid_templates.count() != 0) {
            for (0..self.program.generatedImplementationCount()) |implementation_index| {
                const descriptor = self.program.generatedImplementation(.at(@intCast(implementation_index)));
                if (self.invalid_templates.contains(descriptor.template)) {
                    try self.suppressGeneratedImplementation(descriptor.generated_impl);
                }
            }
        }
    }

    fn templateParametersMatch(self: *Checker, template: DeclId, trait: DeclId) std.mem.Allocator.Error!bool {
        const parameters = self.ast.declTypeParams(template);
        if (parameters.len != self.ast.declTypeParams(trait).len) return false;
        for (parameters, 0..) |parameter, index| {
            const wanted = self.parameterBounds(trait, index);
            const got = self.parameterBounds(template, index);
            const wanted_traits = try self.traitsBounding(null, wanted);
            defer types_mod.freeBoundTraits(self.gpa, wanted_traits);
            const got_traits = try self.traitsBounding(null, got);
            defer types_mod.freeBoundTraits(self.gpa, got_traits);
            const same_capability = capabilityDemandedBy(self.ast, self.res, wanted, wanted_traits) == capabilityDemandedBy(self.ast, self.res, got, got_traits);
            const onto = self.param_types[trait.index()];
            const added = try self.unmatchedMemberBound(trait, template, trait, onto, wanted, got, onto, true);
            const omitted = try self.unmatchedMemberBound(trait, template, trait, onto, wanted, got, onto, false);
            if (same_capability and added == null and omitted == null) continue;
            try self.sink.addError(.t_template, self.ast.fileOf(parameter.name), self.ast.tokenSpan(parameter.name), "use the same bounds as the corresponding trait parameter", "template parameters must admit the same arguments as the trait");
            return false;
        }
        return true;
    }

    fn deinitCheckedTemplateRequirements(self: *Checker) void {
        for (self.checked_template_requirements) |requirements| {
            for (requirements) |checked| {
                if (checked.args.len > 0) self.gpa.free(checked.args);
            }
            if (requirements.len > 0) self.gpa.free(requirements);
        }
        if (self.checked_template_requirements.len > 0) self.gpa.free(self.checked_template_requirements);
        self.checked_template_requirements = &.{};
    }

    /// Validates and interns every source template requirement once, before any
    /// descriptor asks whether one of its component rows is discharged.
    fn validateTemplateRequirements(self: *Checker) std.mem.Allocator.Error!void {
        const checked = try self.gpa.alloc([]CheckedTemplateRequirement, self.ast.template_requirements.len);
        @memset(checked, &.{});
        self.checked_template_requirements = checked;

        const source_decl_count = self.program.source.ast.declCount();
        for (0..source_decl_count) |i| {
            const template = DeclId.at(@intCast(i));
            if (self.ast.declTag(template) != .template_impl) continue;

            const requirement_range = self.ast.templateRequirementRange(template);
            std.debug.assert(requirement_range.end >= requirement_range.start);
            std.debug.assert(requirement_range.end <= self.ast.template_requirements.len);
            const requirements = self.ast.templateRequirements(template);
            var template_valid = true;
            for (requirements, 0..) |requirement, requirement_offset| {
                const requirement_index = requirement_range.start + @as(u32, @intCast(requirement_offset));
                const bounds = self.ast.boundsIn(requirement.bounds);
                const row = try self.gpa.alloc(CheckedTemplateRequirement, bounds.len);
                @memset(row, .{});
                checked[requirement_index] = row;
                const requirement_valid = switch (requirement.kind) {
                    .components => try self.validateTemplateRequirement(template, requirement, row),
                    .derived_supertraits => try self.validateDerivedSupertraitRequirement(template, requirement),
                    .target => true,
                };
                template_valid = requirement_valid and template_valid;
            }
            if (!template_valid) try self.invalid_templates.put(self.gpa, template, {});
        }
    }

    fn validateDerivedSupertraitRequirement(
        self: *Checker,
        template: DeclId,
        requirement: node.TemplateRequirement,
    ) std.mem.Allocator.Error!bool {
        const trait_token = self.ast.declTrait(template);
        const trait = traitAt(self.ast, self.res, trait_token) orelse return false;
        for (self.ast.declBounds(trait)) |bound| {
            if (bound.kind != .named) continue;
            const supertrait = traitAt(self.ast, self.res, bound.named.name) orelse continue;
            if (bound.named.args.len() == 0 and self.ast.declTypeParams(supertrait).len == 0) continue;
            try self.sink.addErrorFmt(
                .t_template,
                self.ast.fileOf(requirement.selector),
                self.ast.tokenSpan(requirement.selector),
                "remove the structural-supertrait predicate, or make every direct supertrait take no arguments",
                "`{s}` has a generic direct supertrait, whose derived arguments this template does not state",
                .{self.ast.tokenText(trait_token)},
            );
            return false;
        }
        return true;
    }

    /// Interns one source requirement's arguments and owns every diagnostic or
    /// deferred bound check that process creates. A requirement is one promise
    /// however many bounds it contains, so its first invalid type is reported
    /// once under the template rule and the rest are recovery evidence only.
    fn validateTemplateRequirement(
        self: *Checker,
        template: DeclId,
        requirement: node.TemplateRequirement,
        checked: []CheckedTemplateRequirement,
    ) std.mem.Allocator.Error!bool {
        const diagnostics_start = self.sink.items().len;
        const errors_before = self.sink.error_count;
        const warnings_before = self.sink.warning_count;
        const reported_start = self.refusalMark();
        const bound_sites_start = self.bound_sites.items.len;
        defer self.forgetRefusalsSince(reported_start);
        defer self.bound_sites.shrinkRetainingCapacity(bound_sites_start);

        const outer_generic = self.generic;
        defer self.generic = outer_generic;
        self.generic = template;

        var valid = true;
        const bounds = self.ast.boundsIn(requirement.bounds);
        for (bounds, checked) |bound, *slot| {
            if (bound.kind != .named) {
                valid = false;
                continue;
            }
            const trait = traitAt(self.ast, self.res, bound.named.name) orelse {
                valid = false;
                continue;
            };
            slot.trait = trait;

            const wanted = self.ast.declTypeParams(trait).len;
            const written = bound.named.args.len();
            if (wanted != written) {
                valid = false;
                try self.sink.addErrorFmt(
                    .t_template,
                    self.ast.fileOf(bound.named.name),
                    self.ast.tokenSpan(bound.named.name),
                    "supply exactly the type arguments the required trait declares",
                    "`{s}` takes {d} type argument(s), and this component requirement gives {d}",
                    .{ self.ast.tokenText(bound.named.name), wanted, written },
                );
                continue;
            }

            slot.args = try self.internTemplateRequirementBoundArgs(.{
                .module = self.program.moduleOf(template),
                .owner = template,
            }, bound);
            slot.valid = true;
            for (slot.args) |arg| {
                if (arg != .poison) continue;
                slot.valid = false;
                valid = false;
            }
        }

        var first_error: ?Diagnostic = null;
        for (self.sink.items()[diagnostics_start..]) |diagnostic| {
            if (diagnostic.severity != .err) continue;
            first_error = diagnostic;
            break;
        }
        if (first_error != null) valid = false;
        if (!valid) {
            for (checked) |*slot| slot.valid = false;
        }

        // All diagnostics since the checkpoint belong to this one requirement.
        // Keep their arena-backed text alive, but expose only the first as the
        // template-owned aggregate.
        self.sink.list.shrinkRetainingCapacity(diagnostics_start);
        self.sink.error_count = errors_before;
        self.sink.warning_count = warnings_before;
        if (first_error) |captured| {
            var diagnostic = captured;
            diagnostic.code = .t_template;
            try self.sink.add(diagnostic);
        }
        return valid;
    }

    /// Interns one requirement bound's closed arguments in source order and
    /// immediately checks any generic applications each argument creates.
    /// Ordinary bounds keep their deferred path through `internedBoundArgs`;
    /// only template requirements own diagnostics at this earlier boundary.
    fn internTemplateRequirementBoundArgs(
        self: *Checker,
        context: BoundInterning,
        bound: node.TraitBound,
    ) std.mem.Allocator.Error![]const TypeId {
        const written = self.ast.typeArgs(bound.named.args);
        if (written.len == 0) return &.{};

        const out = try self.gpa.alloc(TypeId, written.len);
        errdefer self.gpa.free(out);
        for (written, out) |argument, *slot| {
            const sites_start = self.bound_sites.items.len;
            slot.* = try self.typeOfRefOf(context.module, context.owner, argument);

            var site_at = sites_start;
            while (site_at < self.bound_sites.items.len) : (site_at += 1) {
                const site = self.bound_sites.items[site_at];
                const instance = self.builder.instanceOf(site.ty) orelse continue;
                self.generic = site.within;
                try self.checkArgumentBounds(
                    instance.decl,
                    self.builder.argsOf(instance),
                    null,
                    site.at,
                );
            }
        }
        return out;
    }

    /// Discharges every component row through the ordinary implementation
    /// index under the generated implementation's written constraint context.
    fn checkComponentRequirements(self: *Checker) std.mem.Allocator.Error!void {
        const outer_module = self.current;
        const outer_generic = self.generic;
        defer {
            self.current = outer_module;
            self.generic = outer_generic;
        }

        try self.withdrawDiscardableReleaseRequirements();
        for (0..self.program.generatedImplementationCount()) |implementation_index| {
            const implementation_id: GeneratedImplementationId = .at(@intCast(implementation_index));
            const descriptor = self.program.generatedImplementation(implementation_id);
            if (self.invalid_templates.contains(descriptor.template)) {
                try self.suppressGeneratedImplementation(descriptor.generated_impl);
                continue;
            }

            // The entry's written arguments are types of the source request, so
            // the lengths they write are typed here, as the generated
            // implementation's copy is typed on its own.
            const entry_arguments = self.ast.deriveTrait(descriptor.derive_trait).ref.args;
            for (self.ast.typeArgs(entry_arguments)) |argument| {
                self.current = self.program.moduleOf(descriptor.target);
                self.generic = if (self.ast.declTag(descriptor.derive) == .derive_impl) descriptor.derive else descriptor.target;
                _ = try self.typeOfRefOf(self.current, self.generic, argument);
            }

            self.current = self.program.moduleOf(descriptor.generated_impl);
            self.generic = descriptor.generated_impl;
            const implementation_index_in_rows = self.row_of_impl[descriptor.generated_impl.index()];
            if (implementation_index_in_rows == impl_of_none) continue;
            const implementation = self.implementations[implementation_index_in_rows];
            const target_arguments = self.builder.appliedTo(implementation.ty);
            const RequirementKey = struct { requirement: node.TemplateRequirementId, bound: expanded_mod.RequirementBoundOrdinal };
            var argument_sets: std.AutoHashMapUnmanaged(RequirementKey, []const TypeId) = .empty;
            defer {
                var values = argument_sets.valueIterator();
                while (values.next()) |arguments| self.gpa.free(arguments.*);
                argument_sets.deinit(self.gpa);
            }
            for (self.program.componentRequirements(implementation_id)) |row| {
                const requirement = self.ast.template_requirements[row.requirement.index()];
                const bound_index: usize = @intCast(@intFromEnum(row.bound));
                const bound = self.ast.boundsIn(requirement.bounds)[bound_index];
                const checked = self.checked_template_requirements[row.requirement.index()][bound_index];
                if (!checked.valid) {
                    try self.suppressGeneratedImplementation(descriptor.generated_impl);
                    break;
                }

                const raw = try self.componentType(descriptor, row);
                const held = try self.builder.substitute(
                    raw,
                    descriptor.target.index(),
                    target_arguments,
                );
                if (held == .poison) {
                    try self.suppressGeneratedImplementation(descriptor.generated_impl);
                    break;
                }
                const arguments: []const TypeId = if (checked.args.len == 0) &.{} else blk: {
                    const entry = try argument_sets.getOrPut(self.gpa, .{ .requirement = row.requirement, .bound = row.bound });
                    if (!entry.found_existing) {
                        entry.value_ptr.* = &.{};
                        const instantiated = try self.gpa.alloc(TypeId, checked.args.len);
                        errdefer self.gpa.free(instantiated);
                        for (checked.args, instantiated) |argument, *out| out.* = try self.builder.substitute(argument, descriptor.template.index(), implementation.args);
                        entry.value_ptr.* = instantiated;
                    }
                    break :blk entry.value_ptr.*;
                };
                if (try self.settlesByDiscard(descriptor, implementation_index_in_rows, row, bound, raw, held)) continue;
                if (try self.discharges(held, bound.named.name, arguments)) {
                    if (self.anImplementationCouldServe(held, bound)) continue;
                    try self.reportUnservableComponent(descriptor, row.case, row.component, bound, held);
                    try self.suppressGeneratedImplementation(descriptor.generated_impl);
                    break;
                }

                var instantiated = checked;
                instantiated.args = arguments;
                try self.reportUndischargedComponent(descriptor, row.case, row.component, bound, instantiated, held);
                try self.suppressGeneratedImplementation(descriptor.generated_impl);
                break;
            }
        }
    }

    /// Returns the written type of the component a requirement row names,
    /// in terms of the target's own parameters.
    fn componentType(self: *Checker, descriptor: GeneratedImplementation, row: expanded_mod.ComponentRequirement) std.mem.Allocator.Error!TypeId {
        const component_index: usize = @intCast(@intFromEnum(row.component));
        const module = self.program.moduleOf(descriptor.target);
        return switch (self.ast.declTag(descriptor.target)) {
            .struct_ => try self.typeOfRefOf(module, descriptor.target, self.ast.declFields(descriptor.target)[component_index].written),
            .enum_ => try self.typeOfRefOf(module, descriptor.target, self.ast.variantFields(
                self.ast.declVariants(descriptor.target)[@intFromEnum(row.case)],
            )[component_index].written),
            .newtype => try self.typeOfRefOf(module, descriptor.target, self.ast.declReturnRef(descriptor.target)),
            else => unreachable,
        };
    }

    /// Withdraws the `Release` requirement an attached `derive(Release)` places
    /// on each discardable component, for every derive before any derive's
    /// release or discard choice is made. The choice for one derive asks
    /// whether another type implements `Release`, and the answer depends on
    /// the requirements the other derive keeps. Withdrawal depends only on the
    /// component's capability, which no implementation changes, so it can be
    /// finished first; the choices made afterwards then read final
    /// requirements, and declaration order cannot change them.
    ///
    /// The withdrawal is sound for every discardable component: the derive
    /// either discards it, or proves `Release` for it under the type's own
    /// bounds, which already holds for every instantiation.
    ///
    /// **Bound:** one pass over the component requirement rows.
    fn withdrawDiscardableReleaseRequirements(self: *Checker) std.mem.Allocator.Error!void {
        const release = self.builder.closure_release orelse return;
        var changed = false;
        for (0..self.program.generatedImplementationCount()) |implementation_index| {
            const implementation_id: GeneratedImplementationId = .at(@intCast(implementation_index));
            const descriptor = self.program.generatedImplementation(implementation_id);
            if (self.invalid_templates.contains(descriptor.template)) continue;
            if (self.ast.declTag(descriptor.derive) == .derive_impl) continue;
            const row_index = self.row_of_impl[descriptor.generated_impl.index()];
            if (row_index == impl_of_none) continue;
            const implementation = self.implementations[row_index];
            if (implementation.trait != release.trait.index()) continue;
            const target_arguments = self.builder.appliedTo(implementation.ty);
            self.current = self.program.moduleOf(descriptor.generated_impl);
            for (self.program.componentRequirements(implementation_id)) |row| {
                const requirement = self.ast.template_requirements[row.requirement.index()];
                const bound_index: usize = @intCast(@intFromEnum(row.bound));
                const bound = self.ast.boundsIn(requirement.bounds)[bound_index];
                if (!self.checked_template_requirements[row.requirement.index()][bound_index].valid) break;
                if ((traitAt(self.ast, self.res, bound.named.name) orelse continue) != release.trait) continue;
                const raw = try self.componentType(descriptor, row);
                const held = try self.builder.substitute(raw, descriptor.target.index(), target_arguments);
                if (held == .poison) break;
                if (!try self.builder.meetsCapabilityWithin(descriptor.target, raw, .discardable)) continue;
                if (try self.withdrawFieldRelease(row_index, held, release.trait)) changed = true;
            }
        }
        if (changed) self.builder.invalidateImplementationLookup();
    }

    /// Says whether any implementation of the bound's trait could answer for some
    /// instantiation of `held`'s type. A field requirement is discharged by the
    /// derive's own predicate, so a field whose generic type has no such
    /// implementation at all would leave a derive that never applies.
    ///
    /// **Bound:** the candidates of one trait for one head.
    fn anImplementationCouldServe(self: *const Checker, held: TypeId, bound: node.TraitBound) bool {
        const trait = traitAt(self.ast, self.res, bound.named.name) orelse return true;
        const head = self.builder.view().headOf(held);
        if (head != .applied) return true;
        var rows = self.impl_index.candidates(self.implementations, trait.index(), head, true);
        return rows.next() != null;
    }

    fn reportUnservableComponent(
        self: *Checker,
        descriptor: GeneratedImplementation,
        case: expanded_mod.CaseOrdinal,
        ordinal: ComponentOrdinal,
        bound: node.TraitBound,
        held: TypeId,
    ) std.mem.Allocator.Error!void {
        const component_index: usize = @intFromEnum(ordinal);
        const component_loc: Loc = switch (self.ast.declTag(descriptor.target)) {
            .struct_ => blk: {
                const field = self.ast.declFields(descriptor.target)[component_index];
                break :blk .{ .file = self.ast.fileOf(field.name), .span = self.ast.tokenSpan(field.name) };
            },
            .enum_ => self.locOfWritten(self.ast.variantFields(
                self.ast.declVariants(descriptor.target)[@intFromEnum(case)],
            )[component_index].written),
            .newtype => self.locOfWritten(self.ast.declReturnRef(descriptor.target)),
            else => unreachable,
        };
        const derive_trait = self.ast.deriveTrait(descriptor.derive_trait).ref.name;
        const trait_name = self.ast.tokenText(bound.named.name);
        const labels = try self.sink.arena.alloc(Label, 2);
        labels[0] = .{
            .file = component_loc.file,
            .span = component_loc.span,
            .message = try std.fmt.allocPrint(self.sink.arena, "no implementation of `{s}` exists for any `{s}`", .{ trait_name, (try self.typeName(held)) }),
            .style = .secondary,
        };
        labels[1] = .{
            .file = self.ast.fileOf(derive_trait),
            .span = self.ast.tokenSpan(derive_trait),
            .message = "implement the trait for this field's type, or remove the derive",
            .style = .primary,
        };
        try self.sink.add(.{
            .severity = .err,
            .code = .t_derive,
            .message = try std.fmt.allocPrint(
                self.sink.arena,
                "`{s}` cannot derive `{s}` because component type `{s}` implements `{s}` for no arguments",
                .{ self.ast.tokenText(self.ast.declName(descriptor.target)), self.ast.tokenText(derive_trait), (try self.typeName(held)), trait_name },
            ),
            .labels = labels,
        });
    }

    const DiscardedComponent = struct {
        implementation: DeclId,
        case: u32,
        component: u32,
    };

    /// Decides whether a derived `Release` discards this component, and records
    /// the component when it does. A component is discarded when its type is
    /// discardable and not proven to implement `Release` under the derive's
    /// own constraints: the type's written bounds for an attached request, or
    /// the request's written environment for a standalone one. The decision is
    /// made once here, so every instantiation settles the component the same
    /// way. Every attached derive has already withdrawn the `Release`
    /// requirement on its discardable components, so the answer reads final
    /// requirements.
    fn settlesByDiscard(
        self: *Checker,
        descriptor: expanded_mod.GeneratedImplementation,
        row_index: u32,
        row: expanded_mod.ComponentRequirement,
        bound: node.TraitBound,
        raw: TypeId,
        held: TypeId,
    ) std.mem.Allocator.Error!bool {
        const release = self.builder.closure_release orelse return false;
        if (self.implementations[row_index].trait != release.trait.index()) return false;
        if ((traitAt(self.ast, self.res, bound.named.name) orelse return false) != release.trait) return false;
        const attached = self.ast.declTag(descriptor.derive) != .derive_impl;
        const scope = if (attached) descriptor.target else descriptor.generated_impl;
        const subject = if (attached) raw else held;
        const outer = self.generic;
        defer self.generic = outer;
        self.generic = scope;
        if (try self.dischargesDeclared(subject, release.trait, &.{})) return false;
        if (!try self.builder.meetsCapabilityWithin(scope, subject, .discardable)) return false;
        try self.discarded_components.put(self.gpa, .{
            .implementation = descriptor.generated_impl,
            .case = @intFromEnum(row.case),
            .component = @intFromEnum(row.component),
        }, {});
        return true;
    }

    /// Removes `Release` from the requirements an implementation places on
    /// `subject`, and returns whether any requirement named it.
    fn withdrawFieldRelease(self: *Checker, row_index: u32, subject: TypeId, release: DeclId) std.mem.Allocator.Error!bool {
        var changed = false;
        const implementation = &self.implementations[row_index];
        const predicates: []types_mod.Predicate = @constCast(implementation.predicates);
        for (predicates) |*predicate| {
            if (predicate.subject != subject) continue;
            var kept: usize = 0;
            for (predicate.demand.traits) |required| {
                if (required.trait != release.index()) kept += 1;
            }
            if (kept == predicate.demand.traits.len) continue;
            const traits = try self.gpa.alloc(types_mod.BoundTrait, kept);
            var at: usize = 0;
            for (predicate.demand.traits) |required| {
                if (required.trait == release.index()) continue;
                traits[at] = required;
                at += 1;
            }
            self.gpa.free(predicate.demand.traits);
            predicate.demand.traits = traits;
            changed = true;
        }
        return changed;
    }

    /// Returns `release.discard` for the call a derived `Release` makes to
    /// release a component it discards, so the call is checked as a call to
    /// `release.discard` instead.
    fn discardedRelease(self: *const Checker, id: ExprId, callee: BindingId) ?DeclId {
        if (self.discarded_components.count() == 0) return null;
        const release = self.builder.closure_release orelse return null;
        if (callee == .none or self.res.kindOf(callee) != .function or self.res.declaredBy(callee) != release.member) return null;
        const discard = self.release_discard;
        if (discard == .none or self.generic == .none) return null;
        const implementation = self.builder.view().implementationIdOf(self.generic) orelse return null;
        const origin = self.program.generatedOriginAt(self.ast.fileOfExpr(id), self.ast.exprSpan(id)) orelse return null;
        const component = origin.component_ordinal orelse return null;
        const key: DiscardedComponent = .{
            .implementation = self.implementations[implementation.index()].decl,
            .case = if (origin.case_ordinal) |case| @intFromEnum(case) else 0,
            .component = @intFromEnum(component),
        };
        return if (self.discarded_components.contains(key)) discard else null;
    }

    fn templateRequiresDerivedSupertraits(self: *const Checker, template: DeclId) ?node.TemplateRequirement {
        for (self.ast.templateRequirements(template)) |requirement| {
            if (requirement.kind == .derived_supertraits) return requirement;
        }
        return null;
    }

    /// Requires every direct supertrait implementation selected under a
    /// derive's own environment to carry derive provenance. All generated
    /// headers exist before this walk, and component admission has already
    /// poisoned any prerequisite whose own evidence failed.
    fn checkStructuralSupertraits(self: *Checker) std.mem.Allocator.Error!void {
        const outer_module = self.current;
        const outer_generic = self.generic;
        defer {
            self.current = outer_module;
            self.generic = outer_generic;
        }

        for (0..self.program.generatedImplementationCount()) |implementation_index| {
            const descriptor = self.program.generatedImplementation(.at(@intCast(implementation_index)));
            const requirement = self.templateRequiresDerivedSupertraits(descriptor.template) orelse continue;
            if (self.invalid_templates.contains(descriptor.template) or
                self.suppressed_generated_implementations.contains(descriptor.generated_impl)) continue;

            const dependent_index = self.row_of_impl[descriptor.generated_impl.index()];
            if (dependent_index == impl_of_none) continue;
            const dependent = self.implementations[dependent_index];
            const derive_trait = self.ast.deriveTrait(descriptor.derive_trait).ref.name;
            const trait = traitAt(self.ast, self.res, derive_trait) orelse continue;
            self.current = self.program.moduleOf(descriptor.generated_impl);
            self.generic = descriptor.generated_impl;

            for (self.ast.declBounds(trait)) |bound| {
                if (bound.kind != .named) continue;
                const supertrait = traitAt(self.ast, self.res, bound.named.name) orelse continue;
                const prerequisite = try self.builder.implementationRow(supertrait, &.{}, dependent.ty);
                if (prerequisite) |found| {
                    if (found.derived and self.suppressed_generated_implementations.contains(found.decl)) continue;
                    if (found.derived) continue;
                }

                const message = if (prerequisite == null)
                    try std.fmt.allocPrint(
                        self.sink.arena,
                        "`{s}` cannot derive `{s}` because its `{s}` prerequisite is absent or has stronger constraints",
                        .{
                            self.ast.tokenText(self.ast.declName(descriptor.target)),
                            self.ast.tokenText(derive_trait),
                            self.ast.tokenText(bound.named.name),
                        },
                    )
                else
                    try std.fmt.allocPrint(
                        self.sink.arena,
                        "`{s}` cannot derive `{s}` because its `{s}` implementation is handwritten",
                        .{
                            self.ast.tokenText(self.ast.declName(descriptor.target)),
                            self.ast.tokenText(derive_trait),
                            self.ast.tokenText(bound.named.name),
                        },
                    );
                const labels = try self.sink.arena.alloc(Label, 3);
                labels[0] = .{
                    .file = self.ast.fileOf(bound.named.name),
                    .span = self.ast.tokenSpan(bound.named.name),
                    .message = "this is a direct supertrait",
                    .style = .secondary,
                };
                labels[1] = .{
                    .file = self.ast.fileOf(requirement.selector),
                    .span = self.ast.tokenSpan(requirement.selector),
                    .message = "the template requires derived evidence for every direct supertrait",
                    .style = .secondary,
                };
                labels[2] = .{
                    .file = self.ast.fileOf(derive_trait),
                    .span = self.ast.tokenSpan(derive_trait),
                    .message = if (prerequisite == null)
                        "derive the prerequisite under constraints this environment proves"
                    else
                        "replace the handwritten prerequisite with a derive, or write this implementation by hand",
                    .style = .primary,
                };
                try self.sink.add(.{
                    .severity = .err,
                    .code = .t_derive,
                    .message = message,
                    .labels = labels,
                });
                try self.suppressGeneratedImplementation(descriptor.generated_impl);
                break;
            }
        }
    }

    fn suppressGeneratedImplementation(self: *Checker, implementation: DeclId) std.mem.Allocator.Error!void {
        try self.suppressed_generated_implementations.put(self.gpa, implementation, {});
    }

    fn generatedBodyIsSuppressed(self: *const Checker, declaration: DeclId) bool {
        const row = self.impl_of_decl[declaration.index()];
        if (row == impl_of_none) return false;
        const implementation = self.implementations[row];
        if (implementation.isAmbient()) return false;
        return self.suppressed_generated_implementations.contains(implementation.decl);
    }

    fn reportUndischargedComponent(
        self: *Checker,
        descriptor: GeneratedImplementation,
        case: expanded_mod.CaseOrdinal,
        ordinal: ComponentOrdinal,
        bound: node.TraitBound,
        checked: CheckedTemplateRequirement,
        held: TypeId,
    ) std.mem.Allocator.Error!void {
        const component_index: usize = @intCast(@intFromEnum(ordinal));
        const component_loc: Loc = switch (self.ast.declTag(descriptor.target)) {
            .struct_ => blk: {
                const field = self.ast.declFields(descriptor.target)[component_index];
                break :blk .{ .file = self.ast.fileOf(field.name), .span = self.ast.tokenSpan(field.name) };
            },
            .enum_ => self.locOfWritten(self.ast.variantFields(
                self.ast.declVariants(descriptor.target)[@intFromEnum(case)],
            )[component_index].written),
            .newtype => self.locOfWritten(self.ast.declReturnRef(descriptor.target)),
            else => unreachable,
        };
        const derive_trait = self.ast.deriveTrait(descriptor.derive_trait).ref.name;
        const required = try self.builder.spellInstance(self.ast.tokenText(bound.named.name), checked.args);
        defer self.gpa.free(required);
        const settles = if (self.builder.closure_release) |release| traitAt(self.ast, self.res, bound.named.name) == release.trait else false;
        const message = try std.fmt.allocPrint(
            self.sink.arena,
            "`{s}` cannot derive `{s}` because component type `{s}` {s} `{s}`",
            .{
                self.ast.tokenText(self.ast.declName(descriptor.target)),
                self.ast.tokenText(derive_trait),
                (try self.typeName(held)),
                if (settles) "is not discardable and does not implement" else "does not implement",
                required,
            },
        );
        const component_message = try std.fmt.allocPrint(
            self.sink.arena,
            "this component has type `{s}`",
            .{(try self.typeName(held))},
        );
        const requirement_message = if (settles)
            "a derived `Release` releases each component or discards a discardable one"
        else
            try std.fmt.allocPrint(
                self.sink.arena,
                "the template requires every component to implement `{s}`",
                .{required},
            );
        const open = self.mentionsParameter(held, descriptor.generated_impl, .walks_on);
        // A template the library declares is not the program's to change, and
        // the message already names what it requires, so its source is shown
        // only for a template the program wrote.
        const template_module = self.res.moduleOfFile(self.ast.fileOf(bound.named.name));
        const template_in_library = template_module != .none and self.program.get(template_module).library;
        const labels = try self.sink.arena.alloc(Label, if (template_in_library) 2 else 3);
        labels[0] = .{
            .file = component_loc.file,
            .span = component_loc.span,
            .message = component_message,
            .style = .secondary,
        };
        if (!template_in_library) labels[1] = .{
            .file = self.ast.fileOf(bound.named.name),
            .span = self.ast.tokenSpan(bound.named.name),
            .message = requirement_message,
            .style = .secondary,
        };
        labels[labels.len - 1] = .{
            .file = self.ast.fileOf(derive_trait),
            .span = self.ast.tokenSpan(derive_trait),
            .message = if (open)
                "this written constraint environment does not prove the requirement"
            else
                try std.fmt.allocPrint(self.sink.arena, "implement `{s}` for `{s}`, or write this implementation by hand", .{ required, (try self.typeName(held)) }),
            .style = .primary,
        };
        try self.sink.add(.{
            .severity = .err,
            .code = .t_derive,
            .message = message,
            .labels = labels,
        });
    }

    /// A projection's body is a place: a path rooted at its receiver, reached
    /// by field selection and indexing and by nothing else.
    ///
    /// This is what makes a projection structural. The call site *becomes* the
    /// path rather than running it, so a body that computes a value has no
    /// location for an assignment or a lend to reach, and a body that branched
    /// or called would be a construct the flow builders below here would have
    /// to learn.
    ///
    /// Where a path leads is the tree's answer and is read from the tree, so
    /// the spellings a projection may be written with are exactly the ones
    /// ownership already governs.
    ///
    /// **Bound:** the selections this one body wrote.
    fn checkProjectionBody(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!void {
        const body = self.ast.declBody(d);
        // A body the parser gave up on is already reported, and its shape says
        // nothing about what was meant.
        if (self.ast.exprTag(body) != .block) return;

        // What the fix names the root as: whatever this declaration called its
        // receiver. A projection declaring no parameters has none, and `self`
        // is what one would be written as.
        const params = self.ast.declParams(d);
        const receiver = if (params.len == 0) "self" else self.ast.tokenText(params[0].name);
        const reach_it = try std.fmt.allocPrint(
            self.sink.arena,
            "reach the place from `{s}` by field selection and indexing, and nothing else",
            .{receiver},
        );

        const held = self.ast.blockOf(body);
        const stmts = self.ast.blockStmts(held);
        if (stmts.len != 0 or held.tail == ExprId.none) {
            // At the first statement, which is the code the body may not hold.
            // An empty body has none, and what is pointed at there is the
            // braces that hold nothing.
            return if (stmts.len != 0) self.sink.addError(
                .t_projection,
                self.ast.fileOfStmt(stmts[0]),
                self.ast.stmtSpan(stmts[0]),
                "a projection's body is a place, which is one path rather than a sequence of statements",
                reach_it,
            ) else self.sink.addError(
                .t_projection,
                self.ast.fileOfExpr(body),
                self.ast.exprSpan(body),
                "a projection's body is a place, and this one names none",
                reach_it,
            );
        }

        const tail = self.ast.withoutGroups(held.tail);
        if (self.storagePlaceCall(tail)) {
            const args = self.ast.call(tail).args;
            if ((args.len == 5 or args.len == 2) and self.ast.exprTag(self.ast.placePath(args[0]).root) == .name_ref) {
                const root = self.res.targetOf(self.ast.placePath(args[0]).root);
                if (root != .none and self.res.kindOf(root) == .parameter and
                    std.meta.eql(self.res.parameterOwner(root), resolve_mod.ParameterOwner{ .declaration = d }) and
                    self.res.paramIndexOf(root) == 0)
                {
                    for (args[1..], 1..) |arg, arg_index| {
                        if (self.somethingRun(arg) != null) return self.sink.addError(.t_projection, self.ast.fileOfExpr(arg), self.ast.exprSpan(arg), "a storage place argument cannot run code", reach_it);
                        if (args.len == 5 and arg_index < 4) {
                            const field_root = self.ast.placePath(arg).root;
                            if (self.res.targetOf(field_root) != root) return self.sink.addError(.t_projection, self.ast.fileOfExpr(arg), self.ast.exprSpan(arg), "a storage place reads its address and lengths from its owner", reach_it);
                        }
                    }
                    return;
                }
            }
            return self.sink.addError(.t_projection, self.ast.fileOfExpr(tail), self.ast.exprSpan(tail), "a storage place must name its projection receiver as its owner", reach_it);
        }
        const file = self.ast.fileOfExpr(tail);
        const span = self.ast.exprSpan(tail);
        const path = self.ast.placePath(tail);

        if (self.ast.exprTag(path.root) != .name_ref) {
            return self.sink.addError(
                .t_projection,
                file,
                span,
                "a projection names a place, and this body computes a value",
                reach_it,
            );
        }

        const root = self.res.targetOf(path.root);
        // A name reaching nothing is already reported as the undefined name it
        // is, and what it would have been rooted at is not a second mistake.
        if (root == BindingId.none) return;

        if (!self.rootedAtReceiver(d, tail)) {
            return self.sink.addErrorFmt(
                .t_projection,
                file,
                span,
                reach_it,
                "a projection's place is rooted at `{s}`, and this one is rooted at `{s}`",
                .{ receiver, self.ast.tokenText(self.ast.exprMain(path.root)) },
            );
        }

        // The spine is a path; what each bracket holds is an expression, and
        // the rule covers the whole body. An index that runs something runs it
        // at every site the path is spliced into -- once per use rather than
        // once, and in a position no reader wrote it -- so what may stand there
        // is an operator expression over what is in scope and nothing that
        // chooses a path or calls.
        var at = self.ast.withoutGroups(tail);
        while (true) {
            switch (self.ast.exprTag(at)) {
                .field, .dereference => at = self.ast.withoutGroups(self.ast.unaryOperand(at)),
                .index => {
                    const parts = self.ast.binary(at);
                    if (self.somethingRun(parts.rhs)) |ran| {
                        return self.sink.addError(
                            .t_projection,
                            self.ast.fileOfExpr(ran),
                            self.ast.exprSpan(ran),
                            "a projection's index is an expression over what is in scope, and this one runs something",
                            "an index inside a projection names and computes; it does not call or branch",
                        );
                    }
                    at = self.ast.withoutGroups(parts.lhs);
                },
                else => break,
            }
        }
    }

    /// Whether a place path starts at the first parameter of `d`, the receiver
    /// a projection's call site supplies.
    fn rootedAtReceiver(self: *const Checker, d: node.DeclId, place: ExprId) bool {
        const root = self.ast.placePath(place).root;
        if (self.ast.exprTag(root) != .name_ref) return false;
        const target = self.res.targetOf(root);
        return target != BindingId.none and self.res.kindOf(target) == .parameter and
            std.meta.eql(self.res.parameterOwner(target), resolve_mod.ParameterOwner{ .declaration = d }) and
            self.res.paramIndexOf(target) == 0;
    }

    fn storagePlaceCall(self: *const Checker, id: ExprId) bool {
        if (self.ast.exprTag(id) != .call) return false;
        const target = self.res.targetOf(self.ast.call(id).callee);
        return target != .none and self.res.kindOf(target) == .function and
            (self.res.declaredBy(target) == self.raw_accesses.place or self.res.declaredBy(target) == self.raw_accesses.slice_place);
    }

    /// The first thing inside an expression that runs code or chooses a path,
    /// or null where nothing does.
    ///
    /// The whole of what a projection's index may not hold: a call — a
    /// conversion and a construction among them — a `copy`, a `try`, a match, a
    /// conditional, a loop, a block, an assignment, or a jump. Everything else
    /// is a literal, a name, an operator or a place, and is left to the type
    /// rules the way it is anywhere else.
    ///
    /// Exhaustive, with no `else`, so an expression form added to the language
    /// says whether it runs before the build succeeds.
    ///
    /// **Bound:** the nodes of this one index expression, each visited once.
    fn somethingRun(self: *const Checker, id: ExprId) ?ExprId {
        if (id == ExprId.none) return null;
        const tag = self.ast.exprTag(id);
        switch (tag) {
            .call,
            .lambda,
            .copy_,
            .borrow,
            .panic,
            .try_,
            .unwrap_else,
            .match_,
            .match_read,
            .for_,
            .for_read,
            .for_inout,
            .interp,
            .conditional,
            .while_,
            .loop_,
            .block,
            .break_,
            .continue_,
            .return_,
            .assign,
            .add_assign,
            .sub_assign,
            .mul_assign,
            .div_assign,
            .rem_assign,
            .marked,
            .struct_pattern,
            .tuple_pattern,
            => return id,

            // A value form or an operator. Descended into rather than accepted
            // whole: a call sits inside `[a, f()][0]` as surely as it sits on
            // its own.
            .int_literal,
            .float_literal,
            .str_literal,
            .embed,
            .embed_bytes,
            .bool_literal,
            .unit_literal,
            .name_ref,
            .param_argument,
            .reflection_root,
            .err,
            .grouped,
            .negate,
            .dereference,
            .not,
            .from_end,
            .field,
            .variant_ref,
            .index,
            .add,
            .sub,
            .mul,
            .div,
            .rem,
            .eq,
            .ne,
            .lt,
            .le,
            .gt,
            .ge,
            .logical_and,
            .logical_or,
            .range,
            .struct_literal,
            .array_literal,
            .tuple_literal,
            => {},
        }

        return switch (tag.payload()) {
            .none => null,
            .unary => self.somethingRun(self.ast.unaryOperand(id)),
            .binary => blk: {
                const parts = self.ast.binary(id);
                break :blk self.somethingRun(parts.lhs) orelse self.somethingRun(parts.rhs);
            },
            .range => blk: {
                const ends = self.ast.rangeEnds(id);
                break :blk self.somethingRun(ends.lhs) orelse self.somethingRun(ends.rhs);
            },
            .call => blk: {
                for (self.ast.call(id).args) |a| {
                    if (self.somethingRun(a)) |ran| break :blk ran;
                }
                if (tag == .struct_literal) break :blk self.somethingRun(self.ast.call(id).callee);
                break :blk null;
            },
            .interpolation => blk: {
                for (self.ast.interpolation(id).pieces) |piece| {
                    if (self.somethingRun(piece)) |ran| break :blk ran;
                }
                break :blk null;
            },
            // Every tag carrying one is refused above, so nothing reaches here
            // with a block or a conditional to descend into.
            .block, .conditional, .lambda => null,
        };
    }

    /// A projection answers a projection a trait declares, so an `impl` naming
    /// no trait may hold none.
    ///
    /// What a bracket reaches is the trait's member: the site is typed against
    /// the declaration and takes the path the implementation wrote, so a
    /// projection standing outside that relation is a place nothing names.
    /// Admitting one anyway would settle by accident what an inherent bracket
    /// syntax means, which is a design and not a consequence.
    ///
    /// **Bound:** the declarations lying inside this one implementation's
    /// extent, which is what it holds rather than what the program does.
    fn refuseInherentProjections(self: *Checker, impl: node.DeclId) std.mem.Allocator.Error!void {
        for (self.decls.within(self.ast.declTokens(impl))) |mem| {
            // The `impl` itself sits in its own extent, and is what declares
            // the members rather than one of them.
            if (mem == impl) continue;
            if (self.ast.declTag(mem) != .projection) continue;

            const at = self.ast.declName(mem);
            try self.sink.addError(
                .t_projection,
                self.ast.fileOf(at),
                self.ast.tokenSpan(at),
                "a projection answers a projection a trait declares, and this `impl` names no trait",
                "declare it on a trait and implement that trait here, or write it as an `fn`",
            );
        }
    }

    /// A head applies its constructor the arguments that constructor declares.
    ///
    /// The head is what says which types an implementation answers for, so a
    /// head applying a number of arguments its constructor does not take names
    /// no type and answers for nothing. Reported through the one wording a
    /// written type given the wrong number of arguments gets, because that is
    /// what a head is.
    ///
    /// A head applying none is a name and not an application: it stands for the
    /// declaration itself, which is what an inherent implementation on a generic
    /// type is written as.
    fn checkHeadArity(self: *Checker, d: node.DeclId) std.mem.Allocator.Error!void {
        const written = self.ast.declHead(d).args.len();
        if (written == 0) return;

        const tok = self.ast.declName(d);
        const m = self.program.moduleOf(d);
        if (m == .none) return;

        // A head naming nothing is already reported as the undefined name it
        // is, and how many arguments a name that reaches no declaration takes
        // is not a question with an answer.
        if (self.declOfType(m, d, tok) == null and
            self.res.builtinNamed(m, self.ast.tokenName(tok)) == null) return;

        const wanted = self.paramCountOf(m, d, tok);
        if (wanted == written) return;
        // An inherent implementation's members belong to the instantiation its
        // head writes, so a head may omit the trailing arguments a default
        // fills. A trait implementation's head is the constructor applied to
        // each of its parameters, because the head key is the constructor.
        const required = if (self.ast.declTrait(d) == TokenId.none)
            self.requiredParamCountOf(m, d, tok)
        else
            wanted;
        if (written >= required and written <= wanted) return;
        if (self.refusedBefore(tok)) return;
        try self.noteRefused(tok);
        const omits_a_default = written < wanted and written >= self.requiredParamCountOf(m, d, tok);
        try self.refuseTypeArity(self.ast.tokenSpan(tok), tok, required, wanted, written, if (omits_a_default)
            "a trait implementation's head names every parameter, so a default is not filled here"
        else
            null);
    }

    /// What an implementation supplied for its trait, as the record holds it.
    ///
    /// Empty where no record was built, which is an implementation whose head
    /// named nothing -- already reported, and with no signature left to read
    /// through anything.
    /// Searched, not walked. This is asked once per implementation the module
    /// declares, so a walk over every implementation is the square of them --
    /// which is the shape a module implementing one trait for many types has.
    /// `collectImplementations` reads the declarations in order, so the list
    /// is ordered by the declaration each row came from.
    fn suppliedBy(self: *const Checker, impl: node.DeclId) []const TypeId {
        return (self.rowFor(impl) orelse return &.{}).args;
    }

    /// What the collection recorded for an implementation, or null where it
    /// recorded none -- a head naming nothing, which is reported where it is
    /// written.
    fn rowFor(self: *const Checker, impl: node.DeclId) ?*const types_mod.Implementation {
        const at = implementationRowIndex(self.implementations, impl) orelse return null;
        return &self.implementations[at];
    }

    /// What an implementation answers for its trait's parameters.
    ///
    /// Read through the one routine that settles a written type, so an
    /// argument an `impl` wrote is a type the same way an argument anywhere
    /// else is -- and is recorded as one, which is what lets a dump show it.
    /// The caller owns the slice.
    fn traitArgumentsOf(
        self: *Checker,
        impl: node.DeclId,
    ) std.mem.Allocator.Error![]TypeId {
        const written = self.ast.typeArgs(self.ast.declTraitArgs(impl));
        const out = try self.gpa.alloc(TypeId, written.len);
        errdefer self.gpa.free(out);

        const m = self.program.moduleOf(impl);
        for (written, 0..) |a, k| out[k] = try self.typeOfRefOf(m, impl, a);
        return out;
    }

    /// Settle one complete implementation key and verify that structural
    /// matching can recover every declared parameter without inverting a projection.
    fn settleHead(self: *Checker, implementation: *types_mod.Implementation) std.mem.Allocator.Error!void {
        const d = implementation.decl;
        implementation.ty = try self.typeOfRefOf(self.program.moduleOf(d), d, self.ast.declHead(d));
        if (implementation.head == .default_) {
            const parameter = self.builder.get(implementation.ty);
            if (implementation.parameters != 1 or parameter != .parameter or
                parameter.parameter.owner != d.index() or parameter.parameter.index != 0 or
                !implementation.ofATrait() or implementation.args.len != 0 or
                self.ast.declTypeParams(node.DeclId.at(implementation.trait)).len != 0)
            {
                implementation.valid_key = false;
                try self.sink.addErrorFmt(.t_impl, self.ast.fileOfDecl(d), self.ast.writtenSpan(self.ast.declHead(d)), "use one parameter as the whole head of a zero-argument trait", "a default implementation requires one bare parameter head and a zero-argument trait", .{});
            }
        }
        var parameters = try types_mod.ImplementationParameters.init(self.gpa, &self.builder, implementation.*);
        defer parameters.deinit(self.gpa);
        for (parameters.origins, 0..) |origin, at| {
            if (origin != null) continue;
            implementation.valid_key = false;
            const token = self.ast.declTypeParams(d)[at].name;
            try self.sink.addErrorFmt(.t_impl, self.ast.fileOf(token), self.ast.tokenSpan(token), "place the parameter in the receiver or trait arguments outside associated-type projections", "implementation parameter `{s}` cannot be recovered from its key", .{self.ast.tokenText(token)});
        }
    }

    /// Retains projected constraints on an implementation so the one lookup
    /// that selects it can decide applicability after binding the head.
    fn settleImplementationPredicates(
        self: *Checker,
        implementation: *types_mod.Implementation,
    ) std.mem.Allocator.Error!void {
        const d = implementation.decl;
        const range = self.constraints.rangeOfDeclaration(d);
        var count: u32 = 0;
        count = range.end - range.start;
        if (count == 0) return;

        const predicates = try self.gpa.alloc(types_mod.Predicate, count);
        var filled: usize = 0;
        errdefer {
            for (predicates[0..filled]) |predicate| {
                types_mod.freeBoundTraits(self.gpa, predicate.demand.traits);
                if (predicate.demand.callables.len > 0) self.gpa.free(predicate.demand.callables);
            }
            self.gpa.free(predicates);
        }

        for (range.start..range.end) |at| {
            const constraint = self.constraints.records[at];
            const requirements = self.constraints.requirementsOf(constraint);
            const context: BoundInterning = .{ .module = self.program.moduleOf(d), .owner = d };
            const traits = try self.traitsBounding(context, requirements);
            errdefer types_mod.freeBoundTraits(self.gpa, traits);
            const callables = try self.callablesBounding(context, requirements, traits);
            predicates[filled] = .{
                .subject = self.constraint_subjects[at],
                .demand = .{
                    .traits = traits,
                    .callables = callables,
                    .requirement = capabilityDemandedBy(self.ast, self.res, requirements, traits),
                    .integer = integerDemandedBy(self.ast, self.res, requirements, traits),
                    .owned = ownedBound(self.ast, self.res, requirements) != null,
                },
            };
            filled += 1;
        }
        implementation.predicates = predicates;
        self.builder.invalidateImplementationLookup();
    }

    /// Refuses two implementations of one trait whose heads and trait
    /// arguments unify -- there would then exist an instantiation both answer
    /// for, and nothing decides which body it runs.
    ///
    /// Concrete constructors are checked within their trait/head chain.
    /// Parameter heads additionally compare against ordinary constructor heads
    /// in the same trait's index; defaults belong to a separate selection tier.
    /// For a trait with B parameter heads and C constructor heads, this adds
    /// O(B * C) structural comparisons without visiting unrelated traits.
    ///
    /// **Bound:** quadratic in the implementations of one chain whose *trait
    /// arguments* are open -- naming a parameter of the declaration, or a
    /// settled reference, which is what a substitution may move or cannot
    /// decide -- and linear in the rest. An open one is unified against every
    /// other member of its chain, open or not, because a settled override can
    /// collide with a generic implementation at the one point where they
    /// meet.
    ///
    /// Two implementations whose argument lists are both ground are unified
    /// only where those lists are equal: unifying two ground lists degenerates
    /// to comparing them, and unequal ground arguments cannot be made equal by
    /// anything the heads do. Equal ones are found by hashing the list rather
    /// than by comparing every pair, so a chain gains no pairwise cost from
    /// however many settled arguments one type implements a trait at --
    /// whatever its head's own parameters do, since an argument list written
    /// out is ground however generic the type it is written for.
    fn refuseOverlappingImplementations(
        self: *Checker,
        implementations: []const types_mod.Implementation,
    ) std.mem.Allocator.Error!void {
        var handled = try std.DynamicBitSetUnmanaged.initEmpty(self.gpa, implementations.len);
        defer handled.deinit(self.gpa);

        var open_list: std.ArrayList(u32) = .empty;
        defer open_list.deinit(self.gpa);
        var ground_list: std.ArrayList(u32) = .empty;
        defer ground_list.deinit(self.gpa);

        // The ground members sharing one argument list, as a chain per list:
        // the head of each is in `alike`, keyed by a hash of the list, and
        // `next` walks the rest. Positions are into `ground_list`, so both
        // are sized by the chain being examined and not by the program.
        var alike: std.AutoHashMapUnmanaged(u64, u32) = .empty;
        defer alike.deinit(self.gpa);
        var next: std.ArrayList(u32) = .empty;
        defer next.deinit(self.gpa);

        for (implementations, 0..) |im, i| {
            if (im.isAmbient() or !im.ofATrait()) continue;
            if (im.head == .parameter and im.valid_key) {
                var concrete = self.impl_index.membersOfTrait(im.trait);
                while (concrete.next()) |other| {
                    const row = implementations[other];
                    if (row.trait != im.trait or row.head == .parameter or row.head == .default_ or row.isAmbient() or !row.valid_key) continue;
                    // Integer denotes a closed receiver domain. Ordinary trait
                    // predicates do not exclude structural overlap.
                    if (self.builder.isIntegerWithin(im.decl, im.ty) and !self.builder.isIntegerWithin(row.decl, row.ty)) continue;
                    // A trait the head's parameter is bounded by that no
                    // implementation could answer for the other head's
                    // constructor excludes it: `impl[I: Iterator] Sequence for
                    // I` and `impl[T] Sequence for Slice[T]` meet nowhere,
                    // since nothing implements `Iterator` for any `Slice`.
                    if (self.boundExcludesHead(implementations, im, row)) continue;
                    if (try self.builder.anyUnsettled(&.{ im.ty, row.ty }) or
                        try self.builder.anyUnsettled(im.args) or
                        try self.builder.anyUnsettled(row.args)) continue;
                    try self.refuseIfOverlapping(implementations, @intCast(@min(i, other)), @intCast(@max(i, other)));
                }
            }

            if (handled.isSet(i)) continue;
            open_list.clearRetainingCapacity();
            ground_list.clearRetainingCapacity();

            // Collects the whole chain once. A hash collision reaches an
            // implementation of another trait or head; skipped here as
            // `answersFor` skips it, by asking the two questions the hash
            // stands for again.
            var run = self.impl_index.membersOf(im.trait, im.head);
            while (run.next()) |at| {
                const entry = implementations[at];
                if (entry.isAmbient() or !entry.ofATrait()) continue;
                if (entry.trait != im.trait or !entry.head.same(im.head)) continue;
                handled.set(@intCast(at));
                // A pattern head is refused on its own account and stands for
                // no family this can ask a question about: `Pair[T, T]` binds
                // one parameter twice, so which position unify would follow
                // to reach the other is not decided by anything the head
                // says. Left in, every one of these malformed heads answers
                // for the others in this test alone -- noise about a program
                // already refused for the reason that matters.
                if (entry.parameters > 0 and !entry.valid_key) continue;
                // A written type nothing settled -- an array whose length is
                // not a constant -- stands for no family this can ask a
                // question about, and the resolver's own key passes over one
                // for the same reason: two of them called equal make one key
                // for what may be two types. The program is refused where the
                // length is written.
                if (try self.builder.anyUnsettled(&.{entry.ty}) or
                    try self.builder.anyUnsettled(entry.args)) continue;
                if (try self.builder.allGround(entry.args)) {
                    try ground_list.append(self.gpa, at);
                } else {
                    try open_list.append(self.gpa, at);
                }
            }

            if (open_list.items.len != 0) {
                const position = try self.overlapColumn(implementations, open_list.items, ground_list.items);
                var open_candidates: OverlapCandidates = .{};
                defer open_candidates.deinit(self.gpa);
                var ground_candidates: OverlapCandidates = .{};
                defer ground_candidates.deinit(self.gpa);
                for (ground_list.items) |at| {
                    try ground_candidates.add(self.gpa, self.overlapRoot(implementations[at].args, position), at);
                }
                // Both lists retain source order. Filtering merges equal-root
                // and wildcard rows in that order, without moving open/ground
                // reports relative to open/open or ground/ground reports.
                for (open_list.items, 0..) |later, oi| {
                    const root = self.overlapRoot(implementations[later].args, position);
                    var prior_rows = open_candidates.candidates(root, open_list.items[0..oi]);
                    while (prior_rows.next()) |prior| {
                        try self.refuseIfOverlapping(implementations, prior, later);
                    }
                    var ground_rows = ground_candidates.candidates(root, ground_list.items);
                    while (ground_rows.next()) |ground_at| {
                        try self.refuseIfOverlapping(
                            implementations,
                            @min(later, ground_at),
                            @max(later, ground_at),
                        );
                    }
                    try open_candidates.add(self.gpa, root, later);
                }
            }

            alike.clearRetainingCapacity();
            next.clearRetainingCapacity();
            try next.resize(self.gpa, ground_list.items.len);
            for (ground_list.items, 0..) |at, gi| {
                const key = hashOfTypes(implementations[at].args);
                var walk = alike.get(key);
                while (walk) |j| {
                    const other = ground_list.items[j];
                    // Hashed and then compared, so a collision costs a
                    // comparison rather than a report about two lists that
                    // are not the same.
                    if (std.mem.eql(TypeId, implementations[other].args, implementations[at].args)) {
                        try self.refuseIfOverlapping(implementations, other, at);
                    }
                    walk = if (next.items[j] == j) null else next.items[j];
                }
                next.items[gi] = alike.get(key) orelse @intCast(gi);
                try alike.put(self.gpa, key, @intCast(gi));
            }
        }
    }

    /// Whether a trait bounding the parameter `head` implements has no
    /// implementation that could answer for `other`'s head, so no type is
    /// covered by both. Every implementation of the bound's trait is in
    /// `implementations`, so the answer holds for the whole program: a type
    /// given an implementation of the bound elsewhere is found here and the
    /// two are compared as overlapping.
    ///
    /// **Bound:** for each trait the head's parameter is bounded by, the
    /// candidates of that trait for `other`'s head and for every head.
    fn boundExcludesHead(
        self: *const Checker,
        implementations: []const types_mod.Implementation,
        head: types_mod.Implementation,
        other: types_mod.Implementation,
    ) bool {
        const receiver = self.builder.headOf(other.ty);
        for (self.builder.boundsOn(head.ty)) |bound| {
            var rows = self.impl_index.candidates(implementations, bound.trait, receiver, true);
            if (rows.next() == null) return true;
        }
        return false;
    }

    /// A necessary nominal-root equality from the unifier, not an overlap
    /// decision. Parameters, opaque projections and structural types remain
    /// wildcards; only the unifier decides their relation to another argument.
    fn overlapRoot(self: *const Checker, args: []const TypeId, position: usize) ?node.DeclId {
        if (position >= args.len) return null;
        const arg = args[position];
        if (self.builder.standinOf(arg) != null) return null;
        switch (self.builder.get(arg)) {
            .parameter, .array, .callable => return null,
            else => {},
        }
        return (self.builder.instanceOf(arg) orelse return null).decl;
    }

    /// Select one shared position with distinct nominal roots. The scan costs
    /// O(represented arguments), with scratch sized by this chain's arity.
    fn overlapColumn(
        self: *const Checker,
        implementations: []const types_mod.Implementation,
        open: []const u32,
        ground: []const u32,
    ) std.mem.Allocator.Error!usize {
        var arity: usize = 0;
        for ([_][]const u32{ open, ground }) |rows| {
            for (rows) |at| arity = @max(arity, implementations[at].args.len);
        }
        const first = try self.gpa.alloc(?node.DeclId, arity);
        defer self.gpa.free(first);
        @memset(first, null);
        var selected: ?usize = null;
        for ([_][]const u32{ open, ground }) |rows| {
            for (rows) |at| {
                const args = implementations[at].args;
                for (0..args.len) |position| {
                    const root = self.overlapRoot(args, position) orelse continue;
                    if (first[position]) |prior| {
                        if (prior != root) selected = @min(selected orelse position, position);
                    } else first[position] = root;
                }
            }
        }
        return selected orelse 0;
    }

    /// Per-chain rows grouped by one nominal root. Candidate traversal costs
    /// O(rows retained), plus expected O(rows) construction; all-wildcard or
    /// equal-root chains retain the existing comparison's pairwise work.
    const OverlapCandidates = struct {
        named: std.AutoHashMapUnmanaged(node.DeclId, std.ArrayList(u32)) = .empty,
        wildcards: std.ArrayList(u32) = .empty,

        fn deinit(self: *OverlapCandidates, gpa: std.mem.Allocator) void {
            var lists = self.named.valueIterator();
            while (lists.next()) |list| list.deinit(gpa);
            self.named.deinit(gpa);
            self.wildcards.deinit(gpa);
        }

        fn add(self: *OverlapCandidates, gpa: std.mem.Allocator, root: ?node.DeclId, row: u32) !void {
            if (root) |key| {
                const entry = try self.named.getOrPut(gpa, key);
                if (!entry.found_existing) entry.value_ptr.* = .empty;
                try entry.value_ptr.append(gpa, row);
            } else try self.wildcards.append(gpa, row);
        }

        fn candidates(self: *const OverlapCandidates, root: ?node.DeclId, all: []const u32) Iterator {
            if (root) |key| return .{
                .named = if (self.named.get(key)) |list| list.items else &.{},
                .wildcards = self.wildcards.items,
            };
            return .{ .named = all, .wildcards = &.{} };
        }

        const Iterator = struct {
            named: []const u32,
            wildcards: []const u32,

            fn next(self: *Iterator) ?u32 {
                const list = if (self.named.len != 0 and
                    (self.wildcards.len == 0 or self.named[0] < self.wildcards[0]))
                    &self.named
                else
                    &self.wildcards;
                if (list.len == 0) return null;
                const row = list.*[0];
                list.* = list.*[1..];
                return row;
            }
        };
    };

    /// Unifies `first` and `second`'s heads followed by their trait arguments,
    /// as one list each, and reports `[T-Impl]` where they unify -- carried by
    /// the implementation written second, naming the one written first and the
    /// instantiation both would answer for. Where exactly one of the two is
    /// the standard library's, the program's implementation carries it.
    ///
    /// `first` and `second` are positions in a list held in declaration order,
    /// so the report lands where a programmer added the collision, which is
    /// where `[N-Duplicate]` lands for the same reason.
    fn refuseIfOverlapping(
        self: *Checker,
        implementations: []const types_mod.Implementation,
        first: u32,
        second: u32,
    ) std.mem.Allocator.Error!void {
        const gpa = self.gpa;
        const a = implementations[first];
        const b = implementations[second];

        // Two implementations written identically overlap for a reason the
        // resolver has already stated about that very pair. One mistake gets
        // one diagnostic, and the one that names the repetition is the more
        // useful of the two.
        if (self.res.reportedDuplicate(a.decl, b.decl)) return;

        // An implementation resolution refused is reported as refused, and
        // overlapping another is the same mistake said a second time. It keeps
        // its row, which every other check of the program reads it through.
        if (self.res.isRefusedImpl(a.decl) or self.res.isRefusedImpl(b.decl)) return;

        const list_a = try gpa.alloc(TypeId, 1 + a.args.len);
        defer gpa.free(list_a);
        list_a[0] = a.ty;
        @memcpy(list_a[1..], a.args);

        const list_b = try gpa.alloc(TypeId, 1 + b.args.len);
        defer gpa.free(list_b);
        list_b[0] = b.ty;
        @memcpy(list_b[1..], b.args);

        const witness = try types_mod.unifyWitness(gpa, &self.builder, list_a, list_b) orelse return;
        defer gpa.free(witness);

        // The instantiation both answer for, not the substitution that
        // reached it: a reader is told what the two implementations collide
        // at, and the two declarations' own parameters mean nothing outside
        // either one.
        const trait_name = self.ast.tokenText(self.ast.declName(node.DeclId.at(a.trait)));
        const spelled = try self.builder.spellInstance(trait_name, witness[1..]);
        defer gpa.free(spelled);
        const head_name = (try self.typeName(witness[0]));

        const message = try std.fmt.allocPrint(
            self.sink.arena,
            "these two both answer `{s}` for `{s}`",
            .{ spelled, head_name },
        );

        // The program's own implementation carries the report when the other
        // is the library's: that is the one its author can change.
        const a_is_library = self.declaredInLibrary(a.decl);
        const b_is_library = self.declaredInLibrary(b.decl);
        const user_first = b_is_library and !a_is_library;
        const first_decl = if (user_first) b.decl else a.decl;
        const second_decl = if (user_first) a.decl else b.decl;

        // The library implements `Into` for every `From`, so a direct `Into`
        // implementation collides with that bridge whatever its types are.
        var notes: []const []const u8 = &.{};
        const into_trait = self.program.libraryDeclIn("convert", "Into");
        if (into_trait != null and a.trait == into_trait.?.index() and
            a_is_library != b_is_library and witness.len == 2)
        {
            const note = try std.fmt.allocPrint(
                self.sink.arena,
                "implement `From[{s}]` for `{s}` instead: each `From` implementation supplies the matching `Into`",
                .{ head_name, (try self.typeName(witness[1])) },
            );
            const held = try self.sink.arena.alloc([]const u8, 1);
            held[0] = note;
            notes = held;
        }

        const labels = try self.sink.arena.alloc(Label, 2);
        labels[0] = .{
            .file = self.ast.fileOf(self.ast.declTrait(first_decl)),
            .span = self.ast.tokenSpan(self.ast.declTrait(first_decl)),
            .message = "the other implementation",
            .style = .secondary,
        };
        labels[1] = .{
            .file = self.ast.fileOf(self.ast.declTrait(second_decl)),
            .span = self.ast.tokenSpan(self.ast.declTrait(second_decl)),
            .message = "no instantiation may answer to two implementations of one trait",
            .style = .primary,
        };
        try self.sink.add(.{
            .severity = .err,
            .code = .t_impl,
            .message = message,
            .labels = labels,
            .notes = notes,
        });
        try self.overlapping.put(gpa, a.decl, {});
        try self.overlapping.put(gpa, b.decl, {});
    }

    fn declaredInLibrary(self: *const Checker, d: node.DeclId) bool {
        const module = self.program.moduleOf(d);
        return module != .none and self.program.get(module).library;
    }

    /// A run of types as one number, so a caller grouping runs that are equal
    /// finds the group by lookup rather than by comparing every pair. A
    /// collision costs the comparison the caller makes anyway.
    fn hashOfTypes(run: []const TypeId) u64 {
        var h: std.hash.Wyhash = .init(run.len);
        for (run) |t| {
            const id: u32 = @intFromEnum(t);
            h.update(std.mem.asBytes(&id));
        }
        return h.final();
    }

    /// The traits a run of bounds admits, by declaration: the ones it names,
    /// and everything those require.
    ///
    /// A bound naming a trait admits what that trait requires, because an
    /// implementation of it could not have been written without them -- so a
    /// body bounded on it may use them. Worked out here, the one place a bound
    /// list is read for what it admits, rather than at each asker: two
    /// expansions of one list would be the same rule twice, and the second
    /// would disagree on the trait nobody wrote.
    ///
    /// A bound naming no trait is left out: what it names is the resolver's
    /// question and it reports the name that reaches nothing, so holding an
    /// implementation to it here would refuse every use of a program already
    /// refused at its declaration. The caller owns the slice.
    ///
    /// Where a bound's own arguments are read from a declaration's scope, so
    /// they intern to the same names every other written type does -- an
    /// earlier parameter of that declaration among them, per any other
    /// position, because `c.param_types` is aliased into the checker before
    /// the first parameter is interned and each position fills it as
    /// `addParameter` settles it. Null wherever a caller reads what a bound
    /// list admits without regard to arguments -- every asker but the two
    /// that record a declaration's own parameters, which are the only
    /// readings a type argument is later checked against.
    const BoundInterning = struct { module: ModuleId, owner: node.DeclId };

    /// The arguments one written bound names, interned in `interning`'s
    /// scope, or empty where there is no scope to read them in.
    fn internedBoundArgs(
        self: *Checker,
        interning: ?BoundInterning,
        bound: node.TraitBound,
    ) std.mem.Allocator.Error![]const TypeId {
        if (bound.kind == .callable) return &.{};
        const ctx = interning orelse return &.{};
        const written = self.ast.typeArgs(bound.named.args);
        if (written.len == 0) return &.{};
        const out = try self.gpa.alloc(TypeId, written.len);
        errdefer self.gpa.free(out);
        for (written, 0..) |a, k| out[k] = try self.typeOfRefOf(ctx.module, ctx.owner, a);
        return out;
    }

    /// The arguments a bound named, with any of `decl`'s own parameters among
    /// them replaced by what this call or instantiation settled that
    /// parameter to.
    ///
    /// A bound written `[I, C: Lookup[I]]` names `I` as one of `decl`'s own
    /// parameters, and what `Lookup` is discharged at for a particular
    /// receiver is whatever settled `I`, not the parameter itself -- which
    /// matches no implementation's argument. Substituted through the same
    /// routine an implementation's own trait arguments are settled by, since
    /// the question is the same one asked at a different position: what a
    /// declaration's parameter stands for, given what filled it.
    ///
    /// `raw` past the point nothing of `decl`'s own names is unchanged, so a
    /// bound naming only concrete types costs one allocation and no
    /// substitution finds anything to move.
    fn substitutedBoundArgs(
        self: *Checker,
        raw: []const TypeId,
        decl: node.DeclId,
        settled: []const TypeId,
    ) std.mem.Allocator.Error![]const TypeId {
        if (raw.len == 0) return raw;
        const out = try self.gpa.alloc(TypeId, raw.len);
        errdefer self.gpa.free(out);
        for (raw, out) |a, *slot| slot.* = try self.builder.substitute(a, @intCast(decl.index()), settled);
        return out;
    }

    /// **Bound:** one entry per written bound reachable from this list paired
    /// with the arguments it was reached at. Every `written` appended comes
    /// from a bound the program wrote, and the arguments come from
    /// substituting into the entry that reached it, so the list grows only
    /// while a new pair keeps turning up -- and an entry already in the list
    /// is not walked again, which is what makes this finish over the cycle
    /// `reportTraitBoundCycles` refuses.
    fn traitsBounding(
        self: *Checker,
        interning: ?BoundInterning,
        bounds: []const node.TraitBound,
    ) std.mem.Allocator.Error![]const types_mod.BoundTrait {
        var out: std.ArrayList(types_mod.BoundTrait) = .empty;
        var seen: BoundTraitSet = .empty;
        defer seen.deinit(self.gpa);
        const context = BoundTraitContext{ .checker = self };
        errdefer {
            for (out.items) |b| if (b.args.len > 0) self.gpa.free(b.args);
            out.deinit(self.gpa);
        }
        for (bounds) |b| {
            if (b.kind == .callable) continue;
            if (try self.admitIntegerComparisons(&out, &seen, context, b)) continue;
            const t = traitAt(self.ast, self.res, b.named.name) orelse continue;
            const args = try self.internedBoundArgs(interning, b);
            try self.admitOnce(&out, &seen, context, t, b, args);
        }

        // Walked as the list grows, so what a required trait requires is
        // admitted too. The read index never passes the write index, and each
        // entry is walked once.
        //
        // A required trait is admitted at the arguments the trait requiring it
        // wrote -- `trait Fancy: Lookup[UInt64]` admits `Lookup` at `UInt64`
        // and not at anything else. Those arguments are written in the
        // requiring trait's own scope and may name its parameters, so they are
        // read there and settled by whatever the bound that reached it
        // supplied.
        var at: usize = 0;
        while (at < out.items.len) : (at += 1) {
            const required = node.DeclId.at(out.items[at].trait);
            const supplied = out.items[at].args;
            const through: ?BoundInterning = if (interning == null) null else .{
                .module = self.program.moduleOf(required),
                .owner = required,
            };
            for (self.ast.declBounds(required)) |b| {
                if (b.kind == .callable) continue;
                if (try self.admitIntegerComparisons(&out, &seen, context, b)) continue;
                const t = traitAt(self.ast, self.res, b.named.name) orelse continue;
                const raw = try self.internedBoundArgs(through, b);
                defer if (raw.len > 0) self.gpa.free(raw);
                try self.admitOnce(
                    &out,
                    &seen,
                    context,
                    t,
                    b,
                    try self.substitutedBoundArgs(raw, required, supplied),
                );
            }
        }
        return out.toOwnedSlice(self.gpa);
    }

    /// The closed integer family guarantees these same-type comparison traits.
    /// Admit their resolved declarations through the ordinary bound closure.
    fn admitIntegerComparisons(self: *Checker, out: *std.ArrayList(types_mod.BoundTrait), seen: *BoundTraitSet, context: BoundTraitContext, bound: node.TraitBound) !bool {
        const declared = traitAt(self.ast, self.res, bound.named.name);
        if (resolve_mod.boundNames(self.ast, bound.named.name, declared) != .integer) return false;
        for ([_]?node.DeclId{ self.equatable_decl, self.comparable_decl }) |trait| {
            if (trait) |known| try self.admitOnce(out, seen, context, known, bound, &.{});
        }
        return true;
    }

    /// `Closure.open`'s callback must be callable as the closure's `S`, which
    /// no bound can spell: `S` is a type parameter of the implementation, not
    /// a written signature. The callback's parameter carries `S` itself as its
    /// callable bound, and call inference reads it once `S` is settled -- from
    /// the expected closure type, or from the callback's own signature.
    fn withClosureSignature(self: *Checker, open: node.DeclId, written: []const TypeId) std.mem.Allocator.Error![]const TypeId {
        const head = self.headParametersOf(open);
        if (head == .none or self.param_types[head.index()].len == 0) return written;
        const signature = self.param_types[head.index()][0];
        const out = try self.gpa.alloc(TypeId, written.len + 1);
        @memcpy(out[0..written.len], written);
        out[written.len] = signature;
        if (written.len > 0) self.gpa.free(written);
        return out;
    }

    fn callablesBounding(
        self: *Checker,
        interning: BoundInterning,
        bounds: []const node.TraitBound,
        traits: []const types_mod.BoundTrait,
    ) std.mem.Allocator.Error![]const TypeId {
        var out: std.ArrayList(TypeId) = .empty;
        errdefer out.deinit(self.gpa);

        for (bounds) |bound| {
            if (!self.isCallableBound(bound)) continue;
            const signature = try self.boundSignature(interning.module, interning.owner, bound);
            if (signature != .poison and std.mem.indexOfScalar(TypeId, out.items, signature) == null) {
                try out.append(self.gpa, signature);
            }
        }

        for (traits) |carried| {
            const required = node.DeclId.at(carried.trait);
            for (self.ast.declBounds(required)) |bound| {
                if (!self.isCallableBound(bound)) continue;
                const raw = try self.boundSignature(self.program.moduleOf(required), required, bound);
                const signature = try self.builder.substitute(raw, required.index(), carried.args);
                if (signature != .poison and std.mem.indexOfScalar(TypeId, out.items, signature) == null) {
                    try out.append(self.gpa, signature);
                }
            }
        }

        return if (out.items.len == 0) &.{} else out.toOwnedSlice(self.gpa);
    }

    const BoundTraitKey = struct {
        trait: u32,
        args: []const TypeId,
        written: node.TypeRefRange,
    };

    const BoundTraitContext = struct {
        checker: *const Checker,

        pub fn hash(self: @This(), key: BoundTraitKey) u64 {
            var h: std.hash.Wyhash = .init(key.trait);
            h.update(std.mem.sliceAsBytes(key.args));
            const written = resolve_mod.hashBoundArgs(self.checker.ast, self.checker.settledWritten(), key.written) catch unreachable;
            h.update(std.mem.asBytes(&written));
            return h.final();
        }

        pub fn eql(self: @This(), a: BoundTraitKey, b: BoundTraitKey) bool {
            return a.trait == b.trait and
                std.mem.eql(TypeId, a.args, b.args) and
                self.checker.sameBoundArgs(a.written, b.written);
        }
    };

    const BoundTraitSet = std.HashMapUnmanaged(BoundTraitKey, void, BoundTraitContext, 80);

    /// Appends a bound to what a run of them admits, unless the same bound is
    /// already there.
    ///
    /// The pair, because one type may implement one trait once per argument
    /// list: `Lookup[UInt64]` and `Lookup[Bool]` are two bounds, each
    /// discharged by its own implementation, and only `Lookup[UInt64]`
    /// written twice is the repetition a program means as one. A list that
    /// held one bound twice would also walk it twice, which over a
    /// requirement that cycles would not finish.
    ///
    /// Both halves of what an entry holds, because an entry answers two
    /// questions and each is keyed by what it answers with. `args` is what
    /// `boundsCarry` discharges at, so an entry naming other arguments is
    /// another requirement however it was spelled: one trait required at its
    /// own parameter, reached through `Fancy[UInt64]` and again through
    /// `Fancy[Bool]`, is the same written bound twice and two requirements,
    /// and a key reading only the spelling drops the second. `written` is what
    /// `boundArgsWritten` picks an entry out by, so an entry made by another
    /// written bound cannot stand in for one this list never appended.
    ///
    /// The written half is `sameBoundArgs`, which is the comparison the
    /// resolver counts distinct bounds under: a parameter carrying two entries
    /// here and one there would make what a body may rely on differ from what
    /// a settled reference reads.
    fn admitOnce(
        self: *Checker,
        out: *std.ArrayList(types_mod.BoundTrait),
        seen: *BoundTraitSet,
        context: BoundTraitContext,
        trait: node.DeclId,
        written: node.TraitBound,
        args: []const TypeId,
    ) std.mem.Allocator.Error!void {
        const named: u32 = @intCast(trait.index());
        const key: BoundTraitKey = .{ .trait = named, .args = args, .written = written.named.args };
        if (seen.containsContext(key, context)) {
            if (args.len > 0) self.gpa.free(args);
            return;
        }
        seen.putContext(self.gpa, key, {}, context) catch |err| {
            if (args.len > 0) self.gpa.free(args);
            return err;
        };
        out.append(self.gpa, .{ .trait = named, .args = args, .written = written }) catch |err| {
            _ = seen.removeContext(key, context);
            if (args.len > 0) self.gpa.free(args);
            return err;
        };
    }

    /// Whether two bounds' written arguments are one bound's, by the routine
    /// the resolver counts repeated bounds with, over what this pass folded.
    fn sameBoundArgs(self: *const Checker, a: node.TypeRefRange, b: node.TypeRefRange) bool {
        return resolve_mod.sameBoundArgs(self.ast, self.settledWritten(), a, b) catch unreachable;
    }

    /// What the names and constants a bound writes are read through here: the
    /// tables resolution left and what this pass folded.
    fn settledWritten(self: *const Checker) resolve_mod.SettledWritten {
        return .{ .ast = self.ast, .res = self.res, .memo = &self.folded };
    }

    /// The arguments the parameter `t` was interned with for one written
    /// bound on it, and empty where it carries no such bound.
    ///
    /// The written bound picks the entry, not its trait: a parameter bounded
    /// on one trait at several arguments carries an entry per bound, and the
    /// first entry naming the trait answers for whichever bound was written
    /// first rather than for the one being asked about.
    ///
    /// **Bound:** the bounds written on the one parameter.
    fn boundArgsWritten(
        self: *const Checker,
        t: TypeId,
        trait: node.DeclId,
        written: node.TraitBound,
    ) []const TypeId {
        const named: u32 = @intCast(trait.index());
        for (self.builder.boundsOn(t)) |seen| {
            if (seen.trait != named) continue;
            if (!self.sameBoundArgs(seen.written.named.args, written.named.args)) continue;
            return seen.args;
        }
        return &.{};
    }

    /// What a parameter's bounds amount to, as one number.
    ///
    /// Refuses every bound list that asks a capability of a name twice.
    ///
    /// A list is checked once, where it is written, rather than at each body or
    /// call that reads what it demands: the two failures below are properties
    /// of the list alone, and a name nothing can be passed as is a mistake in
    /// the declaration the way an unused one is.
    ///
    /// Every list the program writes: a declaration's own bounds, which is what
    /// a trait requires and what an implementation of a declared type must
    /// settle, and the bounds on each type parameter it declares.
    ///
    /// **Bound:** one visit per declaration and per type parameter, and per
    /// list the traits its bounds reach -- the closure `traitsBounding` walks,
    /// which is what interning a type parameter already costs.
    fn reportCapabilityDemands(self: *Checker) std.mem.Allocator.Error!void {
        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            const own = self.ast.declBounds(d);
            if (own.len > 0) {
                try self.reportCapabilityDemand(own, self.ast.declName(d));
                if (ownedBound(self.ast, self.res, own)) |bound| try self.sink.addErrorFmt(
                    .t_bound,
                    self.ast.fileOf(bound),
                    self.ast.tokenSpan(bound),
                    "write `Owned` on the type parameter that needs it",
                    "`Owned` bounds a type parameter, and `{s}` is not one",
                    .{self.ast.tokenText(self.ast.declName(d))},
                );
            }
            for (self.ast.declTypeParams(d), 0..) |p, k| {
                try self.reportCapabilityDemand(self.parameterBounds(d, k), p.name);
            }
        }
    }

    /// Whether `subject` is a parameter of `d`, or the stand-in for an
    /// associated type read through one.
    fn ownsSubject(self: *const Checker, d: node.DeclId, subject: TypeId) bool {
        if (self.builder.get(subject) != .parameter) return false;
        var root = subject;
        while (self.builder.standinOf(root)) |standin| root = standin.held;
        return switch (self.builder.get(root)) {
            .parameter => |p| self.builder.standinOf(root) == null and p.owner == d.index(),
            else => false,
        };
    }

    /// Records an `Owned` promise a declaration's `where` clause makes about a
    /// written subject, or refuses it.
    ///
    /// The seed reads `Owned` from the record of the parameter a type stands
    /// for, so a promise holds only for a subject whose record belongs to the
    /// declaration that writes it: one of its own parameters, or an associated
    /// type read through one, `I.Item` under `[I: Iterator]` or `Self.Item`
    /// under a trait signature's own `Self`, whose stand-in no other
    /// declaration can name. An enclosing implementation's parameter is
    /// shared with that implementation's other members, and a promise there
    /// would be relied on where nothing checked it.
    fn promiseWrittenOwned(
        self: *Checker,
        d: node.DeclId,
        written: node.TypeRef,
        subject: TypeId,
        bound: TokenId,
        /// The subjects `d`'s clauses have promised so far.
        promised: *std.AutoHashMapUnmanaged(TypeId, void),
    ) std.mem.Allocator.Error!void {
        if (self.ownsSubject(d, subject)) {
            if ((try promised.getOrPut(self.gpa, subject)).found_existing) return self.sink.addErrorFmt(
                .t_bound,
                self.ast.fileOf(bound),
                self.ast.tokenSpan(bound),
                "drop one of the two bounds",
                "`{s}` is bounded `Owned` twice",
                .{self.ast.writtenText(written)},
            );
            return self.builder.promiseOwned(subject);
        }
        // The signature's contract would be inferred as if the promise held
        // for some instantiations and not others; the refusal is the mistake,
        // so the contract is left undecided and nothing is reported against it.
        try self.refused_owned_promises.put(self.gpa, d, {});
        try self.refused_owned_subjects.put(self.gpa, .{ .decl = d, .subject = subject }, {});
        // An implementation's parameter is promised in the implementation's
        // own clause, which every member then relies on.
        const help = if (self.implementationOwning(subject) != null)
            (try self.boundsEdit("Owned", subject)).edit
        else
            "write `Owned` where the type parameter is declared";
        try self.sink.addErrorFmt(
            .t_bound,
            self.ast.fileOf(bound),
            self.ast.tokenSpan(bound),
            help,
            "`Owned` bounds a type parameter of the declaration that writes it, and `{s}` is not one of `{s}`'s",
            .{ self.ast.writtenText(written), self.ast.tokenText(self.ast.declName(d)) },
        );
    }

    /// Rejects repeated or redundant capability bounds, preserving the trait
    /// bounds that also provide operations.
    fn reportCapabilityDemand(
        self: *Checker,
        bounds: []const node.TraitBound,
        named: TokenId,
    ) std.mem.Allocator.Error!void {
        const through = try self.traitsBounding(null, bounds);
        defer types_mod.freeBoundTraits(self.gpa, through);
        const demand = capabilityDemand(self.ast, self.res, bounds, through);

        // A declaration whose name the parser never read still wrote a list,
        // and a bound on that list is a token that is there.
        const at = if (named != .none) named else bounds[0].named.name;

        if (ownedBound(self.ast, self.res, bounds)) |first| {
            for (bounds) |bound| {
                if (bound.kind != .named or bound.named.name == first) continue;
                if (resolve_mod.boundNames(self.ast, bound.named.name, traitAt(self.ast, self.res, bound.named.name)) != .owned) continue;
                return self.sink.addErrorFmt(
                    .t_bound,
                    self.ast.fileOf(at),
                    self.ast.tokenSpan(at),
                    "drop one of the two bounds",
                    "`{s}` is bounded `Owned` twice",
                    .{self.ast.tokenText(at)},
                );
            }
            if (integerDemandedBy(self.ast, self.res, bounds, through)) {
                return self.sink.addError(.t_bound, self.ast.fileOf(at), self.ast.tokenSpan(at), "Integer already includes Owned", "drop the redundant Owned bound");
            }
        }

        if (demand.copyable.demanded() and demand.discardable.written != .none) {
            return self.sink.addError(.t_bound, self.ast.fileOf(at), self.ast.tokenSpan(at), "Copyable already includes Discardable", "drop the redundant Discardable bound");
        }
        if (demand.unrestricted.written != .none and (demand.copyable.demanded() or demand.discardable.demanded())) {
            return self.sink.addError(.t_bound, self.ast.fileOf(at), self.ast.tokenSpan(at), "Linear adds no capability requirement", "drop the redundant Linear bound");
        }
        var source: Demanded = demand.copyable;
        var requirement_name: []const u8 = "Copyable";
        if (!source.restated()) {
            source = demand.discardable;
            requirement_name = "Discardable";
        }
        if (!source.restated()) {
            source = demand.unrestricted;
            requirement_name = "Linear";
        }
        if (!source.restated()) return;

        if (source.again != .none) {
            return self.sink.addErrorFmt(
                .t_bound,
                self.ast.fileOf(at),
                self.ast.tokenSpan(at),
                "drop one of the two bounds",
                "`{s}` is bounded `{s}` twice",
                .{ self.ast.tokenText(at), requirement_name },
            );
        }

        try self.sink.addErrorFmt(
            .t_bound,
            self.ast.fileOf(at),
            self.ast.tokenSpan(at),
            "drop the bound the trait already carries",
            "`{s}` is bounded `{s}`, and `{s}` demands it already",
            .{
                self.ast.tokenText(at),
                requirement_name,
                self.ast.tokenText(self.ast.declName(source.through)),
            },
        );
    }

    /// Refuses every bound whose argument count does not match its trait's
    /// parameter count.
    ///
    /// A trait's parameters are as much of what it declares as its members
    /// are, and a bound stands for an instantiation of it -- so a bound
    /// supplying too few leaves a parameter nothing settles, and one supplying
    /// too many is a substitution with nowhere for the extra to land. One
    /// comparison answers both, matching the rule already stated for a
    /// written type's own arguments.
    ///
    /// A bound naming a capability or nothing at all reaches no trait through
    /// `traitAt` and is left alone here: a capability's own refusal is the
    /// resolver's, asked while `b.args` is still in hand, and a name nothing
    /// declares is refused as an unknown trait rather than as a count.
    ///
    /// **Bound:** one visit per declaration and per type parameter it
    /// declares, and one lookup per bound each carries.
    fn reportBoundArity(self: *Checker) std.mem.Allocator.Error!void {
        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            try self.reportBoundArityOf(self.ast.declBounds(d));
            for (self.ast.declTypeParams(d), 0..) |_, k| {
                try self.reportBoundArityOf(self.parameterBounds(d, k));
            }
        }
    }

    /// Refuses each bound in one run whose argument count does not match its
    /// trait's parameter count.
    fn reportBoundArityOf(
        self: *Checker,
        bounds: []const node.TraitBound,
    ) std.mem.Allocator.Error!void {
        for (bounds) |b| {
            const trait = traitAt(self.ast, self.res, b.named.name) orelse continue;
            const declares: usize = self.ast.declTypeParams(trait).len;
            const supplies: usize = b.named.args.len();
            if (declares == supplies) continue;

            try self.sink.addErrorFmt(
                .t_bound,
                self.ast.fileOf(b.named.name),
                self.ast.tokenSpan(b.named.name),
                if (declares == 0) "this trait takes no arguments" else "supply the arguments it declares",
                "`{s}` takes {d} type argument(s), and this bound supplies {d}",
                .{ self.ast.tokenText(b.named.name), declares, supplies },
            );
        }
    }

    /// One trait on the walk that refuses a bound cycle, and how many of its
    /// own bounds have been stepped through. Named rather than local to the
    /// walk, because the message reads the path out and so takes it.
    const Descent = struct { trait: node.DeclId, at: usize };

    /// Refuses a trait whose own bounds reach itself.
    ///
    /// `trait A: B` with `trait B: A` is a pair neither of which can be
    /// implemented first: an implementation of each owes the other, so no
    /// source discharges either and a bound naming one promises operations no
    /// type could have. Reported where the bound that closes the cycle is
    /// written, which is the token a reader has to change.
    ///
    /// **Bound:** one visit per trait the program declares and one step per
    /// bound each writes -- a single depth-first walk over the whole graph,
    /// not one per trait. The path is a list rather than a stack of calls,
    /// because how deep a chain of traits runs is what the source decides.
    fn reportTraitBoundCycles(self: *Checker) std.mem.Allocator.Error!void {
        // Unvisited, on the walk's current path, or finished. A bound reaching
        // one still on the path closes a cycle; one reaching a finished trait
        // reaches a part of the graph already known to hold none.
        const Colour = enum(u8) { unvisited, on_path, done };
        const colour = try self.gpa.alloc(Colour, self.ast.declCount());
        defer self.gpa.free(colour);
        @memset(colour, .unvisited);

        var path: std.ArrayList(Descent) = .empty;
        defer path.deinit(self.gpa);

        for (0..self.ast.declCount()) |i| {
            const root = node.DeclId.at(@intCast(i));
            if (self.ast.declTag(root) != .trait_) continue;
            if (colour[i] != .unvisited) continue;

            colour[i] = .on_path;
            try path.append(self.gpa, .{ .trait = root, .at = 0 });
            while (path.items.len > 0) {
                const from = path.items[path.items.len - 1].trait;
                const bounds = self.ast.declBounds(from);
                const step = path.items[path.items.len - 1].at;
                if (step == bounds.len) {
                    colour[from.index()] = .done;
                    _ = path.pop();
                    continue;
                }
                path.items[path.items.len - 1].at = step + 1;

                const required = traitAt(self.ast, self.res, bounds[step].named.name) orelse continue;
                switch (colour[required.index()]) {
                    .done => {},
                    .unvisited => {
                        colour[required.index()] = .on_path;
                        try path.append(self.gpa, .{ .trait = required, .at = 0 });
                    },
                    .on_path => try self.refuseBoundCycle(path.items, from, required, bounds[step].named.name),
                }
            }
        }
    }

    /// Reports the bound that closes a cycle, naming every requirement on it.
    ///
    /// The whole cycle rather than its two ends: a run of three or more traits
    /// closes on a pair that require each other only through the ones between
    /// them, so a message naming the pair alone states a requirement no
    /// declaration wrote and sends a reader to a bound that is not there.
    ///
    /// Read from where `required` sits on the walk's path round to the end of
    /// it, which is the cycle: everything before that point leads into the
    /// cycle without being on it.
    ///
    /// **Bound:** the traits on the cycle, which is at most the path the walk
    /// is already holding.
    fn refuseBoundCycle(
        self: *Checker,
        path: []const Descent,
        requiring: node.DeclId,
        required: node.DeclId,
        at: TokenId,
    ) std.mem.Allocator.Error!void {
        const one = self.ast.tokenText(self.ast.declName(requiring));
        if (requiring == required) {
            return self.sink.addErrorFmt(
                .t_bound,
                self.ast.fileOf(at),
                self.ast.tokenSpan(at),
                "drop the bound",
                "`{s}` requires itself",
                .{one},
            );
        }

        // From the bound that closes the cycle, because that is the token
        // underlined, and then forward along the path until it comes back
        // round to here.
        var start: usize = 0;
        while (path[start].trait != required) start += 1;

        var said: std.ArrayList(u8) = .empty;
        defer said.deinit(self.gpa);
        const clauses = path.len - start;
        for (0..clauses) |k| {
            const from = if (k == 0) requiring else path[start + k - 1].trait;
            const to = if (k == 0) required else path[start + k].trait;
            if (k > 0) try said.appendSlice(self.gpa, ", ");
            if (k == clauses - 1) try said.appendSlice(self.gpa, "and ");
            try said.print(self.gpa, "`{s}` requires `{s}`", .{
                self.ast.tokenText(self.ast.declName(from)),
                self.ast.tokenText(self.ast.declName(to)),
            });
        }

        try self.sink.addErrorFmt(
            .t_bound,
            self.ast.fileOf(at),
            self.ast.tokenSpan(at),
            if (clauses == 2) "drop one of the two bounds" else "drop one of the bounds on the cycle",
            "{s}",
            .{said.items},
        );
    }

    /// A signature's type, read through what was supplied for its trait.
    ///
    /// A trait's parameter is a type only once something says what it stands
    /// for, and two things do: an implementation says it by supplying the
    /// argument, and a call says it by settling one. Both arrive here, because
    /// a signature read one way at an `impl` and another way at a call is one
    /// rule with two answers.
    fn throughTrait(
        self: *Checker,
        ty: TypeId,
        trait: node.DeclId,
        args: []const TypeId,
    ) std.mem.Allocator.Error!TypeId {
        if (args.len == 0) return ty;
        return self.builder.substitute(ty, @intCast(trait.index()), args);
    }

    /// The first member bound absent from the signature, or signature bound
    /// absent from the member, after their own parameters are lined up.
    fn unmatchedMemberBound(
        self: *Checker,
        sig: node.DeclId,
        member: node.DeclId,
        trait_decl: node.DeclId,
        trait_args: []const TypeId,
        declared: []const node.TraitBound,
        supplied: []const node.TraitBound,
        signature_parameters: []const TypeId,
        find_added: bool,
    ) std.mem.Allocator.Error!?node.TraitBound {
        const candidates = if (find_added) supplied else declared;
        const counterparts = if (find_added) declared else supplied;
        for (candidates) |candidate| {
            if (candidate.kind == .named and
                resolve_mod.boundNames(self.ast, candidate.named.name, traitAt(self.ast, self.res, candidate.named.name)) == .capability)
            {
                continue;
            }

            var matched = false;
            for (counterparts) |counterpart| {
                const signature_bound = if (find_added) counterpart else candidate;
                const member_bound = if (find_added) candidate else counterpart;
                if (!try self.memberBoundsAlike(
                    sig,
                    member,
                    trait_decl,
                    trait_args,
                    signature_parameters,
                    signature_bound,
                    member_bound,
                )) continue;
                matched = true;
                break;
            }
            if (!matched) return candidate;
        }
        return null;
    }

    /// Whether one signature bound and one member bound denote the same
    /// requirement after the member's k-th parameter is read as the
    /// signature's k-th parameter.
    fn memberBoundsAlike(
        self: *Checker,
        sig: node.DeclId,
        member: node.DeclId,
        trait_decl: node.DeclId,
        trait_args: []const TypeId,
        signature_parameters: []const TypeId,
        declared: node.TraitBound,
        supplied: node.TraitBound,
    ) std.mem.Allocator.Error!bool {
        if (declared.kind != supplied.kind) return false;
        if (declared.kind == .callable) {
            const wanted = try self.throughTrait(
                try self.typeOfRefOf(self.program.moduleOf(sig), sig, self.ast.callableRef(declared.callable)),
                trait_decl,
                trait_args,
            );
            const got = try self.builder.substitute(
                try self.typeOfRefOf(self.program.moduleOf(member), member, self.ast.callableRef(supplied.callable)),
                @intCast(member.index()),
                signature_parameters,
            );
            return wanted == .poison or got == .poison or wanted == got;
        }

        const wanted_name = resolve_mod.boundNames(
            self.ast,
            declared.named.name,
            traitAt(self.ast, self.res, declared.named.name),
        );
        const got_name = resolve_mod.boundNames(
            self.ast,
            supplied.named.name,
            traitAt(self.ast, self.res, supplied.named.name),
        );
        switch (wanted_name) {
            .capability => return false,
            .integer => if (got_name != .integer) return false,
            .owned => if (got_name != .owned) return false,
            .trait => |wanted| switch (got_name) {
                .trait => |got| if (wanted != got) return false,
                else => return false,
            },
            .unknown => switch (got_name) {
                .unknown => if (self.ast.tokenName(declared.named.name) != self.ast.tokenName(supplied.named.name)) return false,
                else => return false,
            },
        }

        const wanted_args = self.ast.typeArgs(declared.named.args);
        const got_args = self.ast.typeArgs(supplied.named.args);
        if (wanted_args.len != got_args.len) return false;
        for (wanted_args, got_args) |wanted_ref, got_ref| {
            const wanted = try self.throughTrait(
                try self.typeOfRefOf(self.program.moduleOf(sig), sig, wanted_ref),
                trait_decl,
                trait_args,
            );
            const got = try self.builder.substitute(
                try self.typeOfRefOf(self.program.moduleOf(member), member, got_ref),
                @intCast(member.index()),
                signature_parameters,
            );
            if (wanted != .poison and got != .poison and wanted != got) return false;
        }
        return true;
    }

    /// Applies the one callable compatibility rule to a member/signature pair.
    /// A call is typed against the signature and runs the member's body, so
    /// their conventions, defaults, parameter types and result must agree even
    /// though each declaration is independently well typed.
    ///
    /// `held` is either an ordinary implementation's settled head or the open
    /// `Self` parameter of an inactive structural template.
    fn checkMemberMatches(
        self: *Checker,
        mismatch_code: Code,
        held: TypeId,
        trait_token: TokenId,
        trait_decl: node.DeclId,
        trait_args: []const TypeId,
        sig: node.DeclId,
        member: node.DeclId,
    ) std.mem.Allocator.Error!void {
        const errors_before = self.sink.error_count;
        try self.compareMember(mismatch_code, held, trait_token, trait_decl, trait_args, sig, member);
        // A member that does not match its signature adopted a contract
        // written over other parameters or another result, so its body is not
        // checked against it: the mismatch is its error.
        if (self.sink.error_count != errors_before and self.adopted_contracts.contains(member))
            try self.declined_contracts.put(self.gpa, member, {});
    }

    fn compareMember(
        self: *Checker,
        mismatch_code: Code,
        held: TypeId,
        trait_token: TokenId,
        trait_decl: node.DeclId,
        trait_args: []const TypeId,
        sig: node.DeclId,
        member: node.DeclId,
    ) std.mem.Allocator.Error!void {
        const at = self.ast.declName(member);
        const file = self.ast.fileOf(at);
        const span = self.ast.tokenSpan(at);
        const trait = self.ast.tokenText(trait_token);
        const name = self.ast.tokenText(at);

        const declares = self.ast.declParams(sig);
        const supplies = self.ast.declParams(member);
        if (declares.len != supplies.len) {
            return self.sink.addErrorFmt(
                mismatch_code,
                file,
                span,
                "take what the signature takes",
                "`{s}` declares `{s}` taking {d} parameter(s), and this takes {d}",
                .{ trait, name, declares.len, supplies.len },
            );
        }

        // An operation generic on its own account declares parameters that
        // belong to it, and the member declares its own. The two stand in the
        // same place and are not one type, so a comparison by identity refuses
        // every such implementation -- and says so by reporting one name
        // against itself.
        const wants = self.ast.declTypeParams(sig);
        const gots = self.ast.declTypeParams(member);
        if (wants.len != gots.len) {
            return self.sink.addErrorFmt(
                mismatch_code,
                file,
                span,
                "take the type parameters the signature takes",
                "`{s}` declares `{s}` over {d} type parameter(s), and this declares {d}",
                .{ trait, name, wants.len, gots.len },
            );
        }

        // The signature's parameters, which the member's are read as: the k-th
        // of one answers for the k-th of the other, which is what makes two
        // declarations of one operation comparable at all.
        const onto: []const TypeId = if (sig.index() < self.param_types.len)
            self.param_types[sig.index()]
        else
            &.{};

        // Standing in the same place means admitting the same arguments, so
        // the k-th of each carries the same bounds. A bound is two facts at
        // once -- what the body may rely on, and what an argument is held to --
        // and only the signature reaches a call, so a bound the member adds is
        // relied on by the body and asked of nothing. The capability is where
        // that is worst: copyability is read off the bound written here, so an
        // added `Copyable` licenses a `copy` of whatever the call supplied.
        //
        // Both directions, because a bound the member drops is the same fact
        // the other way round: the body is checked against less than every
        // caller was promised, and the signature is what the promise is.
        for (wants, gots, 0..) |want, _, k| {
            const declared = self.parameterBounds(sig, k);
            const supplied = self.parameterBounds(member, k);
            const written = self.ast.tokenText(want.name);

            const owes = try self.traitsBounding(null, declared);
            defer types_mod.freeBoundTraits(self.gpa, owes);
            const asks = try self.traitsBounding(null, supplied);
            defer types_mod.freeBoundTraits(self.gpa, asks);

            const owed = capabilityDemandedBy(self.ast, self.res, declared, owes);
            const asked = capabilityDemandedBy(self.ast, self.res, supplied, asks);
            if (owed != asked) {
                return self.sink.addErrorFmt(
                    mismatch_code,
                    file,
                    span,
                    "bound it the way the signature bounds it",
                    "`{s}` bounds `{s}`'s `{s}` `{s}`, and this bounds it `{s}`",
                    .{ trait, name, written, @tagName(owed), @tagName(asked) },
                );
            }

            if (try self.unmatchedMemberBound(
                sig,
                member,
                trait_decl,
                trait_args,
                declared,
                supplied,
                onto,
                true,
            )) |added| {
                const asks_for = try spellBound(self.gpa, self.ast, added);
                defer self.gpa.free(asks_for);
                return self.sink.addErrorFmt(
                    mismatch_code,
                    file,
                    span,
                    "drop it; the signature is what every call is checked against",
                    "`{s}` does not bound `{s}`'s `{s}` by `{s}`",
                    .{ trait, name, written, asks_for },
                );
            }

            if (try self.unmatchedMemberBound(
                sig,
                member,
                trait_decl,
                trait_args,
                declared,
                supplied,
                onto,
                false,
            )) |dropped| {
                const owed_bound = try spellBound(self.gpa, self.ast, dropped);
                defer self.gpa.free(owed_bound);
                return self.sink.addErrorFmt(
                    mismatch_code,
                    file,
                    span,
                    "bound it the way the signature bounds it",
                    "`{s}` bounds `{s}`'s `{s}` by `{s}`, and this does not",
                    .{ trait, name, written, owed_bound },
                );
            }
        }

        const enclosing_self = self.self_at_call;
        const enclosing_args = self.trait_args_at_call;
        const enclosing_settled = self.self_settled;
        defer {
            self.self_at_call = enclosing_self;
            self.trait_args_at_call = enclosing_args;
            self.self_settled = enclosing_settled;
        }
        self.self_at_call = held;
        self.self_settled = true;
        self.trait_args_at_call = trait_args;

        // Only the trait signature supplies defaults. Check this even when
        // an implementation's callable signature cannot be constructed.
        for (declares, supplies) |want, got| {
            if (hasDefault(got)) {
                if (hasDefault(want)) {
                    return self.sink.addErrorFmt(
                        mismatch_code,
                        file,
                        span,
                        "drop it; the signature declares it",
                        "`{s}` declares `{s}`'s `{s}` default; an implementation does not restate it",
                        .{ trait, name, self.ast.tokenText(want.name) },
                    );
                }
                return self.sink.addErrorFmt(
                    mismatch_code,
                    file,
                    span,
                    "declare it on the signature, which is what every call reads",
                    "`{s}` declares `{s}`'s `{s}` and no default for it; an implementation does not add one",
                    .{ trait, name, self.ast.tokenText(want.name) },
                );
            }
        }

        // The same holds for the default of a method's type parameter.
        const declared_generics = self.ast.declTypeParams(sig);
        for (self.ast.declTypeParams(member), 0..) |got, i| {
            if (!got.default.wasWritten()) continue;
            const parameter = self.ast.tokenText(got.name);
            if (i < declared_generics.len and declared_generics[i].default.wasWritten()) {
                return self.sink.addErrorFmt(
                    mismatch_code,
                    file,
                    span,
                    "drop it; the signature declares it",
                    "`{s}` declares `{s}`'s type parameter `{s}` default; an implementation does not restate it",
                    .{ trait, name, parameter },
                );
            }
            return self.sink.addErrorFmt(
                mismatch_code,
                file,
                span,
                "declare it on the signature, which is what every call reads",
                "`{s}` declares `{s}`'s type parameter `{s}` and no default for it; an implementation does not add one",
                .{ trait, name, parameter },
            );
        }

        try self.ensureSignature(sig);
        try self.ensureSignature(member);
        if (self.decl_signatures.get(sig) == .poison or self.decl_signatures.get(member) == .poison) return;
        const promised_signature = self.builder.get(self.decl_signatures.get(sig)).callable;
        const supplied_signature = self.builder.get(self.decl_signatures.get(member)).callable;
        const promised_contracts = promised_signature.contracts;
        const supplied_contracts = supplied_signature.contracts;
        if (!types_mod.contractsWithin(supplied_contracts, promised_contracts)) {
            return self.sink.addError(.t_borrow_contract, file, span, "the implementation's sources exceed the trait signature", "declare these sources on the trait signature or remove the extra effects");
        }

        const member_params = try self.gpa.dupe(types_mod.CallableParam, self.builder.callableParams(supplied_signature));
        defer self.gpa.free(member_params);
        var needs_stable_abi = false;
        for (member_params, self.builder.callableParams(promised_signature)) |*param, promised| {
            if (promised.stable_address and !param.stable_address) {
                param.stable_address = true;
                needs_stable_abi = true;
            }
        }
        if (needs_stable_abi) self.decl_signatures.set(member, try self.builder.internCallable(member_params, supplied_signature.result, supplied_contracts, supplied_signature.invocation));

        // Which parameter is the receiver, where the member has one that is
        // held to a ceiling rather than to equality. Read once, because the
        // question is about the member and not about each parameter.
        const has_a_ceiling = memberKind(self.ast, sig) == .projection;

        // Reflection may rename unused binders hygienically. The template
        // origin owns their public names, while contracts use emitted binders.
        const member_names = names: {
            const origin = self.program.originOf(member) orelse break :names supplies;
            if (origin.template_member == .none) break :names supplies;
            const original = self.ast.declParams(origin.template_member);
            std.debug.assert(original.len == supplies.len);
            break :names original;
        };

        for (declares, supplies, 0..) |want, got, k| {
            // The signature owns the name, because the signature is what every
            // call is checked against: an argument naming the parameter it
            // fills spells what the trait declares, and a member renaming it
            // declares a name no call can write.
            if (!namedAlike(self.ast, want.name, member_names[k].name)) {
                return self.sink.addErrorFmt(
                    mismatch_code,
                    file,
                    span,
                    "name it what the signature names it",
                    "`{s}` declares `{s}`'s parameter `{s}`, and this declares it `{s}`",
                    .{ trait, name, self.ast.tokenText(want.name), self.ast.tokenText(got.name) },
                );
            }

            // A projection's receiver mode is a ceiling rather than a
            // requirement: the trait states the most a conforming
            // implementation may ever let a site's position take through the
            // place, and a container that only hands its elements out to be
            // read declares less and is conforming. Every other parameter, and
            // every parameter of an operation, agrees exactly -- a call is
            // typed against the signature and runs the member, so a mode the
            // two disagree about is an argument passed one way and received
            // another.
            if (has_a_ceiling and k == 0) {
                if (accessGranted(got.convention) > accessGranted(want.convention)) {
                    return self.sink.addErrorFmt(
                        .t_projection,
                        file,
                        span,
                        "declare it the way the trait declares it, or lower",
                        "`{s}` lets `{s}` reach `{s}` at most, and this declares `{s}`",
                        .{ trait, name, @tagName(want.convention), @tagName(got.convention) },
                    );
                }
            } else if (want.convention != got.convention) {
                return self.sink.addErrorFmt(
                    mismatch_code,
                    file,
                    span,
                    "pass it the way the signature does",
                    "`{s}` declares `{s}`'s `{s}` `{s}`, and this declares it `{s}`",
                    .{
                        trait,
                        name,
                        self.ast.tokenText(want.name),
                        @tagName(want.convention),
                        @tagName(got.convention),
                    },
                );
            }

            const wanted = try self.throughTrait(
                try paramType(self, sig, k),
                trait_decl,
                trait_args,
            );
            const supplied = try self.builder.substitute(
                try paramType(self, member, k),
                @intCast(member.index()),
                onto,
            );
            if (wanted == .poison or supplied == .poison) continue;
            if (wanted == supplied) continue;

            return self.sink.addErrorFmt(
                mismatch_code,
                file,
                span,
                "take the type the signature declares",
                "`{s}` declares `{s}`'s `{s}` as `{s}`, and this takes `{s}`",
                .{
                    trait,
                    name,
                    self.ast.tokenText(want.name),
                    (try self.typeName(wanted)),
                    (try self.typeName(supplied)),
                },
            );
        }

        // Compared as types, an omitted result included: it is `()`, so a
        // signature that writes none and a member that writes `UInt8` differ
        // the way any two results do.
        const wanted = try self.throughTrait(try returnType(self, sig), trait_decl, trait_args);
        const supplied = try self.builder.substitute(
            try returnType(self, member),
            @intCast(member.index()),
            onto,
        );
        if (wanted == .poison or supplied == .poison) return;
        if (wanted == supplied) return;

        try self.sink.addErrorFmt(
            mismatch_code,
            file,
            span,
            "return the type the signature declares",
            "`{s}` declares `{s}` returning `{s}`, and this returns `{s}`",
            .{ trait, name, (try self.typeName(wanted)), (try self.typeName(supplied)) },
        );
    }

    /// Refuse recurring type arguments whose structural height is unbounded.
    /// Only constructor-growing calls need a bounded-reentry query.
    fn checkPolyRec(self: *Checker) std.mem.Allocator.Error!void {
        // A program with no accepted calls has no recursive call edge.
        if (self.calls.items.len == 0) return;

        // Which declaration each token sits in, written in declaration order
        // so a function declared inside another takes the tokens they share.
        // Filled per token rather than by asking every declaration about every
        // expression: that question is the product of the two, and this pass
        // asks it whether or not a program has anything for it to find.
        const by_token = try self.gpa.alloc(node.DeclId, self.ast.tokenCount());
        defer self.gpa.free(by_token);
        @memset(by_token, node.DeclId.none);
        for (0..self.ast.declCount()) |i| {
            const d = node.DeclId.at(@intCast(i));
            if (self.ast.declTag(d) != .function) continue;
            const extent = self.ast.declTokens(d);
            @memset(by_token[extent.start.index()..extent.end.index()], d);
        }

        const owner = try self.gpa.alloc(node.DeclId, self.ast.exprCount());
        defer self.gpa.free(owner);
        for (0..self.ast.exprCount()) |e| {
            const at = self.ast.exprMain(node.ExprId.at(@intCast(e))).index();
            owner[e] = by_token[at];
        }

        // Index outgoing calls once so each reached body visits its own run.
        const decls = self.ast.declCount();
        const starts = try self.gpa.alloc(u32, decls + 1);
        defer self.gpa.free(starts);
        @memset(starts, 0);

        var total: u32 = 0;
        for (0..self.ast.exprCount()) |e| {
            if (owner[e] == node.DeclId.none) continue;
            if (self.ast.exprTag(node.ExprId.at(@intCast(e))) != .call) continue;
            starts[owner[e].index() + 1] += 1;
            total += 1;
        }
        for (1..decls + 1) |i| starts[i] += starts[i - 1];

        const calls = try self.gpa.alloc(node.ExprId, total);
        defer self.gpa.free(calls);

        const cursor = try self.gpa.alloc(u32, decls);
        defer self.gpa.free(cursor);
        @memcpy(cursor, starts[0..decls]);

        for (0..self.ast.exprCount()) |e| {
            const id = node.ExprId.at(@intCast(e));
            if (owner[e] == node.DeclId.none) continue;
            if (self.ast.exprTag(id) != .call) continue;
            calls[cursor[owner[e].index()]] = id;
            cursor[owner[e].index()] += 1;
        }

        const may_recur = try self.callsMayRecur(owner);
        defer self.gpa.free(may_recur);

        for (self.calls.items) |call| {
            const from = owner[call.at.index()];
            if (from == .none) continue;
            if (!may_recur[from.index()]) continue;
            const to = switch (call.target) {
                .declared => |decl| decl,
                .closure_recovery, .array_view, .array_length, .closure, .indirect, .generic_callable, .erased => continue,
            };

            var grows = try self.instantiatesLarger(call.selection.own_args, from) or
                try self.instantiatesLarger(call.selection.impl_args, from);
            if (call.selection.impl_args.len == 0) {
                if (call.selection.implementation) |implementation| {
                    grows = grows or try self.instantiatesLarger(implementation.args, from) or
                        try self.instantiatesLarger(&.{implementation.self_ty}, from);
                }
            }
            if (!grows) continue;
            if (!try self.reaches(call, from, starts, calls)) continue;

            _ = self.report(
                .t_poly_rec,
                call.at,
                "this call instantiates `{s}` with more than it was given",
                .{self.ast.tokenText(self.ast.declName(to))},
                "type-argument height must remain bounded across recursive calls",
            );
        }
    }

    /// Trait calls reach a signature's suppliers; direct calls reach their
    /// recorded declaration. Both recurrence walks use this dispatch identity.
    fn recurrenceTarget(self: *const Checker, call: types_mod.NormalizedCall) ?DeclId {
        const target = switch (call.target) {
            .declared => |target| target,
            .closure_recovery, .array_view, .array_length, .closure, .indirect, .generic_callable, .erased => return null,
        };
        if (self.dispatchedToSuppliers(call)) |_| return self.supply.signatureOf(target) orelse target;
        return target;
    }

    /// The trait a call reaches its body through, where an implementation
    /// supplies that body. A provided operation is never supplied: it is the
    /// trait's one body at every type, so a call of it reaches that
    /// declaration as a direct call does, whichever implementation it was
    /// reached through. Both recurrence walks ask this, so a provided body
    /// calling itself is an edge back to itself in each.
    fn dispatchedToSuppliers(self: *const Checker, call: types_mod.NormalizedCall) ?types_mod.CallImpl {
        const implementation = call.selection.implementation orelse return null;
        if (!implementation.ofATrait()) return null;
        switch (call.target) {
            .declared => |target| if (self.ast.declIsProvided(target)) return null,
            else => {},
        }
        return implementation;
    }

    /// How many parameters a recurrence frame holds for `d`: its own, and
    /// for a trait's provided operation the symbolic `Self` after them. A
    /// provided operation is one body at every `Self`, so the `Self` a call
    /// reaches it at is an argument of that body as its own parameters are,
    /// and growing it grows the instantiation.
    fn recurrenceParameterCount(self: *const Checker, d: DeclId) usize {
        return self.ast.declTypeParams(d).len + @intFromBool(self.ast.declIsProvided(d));
    }

    /// `d`'s recurrence parameters as its own body reads them. Allocated from
    /// the checker's allocator and the caller's.
    fn recurrenceParameters(self: *const Checker, d: DeclId) std.mem.Allocator.Error![]TypeId {
        const own = self.param_types[d.index()];
        const out = try self.gpa.alloc(TypeId, self.recurrenceParameterCount(d));
        @memcpy(out[0..own.len], own);
        if (out.len > own.len) out[own.len] = self.builder.internedParameter(@intCast(d.index()), @intCast(own.len)) orelse .poison;
        return out;
    }

    /// What a direct call instantiates `target`'s recurrence parameters with:
    /// its own type arguments, and the `Self` a provided operation was reached
    /// at. Allocated from the checker's allocator and the caller's.
    fn recurrenceArguments(self: *const Checker, call: types_mod.NormalizedCall, target: DeclId) std.mem.Allocator.Error![]TypeId {
        const own = call.selection.own_args;
        const provided_self: ?TypeId = if (self.ast.declIsProvided(target))
            if (call.selection.implementation) |implementation| implementation.self_ty else null
        else
            null;
        const out = try self.gpa.alloc(TypeId, own.len + @intFromBool(provided_self != null));
        @memcpy(out[0..own.len], own);
        if (provided_self) |held| out[own.len] = held;
        return out;
    }

    /// Nominal receiver heads survive substitution of their type arguments.
    /// Other shapes retain the signature's complete supplier set.
    fn recurrenceHead(self: *const Checker, receiver: TypeId) ?types_mod.Head {
        switch (self.builder.get(receiver)) {
            .struct_ => if (self.builder.isInterpolation(receiver)) return null,
            .enum_, .newtype => {},
            else => return null,
        }
        return self.builder.headOf(receiver);
    }

    /// Removing sinks proves which declarations cannot reach any call cycle.
    /// Calls with a fixed nominal head share one candidate node; unknown
    /// receivers use the signature's complete supplier set. Candidate selection
    /// ignores predicates, so retained roots still need the weighted query.
    /// Work and storage follow declarations, calls and distinct candidate edges.
    fn callsMayRecur(self: *const Checker, owner: []const DeclId) ![]bool {
        const declarations = self.ast.declCount();
        const Node = enum(u32) { _ };
        const Edge = struct { from: Node, to: Node };
        const Dispatch = struct { signature: DeclId, head: types_mod.Head };
        var dispatches: std.AutoHashMapUnmanaged(Dispatch, Node) = .empty;
        defer dispatches.deinit(self.gpa);
        var edges: std.ArrayList(Edge) = .empty;
        defer edges.deinit(self.gpa);
        for (self.calls.items) |call| {
            const from = owner[call.at.index()];
            if (from == .none) continue;
            const target = self.recurrenceTarget(call) orelse continue;
            var to: Node = @enumFromInt(target.index());
            if (self.dispatchedToSuppliers(call)) |implementation| {
                if (self.recurrenceHead(implementation.self_ty)) |head| {
                    const entry = try dispatches.getOrPut(self.gpa, .{ .signature = target, .head = head });
                    if (!entry.found_existing) {
                        const index = std.math.cast(u32, declarations + dispatches.count() - 1) orelse return error.OutOfMemory;
                        entry.value_ptr.* = @enumFromInt(index);
                        // Parameter-headed and default families remain
                        // candidates even when no concrete choice is justified
                        // in this scope.
                        var candidates = self.builder.impl_index.candidates(self.builder.implementations, implementation.trait, head, true);
                        while (candidates.next()) |candidate| {
                            const row = self.builder.implementations[candidate];
                            const member = self.supply.memberOf(row.decl, target) orelse continue;
                            try edges.append(self.gpa, .{ .from = entry.value_ptr.*, .to = @enumFromInt(member.index()) });
                        }
                    }
                    to = entry.value_ptr.*;
                }
            }
            try edges.append(self.gpa, .{ .from = @enumFromInt(from.index()), .to = to });
        }
        for (0..declarations) |i| {
            const signature = DeclId.at(@intCast(i));
            for (self.supply.membersOf(signature)) |member| {
                try edges.append(self.gpa, .{ .from = @enumFromInt(i), .to = @enumFromInt(member) });
            }
        }
        const count = declarations + dispatches.count();
        const outgoing = try self.gpa.alloc(u32, count);
        defer self.gpa.free(outgoing);
        @memset(outgoing, 0);
        const starts = try self.gpa.alloc(u32, count + 1);
        defer self.gpa.free(starts);
        @memset(starts, 0);
        for (edges.items) |edge| {
            outgoing[@intFromEnum(edge.from)] += 1;
            starts[@intFromEnum(edge.to) + 1] += 1;
        }
        for (1..count + 1) |i| starts[i] += starts[i - 1];
        const cursor = try self.gpa.dupe(u32, starts[0..count]);
        defer self.gpa.free(cursor);
        const predecessors = try self.gpa.alloc(Node, edges.items.len);
        defer self.gpa.free(predecessors);
        for (edges.items) |edge| {
            predecessors[cursor[@intFromEnum(edge.to)]] = edge.from;
            cursor[@intFromEnum(edge.to)] += 1;
        }
        const pending = try self.gpa.alloc(Node, count);
        defer self.gpa.free(pending);
        var tail: usize = 0;
        for (outgoing, 0..) |degree, i| if (degree == 0) {
            pending[tail] = @enumFromInt(i);
            tail += 1;
        };
        var head: usize = 0;
        while (head < tail) : (head += 1) {
            const removed = @intFromEnum(pending[head]);
            for (predecessors[starts[removed]..starts[removed + 1]]) |from| {
                const index = @intFromEnum(from);
                outgoing[index] -= 1;
                if (outgoing[index] == 0) {
                    pending[tail] = from;
                    tail += 1;
                }
            }
        }
        const result = try self.gpa.alloc(bool, declarations);
        for (outgoing[0..declarations], result) |degree, *may_recur| may_recur.* = degree != 0;
        return result;
    }

    /// Both own and implementation arguments use the same structural growth
    /// measure, including parameters determined only by trait arguments.
    fn instantiatesLarger(
        self: *const Checker,
        args: []const TypeId,
        from: node.DeclId,
    ) std.mem.Allocator.Error!bool {
        var search: ParameterSearch = .{ .checker = self, .owner = from, .other = self.headParametersOf(from), .projection = .walks_on, .memoized = true };
        defer search.memo.deinit(self.gpa);
        for (args) |a| {
            if (!self.namesParameterExactly(a) and try search.visit(a)) return true;
        }
        return false;
    }

    /// What `call_of` holds where an expression has no normalized call row.
    const no_call: u32 = std.math.maxInt(u32);

    /// Symbolic dispatch widens each parameter once. A separate height graph
    /// bounds recurring arguments, including calls through unknown suppliers.
    const Reachability = struct {
        checker: *Checker,
        root: DeclId,
        starts: []const u32,
        calls: []const ExprId,
        frames: std.AutoHashMapUnmanaged(DeclId, Frame) = .empty,
        queue: std.ArrayList(DeclId) = .empty,
        origins: std.AutoHashMapUnmanaged(DeclId, types_mod.ImplementationParameters) = .empty,
        edges: std.AutoHashMapUnmanaged(Edge, i64) = .empty,
        alternatives: std.AutoHashMapUnmanaged(AlternativeKey, u32) = .empty,
        vertices: u32 = 3,
        input_own: []const Slot = &.{},
        input_impl: []const Slot = &.{},
        found: bool = false,

        const root_source: u32 = 0;
        const closed_source: u32 = 1;
        const unbounded_source: u32 = 2;
        const Edge = struct { from: u32, to: u32 };
        const Outer = union(enum) {
            unknown,
            known: types_mod.Head,
            callable,
            closure,
            interpolation,

            fn same(self: Outer, other: Outer) bool {
                return switch (self) {
                    .unknown => other == .unknown,
                    .known => |head| other == .known and head.same(other.known),
                    .callable => other == .callable,
                    .closure => other == .closure,
                    .interpolation => other == .interpolation,
                };
            }

            fn of(pool: *const Typing.Builder, ty: TypeId) Outer {
                return switch (pool.get(ty)) {
                    .callable => .callable,
                    .closure => .closure,
                    .struct_ => if (pool.isInterpolation(ty)) .interpolation else .{ .known = pool.headOf(ty) },
                    else => .{ .known = pool.headOf(ty) },
                };
            }

            fn parent(step: types_mod.ImplementationParameters.Step) Outer {
                return switch (step) {
                    .argument => |position| .{ .known = position.head },
                    .borrow_ => .{ .known = .borrow_ },
                    .array => .{ .known = .array },
                    .callable_parameter, .callable_result => .callable,
                };
            }
        };
        const Term = struct { vertex: u32, outer: Outer, offset: i64 = 0 };
        const TermKey = struct { vertex: u32, outer: Outer };
        const Alternative = struct { outer: Outer, vertex: u32 };
        const Slot = struct { alternatives: std.ArrayList(Alternative) = .empty };
        const SlotKey = struct { declaration: DeclId, implementation: bool, index: u32 };
        const AlternativeKey = struct { slot: SlotKey, outer: Outer };
        const Frame = struct {
            own: []TypeId,
            implementation: []TypeId,
            own_slots: []Slot = &.{},
            impl_slots: []Slot = &.{},
            queued: bool = false,
        };

        fn deinit(self: *Reachability) void {
            const gpa = self.checker.gpa;
            var frames = self.frames.valueIterator();
            while (frames.next()) |frame| {
                gpa.free(frame.own);
                gpa.free(frame.implementation);
                freeSlots(gpa, frame.own_slots);
                freeSlots(gpa, frame.impl_slots);
            }
            var origins = self.origins.valueIterator();
            while (origins.next()) |origin| origin.deinit(gpa);
            self.origins.deinit(gpa);
            self.frames.deinit(gpa);
            self.queue.deinit(gpa);
            self.edges.deinit(gpa);
            self.alternatives.deinit(gpa);
        }

        fn freeSlots(gpa: std.mem.Allocator, slots: []Slot) void {
            for (slots) |*slot| slot.alternatives.deinit(gpa);
            gpa.free(slots);
        }

        fn emptySlots(gpa: std.mem.Allocator, count: usize) ![]Slot {
            const slots = try gpa.alloc(Slot, count);
            @memset(slots, .{});
            return slots;
        }

        fn copySlots(gpa: std.mem.Allocator, slots: []const Slot) ![]Slot {
            const copied = try emptySlots(gpa, slots.len);
            errdefer freeSlots(gpa, copied);
            for (slots, copied) |slot, *copy| try copy.alternatives.appendSlice(gpa, slot.alternatives.items);
            return copied;
        }

        fn queueDeclaration(self: *Reachability, declaration: DeclId) !void {
            if (declaration == self.root) return;
            const frame = self.frames.getPtr(declaration).?;
            if (frame.queued) return;
            try self.queue.append(self.checker.gpa, declaration);
            frame.queued = true;
        }

        /// A genuine unknown head has its own alternative. Known alternatives
        /// never acquire that tag merely because several paths join.
        fn alternative(self: *Reachability, key: SlotKey, outer: Outer) !u32 {
            const identity: AlternativeKey = .{ .slot = key, .outer = outer };
            if (self.alternatives.get(identity)) |vertex| return vertex;
            const frame = self.frames.getPtr(key.declaration).?;
            const slots = if (key.implementation) frame.impl_slots else frame.own_slots;
            const slot = &slots[key.index];
            const vertex = try self.allocateVertices(1);
            try slot.alternatives.append(self.checker.gpa, .{ .outer = outer, .vertex = vertex });
            try self.alternatives.put(self.checker.gpa, identity, vertex);
            try self.queueDeclaration(key.declaration);
            return vertex;
        }

        fn contributeTo(self: *Reachability, key: SlotKey, term: Term) !void {
            const to = try self.alternative(key, term.outer);
            try self.edge(term.vertex, to, term.offset);
        }

        fn allocateVertices(self: *Reachability, count: usize) !u32 {
            const start = self.vertices;
            const size = std.math.cast(u32, count) orelse return error.OutOfMemory;
            self.vertices = std.math.add(u32, start, size) catch return error.OutOfMemory;
            return start;
        }

        fn edge(self: *Reachability, from: u32, to: u32, weight: i64) !void {
            const entry = try self.edges.getOrPut(self.checker.gpa, .{ .from = from, .to = to });
            entry.value_ptr.* = if (entry.found_existing) @max(entry.value_ptr.*, weight) else weight;
        }

        /// Exact slots widen once; each new sparse head alternative also
        /// schedules one coalesced visit of its declaration.
        fn run(self: *Reachability, first: types_mod.NormalizedCall) !bool {
            const c = self.checker;
            const over = c.headParametersOf(self.root);
            const initial_own = try c.recurrenceParameters(self.root);
            defer c.gpa.free(initial_own);
            const initial_impl = try c.gpa.dupe(TypeId, if (over == .none) &.{} else c.param_types[over.index()]);
            defer c.gpa.free(initial_impl);
            const own_slots = try emptySlots(c.gpa, initial_own.len);
            defer freeSlots(c.gpa, own_slots);
            const impl_slots = try emptySlots(c.gpa, initial_impl.len);
            defer freeSlots(c.gpa, impl_slots);
            for ([_][]Slot{ own_slots, impl_slots }) |slots| for (slots) |*slot| {
                const vertex = try self.allocateVertices(1);
                try slot.alternatives.append(c.gpa, .{ .outer = .unknown, .vertex = vertex });
                try self.edge(root_source, vertex, 0);
            };
            self.input_own = own_slots;
            self.input_impl = impl_slots;
            const initial: Frame = .{ .own = initial_own, .implementation = initial_impl, .own_slots = own_slots, .impl_slots = impl_slots };
            var initial_scan = Scan.init(self, self.root, initial);
            defer initial_scan.deinit();
            try self.call(first, &initial_scan);
            while (self.queue.pop()) |declaration| {
                const pending = self.frames.getPtr(declaration).?;
                pending.queued = false;
                const pending_own_slots = try copySlots(c.gpa, pending.own_slots);
                defer freeSlots(c.gpa, pending_own_slots);
                const pending_impl_slots = try copySlots(c.gpa, pending.impl_slots);
                defer freeSlots(c.gpa, pending_impl_slots);
                // Recursive edges may widen the stored frame during this visit.
                const own = try c.gpa.dupe(TypeId, pending.own);
                defer c.gpa.free(own);
                const implementation = try c.gpa.dupe(TypeId, pending.implementation);
                defer c.gpa.free(implementation);
                const frame: Frame = .{ .own = own, .implementation = implementation, .own_slots = pending_own_slots, .impl_slots = pending_impl_slots };
                var scan = Scan.init(self, declaration, frame);
                defer scan.deinit();
                for (self.calls[self.starts[declaration.index()]..self.starts[declaration.index() + 1]]) |id| {
                    const at = c.call_of[id.index()];
                    if (at != no_call) try self.call(c.calls.items[at], &scan);
                }
            }
            if (!self.found) return false;
            return try self.unboundedFrom(root_source, true) or
                try self.unboundedFrom(closed_source, false) or
                try self.unboundedFrom(unbounded_source, null);
        }

        /// Maximum paths are finite unless a reachable positive cycle can
        /// reach an output. Checked additions bound intermediate relaxations.
        fn unboundedFrom(self: *Reachability, source: u32, check_positive: ?bool) !bool {
            const gpa = self.checker.gpa;
            const no_path = std.math.minInt(i128);
            const distance = try gpa.alloc(i128, self.vertices);
            defer gpa.free(distance);
            @memset(distance, no_path);
            distance[source] = 0;
            var rounds: u32 = 1;
            while (rounds < self.vertices) : (rounds += 1) {
                var changed = false;
                var edges = self.edges.iterator();
                while (edges.next()) |entry| {
                    const e = entry.key_ptr.*;
                    if (distance[e.from] == no_path) continue;
                    const next = std.math.add(i128, distance[e.from], entry.value_ptr.*) catch return error.OutOfMemory;
                    if (next > distance[e.to]) {
                        distance[e.to] = next;
                        changed = true;
                    }
                }
                if (!changed) break;
            }
            const infinite = try gpa.alloc(bool, self.vertices);
            defer gpa.free(infinite);
            @memset(infinite, false);
            var edges = self.edges.iterator();
            while (edges.next()) |entry| {
                const e = entry.key_ptr.*;
                if (distance[e.from] == no_path) continue;
                const next = std.math.add(i128, distance[e.from], entry.value_ptr.*) catch return error.OutOfMemory;
                if (next > distance[e.to]) infinite[e.to] = true;
            }
            rounds = 0;
            while (rounds < self.vertices) : (rounds += 1) {
                var changed = false;
                edges = self.edges.iterator();
                while (edges.next()) |entry| {
                    const e = entry.key_ptr.*;
                    if (infinite[e.from] and !infinite[e.to]) {
                        infinite[e.to] = true;
                        changed = true;
                    }
                }
                if (!changed) break;
            }
            const output = self.frames.get(self.root).?;
            for ([_][]const Slot{ output.own_slots, output.impl_slots }) |slots| for (slots) |slot| for (slot.alternatives.items) |alternative_| {
                const vertex = alternative_.vertex;
                if (infinite[vertex]) return true;
                if (check_positive) |positive| {
                    if (positive and distance[vertex] != no_path and distance[vertex] > 0) return true;
                } else if (distance[vertex] != no_path) return true;
            };
            return false;
        }

        fn enqueue(self: *Reachability, declaration: DeclId, own: []const TypeId, implementation: []const TypeId) !Frame {
            const c = self.checker;
            const entry = try self.frames.getOrPut(c.gpa, declaration);
            var changed = !entry.found_existing;
            if (!entry.found_existing) {
                entry.value_ptr.* = .{ .own = &.{}, .implementation = &.{} };
                const own_count = c.recurrenceParameterCount(declaration);
                entry.value_ptr.own = try c.gpa.alloc(TypeId, own_count);
                @memset(entry.value_ptr.own, .poison);
                const over = c.headParametersOf(declaration);
                const impl_count = if (over == .none) 0 else c.ast.declTypeParams(over).len;
                entry.value_ptr.implementation = try c.gpa.alloc(TypeId, impl_count);
                @memset(entry.value_ptr.implementation, .poison);
                entry.value_ptr.own_slots = try emptySlots(c.gpa, own_count);
                entry.value_ptr.impl_slots = try emptySlots(c.gpa, impl_count);
                if (own.len == own_count) @memcpy(entry.value_ptr.own, own);
                if (implementation.len == impl_count) @memcpy(entry.value_ptr.implementation, implementation);
            } else {
                changed = join(entry.value_ptr.own, own) or changed;
                changed = join(entry.value_ptr.implementation, implementation) or changed;
            }
            if (declaration == self.root) {
                self.found = true;
            } else if (changed) try self.queueDeclaration(declaration);
            return entry.value_ptr.*;
        }

        fn join(slots: []TypeId, incoming: []const TypeId) bool {
            var changed = false;
            for (slots, 0..) |*slot, i| {
                const next = if (i < incoming.len) incoming[i] else .poison;
                if (slot.* != .poison and slot.* != next) {
                    slot.* = .poison;
                    changed = true;
                }
            }
            return changed;
        }

        fn transfer(self: *Reachability, source: []const TypeId, count: usize, declaration: DeclId, implementation: bool, scan: *Scan, substitute: bool) !void {
            for (0..count) |i| {
                const to: SlotKey = .{ .declaration = declaration, .implementation = implementation, .index = @intCast(i) };
                if (i >= source.len) {
                    try self.contributeTo(to, .{ .vertex = unbounded_source, .outer = .unknown });
                    continue;
                }
                for (try scan.height(source[i], substitute)) |term| try self.contributeTo(to, term);
            }
        }

        fn call(self: *Reachability, recorded: types_mod.NormalizedCall, scan: *Scan) !void {
            const c = self.checker;
            const target = c.recurrenceTarget(recorded) orelse return;
            const own = try self.arguments(recorded.selection.own_args, scan);
            defer c.gpa.free(own);
            if (c.dispatchedToSuppliers(recorded)) |implementation| {
                const signature = target;
                const receiver = try self.through(implementation.self_ty, scan);
                const args = try self.arguments(implementation.args, scan);
                defer c.gpa.free(args);
                if (receiver != .poison and std.mem.indexOfScalar(TypeId, args, .poison) == null) {
                    if (try c.builder.implementationChoiceWithin(self.root, DeclId.at(implementation.trait), args, receiver)) |choice| {
                        if (choice.declaredImplementation()) |selected| {
                            const row = c.builder.implementations[selected.index()];
                            if (c.supply.memberOf(row.decl, signature)) |member| {
                                const frame = try self.enqueue(member, own, choice.impl_args);
                                try self.transfer(recorded.selection.own_args, frame.own.len, member, false, scan, true);
                                try self.transfer(choice.impl_args, frame.implementation.len, member, true, scan, false);
                                return;
                            }
                            // The implementation chosen for this receiver has no
                            // body for the signature: the built-in Equatable of an
                            // integer and a field delegation are the two such
                            // implementations. The call reaches no declaration, and
                            // every other supplier answers a different receiver.
                            return;
                        }
                    }
                }
                for (c.supply.membersOf(signature)) |supplier| {
                    const member = DeclId.at(supplier);
                    const frame = try self.enqueue(member, own, &.{});
                    try self.transfer(recorded.selection.own_args, frame.own.len, member, false, scan, true);
                    try self.supplierArguments(member, implementation, frame, scan);
                }
                return;
            }
            const implementation = try self.arguments(recorded.selection.impl_args, scan);
            defer c.gpa.free(implementation);
            const written = try c.recurrenceArguments(recorded, target);
            defer c.gpa.free(written);
            const direct = try self.arguments(written, scan);
            defer c.gpa.free(direct);
            const frame = try self.enqueue(target, direct, implementation);
            try self.transfer(written, frame.own.len, target, false, scan, true);
            try self.transfer(recorded.selection.impl_args, frame.implementation.len, target, true, scan, true);
        }

        fn supplierArguments(self: *Reachability, member: DeclId, key: types_mod.CallImpl, frame: Frame, scan: *Scan) !void {
            const c = self.checker;
            const over = c.headParametersOf(member);
            if (over == .none) return;
            const entry = try self.origins.getOrPut(c.gpa, over);
            if (!entry.found_existing) {
                entry.value_ptr.* = .{ .origins = &.{} };
                const implementation = c.builder.view().implementationOf(member) orelse return;
                entry.value_ptr.* = try types_mod.ImplementationParameters.init(c.gpa, &c.builder, implementation);
            }
            const origins = entry.value_ptr;
            for (0..frame.implementation.len) |i| {
                const to: SlotKey = .{ .declaration = member, .implementation = true, .index = @intCast(i) };
                const origin = if (i < origins.origins.len) origins.origins[i] else null;
                if (origin) |position| {
                    const ty = switch (position.root) {
                        .receiver => key.self_ty,
                        .argument => |index| if (index < key.args.len) key.args[index] else .poison,
                    };
                    var value: Scan.Key = .{ .ty = ty, .substitute = true };
                    const path = origins.path(position);
                    var at: usize = 0;
                    while (at < path.len) : (at += 1) {
                        value = scan.replacement(value);
                        if (c.builder.standinOf(value.ty) != null) break;
                        value.ty = path[at].child(&c.builder, value.ty) orelse break;
                    }
                    const descent: i64 = @intCast(path.len - at);
                    for (try scan.height(value.ty, value.substitute)) |term| {
                        if (descent != 0 and term.outer != .unknown and !term.outer.same(Outer.parent(path[at]))) continue;
                        try self.contributeTo(to, .{
                            .vertex = term.vertex,
                            .outer = if (descent == 0) term.outer else .unknown,
                            .offset = std.math.sub(i64, term.offset, descent) catch return error.OutOfMemory,
                        });
                    }
                } else try self.contributeTo(to, .{ .vertex = unbounded_source, .outer = .unknown });
            }
        }

        fn arguments(self: *Reachability, source: []const TypeId, scan: *Scan) ![]TypeId {
            const mapped = try self.checker.gpa.alloc(TypeId, source.len);
            errdefer self.checker.gpa.free(mapped);
            for (source, mapped) |argument, *result| result.* = try self.through(argument, scan);
            return mapped;
        }

        fn through(self: *Reachability, ty: TypeId, scan: *Scan) !TypeId {
            if (try scan.unknown(ty, true)) return .poison;
            const own = try self.checker.builder.substitute(ty, scan.declaration.index(), scan.frame.own);
            if (scan.over == .none) return own;
            return self.checker.builder.substitute(own, scan.over.index(), scan.frame.implementation);
        }

        /// Memoized for one immutable frame snapshot. Projections and unknown
        /// replacements are detected before substitution can settle them.
        const Scan = struct {
            query: *Reachability,
            checker: *Checker,
            declaration: DeclId,
            over: DeclId,
            frame: Frame,
            memo: std.AutoHashMapUnmanaged(Key, bool) = .empty,
            heights: std.AutoHashMapUnmanaged(Key, []Term) = .empty,

            const Key = struct { ty: TypeId, substitute: bool };

            fn init(query: *Reachability, declaration: DeclId, frame: Frame) Scan {
                return .{ .query = query, .checker = query.checker, .declaration = declaration, .over = query.checker.headParametersOf(declaration), .frame = frame };
            }

            fn deinit(self: *Scan) void {
                self.memo.deinit(self.checker.gpa);
                var heights = self.heights.valueIterator();
                while (heights.next()) |terms| self.checker.gpa.free(terms.*);
                self.heights.deinit(self.checker.gpa);
            }

            /// Exact replacements belong to the original caller's scope.
            /// Unknown slots retain their local parameter vertex.
            fn replacement(self: *const Scan, key: Key) Key {
                if (!key.substitute or self.checker.builder.standinOf(key.ty) != null) return key;
                const ty = self.checker.builder.get(key.ty);
                if (ty != .parameter) return key;
                const p = ty.parameter;
                const args = if (p.owner == self.declaration.index()) self.frame.own else if (self.over != .none and p.owner == self.over.index()) self.frame.implementation else return key;
                if (p.index >= args.len or args[p.index] == .poison) return key;
                return .{ .ty = args[p.index], .substitute = false };
            }

            fn height(self: *Scan, ty: TypeId, substitute: bool) std.mem.Allocator.Error![]const Term {
                const key: Key = .{ .ty = ty, .substitute = substitute };
                if (self.heights.get(key)) |answer| return answer;
                var terms: std.AutoHashMapUnmanaged(TermKey, i64) = .empty;
                defer terms.deinit(self.checker.gpa);
                try self.measure(key, &terms);
                const answer = try self.checker.gpa.alloc(Term, terms.count());
                errdefer self.checker.gpa.free(answer);
                var entries = terms.iterator();
                var at: usize = 0;
                while (entries.next()) |entry| : (at += 1) answer[at] = .{ .vertex = entry.key_ptr.vertex, .outer = entry.key_ptr.outer, .offset = entry.value_ptr.* };
                try self.heights.put(self.checker.gpa, key, answer);
                return answer;
            }

            fn contribute(self: *Scan, terms: *std.AutoHashMapUnmanaged(TermKey, i64), vertex: u32, outer: Outer, offset: i64) !void {
                const entry = try terms.getOrPut(self.checker.gpa, .{ .vertex = vertex, .outer = outer });
                entry.value_ptr.* = if (entry.found_existing) @max(entry.value_ptr.*, offset) else offset;
            }

            fn childHeight(self: *Scan, terms: *std.AutoHashMapUnmanaged(TermKey, i64), ty: TypeId, substitute: bool, outer: Outer) std.mem.Allocator.Error!void {
                for (try self.height(ty, substitute)) |term| try self.contribute(terms, term.vertex, outer, std.math.add(i64, term.offset, 1) catch return error.OutOfMemory);
            }

            fn measure(self: *Scan, key: Key, terms: *std.AutoHashMapUnmanaged(TermKey, i64)) std.mem.Allocator.Error!void {
                const pool = &self.checker.builder;
                if (key.ty == .poison or pool.standinOf(key.ty) != null) return self.contribute(terms, unbounded_source, .unknown, 0);
                const replaced = self.replacement(key);
                if (replaced.ty != key.ty or replaced.substitute != key.substitute) {
                    for (try self.height(replaced.ty, replaced.substitute)) |term| try self.contribute(terms, term.vertex, term.outer, term.offset);
                    return;
                }
                const outer = Outer.of(pool, key.ty);
                switch (pool.get(key.ty)) {
                    .parameter => |p| {
                        const slot: ?Slot = blk: {
                            if (key.substitute) {
                                if (p.owner == self.declaration.index() and p.index < self.frame.own_slots.len) break :blk self.frame.own_slots[p.index];
                                if (self.over != .none and p.owner == self.over.index() and p.index < self.frame.impl_slots.len) break :blk self.frame.impl_slots[p.index];
                            }
                            const root = self.query.root;
                            const over = self.checker.headParametersOf(root);
                            if (p.owner == root.index() and p.index < self.query.input_own.len) break :blk self.query.input_own[p.index];
                            if (over != .none and p.owner == over.index() and p.index < self.query.input_impl.len) break :blk self.query.input_impl[p.index];
                            break :blk null;
                        };
                        if (slot) |found| {
                            for (found.alternatives.items) |alternative_| try self.contribute(terms, alternative_.vertex, alternative_.outer, 0);
                            return;
                        }
                        return self.contribute(terms, unbounded_source, .unknown, 0);
                    },
                    .borrow => |observation| return self.childHeight(terms, observation.referent, key.substitute, outer),
                    .array => |array| return self.childHeight(terms, array.element, key.substitute, outer),
                    .callable => |signature| {
                        for (pool.callableParams(signature)) |parameter| try self.childHeight(terms, parameter.ty, key.substitute, outer);
                        return self.childHeight(terms, signature.result, key.substitute, outer);
                    },
                    .closure => |closure| {
                        for (pool.closureArgs(closure)) |argument| try self.childHeight(terms, argument, key.substitute, outer);
                        for (pool.closureImplArgs(closure)) |argument| try self.childHeight(terms, argument, key.substitute, outer);
                        if (closure.self_ty != .poison) try self.childHeight(terms, closure.self_ty, key.substitute, outer);
                        if (closure.arg_count == 0 and closure.impl_arg_count == 0 and closure.self_ty == .poison) try self.contribute(terms, closed_source, outer, 0);
                        return;
                    },
                    .struct_ => if (pool.isInterpolation(key.ty)) {
                        var at: u32 = 1;
                        while (at < pool.fieldCount(key.ty)) : (at += 2) try self.childHeight(terms, pool.fieldType(key.ty, at), key.substitute, outer);
                        if (pool.fieldCount(key.ty) < 2) try self.contribute(terms, closed_source, outer, 0);
                        return;
                    },
                    .integer, .open_integer, .open_type, .boolean, .float, .poison, .unit, .never, .enum_, .newtype => {},
                }
                for (pool.appliedTo(key.ty)) |argument| try self.childHeight(terms, argument, key.substitute, outer);
                if (pool.appliedTo(key.ty).len == 0) try self.contribute(terms, closed_source, outer, 0);
            }

            fn unknown(self: *Scan, ty: TypeId, substitute: bool) std.mem.Allocator.Error!bool {
                const key: Key = .{ .ty = ty, .substitute = substitute };
                if (self.memo.get(key)) |answer| return answer;
                const answer = try self.inspect(ty, substitute);
                try self.memo.put(self.checker.gpa, key, answer);
                return answer;
            }

            fn inspect(self: *Scan, ty: TypeId, substitute: bool) std.mem.Allocator.Error!bool {
                const pool = &self.checker.builder;
                if (ty == .poison or pool.standinOf(ty) != null) return true;
                switch (pool.get(ty)) {
                    .parameter => |parameter| {
                        if (!substitute) return false;
                        const args = if (parameter.owner == self.declaration.index()) self.frame.own else if (self.over != .none and parameter.owner == self.over.index()) self.frame.implementation else return false;
                        if (parameter.index >= args.len) return true;
                        // Replacement types already belong to the original
                        // caller's scope; inspect them without applying this
                        // declaration's frame a second time.
                        return self.unknown(args[parameter.index], false);
                    },
                    .borrow => |borrow| return self.unknown(borrow.referent, substitute),
                    .array => |array| return self.unknown(array.element, substitute),
                    .callable => |signature| {
                        for (pool.callableParams(signature)) |parameter| {
                            if (try self.unknown(parameter.ty, substitute)) return true;
                        }
                        return self.unknown(signature.result, substitute);
                    },
                    .closure => |closure| {
                        for (pool.closureArgs(closure)) |argument| {
                            if (try self.unknown(argument, substitute)) return true;
                        }
                        for (pool.closureImplArgs(closure)) |argument| {
                            if (try self.unknown(argument, substitute)) return true;
                        }
                        if (closure.self_ty != .poison and try self.unknown(closure.self_ty, substitute)) return true;
                    },
                    .struct_ => if (pool.isInterpolation(ty)) {
                        var at: u32 = 1;
                        while (at < pool.fieldCount(ty)) : (at += 2) if (try self.unknown(pool.fieldType(ty, at), substitute)) return true;
                    },
                    else => {},
                }
                for (pool.appliedTo(ty)) |argument| {
                    if (try self.unknown(argument, substitute)) return true;
                }
                return false;
            }
        };
    };

    fn reaches(
        self: *Checker,
        first: types_mod.NormalizedCall,
        root: DeclId,
        starts: []const u32,
        calls: []const ExprId,
    ) std.mem.Allocator.Error!bool {
        var reachability: Reachability = .{ .checker = self, .root = root, .starts = starts, .calls = calls };
        defer reachability.deinit();
        return reachability.run(first);
    }

    /// One parameter settled two ways, which is what stops a call meaning two
    /// things at once.
    const Clash = struct { index: u32, was: TypeId, got: TypeId };

    /// Whether a type argument is one of the caller's type parameters and
    /// nothing more, which the measure holds to be no larger than what the
    /// caller was given.
    ///
    /// A projection is interned as a parameter and is not one: `S.Next` puts
    /// `S` beneath a type-level operation, so it is one structural step larger
    /// than `S` whatever an implementation settles it to.
    fn namesParameterExactly(self: *const Checker, ty: TypeId) bool {
        if (self.builder.standinOf(ty) != null) return false;
        return self.builder.get(ty) == .parameter;
    }

    /// What a walk looking for `d`'s type parameters does at a projection,
    /// which is the one place its two askers want different answers.
    ///
    /// Inference settles a type parameter by matching a declared type against
    /// what was passed, and nothing can be matched into a projection: `T.Item`
    /// handed a `UInt8` says nothing about `T`, so a parameter standing
    /// beneath one settles nothing and the argument is checked against the
    /// substituted parameter instead. The measure asks the other question --
    /// whether a parameter stands beneath a type-level operation at all -- and
    /// a projection is one such operation.
    const AtAProjection = enum { stops, walks_on };

    /// Whether an expression determines its own type, or waits for one.
    ///
    /// §4 divides expressions this way already -- types flow "outward from an
    /// expression that determines its own type" -- and this is where the
    /// sentence gets a referent. A literal waits; a name, a call, a field or a
    /// conversion answers for itself.
    ///
    /// Structural rather than a check run twice. Asking would mean checking the
    /// expression to see what it did, and a check that turned out to be
    /// premature cannot be taken back: the sink appends and has no rewind, so a
    /// diagnostic reported while probing is a diagnostic the program keeps.
    ///
    /// Wrong in either direction costs only a diagnostic. Answering "waits"
    /// for something that would have determined its own type leaves a type
    /// parameter for a later argument to settle, and where none does the
    /// second pass settles it from this one anyway. Answering "determines"
    /// for something that waits lets it settle the parameter from its own
    /// type, which an argument checked against it could have settled too.
    /// Neither answer produces a wrong type, which is what makes a structural
    /// approximation safe here.
    fn determinesItsOwnType(self: *const Checker, id: ExprId) bool {
        return switch (self.ast.exprTag(id)) {
            // Nothing about these says what they are. A literal takes what
            // flows in or its default; the shorthands have no name to read a
            // type off at all.
            .int_literal,
            .float_literal,
            .array_literal,
            => false,

            // A named literal says its type through the canonical written
            // type head. The contextual form still waits for one to flow in.
            .struct_literal => self.ast.structLiteralHead(id) != null,

            // A leading-dot variant names no enum, bare or applied to its
            // payload, so it waits for the enum other arguments settle. A
            // qualified variant names its enum and answers for itself, unless
            // the enum is generic: `Option.None` names `Option` but not what
            // it holds, so it waits as well.
            .variant_ref => self.ast.unaryOperand(id) != ExprId.none and !self.namesAGenericEnum(id),
            // `Option.None` written as a selection from the enum's name is the
            // same qualified variant, and waits for the same reason.
            .field => !self.namesAGenericEnum(id),
            .call => blk: {
                const callee = self.ast.withoutGroups(self.ast.call(id).callee);
                break :blk !(self.ast.exprTag(callee) == .variant_ref and self.ast.unaryOperand(callee) == ExprId.none);
            },

            // A lambda says its type only through parameter types it writes;
            // one that leaves any out takes them from the type that flows in.
            .lambda => for (self.ast.lambda(id).params) |param| {
                if (!param.written.wasWritten()) break false;
            } else true,

            // Written around another expression, and say what it says.
            .grouped, .negate, .marked, .copy_ => self.determinesItsOwnType(self.ast.unaryOperand(id)),

            // Arithmetic over two operands is whatever the operands are, and
            // one of them naming a type is enough: `n + 1` is `n`'s type.
            .add, .sub, .mul, .div, .rem => blk: {
                const p2 = self.ast.binary(id);
                break :blk self.determinesItsOwnType(p2.lhs) or self.determinesItsOwnType(p2.rhs);
            },

            // A tuple's components are independent, so it says what it is
            // only where every component does. One that leaves a component
            // open -- `(3, true)` -- takes that component's type from the type
            // that flows in, as a lambda takes a parameter type it left out;
            // answering for the tuple from the one component that spoke would
            // settle the open one to its default instead.
            .tuple_literal => for (self.ast.call(id).args) |component| {
                if (!self.determinesItsOwnType(component)) break false;
            } else true,

            // Everything else answers for itself -- a name, a call, a field, an
            // index, a range, a conversion, a comparison, text and truth. A
            // range of literals answers `Range` over an open integer type,
            // which the rest of the call or a callback body settles.
            else => true,
        };
    }

    /// Whether a variant reference names a variant of a generic enum, whose
    /// instantiation only an expectation can say.
    ///
    /// A selection is a variant reference when it settles on its base's own
    /// binding, as `Option.None` settles on `Option`; any other selection
    /// answers for itself.
    fn namesAGenericEnum(self: *const Checker, id: ExprId) bool {
        const target = self.res.targetOf(id);
        if (target == BindingId.none) return false;
        if (self.ast.exprTag(id) == .field and target != self.res.targetOf(self.ast.unaryOperand(id))) return false;
        return self.ast.declTypeParams(self.res.declaredBy(target)).len != 0;
    }

    /// Whether a type contains a parameter owned by the selected declaration.
    /// The projection policy controls traversal through associated selections.
    fn mentionsParameter(
        self: *const Checker,
        ty: TypeId,
        d: node.DeclId,
        at: AtAProjection,
    ) bool {
        return self.mentionsParameterAt(ty, d, at, null);
    }

    fn mentionsParameterAt(
        self: *const Checker,
        ty: TypeId,
        d: node.DeclId,
        at: AtAProjection,
        index: ?u32,
    ) bool {
        var search: ParameterSearch = .{ .checker = self, .owner = d, .projection = at, .index = index };
        // The uncached path performs no allocations.
        return search.visit(ty) catch unreachable;
    }

    /// Inference and growth use one identity walk with explicit projection
    /// policy. Growth memoizes each visited type within the fixed owner query.
    const ParameterSearch = struct {
        checker: *const Checker,
        owner: DeclId,
        other: DeclId = .none,
        projection: AtAProjection,
        index: ?u32 = null,
        memoized: bool = false,
        memo: std.AutoHashMapUnmanaged(TypeId, bool) = .empty,

        fn visit(self: *ParameterSearch, ty: TypeId) std.mem.Allocator.Error!bool {
            if (self.memoized) if (self.memo.get(ty)) |answer| return answer;
            const answer = try self.inspect(ty);
            if (self.memoized) try self.memo.put(self.checker.gpa, ty, answer);
            return answer;
        }

        fn inspect(self: *ParameterSearch, ty: TypeId) std.mem.Allocator.Error!bool {
            const pool = &self.checker.builder;
            if (pool.standinOf(ty)) |standin| {
                if (self.projection == .stops) return false;
                if (try self.visit(standin.held)) return true;
                for (pool.standinArgsOf(standin)) |argument| if (try self.visit(argument)) return true;
                return false;
            }
            switch (pool.get(ty)) {
                .parameter => |p| return (p.owner == self.owner.index() or (self.other != .none and p.owner == self.other.index())) and (self.index == null or p.index == self.index.?),
                .array => |array| return self.visit(array.element),
                .borrow => |observation| return self.visit(observation.referent),
                .callable => |signature| {
                    for (pool.callableParams(signature)) |parameter| if (try self.visit(parameter.ty)) return true;
                    return self.visit(signature.result);
                },
                .closure => |closure| {
                    for (pool.closureArgs(closure)) |argument| if (try self.visit(argument)) return true;
                    for (pool.closureImplArgs(closure)) |argument| if (try self.visit(argument)) return true;
                    if (closure.self_ty != .poison and try self.visit(closure.self_ty)) return true;
                },
                .struct_ => if (pool.isInterpolation(ty)) {
                    var at: u32 = 1;
                    while (at < pool.fieldCount(ty)) : (at += 2) if (try self.visit(pool.fieldType(ty, at))) return true;
                },
                .integer, .open_integer, .open_type, .boolean, .float, .poison, .unit, .never, .enum_, .newtype => {},
            }
            for (pool.appliedTo(ty)) |argument| if (try self.visit(argument)) return true;
            return false;
        }
    };

    /// Settles a function family's arguments from corresponding parameter and
    /// result type positions, leaving exact signature identity to the
    /// substituted comparison after bounds have been checked.
    fn settleSignatureTypes(
        self: *Checker,
        declared: TypeId,
        actual: TypeId,
        d: node.DeclId,
        found: []TypeId,
        clash: *?Clash,
    ) std.mem.Allocator.Error!bool {
        return self.settleBy(declared, actual, d, found, clash, .signature_types);
    }

    /// Settles what a callee's parameters must be, by walking what it declared
    /// alongside what it was handed.
    ///
    /// A parameter is settled wherever it stands, not only where it is the
    /// whole of a written type: `o: Option[T]` handed an `Option[Bool]`
    /// says exactly what `x: T` handed a `Bool` says. Without this, every
    /// function over a generic type is uncallable -- which is every method
    /// `Option` and `Result` have.
    ///
    /// Where the two do not correspond at all this settles nothing and says
    /// nothing: the argument is checked against the substituted parameter
    /// afterwards, and that is the check whose diagnostic reads properly.
    fn settle(
        self: *Checker,
        declared: TypeId,
        actual: TypeId,
        d: node.DeclId,
        found: []TypeId,
        clash: *?Clash,
    ) std.mem.Allocator.Error!bool {
        return self.settleBy(declared, actual, d, found, clash, .matching);
    }

    const Settlement = enum { matching, signature_types };

    fn settleBy(
        self: *Checker,
        declared: TypeId,
        actual: TypeId,
        d: node.DeclId,
        found: []TypeId,
        clash: *?Clash,
        settlement: Settlement,
    ) std.mem.Allocator.Error!bool {
        return self.settleByInContext(declared, actual, d, found, clash, settlement, null);
    }

    fn settleByInContext(
        self: *Checker,
        declared: TypeId,
        actual: TypeId,
        d: node.DeclId,
        found: []TypeId,
        clash: *?Clash,
        settlement: Settlement,
        open_context: ?[]const Settling,
    ) std.mem.Allocator.Error!bool {
        switch (self.builder.get(declared)) {
            .parameter => |p| {
                if (open_context) |slots| if (self.hasOpenParameter(actual, slots)) return true;
                if (p.owner != d.index() or p.index >= found.len or actual == .never) return true;
                if (found[p.index] == .poison) {
                    found[p.index] = actual;
                    return true;
                }
                if (found[p.index] == actual) return true;
                // Two open integer types meeting at one parameter become one.
                if ((try self.builder.mentionsOpen(found[p.index]) or try self.builder.mentionsOpen(actual)) and
                    try self.meet(found[p.index], actual, null)) return true;
                clash.* = .{ .index = p.index, .was = found[p.index], .got = actual };
                return false;
            },
            // An array is the one constructed type that is not an
            // instantiation, so the walk below cannot reach inside it. The
            // length is written down and settles nothing, so only the element
            // is matched -- and two arrays of different lengths are different
            // types, which is a mismatch to report rather than a parameter to
            // settle.
            .borrow => |wanted| {
                const got = switch (self.builder.get(actual)) {
                    .borrow => |b| b,
                    else => return true,
                };
                return self.settlePartInContext(wanted.referent, got.referent, d, found, clash, settlement, open_context);
            },
            .array => |w| {
                const g = switch (self.builder.get(actual)) {
                    .array => |x| x,
                    else => return true,
                };
                if (w.count != g.count) return true;
                return self.settlePartInContext(w.element, g.element, d, found, clash, settlement, open_context);
            },
            .callable => |want| {
                const got = switch (self.builder.get(actual)) {
                    .callable => |signature| signature,
                    else => return true,
                };
                if ((settlement == .matching and !types_mod.sameContracts(want.contracts, got.contracts))) return true;
                const wanted = self.builder.callableParams(want);
                const given = self.builder.callableParams(got);
                if (wanted.len == given.len) {
                    for (wanted, given) |w, g| {
                        if (settlement == .matching and
                            (w.convention != g.convention or
                                w.stable_address != g.stable_address or
                                !w.default.eql(g.default)))
                        {
                            return true;
                        }
                        if (!try self.settlePartInContext(w.ty, g.ty, d, found, clash, settlement, open_context)) return false;
                    }
                } else if (settlement == .matching) {
                    return true;
                }
                return self.settlePartInContext(want.result, got.result, d, found, clash, settlement, open_context);
            },
            else => {},
        }

        const want = self.builder.instanceOf(declared) orelse return true;
        const got = self.builder.instanceOf(actual) orelse return true;
        if (want.decl != got.decl) return true;

        const wanted = self.builder.argsOf(want);
        const given = self.builder.argsOf(got);
        if (wanted.len != given.len) return true;

        for (wanted, given) |w, g| {
            if (!try self.settlePartInContext(w, g, d, found, clash, settlement, open_context)) return false;
        }
        return true;
    }

    /// Settles a part of a written type, such as `Never` in
    /// `Result[UInt8, Never]`. Only an expression of type `Never` produces no
    /// value and so settles nothing; `Never` written inside another type is a
    /// type argument, and it settles the parameter it stands for like any
    /// other type.
    fn settlePartInContext(
        self: *Checker,
        declared: TypeId,
        actual: TypeId,
        d: node.DeclId,
        found: []TypeId,
        clash: *?Clash,
        settlement: Settlement,
        open_context: ?[]const Settling,
    ) std.mem.Allocator.Error!bool {
        if (actual == .never) switch (self.builder.get(declared)) {
            .parameter => |p| {
                if (open_context) |slots| if (self.hasOpenParameter(actual, slots)) return true;
                if (p.owner != d.index() or p.index >= found.len) return true;
                if (found[p.index] == .poison or found[p.index] == .never) {
                    found[p.index] = .never;
                    return true;
                }
                clash.* = .{ .index = p.index, .was = found[p.index], .got = actual };
                return false;
            },
            else => {},
        };
        return self.settleByInContext(declared, actual, d, found, clash, settlement, open_context);
    }

    /// The type arguments a call recovers from the arguments it was given.
    ///
    /// Matching structural positions in the declared and checked argument
    /// types settle parameters. Inference is local to those types and the
    /// expected result; it does not inspect the callee's body.
    ///
    /// Two arguments settling one parameter differently is reported at the
    /// second, which is where the disagreement becomes visible.
    /// `args` rather than what the call node holds. A postfix call's receiver
    /// is an argument the tree does not spell, so the written list is short by
    /// one and shifted by one -- and `walked` is indexed against the list the
    /// caller has, so writing it against the other one marks the wrong
    /// argument checked. The caller was handed the right list and every other
    /// rule in it already reads that one.
    /// One list of type parameters a call has to settle, and what it settled
    /// them to.
    ///
    /// A call settles at most two: the callee's own, and the ones the
    /// implementation the callee is a member of declares. A member of an
    /// implementation generic over its head is written in the second exactly as
    /// it is written in the first, so both are read off the arguments by one
    /// walk rather than by a walk each -- two walks would check an argument
    /// mentioning both a second time, and report whatever is wrong inside it
    /// twice.
    const Settling = struct {
        owner: node.DeclId,
        generics: []const node.TypeParam,
        found: []TypeId,
        parameters: []const TypeId = &.{},
    };

    /// What a call settled, per list.
    ///
    /// `head` is empty where the callee is a member of no implementation, or of
    /// one declaring no parameters -- which is the degenerate case of the same
    /// walk rather than a path beside it.
    const Bindings = struct {
        own: []const TypeId = &.{},
        head: []const TypeId = &.{},
    };

    fn inferCall(
        self: *Checker,
        id: ExprId,
        d: node.DeclId,
        over: node.DeclId,
        args: []const ExprId,
        walked: []bool,
        expected: ?Expected,
        written: []const TypeId,
    ) std.mem.Allocator.Error!?Bindings {
        const params = self.ast.declParams(d);

        var slots: [2]Settling = undefined;
        var count: usize = 0;
        for ([_]node.DeclId{ d, over }) |owner| {
            if (owner == node.DeclId.none) continue;
            const generics = self.ast.declTypeParams(owner);
            if (generics.len == 0) continue;
            const found = try self.sink.arena.alloc(TypeId, generics.len);
            @memset(found, .poison);
            // Type arguments the call names settle its own parameters before
            // anything else is read.
            if (owner == d and written.len == generics.len) @memcpy(found, written);
            slots[count] = .{ .owner = owner, .generics = generics, .found = found, .parameters = self.param_types[owner.index()] };
            count += 1;
        }
        const settling = slots[0..count];
        if (count == 0) return .{};

        // A path through an alias names the implementation's head at the
        // alias's arguments, which settles them as the receiver would. A
        // generic alias settles the positions it writes closed, and the
        // others wait for the call, as the bare declaration's would.
        var through: ?AliasHeading = null;
        if (over != node.DeclId.none) if (self.calledThroughAlias(id)) |head| if (head.held != .poison) {
            if (self.builder.view().implementationIdOf(d)) |implementation| {
                if (try self.builder.implementationArgumentsWithin(self.generic, implementation, &.{}, head.held)) |applied| {
                    const heading: AliasHeading = .{ .alias = head.alias, .written = applied, .found = try self.openAliasArguments(head.alias) };
                    for (settling) |s| if (s.owner == over) self.seedAliasHeading(heading, s.found);
                    if (heading.found.len != 0) through = heading;
                }
            }
        };

        // The declared types of arguments refused where they are written. A
        // type parameter one of them mentions is left open by that refusal,
        // which was reported, so the call does not report it again; a type
        // parameter none of them mentions is still reported. Sized by the
        // call's arguments.
        var refused_declared: std.ArrayList(TypeId) = .empty;
        defer refused_declared.deinit(self.gpa);

        // Known arguments settle parameters first, then the expected result
        // supplies remaining context. Only unconstrained literals default.
        // Arguments whose parameter is settled wait for the ordinary argument
        // check below, which propagates that type into the expression.
        for ([_]bool{ true, false }, 0..) |speaking, pass| {
            if (pass == 1) try self.settleCallResult(d, args, settling, expected, self.successExpectationAt(id), self.failureExpectationAt(id), self.methodExpectationAt(id));
            for (args, 0..) |a, j| {
                if (j >= params.len) break;
                // An omitted parameter determines nothing. Its default is a
                // constant of the parameter's declared type, and a type
                // parameter has no constants -- so a parameter reached only this
                // way is one nothing settles, which the report below is already
                // about.
                if (a == ExprId.none) continue;
                // Self or trait-argument inference may already have checked
                // this expression. Its recorded type still settles method
                // parameters; only evaluation is skipped.
                if (pass != 0 and walked[j]) continue;
                const declared = try paramType(self, d, j);
                const value = if (self.ast.exprTag(a) == .marked) self.ast.unaryOperand(a) else a;
                if (!walked[j] and self.needsCallableContext(value) and self.callbackParameter(declared) != null) continue;

                // An argument whose parameter says nothing about any of them
                // settles nothing, and checking it here would report whatever is
                // wrong with it a second time.
                if (!self.mentionsSettling(declared, settling)) continue;

                if (!walked[j] and self.determinesItsOwnType(value) != speaking) continue;

                // A parameter something else settled is one this argument has
                // nothing to add to, and checking it here would ask it for a
                // type with nothing flowing in -- the very thing the walk below
                // is about to do properly.
                if (!speaking and !self.hasOpenParameter(declared, settling)) continue;

                const observed = if (walked[j]) self.builder.exprType(value) else try self.check(value, null);
                const got = if (over != .none and readsSelf(self.ast, params[j])) try self.inherentReceiver(d, observed) else observed;
                walked[j] = true;
                if (got == .poison) {
                    try refused_declared.append(self.gpa, declared);
                    continue;
                }

                for (settling) |s| {
                    var clash: ?Clash = null;
                    if (try self.settle(declared, got, s.owner, s.found, &clash)) continue;

                    const at = clash.?;
                    const got_name = try self.typeName(at.got);
                    const spelled = .{
                        self.ast.tokenText(s.generics[at.index].name),
                        (try self.typeName(at.was)),
                        article.before(got_name),
                        got_name,
                    };
                    _ = if (s.owner == d and written.len > 0)
                        self.report(.t_mismatch, a, "the call names `{s}` as `{s}` in its brackets, and this is {s} `{s}`", spelled, "one type parameter, two types")
                    else
                        self.report(.t_mismatch, a, "`{s}` was already settled as `{s}` here, and this is {s} `{s}`", spelled, "one type parameter, two types");
                    return null;
                }

                // A checked callable's bound relates its signature to the
                // callee's other type parameters, beyond the callable type itself.
                const bounds = self.builder.callableBoundsOn(declared);
                if (bounds.len > 0) {
                    const supplied = try self.callbackValueSignature(got);
                    for (bounds) |interned| {
                        // A bound that is a type parameter waits for the
                        // call's context, below.
                        if (self.builder.get(interned) == .parameter) continue;
                        const bound = try self.boundAtCall(d, declared, interned);
                        if (!try self.settleCallbackResult(bound, supplied, settling, value)) return null;
                    }
                }
            }
        }

        // A callback whose bound is a type parameter settles it from its own
        // signature only where the call's context left it open: the closure
        // type a caller expects decides what the callback is called as.
        for (args, 0..) |a, j| {
            if (j >= params.len or a == .none or !walked[j]) continue;
            const value = if (self.ast.exprTag(a) == .marked) self.ast.unaryOperand(a) else a;
            for (self.builder.callableBoundsOn(try paramType(self, d, j))) |bound| {
                if (self.builder.get(bound) != .parameter) continue;
                if (self.builder.get(try self.callableContext(bound, settling)) == .callable) continue;
                const supplied = try self.callbackCallableSignature(self.builder.exprType(value)) orelse continue;
                if (!try self.settleCallbackResult(bound, supplied, settling, value)) return null;
            }
        }

        var callbacks = try CallbackWork.init(self.gpa, args.len, settling);
        defer callbacks.deinit(self.gpa);
        for (args, 0..) |a, j| {
            if (j >= params.len) break;
            if (a == .none or walked[j]) continue;
            const value = if (self.ast.exprTag(a) == .marked) self.ast.unaryOperand(a) else a;
            if (!self.needsCallableContext(value)) continue;
            const declared = try paramType(self, d, j);
            const callback = self.callbackParameter(declared) orelse continue;
            // A callback whose type names none of the parameters being settled
            // waits for nothing; the ordinary argument check converts it.
            if (!self.mentionsSettling(declared, settling)) continue;
            callbacks.bounds[j] = try self.boundAtCall(d, declared, callback.signature);
            callbacks.structural[j] = callback.structural;
            var dependencies: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
            defer dependencies.deinit(self.gpa);
            var visited: std.AutoHashMapUnmanaged(TypeId, void) = .empty;
            defer visited.deinit(self.gpa);
            if (callbacks.bounds[j] != .poison) switch (self.builder.get(callbacks.bounds[j])) {
                .callable => |signature| {
                    for (self.builder.callableParams(signature)) |parameter| {
                        try self.openCallbackParameters(parameter.ty, settling, &dependencies, &visited);
                    }
                    if (self.contextualConstructor(value)) {
                        const contextual_result = try self.callableContext(signature.result, settling);
                        if (self.declaringType(contextual_result) == null) {
                            try self.openCallbackParameters(signature.result, settling, &dependencies, &visited);
                        } else if (self.constructorSelection(self.ast.withoutGroups(value), contextual_result, false)) |selection| {
                            const callable_parameters = self.builder.callableParams(signature);
                            if (selection.result != .poison and
                                callable_parameters.len == 1 and
                                self.builder.variantFieldCount(selection.result, selection.ordinal) == 1)
                            {
                                const generics = self.ast.declTypeParams(selection.declaration);
                                const inferred = try self.gpa.alloc(TypeId, generics.len);
                                defer self.gpa.free(inferred);
                                @memset(inferred, .poison);
                                var clash: ?Clash = null;
                                const template = self.type_of_decl.get(selection.declaration);
                                const payload = self.builder.variantFieldType(template, selection.ordinal, 0);
                                _ = try self.settleSignatureTypes(payload, callable_parameters[0].ty, selection.declaration, inferred, &clash);
                                if (self.builder.instanceOf(selection.result)) |instance| {
                                    for (inferred, self.builder.argsOf(instance)) |found, argument| {
                                        if (found == .poison) try self.openCallbackParameters(argument, settling, &dependencies, &visited);
                                    }
                                }
                            }
                        }
                    }
                },
                else => {},
            };
            var keys = dependencies.keyIterator();
            while (keys.next()) |key| try callbacks.waitFor(self.gpa, key.*, j);
            if (callbacks.remaining[j] == 0) callbacks.ready.appendAssumeCapacity(j);
        }

        var delayed_refused = false;
        var next_callback: usize = 0;
        while (next_callback < callbacks.ready.items.len) : (next_callback += 1) {
            const j = callbacks.ready.items[next_callback];
            defer callbacks.wake(settling);
            const a = args[j];
            const value = if (self.ast.exprTag(a) == .marked) self.ast.unaryOperand(a) else a;
            const declared = try paramType(self, d, j);
            var bound = callbacks.bounds[j];
            // A callable bound keeps the argument's own type; a structural
            // callable parameter converts the argument to its signature.
            const callable_context = !callbacks.structural[j];
            // A bound that is a type parameter is the callable type it settles
            // to. Settled, it supplies context as a written bound does.
            // Unsettled, the callback's own signature settles it, so the
            // callback is checked without context and must write its types.
            var from_callback = false;
            if (self.builder.get(bound) == .parameter) {
                const settled = try self.callableContext(bound, settling);
                if (self.builder.get(settled) == .callable) {
                    bound = try self.builder.carriedByCallee(settled);
                } else {
                    from_callback = true;
                }
            }
            var got: TypeId = .poison;
            if (from_callback) {
                // A function named with nothing expected has its own
                // signature, with the parameters it leaves open for the
                // closure's uses to settle, which is what a lambda's written
                // parameter types are to a lambda.
                got = try self.check(value, null);
                if (got != .poison and !try self.settleCallbackResult(bound, try self.callbackValueSignature(got), settling, value)) {
                    walked[j] = true;
                    delayed_refused = true;
                    continue;
                }
            } else if (bound == .poison or !self.callableInputsKnown(bound, settling)) {
                self.reportCallbackInputs(value);
                _ = try self.check(value, .{ .ty = .poison, .at = self.locOf(value), .reason = .parameter, .callable_context = true });
                walked[j] = true;
                delayed_refused = true;
                continue;
            }

            if (!from_callback) {
                const infer_result = self.hasOpenParameter(bound, settling);
                var signature = try self.callableContext(bound, settling);
                const at_parameter: Loc = .{ .file = self.ast.fileOf(params[j].name), .span = self.ast.tokenSpan(params[j].name) };
                if (infer_result and !self.isLambda(value)) {
                    const supplied = try self.namedCallbackSignature(value, signature, settling) orelse {
                        _ = self.report(.t_infer, value, "the callback's inputs do not select its result type", .{}, "supply a callable with a determined result");
                        _ = try self.check(value, .{ .ty = .poison, .at = self.locOf(value), .reason = .parameter });
                        walked[j] = true;
                        delayed_refused = true;
                        continue;
                    };
                    if (supplied == .poison) {
                        _ = self.record(value, .poison);
                        walked[j] = true;
                        delayed_refused = true;
                        continue;
                    }
                    if (!try self.settleCallbackResult(bound, supplied, settling, value)) {
                        walked[j] = true;
                        delayed_refused = true;
                        continue;
                    }
                    signature = try self.callableContext(bound, settling);
                    got = try self.check(value, .{ .ty = signature, .at = at_parameter, .reason = .parameter, .callable_context = callable_context, .callee = d, .receiver = try self.receiverArgument(d, args, params, j, bound), .passed_to = d });
                } else {
                    got = try self.check(value, .{
                        .ty = signature,
                        .at = at_parameter,
                        .reason = .parameter,
                        .callable_context = callable_context,
                        .callee = d,
                        .receiver = try self.receiverArgument(d, args, params, j, bound),
                        .passed_to = d,
                        .infer_lambda_result = infer_result,
                        .inference = if (infer_result) settling else null,
                    });
                    if (infer_result and got != .poison) {
                        const supplied = try self.callbackValueSignature(got);
                        if (!try self.settleCallbackResult(bound, supplied, settling, value)) {
                            walked[j] = true;
                            delayed_refused = true;
                            continue;
                        }
                    }
                }
            }
            walked[j] = true;
            if (got == .poison) {
                delayed_refused = true;
                continue;
            }

            for (settling) |s| {
                var clash: ?Clash = null;
                if (try self.settle(declared, got, s.owner, s.found, &clash)) continue;
                const at = clash.?;
                _ = self.report(
                    .t_mismatch,
                    value,
                    "`{s}` was already settled as `{s}` here, and this is {s} `{s}`",
                    .{
                        self.ast.tokenText(s.generics[at.index].name),
                        (try self.typeName(at.was)),
                        article.before(try self.typeName(at.got)),
                        (try self.typeName(at.got)),
                    },
                    "one type parameter, two types",
                );
                delayed_refused = true;
            }
        }
        for (callbacks.remaining, 0..) |remaining, j| {
            if (remaining == 0 or walked[j]) continue;
            const a = args[j];
            const value = if (self.ast.exprTag(a) == .marked) self.ast.unaryOperand(a) else a;
            self.reportCallbackInputs(value);
            _ = try self.check(value, .{ .ty = .poison, .at = self.locOf(value), .reason = .parameter, .callable_context = true });
            walked[j] = true;
            delayed_refused = true;
        }
        if (delayed_refused) return null;

        if (through) |heading| for (settling) |s| if (s.owner == over) try self.closeAliasHeading(heading, s.found);

        // A parameter of the implementation that nothing determined takes the
        // default of the type parameter it stands for in the implementation's
        // head.
        // An expected type that was refused has been reported, and says nothing
        // more about what the call leaves open.
        // Poison is only recorded after it was reported, which is what lets
        // this skip both the default and the unresolved-parameter report.
        const context_refused = if (expected) |want| want.ty == .poison else false;
        if (!context_refused) for (settling) |s| {
            if (s.owner != over) continue;
            for (s.found, 0..) |*f, k| {
                if (f.* == .poison) f.* = try self.headDefaultOf(id, d, @intCast(k)) orelse continue;
            }
        };

        // A type parameter of the callee that nothing determined takes the
        // default it writes, and an omitted argument is that default's
        // constant, so a call that settled the parameter as another type
        // cannot leave the argument out.
        if (!context_refused) for (settling) |s| {
            if (s.owner != d) continue;
            const taken = try self.sink.arena.alloc(bool, s.generics.len);
            @memset(taken, false);
            for (s.found, s.generics, 0..) |*f, g, k| {
                if (!g.default.wasWritten()) continue;
                if (f.* == .poison) {
                    f.* = try self.takeDefault(id, d, k);
                    taken[k] = true;
                    continue;
                }
                // A literal nothing else typed meets the default as it meets
                // the default of a written type: it takes it.
                const open = self.openVariable(try self.builder.resolveOpen(f.*, &self.open_types)) orelse continue;
                if (!self.open_types.isInteger(open)) continue;
                const default = try self.defaultAt(d, k);
                if (default != .poison and try self.meet(f.*, default, self.literalSite(id))) {
                    f.* = try self.builder.resolveOpen(f.*, &self.open_types);
                    try self.recordDefaultTaken(id, d, k, default);
                    taken[k] = true;
                }
            }
            // A default meets the bounds of its parameter, as an argument
            // would; the cause is the default, so the report says so.
            for (s.found, s.generics, taken) |f, g, was_taken| {
                if (!was_taken or f == .poison) continue;
                const bounds = self.ast.boundsOf(g);
                if (bounds.len == 0) continue;
                const own: OwnBound = .{ .source = .{ .scope = .{ .module = self.program.moduleOf(d), .owner = d } }, .decl = d, .settled = s.found };
                if (!try self.undischarged(self.ast.tokenText(g.name), bounds, own, f, g.name, self.ast.tokenSpan(g.name), .ask, null)) continue;
                _ = self.report(
                    .t_bound,
                    id,
                    "`{s}` is left to its default `{s}`, which does not meet the bounds of `{s}`",
                    .{ self.ast.tokenText(g.name), try self.typeName(f), self.ast.tokenText(g.name) },
                    "pass an argument that settles the type, or give the type parameter a default that meets its bounds",
                );
                return null;
            }
            for (args, 0..) |a, j| {
                if (j >= params.len) break;
                if (a != ExprId.none or !hasDefault(params[j])) continue;
                const declared = try paramType(self, d, j);
                const parameter = switch (self.builder.get(declared)) {
                    .parameter => |parameter| parameter,
                    else => continue,
                };
                if (parameter.owner != d.index() or !s.generics[parameter.index].default.wasWritten()) continue;
                const found = s.found[parameter.index];
                const default = try self.defaultAt(d, parameter.index);
                if (found == .poison or default == .poison or found == default) continue;
                const settled_as = if (self.builder.get(found) == .parameter)
                    try std.fmt.allocPrint(self.sink.arena, "the caller's `{s}`", .{try self.typeName(found)})
                else
                    try std.fmt.allocPrint(self.sink.arena, "`{s}`", .{try self.typeName(found)});
                _ = self.report(
                    .t_mismatch,
                    id,
                    "in this call to `{s}`, `{s}` is {s}, and the default of `{s}` has the type `{s}`",
                    .{ self.ast.tokenText(self.ast.declName(d)), self.ast.tokenText(s.generics[parameter.index].name), settled_as, self.ast.tokenText(params[j].name), try self.typeName(default) },
                    "write the argument, or let nothing else settle the type",
                );
                return null;
            }
        };

        var left_open = false;
        for (settling) |s| {
            for (s.found, s.generics, 0..) |f, g, k| {
                if (f != .poison) continue;
                if (context_refused) return null;
                left_open = true;
                const refused = for (refused_declared.items) |declared| {
                    if (self.mentionsParameterAt(declared, s.owner, .stops, @intCast(k))) break true;
                } else false;
                if (refused) continue;
                const through_alias = if (through) |h| if (s.owner == over) self.aliasParameterAt(h, k) else null else null;
                _ = self.report(
                    .t_infer,
                    id,
                    "nothing here says what `{s}` is",
                    .{self.ast.tokenText(through_alias orelse g.name)},
                    "no argument determines it, and nothing expects a type of it",
                );
                return null;
            }
        }
        if (left_open) return null;

        // Every argument and callback has had its chance to settle an open
        // integer inside a type argument; one still open takes the default,
        // since the call's result type needs a concrete instantiation.
        for (settling) |s| for (s.found) |*f| {
            f.* = try self.forceInteger(f.*, self.literalSite(id));
        };
        if (through) |heading| for (settling) |s| if (s.owner == over) {
            const callee = self.ast.withoutGroups(self.ast.call(id).callee);
            const head = self.ast.exprMain(self.ast.unaryOperand(callee));
            if (!try self.settleAliasHeading(id, head, heading, s.found)) return null;
        };
        // A callback's signature was minted while those integers were open,
        // and implementation selection reads it: give it the settled types.
        for (args) |arg| switch (self.builder.get(self.builder.exprType(arg))) {
            .closure => |closure| {
                const descriptors = @constCast(self.builder.closure_descriptors);
                const descriptor = &descriptors[closure.closure.index()];
                descriptor.signature = try self.builder.resolveOpen(descriptor.signature, &self.open_types);
            },
            else => {},
        };

        var out: Bindings = .{};
        for (settling) |s| {
            if (s.owner == d) out.own = s.found else out.head = s.found;
        }
        return out;
    }

    /// Each callback enters the ready queue once. Input type nodes are visited
    /// once per callback; each dependency edge wakes once. Detecting newly
    /// settled parameters costs O(callbacks * generic parameters).
    const CallbackWork = struct {
        bounds: []TypeId,
        structural: []bool,
        remaining: []usize,
        notified: []bool,
        waiting: std.AutoHashMapUnmanaged(TypeId, std.ArrayList(usize)) = .empty,
        ready: std.ArrayList(usize) = .empty,

        fn init(gpa: std.mem.Allocator, count: usize, settling: []const Settling) !CallbackWork {
            const bounds = try gpa.alloc(TypeId, count);
            errdefer gpa.free(bounds);
            @memset(bounds, .poison);
            const structural = try gpa.alloc(bool, count);
            errdefer gpa.free(structural);
            @memset(structural, false);
            const remaining = try gpa.alloc(usize, count);
            errdefer gpa.free(remaining);
            @memset(remaining, 0);
            var parameters: usize = 0;
            for (settling) |slot| parameters += slot.found.len;
            const notified = try gpa.alloc(bool, parameters);
            errdefer gpa.free(notified);
            var index: usize = 0;
            for (settling) |slot| for (slot.found) |found| {
                notified[index] = found != .poison;
                index += 1;
            };
            var ready: std.ArrayList(usize) = .empty;
            try ready.ensureTotalCapacity(gpa, count);
            return .{ .bounds = bounds, .structural = structural, .remaining = remaining, .notified = notified, .ready = ready };
        }

        fn deinit(self: *CallbackWork, gpa: std.mem.Allocator) void {
            var lists = self.waiting.valueIterator();
            while (lists.next()) |list| list.deinit(gpa);
            self.waiting.deinit(gpa);
            self.ready.deinit(gpa);
            gpa.free(self.bounds);
            gpa.free(self.structural);
            gpa.free(self.remaining);
            gpa.free(self.notified);
        }

        fn waitFor(self: *CallbackWork, gpa: std.mem.Allocator, parameter: TypeId, callback: usize) !void {
            const entry = try self.waiting.getOrPut(gpa, parameter);
            if (!entry.found_existing) entry.value_ptr.* = .empty;
            try entry.value_ptr.append(gpa, callback);
            self.remaining[callback] += 1;
        }

        fn wake(self: *CallbackWork, settling: []const Settling) void {
            var index: usize = 0;
            for (settling) |slot| for (slot.found, slot.parameters) |found, parameter| {
                defer index += 1;
                if (self.notified[index] or found == .poison) continue;
                self.notified[index] = true;
                const waiting = self.waiting.get(parameter) orelse continue;
                for (waiting.items) |callback| {
                    self.remaining[callback] -= 1;
                    if (self.remaining[callback] == 0) self.ready.appendAssumeCapacity(callback);
                }
            };
        }
    };

    fn mentionsSettling(self: *const Checker, ty: TypeId, settling: []const Settling) bool {
        for (settling) |s| {
            if (self.mentionsParameter(ty, s.owner, .stops)) return true;
        }
        return false;
    }

    fn reportCallbackInputs(self: *Checker, value: ExprId) void {
        _ = self.report(.t_infer, value, "the callable signature depends on a type no other argument or result settles", .{}, "settle every input type before this callable value");
    }

    fn openCallbackParameters(self: *const Checker, ty: TypeId, settling: []const Settling, out: *std.AutoHashMapUnmanaged(TypeId, void), visited: *std.AutoHashMapUnmanaged(TypeId, void)) std.mem.Allocator.Error!void {
        const entry = try visited.getOrPut(self.gpa, ty);
        if (entry.found_existing) return;
        if (self.builder.standinOf(ty)) |standin| {
            try self.openCallbackParameters(standin.held, settling, out, visited);
            for (self.builder.standinArgsOf(standin)) |arg| try self.openCallbackParameters(arg, settling, out, visited);
            return;
        }
        switch (self.builder.get(ty)) {
            .parameter => if (self.hasOpenParameter(ty, settling)) {
                try out.put(self.gpa, ty, {});
            },
            .array => |array| try self.openCallbackParameters(array.element, settling, out, visited),
            .borrow => |borrowed| try self.openCallbackParameters(borrowed.referent, settling, out, visited),
            .callable => |signature| {
                for (self.builder.callableParams(signature)) |parameter| try self.openCallbackParameters(parameter.ty, settling, out, visited);
                try self.openCallbackParameters(signature.result, settling, out, visited);
            },
            .closure => |closure| {
                for (self.builder.closureArgs(closure)) |arg| try self.openCallbackParameters(arg, settling, out, visited);
                for (self.builder.closureImplArgs(closure)) |arg| try self.openCallbackParameters(arg, settling, out, visited);
                if (closure.self_ty != .poison) try self.openCallbackParameters(closure.self_ty, settling, out, visited);
            },
            else => if (self.builder.instanceOf(ty)) |instance| {
                for (self.builder.argsOf(instance)) |arg| try self.openCallbackParameters(arg, settling, out, visited);
            },
        }
    }

    fn callableInputsKnown(self: *const Checker, ty: TypeId, settling: []const Settling) bool {
        const signature = switch (self.builder.get(ty)) {
            .callable => |signature| signature,
            else => return false,
        };
        for (self.builder.callableParams(signature)) |parameter| {
            if (self.hasOpenParameter(parameter.ty, settling)) return false;
        }
        return true;
    }

    /// What a call settled for a callee's own type parameters, followed by
    /// the `Self` it settled where the callee is a trait signature. A
    /// signature's `where` subjects are read over its symbolic `Self`, which
    /// stands after its own parameters, so substituting this list reads them
    /// at the call. Anything else keeps `settled`; a
    /// different slice is the caller's to free.
    fn withSettledSelf(self: *Checker, d: node.DeclId, settled: []const TypeId) std.mem.Allocator.Error![]const TypeId {
        const held = self.self_at_call orelse return settled;
        return self.withSelf(d, settled, held);
    }

    /// What a call settled for a callee's own type parameters, followed by
    /// the callee's own symbolic `Self` where it is a trait signature: the
    /// list that substitutes a type already read at the call's `Self` without
    /// reading its `Self` again. A different slice is the caller's to free.
    fn withSymbolicSelf(self: *Checker, d: node.DeclId, settled: []const TypeId) std.mem.Allocator.Error![]const TypeId {
        if (self.self_at_call == null) return settled;
        const own: u32 = @intCast(self.ast.declTypeParams(d).len);
        // A symbolic `Self` never interned appears in no type to keep.
        return self.withSelf(d, settled, self.builder.internedParameter(@intCast(d.index()), own) orelse .poison);
    }

    fn withSelf(self: *Checker, d: node.DeclId, settled: []const TypeId, held: TypeId) std.mem.Allocator.Error![]const TypeId {
        if (!self.ast.declIsSignature(d)) return settled;
        const own = self.ast.declTypeParams(d).len;
        if (settled.len != own) return settled;
        const out = try self.gpa.alloc(TypeId, own + 1);
        @memcpy(out[0..own], settled);
        out[own] = held;
        return out;
    }

    /// A callable bound on a callee's own type parameter `declared`, as the
    /// call reads it. A trait signature's bound may name `Self` and what its
    /// implementation settles, so it is read again where the call is, with
    /// the call's `Self` and in the caller's scope -- the reading its
    /// parameter types take, and the one a bound check at the call takes, so
    /// the callback is inferred against the bound it is held to. A `where`
    /// clause of the caller then proves what the reading needs, as it does
    /// for `Filter[S.Iter, F]` walked inside `fn f[S: Sequence]`. Every other
    /// callee's bounds are what its parameters were interned with.
    ///
    /// **Bound:** the bounds written on the one parameter, read once.
    fn boundAtCall(self: *Checker, d: node.DeclId, declared: TypeId, bound: TypeId) std.mem.Allocator.Error!TypeId {
        if (bound == .poison or !self.ast.declIsSignature(d) or self.self_at_call == null) return bound;
        const parameter = switch (self.builder.get(declared)) {
            .parameter => |p| p,
            else => return bound,
        };
        if (parameter.owner != d.index()) return bound;
        const interned = self.builder.callableBoundsOn(declared);
        const at = std.mem.indexOfScalar(TypeId, interned, bound) orelse return bound;
        const reread = try self.callablesBounding(
            .{ .module = self.program.moduleOf(d), .owner = d },
            self.parameterBounds(d, parameter.index),
            self.builder.boundsOn(declared),
        );
        defer if (reread.len > 0) self.gpa.free(reread);
        if (reread.len != interned.len) return bound;
        return reread[at];
    }

    /// Keep undetermined result parameters symbolic while supplying known inputs.
    fn callableContext(self: *Checker, ty: TypeId, settling: []const Settling) !TypeId {
        var result = ty;
        for (settling) |slot| {
            const replacements = try self.gpa.dupe(TypeId, slot.found);
            defer self.gpa.free(replacements);
            for (replacements, self.param_types[slot.owner.index()]) |*replacement, parameter| {
                if (replacement.* == .poison) replacement.* = parameter;
            }
            result = try self.builder.substitute(result, slot.owner.index(), replacements);
        }
        return result;
    }

    /// `signature` without the contracts that name a capture or the callee.
    /// Those describe one closure's environment, and a structural callable
    /// type has none: what it carries is its callee's, which a call through a
    /// requirement adds back.
    fn withoutEnvironmentContracts(self: *Checker, signature_ty: TypeId) std.mem.Allocator.Error!TypeId {
        const signature = switch (self.builder.get(signature_ty)) {
            .callable => |signature| signature,
            else => return signature_ty,
        };
        var kept: std.ArrayList(types_mod.CallableContract) = .empty;
        defer kept.deinit(self.gpa);
        for (signature.contracts) |contract| {
            const environmental = contract.source.root == .capture or contract.source.root == .callee or
                (contract.destination != null and contract.destination.?.root == .capture);
            if (!environmental) try kept.append(self.gpa, contract);
        }
        if (kept.items.len == signature.contracts.len) return signature_ty;
        const params = try self.gpa.dupe(types_mod.CallableParam, self.builder.callableParams(signature));
        defer self.gpa.free(params);
        return self.builder.internCallable(params, signature.result, kept.items, signature.invocation);
    }

    /// The structural signature a value of type `ty` is called as: a
    /// closure's own, a function value's, or the one callable bound of a type
    /// parameter. Null for anything else, which has none to offer.
    fn callbackCallableSignature(self: *Checker, ty: TypeId) std.mem.Allocator.Error!?TypeId {
        return switch (self.builder.get(ty)) {
            .closure => |closure| try self.builder.closureSignature(closure),
            .callable => ty,
            else => {
                const bounds = self.builder.callableBoundsOn(ty);
                return if (bounds.len == 1 and self.builder.get(bounds[0]) == .callable) bounds[0] else null;
            },
        };
    }

    fn callbackValueSignature(self: *Checker, ty: TypeId) std.mem.Allocator.Error!TypeId {
        return switch (self.builder.get(ty)) {
            .closure => |closure| try self.builder.closureSignature(closure),
            else => ty,
        };
    }

    fn settleCallbackResult(self: *Checker, bound: TypeId, supplied: TypeId, settling: []const Settling, at: ExprId) std.mem.Allocator.Error!bool {
        // A bound that is a type parameter settles to the callback's signature
        // as a structural type, which names no capture of the callback.
        const offered = if (self.builder.get(bound) == .parameter) try self.withoutEnvironmentContracts(supplied) else supplied;
        for (settling) |slot| {
            var clash: ?Clash = null;
            if (try self.settleByInContext(bound, offered, slot.owner, slot.found, &clash, .signature_types, settling)) continue;
            const conflict = clash.?;
            _ = self.report(.t_mismatch, at, "`{s}` was settled as `{s}`, but the callback supplies `{s}`", .{
                self.ast.tokenText(slot.generics[conflict.index].name),
                (try self.typeName(conflict.was)),
                (try self.typeName(conflict.got)),
            }, "one type parameter, two types");
            return false;
        }
        return true;
    }

    /// Select a named callback's lists -- its own generics with a trait
    /// operation's `Self`, a generic inherent implementation's parameters, a
    /// trait's -- from the already-known inputs. Exact interface validation
    /// remains in selectFunctionValue.
    fn namedCallbackSignature(self: *Checker, value: ExprId, context: TypeId, settling: []const Settling) !?TypeId {
        const at = self.ast.withoutGroups(value);
        if (self.qualifiedConstructor(at) or self.contextualConstructor(at)) {
            const selection = try self.constructorSignature(at, context, settling) orelse return null;
            return selection.signature;
        }
        const target = self.res.targetOf(self.ast.withoutGroups(value));
        if (target == .none or self.res.kindOf(target) != .function) return null;
        const declaration = self.res.declaredBy(target);
        if (self.ineligibleFunction(declaration) != null) return null;
        try self.ensureSignature(declaration);
        const signature = self.decl_signatures.get(declaration);
        const lists = self.valueLists(declaration);
        var found: [3][]TypeId = undefined;
        var allocated: usize = 0;
        defer for (found[0..allocated]) |list| self.gpa.free(list);
        var total: usize = 0;
        for (&found, 0..) |*list, k| {
            list.* = try self.gpa.alloc(TypeId, self.valueListLen(lists, k));
            allocated += 1;
            @memset(list.*, .poison);
            total += list.len;
        }
        if (total == 0) return signature;
        const actual = switch (self.builder.get(signature)) {
            .callable => |callable| callable,
            else => return null,
        };
        const wanted = switch (self.builder.get(context)) {
            .callable => |callable| callable,
            else => return null,
        };
        const actual_params = self.builder.callableParams(actual);
        const wanted_params = self.builder.callableParams(wanted);
        if (actual_params.len != wanted_params.len) return null;
        for (lists.owners(), found) |owner, list| {
            if (owner == node.DeclId.none or list.len == 0) continue;
            for (actual_params, wanted_params) |parameter, expected_parameter| {
                var clash: ?Clash = null;
                if (!try self.settleSignatureTypes(parameter.ty, expected_parameter.ty, owner, list, &clash)) return null;
            }
            var result_clash: ?Clash = null;
            if (!try self.settleByInContext(actual.result, wanted.result, owner, list, &result_clash, .signature_types, settling)) return null;
            for (list) |ty| if (ty == .poison) return null;
        }
        return try self.throughValue(signature, lists, .{ found[0], found[1], found[2] });
    }

    fn settleCallResult(
        self: *Checker,
        d: node.DeclId,
        args: []const ExprId,
        settling: []const Settling,
        expected: ?Expected,
        success: ?SuccessExpectation,
        failure: ?FailureExpectation,
        method: ?MethodExpectation,
    ) std.mem.Allocator.Error!void {
        if (expected == null and success == null and failure == null and method == null) return;
        try self.settleResultContexts(try returnType(self, d), settling, expected, success, failure, method, .{ .callee = d, .args = args });
    }

    fn successExpectationAt(self: *const Checker, id: ExprId) ?SuccessExpectation {
        const want = self.success_expected orelse return null;
        return if (want.target == id) want else null;
    }

    fn methodExpectationAt(self: *const Checker, id: ExprId) ?MethodExpectation {
        const want = self.method_expected orelse return null;
        return if (want.target == self.ast.withoutGroups(id)) want else null;
    }

    /// Settle what a call left open through the postfix call made on its
    /// result: find the operation `method` names on `result`, read the
    /// operation's result with its receiver bound to `result`, and settle
    /// that against what the postfix call is expected to produce, projected
    /// through its success context. Only parameters still open are kept, as
    /// the failure context keeps them, so this adds evidence and never
    /// overrides the call's own.
    ///
    /// **Bound:** one lookup of the name on the result's type, and one walk
    /// of the operation's receiver and result types.
    fn settleThroughMethod(self: *Checker, result: TypeId, settling: []const Settling, method: ?MethodExpectation) std.mem.Allocator.Error!void {
        const want = method orelse return;
        var unsettled = false;
        for (settling) |s| for (s.found) |f| {
            if (f == .poison) unsettled = true;
        };
        if (!unsettled or result == .poison) return;

        try self.prepareNamedLookup(result, want.name, false, .operation, null);
        var applicable: std.ArrayList(Applicable) = .empty;
        defer applicable.deinit(self.gpa);
        const pool = try self.builder.capabilityView();
        try self.reaching(&pool).named(self.gpa, result, want.name, &applicable);
        var name_reach: NameReach = .{};
        for (applicable.items) |a| name_reach.note(a);
        var reached: ?node.DeclId = null;
        for (applicable.items) |a| if (name_reach.reaches(a)) {
            if (reached != null) return;
            reached = a.sig;
        };
        const sig = reached orelse return;
        if (self.ast.declParams(sig).len == 0) return;

        // Bind the operation's own parameters and its implementation's from
        // the receiver alone, as a call binds them from its first argument.
        const over = self.headParametersOf(sig);
        const own = try self.gpa.alloc(TypeId, self.ast.declTypeParams(sig).len);
        defer self.gpa.free(own);
        @memset(own, .poison);
        const head = try self.gpa.alloc(TypeId, if (over == node.DeclId.none) 0 else self.ast.declTypeParams(over).len);
        defer self.gpa.free(head);
        @memset(head, .poison);
        const receiver = try paramType(self, sig, 0);
        var ignored: ?Clash = null;
        _ = try self.settle(receiver, result, sig, own, &ignored);
        if (over != node.DeclId.none) _ = try self.settle(receiver, result, over, head, &ignored);
        var answers = try self.throughCall(try returnType(self, sig), sig, over, .{ .own = own, .head = head });

        const target = if (want.success) |success| blk: {
            answers = self.successType(answers, success.depth) orelse return;
            break :blk success.expected;
        } else want.expected orelse return;
        if (target.ty == .poison or answers == .poison) return;

        for (settling) |s| {
            const scratch = try self.gpa.dupe(TypeId, s.found);
            defer self.gpa.free(scratch);
            var clash: ?Clash = null;
            _ = try self.settle(answers, target.ty, s.owner, scratch, &clash);
            for (s.found, scratch) |*kept, settled| {
                if (kept.* == .poison) kept.* = settled;
            }
        }
    }

    /// A parameter that takes a callback, and the signature its argument meets.
    const CallbackParameter = struct {
        /// Poison where a type parameter carries several callable bounds.
        signature: TypeId,
        /// A structural callable type converts its argument to that type; a
        /// callable bound keeps the argument's own signature or closure type.
        structural: bool,
    };

    /// Whether a parameter declared as `declared` takes a callback: a
    /// structural callable type, or a type parameter with a callable bound.
    /// Call inference's callback worklist and propagation context both read
    /// this, so the two forms of callback parameter behave alike.
    fn callbackParameter(self: *const Checker, declared: TypeId) ?CallbackParameter {
        if (self.builder.get(declared) == .callable) return .{ .signature = declared, .structural = true };
        const bounds = self.builder.callableBoundsOn(declared);
        if (bounds.len == 0) return null;
        return .{ .signature = if (bounds.len == 1) bounds[0] else .poison, .structural = false };
    }

    /// Whether a callback argument leaves its result for context to supply.
    /// A lambda without a written result and a leading-dot constructor do; a
    /// named function, a qualified constructor, an annotated lambda and any
    /// value with its own type already fix their result.
    fn leavesCallbackResultOpen(self: *const Checker, argument: ExprId) bool {
        const marked = if (self.ast.exprTag(argument) == .marked) self.ast.unaryOperand(argument) else argument;
        const value = self.ast.withoutGroups(marked);
        if (self.contextualConstructor(value)) return true;
        if (self.ast.exprTag(value) != .lambda) return false;
        return !self.ast.lambda(value).result.wasWritten();
    }

    /// A call whose callback arguments propagation context may reach.
    const CallbackArguments = struct {
        callee: node.DeclId,
        args: []const ExprId,
    };

    /// Whether type parameter `index` of `owner` appears in the result of a
    /// callback whose argument at this call leaves that result open.
    ///
    /// **Bound:** the callee's parameters, each result walked once.
    fn openCallbackResultNames(self: *Checker, call: CallbackArguments, owner: node.DeclId, index: u32) std.mem.Allocator.Error!bool {
        const count = @min(call.args.len, self.ast.declParams(call.callee).len);
        for (call.args[0..count], 0..) |argument, j| {
            if (argument == .none or !self.leavesCallbackResultOpen(argument)) continue;
            const callback = self.callbackParameter(try paramType(self, call.callee, j)) orelse continue;
            switch (self.builder.get(callback.signature)) {
                .callable => |signature| if (self.mentionsParameterAt(signature.result, owner, .walks_on, index)) return true,
                else => {},
            }
        }
        return false;
    }

    /// Whether type parameter `index` of `owner` is the declared type of an
    /// argument written as an integer literal at this call, so that nothing
    /// but a use settles it.
    ///
    /// **Bound:** the callee's parameters, each declared type read once.
    fn integerLiteralNames(self: *Checker, call: CallbackArguments, owner: node.DeclId, index: u32) std.mem.Allocator.Error!bool {
        const count = @min(call.args.len, self.ast.declParams(call.callee).len);
        for (call.args[0..count], 0..) |argument, j| {
            if (argument == .none) continue;
            var value = argument;
            while (true) switch (self.ast.exprTag(value)) {
                .grouped, .negate, .marked => value = self.ast.unaryOperand(value),
                else => break,
            };
            if (self.ast.exprTag(value) != .int_literal) continue;
            const declared = try paramType(self, call.callee, j);
            switch (self.builder.get(declared)) {
                .parameter => |p| if (p.owner == owner.index() and p.index == index) return true,
                else => {},
            }
        }
        return false;
    }

    fn isIntegerType(self: *Checker, t: TypeId) bool {
        return t.bounds() != null or self.builder.isIntegerWithin(self.generic, t);
    }

    fn failureExpectationAt(self: *const Checker, id: ExprId) ?FailureExpectation {
        const want = self.failure_expected orelse return null;
        return if (want.target == id) want else null;
    }

    fn settleResultContexts(
        self: *Checker,
        result: TypeId,
        settling: []const Settling,
        expected: ?Expected,
        success: ?SuccessExpectation,
        failure: ?FailureExpectation,
        method: ?MethodExpectation,
        call: CallbackArguments,
    ) std.mem.Allocator.Error!void {
        try self.settleThroughMethod(result, settling, method);

        // A sibling arm can supply the whole result, including its error.
        // Payload context adds a constraint without replacing that evidence.
        for ([_]?Expected{ expected, if (success) |p| p.expected else null }, 0..) |context, index| {
            const want = context orelse continue;
            if (want.ty == .poison) continue;
            var unsettled = false;
            for (settling) |s| for (s.found) |f| {
                if (f == .poison) unsettled = true;
            };
            if (!unsettled) return;

            const answers = switch (index) {
                0 => result,
                1 => self.successType(result, success.?.depth) orelse continue,
                else => unreachable,
            };
            for (settling) |s| {
                var ignored: ?Clash = null;
                _ = try self.settle(answers, want.ty, s.owner, s.found, &ignored);
            }
        }
        if (failure) |want| {
            var at = result;
            for (0..want.depth + 1) |_| {
                const carrier = self.carrierOf(at) orelse break;
                if (carrier.kind == .result) for (settling) |s| {
                    // Propagation constrains only what the call left open: a
                    // callback result, or the type of an integer literal. It
                    // settles into a scratch copy, and only parameters named
                    // by the result of a callback whose argument leaves that
                    // result open, or by the type of an integer literal
                    // argument where the propagated error is an integer, are
                    // kept.
                    const scratch = try self.gpa.dupe(TypeId, s.found);
                    defer self.gpa.free(scratch);
                    var ignored: ?Clash = null;
                    _ = try self.settle(self.errorTypeOf(carrier), want.expected, s.owner, scratch, &ignored);
                    for (s.found, scratch, 0..) |*kept, settled, index| {
                        if (kept.* != .poison or settled == .poison) continue;
                        if (try self.openCallbackResultNames(call, s.owner, @intCast(index)) or
                            (self.isIntegerType(settled) and try self.integerLiteralNames(call, s.owner, @intCast(index))))
                            kept.* = settled;
                    }
                };
                at = self.payloadTypeOf(carrier);
            }
        }
    }

    fn successType(self: *const Checker, ty: TypeId, depth: u32) ?TypeId {
        var result = ty;
        for (0..depth) |_| {
            const carrier = self.carrierOf(result) orelse return null;
            result = self.payloadTypeOf(carrier);
        }
        return result;
    }

    /// Whether `id` is a name or a qualified path, whatever it reaches.
    fn namesSomething(self: *const Checker, id: ExprId) bool {
        return switch (self.ast.exprTag(self.ast.withoutGroups(id))) {
            .name_ref, .field => true,
            else => false,
        };
    }

    fn isLambda(self: *const Checker, id: ExprId) bool {
        return self.ast.exprTag(self.ast.withoutGroups(id)) == .lambda;
    }

    fn needsCallableContext(self: *const Checker, id: ExprId) bool {
        const at = self.ast.withoutGroups(id);
        if (self.ast.exprTag(at) == .lambda) return true;
        if (self.qualifiedConstructor(at)) return true;
        if (self.contextualConstructor(at)) return true;
        if (self.ast.exprTag(at) != .name_ref and self.ast.exprTag(at) != .field) return false;
        const target = self.res.targetOf(at);
        return target != BindingId.none and self.res.kindOf(target) == .function;
    }

    fn contextualConstructor(self: *const Checker, id: ExprId) bool {
        const at = self.ast.withoutGroups(id);
        return self.ast.exprTag(at) == .variant_ref and self.ast.unaryOperand(at) == .none and self.res.targetOf(at) == .none;
    }

    fn hasOpenParameter(self: *const Checker, ty: TypeId, settling: []const Settling) bool {
        if (self.builder.standinOf(ty)) |standin| return self.hasOpenParameter(standin.held, settling);
        switch (self.builder.get(ty)) {
            .poison => return true,
            .parameter => |parameter| {
                for (settling) |s| {
                    if (parameter.owner != s.owner.index() or parameter.index >= s.found.len) continue;
                    return s.found[parameter.index] == .poison;
                }
                return false;
            },
            .array => |array| return self.hasOpenParameter(array.element, settling),
            .borrow => |b| return self.hasOpenParameter(b.referent, settling),
            .callable => |signature| {
                for (self.builder.callableParams(signature)) |parameter| {
                    if (self.hasOpenParameter(parameter.ty, settling)) return true;
                }
                return self.hasOpenParameter(signature.result, settling);
            },
            .closure => |closure| {
                for (self.builder.closureArgs(closure)) |arg| {
                    if (self.hasOpenParameter(arg, settling)) return true;
                }
                for (self.builder.closureImplArgs(closure)) |arg| {
                    if (self.hasOpenParameter(arg, settling)) return true;
                }
                return closure.self_ty != .poison and self.hasOpenParameter(closure.self_ty, settling);
            },
            else => {},
        }
        const origin = self.builder.instanceOf(ty) orelse return false;
        for (self.builder.argsOf(origin)) |arg| {
            if (self.hasOpenParameter(arg, settling)) return true;
        }
        return false;
    }

    /// The implementation whose parameters a callee is written in, or none
    /// where it is written in none.
    ///
    /// Read through the one index that says which implementation encloses a
    /// declaration, so the head a call binds and the head a member's body is
    /// checked against are one implementation rather than two lookups.
    fn headParametersOf(self: *const Checker, d: node.DeclId) node.DeclId {
        const impl = self.implEnclosing(d) orelse return node.DeclId.none;
        if (self.ast.declTypeParams(impl).len == 0) return node.DeclId.none;
        return impl;
    }

    /// A type written in a callee, read through everything the call settled.
    ///
    /// Both lists, in one place: a member of an implementation generic over its
    /// head names the implementation's parameters where it names its own, and a
    /// type mentioning either is not a type until both are bound.
    fn throughCall(
        self: *Checker,
        ty: TypeId,
        d: node.DeclId,
        over: node.DeclId,
        settled: Bindings,
    ) std.mem.Allocator.Error!TypeId {
        // A trait signature's types are read at the call's `Self` (`paramType`,
        // `returnType`), so its symbolic `Self`, which sits after its own
        // parameters, is already replaced by the `Self` the call settled.
        // Where that `Self` is written in the callee's own terms -- a provided
        // body calling itself, on `self` or on `self.up()` -- the symbolic
        // `Self` in the type is the caller's and stays as it is, rather than
        // being read at the call's `Self` a second time.
        const bound = try self.withSymbolicSelf(d, settled.own);
        defer if (bound.ptr != settled.own.ptr) self.gpa.free(bound);
        const own = try self.builder.substitute(ty, @intCast(d.index()), bound);
        if (over == node.DeclId.none) return own;
        return self.builder.substitute(own, @intCast(over.index()), settled.head);
    }

    /// Records which member of a family a call reached, for lowering to emit
    /// the body that member has.
    ///
    /// The head read through what the call bound the implementation's
    /// parameters to, which is the type the member exists once per. Written
    /// into the same table a call through a trait writes, because it answers
    /// the same question -- what this call settled the head to -- and a second
    /// table would be a second answer.
    fn noteSettledHead(
        self: *Checker,
        id: ExprId,
        over: node.DeclId,
        bound: []const TypeId,
    ) std.mem.Allocator.Error!?usize {
        const self_ty = try self.settledHead(over, bound) orelse return null;
        const at = self.call_impls.items.len;
        try self.call_impls.append(self.gpa, .{
            .call = @intCast(id.index()),
            .trait = types_mod.Implementation.no_trait,
            .self_ty = self_ty,
        });
        return at;
    }

    /// The head of a generic inherent implementation, read through what its
    /// parameters were settled to: the receiver type one member instance runs
    /// for. A call and a function value naming the member both key by it.
    fn settledHead(
        self: *Checker,
        over: node.DeclId,
        bound: []const TypeId,
    ) std.mem.Allocator.Error!?TypeId {
        const row = self.rowFor(over) orelse return null;
        return try self.builder.substitute(row.ty, @intCast(over.index()), bound);
    }

    /// The type a declaration's name stands for here.
    ///
    /// For a type taking no parameters, the one it always stood for. For a
    /// generic one, the name alone is a template rather than a type: which
    /// instantiation is meant is the expectation's to say, supplied by context
    /// or inferred from the payload before this is reached. Falling back to
    /// the template keeps a program that determined neither from losing its
    /// diagnostic to a poison.
    fn instanceFor(self: *const Checker, d: node.DeclId, expected: ?Expected) ?TypeId {
        const template = self.type_of_decl.get(d);
        if (self.ast.declTypeParams(d).len == 0) return template;

        // The expectation says which instantiation is meant only where it is
        // one of *this* declaration's. Handed back unchecked, `Option.None`
        // took the type of whatever was expected -- so it type-checked as a
        // `UInt8`, and as another enum's instantiation it produced a value whose
        // layout the code that read it did not have.
        const want = Expected.typeOf(expected) orelse return null;
        const origin = self.builder.instanceOf(want) orelse return null;
        if (origin.decl != d) return null;
        return want;
    }

    /// Reports a generic type named where the context wanted something else,
    /// or wanted nothing at all.
    ///
    /// The two read differently to whoever wrote it: a type was expected and
    /// this is not one of them, or no type was expected and this one names no
    /// instantiation.
    fn reportWrongInstance(
        self: *Checker,
        at: ExprId,
        d: node.DeclId,
        expected: ?Expected,
    ) TypeId {
        const want = Expected.typeOf(expected) orelse return self.reportUndetermined(at, d);
        return self.report(
            .t_mismatch,
            at,
            "expected `{s}`, found {s} `{s}`",
            .{ self.typeName(want) catch return self.record(at, .poison), article.before(self.ast.tokenText(self.ast.declName(d))), self.ast.tokenText(self.ast.declName(d)) },
            "this names a different type",
        );
    }

    /// Reports a generic type named where nothing says which instantiation is
    /// meant. A template is not a type, and handing one out would let it stand
    /// in for the instantiation nobody chose.
    fn reportUndetermined(self: *Checker, at: ExprId, d: node.DeclId) TypeId {
        // Named rather than counted. A programmer fixes this by saying what a
        // parameter is, and a message about "the arguments" leaves them to
        // work out which ones those are.
        var names: std.ArrayList(u8) = .empty;
        for (self.ast.declTypeParams(d), 0..) |p, i| {
            if (i > 0) names.appendSlice(self.sink.arena, ", ") catch break;
            names.appendSlice(self.sink.arena, self.ast.tokenText(p.name)) catch break;
        }

        return self.report(
            .t_infer,
            at,
            "nothing here says what `{s}` is",
            .{names.items},
            "give the binding a type, or annotate the signature it comes from",
        );
    }

    /// What a constructor's payload said about its enum's parameters.
    ///
    /// `.reported` rather than `.nothing` where a parameter was left
    /// undetermined, because the caller would otherwise ask the same question
    /// of the whole declaration and answer it worse: it knows only that no
    /// instantiation was settled, and this knows which parameter and why.
    const Inferred = union(enum) { nothing, made: Expected, reported };

    /// The instantiation a construction's payload determines, where the enum
    /// it names is generic and nothing expects a particular one.
    ///
    /// Every parameter the selected variant's payload mentions is settled by
    /// the argument in that position. A parameter the payload does not mention
    /// is settled by nothing here and must come from context -- so
    /// `Option.Some(3)` infers and `Result.Ok(3)` does not, because no
    /// argument of `Ok` says what `E` is.
    ///
    /// The payload's *checked* type is what settles it, so
    /// `Option.Some(copy(x))` reads `x`'s type rather than the shape of the
    /// expression that produced it. Each value checked here is marked in
    /// `walked`, and the caller reads its recorded type rather than checking
    /// it again.
    fn inferConstruct(
        self: *Checker,
        id: ExprId,
        expected: ?Expected,
        walked: []bool,
    ) std.mem.Allocator.Error!Inferred {
        if (Expected.typeOf(expected) != null) return .nothing;

        const c = self.ast.call(id);
        const callee = self.ast.withoutGroups(c.callee);
        const target = self.res.targetOf(callee);
        if (target == BindingId.none) return .nothing;

        const d = self.res.declaredBy(target);
        const params = self.ast.declTypeParams(d);
        if (params.len == 0) return .nothing;

        const template = self.type_of_decl.get(d);
        const k = self.variantOrdinal(callee) orelse return .nothing;
        if (self.builder.variantFieldCount(template, k) != c.args.len) return .nothing;

        const found = try self.gpa.alloc(TypeId, params.len);
        defer self.gpa.free(found);
        @memset(found, .poison);

        // A generic alias heading the variant fixes the arguments it writes
        // closed, and the payload settles the rest.
        var heading: ?AliasHeading = null;
        const q = self.ast.unaryOperand(callee);
        if (q != ExprId.none) if (self.genericAliasHead(self.res.targetOf(q))) |alias| {
            if (self.aliasPathType(self.res.targetOf(q))) |aliased| if (self.builder.instanceOf(aliased)) |instance| {
                const written = self.builder.argsOf(instance);
                if (written.len == params.len) {
                    heading = .{ .alias = alias, .written = written, .found = try self.openAliasArguments(alias) };
                    self.seedAliasHeading(heading.?, found);
                }
            };
        };

        // Which parameters a payload was checked to settle. One whose payload
        // has no type was reported where that payload is written.
        const tried = try self.gpa.alloc(bool, params.len);
        defer self.gpa.free(tried);
        @memset(tried, false);
        for (c.args, 0..) |a, j| {
            const carried = self.builder.variantFieldType(template, k, @intCast(j));
            const p = switch (self.builder.get(carried)) {
                .parameter => |x| x,
                // A payload that is not a bare parameter settles nothing:
                // reading through `Inner[T]` to find `T` is unification, and
                // inference here is local by design.
                else => continue,
            };
            if (p.owner != d.index() or p.index >= found.len) continue;
            if (found[p.index] != .poison) continue;
            found[p.index] = try self.check(a, null);
            walked[j] = true;
            tried[p.index] = true;
        }

        if (heading) |h| try self.closeAliasHeading(h, found);

        // A payload settles the parameters it mentions and no others, so a
        // variant carrying one of two says which is missing. Reporting it here
        // is what keeps that knowledge: the caller sees only that no type was
        // determined, and would have to say so about the whole declaration.
        // A payload with no type was reported where it is written, and the
        // parameter it would have settled is that mistake's consequence. A
        // parameter no payload mentions is a mistake of its own, reported
        // whichever order the parameters are declared in.
        var unsettled = false;
        var reported = false;
        for (found, tried, self.ast.declTypeParams(d)) |f, t, g| {
            if (f != .poison) continue;
            unsettled = true;
            if (t or reported) continue;
            _ = self.report(
                .t_infer,
                id,
                "nothing here says what `{s}` is",
                .{self.ast.tokenText(g.name)},
                "no argument of this variant determines it",
            );
            reported = true;
        }
        if (unsettled) return .reported;

        // A bound is a claim about every instantiation, so it is asked wherever
        // one is made. Asked only where a type was written down and where a
        // call settled one, the same program was refused with an annotation on
        // it and accepted without.
        try self.checkArgumentBounds(d, found, null, self.ast.exprMain(id));

        const made = try self.builder.instantiate(template, d, found);
        return .{ .made = .{
            .ty = made,
            .at = .{ .file = self.ast.fileOfExpr(id), .span = self.ast.exprSpan(id) },
            .reason = .payload,
        } };
    }

    /// `match e { P => body, … }`.
    ///
    /// Each arm's pattern is checked against the scrutinee's type, then asked
    /// whether some value reaches it past the arms before it; once every arm
    /// is checked, whether some value reaches none of them. Both questions are
    /// coverage's, so a pattern nested at any depth is held to them alike.
    fn checkMatch(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const m = self.ast.call(id);
        // A `match read` lends what its arms bind, exactly as a lending walk
        // lends what it projects: the body reads a place it does not own.
        const lends = self.ast.exprTag(id) == .match_read;
        // The arms are checked against the scrutinee's type, read as a
        // receiver's is: an open literal matched itself takes the default
        // here, where its arms compare it. A scrutinee whose type only holds
        // an open literal -- the `Option` a range's `next` hands back -- is
        // taken apart by its known head. Its arms bind what it holds without
        // comparing it, so the open type passes to the binders and settles by
        // their uses, as it does for a walk's binder and `let ... else`.
        const scrutinee = try self.receiverType(try self.check(m.callee, null), self.literalSite(m.callee));
        if (scrutinee == .never) {
            var j: usize = 1;
            while (j < m.args.len) : (j += 2) _ = try self.check(m.args[j], null);
            return self.expect(id, .never, expected);
        }

        // On the scrutinee's type, not on what the arms name. A catch-all
        // names no variant and so needs nothing from a sealed type, which
        // would make it the obvious exemption -- and the exemption is exactly
        // how the seal would be defeated.
        if (self.sealedHere(scrutinee)) {
            var j: usize = 1;
            while (j < m.args.len) : (j += 2) _ = try self.check(m.args[j], null);
            return self.reportSealed(id, scrutinee, "only its own module can take one apart");
        }

        // An implicit test success permits unit arms without changing their
        // value type. The first completing arm settles the match itself; the
        // test body records the later wrapping into its success result.
        var arms: MatchArms = .{ .settled = expected, .can_wait = expected == null and self.someArmDeterminesItsOwnType(m.args) };
        defer arms.waiting.deinit(self.gpa);
        var poisoned = scrutinee == .poison;

        // The sound arms, as coverage reads them, and the patterns they came
        // from. Built in an arena sized by this match's patterns and freed
        // with it.
        var state = std.heap.ArenaAllocator.init(self.gpa);
        defer state.deinit();
        var coverage: PatternCoverage = .{ .context = .{ .checker = self }, .arena = state.allocator() };
        var rows: std.ArrayList(PatternCoverage.Row) = .empty;
        var row_patterns: std.ArrayList(ExprId) = .empty;

        var i: usize = 0;
        while (i + 1 < m.args.len) : (i += 2) {
            const pattern = m.args[i];
            // A pattern the parser could not read was reported where it was
            // written. It takes nothing, so it leaves the cover where it was
            // and makes no arm after it unreachable.
            const sound = if (self.ast.exprTag(pattern) == .err) blk: {
                _ = self.record(pattern, .poison);
                break :blk false;
            } else try self.checkPattern(pattern, scrutinee, m.callee);

            if (!sound) {
                if (self.ast.exprTag(pattern) != .err) poisoned = true;
            } else if (scrutinee != .poison) {
                const row = try coverage.arena.alloc(PatternCoverage.Cell, 1);
                row[0] = .{ .pattern = try self.coveragePattern(coverage.arena, pattern, scrutinee), .ty = scrutinee };
                try rows.append(coverage.arena, row);
                try row_patterns.append(coverage.arena, pattern);
            }

            if (try self.matchArmBody(id, &arms, pattern, m.args[i + 1], lends)) |body| {
                if (body == .poison) poisoned = true;
            }
        }

        // The arms still waiting: no arm settled a type, because the one that
        // names its own was poisoned or never completes, so they are checked
        // with nothing expected.
        try self.checkWaitingArms(id, &arms, lends);
        if (arms.poisoned) poisoned = true;

        // One pass answers both questions: which arms some value reaches, and
        // which values no arm takes. The second is reported only where the
        // arms themselves were sound: a pattern that named no variant leaves
        // the cover short as a consequence, and reporting that as well
        // describes one mistake twice.
        if (scrutinee != .poison) {
            // A refused refinement's values are unknown, and its declaration
            // is where that was said, so neither question has an answer to
            // report.
            var refused = false;
            const outcome: ?PatternCoverage.Outcome = coverage.check(rows.items, scrutinee) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                error.TooIntricate => null,
                error.Refused => blk: {
                    refused = true;
                    break :blk null;
                },
            };
            if (outcome) |o| {
                for (o.reached, row_patterns.items) |reached, pattern| {
                    if (reached) continue;
                    _ = self.report(.t_unreachable, pattern, "no value reaches this arm", .{}, "the arms before it take every value it would");
                    poisoned = true;
                }
                if (!poisoned and o.missing.len > 0) {
                    const missing = try self.witnessList(o.missing);
                    defer self.gpa.free(missing);
                    _ = if (missing.len == 0)
                        self.report(.t_cover, id, "this `match` does not cover every variant", .{}, "add the missing arms, or a `_`")
                    else
                        self.report(.t_cover, id, "this `match` does not cover {s}", .{missing}, "add the missing arms, or a `_`");
                    poisoned = true;
                }
            } else if (!refused) {
                self.reportTooIntricate(id);
                poisoned = true;
            }
        }

        if (poisoned) return self.record(id, .poison);
        var completes = false;
        var arm_index: usize = 1;
        while (arm_index < m.args.len) : (arm_index += 2) {
            completes = completes or self.completionReaches(m.args[arm_index]);
        }
        const answer: TypeId = if (!completes)
            .never
        else if (arms.settled) |s|
            s.ty
        else
            .unit;

        return self.expect(id, answer, expected);
    }

    /// The most values a [T-Cover] report names; past them it says there
    /// are more.
    const max_named_witnesses = 8;

    /// The values no arm takes, as patterns quoted and separated for a
    /// report. Empty where the one value untaken is anything at all, which
    /// names no variant.
    fn witnessList(self: *Checker, missing: []const PatternCoverage.Witness) std.mem.Allocator.Error![]u8 {
        var text: std.ArrayList(u8) = .empty;
        errdefer text.deinit(self.gpa);
        if (missing[0].isWild()) return text.toOwnedSlice(self.gpa);
        for (missing, 0..) |w, n| {
            if (n == max_named_witnesses) {
                try text.appendSlice(self.gpa, ", and more");
                break;
            }
            if (n > 0) try text.appendSlice(self.gpa, ", ");
            try text.append(self.gpa, '`');
            try self.witnessText(w, &text);
            try text.append(self.gpa, '`');
        }
        return text.toOwnedSlice(self.gpa);
    }

    fn reportTooIntricate(self: *Checker, id: ExprId) void {
        _ = self.report(
            .t_cover_limit,
            id,
            "this `match` is too intricate to check",
            .{},
            "split it into nested `match`es, each covering one part",
        );
    }

    test "an arm with a tuple pattern takes each component's type, and a mismatch is reported once" {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        for ([_]struct { statement: []const u8, errors: u32 }{
            .{ .statement = "let _r = match xs {\n        (_, _) => 1,\n    }", .errors = 1 },
            .{ .statement = "for (i, x) in xs {\n        total = total + i + x\n    }\n    match read total {\n        (a, _) => a,\n    }", .errors = 1 },
        }) |case| {
            try testing.expectEqual(case.errors, try errorsOfPairStatement(gpa, case.statement));
        }
    }

    /// What a `match`'s arms have settled so far, and the arms waiting for it.
    const MatchArms = struct {
        settled: ?Expected,
        /// Nothing is expected of the match and some arm's body names its
        /// type, so an arm whose body needs a type waits for that one rather
        /// than failing for want of it -- as the arms of an `if` do.
        can_wait: bool,
        /// Sized by this match's arms.
        waiting: std.ArrayList(WaitingArm) = .empty,
        /// Whether an arm checked after waiting was poisoned. Its report went
        /// out where it was checked; this carries the fact to the match.
        poisoned: bool = false,
    };

    const WaitingArm = struct { pattern: ExprId, body: ExprId };

    /// Whether some arm's body names its own type.
    fn someArmDeterminesItsOwnType(self: *const Checker, args: []const ExprId) bool {
        var at: usize = 1;
        while (at < args.len) : (at += 2) {
            if (self.determinesItsOwnType(self.resultOf(args[at]))) return true;
        }
        return false;
    }

    /// Checks one arm's body against what the arms settled so far, or sets it
    /// aside while nothing is settled, its body needs a type, and another arm
    /// names one. Null for an arm set aside.
    ///
    /// An arm that settles the type is followed at once by the arms set aside
    /// for it, before any arm written after it: an arm waits only as long as
    /// it must, so what is wrong in it is reported before what is wrong in
    /// the arms that follow.
    fn matchArmBody(self: *Checker, parent: ExprId, arms: *MatchArms, pattern: ExprId, body_expr: ExprId, lends: bool) std.mem.Allocator.Error!?TypeId {
        if (arms.can_wait and arms.settled == null and !self.determinesItsOwnType(self.resultOf(body_expr))) {
            try arms.waiting.append(self.gpa, .{ .pattern = pattern, .body = body_expr });
            return null;
        }
        const body = try self.checkMatchArmBody(parent, arms, pattern, body_expr, lends);
        if (arms.settled != null) try self.checkWaitingArms(parent, arms, lends);
        return body;
    }

    /// Checks the arms set aside, in the order they were written, against
    /// what the arms settled. An arm still waiting when the match ends is
    /// checked with nothing expected, which reports what it needed.
    fn checkWaitingArms(self: *Checker, parent: ExprId, arms: *MatchArms, lends: bool) std.mem.Allocator.Error!void {
        for (arms.waiting.items) |waiting| {
            const body = try self.checkMatchArmBody(parent, arms, waiting.pattern, waiting.body, lends);
            if (body == .poison) arms.poisoned = true;
        }
        arms.waiting.clearRetainingCapacity();
    }

    fn checkMatchArmBody(self: *Checker, parent: ExprId, arms: *MatchArms, pattern: ExprId, body_expr: ExprId, lends: bool) std.mem.Allocator.Error!TypeId {
        const lent = if (lends) try self.armLends(parent, pattern) else 0;
        const body = try self.checkResult(parent, body_expr, arms.settled);
        try self.armEnds(pattern, body_expr, lent);
        self.settleMatchArm(&arms.settled, body_expr, body);
        return body;
    }

    fn settleMatchArm(self: *Checker, settled: *?Expected, body_expr: ExprId, body: TypeId) void {
        if (body == .poison or body == .never) return;
        if (settled.*) |context| if (!context.unit_test_success) return;
        settled.* = .{ .ty = body, .at = self.locOf(self.resultOf(body_expr)), .reason = .arm };
    }

    /// A closed interval in the checker's own arithmetic: wide enough for
    /// `UInt64`'s maximum and `Int64`'s minimum together, which is why a
    /// range pattern normalises here rather than in the width of whatever
    /// type it matches.
    const Interval = usefulness.Interval;

    /// A literal or a range arm's interval, or `null` where a bound already
    /// reported what is wrong with it.
    fn intArmInterval(self: *Checker, pattern: ExprId, scrutinee: TypeId) std.mem.Allocator.Error!?Interval {
        if (self.ast.exprTag(pattern) != .range) {
            const v = try self.checkPatternBound(pattern, scrutinee) orelse return null;
            return .{ .lo = v, .hi = v };
        }
        const ends = self.ast.rangeEnds(pattern);
        const lo = try self.checkPatternBound(ends.lhs, scrutinee) orelse return null;
        const hi_written = try self.checkPatternBound(ends.rhs, scrutinee) orelse return null;
        const hi = if (self.ast.rangeInclusive(pattern)) hi_written else hi_written - 1;
        return .{ .lo = lo, .hi = hi };
    }

    /// A range pattern's bound, checked against the scrutinee's type and read
    /// through the fold table -- the same routine an array's length folds
    /// through, so a name that is not a constant expression is
    /// refused the one way it already is anywhere else.
    fn checkPatternBound(self: *Checker, end: ExprId, scrutinee: TypeId) std.mem.Allocator.Error!?i128 {
        const ty = try self.checkRangeEnd(end, .{ .ty = scrutinee, .at = self.locOf(end), .reason = .range_end });
        if (ty == .poison) return null;
        if (self.folds.get(end).valueOf()) |v| return v;
        _ = self.report(
            .t_const,
            end,
            "a pattern's bound must be a constant the compiler can work out",
            .{},
            "not a constant expression",
        );
        return null;
    }

    /// An integer type known only by its bounds: a parameter bounded by
    /// `Integer` or constrained to one. Its values have no fixed range, so
    /// nothing about them folds. An open integer literal is not one: its
    /// value is known and its type is only waiting to be settled.
    fn isSymbolicInteger(self: *const Checker, t: TypeId) bool {
        return t.bounds() == null and self.builder.get(t) != .open_integer and self.builder.isIntegerWithin(self.generic, t);
    }

    fn arithmeticHolds(self: *const Checker, t: TypeId) bool {
        return t == .poison or t == .f64 or self.builder.get(t) == .open_integer or self.builder.isIntegerWithin(self.generic, t);
    }

    /// Whether a type answers a trait the prelude declares, where the demand
    /// comes from the language rather than from a bound somebody wrote.
    ///
    /// A prelude publishing no such trait publishes no operation the operator
    /// could be a call on, so there is nothing to demand: a build with no
    /// library at all -- which is what the compiler's own harness compiles --
    /// keeps the comparison it always had, and lowering emits the instruction
    /// because there is no row to find. The same shape an interpolation's
    /// `Display` demand takes, for the same reason.
    fn answersTrait(
        self: *Checker,
        held: TypeId,
        trait: ?node.DeclId,
    ) std.mem.Allocator.Error!bool {
        const declared = trait orelse return true;
        if (try self.answersDeclared(held, declared)) return true;
        if (!try self.fallBackOpenParts(held, &.{})) return false;
        return self.answersDeclared(try self.builder.resolveOpen(held, &self.open_types), declared);
    }

    fn answersDeclared(self: *Checker, held: TypeId, declared: node.DeclId) std.mem.Allocator.Error!bool {
        try self.builder.prepareTraitLookupWithin(self.generic, declared, held);
        const pool = try self.builder.capabilityView();
        return self.reaching(&pool).answers(self.gpa, held, declared);
    }

    /// An implementation query no implementation answered while open
    /// integers stood in its types needs those types now, so each takes the
    /// default. Says whether anything fell back, which is when the query is
    /// worth asking again.
    fn fallBackOpenParts(self: *Checker, held: TypeId, args: []const TypeId) std.mem.Allocator.Error!bool {
        var any = try self.builder.mentionsOpen(held);
        for (args) |argument| any = any or try self.builder.mentionsOpen(argument);
        if (!any) return false;
        try self.forceLeaves(held, null);
        for (args) |argument| try self.forceLeaves(argument, null);
        return true;
    }

    /// Checks a conditional: a `Bool` condition and two arms that agree.
    ///
    /// A missing `else` is an arm of type Unit rather than an absent one, so
    /// `if c { log() }` is well formed because both arms are Unit and
    /// `let x = if c { 1 }` is not because they disagree. That framing needs no
    /// distinction between statement and expression position, which the
    /// language does not have.
    fn checkConditional(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const c = self.ast.conditional(id);

        const condition = try self.checkCondition(c.cond, id);

        // The expectation flows into both arms, so an annotated binding tells
        // each what it must be rather than leaving them to agree alone.
        //
        // With no expectation, the arm that determines its own type settles it
        // and the other is checked against what it settled -- which is what a
        // call already does across its arguments, and for the same reason. A
        // rule reading arms in the order they are written would accept
        // `if c { n } else { 1 }` and refuse `if c { 1 } else { n }`, making
        // the spelling decide a question about types. So the second arm goes
        // first where it is the one that knows and the first is waiting.
        // Read through the braces: an arm is a block and a block is its tail,
        // which is the expression that says what the arm is. `resultOf` is
        // what the reports below already use to name an arm's value, so the
        // question is asked about the same expression a reader is shown.
        // A lambda has a type of its own and converts to a function type
        // that flows into it, so a lambda arm beside a name takes its type
        // from the name, whichever is written first.
        const lambda_first = c.otherwise != ExprId.none and
            self.isLambda(self.resultOf(c.then)) and
            self.namesSomething(self.resultOf(c.otherwise));
        const settled_late = condition != .never and
            expected == null and
            c.otherwise != ExprId.none and
            (lambda_first or
                (!self.determinesItsOwnType(self.resultOf(c.then)) and
                    self.determinesItsOwnType(self.resultOf(c.otherwise))));

        if (settled_late) return self.checkArmsFromTheSecond(id, c);

        const then = try self.checkResult(id, c.then, expected);

        if (c.otherwise == ExprId.none) {
            if (condition == .never) return self.expect(id, .never, expected);
            // The absent arm is Unit, so the written one must be too.
            if (then != .poison and then != .unit and then != .never) {
                return self.reportWithOrigin(
                    .t_arms,
                    self.resultOf(c.then),
                    try std.fmt.allocPrint(self.gpa, "expected `()`, found `{s}`", .{(try self.typeName(then))}),
                    "this arm produces a value",
                    .{
                        .file = self.ast.fileOf(self.ast.exprMain(id)),
                        .span = self.ast.tokenSpan(self.ast.exprMain(id)),
                        .message = "an `if` with no `else` yields `()`",
                        .style = .secondary,
                    },
                );
            }
            return self.record(id, .unit);
        }

        const otherwise = try self.checkResult(id, c.otherwise, expected orelse Expected{
            .ty = then,
            .at = self.locOf(self.resultOf(c.then)),
            .reason = .arm,
        });

        if (then == .poison or otherwise == .poison) return self.record(id, .poison);
        if (condition == .never) return self.expect(id, .never, expected);

        const answer = try self.joinArms(then, otherwise, self.literalSite(id)) orelse {
            return self.reportWithOrigin(
                .t_arms,
                c.otherwise,
                try std.fmt.allocPrint(self.gpa, "expected `{s}`, found `{s}`", .{ (try self.typeName(then)), (try self.typeName(otherwise)) }),
                "the arms disagree",
                .{
                    .file = self.ast.fileOfExpr(c.then),
                    .span = self.ast.exprSpan(c.then),
                    .message = "this arm settled the type",
                    .style = .secondary,
                },
            );
        };

        return self.record(id, answer);
    }

    /// The arms of a branch where the second is the one that knows what it is.
    ///
    /// The same two checks the ordinary path runs, in the other order, so what
    /// settles the type is the arm that determines it rather than the arm that
    /// was written first. The disagreement is still reported against the arm
    /// that waited, and still points at the arm that settled -- a reader is
    /// told which one decided, and that is the one that could decide.
    fn checkArmsFromTheSecond(
        self: *Checker,
        id: ExprId,
        c: anytype,
    ) std.mem.Allocator.Error!TypeId {
        const otherwise = try self.checkResult(id, c.otherwise, null);

        const then = try self.checkResult(id, c.then, Expected{
            .ty = otherwise,
            .at = self.locOf(self.resultOf(c.otherwise)),
            .reason = .arm,
        });

        if (then == .poison or otherwise == .poison) return self.record(id, .poison);

        const answer = try self.joinArms(then, otherwise, self.literalSite(id)) orelse {
            return self.reportWithOrigin(
                .t_arms,
                c.then,
                try std.fmt.allocPrint(self.gpa, "expected `{s}`, found `{s}`", .{ (try self.typeName(otherwise)), (try self.typeName(then)) }),
                "the arms disagree",
                .{
                    .file = self.ast.fileOfExpr(c.otherwise),
                    .span = self.ast.exprSpan(c.otherwise),
                    .message = "this arm settled the type",
                    .style = .secondary,
                },
            );
        };

        return self.record(id, answer);
    }

    /// The value type of two alternatives that may not both complete.
    /// The type two arms agree on. Arms whose types were minted apart but
    /// hold the same open integers agree once those are met.
    fn joinArms(self: *Checker, first: TypeId, second: TypeId, at: open_types_mod.Site) std.mem.Allocator.Error!?TypeId {
        const a = try self.builder.resolveOpen(first, &self.open_types);
        const b = try self.builder.resolveOpen(second, &self.open_types);
        if (joinArmTypes(a, b)) |joined| return joined;
        if (!try self.meet(a, b, at)) return null;
        return try self.builder.resolveOpen(a, &self.open_types);
    }

    fn joinArmTypes(first: TypeId, second: TypeId) ?TypeId {
        if (first == second) return first;
        if (first == .never) return second;
        if (second == .never) return first;
        return null;
    }

    /// Checks a comparison, which yields `Bool` whatever its operands are.
    ///
    /// Nothing flows into the operands from outside: an expectation on the
    /// comparison is about the `Bool` it produces, not about what is being
    /// compared. The left operand settles the operand type and the right is
    /// checked against it, as for arithmetic.
    fn checkComparison(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const b = self.ast.binary(id);
        const tag = self.ast.exprTag(id);

        const checked_lhs = try self.check(b.lhs, null);
        const rhs = try self.check(b.rhs, if (checked_lhs == .never) null else Expected{
            .ty = checked_lhs,
            .at = .{ .file = self.ast.fileOfExpr(b.lhs), .span = self.ast.exprSpan(b.lhs) },
            .reason = .operand,
        });
        // The right operand may have settled an open left one.
        const lhs = try self.builder.resolveOpen(checked_lhs, &self.open_types);
        if (lhs == .poison or rhs == .poison) return self.record(id, .poison);
        if (lhs == .never or rhs == .never) return self.expect(id, .never, expected);

        // The operator is a call on the trait `std` declares for it, so the
        // operand type must implement that trait. `==` reaches `equals`; the
        // four orderings reach `less` and may reach `equals` beside it, which
        // is one demand rather than two because `Comparable` requires
        // `Equatable` and no type carries the one without the other.
        const orders = tag != .eq and tag != .ne;
        const needed = if (orders) self.comparable_decl else self.equatable_decl;
        if (!try self.answersTrait(lhs, needed)) {
            const file = self.ast.fileOfExpr(id);
            const span = self.ast.tokenSpan(self.ast.exprMain(id));
            const trait = needed orelse .none;
            const header_args = .{ (try self.typeName(lhs)), if (orders) "Comparable" else "Equatable" };
            if (operandHint(&self.builder, lhs)) |hint|
                try self.reportUnimplemented(file, span, hint, "`{s}` does not implement `{s}`", header_args, trait, &.{}, lhs)
            else
                try self.reportUnmet(file, span, unmet_operator_help, "`{s}` does not implement `{s}`", header_args, trait, &.{}, lhs);
            return self.record(id, .poison);
        }

        return self.expect(id, .bool_, expected);
    }

    fn checkBinary(self: *Checker, id: ExprId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        const b = self.ast.binary(id);

        // A surrounding numeric type settles both operands. A non-numeric
        // expectation belongs to the operation's result and is checked only
        // after both operands, so a divergent operand can make the operation
        // `Never` before a value-type mismatch is considered.
        const operand_expected = if (expected) |want|
            if (self.arithmeticHolds(want.ty)) want else null
        else
            null;
        const checked_lhs = try self.check(b.lhs, operand_expected);
        // The right operand is checked against the left's type when nothing
        // flowed in, which is what makes operands agree without promotion. An
        // open left operand is settled by that check where the right has a type.
        const rhs = try self.check(b.rhs, if (checked_lhs == .never) null else operand_expected orelse Expected{
            .ty = checked_lhs,
            .at = .{ .file = self.ast.fileOfExpr(b.lhs), .span = self.ast.exprSpan(b.lhs) },
            .reason = .operand,
        });
        const lhs = try self.builder.resolveOpen(checked_lhs, &self.open_types);

        // Disagreeing operands are already reported by the check above: the
        // right is checked against the left, so a mismatch is caught where it
        // is found and under the rule the expectation names. A second test
        // here could only fire where that check let a type through, which is
        // where the two would have disagreed about the language.
        if (lhs == .poison or rhs == .poison) {
            self.foldFailed(id, &.{ b.lhs, b.rhs });
            return self.record(id, .poison);
        }
        if (lhs == .never or rhs == .never) {
            self.foldFailed(id, &.{ b.lhs, b.rhs });
            return self.expect(id, .never, expected);
        }

        if (!self.arithmeticHolds(lhs)) {
            self.foldFailed(id, &.{ b.lhs, b.rhs });
            return self.reportAtOp(
                .t_operands,
                id,
                "`{s}` is not a number",
                .{(try self.typeName(lhs))},
                operandHint(&self.builder, lhs) orelse "arithmetic is defined over integers",
            );
        }

        if (self.ast.exprTag(id) == .rem and !remainderHoldsIn(lhs)) {
            self.foldFailed(id, &.{ b.lhs, b.rhs });
            return self.reportNoRemainder(id);
        }

        if (self.isSymbolicInteger(lhs)) {
            try self.markNotConstant(id);
            return self.expect(id, lhs, expected);
        }

        if (self.folds.get(b.lhs).valueOf()) |a| {
            if (self.folds.get(b.rhs).valueOf()) |c| {
                const result = constfold.arithmetic(self.ast.exprTag(id), a, c);

                if (result == null and c == 0) {
                    self.folds.set(id, .absent);
                    return self.reportAtOp(
                        .t_divide_by_zero,
                        id,
                        "division by zero",
                        .{},
                        "the right operand is zero",
                    );
                }

                // A remainder is what its division leaves, so where that
                // division has no representable quotient the remainder has no
                // value to be what is left over from -- and the hardware agrees,
                // faulting on exactly that pair. Reported here so the answer is
                // the one the program would get, rather than a zero the checker
                // believes and the processor refuses.
                // An open operand type has no range yet: the result and the
                // quotient are checked once it has one.
                const open_operand: ?u32 = switch (self.builder.get(lhs)) {
                    .open_integer => |v| v,
                    else => null,
                };
                if (open_operand) |v| if (result != null) {
                    try self.open_types.awaitRange(self.gpa, .{ .v = v, .expr = id, .value = result.?, .rule = .operation });
                    if (self.ast.exprTag(id) == .rem and c != 0)
                        try self.open_types.awaitRange(self.gpa, .{ .v = v, .expr = id, .value = @divTrunc(a, c), .rule = .operation });
                };

                const quotient_overflows = self.ast.exprTag(id) == .rem and
                    c != 0 and !self.builder.holds(lhs, @divTrunc(a, c));

                // Folding is carried in a type wider than any operand's, so a
                // result missing here with a divisor that is not zero is one
                // that left even that width -- which no operand type could
                // hold either, and is the overflow the operand type reports.
                if (result == null or quotient_overflows or !self.builder.holds(lhs, result.?)) {
                    self.folds.set(id, .absent);
                    return self.reportAtOp(
                        .t_overflow,
                        id,
                        "this operation overflows `{s}`",
                        .{(try self.typeName(lhs))},
                        "the result is not representable",
                    );
                }
                self.folds.set(id, .{ .value = result.? });
            } else self.foldFailed(id, &.{ b.lhs, b.rhs });
        } else self.foldFailed(id, &.{ b.lhs, b.rhs });

        return self.expect(id, lhs, expected);
    }

    /// Records a type and reports when it is not the one that flowed in.
    fn expect(self: *Checker, id: ExprId, actual: TypeId, expected: ?Expected) std.mem.Allocator.Error!TypeId {
        if (expected) |want| {
            if (want.inference != null or (want.unit_test_success and actual == .unit)) return self.record(id, actual);
            // Poison on either side is a region already reported. Comparing
            // against it would describe one mistake twice, once where it was
            // made and again at every place its value reaches.
            // Never supplies no value whose representation could disagree. It
            // satisfies a type already chosen by the surrounding position but
            // remains Never in the expression table, so it cannot choose an
            // open type during inference.
            if (want.ty != .poison and actual != .poison and actual != .never and actual != want.ty) {
                if (!try self.meet(actual, want.ty, self.literalSite(id))) {
                    // Named by what each side settled on, where it settled.
                    var settled_want = want;
                    settled_want.ty = try self.builder.resolveOpen(want.ty, &self.open_types);
                    const chosen: ?Label = switch (self.builder.get(actual)) {
                        .open_integer => |v| try self.chosenLabel(v),
                        else => switch (self.builder.get(want.ty)) {
                            .open_integer => |v| try self.chosenLabel(v),
                            else => null,
                        },
                    };
                    return self.reportMismatchChosen(id, try self.builder.resolveOpen(actual, &self.open_types), settled_want, "", chosen);
                }
                return self.record(id, try self.builder.resolveOpen(actual, &self.open_types));
            }
        }
        return self.record(id, actual);
    }
};

// Makes every test build compile the tests `Checker` holds, including a build
// filtered to one of them, which would otherwise never look inside it.
comptime {
    _ = Checker;
}

// These records contain slices and typed scalar handles, never owning pointers.
// A continuation arena owns the copied runs as one compilation lifetime.
fn copyRetained(gpa: std.mem.Allocator, value: anytype) std.mem.Allocator.Error!@TypeOf(value) {
    const T = @TypeOf(value);
    switch (@typeInfo(T)) {
        .pointer => |pointer| {
            if (pointer.size != .slice) @compileError("retained semantic records must not contain pointers");
            const result = try gpa.alloc(pointer.child, value.len);
            for (value, result) |item, *target| target.* = try copyRetained(gpa, item);
            return result;
        },
        .@"struct" => |record| {
            var result: T = undefined;
            inline for (record.fields) |field| @field(result, field.name) = try copyRetained(gpa, @field(value, field.name));
            return result;
        },
        .@"union" => {
            return switch (value) {
                inline else => |payload, tag| @unionInit(T, @tagName(tag), try copyRetained(gpa, payload)),
            };
        },
        .optional => return if (value) |item| try copyRetained(gpa, item) else null,
        else => return value,
    }
}

fn checkSourceInto(gpa: std.mem.Allocator, text: []const u8, sink: *Sink) !u32 {
    const source: Source = .{ .path = "t.lin", .text = text };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, sink);
    const res = try resolveTree(gpa, &ast, sink);
    const before = sink.error_count;
    var typing = try typecheckTree(gpa, &res, sink);
    _ = &typing;
    return sink.error_count - before;
}

/// Checks `text` and returns what the checker recorded, for a test that asks
/// about a side table rather than a diagnostic.
fn typingOf(gpa: std.mem.Allocator, text: []const u8, sink: *Sink) !types_mod.Typing {
    const source: Source = .{ .path = "t.lin", .text = text };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, sink);
    const res = try resolveTree(gpa, &ast, sink);
    return typecheckTree(gpa, &res, sink);
}

fn checkSource(gpa: std.mem.Allocator, text: []const u8) !u32 {
    var sink = Sink.init(gpa);
    return checkSourceInto(gpa, text, &sink);
}

/// What the checker recorded for `text` as a program whose prelude is its own
/// module, so a program declaring `Tuple2` itself is one whose tuple syntax
/// names that declaration.
fn typingAsPrelude(gpa: std.mem.Allocator, text: []const u8, sink: *Sink) !struct { ast: Ast, res: resolve_mod.ResolvedTree, typing: types_mod.Typing } {
    const source: Source = .{ .path = "t.lin", .text = text };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, sink);
    var res = try resolveTree(gpa, &ast, sink);
    res.resolution.prelude = res.expanded.declsOf(.from(0));
    res.resolution.tuple_decls = resolve_mod.tupleDeclsIn(&res.expanded.ast, res.resolution.prelude);
    const typing = try typecheckTree(gpa, &res, sink);
    return .{ .ast = ast, .res = res, .typing = typing };
}

const own_tuple2 =
    \\@copyable
    \\pub struct Tuple2[A, B] { _0: A, _1: B }
    \\
;

test "scalar snapshots reject only concretely authored scalar copies" {
    const rejected = [_][]const u8{
        \\fn main() -> UInt8 { let value: UInt8 = 7; copy(value) }
        ,
        \\fn main() -> UInt8 { let value = true; if copy(value) { 0 } else { 1 } }
        ,
        \\fn main() -> UInt8 { let value: Int64 = -7; let saved = copy(value); if saved == -7 { 0 } else { 1 } }
        ,
        \\fn main() -> UInt8 { let value: Float64 = 1.5; let saved = copy(value); if saved == 1.5 { 0 } else { 1 } }
        ,
        \\@copyable
        \\enum Flag { On, Off }
        \\fn main() -> UInt8 { let value: Flag = .On; match copy(value) { On => 0, Off => 1 } }
        ,
        \\fn duplicate[T: Copyable](value: T) -> T {
        \\    let number: UInt8 = 7
        \\    let _snapshot = copy(number)
        \\    copy(value)
        \\}
        \\fn main() -> UInt8 { duplicate(UInt8(0)) }
        ,
    };
    for (rejected) |source| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        var sink = Sink.init(arena.allocator());
        _ = try checkSourceInto(arena.allocator(), source, &sink);
        try testing.expectEqual(@as(u32, 1), sink.error_count);
        try testing.expectEqual(.o_scalar_copy, sink.items()[0].code.?);
    }

    const admitted = [_][]const u8{
        \\fn duplicate[T: Copyable](value: T) -> T { copy(value) }
        \\fn main() -> UInt8 { let value: UInt8 = 0; duplicate(value) }
        ,
        \\@copyable
        \\type Count = UInt8
        \\fn main() -> UInt8 { let value = Count(7); let saved = copy(value); if saved == value { 0 } else { 1 } }
        ,
        \\@copyable
        \\enum Flag { Present(()) }
        \\fn main() -> UInt8 { let value: Flag = .Present(()); match copy(value) { Present(_) => 0 } }
        ,
        \\@copyable
        \\struct Held { number: UInt8 }
        \\fn main() -> UInt8 { let value: Held = .{ number = 7 }; let saved = copy(value); saved.number - value.number }
        ,
    };
    for (admitted) |source| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        var sink = Sink.init(arena.allocator());
        _ = try checkSourceInto(arena.allocator(), source, &sink);
        try testing.expectEqual(@as(u32, 0), sink.error_count);
    }
}

test "affine capabilities separate copying from settlement" {
    const cases = [_]struct { source: []const u8, rejected_copy: bool = false }{
        .{ .source =
        \\struct Point { x: UInt8 }
        \\fn duplicate(point: Point) -> Point { copy(point) }
        \\fn main() -> UInt8 { let point: Point = .{ x = 1 }; let other = duplicate(point); other.x + point.x }
        , .rejected_copy = true },
        .{ .source =
        \\@linear
        \\struct Ticket { id: UInt8 }
        \\struct Wrapper { ticket: Ticket }
        \\fn main() -> UInt8 {
        \\    let wrapper: Wrapper = .{ ticket = .{ id = 7 } }
        \\    let Wrapper { ticket } = wrapper
        \\    let Ticket { id } = ticket
        \\    id
        \\}
        },
        .{ .source =
        \\@copyable
        \\struct Coordinate { x: UInt8 }
        \\fn duplicate(point: Coordinate) -> Coordinate { copy(point) }
        \\fn main() -> UInt8 { let point: Coordinate = .{ x = 1 }; let other = duplicate(point); other.x + point.x }
        },
        .{ .source =
        \\struct Point { x: UInt8 }
        \\fn discard[T: Discardable](sink _value: T) {}
        \\fn main() -> UInt8 { let point: Point = .{ x = 1 }; discard(point); 0 }
        },
        .{ .source =
        \\fn duplicate[T: Discardable](value: T) -> T { copy(value) }
        \\fn main() -> UInt8 { duplicate(UInt8(1)) }
        , .rejected_copy = true },
        .{ .source =
        \\@copyable
        \\enum Maybe[T] { None, Some(T) }
        \\struct Point { x: UInt8 }
        \\fn keep[T](sink value: Maybe[T]) -> Maybe[T] where carries(value) { value }
        \\fn main() -> UInt8 {
        \\    let item: Maybe[Point] = .Some(.{ x = 7 })
        \\    match keep(item) { None => 0, Some(point) => { let Point { x } = point; x } }
        \\}
        },
    };
    for (cases) |case| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        var sink = Sink.init(arena.allocator());
        _ = try checkSourceInto(arena.allocator(), case.source, &sink);
        if (case.rejected_copy) {
            var rejected = false;
            for (sink.items()) |diagnostic| if (diagnostic.code == .o_copy) {
                rejected = true;
            };
            try testing.expect(rejected);
        } else {
            for (sink.items()) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.message });
            try testing.expectEqual(@as(u32, 0), sink.error_count);
        }
    }
}

test "affine capabilities compose owned fields and associated obligations" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "capabilities.lin", .text =
        \\struct _Point { number: UInt8 }
        \\@copyable
        \\struct _Coordinate { number: UInt8 }
        \\@linear
        \\struct Ticket { number: UInt8 }
        \\struct _Wrapped { ticket: Ticket }
        \\@copyable
        \\struct View[T] { owner: borrow T }
        \\@copyable
        \\enum Maybe[T] { None, Some(T) }
        \\struct _Shapes {
        \\    observation: View[Ticket],
        \\    empty: [Ticket; 0],
        \\    one: [Ticket; 1],
        \\    optional: Maybe[Ticket],
        \\}
        \\trait Allocator { type Obligation }
        \\@copyable
        \\struct System {}
        \\@copyable
        \\struct ArenaHandle {}
        \\impl Allocator for System { type Obligation = Ticket }
        \\impl Allocator for ArenaHandle { type Obligation = () }
        \\struct Buffer[A: Allocator] { allocator: A, obligation: A.Obligation }
        \\struct _Buffers { system: Buffer[System], arena: Buffer[ArenaHandle] }
        \\fn main() -> UInt8 { 0 }
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const resolution = try resolveTree(gpa, &ast, &sink);
    const typing = try typecheckTree(gpa, &resolution, &sink);
    for (sink.items()) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.message });
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    var verified: usize = 0;
    for (typing.templates) |template| {
        const name = typing.nameOf(template.ty);
        if (std.mem.eql(u8, name, "_Point")) {
            try testing.expect(!typing.mayCopy(template.ty));
            try testing.expect(typing.mayDiscard(template.ty));
            verified += 1;
        } else if (std.mem.eql(u8, name, "_Coordinate")) {
            try testing.expect(typing.mayCopy(template.ty));
            verified += 1;
        } else if (std.mem.eql(u8, name, "_Wrapped")) {
            try testing.expect(typing.mustConsume(template.ty));
            verified += 1;
        } else if (std.mem.eql(u8, name, "_Shapes")) {
            try testing.expect(typing.mayCopy(typing.fieldType(template.ty, 0)));
            try testing.expect(typing.mayCopy(typing.fieldType(template.ty, 1)));
            try testing.expect(typing.mustConsume(typing.fieldType(template.ty, 2)));
            try testing.expect(typing.mustConsume(typing.fieldType(template.ty, 3)));
            verified += 1;
        } else if (std.mem.eql(u8, name, "_Buffers")) {
            try testing.expect(typing.mustConsume(typing.fieldType(template.ty, 0)));
            try testing.expect(typing.mayDiscard(typing.fieldType(template.ty, 1)));
            try testing.expect(!typing.mayCopy(typing.fieldType(template.ty, 1)));
            verified += 1;
        }
    }
    try testing.expectEqual(@as(usize, 5), verified);
}

