    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "receivers.lin", .text =
        \\struct Box[T] { value: T }
        \\trait Iterator { type Item }
        \\impl Iterator for UInt64 { type Item = UInt64 }
        \\trait Select { type Elem; proj at(inout self: Self) -> Elem where carries(self) }
        \\impl[T] Select for Box[T] {
        \\    type Elem = T
        \\    proj at(inout self: Self) -> T where carries(self) { self.value }
        \\}
        \\fn count[T](_box: Box[T]) -> UInt64 { 1 }
        \\impl[T] Box[T] {
        \\    trav positions(self: Self) = count(self)
        \\}
        \\fn main() -> UInt8 { 0 }
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var resolved = try resolveTree(gpa, &ast, &sink);
    resolved.resolution.prelude = resolved.expanded.declsOf(.from(0));
    const typing = try typecheckTree(gpa, &resolved, &sink);
    if (sink.error_count > 0) for (sink.items()) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.message });
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    var checked: usize = 0;
    for (0..ast.declCount()) |i| {
        const declaration = node.DeclId.at(@intCast(i));
        const kind = ast.declTag(declaration);
        if (kind != .projection and kind != .traversal_) continue;
        for (resolved.resolution.parametersOf(declaration)) |binding| {
            try testing.expect(typing.binding_types.get(binding) != .poison);
            checked += 1;
        }
    }
    try testing.expectEqual(@as(usize, 3), checked);
}

test "call recovery preserves mutation markers after an invalid receiver" {
    const prefix =
