        \\    var count: UInt8 = 0
        \\
    ;
    for ([_]struct { call: []const u8, errors: u32 }{
        .{ .call = "Inspect.inspect(box.missing, &count)", .errors = 1 },
        .{ .call = "Inspect.inspect(box.missing, &box.absent)", .errors = 2 },
    }) |case| {
