        _ = try checkSourceInto(gpa, source, &sink);
        if (sink.error_count != case.errors) for (sink.items()) |diagnostic| {
            std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.message });
        };
        try testing.expectEqual(case.errors, sink.error_count);
        for (sink.items()) |diagnostic| try testing.expectEqual(Code.t_unknown_field, diagnostic.code.?);
    }
}

fn diagnosticSays(sink: *const Sink, code: Code, needle: []const u8) bool {
    for (sink.items()) |diagnostic| {
        if (diagnostic.code != code) continue;
        if (std.mem.indexOf(u8, diagnostic.message, needle) != null) return true;
        for (diagnostic.labels) |label| {
            if (std.mem.indexOf(u8, label.message, needle) != null) return true;
        }
    }
    return false;
}

