        \\impl[A, B] Route[Tag[B]] for Pair[A, B] {}
        \\impl[A, B] Route[Other[B]] for Pair[A, B] {}
        \\impl[X, Y] Route[Tag[Y]] for Pair[X, Y] {}
        , .duplicates = 1 },
