        },
        .{ .declarations =
        \\trait Second[phantom Fixed, phantom A] {}
        \\impl[A, B] Second[UInt8, Other[B]] for Pair[A, B] {}
        \\impl[A, B] Second[UInt8, A] for Pair[A, B] {}
