        \\impl Route[Tag[UInt8]] for Pair[Tag[UInt8], Bool] {}
        \\impl[A, B] Route[A] for Pair[A, B] {}
        , .duplicates = 1 },
        .{ .declarations =
        \\trait Family { type Item }
        \\impl[A: Family, B] Route[A.Item] for Pair[A, B] {}
        \\impl[A: Family, B] Route[Tag[B]] for Pair[A, B] {}
        , .overlaps = 1 },
        .{ .declarations =
        \\impl[A, B] Route[fn(read item: A) -> A] for Pair[A, B] {}
        \\impl[A, B] Route[fn(read item: B) -> B] for Pair[A, B] {}
        , .overlaps = 1 },
        .{ .declarations =
        \\impl[A, B] Route[fn(read left: A) -> A] for Pair[A, B] {}
        \\impl[A, B] Route[fn(read right: B) -> B] for Pair[A, B] {}
        , .overlaps = 1 },
        .{ .declarations =
        \\impl[A, B] Route[fn(read left: A) -> A] for Pair[A, B] {}
        \\impl[A, B] Route[fn(sink right: B) -> B] for Pair[A, B] {}
        },
    };
    for (cases) |case| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        const text = try std.fmt.allocPrint(gpa, "{s}{s}\nfn main() -> UInt8 {{ 0 }}\n", .{ prelude, case.declarations });
        var sink = Sink.init(gpa);
        _ = try checkSourceInto(gpa, text, &sink);
        var duplicates: u32 = 0;
        var overlaps: u32 = 0;
        for (sink.items()) |diagnostic| {
            if (diagnostic.code == .n_duplicate) duplicates += 1;
            if (diagnostic.code == .t_impl) overlaps += 1;
        }
        try testing.expectEqual(case.duplicates, duplicates);
        try testing.expectEqual(case.overlaps, overlaps);
        try testing.expectEqual(case.duplicates + case.overlaps, sink.error_count);
    }
}

test "coherence overlap reports preserve prior declaration order across constructors" {
    const text =
        \\pub struct Pair[A, B] { first: A, second: B }
        \\struct Tag[T] { value: T }
        \\struct Other[T] { value: T }
        \\trait Route[phantom A] {}
        \\impl[A, B] Route[Other[B]] for Pair[A, B] {}
        \\impl[A, B] Route[Tag[B]] for Pair[A, B] {}
        \\impl[A, B] Route[A] for Pair[A, B] {}
        \\fn main() -> UInt8 { 0 }
    ;
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    _ = try checkSourceInto(gpa, text, &sink);
    try testing.expectEqual(@as(u32, 2), sink.error_count);
    const expected_prior = [_][]const u8{ "Route[Other[B]]", "Route[Tag[B]]" };
    const later = std.mem.indexOf(u8, text, "Route[A] for").?;
    for (sink.items(), expected_prior) |diagnostic, prior| {
        try testing.expectEqual(Code.t_impl, diagnostic.code.?);
        try testing.expectEqual(@as(usize, 2), diagnostic.labels.len);
        try testing.expectEqual(std.mem.indexOf(u8, text, prior).?, diagnostic.labels[0].span.start);
        try testing.expectEqual(later, diagnostic.labels[1].span.start);
    }
}

