test "component requirement suppression records generated bodies in traversal order" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const source: Source = .{ .path = "t.lin", .text =
        \\trait Measured {}
        \\trait Inspect {
        \\    fn first(self: Self) -> UInt8
        \\    fn second(self: Self) -> UInt8
        \\}
        \\template impl Inspect
        \\where reflect.components: Measured
        \\{
        \\    fn first(_self: Self) -> UInt8 { 0 }
        \\    fn second(_self: Self) -> UInt8 { 0 }
        \\}
        \\struct Box[T] { value: T }
        \\derive[T] Inspect for Box[T]
        \\fn main() -> UInt8 { 0 }
    };
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var resolved = try resolve_mod.resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &resolved, &sink);
    _ = &typing;

    var derive_errors: usize = 0;
    for (sink.items()) |diagnostic| {
        if (diagnostic.code == .t_derive) derive_errors += 1;
    }
    try testing.expectEqual(@as(usize, 1), derive_errors);
    try testing.expectEqual(@as(usize, 2), typing.suppressed_generated_bodies.len);

    var suppressed_at: usize = 0;
    for (resolved.expanded.modules, 0..) |_, module_index| {
        for (resolved.expanded.declsOf(ModuleId.from(module_index))) |declaration| {
            if (suppressed_at >= typing.suppressed_generated_bodies.len or
                typing.suppressed_generated_bodies[suppressed_at] != declaration) continue;
            try testing.expectEqual(node.Decl.Tag.function, resolved.expanded.ast.declTag(declaration));
            try testing.expect(resolved.expanded.originOf(declaration) != null);
            suppressed_at += 1;
        }
    }
    try testing.expectEqual(typing.suppressed_generated_bodies.len, suppressed_at);
}

