test "generated origin attributes standalone errors to the selected derive trait" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const text =
        \\trait Marker {}
        \\template impl Marker {}
        \\trait Structural {
        \\    fn value(self: Self) -> UInt8
        \\}
        \\template impl Structural {
        \\    fn value(_self: Self) -> UInt8 { true }
        \\}
        \\struct Mark {}
        \\derive (Marker, Structural) for Mark
        \\fn main() -> UInt8 { 0 }
    ;
    const source: Source = .{ .path = "t.lin", .text = text };
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var resolved = try resolveTree(gpa, &ast, &sink);
    try testing.expect(!sink.hasErrors());

    const first_diagnostic = sink.items().len;
    var typing = try typecheckTree(gpa, &resolved, &sink);
    try testing.expect(sink.items().len > first_diagnostic);

    var derive = DeclId.none;
    for (0..ast.declCount()) |i| {
        const decl = DeclId.at(@intCast(i));
        if (ast.declTag(decl) == .derive_impl) derive = decl;
    }
    try testing.expect(derive != .none);
    const trait_token = ast.deriveTraits(derive)[1].ref.name;
    const trait_span = ast.tokenSpan(trait_token);
    try testing.expectEqualStrings("Structural", text[trait_span.start..trait_span.end]);
    for (0..3) |collapse_count| {
        for (sink.items()[first_diagnostic..]) |diagnostic| {
            for (diagnostic.labels) |label| {
                try testing.expectEqual(FileId.from(0), label.file);
                try testing.expectEqual(trait_span, label.span);
            }
        }
        if (collapse_count < 2) try resolved.expanded.collapseGeneratedDiagnostics(&sink);
    }

    typing.deinit(gpa);
    resolved.deinit(gpa);
    ast.deinit(gpa);
    interner.deinit(gpa);
}

test "generated reflection diagnostics retain template origin" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const text =
        \\trait Sum { fn sum(self: Self) -> UInt8 }
        \\template impl Sum {
        \\    fn sum(_self: Self) -> UInt8 {
        \\        match read _self { reflect.case => {
        \\            var total: UInt8 = 0
        \\            for component in reflect.components {
        \\                total = total + component.of(_self)
        \\            }
        \\            total
        \\        } }
        \\    }
        \\}
        \\struct Parts { good: UInt8, bad: Bool }
        \\derive Sum for Parts
        \\fn main() -> UInt8 { 0 }
    ;
    const source: Source = .{ .path = "t.lin", .text = text };
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var resolved = try resolveTree(gpa, &ast, &sink);
    try testing.expect(!sink.hasErrors());

    var typing = try typecheckTree(gpa, &resolved, &sink);
    try testing.expect(sink.hasErrors());

    var derive = DeclId.none;
    var component_call = ExprId.none;
    for (0..ast.declCount()) |i| {
        const declaration = DeclId.at(@intCast(i));
        if (ast.declTag(declaration) == .derive_impl) derive = declaration;
    }
    for (0..ast.exprCount()) |i| {
        const expression = ExprId.at(@intCast(i));
        if (ast.exprTag(expression) != .call) continue;
        const callee = ast.call(expression).callee;
        if (ast.exprTag(callee) == .field and std.mem.eql(u8, ast.tokenText(ast.exprMain(callee)), "of")) {
            component_call = expression;
        }
    }
    try testing.expect(derive != .none and component_call != .none);
    const derive_span = ast.tokenSpan(ast.deriveTraits(derive)[0].ref.name);
    const component_span = ast.exprSpan(component_call);

    var found_primary = false;
    var found_component = false;
    for (sink.items()) |diagnostic| {
        for (diagnostic.labels) |label| {
            try testing.expectEqual(FileId.from(0), label.file);
            if (label.style == .primary and label.span.start == derive_span.start and label.span.end == derive_span.end) {
                found_primary = true;
            }
            if (label.style == .secondary and label.span.start == component_span.start and label.span.end == component_span.end and
                std.mem.indexOf(u8, label.message, "`Parts.bad`") != null)
            {
                found_component = true;
            }
        }
    }
    try testing.expect(found_primary);
    try testing.expect(found_component);

    const label_count = sink.items()[sink.items().len - 1].labels.len;
    try resolved.expanded.collapseGeneratedDiagnostics(&sink);
    try testing.expectEqual(label_count, sink.items()[sink.items().len - 1].labels.len);

    typing.deinit(gpa);
    resolved.deinit(gpa);
    ast.deinit(gpa);
    interner.deinit(gpa);
}

test "generated reflection diagnostics retain repeated body origins" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const text =
        \\trait Check { fn check(self: Self) -> UInt8 }
        \\template impl Check {
        \\    fn check(_self: Self) -> UInt8 {
        \\        match read _self { reflect.case => {
        \\            for component in reflect.components {
        \\                let _part = component.of(_self)
        \\                let _bad = true + false
        \\            }
        \\            0
        \\        } }
        \\    }
        \\}
        \\struct Pair { left: UInt8, right: UInt8 }
        \\derive Check for Pair
        \\fn main() -> UInt8 { 0 }
    ;
    const source: Source = .{ .path = "t.lin", .text = text };
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var resolved = try resolveTree(gpa, &ast, &sink);
    try testing.expect(!sink.hasErrors());

    var typing = try typecheckTree(gpa, &resolved, &sink);
    try testing.expect(sink.hasErrors());

    var loop_body = ExprId.none;
    for (0..ast.exprCount()) |i| {
        const expression = ExprId.at(@intCast(i));
        if (ast.exprTag(expression) == .for_) loop_body = ast.call(expression).args[1];
    }
    try testing.expect(loop_body != .none);
    const body_span = ast.exprSpan(loop_body);
    var components = [_]bool{ false, false };
    for (sink.items()) |diagnostic| {
        for (diagnostic.labels) |label| {
            if (label.style != .secondary or label.span.start != body_span.start or label.span.end != body_span.end) continue;
            for (&components, [_][]const u8{ "`Pair.left`", "`Pair.right`" }) |*found, expected| {
                if (std.mem.indexOf(u8, label.message, expected) != null) found.* = true;
            }
        }
    }
    try testing.expect(components[0] and components[1]);

    typing.deinit(gpa);
    resolved.deinit(gpa);
    ast.deinit(gpa);
    interner.deinit(gpa);
}

const resolveTree = resolve_mod.resolveTree;

fn expectOk(gpa: std.mem.Allocator, body: []const u8) !void {
    const text = try std.fmt.allocPrint(gpa, "fn main() -> UInt8 {{ {s} }}", .{body});
    try testing.expectEqual(@as(u32, 0), try checkSource(gpa, text));
}

fn expectErrors(gpa: std.mem.Allocator, body: []const u8, n: u32) !void {
    const text = try std.fmt.allocPrint(gpa, "fn main() -> UInt8 {{ {s} }}", .{body});
    try testing.expectEqual(n, try checkSource(gpa, text));
}

test "a trait signature's default is typed, not left poison" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    // A signature has no body, so the per-declaration walk that types a
    // default has to reach it before the walk bails out on that absence --
    // otherwise the default's expression keeps the `.poison` every
    // expression starts with, and nothing reported why.
    const text =
        \\trait Measure {
        \\    fn of(x: Self, width: UInt8 = 8) -> UInt8
        \\}
        \\
        \\struct Box {
        \\    n: UInt8,
        \\}
        \\
        \\impl Measure for Box {
        \\    fn of(x: Self, width: UInt8) -> UInt8 {
        \\        width + x.n
        \\    }
        \\}
        \\
        \\fn main() -> UInt8 {
        \\    let b: Box = .{ n = 1 }
        \\    Measure.of(b, 2)
        \\}
    ;

    const source: Source = .{ .path = "t.lin", .text = text };
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);
    _ = &typing;

    try testing.expectEqual(@as(u32, 0), sink.error_count);

    var default: ExprId = ExprId.none;
    for (0..ast.declCount()) |i| {
        const d = node.DeclId.at(@intCast(i));
        if (!ast.declIsSignature(d)) continue;
        for (ast.declParams(d)) |p| {
            if (p.default != ExprId.none) default = p.default;
        }
    }
    try testing.expect(default != ExprId.none);
    try testing.expect(typing.exprType(default) != .poison);
}

