test "poison passing through several operations reports once" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    // One undefined name, reported by the resolver. The grouping, the
    // multiplication and the addition each consume its poison and say nothing.
    try testing.expectEqual(@as(u32, 1), try checkSourceTotal(gpa, "fn main() -> UInt8 { (nope + 1) * 2 + 3 }"));

    // Each *use* of an undefined name is its own mistake, though.
    try testing.expectEqual(@as(u32, 3), try checkSourceTotal(gpa, "fn main() -> UInt8 { (nope + nope) * nope }"));
}

/// Counts every semantic diagnostic, not only the checker's, because which
/// pass finds a mistake is an implementation detail.
/// The diagnostics a program produces, so a test can inspect their labels
/// rather than only counting them.
fn secondaryLabel(diagnostic: *const Diagnostic) ?Label {
    for (diagnostic.labels) |label| {
        if (label.style == .secondary) return label;
    }
    return null;
}

fn diagnose(gpa: std.mem.Allocator, text: []const u8) !Sink {
    const source: Source = .{ .path = "t.lin", .text = text };
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);
    _ = &typing;
    return sink;
}

test "borrow static trait calls infer Self through owned arguments" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const text =
        \\@linear
        \\struct Packet[A] { allocator: A }
        \\trait Dispose { fn dispose(sink value: Packet[Self]) }
        \\struct Heap {}
        \\impl Dispose for Heap {
        \\    fn dispose(sink value: Packet[Heap]) { let Packet { allocator: _allocator } = value }
        \\}
        \\fn release[A: Dispose](sink packet: Packet[A]) { Dispose.dispose(packet) }
        \\fn main() -> UInt8 {
        \\    let heap: Heap = .{}
        \\    let packet: Packet[Heap] = .{ allocator = heap }
        \\    release(packet)
        \\    0
        \\}
    ;
    var sink = try diagnose(arena.allocator(), text);
    for (sink.items()) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.labels[0].message });
    try testing.expectEqual(@as(u32, 0), sink.error_count);
}

test "static trait Self reuses argument types for method generics" {
