    defer arena.deinit();
    const text =
        \\@linear
        \\struct Packet[T, A] { value: T, allocator: A }
        \\trait Dispose { fn dispose[T: Copyable](sink value: Packet[T, Self]) }
        \\struct Heap {}
        \\impl Dispose for Heap {
        \\    fn dispose[T: Copyable](sink value: Packet[T, Heap]) {
        \\        let Packet { value: item, allocator: _allocator } = value
        \\        let _taken = item
        \\    }
        \\}
        \\fn main() -> UInt8 {
        \\    let packet: Packet[UInt8, Heap] = .{ value = 7, allocator = .{} }
        \\    Dispose.dispose(packet)
        \\    0
        \\}
    ;
    var sink = try diagnose(arena.allocator(), text);
    for (sink.items()) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.labels[0].message });
    try testing.expectEqual(@as(u32, 0), sink.error_count);
}

test "static trait Self uses known arguments before contextual constructors" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const text =
        \\@linear
        \\struct Packet[A] { allocator: A }
        \\trait Use { fn run(sink packet: Packet[Self], owner: Self) -> UInt8 }
        \\struct Heap {}
        \\impl Use for Heap {
        \\    fn run(sink packet: Packet[Heap], owner: Heap) -> UInt8 {
        \\        let Packet { allocator: _allocator } = packet
        \\        match read owner { _ => 7 }
        \\    }
        \\}
        \\fn main() -> UInt8 {
        \\    let heap: Heap = .{}
        \\    Use.run(.{ allocator = .{} }, heap)
        \\}
    ;
    var sink = try diagnose(arena.allocator(), text);
    for (sink.items()) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.labels[0].message });
    try testing.expectEqual(@as(u32, 0), sink.error_count);
}

test "a settled-reference return does not settle Self through its result" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();

    const gpa = arena.allocator();
    const text =
        \\enum Maybe[T] { Some(T), None }
        \\struct Counter { at: UInt8 }
        \\trait Measure {
        \\    type Item
        \\    fn zero() -> Self.Item
        \\    fn none_of() -> Maybe[Self.Item]
        \\}
        \\impl Measure for Counter {
        \\    type Item = UInt8
        \\    fn zero() -> Self.Item { 0 }
        \\    fn none_of() -> Maybe[Self.Item] { .None }
        \\}
        \\fn main() -> UInt8 {
        \\    let z: UInt8 = Measure.zero()
        \\    let n: Maybe[UInt8] = Measure.none_of()
        \\    match n { None => z, Some(v) => v }
        \\}
    ;
    var diagnostics = try diagnose(gpa, text);
    var bound_count: usize = 0;
    for (diagnostics.items()) |d| {
        if (d.code == .t_bound) bound_count += 1;
        try testing.expect(d.code != .t_mismatch);
    }
    try testing.expectEqual(@as(usize, 2), bound_count);
}

test "a mismatch names the return type that required it" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();

    const text = "fn main() -> UInt8 {\n    let x: Int64 = 4;\n    x\n}\n";
    var sink = try diagnose(arena.allocator(), text);
    try testing.expectEqual(@as(usize, 1), sink.items().len);

    const d = sink.items()[0];
    try testing.expectEqual(@as(usize, 2), d.labels.len);

    // The secondary points at the `UInt8` in the signature, which is what a
    // reader has to change; the primary points at the expression.
    const secondary = secondaryLabel(&d).?;
    try testing.expectEqual(LabelStyle.secondary, secondary.style);
    try testing.expectEqualStrings("UInt8", secondary.span.slice(text));

    const primary = d.primaryLabel().?;
    try testing.expectEqual(LabelStyle.primary, primary.style);
    try testing.expectEqualStrings("x", primary.span.slice(text));
}

test "a mismatch names the annotation that required it" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();

    const text = "fn main() -> UInt8 {\n    let x: UInt8 = 1;\n    let y: Int64 = 2;\n    x + y\n}\n";
    var sink = try diagnose(arena.allocator(), text);
    try testing.expect(sink.items().len >= 1);

    const d = sink.items()[0];
    try testing.expectEqual(@as(usize, 2), d.labels.len);
    try testing.expect(std.mem.indexOf(u8, secondaryLabel(&d).?.message, "return type") != null);
}

test "a diagnostic with nothing to point at carries one label" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();

    // Too large for any representation at all, so no annotation, return type
    // or binding explains it -- the literal is simply unwritable. The rule is
    // "name a second location when one exists", not "always emit two".
    const huge = "9" ** 60;
    const text = try std.fmt.allocPrint(arena.allocator(), "fn main() -> UInt8 {{\n    {s}\n}}\n", .{huge});

    var sink = try diagnose(arena.allocator(), text);
    try testing.expect(sink.items().len >= 1);
    try testing.expectEqual(@as(usize, 1), sink.items()[0].labels.len);
}

test "local expected call results constrain waiting literals" {
    const prefix =
        \\struct Cell[T] { value: T }
        \\fn wrap[T](sink value: T) -> Cell[T] { .{ value = value } }
    ;
    const cases = [_]struct { source: []const u8, refused: bool }{
        .{ .source =
        \\fn main() -> UInt8 {
        \\    let cell: Cell[UInt8] = wrap(5)
        \\    cell.value
        \\}
        , .refused = false },
        .{ .source =
        \\fn main() -> UInt8 {
        \\    let cell = wrap(5)
        \\    let value: Int64 = cell.value
        \\    UInt8(value)
        \\}
        , .refused = false },
        .{ .source =
        \\fn main() -> UInt8 {
        \\    let value: UInt64 = 5
        \\    let cell: Cell[UInt8] = wrap(value)
        \\    cell.value
        \\}
        , .refused = true },
    };
    for (cases) |case| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const source = try std.mem.concat(arena.allocator(), u8, &.{ prefix, "\n", case.source });
        var sink = try diagnose(arena.allocator(), source);
        try testing.expectEqual(case.refused, sink.hasErrors());
    }
}

test "an out-of-range literal names what constrained it" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();

    const text = "fn main() -> UInt8 {\n    let x: UInt8 = 300;\n    x\n}\n";
    var sink = try diagnose(arena.allocator(), text);
    const d = sink.items()[0];
    try testing.expectEqual(@as(usize, 2), d.labels.len);
    try testing.expectEqualStrings("UInt8", secondaryLabel(&d).?.span.slice(text));
}

test "a failing conversion names where its value came from" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();

    const text = "fn main() -> UInt8 {\n    let x = 300;\n    UInt8(x)\n}\n";
    var sink = try diagnose(arena.allocator(), text);
    const d = sink.items()[0];
    try testing.expectEqual(@as(usize, 2), d.labels.len);

    // The secondary points at the initialiser, not at the name that used it.
    try testing.expectEqualStrings("300", secondaryLabel(&d).?.span.slice(text));
    try testing.expect(std.mem.indexOf(u8, secondaryLabel(&d).?.message, "comes from") != null);
}

fn checkSourceTotal(gpa: std.mem.Allocator, text: []const u8) !u32 {
    const source: Source = .{ .path = "t.lin", .text = text };
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const before = sink.error_count;
    const res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);
    _ = &typing;
    return sink.error_count - before;
}

