test "an assignment is Unit and takes the binding's type" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    try expectOk(gpa, "var x: UInt8 = 1; x = 2; x");
    // The value must have the binding's type.
    try expectErrors(gpa, "var x: UInt8 = 1; x = true; x", 1);
    // And the assignment itself yields nothing.
    try expectErrors(gpa, "var x: UInt8 = 1; let y: UInt8 = (x = 2); y", 1);
