test "a var is not a constant expression" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    // An immutable binding carries its initialiser's value, so the conversion
    // is settled where it is written.
    try expectErrors(gpa, "let x = 300; UInt8(x)", 1);
    // A `var` may be assigned again, so what it was initialised with is not
    // what it holds: the same conversion is checked where it runs.
    try expectOk(gpa, "var x: Int64 = 300; UInt8(x)");
}

