    try expectOk(gpa, "let x: UInt8 = loop { if true { break 1; } break 2; }; x");
    try expectErrors(gpa, "let x: UInt8 = loop { if true { break 1; } break true; }; x", 1);
}

test "a loop that never completes satisfies every expected type" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    // Used for its effect it is well formed: nothing after it runs.
    try expectOk(gpa, "loop { } 0");
    // Never supplies no value, so it is compatible with an expected type
    // without pretending to produce one.
    try expectOk(gpa, "let x: UInt8 = loop { }; x");
