test "Never does not settle an open generic parameter" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    try expectProgram(gpa,
        \\fn choose[T](sink value: T) -> T { value }
        \\fn main() -> UInt8 {
        \\    let _answer = choose(loop {})
        \\    0
        \\}
    , 1);
}

