test "a loop whose only exit is conditional types as its break site" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    // The no-value rule must not reject this: it has a break site.
    try expectOk(gpa, "let x: UInt8 = loop { if true { break 1; } }; x");
}

test "break leaves the nearest enclosing loop of either kind" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    // The inner break belongs to the while, so the loop still needs its own.
    try expectOk(gpa, "let x: UInt8 = loop { while true { break; } break 1; }; x");
    // A while is Unit whatever its body, so a break carrying a value out of
    // one is rejected without a rule written specially for it.
    try expectErrors(gpa, "while true { break 1; } 0", 1);
}

test "break and continue outside a loop are rejected" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
