    try expectErrors(gpa, "break; 0", 1);
    try expectErrors(gpa, "continue; 0", 1);
    try expectOk(gpa, "loop { continue; } 0");
}

/// A whole program rather than a body, for the cases that need more than one
/// declaration.
fn expectProgram(gpa: std.mem.Allocator, text: []const u8, n: u32) !void {
    try testing.expectEqual(n, try checkSource(gpa, text));
}

test "an argument takes the parameter's type" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
