test "normalised calls preserve every direct call spelling" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "normalised-calls.lin", .text =
        \\trait Pad {
        \\    fn pad(value: Self, width: UInt8 = 8) -> UInt8
        \\}
        \\impl Pad for UInt8 {
        \\    fn pad(value: UInt8, width: UInt8) -> UInt8 { value + width }
        \\}
        \\struct Holder[T] { value: T }
        \\impl[T] Holder[T] {
        \\    fn one(_holder: Self) -> UInt8 { 1 }
        \\}
        \\fn ordered(first: UInt8, second: UInt8, third: UInt8 = 3) -> UInt8 {
        \\    first + second + third
        \\}
        \\fn identity[T: Copyable](value: T) -> T { copy(value) }
        \\fn main() -> UInt8 {
        \\    let positional = ordered(1, 2, 3)
        \\    let named = ordered(second: 2, first: 1)
        \\    let defaulted = ordered(1, 2)
        \\    let postfix_value: UInt8 = 4
        \\    let postfix = postfix_value.pad()
        \\    let trait_value: UInt8 = 5
        \\    let trait_call = Pad.pad(trait_value)
        \\    let holder: Holder[UInt8] = .{ value = 6 }
        \\    let inherent = Holder.one(holder)
        \\    let generic_value: UInt8 = 7
        \\    let generic = identity(generic_value)
        \\    positional + named + defaulted + postfix + trait_call + inherent + generic
        \\}
    };

    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);

    var ordered_decl = node.DeclId.none;
    var pad_signature = node.DeclId.none;
    var one_decl = node.DeclId.none;
    var identity_decl = node.DeclId.none;
    for (0..ast.declCount()) |i| {
        const decl = node.DeclId.at(@intCast(i));
        const name = ast.tokenText(ast.declName(decl));
        if (std.mem.eql(u8, name, "ordered")) ordered_decl = decl;
        if (std.mem.eql(u8, name, "pad") and ast.declIsSignature(decl)) pad_signature = decl;
        if (std.mem.eql(u8, name, "one")) one_decl = decl;
        if (std.mem.eql(u8, name, "identity")) identity_decl = decl;
    }
    try testing.expect(ordered_decl != .none);
    try testing.expect(pad_signature != .none);
    try testing.expect(one_decl != .none);
    try testing.expect(identity_decl != .none);

    var positional = ExprId.none;
    var named = ExprId.none;
    var defaulted = ExprId.none;
    var postfix = ExprId.none;
    var trait_call = ExprId.none;
    var inherent = ExprId.none;
    var generic = ExprId.none;
    var call_count: u32 = 0;
    for (0..ast.exprCount()) |i| {
        const call = ExprId.at(@intCast(i));
        if (ast.exprTag(call) != .call) continue;
        call_count += 1;
        const c = ast.call(call);
        const name = ast.tokenText(ast.exprMain(c.callee));
        if (std.mem.eql(u8, name, "ordered")) {
            var has_name = false;
            for (ast.callNames(call)) |arg_name| if (arg_name != .none) {
                has_name = true;
            };
            if (has_name) {
                named = call;
            } else if (c.args.len == 3) {
                positional = call;
            } else {
                defaulted = call;
            }
        } else if (std.mem.eql(u8, name, "pad")) {
            if (res.resolution.targetOf(c.callee) == BindingId.none) postfix = call else trait_call = call;
        } else if (std.mem.eql(u8, name, "one")) {
            inherent = call;
        } else if (std.mem.eql(u8, name, "identity")) {
            generic = call;
        }
    }
    try testing.expectEqual(@as(u32, 7), call_count);

    const calls = &typing.call_index;
    try testing.expectEqual(@as(usize, 7), typing.calls.len);
    for ([_]ExprId{ positional, named, defaulted, postfix, trait_call, inherent, generic }) |call| {
        try testing.expect(call != .none);
        try testing.expect(calls.callOf(&typing, call) != null);
    }

    try testing.expectEqual(
        types_mod.CallTarget{ .declared = ordered_decl },
        calls.callOf(&typing, positional).?.target,
    );
    try testing.expectEqualSlices(ExprId, ast.call(positional).args, calls.callOf(&typing, positional).?.args);

    const named_written = ast.call(named).args;
    try testing.expectEqualSlices(
        ExprId,
        &.{ named_written[1], named_written[0], ExprId.none },
        calls.callOf(&typing, named).?.args,
    );
    try testing.expectEqualSlices(
        ExprId,
        &.{ ast.call(defaulted).args[0], ast.call(defaulted).args[1], ExprId.none },
        calls.callOf(&typing, defaulted).?.args,
    );

    for ([_]ExprId{ postfix, trait_call }) |call| {
        const normal = calls.callOf(&typing, call).?;
        try testing.expectEqual(types_mod.CallTarget{ .declared = pad_signature }, normal.target);
        try testing.expect(normal.selection.implementation != null);
        try testing.expect(normal.selection.implementation.?.ofATrait());
        try testing.expectEqual(@as(usize, 2), normal.args.len);
        try testing.expectEqual(ExprId.none, normal.args[1]);
        const signature = typing.get(normal.signature).callable;
        try testing.expectEqual(types_mod.CallableDefault{ .value = .{ .integer = 8 } }, typing.callableParams(signature)[1].default);
    }

    const inherent_call = calls.callOf(&typing, inherent).?;
    try testing.expectEqual(types_mod.CallTarget{ .declared = one_decl }, inherent_call.target);
    try testing.expect(inherent_call.selection.implementation != null);
    try testing.expect(!inherent_call.selection.implementation.?.ofATrait());
    try testing.expectEqualSlices(TypeId, &.{.u8}, inherent_call.selection.impl_args);
    const inherent_signature = typing.get(inherent_call.signature).callable;
    try testing.expectEqual(typing.exprType(ast.call(inherent).args[0]), typing.callableParams(inherent_signature)[0].ty);

    const generic_call = calls.callOf(&typing, generic).?;
    try testing.expectEqual(types_mod.CallTarget{ .declared = identity_decl }, generic_call.target);
    try testing.expectEqualSlices(TypeId, &.{.u8}, generic_call.selection.own_args);
    const generic_signature = typing.get(generic_call.signature).callable;
    try testing.expectEqual(TypeId.u8, typing.callableParams(generic_signature)[0].ty);
    try testing.expectEqual(TypeId.u8, generic_signature.result);

    for (typing.calls) |call| {
        const signature = typing.get(call.signature).callable;
        try testing.expectEqual(typing.exprType(call.at), signature.result);
    }
}

test "rejected calls are not normalised" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "rejected-calls.lin", .text =
        \\fn mutate(inout value: UInt8) { value = value + 1; }
        \\fn takes(_value: UInt8) {}
        \\fn main() -> UInt8 {
        \\    var value: UInt8 = 1
        \\    mutate(value)
        \\    takes(true)
        \\    value + later()
        \\}
        \\fn later(value: UInt8 = 1) -> UInt8 { value }
    };

    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 2), sink.error_count);

    const calls = &typing.call_index;
    var rejected: u32 = 0;
    var accepted = ExprId.none;
    for (0..ast.exprCount()) |i| {
        const call = ExprId.at(@intCast(i));
        if (ast.exprTag(call) != .call) continue;
        const name = ast.tokenText(ast.exprMain(ast.call(call).callee));
        if (std.mem.eql(u8, name, "later")) {
            accepted = call;
            continue;
        }
        if (!std.mem.eql(u8, name, "mutate") and !std.mem.eql(u8, name, "takes")) continue;
        rejected += 1;
        try testing.expectEqual(@as(?types_mod.NormalizedCall, null), calls.callOf(&typing, call));
    }
    try testing.expectEqual(@as(u32, 2), rejected);
    try testing.expect(accepted != .none);
    const normal = calls.callOf(&typing, accepted).?;
    const signature = typing.get(normal.signature).callable;
    try testing.expectEqual(types_mod.CallableDefault{ .value = .{ .integer = 1 } }, typing.callableParams(signature)[0].default);
}

test "conservative recurrence graph retains unknown and default suppliers" {
    const cases = [_][]const u8{
        \\trait Run { fn run(self: Self) -> UInt8 }
        \\@copyable
        \\struct Wrap[phantom T] {}
        \\default impl[T] Run for T {
        \\    fn run(_self: Self) -> UInt8 {
        \\        let next: Wrap[T] = .{}
        \\        Run.run(next)
        \\    }
        \\}
        \\fn main() -> UInt8 { Run.run(UInt8(0)) }
        ,
        \\trait Run { fn run(self: Self) -> UInt8 }
        \\@copyable
        \\struct Wrap[phantom T] {}
        \\fn invoke[T: Run](value: T) -> UInt8 { Run.run(value) }
        \\impl[T] Run for Wrap[T] {
        \\    fn run(_self: Self) -> UInt8 {
        \\        let next: Wrap[Wrap[T]] = .{}
        \\        invoke(next)
        \\    }
        \\}
        \\fn main() -> UInt8 { let first: Wrap[UInt8] = .{}; invoke(first) }
        ,
    };
    for (cases) |source| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        var sink = Sink.init(arena.allocator());
        try testing.expect(try checkSourceInto(arena.allocator(), source, &sink) > 0);
        for (sink.items()) |diagnostic| try testing.expectEqual(Code.t_poly_rec, diagnostic.code.?);
    }
}

test "nested growing calls are each diagnosed once" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "nested-growth.lin", .text =
        \\@copyable
        \\struct Wrap[T] { value: T }
        \\fn grow[T: Copyable](value: T, _n: UInt8) -> UInt8 {
        \\    let wrapped: Wrap[T] = .{ value = copy(value) }
        \\    grow(wrapped, grow(wrapped, 0))
        \\}
        \\fn main() -> UInt8 {
        \\    let value: UInt8 = 1
        \\    grow(value, 0)
        \\}
    };
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var resolved = try resolveTree(gpa, &ast, &sink);
    try testing.expect(!sink.hasErrors());
    _ = try typecheckTree(gpa, &resolved, &sink);

    try testing.expectEqual(@as(u32, 2), sink.error_count);
    var inner = false;
    var outer = false;
    for (sink.items()) |*diagnostic| {
        try testing.expectEqual(Code.t_poly_rec, diagnostic.code.?);
        const text = diagnostic.primaryLabel().?.span.slice(source.text);
        if (std.mem.eql(u8, text, "grow(wrapped, 0)")) {
            try testing.expect(!inner);
            inner = true;
        } else {
            try testing.expectEqualStrings("grow(wrapped, grow(wrapped, 0))", text);
            try testing.expect(!outer);
            outer = true;
        }
    }
    try testing.expect(inner and outer);
}

test "rejected calls retain their matched argument prefix" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "rejected-call-prefix.lin", .text =
        \\fn take(sink value: UInt8) {}
        \\fn main() -> UInt8 {
        \\    let a: UInt8 = 1
        \\    let b: UInt8 = 2
        \\    take(a, b)
        \\    b
        \\}
    };

    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);

    const calls = &typing.call_index;
    var call = ExprId.none;
    for (0..ast.exprCount()) |i| {
        const candidate = ExprId.at(@intCast(i));
        if (ast.exprTag(candidate) != .call) continue;
        if (std.mem.eql(u8, ast.tokenText(ast.exprMain(ast.call(candidate).callee)), "take")) call = candidate;
    }
    try testing.expect(call != .none);
    try testing.expectEqual(@as(?types_mod.NormalizedCall, null), calls.callOf(&typing, call));

    const recovered = calls.recoveredArgsOf(&typing, call);
