    try testing.expectEqual(ast.call(call).args[0], recovered[0].argument);
    try testing.expectEqual(@as(?u32, 0), recovered[0].parameter);
    try testing.expectEqual(node.Convention.sink, recovered[0].convention);
    try testing.expectEqual(ast.call(call).args[1], recovered[1].argument);
    try testing.expectEqual(@as(?u32, null), recovered[1].parameter);
    try testing.expectEqual(node.Convention.read, recovered[1].convention);
}

test "rejected callable value calls retain their target without arguments" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "rejected-call-target.lin", .text =
        \\fn identity(value: UInt8) -> UInt8 { value }
        \\fn choose() -> fn(read value: UInt8) -> UInt8 { identity }
        \\fn main() -> UInt8 { choose()() }
    };

    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);

    const calls = &typing.call_index;
    var rejected = ExprId.none;
    for (0..ast.exprCount()) |i| {
        const call = ExprId.at(@intCast(i));
        if (ast.exprTag(call) != .call or ast.call(call).args.len != 0) continue;
        if (ast.exprTag(ast.call(call).callee) == .call) rejected = call;
    }
