    const recovery = calls.recoveredCallOf(&typing, rejected).?;
    try testing.expectEqual(rejected, recovery.at);
    try testing.expectEqual(types_mod.CallTarget{ .indirect = ast.call(rejected).callee }, recovery.target);
}

test "position after a name preserves the matched prefix" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "position-after-name.lin", .text =
        \\fn add(a: UInt8, b: UInt8) -> UInt8 { a + b }
        \\fn main() -> UInt8 {
        \\    let _first = add(a: 2, 40)
        \\    add(b: 2, 40)
        \\}
    };

    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 2), sink.error_count);

    const calls = &typing.call_index;
    var found: u32 = 0;
    for (0..ast.exprCount()) |i| {
        const call = ExprId.at(@intCast(i));
        if (ast.exprTag(call) != .call) continue;
        if (!std.mem.eql(u8, ast.tokenText(ast.exprMain(ast.call(call).callee)), "add")) continue;

        const names = ast.callNames(call);
        const parameter: u32 = if (std.mem.eql(u8, ast.tokenText(names[0]), "a")) 0 else 1;
        const recovered = calls.recoveredArgsOf(&typing, call);
        try testing.expectEqual(@as(usize, 2), recovered.len);
        try testing.expectEqual(@as(?u32, parameter), recovered[0].parameter);
        try testing.expectEqual(ast.call(call).args[0], recovered[0].argument);
        try testing.expectEqual(@as(?u32, null), recovered[1].parameter);
        try testing.expectEqual(ast.call(call).args[1], recovered[1].argument);
        found += 1;
    }
    try testing.expectEqual(@as(u32, 2), found);
}

test "nested trait calls retain their own implementation selections" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "nested-trait-calls.lin", .text =
        \\struct Coins { count: UInt8 }
        \\struct Notes { count: UInt8 }
        \\trait Measure { fn of(x: Self) -> UInt8 }
        \\trait Wrap { fn into(n: Self) -> Coins }
        \\impl Measure for Coins {
        \\    fn of(x: Self) -> UInt8 { x.count }
        \\}
        \\impl Wrap for Notes {
        \\    fn into(n: Self) -> Coins { .{ count = n.count } }
        \\}
        \\fn main() -> UInt8 {
        \\    let n: Notes = .{ count = 3 }
        \\    Measure.of(Wrap.into(n))
        \\}
    };

    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    const typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);

    var found: u32 = 0;
    for (typing.calls) |call| switch (call.target) {
        .declared => |decl| {
            const name = ast.tokenText(ast.declName(decl));
            if (!std.mem.eql(u8, name, "of") and !std.mem.eql(u8, name, "into")) continue;
            const selected = call.selection.implementation.?;
            try testing.expectEqual(@as(u32, @intCast(call.at.index())), selected.call);
            const trait = node.DeclId.at(selected.trait);
            try testing.expectEqualStrings(
                if (std.mem.eql(u8, name, "of")) "Measure" else "Wrap",
                ast.tokenText(ast.declName(trait)),
            );
            found += 1;
        },
        else => {},
    };
    try testing.expectEqual(@as(u32, 2), found);
}

test "lambda defaults are folded into normalised holes" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "lambda-default.lin", .text =
        \\let fallback: UInt8 = 5
        \\fn main() -> UInt8 {
        \\    let read_fallback = |value: UInt8 = fallback| value
        \\    read_fallback()
        \\}
    };

    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    const typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);

    const calls = &typing.call_index;
    var found: ?types_mod.NormalizedCall = null;
    for (typing.calls) |call| switch (call.target) {
        .closure => found = calls.callOf(&typing, call.at),
        else => {},
    };
    const normal = found.?;
    try testing.expectEqualSlices(ExprId, &.{ExprId.none}, normal.args);
    const signature = typing.get(normal.signature).callable;
    try testing.expectEqual(
        types_mod.CallableDefault{ .value = .{ .integer = 5 } },
        typing.callableParams(signature)[0].default,
    );
}

