test "enum constant: a default keeps its variant and its parameter keeps the enum" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "enum-default.lin", .text =
        \\enum First { Preserve, Replace }
        \\enum Second { Preserve, Exact(UInt64) }
        \\let chosen: Second = .Preserve
        \\fn first(mode: First = .Preserve) -> UInt8 { match read mode { Preserve => 0, Replace => 1 } }
        \\fn second(mode: Second = chosen) -> UInt8 { match read mode { Preserve => 0, Exact(_) => 1 } }
        \\fn main() -> UInt8 { first() + second() }
    };

    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    const typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);

    var first = node.DeclId.none;
    var second = node.DeclId.none;
    for (0..ast.declCount()) |i| {
        const decl = node.DeclId.at(@intCast(i));
        const name = ast.tokenText(ast.declName(decl));
        if (std.mem.eql(u8, name, "first")) first = decl;
        if (std.mem.eql(u8, name, "second")) second = decl;
    }
    // A default's value is the variant it names; the parameter type keeps
    // the two enums apart, so the signatures differ though the values match.
    const first_default = typing.defaults.get(@intCast(first.index()), 0).?;
    const second_default = typing.defaults.get(@intCast(second.index()), 0).?;
    try testing.expect(first_default == .aggregate);
    try testing.expect(first_default.eql(second_default));

    const first_signature = typing.declSignature(first);
    const second_signature = typing.declSignature(second);
    try testing.expect(first_signature != second_signature);
    try testing.expectEqualStrings("fn(read First = .Preserve) -> UInt8", typing.nameOf(first_signature));
    try testing.expectEqualStrings("fn(read Second = .Preserve) -> UInt8", typing.nameOf(second_signature));
}

