}

test "a contextual lambda records one structural function value" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "function-value.lin", .text =
        \\fn main() -> UInt8 {
        \\    let increment: fn(read value: UInt8) -> UInt8 = |value| value + 1
        \\    increment(4)
        \\}
    };

    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    const typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    try testing.expectEqual(@as(usize, 1), typing.function_values.len);

    var lambda = ExprId.none;
    for (0..ast.exprCount()) |i| {
        const expr = ExprId.at(@intCast(i));
        if (ast.exprTag(expr) == .lambda) lambda = expr;
    }
    try testing.expect(lambda != .none);

    const closure = res.resolution.closures.closureOf(lambda);
    const value = typing.function_values[0];
    try testing.expectEqual(lambda, value.at);
    try testing.expectEqual(
        types_mod.FunctionTarget{ .closure = closure },
        value.target,
    );
    try testing.expectEqual(value.signature, typing.exprType(lambda));
    try testing.expect(typing.get(typing.exprType(lambda)) == .callable);
}

test "a generic function reference records one complete declared selection" {
