    var res = try resolveTree(gpa, &ast, &sink);
    const typing = try typecheckTree(gpa, &res, &sink);
    // The checker refuses the closure and leaves [O-Capture] to ownership,
    // which decides by position what the body does with the name.
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    try testing.expectEqual(@as(usize, 1), typing.closures.len);
    for (typing.closures) |closure| try testing.expectEqual(TypeId.poison, typing.exprType(closure.expr));
}

test "a parameter is immutable" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();

    // `read` is the default and behaves as a `let` does. `inout` is the
    // convention that changes this, and it arrives with mutation.
    //
    // Counted from before resolution: whether a name may be assigned is a rule
    // about the name, so the resolver reports it.
    try testing.expectEqual(@as(u32, 1), try checkSourceTotal(arena.allocator(),
        \\fn f(a: UInt8) -> UInt8 { a = 2; a }
        \\fn main() -> UInt8 { f(1) }
    ));
}

