test "a marked argument may not overlap another argument" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    // Two marked arguments naming one place.
    try testing.expect(0 < try checkSourceTotal(gpa,
        \\fn swap2(inout a: UInt8, inout b: UInt8) { a = b; }
        \\fn main() -> UInt8 { var x: UInt8 = 1; swap2(&x, &x); x }
    ));

    // And a marked argument overlapping one that is merely read: the callee
    // would observe its storage changing through an argument nobody marked.
    try testing.expect(0 < try checkSourceTotal(gpa,
        \\fn bump(inout a: UInt8, b: UInt8) { a = a + b; }
        \\fn main() -> UInt8 { var x: UInt8 = 1; bump(&x, x); x }
    ));

    // Distinct places are fine.
    try testing.expectEqual(@as(u32, 0), try checkSourceTotal(gpa,
        \\fn bump(inout a: UInt8, b: UInt8) { a = a + b; }
        \\fn main() -> UInt8 { var x: UInt8 = 1; var y: UInt8 = 2; bump(&x, y); x }
    ));
}

test "a mark inside an argument still counts against the call" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    // The mark is one level down, so a check that looked only at the top of
    // each argument found none and accepted this. What `pair` receives for
    // its second argument then depends on the order the two are evaluated in,
    // which is the one thing the rule exists to stop being observable.
    try testing.expect(0 < try checkSourceTotal(gpa,
        \\fn bump(inout n: UInt8) -> UInt8 { n = n + 1; 0 }
        \\fn pair(a: UInt8, b: UInt8) -> UInt8 { a + b }
        \\fn main() -> UInt8 { var x: UInt8 = 1; pair(bump(&x), x) }
    ));

    // Distinct places nested the same way are still fine.
    try testing.expectEqual(@as(u32, 0), try checkSourceTotal(gpa,
        \\fn bump(inout n: UInt8) -> UInt8 { n = n + 1; 0 }
        \\fn pair(a: UInt8, b: UInt8) -> UInt8 { a + b }
        \\fn main() -> UInt8 { var x: UInt8 = 1; var y: UInt8 = 2; pair(bump(&x), y) }
    ));
}

test "places under one root overlap by prefix, not by root" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    const decls =
        \\struct Inner { y: UInt8 }
        \\struct Outer { inner: Inner, z: UInt8 }
        \\fn bump(inout i: Inner, n: UInt8) -> UInt8 { i.y = 1; n }
        \\
    ;

    // Two paths under one root that select different fields name different
    // bytes, and neither can be reached through the other.
    try testing.expectEqual(@as(u32, 0), try checkSourceTotal(gpa, decls ++
        \\fn main() -> UInt8 {
        \\    var o: Outer = .{ inner = .{ y = 1 }, z = 2 };
        \\    bump(&o.inner, o.z)
        \\}
    ));

    // One path a prefix of the other: writing through `o.inner` is what
    // `o.inner.y` reads.
    try testing.expect(0 < try checkSourceTotal(gpa, decls ++
        \\fn main() -> UInt8 {
        \\    var o: Outer = .{ inner = .{ y = 1 }, z = 2 };
        \\    bump(&o.inner, o.inner.y)
        \\}
    ));

    // The bare root is a prefix of every path under it, in both directions.
    try testing.expect(0 < try checkSourceTotal(gpa, decls ++
        \\fn takes(inout o: Outer, n: UInt8) -> UInt8 { o.z = 1; n }
        \\fn main() -> UInt8 {
        \\    var o: Outer = .{ inner = .{ y = 1 }, z = 2 };
        \\    takes(&o, o.inner.y)
        \\}
    ));
    try testing.expect(0 < try checkSourceTotal(gpa, decls ++
        \\fn main() -> UInt8 {
        \\    var o: Outer = .{ inner = .{ y = 1 }, z = 2 };
        \\    bump(&o.inner, copy(o).z)
        \\}
    ));
}

test "parentheses do not change which places overlap" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    const decls =
        \\struct Inner { y: UInt8 }
        \\struct Outer { inner: Inner, z: UInt8 }
        \\fn f(inout n: UInt8, i: Inner) -> UInt8 { n = 1; i.y }
        \\
    ;

    // The marked place itself parenthesised, which is the only shape that
    // reaches the comparison with a group still on the outside: everywhere
    // else the walk strips one on the way in.
    try testing.expect(0 < try checkSourceTotal(gpa, decls ++
        \\fn main() -> UInt8 {
        \\    var o: Outer = .{ inner = .{ y = 1 }, z = 2 };
        \\    f(&(o.inner.y), o.inner) + o.z
        \\}
    ));
    try testing.expectEqual(@as(u32, 0), try checkSourceTotal(gpa, decls ++
        \\fn main() -> UInt8 {
        \\    var o: Outer = .{ inner = .{ y = 1 }, z = 2 };
        \\    f(&(o.z), o.inner) + o.inner.y
        \\}
    ));

    // `(o).inner` is the place `o.inner` is, and it does not overlap `o.z`.
    // A comparison that stopped at the parenthesis found the bare `o` inside
    // and reported every place under it.
    try testing.expectEqual(@as(u32, 0), try checkSourceTotal(gpa, decls ++
        \\fn main() -> UInt8 {
        \\    var o: Outer = .{ inner = .{ y = 1 }, z = 2 };
        \\    f(&o.z, (o).inner) + o.z
        \\}
    ));

    // And it still overlaps what it should.
    try testing.expect(0 < try checkSourceTotal(gpa, decls ++
        \\fn main() -> UInt8 {
        \\    var o: Outer = .{ inner = .{ y = 1 }, z = 2 };
        \\    f(&o.inner.y, (o).inner) + o.z
        \\}
    ));
}

test "a marked argument may be a path into a binding" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    // The argument's type is the field's, not the root's.
