test "an empty struct pattern takes an empty product apart" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();

    try expectProgram(gpa,
        \\struct Empty {}
        \\fn main(value: Empty) -> UInt8 { match value { Empty {} => 7 } }
    , 0);

    try expectProgram(gpa,
        \\struct Empty {}
        \\fn main(value: Empty) -> UInt8 { let Empty {} = value; 7 }
    , 0);

    try expectProgram(gpa,
        \\struct NonEmpty { value: UInt8 }
        \\fn main(value: NonEmpty) -> UInt8 { match value { NonEmpty {} => 7 } }
    , 1);

    try expectProgram(gpa,
        \\type Meters = UInt8
        \\fn main(value: Meters) -> UInt8 { match value { Meters {} => 7 } }
    , 1);

    try expectProgram(gpa,
        \\enum Pick { First, Second }
        \\fn main(value: Pick) -> UInt8 { match value { Pick {} => 7 } }
    , 1);
}

test "an empty match completes only an uninhabited enum" {
