    const pair = "struct Pair[A, B] { first: A, second: B }\n";
    for ([_][]const u8{
        try std.mem.concat(gpa, u8, &.{ wrapper, pair }),
        try std.mem.concat(gpa, u8, &.{ pair, wrapper }),
    }) |declarations| {
        try expectProgram(gpa, try std.mem.concat(gpa, u8, &.{
            declarations,
            "fn main() -> UInt8 { let value: Wrap[UInt8] = .{ pair = .{ first = 3, second = 4 } }; value.pair.first }\n",
        }), 0);
        try expectProgram(gpa, try std.mem.concat(gpa, u8, &.{
            declarations,
            "struct Cycle[T] { value: Wrap[Cycle[T]] }\nfn main() -> UInt8 { 0 }\n",
        }), 1);
    }
}

