test "diagnostic detail: dense layout cycles are all broken before layout" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var source: std.ArrayList(u8) = .empty;
    const count = 12;
    for (0..count) |i| {
        try source.appendSlice(gpa, try std.fmt.allocPrint(gpa, "struct T{d} {{\n", .{i}));
        for (0..count) |j| {
            if (i == j) continue;
            try source.appendSlice(gpa, try std.fmt.allocPrint(gpa, "f{d}: T{d},\n", .{ j, j }));
        }
        try source.appendSlice(gpa, "}\n");
    }
    try source.appendSlice(gpa, "fn main() -> UInt8 { 0 }\n");
    var sink = Sink.init(gpa);
    try testing.expect(try checkSourceInto(gpa, source.items, &sink) > 0);
    for (sink.items()) |diagnostic| try testing.expectEqual(Code.t_infinite_layout, diagnostic.code);
}

