fn typecheckOnly(gpa: std.mem.Allocator, ctx: struct {
    resolved: *const resolve_mod.ResolvedTree,
}) !void {
    var arena = std.heap.ArenaAllocator.init(gpa);
    defer arena.deinit();
    var sink = Sink.init(arena.allocator());
    var typing = try typecheckTree(gpa, ctx.resolved, &sink);
    typing.deinit(gpa);
}

test "postfix checking and finalization release allocations on failure" {
    const gpa = testing.allocator;
    const source: Source = .{ .path = "postfix.lin", .text =
        \\struct Coins { count: UInt8 }
        \\trait Measure { fn of(x: Self) -> UInt8 }
        \\impl Measure for Coins {
        \\    fn of(x: Self) -> UInt8 { x.count }
        \\}
        \\fn main() -> UInt8 {
        \\    let coins: Coins = .{ count = 1 }
        \\    coins.of()
        \\}
    };
    var arena = std.heap.ArenaAllocator.init(gpa);
    defer arena.deinit();
    var sink = Sink.init(arena.allocator());
    var interner: Interner = .empty;
    defer interner.deinit(gpa);
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    defer ast.deinit(gpa);
    var res = try resolveTree(gpa, &ast, &sink);
    defer res.deinit(gpa);
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    var typing = try typecheckTree(gpa, &res, &sink);
    defer typing.deinit(gpa);
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    try testing.expectEqual(@as(usize, 1), typing.postfix.len);
    try testing.expect(typing.call_index.callOf(&typing, ExprId.at(typing.postfix[0].call)) != null);
    try testing.checkAllAllocationFailures(gpa, typecheckOnly, .{.{ .resolved = &res }});
}

test "checking that fails part-way gives back what it took" {
    // Every other test here asks what checking owns when it succeeds. The
    // checker allocates five tables before it exists and several more while it
    // runs, and a failure at any one of them leaves the ones before it holding
    // memory nobody owns -- invisible to a test that never fails an
    // allocation. Source broad enough to reach the tables the pass only builds
    // when the program needs them.
    const gpa = testing.allocator;
    const source: Source = .{ .path = "t.lin", .text =
        \\struct Cell[T] {
        \\    v: T,
        \\}
        \\
        \\enum Side {
        \\    Left(UInt8),
        \\    Right,
        \\}
        \\
        \\struct Coins {
        \\    count: UInt8,
        \\}
        \\
        \\trait Measure {
        \\    fn of(x: Self) -> UInt8
        \\}
        \\
        \\impl Measure for Coins {
        \\    fn of(x: Self) -> UInt8 {
        \\        x.count
        \\    }
        \\}
        \\
        \\fn wrap[T: Copyable](x: T) -> Cell[T] {
        \\    .{ v = copy(x) }
        \\}
        \\
        \\fn main() -> UInt8 {
        \\    let a: UInt8 = 1
        \\    let c = wrap(a)
        \\    let coins: Coins = .{ count = 1 }
        \\    var total: UInt8 = Measure.of(coins)
        \\    var i: UInt8 = 0
        \\    while i < 4 {
        \\        total = total + c.v
        \\        i = i + 1
        \\    }
        \\    let s: Side = Side.Left(2)
        \\    match s {
        \\        Left(n) => total + n,
        \\        Right => total,
        \\    }
        \\}
    };

    var arena = std.heap.ArenaAllocator.init(gpa);
    defer arena.deinit();
    var sink = Sink.init(arena.allocator());
    var interner: Interner = .empty;
    defer interner.deinit(gpa);

    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    defer ast.deinit(gpa);
    var res = try resolveTree(gpa, &ast, &sink);
    defer res.deinit(gpa);
    try testing.expectEqual(@as(u32, 0), sink.error_count);

    try testing.checkAllAllocationFailures(gpa, typecheckOnly, .{.{
        .resolved = &res,
    }});
}

test "an implementation the compiler provides names no declaration to call" {
    const gpa = testing.allocator;

    const impls = [_]types_mod.Implementation{.{
        .trait = 0,
        .head = .{ .whole = .u8 },
        .ty = .u8,
        .decl = .none,
        .ambient = true,
    }};
    var index = try types_mod.ImplIndex.build(gpa, &impls);
    defer index.deinit(gpa);
    var pool = try Typing.Builder.init(gpa);
    defer pool.deinit();
    pool.implementations = &impls;
    pool.impl_index = index;
    const trait = node.DeclId.at(0);

    // The row is found, so the implementation exists: what a bound asks is
    // answered yes. The declaration is not, because there is none -- and a
    // caller handed one would index the tree by a number no declaration has.
    try testing.expect(try index.any(gpa, &impls, &pool, trait.index(), .u8, .none, .forward));
    try testing.expect((try pool.implementationRow(trait, &.{}, .u8)).?.isAmbient());
}

test "typed storage intrinsics reject a scalar replacement signature" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "slots.lin", .text =
        \\extern fn slot_stride(shape: UInt64) -> UInt64
        \\fn main() -> UInt8 { let _width = slot_stride(0); 0 }
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var resolved = try resolveTree(gpa, &ast, &sink);
    resolved.modules[0].name = "mem";
    resolved.modules[0].library = true;
    resolved.modules[0].externs = true;
