        \\fn main() -> UInt8 {
        \\    let owner: Resource = .{ number = 7 }
        \\    let view = duplicate(observe(owner))
        \\    let result = view.owner.number
        \\    let Resource { number: _ } = owner
        \\    result
        \\}
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(arena.allocator(), &source, .from(0), &sink, &interner);
    var ast = try parse(arena.allocator(), &source, .from(0), tokens, &sink);
    const resolved = try resolveTree(arena.allocator(), &ast, &sink);
    const typing = try typecheckTree(arena.allocator(), &resolved, &sink);
    for (sink.list.items) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.message });
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    for (typing.instances) |inst| {
        if (typing.get(inst.ty) == .struct_) {
            const structure = typing.get(inst.ty).struct_;
            if (structure.field_count == 1 and typing.get(typing.fields.items(.ty)[structure.first_field]) == .borrow)
                try testing.expect(typing.mayCopy(inst.ty));
        }
    }
}

