test "borrow explicit observational implementations retain their receiver ABI" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    const source: Source = .{ .path = "observation-impl.lin", .text =
        \\trait Number { fn number(self: Self) -> UInt8 }
        \\impl Number for UInt8 { fn number(self: Self) -> UInt8 { self } }
        \\impl Number for borrow UInt8 { fn number(_self: Self) -> UInt8 { 9 } }
        \\fn main() -> UInt8 { let value: UInt8 = 3; let observed = borrow value; Number.number(borrow observed) + Number.number(observed) }
    };
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    const resolved = try resolveTree(gpa, &ast, &sink);
    const typing = try typecheckTree(gpa, &resolved, &sink);
    for (sink.list.items) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.message });
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    var found = false;
    var choices = typing.implementation_selections.rows.iterator();
    while (choices.next()) |entry| {
        if (typing.get(entry.key_ptr.receiver) != .borrow) continue;
        found = true;
        const referent = typing.get(entry.key_ptr.receiver).borrow.referent;
        const expected = if (typing.get(referent) == .borrow) referent else entry.key_ptr.receiver;
        try testing.expectEqual(expected, entry.value_ptr.*.?.receiver);
    }
    try testing.expect(found);
}

