test "joint closure callable bounds substitute implementation signature types" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    const source: Source = .{ .path = "closure-key.lin", .text =
        \\trait Run[T] { fn run(sink job: Self) -> T }
        \\struct Job[T, F] { value: T, work: F }
        \\impl[T: Integer, F: fn() -> T] Run[T] for Job[T, F] {
        \\    fn run(sink job: Self) -> T {
        \\        let Job { value: _value, work } = job
        \\        work()
        \\    }
        \\}
        \\fn pack[T: Integer, F](value: T, sink work: F) -> Job[T, F] where carries(work) {
        \\    .{ value = copy(value), work = work }
        \\}
        \\struct Holder[S] { value: S }
        \\impl[S: Integer] Holder[S] {
        \\    fn run(self: Self) -> S { Run.run(pack(self.value, || S.max)) }
        \\}
        \\fn main() -> UInt8 { let holder: Holder[UInt8] = .{ value = 0 }; holder.run() }
    };
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    var ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var res = try resolveTree(gpa, &ast, &sink);
    var typing = try typecheckTree(gpa, &res, &sink);
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    var builder = try Typing.Builder.reopen(gpa, &typing);
    defer builder.deinit();
    var reached = false;
    for (typing.calls) |call| {
        const selected = call.selection.implementation orelse continue;
        if (!selected.ofATrait() or selected.args.len != 1) continue;
        const argument = typing.get(selected.args[0]);
        if (argument != .parameter) continue;
        const owner = argument.parameter.owner;
        const receiver = try builder.substitute(selected.self_ty, owner, &.{.u8});
        const trait_argument = try builder.substitute(selected.args[0], owner, &.{.u8});
        const choice = try builder.implementationChoice(node.DeclId.at(selected.trait), &.{trait_argument}, receiver);
        try testing.expect(choice != null);
        reached = true;
    }
    try testing.expect(reached);
}

