        if (call.target != .closure_recovery) continue;
        found = true;
        const signature = typing.get(call.signature).callable;
        const receiver = typing.get(typing.exprType(call.args[0])).closure;
        try testing.expectEqual(receiver.environment, signature.result);
        try testing.expectEqual(node.Convention.sink, typing.callableParams(signature)[0].convention);
