        \\fn main() -> UInt8 {
        \\    let first: UInt8 = 1
        \\    let saved = borrow first
        \\    let _callback = inout [saved] |value: borrow UInt8| -> where retains(saved: value) { let _input = copy(value); let _saved = copy(saved) }
        \\    0
        \\}
        , .message = "retention requires an inout destination" },
        .{ .source =
        \\fn main() -> UInt8 {
        \\    let first: UInt8 = 1
        \\    let _callback = [sink saved = borrow first] |value: borrow UInt8| -> where retains(saved: value) { let _input = copy(value); let _saved = copy(saved) }
        \\    0
        \\}
        , .message = "retention requires an inout destination" },
        .{ .source =
        \\fn main() -> UInt8 {
        \\    let first: UInt8 = 1
        \\    let _callback = sink [sink saved = borrow first] |value: borrow UInt8| -> where retains(saved: value) { let _input = copy(value); let _saved = copy(saved) }
        \\    0
        \\}
        , .message = "retention requires an inout destination" },
        .{ .source =
        \\fn main() -> UInt8 {
        \\    let first: UInt8 = 1
        \\    let _callback = inout [sink saved = borrow first] |value: borrow UInt8| -> where retains(missing: value) { let _input = copy(value); let _saved = copy(saved) }
        \\    0
        \\}
        , .message = "a contract path must name a declared source" },
        .{ .source =
        \\fn accept[F: inout fn(value: borrow UInt8)](sink _callback: F) {}
        \\fn main() -> UInt8 {
        \\    let first: UInt8 = 1
        \\    accept(inout [sink saved = borrow first] |value| -> where retains(saved: value) { saved = copy(value) })
        \\    0
        \\}
        , .message = "this closure's effects exceed the callable requirement" },
