test "checked library prefix retains nominal and parameter identities" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const gpa = arena.allocator();
    var sink = Sink.init(gpa);
    var interner: Interner = .empty;
    const source: Source = .{ .path = "std/value.lin", .text =
        \\pub struct Box[T] { value: T }
        \\pub fn identity[T](sink value: T) -> T { value }
        \\pub trait Measure { fn measure(self: Self) -> UInt8 }
    };
    const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
    const ast = try parse(gpa, &source, .from(0), tokens, &sink);
    var modules = [_]program_mod.Module{.{
        .name = "std",
        .dir = "std",
        .files = &.{.from(0)},
        .decls = .{ .start = 0, .end = ast.declCount() },
        .imports = &.{},
        .library = true,
        .externs = true,
    }};
    const program: Program = .{ .ast = ast, .modules = &modules, .kind = .library };
    const resolved = try resolve_mod.resolve(gpa, &program, &interner, &sink, .program);
    var prefix = try typecheckLibraryPrefix(testing.allocator, &resolved.expanded, &resolved.resolution, &sink);
    defer prefix.deinit();
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    try testing.expectEqual(prefix.typing.templates[0].ty, prefix.seed.declared_types[0]);
    for (prefix.seed.parameters, 0..) |parameters, owner| {
        for (parameters, 0..) |held, index| {
            const parameter = prefix.typing.get(held).parameter;
            try testing.expectEqual(owner, parameter.owner);
            try testing.expectEqual(index, parameter.index);
        }
    }
    try testing.expectEqual(resolved.resolution.bindingCount(), prefix.seed.binding_owners.len);
    try testing.expectEqual(resolved.expanded.ast.exprCount(), prefix.seed.expression_owners.len);
    var continued = try typecheckWithPrefix(testing.allocator, &resolved.expanded, &resolved.resolution, &sink, &prefix, .{ .source = relocation_mod.Mark.of(&program.ast), .destination = relocation_mod.Mark.of(&program.ast) }, false);
    defer continued.deinit();
    try testing.expectEqual(@as(u32, 0), sink.error_count);
    try testing.expectEqualSlices(TypeId, prefix.typing.expr_types, continued.typing.expr_types);
    try testing.expectEqual(prefix.typing.pool.len, continued.typing.pool.len);
}

test "parameter heads bind receiver and trait key parameters" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const sink = try diagnose(arena.allocator(),
        \\trait Build[T] { fn build(sink value: T) -> Self where carries(value) }
        \\trait Deliver[T] { fn deliver(sink self: Self) -> T where carries(self) }
        \\impl[T, U: Build[T]] Deliver[U] for T {
        \\    fn deliver(sink self: T) -> U where carries(self) { Build.build(self) }
        \\}
        \\struct Box[T] { value: T }
        \\impl[T] Build[T] for Box[T] {
        \\    fn build(sink value: T) -> Box[T] where carries(value) { .{ value = value } }
        \\}
        \\fn forward[T, U: Build[T]](sink value: T) -> U where carries(value) { value.deliver() }
        \\fn main() -> UInt8 { let result: Box[UInt8] = forward(UInt8(7)); result.value }
    );
    if (sink.hasErrors()) for (sink.items()) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.message });
    try testing.expectEqual(@as(u32, 0), sink.error_count);
}

test "parameter heads refuse overlap across receiver constructors their bounds could answer" {
    const cases = [_][]const u8{
        \\trait Route[T] {}
        \\impl[T, U] Route[U] for T {}
        \\struct Packet {}
        \\impl Route[Bool] for Packet {}
        \\fn main() -> UInt8 { 0 }
        ,
        \\trait Allowed {}
        \\trait Route[T] {}
        \\impl[T: Allowed, U] Route[U] for T {}
        \\struct Packet[T] { value: T }
        \\impl[T] Allowed for Packet[T] {}
        \\impl[T] Route[Bool] for Packet[T] {}
        \\fn main() -> UInt8 { 0 }
        ,
        \\trait Route[T] {}
        \\impl[T, U] Route[U] for T {}
        \\impl[T] Route[Bool] for T {}
        \\fn main() -> UInt8 { 0 }
        ,
        \\trait Route[T] {}
        \\impl[T, U] Route[U] for T {}
        \\impl Route[Bool] for UInt8 {}
        \\fn main() -> UInt8 { 0 }
        ,
    };
    for (cases) |source| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const sink = try diagnose(arena.allocator(), source);
        try testing.expect(diagnosticSays(&sink, .t_impl, "both answer"));
    }
}

