test "default implementations select concrete and nominal generic query types" {
    var arena = std.heap.ArenaAllocator.init(testing.allocator);
    defer arena.deinit();
    const sink = try diagnose(arena.allocator(),
        \\trait Queryable { type Query; fn accepts(value: Self, query: Self.Query) -> Bool }
        \\default impl[T] Queryable for T {
        \\    type Query = T
        \\    fn accepts(_value: T, _query: T) -> Bool { true }
        \\}
        \\struct Box[T] { value: T }
        \\impl Queryable for Bool {
        \\    type Query = UInt8
        \\    fn accepts(value: Bool, query: UInt8) -> Bool { value && query == 7 }
        \\}
        \\fn same[T](value: Box[T]) -> Bool { Queryable.accepts(value, value) }
        \\fn ask[T: Queryable](value: T, query: T.Query) -> Bool { Queryable.accepts(value, query) }
        \\fn main() -> UInt8 {
        \\    let value: Box[UInt16] = .{ value = 3 }
        \\    if same(value) && ask(true, 7) && Queryable.accepts(UInt64(5), 5) { 0 } else { 1 }
        \\}
    );
    if (sink.hasErrors()) for (sink.items()) |diagnostic| std.debug.print("{s}: {s}\n", .{ @tagName(diagnostic.code.?), diagnostic.message });
    try testing.expectEqual(@as(u32, 0), sink.error_count);
}

