        \\trait Permitted {}
        \\struct Box[T] { value: T }
        \\impl[T: Permitted] Selected for Box[T] { fn selected(_value: Box[T]) -> UInt8 { 2 } }
        \\fn main() -> UInt8 {
        \\    let value: Box[Bool] = .{ value = false }
        \\    Selected.selected(value)
        \\}
