}

test "float math private primitives require their complete trusted signatures" {
    const cases = [_]struct {
        module: []const u8 = "scalar",
        library: bool = true,
        declaration: []const u8,
        call: []const u8 = "linea_math_sqrt(4.0)",
        expected: ?Code = .t_extern,
    }{
        .{ .declaration = "extern fn linea_math_sqrt(value: Float64) -> Float64", .expected = null },
        .{ .declaration = "extern fn linea_math_pow(value: Float64, exponent: Float64) -> Float64", .call = "linea_math_pow(2.0, 3.0)", .expected = null },
        .{ .module = "other", .declaration = "extern fn linea_math_sqrt(value: Float64) -> Float64" },
        .{ .module = "other", .declaration = "extern fn linea_math_sqrt(value: UInt64) -> UInt64", .call = "linea_math_sqrt(4)" },
        .{ .library = false, .declaration = "extern fn linea_math_sqrt(value: Float64) -> Float64", .expected = .m_extern },
        .{ .declaration = "pub extern fn linea_math_sqrt(value: Float64) -> Float64" },
        .{ .declaration = "extern fn linea_math_sqrt(sink value: Float64) -> Float64" },
        .{ .declaration = "extern fn linea_math_sqrt(inout value: Float64) -> Float64" },
        // A parameter's name is a label, so a renamed one is still the primitive.
        .{ .declaration = "extern fn linea_math_sqrt(number: Float64) -> Float64", .expected = null },
        .{ .declaration = "extern fn linea_math_sqrt(value: UInt64) -> Float64", .call = "linea_math_sqrt(4)" },
        .{ .declaration = "extern fn linea_math_sqrt(value: Float64) -> UInt64" },
        .{ .declaration = "extern fn linea_math_sqrt(value: UInt64) -> UInt64", .call = "linea_math_sqrt(4)" },
        .{ .declaration = "extern fn linea_math_sqrt() -> Float64", .call = "linea_math_sqrt()" },
        .{ .declaration = "extern fn linea_math_sqrt(value: Float64, extra: Float64) -> Float64", .call = "linea_math_sqrt(4.0, 0.0)" },
        .{ .declaration = "extern fn linea_math_pow(value: Float64) -> Float64", .call = "linea_math_pow(4.0)" },
        .{ .declaration = "extern fn linea_math_sqrt[phantom T](value: Float64) -> Float64", .call = "linea_math_sqrt[UInt8](4.0)" },
        .{ .declaration = "extern fn linea_math_sqrt(value: Float64 = 4.0) -> Float64" },
        .{ .declaration = "extern fn linea_math_sqrt(value: Float64) -> Float64 where carries(value)" },
        .{ .declaration = "fn linea_math_sqrt(value: Float64) -> Float64 { value }", .expected = null },
        .{ .library = false, .declaration = "fn linea_math_sqrt(value: Float64) -> Float64 { value }", .expected = null },
    };
    for (cases) |case| {
        var arena = std.heap.ArenaAllocator.init(testing.allocator);
        defer arena.deinit();
        const gpa = arena.allocator();
        var sink = Sink.init(gpa);
        const text = try std.fmt.allocPrint(gpa, "{s}\nfn main() -> UInt8 {{ let _answer = {s}; 0 }}", .{ case.declaration, case.call });
        const source: Source = .{ .path = "float.lin", .text = text };
        var interner: Interner = .empty;
        const tokens = try tokenize(gpa, &source, .from(0), &sink, &interner);
        var ast = try parse(gpa, &source, .from(0), tokens, &sink);
        var resolved = try resolveTree(gpa, &ast, &sink);
        resolved.modules[0].name = case.module;
        resolved.modules[0].library = case.library;
        resolved.modules[0].externs = case.library;
        _ = try typecheckTree(gpa, &resolved, &sink);
        if (case.expected) |expected| {
            var found = false;
            for (sink.list.items) |diagnostic| if (diagnostic.code == expected) {
                found = true;
            };
            if (!found) std.debug.print("missing {s} for {s}\n", .{ @tagName(expected), case.declaration });
            try testing.expect(found);
        } else {
            if (sink.hasErrors()) for (sink.list.items) |diagnostic| std.debug.print("{s}: {s}\n", .{ case.declaration, diagnostic.message });
            try testing.expect(!sink.hasErrors());
        }
    }
}

/// How a runtime signature's scalar is written in Linea.
fn runtimeScalarName(scalar: runtime_symbols.Scalar) []const u8 {
    return switch (scalar) {
        .u8 => "UInt8",
        .i32 => "Int32",
        .i64 => "Int64",
        .u64 => "UInt64",
        .f64 => "Float64",
        .unit => "()",
        .ptr => unreachable,
    };
}

test "a runtime scalar is spelled as the Linea type written for it" {
    try testing.expectEqualStrings("UInt64", runtimeScalarName(.u64));
    try testing.expectEqualStrings("()", runtimeScalarName(.unit));
}
